export const CARD_TEXT_ES: Readonly<Record<string, { readonly n?: string; readonly t?: string; readonly f?: string }>> = {
  "01001a": {"n":"Spiderman","t":"Sentido arácnido — Interrupción: cuando el Villano inicie un ataque contra ti, roba 1 carta.","f":"\"¡Sólo soy vuestro amistoso vecino Spiderman!\""},
  "01001b": {"t":"Científico — Recurso: Genera un recurso [mental]. (Límite de una vez por ronda.)","f":"\"Ahora mismo cambiaría todo el rollo de Spiderman por una mecedora y un buen libro.\""},
  "01002": {"n":"Gata Negra","t":"Respuesta obligada: después de que juegues a la Gata Negra, descarta las 2 primeras cartas de tu mazo. Añade a tu mano todas las cartas con un recurso [mental] impreso que hayas descartado de este modo.","f":"\"No soy una heroina, sino una ladrona.\""},
  "01003": {"n":"Voltereta hacia atrás","t":"Interrupción (defensa): cuando vayas a sufrir cualquier cantidad de Daño provocado por un ataque, evita todo ese Daño.","f":"\"¿Has estado entrenándote? Porque con ésa casi me alcanzas.\" —Spiderman"},
  "01004": {"n":"Sentido arácnido mejorado","t":"Interrupción de Héroe: cuando se muestre una carta de Perfidia del mazo de Encuentros, anula su efecto de \"Cuando se muestre esta carta\".","f":"\"¡Mi sentido arácnido está zumbando!\" —Spiderman"},
  "01005": {"n":"Balanceo con patada","t":"Acción de Héroe (ataque): inflige 8 de Daño a un enemigo.","f":"\"¡Cuidado que voy!\" —Spiderman"},
  "01006": {"n":"Tía May","t":"Acción de Alter ego: agota a la Tía May → cura 4 de Daño a Peter Parker.","f":"\"¡Cielo santo, Peter! Últimamente no das pie con bola.\""},
  "01007": {"n":"Rastreador arácnido","t":"Vincula esta carta a un Esbirro.\nInterrupción obligada: cuando el Esbirro vinculado sea derrotado, quita 3 de Amenaza de un Plan."},
  "01008": {"n":"Lanzarredes","t":"Usos (3 contadores de Telaraña). (Entra en juego con 3 contadores. Cuando se acaben, descarta esta carta.)\nRecurso de Héroe: agota los Lanzarredes y quítales 1 contador de Telaraña → genera un recurso [wild]."},
  "01009": {"n":"Envuelto en telaraña","t":"Sólo identidad de Héroe. Vincula esta carta a un enemigo. Máximo de 1 por enemigo.\nInterrupción obligada: cuando el enemigo vinculado vaya a atacar, en vez de eso descarta Envuelto en telaraña. Luego aturde a ese enemigo."},
  "01010a": {"n":"Capitana Marvel","t":"Redirigir energía — Acción: gasta un recurso [energy] y cura 1 de Daño a la Capitana Marvel → roba 1 carta. (Límite de una vez por ronda.)","f":"\"Yo nunca me rindo.\""},
  "01010b": {"t":"Comandante — Acción: un jugador de tu elección roba 1 carta. (Límite de una vez por ronda.)","f":"\"Mi trabajo consiste en proteger la Tierra y a todos los que viven en ella.\""},
  "01011": {"n":"Spiderwoman","t":"Respuesta: después de que Spiderwoman entre en juego, confunde al Villano.","f":"\"Esto quería yo. Ayudar a los inocentes y hospitalizar a los culpables.\""},
  "01012": {"n":"Evitar una crisis","t":"Acción de Héroe (intervención): quita 2 de Amenaza de un Plan. Luego, si tienes el rasgo AÉREO, quita 2 de Amenaza de otro Plan distinto.","f":"\"Pocos desastres he visto más impresionantes que éste.\" —Carol Danvers"},
  "01013": {"n":"Rayo fotónico","t":"Acción de Héroe (ataque): inflige 5 de Daño a un enemigo. Si has pagado el coste de esta carta usando un recurso [energy], roba 1 carta."},
  "01014": {"n":"Absorción de energía","f":"\"¡Se acabó!\" —Capitana Marvel"},
  "01015": {"n":"Base orbital de Alpha Flight","t":"Acción: agota la Base orbital de Alpha Flight, elige 1 carta de tu mano y descártala → roba 1 carta (roba 2 cartas si eres Carol Danvers).","f":"Esta estación espacial, situada en la órbita baja del planeta, puede trasladar cargamentos desde y hacia el Triskelion."},
  "01016": {"n":"Casco de la Capitana Marvel","t":"La Capitana Marvel recibe +1 DEF (+2 DEF si tienes el rasgo AÉREO).","f":"\"¡Esto es una pasada!\" —Jessica Drew"},
  "01017": {"n":"Vuelo cósmico","t":"La Capitana Marvel gana el rasgo AÉREO.\nInterrupción de Héroe (defensa): cuando la Capitana Marvel vaya a sufrir Daño, descarta Vuelo cósmico → evita 3 de ese Daño."},
  "01018": {"n":"Canalizar energía","t":"Máximo de 1 por jugador.\nAcción: gasta X recursos [energy] → coloca X contadores de Energía sobre esta carta.\nAcción de Héroe (ataque): descarta Canalizar energía → inflige 2 de Daño a un enemigo por cada contador de Energía que haya sobre esta carta (hasta un Daño máximo de 10)."},
  "01019a": {"n":"Hulka","t":"\"¡Deberías hacer pesas!\" — Respuesta: después de que cambies a esta identidad, inflige 2 de Daño a un enemigo.","f":"\"¡Mido 2,13 y soy de color verde! ¡Se me van a quedar mirando lleve lo que lleve!.\""},
  "01019b": {"t":"\"¡Protesto!\" — Interrupción: cuando vaya a colocarse Amenaza sobre un Plan, evita 1 de esa Amenaza. (Límite de una vez por ronda.)","f":"\"Puedo convertirme en Hulka siempre que quiera. Pero el hecho de que puedas hacer algo no significa que debas hacerlo."},
  "01020": {"n":"Gata Infernal","t":"Acción: devuelve a Gata Infernal a tu mano.","f":"\"Vuélvanse, caballeros, y conozcan a... ¡Gata Infernal!\""},
  "01021": {"n":"Apisonadora gamma","t":"Acción de Héroe (ataque): inflige X de Daño a un enemigo (hasta un máximo de 15). X es la cantidad de Daño que tengas acumulado.","f":"\"¡Te has metido con la mujer equivocada!\" —Hulka"},
  "01022": {"n":"Pisotón","t":"Acción de Héroe: inflige 1 de Daño a cada enemigo.","f":"\"Estas botas están hechas para pisar fuerte.\" —Hulka"},
  "01023": {"n":"Proceso judicial","t":"Acción de Alter ego (intervención): elige y descarta hasta 5 cartas de tu mano → quita 1 de Amenaza de un Plan por cada carta que hayas descartado de este modo.","f":"\"Es la primera vez que veo a alguien ganar una pelea con argumentos.\" —Spiderman"},
  "01024": {"n":"Sucesión de puñetazos","t":"Respuesta: después de que realices un ataque básico (usando tu ATQ), prepara a Hulka.","f":"\"No me gustan los tipos bocazas.\" —Jennifer Walters"},
  "01025": {"n":"Doble personalidad","t":"Acción: cambia de identidad (dale la vuelta a tu carta de Superhéroe). Luego roba cartas hasta alcanzar el valor impreso del tamaño de tu mano..","f":"\"Sé un par de cosas sobre la furia. Y esa clase de furia... no se aplaca sin llevarse a alguien por delante.\" —Jennifer Walters"},
  "01026": {"n":"División de Derecho Superhumano","t":"Acción de Alter ego (intervención): agota la División de Derecho Superhumano y gasta un recurso [mental] → quita 2 de Amenaza de un Plan.","f":"\"Ya te pasaré la factura. Mi tiempo se cotiza muy alto hoy en día.\" —Jennifer Walters"},
  "01027": {"n":"Furia concentrada","t":"Acción de Héroe: agota la Furia concentrada y sufre 1 de Daño → roba una carta."},
  "01028": {"n":"Fuerza sobrehumana","t":"Hulka recibe +2 ATK.\nRespuesta obligada: después de que Hulka ataque, descarta la Fuerza sobrehumana → aturde al enemigo atacado."},
  "01029a": {"t":"Recibes +1 al tamaño de tu mano por cada Mejora TECNOLOGÍA que controles (hasta un tamaño máximo de 7).","f":"\"Soy Iron Man.\""},
  "01029b": {"t":"Visión de futuro — Acción: mira las 3 primeras cartas de tu mazo. Añade 1 a tu mano y descarta las demás. (Límite de una vez por ronda.)","f":"\"Es evidente que no hago esto por el dinero...\""},
  "01030": {"n":"Máquina de Guerra","t":"Acción: agota a Máquina de Guerra e inflígele 2 de Daño → inflige 1 de Daño a cada enemigo.","f":"\"¿Esto es una guerra privada o puede participar cualquiera?\""},
  "01031": {"n":"Rayo repulsor","t":"Acción de Héroe (ataque): inflige 1 de Daño a un enemigo y descarta las 5 primeras cartas de tu mazo. Por cada recurso [energy] impreso que hayas descartado de este modo, infliges 2 de Daño adicional a ese enemigo."},
  "01032": {"n":"Puñetazo supersónico","t":"Acción de Héroe (ataque): inflige 4 de Daño a un enemigo (8 de Daño si tienes el rasgo AÉREO).","f":"\"Buena técnica. Pero si lo haces así... duele más.\" —Tony Stark"},
  "01033": {"t":"Recurso: agota a Pepper Potts → genera los recursos de la carta que esté en la parte superior de tu pila de descartes.","f":"\"Haz lo tuyo. Yo me ocupo de esto.\""},
  "01034": {"n":"Torre Stark","t":"Acción de Alter ego: agota la Torre Stark → elige un jugador. Ese jugador devuelve a su mano la primera Mejora TECNOLOGÍA que haya en la parte superior de su pila de descartes.","f":"\"Esperaba algo un poco más grande. Pero esto servirá.\" —Tony Stark"},
  "01035": {"n":"Reactor ARK","t":"Acción de Héroe: agota el Reactor ARK → prepara a Iron Man.","f":"\"Cuando me puse esta armadura, adopté más poderes de los que ningún humano debía tener... y tal vez más responsabilidad de la que mi corazón puede soportar.\" —Tony Stark"},
  "01036": {"n":"Armadura Mark V","t":"Recibes +6 de Vida.","f":"\"¿Eso es todo lo que tienes?\" —Tony Stark"},
  "01037": {"n":"Casco Mark V","t":"Acción de Héroe (intervención): agota el Casco Mark V → quita 1 de Amenaza de un Plan (de todos los planes si tienes el rasgo AÉREO).","f":"\"¿Seguro que quieres hacer eso, Tony?\" —P.E.P.P.E.R."},
  "01038": {"n":"Guanteletes potenciados","t":"Acción de Héroe (ataque): agota los Guanteletes potenciados → inflige 1 de Daño a un enemigo (2 de Daño si tienes el rasgo AÉREO).","f":"\"Espera, que te echo una mano.\" —Tony Stark"},
  "01039": {"n":"Botas propulsoras","t":"Recibes +1 de Vida.\nAcción de Héroe: agota las Botas propulsoras y gasta un recurso [mental] → ganas el rasgo AÉREO hasta el final de la fase."},
  "01040a": {"n":"Pantera Negra","t":"Represalia 1. (Después de que se ataque a este personaje, se inflige 1 de Daño al personaje atacante.)","f":"\"Atacarme a mí es atacar a Wakanda.\""},
  "01040b": {"t":"Previsión — Preparación: busca en tu mazo una Mejora PANTERA NEGRA y añádela a tu mano. Baraja tu mazo."},
  "01041": {"t":"Respuesta: después de que Shuri entre en juego, busca una Mejora en tu mazo y añádela a tu mano. Baraja tu mazo.","f":"\"¡Sin mí estarías perdido, hermanito!!\""},
  "01042": {"n":"Sabiduría ancestral","t":"Acción de Alter ego: elige hasta 3 cartas distintas de tu pila de descartes, añádelas a tu mazo y barájalo.","f":"\"En Wakanda, la sabiduría de nuestros antepasados nos otorga fuerza.\" —T'Challa"},
  "01043a": {"n":"¡Wakanda por siempre!","t":"Acción de Héroe: resuelve la capacidad \"Especial\" de todas las Mejoras PANTERA NEGRA que controles (en el orden que prefieras). (Resolver cada capacidad es un paso dentro de esta secuencia.)"},
  "01043b": {"n":"¡Wakanda por siempre!","t":"Acción de Héroe: resuelve la capacidad \"Especial\" de todas las Mejoras PANTERA NEGRA que controles (en el orden que prefieras). (Resolver cada capacidad es un paso dentro de esta secuencia.)"},
  "01043c": {"n":"¡Wakanda por siempre!","t":"Acción de Héroe: resuelve la capacidad \"Especial\" de todas las Mejoras PANTERA NEGRA que controles (en el orden que prefieras). (Resolver cada capacidad es un paso dentro de esta secuencia.)"},
  "01043d": {"n":"¡Wakanda por siempre!","t":"Acción de Héroe: resuelve la capacidad \"Especial\" de todas las Mejoras PANTERA NEGRA que controles (en el orden que prefieras). (Resolver cada capacidad es un paso dentro de esta secuencia.)"},
  "01044": {"n":"Vibránium","f":"\"Desde el reinado de Bashenga, hemos controlado nuestro destino como pocas naciones pueden.\""},
  "01045": {"n":"La Ciudad Dorada","t":"Acción de Alter ego: agota La Ciudad Dorada → roba 2 cartas.","f":"La capital de Wakanda es una maravilla arquitectónica y tecnología sin parangón."},
  "01046": {"n":"Dagas de energía","t":"Especial: elige un jugador. Inflige 1 de Daño al Villano y a cada enemigo que esté enfrentado a ese jugador (2 de Daño si éste es el último paso de esta secuencia).\n(Juega el Evento \"¡Wakanda por siempre!\" para usar esta capacidad.)"},
  "01047": {"n":"Garras de pantera","t":"Especial (ataque): inflige 2 de Daño a un enemigo (4 de Daño si éste es el último paso de esta secuencia).\n(Juega el Evento \"¡Wakanda por siempre!\" para usar esta capacidad.)"},
  "01048": {"n":"Ingenio táctico","t":"Especial (intervención): quita 1 de Amenaza de un Plan (2 de Amenaza si éste es el último paso de esta secuencia).\n(Juega el Evento \"¡Wakanda por siempre!\" para usar esta capacidad.)"},
  "01049": {"n":"Traje de vibránium","t":"Especial (ataque): traslada 1 de Daño desde tu Héroe hasta un enemigo (2 de Daño si éste es el último paso de esta secuencia).\n(Juega el Evento \"¡Wakanda por siempre!\" para usar esta capacidad.)"},
  "01050": {"t":"Respuesta obligada: después de que Hulk ataque, descarta la primera carta de tu mazo. Si el recurso impreso de esa carta tiene:\n[physical] - Inflige 2 de Daño a un enemigo.\n[energy] - Inflige 1 de Daño a cada personaje.\n[mental] - Descarta a Hulk.\n[wild] - Todo lo anterior."},
  "01051": {"t":"Respuesta: después de que Tigra ataque y derrote a un Esbirro, se cura 1 de Daño.","f":"\"Lo siento, nada de autógrafos.\""},
  "01052": {"n":"A por ellos","t":"Respuesta (intervención): después de que tu Héroe ataque y derrote a un enemigo, quita 2 de Amenaza de un Plan.","f":"\"Kamala, no tenemos banda sonora propia. Deja ya de tatarear...\" —Capitana Marvel"},
  "01053": {"n":"Asalto implacable","t":"Acción de Héroe (ataque): inflige 5 de Daño a un Esbirro. Si has pagado el coste de esta carta usando un recurso [physical], este ataque gana Brutalidad. (El Daño sobrante de este ataque se inflige al Villano.)"},
  "01054": {"n":"Gancho","t":"Acción de Héroe (ataque): inflige 5 de Daño a un enemigo.","f":"¡PAF!"},
  "01055": {"n":"El poder de la agresividad","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta de Agresividad (roja)."},
  "01056": {"n":"Unidad táctica","t":"Usos (3 contadores de Ataque). (Entra en juego con 3 contadores. Cuando se acaben, descarta esta carta)\nAcción: agota la Unidad táctica y quítale 1 contador de Ataque → inflige 2 de Daño a un enemigo."},
  "01057": {"n":"Entrenamiento de combate","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nTu Héroe recibe +1 ATQ.","f":"\"¡Tony! ¡Lo ha vuelto a hacer!\" —Janet Van Dyne"},
  "01058": {"t":"Respuesta: después de que Daredevil intervenga, inflige 1 de Daño a un enemigo.","f":"\"A veces creo que consigo más con los puños que con el bufete.\""},
  "01059": {"t":"Jessica Jones recibe +1 INT por cada Plan secundario que haya en juego.","f":"\"Se me da muy bien encontrar a gente.\""},
  "01060": {"n":"¡Por la justicia!","t":"Acción de Héroe (intervención): quita 3 de Amenaza de un Plan (4 de Amenaza si has pagado el coste de esta carta usando un recurso [mental]).","f":"\"Has perdido. Y vas a responder por tus actos.\" —Capitán América"},
  "01061": {"n":"Una gran responsabilidad","t":"Interrupción de Héroe: cuando vaya a colocarse cualquier cantidad de Amenaza sobre un Plan, en vez de eso tú sufres esa misma cantidad de Daño."},
  "01062": {"n":"El poder de la justicia","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta de Justicia (amarilla)."},
  "01063": {"n":"Sala de interrogatorios","t":"Máximo de 1 por jugador.\nRespuesta: después de que derrotes a un Esbirro, agota la Sala de interrogatorios → quita 1 de Amenaza de un Plan.","f":"\"¡Ah, que lo sientes! Pues nada, ahora mismo te quito las esposas y te pido un taxi\" —Misty Knight"},
  "01064": {"n":"Equipo de vigilancia","t":"Usos (3 contadores de Escucha). (Entra en juego con 3 contadores. Cuando se acaben, descarta esta carta)\nAcción: agota el Equipo de vigilancia y quítale 1 contador de Escucha → quita 1 de Amenaza de un Plan."},
  "01065": {"n":"Intuición heroica","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nTu Héroe recibe +1 INT."},
  "01066": {"n":"Ojo de Halcón","t":"Ojo de Halcón entra en juego con 4 contadores de Flechas.\nRespuesta: después de que entre en juego un Esbirro, quítale 1 contador de Flechas a Ojo de Halcón → inflige 2 de Daño a ese Esbirro."},
  "01067": {"n":"María Hill","t":"Respuesta: después de que María Hill entre en juego, cada jugador roba 1 carta.","f":"\"Lo creas o no, todos queremos lo mismo.\""},
  "01068": {"n":"La Visión","t":"Acción: gasta un recurso [energy] → elige entre INT o ATQ. Hasta el final de la fase, La Visión recibe un +2 para el atributo elegido. (Límite de una vez por ronda.)","f":"\"Yo me encargaré de esto.\""},
  "01069": {"n":"Preparación","t":"Acción: prepara un Aliado.","f":"\"Nos entrenamos sin descanso todos los días para estar preparados cuando llegue el momento.\" —Steve Rogers"},
  "01070": {"n":"Liderar en vanguardia","t":"Acción de Héroe: elige un jugador. Cada personaje controlado por ese jugador recibe +1 INT y +1 ATQ hasta el final de la fase.","f":"\"¡Seguidme todos!\" —Carol Danvers"},
  "01071": {"n":"Hacer la llamada","t":"Acción: paga el coste impreso de un Aliado que esté en la pila de descartes de cualquier jugador → pon en juego ese Aliado controlado por ti.","f":"\"¡Código rojo! ¡Todo el mundo a sus puestos!\" —María Hill"},
  "01072": {"n":"El poder del liderazgo","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta de Liderazgo (azul)."},
  "01073": {"n":"El Triskelion","t":"Tu límite de Aliados se incrementa en 1. (Esto te permite controlar más de 3 Aliados.)","f":"\"¿Crees que lo han construido lo bastante alto?\" —Hulka"},
  "01074": {"n":"Inspiración","t":"Vincula esta carta a un Aliado. Máximo de 1 por Aliado.\nEl Aliado vinculado recibe +1 INT y +1 ATQ.","f":"\"Menos mal que está de nuestra parte.\" —Starlord"},
  "01075": {"n":"Viuda Negra","t":"Interrupción: cuando se muestre una carta del mazo de Encuentros, agota a la Viuda Negra y gasta un recurso [mental] → anula los efectos de esa carta y descártala. Luego muestra otra carta del mazo de Encuentros."},
  "01076": {"t":"Dureza. (Este personaje entra en juego con una carta de Estado \"Duro\".)","f":"\"Power Man de alquiler. Cage al habla."},
  "01077": {"n":"Contragolpe","t":"Respuesta (ataque): después de que tu Héroe defienda contra un ataque enemigo, inflige tanto Daño a ese enemigo como el ATQ de tu Héroe.","f":"\"¡Te lo tienes bien merecido!\" —Puño de Hierro"},
  "01078": {"n":"¡Poneos detrás de mí!","t":"Interrupción de Héroe: cuando se muestre una carta de Perfidia del mazo de Encuentros, anula su efecto de \"Cuando se muestre esta carta\". En vez de eso, el Villano te ataca a ti.","f":"\"¡Ejem! ¡A un lado, ciudadanos!\" —Ms. Marvel"},
  "01079": {"n":"El poder de la protección","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta de Protección (verde)."},
  "01080": {"n":"Equipo médico","t":"Usos (3 contadores de Medicina). (Entra en juego con 3 contadores. Cuando se acaben, descarta esta carta.)\nAcción: agota al Equipo médico y quítale 1 contador de Medicina → cura 2 de Daño a un personaje amigo."},
  "01081": {"n":"Chaleco blindado","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nTu Héroe recibe +1 DEF.","f":"Te salva la vida con estilo."},
  "01082": {"n":"Indómito","t":"Respuesta: después de que tu Héroe defienda, descarta Indómito → prepara a tu Héroe.","f":"\"No tenemos elección. Lucharemos... y venceremos. No hay otra opción.\" —Capitán América"},
  "01083": {"n":"Pájaro Burlón","t":"Respuesta: después de que Pájaro Burlón entre en juego, aturde a un enemigo.","f":"\"¡¿Llamas a eso 'ciencia'?!\""},
  "01084": {"n":"Nick Furia","t":"Respuesta obligada: después de que Nick Furia entre en juego, elige una de estas opciones: quita 2 de Amenaza de un Plan, roba 3 cartas o inflige 4 de Daño a un enemigo. Al final de la ronda, si Nick Furia aún sigue en juego, descártalo."},
  "01085": {"n":"Emergencia","t":"Interrupción (intervención): cuando el Villano ejecute el Plan, reduce en 1 la cantidad de Amenaza que se coloque sobre el Plan.","f":"\"¡A TODAS LAS UNIDADES! ¡LLAMANDO A TODAS LAS UNIDADES!\""},
  "01086": {"n":"Primeros auxilios","t":"Acción: cura 2 de Daño a cualquier personaje.","f":"\"¿Sigue llamándose 'primeros auxilios' si es ya el segundo día que me paso en el hospital?\" —Clint Barton"},
  "01087": {"n":"Puñetazo demoledor","t":"Acción de Héroe (ataque): inflige 3 de Daño a un enemigo.","f":"¡ZAS!"},
  "01088": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "01089": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "01090": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "01091": {"n":"Mansión de los Vengadores","t":"Máximo de 1 por jugador.\nAcción: agota la Mansión de los Vengadores → elige un jugador. Ese jugador roba 1 carta.","f":"\"¿Te has acordado de cerrar con llave?\" —Janet Van Dyne"},
  "01092": {"n":"Helitransporte","t":"Máximo de 1 por jugador.\nAcción: agota el Helitransporte → elige un jugador. Reduce en 1 el coste en recursos de la siguiente carta jugada por ese jugador en esta fase.","f":"\"¿Un portaaviones volador? Estás de guasa, ¿no?\" —Jennifer Walters"},
  "01093": {"n":"Tenacidad","t":"Acción de Héroe: gasta un recurso [physical] y descarta esta carta → prepara tu Héroe."},
  "01094": {"n":"Rino","f":"\"Soy el Rino. Tiro cosas abajo. A eso me dedico. Eso es quien soy.\""},
  "01095": {"n":"Rino","t":"Cuando se muestre esta carta: busca el Plan secundario \"Arramblar con todo\" en el mazo de Encuentros y en su pila de descartes y muéstralo. Baraja el mazo de Encuentros.","f":"\"¡Fuera de mi camino!\""},
  "01096": {"n":"Rino","t":"Dureza.\nCuando se muestre esta carta: aturde a todos los Héroes.","f":"\"¡Tú te lo has buscado!\""},
  "01097a": {"n":"¡Allanamiento!","t":"Contenido: Rino (I) y Rino (II). (Rino (II) y Rino (III) para jugar en modo Experto.) Conjuntos de Encuentro normales y del Rino. Un conjunto de Encuentros modular (recomendado: Amenaza de bomba).\nPreparación: Avanza a la etapa 1B.","f":"¡El Rino está atacando unas instalaciones de S.H.I.E.L.D.!"},
  "01097b": {"n":"¡Allanamiento!","t":"Si se completa esta etapa, los jugadores pierden la partida.","f":"El Rino pretende derribar los muros del complejo y robar un cargamento de vibránium. ¡Tenéis que detenerlo!"},
  "01098": {"n":"Piel blindada del Rino","t":"Vincula esta carta al Rino.\nInterrupción obligada: cuando vaya a infligirse cualquier cantidad de Daño al Rino, en vez de eso coloca ese Daño sobre esta carta. Luego, si hay al menos 5 de Daño sobre esta carta, descarta la Piel blindada del Rino."},
  "01099": {"n":"Embestida","t":"Vincula esta carta al Rino.\n[star] Interrupción obligada: cuando el Rino ataca, su ataque gana Brutalidad. Al final de este ataque, descarta la Embestida."},
  "01100": {"n":"Cuerno de marfil mejorado","t":"Vincula esta carta al Rino.\nAcción de Héroe: gasta recursos [physical] [physical] [physical] → descarta esta carta."},
  "01101": {"n":"Mercenario de Hydra","t":"Guardia.","f":"\"¿Qué hace Hydra aquí?\" —Carol Danvers"},
  "01102": {"n":"Hombre de Arena","t":"Dureza.","f":"\"¡Yo sólo quiero cobrar!\""},
  "01103": {"n":"Conmocionador","t":"Cuando se muestre esta carta: inflige 1 de Daño a cada Héroe.","f":"\"Seguro que verme aquí te supone toda una conmoción para ti.\""},
  "01104": {"n":"Difícil de tumbar","t":"Cuando se muestre esta carta: el Rino se cura 4 de Daño. Si no se cura Daño de este modo, esta carta gana Oleada.","f":"\"¿Crees que puedes detenerme? ¡Menudo chiste!\" —Rhino"},
  "01105": {"n":"\"¡Soy duro!\"","t":"Cuando se muestre esta carta: dale al Rino una carta de Estado \"Duro\". Si el Rino ya tiene una carta de Estado \"Duro\", esta carta gana Oleada.","f":"\"¡Ven a por mí!\" —Rino"},
  "01106": {"n":"Estampida","t":"Cuando se muestre esta carta (Alter ego): esta carta gana Oleada.\nCuando se muestre esta carta (Héroe): el Rino te ataca. Si un personaje sufre Daño por este ataque, ese personaje queda aturdido."},
  "01107": {"n":"Arramblar con todo","t":"Cuando se muestre esta carta: coloca 1 [per_hero] de Amenaza adicional sobre esta carta.","f":"El Rino está arrramblando con todo lo que pilla."},
  "01108": {"n":"Control de multitudes","f":"Este sitio está abarrotado de civiles asustados. Si os enfrentáis al Rino entre tanta gente, correrán un grave peligro. ¡Tenéis que ponerlos a salvo!"},
  "01109": {"n":"Amenaza de bomba","t":"Cuando se muestre esta carta: coloca 1 [per_hero] de Amenaza adicional sobre esta carta.","f":"Os han informado de que unos agentes de Hydra han colocado un artefacto explosivo en un hotel cercano."},
  "01110": {"n":"Terrorista de Hydra","t":"Cuando se muestre esta carta: elige entre sufrir 2 de Daño o colocar 1 de Amenaza sobre el Plan principal","f":"\"Sé que si cortas una cabeza, otras dos ocupan su lugar. Pero ¿y si explota?\" —Hulka"},
  "01111": {"n":"Explosión","t":"Cuando se muestre esta carta: si está en juego la Amenaza de bomba, reparte X de Daño entre Héroes y Aliados, siendo X la cantidad de Amenaza que haya sobre la Amenaza de bomba. Si la Amenaza de bomba no está en juego, esta carta gana Oleada."},
  "01112": {"n":"Falsa alarma","t":"Cuando se muestre esta carta: quedas confundido. Si ya estabas confundido, esta carta gana Oleada.","f":"\"¡Aquí no hay nada que ver!\" —Iron Man"},
  "01113": {"t":"[star] Interrupción obligada: cuando Klaw ataque, dale 1 carta de aumento adicional para esta activación.","f":"\"¡Enfréntate a la muerte!\""},
  "01114": {"t":"Cuando se muestre esta carta: busca la carta Klaw \"el inmortal\" en el mazo de Encuentros y en su pila de descartes y muéstrala. Baraja el mazo de Encuentros.\n[star] Interrupción obligada: cuando Klaw ataque, dale 1 carta de aumento adicional para esta activación."},
  "01115": {"t":"Dureza\n[star] Interrupción obligada: cuando Klaw ataque, dale 1 carta de aumento adicional para esta activación."},
  "01116a": {"n":"Distribución clandestina","t":"Contenido: Klaw (I) y Klaw (II). (Klaw (II) y Klaw (III) para jugar en modo Experto). Conjuntos de Encuentros normales y de Klaw. Un conjunto de Encuentros modular (recomendado: Señores del Mal).\nPreparación: busca en el mazo de Encuentros el Plan secundario \"Red de defensa\" y muéstralo. Baraja el mazo de Encuentros. Avanza a la etapa 1B.","f":"El ataque a las instalaciones de S.H.I.E.L.D. se ha atribuido a una red clandestina de tráfico de armas."},
  "01116b": {"n":"Distribución clandestina","t":"Cuando se muestre esta carta: descarta cartas del mazo de Encuentros hasta que se descarte un Esbirro. Pon en juego ese Esbirro enfrentado al jugador inicial.","f":"¡Vuestra investigación ha revelado que el jefe de esta organización criminal es Klaw, un viejo enemigo de los Vengadores!"},
  "01117a": {"n":"Reunión secreta","t":"Cuando se muestre esta carta: descarta cartas del mazo de Encuentros hasta que se descarte un Esbirro. Pon en juego ese Esbirro enfrentado al jugador inicial. Avanza a la etapa 2B.","f":"Klaw ha encontrado un comprado interesado en su armamento ilegal. De vosotros depende impedir la transacción, pero el lugar del encuentro está custodiado por los secuaces de Klaw."},
  "01117b": {"n":"Reunión secreta","t":"Si se completa esta etapa, los jugadores pierden la partida.","f":"Klaw se ha reunido con la Capucha Carmesí. El amo del sonido y la misteriosa figura se escabullen entre las sombras cuando les hacéis frente, y los esbirros de Klaw se interponen en vuestro camino para cubrir su fuga."},
  "01118": {"n":"Transformador sónico","t":"Vincula esta carta a Klaw.\n[star] Respuesta obligada: después de que Klaw ataque y cause Daño a un personaje, aturde a ese personaje.\nAcción de Héroe: gasta recursos [energy] [mental] [physical] → descarta esta carta."},
  "01119": {"n":"Cuerpo de sonido sólido","t":"Vincula esta carta a Klaw.\nKlaw gana Represalia 1.\nAcción de Héroe: gasta recursos [energy] [mental] [physical] → descarta esta carta."},
  "01120": {"n":"Guardia acorazado","t":"Guardia.\nDureza."},
  "01121": {"n":"Traficante de armas","t":"Oleada.\n[star] Aumento: Pon en juego al Traficante de armas enfrentado a ti."},
  "01122": {"n":"La venganza de Klaw","t":"Cuando se muestre esta carta (Alter ego): descarta 1 carta de tu mano al azar.\nCuando se muestre esta carta (Héroe): Klaw te ataca. Si este ataque inflige Dañol, coloca 1 de Amenaza sobre el Plan principal."},
  "01123": {"n":"Estallido sónico","t":"Cuando se muestre esta carta: elige entre gastar recursos [energy] [mental] [physical] o bien agotar todos los personajes que controles.\n[star] Aumento: Si esta activación te inflige Daño, agota a tu Héroe."},
  "01124": {"n":"Manipulación del sonido","t":"Cuando se muestre esta carta (Alter ego): Klaw se cura 4 de Daño. Si no se cura Daño de este modo, esta carta gana Oleada.\nCuando se muestre esta carta (Héroe): sufres 2 de Daño. Klaw se cura 2 de Daño."},
  "01125": {"n":"Red de defensa","t":"Cuando se muestre esta carta: coloca 1 [per_hero] de Amenaza adicional sobre esta carta.","f":"La organización criminal de Klaw está protegida por una banda de matones a sueldo."},
  "01126": {"n":"Fábrica de armamento ilegal","t":"Cuando se muestre esta carta: coloca 1 [per_hero] de Amenaza adicional sobre esta carta.","f":"Klaw está suministrando a los villanos armamento avanzado que produce en una fábrica de armas clandestina."},
  "01127": {"n":"Klaw \"el inmortal\"","t":"Klaw recibe +10 de Vida. (Cuando se derrote este Plan, Klaw pierde esta Vida adicional.)","f":"Klaw ejerce tal dominio sobre el sonido que puede volver a adquirir forma sólida por pura fuerza de voluntad."},
  "01128": {"n":"Los Señores del Mal","t":"Cuando se muestre esta carta: descarta cartas del mazo de Encuentros hasta que se descarte un Esbirro Señores del Mal. Pon en juego ese Esbirro enfrentado al jugador inicial.","f":"¡Los Señores del Mal han escogido este momento para atacar a los héroes!"},
  "01129": {"n":"Hombre Radiactivo","t":"[star] Respuesta obligada: después de que el Hombre Radiactivo te ataque, descarta 1 carta de tu mano al azar.\n[star] Aumento: Descarta 1 carta de tu mano al azar."},
  "01130": {"n":"Torbellino","t":"[star] Interrupción obligada: cuando Torbellino te ataque, resuelve su ataque también contra todos los demás Héroes.\n[star] Aumento: Inflige 1 de Daño a cada Héroe."},
  "01131": {"n":"Tiburón Tigre","t":"[star] Respuesta obligada: después de que Tiburón Tigre ataque, dale una carta de Estado \"Duro\".\n[star] Aumento: Dale al Villano una carta de Estado \"Duro\"."},
  "01132": {"n":"Fundidor","t":"[star] El jugador enfrentado debe defender contra los ataques de Fundidor con un Aliado que controle (si puede).\n[star] Aumento: Agota todos los Aliados que controles."},
  "01133": {"n":"Señores del caos","t":"Cuando se muestre esta carta: cada Esbirro Señores del Mal ataca al Héroe con el que esté enfrentado. Si no se efectúa ningún ataque de este modo, busca un Esbirro Señores del Mal en el mazo de Encuentros y en su pila de descartes y ponlo en juego enfrentado a ti; luego baraja el mazo de Encuentros."},
  "01134": {"n":"Ultrón","t":"[star] Respuesta obligada: después e que Ultrón te ataque, elige entre colocar 1 de Amenaza sobre el Plan principal o bien poner en juego la primera carta de tu mazo enfrentada a tu boca abajo como un Esbirro Dron."},
  "01135": {"n":"Ultrón","t":"[star] Interrupción obligada: cuando Ultrón te ataque, pon en juego la primera carta de tu mazo enfrentada a ti boca abajo como un Esbirro Dron. Hasta el final de este ataque, Ultrón recibe +1 ATQ por cada Esbirro Dron que esté enfrentado a ti."},
  "01136": {"n":"Ultrón","t":"Cada Esbirro Dron recibe +1 de ATA y +1 de Vida. Ultrón no puede sufrir Daño mientras haya en juego un Esbirro Dron.\nCuando se muestre esta carta: busca el Plan secundario \"La Directriz Ultrón\" en el mazo de Encuentros y en su pila de descartes y muéstralo. Baraja el mazo de Encuentros."},
  "01137a": {"n":"La Capucha Carmesí","t":"Contenido: Ultrón (I) y Ultrón (II). (Ultrón (II) y Ultrón (III) para jugar en modo Experto). Conjuntos de Encuentros normales y de Ultrón. Un conjunto de Encuentros modular (recomendado: Civiles en peligro).\nPreparación: pon en juego la carta de Entorno Drones de Ultrón. Baraja el mazo de Encuentros. Avanza a la etapa 1B.","f":"El misterioso cliente encapuchado de Klaw es en realidad el androide genocida Ultrón."},
  "01137b": {"n":"La Capucha Carmesí","t":"Cuando se muestre esta carta: cada jugador pone en juego la primera carta de su mazo boca abajo y enfrentada a él como un Esbirro Dron.","f":"Ultrón está usando las piezas suministradas por Klaw para construir un ejército de drones robóticos."},
  "01138a": {"n":"Ataque al NORAD","t":"Cuando se muestre esta carta: cada jugador pone en juego la primera carta de su mazo boca abajo y enfrentada a él como un Esbirro Dron. Avanza a la etapa 2B.","f":"Mientras seguís el rastro de Ultrón, recibís una llamada de socorro procedente del Mando Norteamericano de Defensa Aeroespacial situado en Colorado. ¡Un ejército de drones de Ultrón los tiene bajo asedio!"},
  "01138b": {"n":"Ataque al NORAD","t":"Respuesta obligada: después de que se coloque Amenaza sobre esta carta durante el paso uno de la fase del Villano, cada jugador debe elegir entre colocar 2 de Amenaza sobre esta carta o bien poner en juego la primera carta de su mazo boca abajo y enfrentada a él como un Esbirro Dron.","f":"¡Si Ultrón toma el control del NORAD, tendrá acceso a todos los misiles balísticos de Estados Unidos!"},
  "01139a": {"n":"Cuenta atrás para el olvido","t":"Cuando se muestre esta carta: cada jugador pone en juego la primera carta de su mazo boca abajo y enfrentada a él como un Esbirro Dron. Avanza a la etapa 3B.","f":"Ultrón ha tomado el control del NORAD. Es sólo cuestión de tiempo que supere las medidas de seguridad y lance todo el arsenal nuclear."},
  "01139b": {"n":"Cuenta atrás para el olvido","t":"No puede quitarse Amenaza de este Plan.\nSi se completa esta etapa, los jugadores pierden la partida.","f":"¡Sóis los únicos que podéis slavar el mundo del holocausto nuclear!"},
  "01140": {"n":"Drones de Ultrón","t":"Cada Esbirro Dron que esté enfrentado boca abajo a un jugador tiene un PLA básico de 1, un ATQ básico de 1 y una Vida básica de 1.\nRespuesta obligada: después de que un Esbirro Dron que esté boca abajo sea derrotado, coloca esa carta en la pila de descartes de su propietario."},
  "01141": {"n":"Transmisor de programa","t":"Vincula esta carta a Ultrón.\n[star] Respuesta obligada: después de que Ultrón ejecute el Plan, coloca 1 de Amenaza sobre cada Plan secundario.\nAcción de Héroe: agota tu Héroe y gasta recursos [mental] [mental] → descarta esta carta."},
  "01142": {"n":"Drones mejorados","t":"Vincula esta carta al Entorno Drones de Ultrón.\nCada Esbirro Dron que esté boca abajo recibe +1 ATQ y +1 de Vida.\nAcción de Héroe: gasta recursos [energy] [mental] [physical] → descarta esta carta."},
  "01143": {"n":"Dron avanzado de Ultrón.","t":"Guardia.\nInterrupción obligada: cuando el Dron avanzado de Ultrón sea derrotado, el jugador al que estaba enfrentado pone en juego la primera carta de su mazo boca abajo y enfrentada a él como un Esbirro Dron"},
  "01144a": {"n":"Eficacia androide","t":"Cuando se muestre esta carta: cada jugador pone en juego la primera carta de su mazo boca abajo y enfrentada a él como un Esbirro Dron.\n[star] Aumento: Elige entre gastar un recurso [energy] o bien poner en juego la primera carta de tu mazo boca abajo y enfrentada a tu como un Esbirro Dron"},
  "01144b": {"n":"Eficacia androide","t":"Cuando se muestre esta carta: cada jugador pone en juego la primera carta de su mazo boca abajo y enfrentada a él como un Esbirro Dron.\n[star] Aumento: Elige entre gastar un recurso [mental] o bien poner en juego la primera carta de tu mazo boca abajo y enfrentada a tu como un Esbirro Dron"},
  "01144c": {"n":"Eficacia androide","t":"Cuando se muestre esta carta: cada jugador pone en juego la primera carta de su mazo boca abajo y enfrentada a él como un Esbirro Dron.\n[star] Aumento: Elige entre gastar un recurso [physical] o bien poner en juego la primera carta de tu mazo boca abajo y enfrentada a tu como un Esbirro Dron"},
  "01145": {"n":"La cólera de Ultrón","t":"Cuando se muestre esta carta (Alter ego): Ultrón ejecuta el Plan. Descarta tantas cartas de la parte superior de tu mazo como la cantidad de Amenaza que se coloque de este modo.\nCuando se muestre esta carta (Héroe): Ultrón te ataca. Descarta tantas cartas de la parte superior de tu mazo como la cantida de Daño que inflija este ataque."},
  "01146": {"n":"Secuencia de reparación","t":"Cuando se muestre esta carta: Ultrón se cura 2 de Daño por cada Esbirro Dron que esté enfrentado a ti. Si no se cura Daño de este modo, esta carta gana Oleada.\n[star] Aumento: Ultrón se cura 1 de Daño por cada Esbirro Dron que esté enfrentado a ti."},
  "01147": {"n":"Ejército robótico","t":"Cuando se muestre esta carta: cada Esbirro Dron que esté enfrentado a tu Héroe ataca. Si no se efectúa ningún ataque de este modo, pon en juego la primera carta de tu mazo boca abajo y enfrentada a ti como un Esbirro Dron."},
  "01148": {"n":"Fábrica de drones","t":"Cuando se muestre esta carta: cada jugador pone en juego la primera carta de su mazo boca abajo y enfrentada a él como un Esbirro Dron. Coloca 1 de Amenaza sobre esta carta oir cada Esbirro Dron que haya en juego."},
  "01149": {"n":"IA invasiva","t":"Cuando se muestre esta carta: cada jugador descarta las 3 primeras cartas de su mazo.","f":"Ultrón está pirateando redes inalámbricas por todo el planeta para causar una crisis a escala mundial."},
  "01150": {"n":"La Directriz Ultrón","t":"Cuando se muestre esta carta: el jugador inicial pone en juego las 2 primeras cartas de su mazo boca abajo y enfrentadas a él como Esbirros Dron.","f":"Ultrón controla su ejército de drones mediante una mente colmena electrónica."},
  "01151": {"n":"Civiles en peligro","t":"Cuando se muestre esta carta: cada jugador elige entre colocar 2 de Amenaza sobre esta carta o bien infligir 3 de Daño a su Héroe.","f":"Están atacando a unos civiles. ¡Necesitan vuestra ayuda urgentemente!"},
  "01152": {"n":"Armadura de Vibránium","t":"Vincula esta carta al Villano.\nRespuesta obligada: después de que el Villano sufra Daño, dale una carta de Estado \"Duro\".\nAcción de Héroe: agota tu Héroe y gasta recursos [physical] [physical] → descarta esta carta."},
  "01153": {"n":"Rayos de fuerza","t":"Vincula esta carta al Villano.\nEl Villano gana Represalia 1.\nAcción de Héroe: agota tu Héroe y gasta recursos [energy] [energy] → descarta esta carta."},
  "01154": {"n":"Descarga fulminante","t":"Cuando se muestre esta carta: inflige 1 de Daño a cada personaje amigo.\n[star] Aumento: Inflige 1 de Daño a cada personaje que controles."},
  "01155": {"n":"Asuntos de estado","t":"Dale esta carta al jugador que lleva a T'Challa.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n— Agota a T'Challa → retira del juego Asuntos de estado.\n— Descarta una Mejora Pantera Negra de tu elección que controles. Descarta esta Obligación."},
  "01156": {"n":"Usurpar el trono","f":"El renegado Killmonger ha efectuado un golpe de estado para hacerse con el poder en Wakanda."},
  "01157": {"t":"Killmonger no puede sufrir Daño causado por Mejoras Pantera Negra.","f":"\"¡Debería ser yo el que se sienta en el trono!\""},
  "01158": {"n":"Hierba con forma de corazón","t":"Oleada.\nCuando se muestre esta carta: dales una carta de Estado \"Duro\" al Villano y a todos los Esbirros que estén enfrentados a ti.\n[star] Aumento: Dale al Villano una carta de Estado \"Duro\"."},
  "01159": {"n":"Combate ritual","t":"Cuando se muestre esta carta: descarta la primera carta del mazo de Encuentros. Luego elige entre infligir X de Daño a tu Héroe o bien colocar X de Amenaza sobre el Plan principal. X es igual a 1 más el número de iconos de Aumento que haya en la carta de Encuentro descartada."},
  "01160": {"n":"Trabajo jurídico","t":"Dale esta carta al jugador que lleva a Jennifer Walters.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n— Agota a Jennifer Walters → retira del juego Trabajo jurídico.\n— Asigna 1 ficha de Aceleración al Plan principal. Descarta esta Obligación."},
  "01161": {"n":"Reto personal","t":"Cuando se muestre esta carta: coloca 1 [per_hero] de Amenaza adicional sobre esta carta.","f":"Titania se la tiene jurada a Hulka desde hace años. No descansará hasa saldar cuentas con ella."},
  "01162": {"t":"X es igual a la Vida restante de Titania","f":"\"Admítelo, verdusca. Sólo hay lugar para UNA mujer más fuerte… ¡y no eres tú!\""},
  "01163": {"n":"Mejora genética","t":"Vicnula esta carta al Esbirro que tenga el valor impreso más alto de Vida. Si no hay Esbirros en juego, esta carta gana Oleada.\nEl Esbiro vinculado recibe +3 de Vida."},
  "01164": {"n":"La furia de Titania","t":"Cuando se muestre esta carta: Titania ataca a tu Héroe. Si Titania no ha atacado, cura todo el Daño de Titania y esta carta gana Oleada.\n[star] Aumento: Dale al Villano 1 carta de aumento adicional para esta activación."},
  "01165": {"n":"Aviso de desahucio","t":"Dale esta carta al jugador que lleva a Peter Parker.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n— Agota a Peter Parker → retira del juego Aviso de desahucio.\n— Descarta 1 carta de tu mano al azar. Esta carta gana Oleada. Descarta esta Obligación."},
  "01166": {"n":"Ladrón Alado","t":"Cuando se muestre esta carta: cada jugador coge al azar una carta de su mano y la coloca boca abajo sobre esta carta.\nCuando se derrote esta carta: devuelve a la mano de su propietario las cartas que estén boca abajo sobre esta carta."},
  "01167": {"n":"Buitre","t":"Ataque veloz.","f":"\"¡Soy más rápido, fuerte e inteligente que cien hombres de mi edad!\""},
  "01168": {"n":"Picado arrollador","t":"Cuando se muestre esta carta: atarude a tu Héroe. Si el Buitre está en juego, esta carta gana Oleada.\n[star] Aumento: Si esta activación inflige Daño a un personaje amigo, aturde a ese personaje."},
  "01169": {"n":"Los planes del Buitre","t":"Cuando se muestre esta carta: descarta 1 carta al azar de la mano de cada jugador. Coloca 1 de Amenaza sobre el Plan principal por cada tipo de recurso distinto que se haya descartado de este modo.","f":"\"¡Spiderman pagará caro el haber interferido en mis planes!\" —El Buitre"},
  "01170": {"n":"Problemas de negocios","t":"Dale esta carta al jugador que lleva a Tony Stark.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n— Agota a Tony Stark → retira del juego Problemas de negocios.\n— Agota todas las Mejoras que controles. Descarta esta Obligación."},
  "01171": {"n":"Sobrecarga inminente","t":"Cuando se muestre esta carta: coloca 1 [per_hero] de Amenaza adicional sobre esta carta.","f":"Latigazo se ha hecho con el control de una central eléctrica y amenaza con sobrecargar los transformadores si no se cumplen sus exigencias."},
  "01172": {"n":"Latigazo","t":"Represalia 1.","f":"\"Tú lo has empezado, Tony. Yo lo voy a terminar.\""},
  "01173": {"n":"Azote de electrolátigo","t":"Cuando se muestre esta carta: elige entre infligir 1 de Daño a tu Héroe por cada Mejora que controles, o bien elegir y descartar una Mejora que controles.\n[star] Aumento: Si el Villano está efectuando un ataque no defendido, elige y descarta una Mejora que controles."},
  "01174": {"n":"Descarga electromagnética","t":"Cuando se muestre esta carta: cada jugador descarta las 5 primeras cartas de su mazo. Por cada recurso [energy] impreso que haya descartado un jugador de este modo, ese jugador sufre 1 de Daño.","f":"Cinca, cuatro, tres, dos…"},
  "01175": {"n":"Emergencia familiar","t":"Dale esta carta al jugador que lleva a Carol Danvers.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n— Agota a Carol Danvers → retira del juego Emergencia familiar.\n— Quedas aturdido. Esta carta gana Oleada. Descarta esta Obligación."},
  "01176": {"n":"El psicomagnetrón","t":"Cuando se muestre esta carta: coloca 1[per_hero] de Amenaza adicional sobre esta carta.","f":"El psicomagnetrón es un dispositivo kree que tiene el poder de hacer realidad los pensamientos. En manos de Yon-Rogg sería un arma devastadora."},
  "01177": {"t":"[star] Respuesta obligada: después de que Yon-Rogg ataque, coloca 1 de Amenaza sobre El psicomagnetrón.","f":"\"No es auténtico poder a menos que te teman.\""},
  "01178": {"n":"Manipulador kree","t":"Oleada.\nCuando se muestre esta carta: coloca 1 de Amenaza sobre el Plan principal.\n[star] Aumento: Si el villano está efectuando un ataque no defendido, coloca 1 de Amenaza sobre el Plan principal."},
  "01179": {"n":"La traición de Yon-Rogg","t":"Cuando se muestre esta carta: descarta todos los recursos [energy] que haya en tu mano. Si no has descartado ninguna carta de este modo, esta carta gana Oleada.","f":"\"¡Ahora este mundo pertenece al Imperio Kree!\" —Yon-Rogg"},
  "01180": {"n":"Legiones de Hydra","t":"Cuando se muestre esta carta: si Madame Hydra no está en juego, busca a Madame Hydra en el mazo de Encuentros y en su pila de descartes y ponla en juego enfrentada a ti; luego baraja el mazo de Encuentros. Coloca 2 de Amenaza adicional sobre esta carta por cada enemigo Hydra que haya en el juego."},
  "01181": {"t":"Madame Hydra no puede sufrir Daño mientras esté en juego el Plan secundario Legiones de Hydra.\n[star] Respuesta obligada: después de que Madame Hydra ejecute el Plan o ataque, coloca 2 de Amenaza sobre el Plan secundario Legiones de Hydra."},
  "01182": {"n":"Soldado de Hydra","t":"Guardia.\nCuando se derrote esta carta: reparte una carta de Encuentro al jugador enfrentado."},
  "01183": {"n":"La Silla del Juicio Final","t":"Cuando se muestre esta carta: si MODOK no está en juego, busca a MODOK en el mazo de Encuentros y en su pila de descartes y ponlo en juego enfrentado a ti; luego baraja el mazo de Encuentros."},
  "01184": {"n":"MODOK","t":"Represalia 2.","f":"\"¡Deberías haberte quedado escondido debajo de la roca de la que has salido arrastrándote!\""},
  "01185": {"n":"Mejoras biomecánicas","t":"Oleada.\nVincula esta carta al Esbirro que tenga el valor impreso más alto de Vida y que no tenga ya vinculada otra carta de Mejoras biomecánicas.\nInterrupción obligada: cuando el Esbirro vinculado vaya a ser derrotado, en vez de eso cúrale todo el Daño y luego descarta esta carta."},
  "01186": {"n":"Mover ficha","t":"Cuando se muestre esta carta: el Villano ejecuta el Plan.","f":"\"¡El mundo será mío!\" —Cráneo Rojo"},
  "01187": {"n":"Agresión","t":"Cuando se muestre esta carta (Alter ego): esta carta gana Oleada.\nCuando se muestre esta carta (Héroe): el Villano te ataca.","f":"\"¡Muere!\" —Veneno"},
  "01188": {"n":"Con la guardia baja","t":"Cuando se muestre esta carta: descarta una Mejora o Apoyo que controles. Si no se descarta ninguna carta de este modo, esta carta gana Oleada."},
  "01189": {"n":"Todos a una","t":"Cuando se muestre esta carta (Alter ego): esta carta gana Oleada.\nCuando se muestre esta carta (Héroe): el Villano y todos los Esbirros que estén enfrentados a ti te atacan."},
  "01190": {"n":"Una sombra del pasado","t":"Cuando se muestre esta carta: muestra tu Esbirro Archienemigo que está apartado y ponlo en juego enfrentado a ti. Muestra el Plan secundario de tu Archienemigo que está apartado y ponlo en juego. Mezcla el resto del conjunto de Encuentros apartado de tu Archienemigo con el mazo de Encuentros y barájalo. Si tu Esbirro Archienemigo no entra en juego de este modo, esta carta gana Oleada."},
  "01191": {"n":"Agotamiento","t":"Oleada.\nCuando se muestre esta carta: agota tu carta de Superhéroe."},
  "01192": {"n":"Plan maestro","t":"Cuando se muestre esta carta: coloca 4 de Amenaza sobre cada Plan secundario. Si no hay Planes secundarios en juego, descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Plan secundario. Muestra ese Plan secundario."},
  "01193": {"n":"Bajo fuego intenso","t":"Oleada.\nCuando se muestre esta carta: muestra la primera carta del mazo de Encuentros.","f":"\"Pero ¡espera, que aún hay más!\" —Klaw"},
  "02001a": {"t":"[star] Interrupción obligada: cuando Norman Osborn vaya a atacar, en vez de eso coloca 1 contador de Infamia sobre Empresa criminal.\nInterrupción obligada: cuando Norman Osborn vaya a sufrir cualquier cantidad de Daño, en vez de eso quita esa misma cantidad de contadores de Infamia de Empresa criminal."},
  "02001b": {"n":"Duende Verde","t":"Cuando se muestre esta carta: inflige 3 de Daño indirecto a todos los jugadores que tengan adoptada su identidad de Héroe.\n[star] Interrupción obligada: cuando el Duende Verde vaya a ejecutar el Plan, en vez de eso quita 1 contador de Locura de Estado de locura."},
  "02002a": {"t":"[star] Interrupción obligada: cuando Norman Osborn vaya a atacar, en vez de eso coloca 2 contadores de Infamia sobre Empresa criminal.\nInterrupción obligada: cuando Norman Osborn vaya a sufrir cualquier cantidad de Daño, en vez de eso quita esa misma cantidad de contadores de Infamia de Empresa criminal."},
  "02002b": {"n":"Duende Verde","t":"Cuando se muestre esta carta: inflige 4 de Daño indirecto a cada jugador.\n[star] Interrupción obligada: cuando el Duende Verde vaya a ejecutar el Plan, en vez de eso quita 1 contador de Locura de Estado de locura."},
  "02003a": {"t":"[star] Interrupción obligada: cuando Norman Osborn vaya a atacar, en vez de eso coloca 3 contadores de Infamia sobre Empresa criminal.\nInterrupción obligada: cuando Norman Osborn vaya a sufrir cualquier cantidad de Daño, en vez de eso quita esa misma cantidad de contadores de Infamia de Empresa criminal."},
  "02003b": {"n":"Duende Verde","t":"Cuando se muestre esta carta: inflige 4 de Daño a cada jugador.\n[star] Interrupción obligada: cuando el Duende Verde vaya a ejecutar el Plan, en vez de eso quita 2 contadores de Locura de Estado de locura."},
  "02004a": {"n":"OPA hostil","t":"Contenido: Norman Osborn (I) y Norman Osborn (II). (Norman Osborn (II) y Norman Osborn (III) para jugar en modo Experto.) Conjuntos de Encuentro normales y de Negocios arriesgados. Un conjunto de Encuentros modular (recomendado: Trucos de duende).\nPreparación: pon en juego la carta de Entorno Empresa criminal. Baraja el mazo de Encuentros. Avanza a la etapa 1B."},
  "02004b": {"n":"OPA hostil","t":"Cuando se complete esta etapa: coloca 1 [per_hero] contadores de Infamia sobre Empresa criminal. Luego descarta 1 carta del mazo de cada jugador por cada contador de Infamia que haya sobre Empresa criminal.","f":"Norman Osborn se ha reunido con la junta directiva para planificar la adquisición de una filial de Industrias Stark."},
  "02005a": {"n":"Adquisición corporativa","t":"Cuando se muestre esta carta: avanza a la etapa 2B.","f":"Ahora que controla una filial de Industrias Stark, Norman Osborn obtendrá acceso a tecnologías mortíferas y cuadruplicará la producción de Oscorp."},
  "02005b": {"n":"Adquisición corporativa","t":"Si se completa esta etapa, los jugadores pierden la partida.","f":"Si Norman Osborn triunfa, nada se interpondrá en su camino hacia la supremacía tecnológica."},
  "02006a": {"n":"Empresa criminal","t":"Empresa criminal entre en juego con 2[per_hero] contadores de Infamia. Si no hay contadores de Infamia sobre esta carta, dales la vuelta a Norman Osborn y a Empresa criminal.","f":"\"Los negocios van bien.\""},
  "02006b": {"n":"Estado de locura","t":"Estado de locura entre en juego con 2 [per_hero] contadores de Locura. Si no hay contadores de Locura sobre esta carta, dales la vuelta al Duende Verde y a Estado de Locura.","f":"\"¡Idiota! ¡Tu poder no es nada comparado con el mío! Tu fuerza no es nada. Tu intelecto no es nada.\" —Duende Verde"},
  "02007": {"n":"Pistolero a sueldo","t":"Cuando se muestre esta carta: elige entre darle al Villano 1 carta de aumento boca abajo o colocar 2 contadores de Infamia sobre Empresa criminal.\n[star] Aumento: Coloca 1 contador de Infamia sobre Empresa criminal. Si no puedes hacerlo, quita 1 contador de Locura de Estado de locura."},
  "02008": {"n":"Guardia privado de seguridad","t":"Guardia.\n[star] Aumento: Coloca 1 contador de Infamia sobre Empresa criminal. Si no puedes hacerlo, quita 1 contador de Locura de Estado de locura."},
  "02009": {"n":"Puente inestable","t":"[star] Aumento: Coloca 1 contador de Infamia sobre Empresa criminal. Si no puedes hacerlo, quita 1 contador de Locura de Estado de locura."},
  "02010": {"n":"Industrias Oscorp","t":"Cuando se muestre esta carta (Norman Osborn): coloca 1[per_hero] de Amenaza adicional sobre esta carta.","f":"Pese a las protestas de los accionistas, ahora Oscorp produce exclusivamente armamento de categoría militar."},
  "02011": {"n":"Soborno","t":"[star] Aumento: Coloca 1 contador de Infamia sobre Empresa criminal. Si no puedes hacerlo, quita 1 contador de Locura de Estado de locura.","f":"Despite objections from shareholders, Oscorp now exclusively produces military-grade weaponry."},
  "02012": {"n":"Rutina laboral","t":"Cuando se muestre esta carta: coloca 2 contadores de Infamia sobre Empresa criminal. Si no puedes hacerlo, quita 2 contadores de Locura de Estado de locura.\n[star] Aumento: Coloca 1 contador de Infamia sobre Empresa criminal. Si no puedes hacerlo, quita 1 contador de Locura de Estado de locura."},
  "02013": {"n":"Genio loco","t":"Cuando se muestre esta carta (Duende Verde): el Duende Verde ataca al Héroe que tenga menos Vida restante. Si no se produce ningún ataque de este modo, esta carta gana Oleada.\nCuando se muestre esta carta (Norman Osborn): descarta tantas cartas de la parte superior de tu mazo como el número de contadores de Infamia que haya sobre Empresa criminal"},
  "02014": {"n":"Duende Verde","t":"Respuesta obligada: después de que el Duende Verde ataque y te inflija Daño, coloca 1 de Amenaza sobre el Plan principal.","f":"\"¿Creías que el Duende Verde te dejaría vivir?\""},
  "02015": {"n":"Duende Verde","t":"Cuando se muestre esta carta: reparte 2 cartas de Encuentro a cada jugador.\n[star] Respuesta obligada: después de que el Duende Verde ataque y te inflija Daño, coloca 1 de Amenaza sobre el Plan principal."},
  "02016": {"n":"Duende Verde","t":"Cuando se muestre esta carta: reparte 3 cartas de Encuentro a cada jugador.\n[star] Respuesta obligada: después de que el Duende Verde ataque y te inflija Daño, coloca 2 de Amenaza sobre el Plan principal."},
  "02017a": {"n":"Liberar el mutágeno","t":"Contenido: Duende Verde (I) y Duende Verde (II). (Duende Verde (II) y Duende Verde (III) para jugar en modo Experto.) Conjuntos de Encuentro normales y de La fórmula mutagénica. Un conjunto de Encuentros modular (recomendado: Trucos de duende).\nPreparación: pon en juego un Esbirro Esclavo duende enfrentado a cada jugador. Baraja el mazo de Encuentros. Avanza a la etapa 1B."},
  "02017b": {"n":"Liberar el mutágeno","t":"Cuando se complete esta etapa: siguiendo el orden de jugadores, cada jugador que no esté enfrentado a un Esbirro Duende debe descartar 3 cartas del mazo de Encuentros y poner en juego enfrentado a él el primer Esbirro Duende descartado de este modo.","f":"El Duende Verde ha liberado un mutágeno tóxico en forma de gas sobre la ciudad de Nueva York."},
  "02018a": {"n":"Nube de mutágeno","t":"Cuando se muestre esta carta: avanza a la etapa 2B.","f":"La nube se propaga por la ciudad, y quienes tienen la desgracia de verse atrapados por el gas empiezan a convulsionarse y a cambiar, transformándose en horribles criaturas semejantes a duendes."},
  "02018b": {"n":"Nube de mutágeno","t":"X es igual al número de enemigos Duende (incluido el Duende Verde) que haya en juego.\nSi se completa esta etapa, los jugadores pierden la partida.","f":"Las criaturas transfiguradas obedecen todas las órdenes del Duende Verde. ¡Tenéis que detener al villano antes de que su monstruosa milicia invada la ciudad!"},
  "02019": {"n":"Planeador duende","t":"Vincula esta carta al enemigo que tenga el valor impreso más alto de Vida y que no tenga ya vinculado otro Planeador duende. Si no puedes hacerlo, esta carta gana Oleada.\nAcción de Héroe: gasta recursos [energy] [energy] → descarta esta carta."},
  "02020": {"n":"Histeria","t":"Vincula esta carta al Duende Verde.\n[star] Interrupción obligada: cuando el Duende Verde ataque o ejecute el Plan, dale 1 carta de aumento adicional para esa activación.\nAcción de Héroe: gasta recursos [mental] [mental] → descarta esta carta."},
  "02021": {"n":"Bombas calabaza","t":"Vincula esta carta al Villano.\n[star] Respuesta obligada: después de que el Villano te ataque, descarta Bombas calabaza y sufres 2 de Daño indirecto.\nAcción de Héroe: gasta recursos [physical] [physical] → descarta esta carta."},
  "02022": {"n":"Caballero Duende","t":"[star] Respuesta obligada: después de que el Caballero Duende te ataque, descarta 1 carta del mazo de Encuentros. Si esa carta es un Esbirro Duende, ponlo en juego enfrentado a ti.\n[star] Aumento: Después de que termine esta activación, devuelve esta carta al mazo de Encuentros y barájalo."},
  "02023": {"n":"Soldado duende","t":"Cuando se derrote esta carta: inflige 1 de Daño al jugador enfrentado.\n[star] Aumento: Pon en juego al Soldado duende enfrentado a ti."},
  "02024": {"n":"Esclavo duende","t":"Guardia.\n[star] Aumento: Pon en juego al Esclavo duende enfrentado a ti."},
  "02025": {"n":"Monstruo","t":"Cuando se muestre esta carta: quedas aturdido. Si ya estabas aturdido, sufres 2 de Daño.\n[star] Aumento: Después de que termine esta activación, devuelve esta carta al mazo de Encuentros y barájalo."},
  "02026": {"n":"Duendes de refuerzo","t":"Cuando se muestre esta carta: coloca 1 de Amenaza adicional sobre esta carta por cada Esbirro Duende que haya en juego.","f":"El Duende Verde ha empleado el suero del mutágeno y su entrenamiento de combate avanzado para crear un comando de duendes de élite."},
  "02027": {"n":"Nación duende","t":"Todos los enemigos Duende (incluido el Duende Verde) recibe +1 ATQ.\n[star] Aumento: Pon en juego Nación duende.","f":"\"No somos una pandilla. Somos mucho más. Somos una familia. ¡Un imperio! ¡Un panteón! ¿Y yo? ¡Soy el Rey Duende!\" —Duende Verde"},
  "02028": {"n":"Horda imparable","t":"Cuando se derrote esta carta: siguiendo el orden de jugadores, cada jugador debe descartar 2 cartas del mazo de Encuentros y poner en juego enfrentado a él todos los Esbirros Duende que haya descartado de este modo."},
  "02029": {"n":"Muerte desde el cielo","t":"Cuando se muestre esta carta (Alter ego): el Duende Verde ejecuta el Plan con +X PLA, siendo X igual al número de etapa del Villano.\nCuando se muestre esta carta (Héroe): el Duende Verde ataca con +X ATQ, siendo X igual al número de etapa del Villano."},
  "02030": {"n":"Te veo","t":"Cuando se muestre esta carta: el Duende Verde te ataca. Si tienes adoptada la forma de tu Alter ego, no des al Villano una carta de aumento para esta activación.\n[star] Aumento: Esta carta recibe +1 icono de Aumento ([boost]) si hay al menos un Esbirro Duende enfrentado a ti."},
  "02031": {"n":"Exceso de confianza","t":"Cuando se muestre esta carta (Alter ego): el Duende Verde ejecuta el Plan. Si se han colocado al menos 3 de Amenaza con esta activación, esta carta gana Oleada.\nCuando se muestre esta carta (Héroe): el Duende Verde te ataca. Si se han infligido al menos 3 de Daño con esta activación, esta carta gana Oleada."},
  "02032": {"n":"Ambición cruel","t":"Cuando se muestre esta carta: descarta X cartas del mazo de Encuentros, siendo X igual al doble del número de etapa del Villano. Cada vez que se descarte un Esbirro Duende de este modo, elige entre sufrir 3 de Daño o poner en juego ese Esbirro enfrentado a ti."},
  "02033": {"n":"Planeador duende","t":"Vincula esta carta al enemigo que tenga el valor impreso más alto de Vida y que no tenga ya vinculado otro Planeador duende. Si no puedes hacerlo, esta carta gana Oleada.\nAcción de Héroe: gasta recursos [energy] [energy] → descarta esta carta."},
  "02034": {"n":"Bombas calabaza","t":"Vincula esta carta al Villano.\n[star] Respuesta obligada: después de que el Villano te ataque, descarta Bombas calabaza y sufres 2 de Daño indirecto.\nAcción de Héroe: gasta recursos [physical] [physical] → descarta esta carta."},
  "02035": {"n":"Intimidación","t":"Cuando se muestre esta carta: elige entre gasta 2 recursos de cualquier tipo o darle al Villano 1 carta de aumento boca abajo.\n[star] Aumento: Dale al Villano 1 carta de aumento adicional para esta activación."},
  "02036": {"n":"Curación regenerativa","t":"Cuando se muestre esta carta: el Villano se cura X de Daño, siendo X igual al doble del número de etapa del Villano. Si no se cura Daño de este modo, esta carta gana Oleada.\n[star] Aumento: El Villano se cura 2 de Daño."},
  "02037": {"n":"Un auténtico estropicio","t":"Cuando se muestre esta carta: coloca 2 de Amenaza adicional sobre esta carta por cada personaje amigo que esté aturdido.","f":"El Escorpión está sembrando el caos y la destrucción por las calles del distrito financiero."},
  "02038": {"n":"Escorpión","t":"Ataque veloz.\n[star] Respuesta obligada: después de que el Escorpión te ataque y cause Daño a un personaje, aturde a ese personaje.","f":"\"¡Te voy a aplastar, Spiderman!\""},
  "02039": {"n":"Todos a una","t":"Cuando se muestre esta carta (Alter ego): esta carta gana Oleada.\nCuando se muestre esta carta (Héroe): el Villano y todos los Esbirros que estén enfrentados a ti te atacan."},
  "02040": {"n":"Barrido de cola","t":"Cuando se muestre esta carta: el Escorpión ataca a tu Héroe. Si no se efectúa ningún ataque de este modo, quedas aturdido.\n[star] Aumento: Quedas aturdido."},
  "02041": {"n":"Alta tensión","t":"Cuando se derrote esta carta: descarta 2 cartas del mazo de Encuentros. Cada jugador debe elegir y descartar 1 recurso de cualquier tipo de su mano por cada icono de Aumento que se haya descartado de este modo."},
  "02042": {"t":"[star] Respuesta obligada: después de que Electro te ataque, descarta 1 carta del mazo de Encuentros. Sufres 1 de Daño indirecto por cada icono de Aumento que se haya descartado de este modo.\n[star] Aumento: Descarta 3 cartas del mazo de Encuentros."},
  "02043": {"n":"Pulso electromagnético","t":"Cuando se muestre esta carta: descarta 7 cartas del mazo de Encuentros. Si se ha descartado a Electro de este modo, ponlo en juego enfrentado a ti. Si no se ha descartado a Electro de este modo, esta carta gana Oleada.\n[star] Aumento: Descarta 3 cartas del mazo de Encuentros."},
  "02044": {"n":"Descarga eléctrica","t":"Cuando se muestre esta carta: descarta 2 cartas del mazo de Encuentros. Sufres 1 de Daño indirecto por cada icono de Aumento que se haya descartado de este modo.\n[star] Aumento: Descarta 3 cartas del mazo de Encuentros."},
  "02045": {"n":"Terapia de electrochoque","t":"Cuando se muestre esta carta: descarta 1[per_hero] cartas del mazo de Encuentros. El Villano se cura 1 de Daño por cada icono de Aumento que se haya descartado de este modo.\n[star] Aumento: Descarta 3 cartas del mazo de Encuentros."},
  "02046": {"n":"Impedimentos","t":"Cuando se muestre esta carta: cada jugador debe elegir entre descartar recursos [mental] [physical] o bien colocar 2 de Amenaza sobre esta carta."},
  "02047": {"n":"Lápida","t":"[star] Respuesta obligada: después de que Lápida ataque y te inflija Daño, descarta un recurso [mental] o [physical] de tu mano (si puedes)."},
  "02048": {"n":"Con las manos atadas","t":"Vincula esta carta a tu carta de Superhéroe.\nEl personaje vinculado no puede prepararse ni cambiar de identidad.\nAcción: gasta recursos [mental] [physical] → descarta esta carta."},
  "02049": {"n":"Cobertura mediática","t":"Vincula esta carta a tu carta de Superhéroe.\nResuelve 1 vez adicional cada capacidad de \"Cuando se muestre esta carta\" que muestres.\nAcción de Alter ego: gasta un recurso [mental] → descarta esta carta."},
  "03001a": {"n":"Capitán América","t":"\"¡Aguantaría todo el día!\" — Acción: descarta 1 carta de tu mano → prepara al Capitán América. (Límite de una vez por ronda.)","f":"\"Mi deber con mi país está primero... ¡no importa cuál sea el precio!\""},
  "03001b": {"t":"Leyenda viviente — Reduce en 1 el coste del primer Aliado que se juegue en cada ronda.\nPreparación: busca en tu mazo y tu pila de descartes la Mejora Escudo del Capitán América y añádela a tu mano. Baraja tu mazo."},
  "03002": {"n":"Agente 13","t":"Respuesta: después de que la Agente 13 entre en juego, quita 2 de Amenaza de un Plan.","f":"\"¡Capi, dijiste que lucharíamos en equipo! ¡Quiero ir contigo!\""},
  "03003": {"n":"Determinación audaz","t":"Acción de Héroe: el Capitán América recibe +1 INT hasta el final de la fase. Roba 1 carta.","f":"\"Nadie muere delante de mí.\" —Capitán América"},
  "03004": {"n":"Golpe heroico","t":"Acción de Héroe (ataque): inflige 6 de Daño a un enemigo. Si has pagado el coste de esta carta usando un recurso [physical], aturde a ese enemigo.","f":"\"No, muévete tú.\" —Capitán América"},
  "03005": {"n":"Bloqueo de escudo","t":"Interrupción (defensa): cuando vayas a sufrir cualquier cantidad de Daño, agota el Escudo del Capitán América → evita todo ese Daño.","f":"\"¿Eso es todo lo que tienes?\" —Capitán América"},
  "03006": {"n":"Lanzamiento de escudo","t":"Acción de Héroe (ataque): descarta X cartas de tu mano, luego devuelve el Escudo del Capitán América del juego a tu mano → inflige 4 de Daño a X enemigos.","f":"\"¡Sharon! ¡Agáchate!\" —Capitán América"},
  "03007": {"n":"Apartamento de Steve","t":"Acción de Alter ego: agota el Apartamento de Steve → roba 1 carta y cura 1 de Daño a Steve Rogers.","f":"Incluso el Capitán América necesita un lugar en el que refugiarse y descansar."},
  "03008": {"n":"Casco del Capitán América","t":"Interrupción: cuando el Capitán América vaya a ser derrotado, en vez de eso fija su medidor de Vida en 1. Luego descarta esta carta.","f":"\"Un soldado, incluso un supersoldado, sólo es tan fuerte como sus ideales.\" —Steve Rogers"},
  "03009": {"n":"Escudo del Capitán América","t":"Restringida. (Máximo de 2 cartas Restringidas por jugador.)\nEl Capitán América recibe +1 DEF y gana Represalia 1.","f":"\"Este escudo es un símbolo de libertad.\" —Capitán América"},
  "03010": {"n":"Suero de supersoldado","t":"Recurso: agota el Suero de supersoldado → genera un recurso [physical].","f":"\"El suero otorgó superfuerza al Capi. Pero su pasión, su inquebrantable determinación... Steve ya poseía esas cualidades mucho antes de tomar el escudo.\" —Sharon Carter"},
  "03011": {"n":"Halcón","t":"Respuesta: después de que el Halcón entre en juego, mira las 3 primeras cartas del mazo de Encuentros. Por cada carta de Perfidia que mires de este modo, quita 1 de Amenaza de un Plan."},
  "03012": {"n":"Ojo de Halcón","t":"Ojo de Halcón entra en juego con 4 contadores de Flechas.\nRespuesta: después de que entre en juego un Esbirro, quítale 1 contador de Flechas a Ojo de Halcón → inflige 2 de Daño a ese Esbirro."},
  "03013": {"n":"Chica Ardilla","t":"Respuesta: después de que la Chica Ardilla entre en juego, inflige 1 de Daño a cada enemigo.","f":"¡Venga ardillitas, vamos a por él!"},
  "03014": {"n":"Hombre Maravilla","t":"[star] Como coste adicional para que el Hombre Maravilla ataque, debes descartar una carta de tu mano.","f":"¡Es la hora de saldar cuentas!"},
  "03015": {"n":"¡Vengadores, reuníos!","t":"Máximo de 1 por ronda.\nAcción de Héroe: prepara todos los personajes VENGADOR que controles. Hasta el final de la fase, cada personaje VENGADOR que esté en juego recibe +1 INT y +1 ATQ."},
  "03016": {"n":"Hacer la llamada","t":"Acción: paga el coste impreso de un Aliado que esté en la pila de descartes de cualquier jugador → pon en juego ese Aliado controlado por ti.","f":"\"¡Código rojo! ¡Todo el mundo a sus puestos!\" —María Hill"},
  "03017": {"n":"Superioridad numérica","t":"Acción: agota cualquier número de Aliados que controles → roba 1 carta por cada Aliado agotado de este modo.","f":"\"Menos mal que he venido con unos amigos.\" —Capitán América"},
  "03018": {"n":"El poder del liderazgo","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta de Liderazgo (azul)."},
  "03019": {"t":"Respuesta: después de que empiece tu turno, coloca 1 contador de Tiempo sobre el Quinjet.\nAcción: pon en juego desde tu mano un Aliado VENGADOR cuyo coste impreso sea igual o inferior al número de contadores de Tiempo que haya sobre el Quinjet. Luego descarta el Quinjet."},
  "03020": {"n":"Pájaro Burlón","t":"Respuesta: después de que Pájaro Burlón entre en juego, aturde a un enemigo.","f":"\"¡¿Llamas a eso 'ciencia'?!\""},
  "03021": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "03022": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "03023": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "03024": {"n":"Torre de los Vengadores","t":"Si todos tus Aliados tienen el rasgo VENGADOR, tu límite de Aliados se incrementa en 1.\nAcción: agota la Torre de los Vengadores → reduce en 1 el coste del siguiente Aliado VENGADOR que se juegue en esta fase."},
  "03025": {"n":"Vengador honorario","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Vengador.\nVincula esta carta a un personaje amigo.\nEl personaje vinculado recibe +1 de Vida y gana el rasgo VENGADOR."},
  "03026": {"n":"El hombre fuera del tiempo","t":"Dale esta carta al jugador que lleva a Steve Rogers.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n• Agota a Steve Rogers → retira del juego El hombre fuera del tiempo.\n• Descarta la mitad de las cartas de tu mano (redondeando hacia abajo). Descarta esta Obligación."},
  "03027": {"n":"Escuadrón de la muerte","t":"Cuando se muestre esta carta: siguiendo el orden de jugadores, cada jugador descarta la primera carta del mazo de Encuentros y sufre 1 de Daño por cada icono de Aumento que se descarte de este modo.","f":"El Barón Zemo irrumpe en la ciudad al frente de un destacamento de Hydra para dar caza a los Vengadores."},
  "03028": {"n":"Barón Zemo","t":"Ataque veloz.\nMientras el Barón Zemo esté enfrentado a ti, no puedes intervenir.\n(Esbirro Archienemigo del Capitán América.)","f":"\"Si he de vengar a mi padre, el Capitán América debe morir.\""},
  "03029": {"n":"Soldado de Hydra","t":"Guardia. (Mientras este Esbirro esté enfrentado a ti, no podrás atacar al Villano.)\nCuando se derrote esta carta: reparte una carta de Encuentro al jugador enfrentado."},
  "03030": {"n":"¡Hail Hydra!","t":"Cuando se muestre esta carta: todo Esbirro HYDRA que esté enfrentado a un Héroe ataca a ese Héroe. Cada jugador que no sea atacado de este modo busca un Esbirro Hydra en el mazo y la pila de descartes de Encuentros y lo pone en juego enfrentado a él. Baraja el mazo de Encuentros si se ha buscado en él."},
  "03031": {"n":"Enfurecido","t":"Vincula esta carta a un Aliado. Máximo de 1 por Aliado.\nEl Aliado vinculado recibe +2 ATQ y sufre +1 de Daño derivado después de atacar.","f":"\"¿Debería preocuparme por él?\" —Spiderman"},
  "03032": {"n":"Seguimiento","t":"Vincula esta carta a un Plan. Máximo de 1 por Plan.\nRespuesta: cuando se derrote el Plan vinculado, inflige 4 de Daño a un enemigo."},
  "03033": {"n":"Defensa hábil","t":"Interrupción de Héroe (defensa): cuando tu Héroe defienda contra un ataque, recibe +3 DEF para ese ataque.","f":"\"¿Es que estos tíos nunca se quedan sin munición?\" —Capitán América"},
  "03034": {"n":"Consciencia mejorada","t":"Usos (3 contadores Mentales).\nRecurso de Héroe: agota la Consciencia mejorada y quítale 1 contador Mental → genera un recurso [mental]."},
  "04001a": {"n":"Ojo de Halcón","t":"Desefundado rápido — Acción: agota a Ojo de Halcón → prepara el Arco de Ojo de Halcón","f":"\"Puede que no sea el Vengador más poderoso, pero desde luego soy el que más mola.\""},
  "04001b": {"t":"Arma predilecta — Acción: gasta 1 recurso de cualquier tipo → busca el Arco de Ojo de Halcón en tu mazo y tu pila de descartes y añádelo a tu mano. Baraja tu mazo. (Límite de una vez por fase.)"},
  "04002": {"n":"Arco de Ojo de Halcón","t":"Restringida.\nTu Héroe recibe +1 ATQ y todos tus ataques de FLECHA ganan A distancia."},
  "04003": {"n":"Carcaj de Ojo de Halcón","t":"Puedes jugar Eventos FLECHA vinculados a esta carta como si estuvieran en tu mano.\nAcción de Héroe: agota el Carcaj de Ojo de Halcón → busca un Evento FLECHA entre las 5 primeras cartas de tu mazo y vincúlalo a esta carta boca arriba."},
  "04004": {"n":"Pájaro Burlón","t":"Interrupción: cuando el Villano inicie un ataque contra ti, gasta 1 recurso de cualquier tipo y devuelve a Pájaro Burlón a tu mano → evita todo el Daño de este ataque.","f":"\"¿Eso es todo lo que tienes?\""},
  "04005": {"n":"Flecha sónica","t":"Acción de Héroe (ataque): agota el Arco de Ojo de Halcón → confunde a un enemigo e inflígele 3 de Daño (5 de daño si ya estaba confundido).","f":"¡¡¡IIIIIIIIIIIIIIIIH!!!"},
  "04006": {"n":"Flecha explosiva","t":"Acción de Héroe: agota el Arco de Ojo de Halcón y elige un jugador → inflige 3 de Daño al Villano y a cada Esbirro que esté enfrentado a ese jugador.","f":"\"¿Nunca te han dicho que los ojos te echan chispas cuando te enfadas?\" —Clint Barton"},
  "04007": {"n":"Flecha eléctrica","t":"Acción de Héroe (ataque): agota el Arco de Ojo de Halcón → ature a un enemigo e inflígele 3 de Daño (5 de Daño si ya estaba confundido).","f":"\"¡Hail, Ojo de Halcón!\" —Clint Barton"},
  "04008": {"n":"Flecha con cable","t":"Acción de Héroe (intervención): agota el Arco de Ojo de Halcón → quita 3 de Amenaza de un Plan, ignorando los iconos de Crisis que haya en juego.","f":"\"Es un método estupendo para desplazarse.\" —Clint Barton"},
  "04009": {"n":"Flecha de vibránium","t":"Acción de Héroe (ataque): agota el Arco de Ojo de Halcón → inflige 6 de Daño a un enemigo. Este ataque gana Penetrante."},
  "04010": {"n":"Tirador experto","t":"Recurso: agota Tirador experto → genera un recurso [wild] para un Evento FLECHA.","f":"\"Cuando uno lucha junto a dioses y monstruos, no basta con ser bueno; hay que ser el mejor.\" —Clint Barton"},
  "04011": {"n":"Ojo de Halcón","t":"Acción: agota este Aliado y descarta 1 carta de tu mano → inflige X de Daño a un enemigo, siendo X el número de recursos impresos en esa carta","f":"\"Veis que os estoy apuntando con flechas literales, ¿verdad?\""},
  "04012": {"n":"Caballero Negro","t":"[star] El ataque básico del Caballero Negro gana Penetrante.","f":"\"Mientras la Espada Negra brilla en mi mano, debo luchar… ¡cueste lo que cueste!\""},
  "04013": {"n":"Goliat","t":"Acción: Goliat recibe +4 ATQ hasta el final de la fase. Al final de la fase, descarta a Goliat. (Máximo de una vez por fase.)","f":"\"A veces para ser un caballero hay que sostener la puerta, y el resto del edificio.\""},
  "04014": {"n":"USAgente","t":"Represalia 1.","f":"\"El Capi no es el único soldado que ama a su país.\""},
  "04015": {"n":"Aeromoto","t":"Vincula esta carta a un Aliado VENGADOR. Máximo de 1 por Aliado.\nEl Aliado vinculado gana AÉREO.\nAcción: agota la Aeromoto → prepara al Aliado vinculado."},
  "04016": {"n":"Entrenamiento en equipo","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nCada Aliado que controles recibe +1 de Vida.","f":"\"Normalmente esperamos a que el Capi exclame 'Vengadores, reuníos' y atacamos todos en la misma dirección que él.\" —Clint Barton"},
  "04017": {"n":"Listo para la acción","t":"Acción de Héroe: dale una carta de Estado \"Duro\" a un Aliado que controles.","f":"\"Inténtalo otra vez. Si te atreves.\" —Jessica Drew"},
  "04018": {"n":"Liderar en vanguardia","t":"Acción de Héroe: elige un jugador. Cada personaje controlado por ese jugador recibe +1 INT y +1 ATQ hasta el final de la fase.","f":"\"¡Seguidme todos!\" —Carol Danvers"},
  "04019": {"n":"El poder del liderazgo","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta de Liderazgo (azul)."},
  "04020": {"n":"Máquina de Guerra","t":"Dureza.\nEl ataque básico de Máquina de Guerra gana A distancia."},
  "04021": {"n":"Torre de los Vengadores","t":"Si todos tus Aliados tienen el rasgo VENGADOR, tu límite de Aliados se incrementa en 1.\nAcción: agota la Torre de los Vengadores → reduce en 1 el coste del siguiente Aliado VENGADOR que se juegue en esta fase."},
  "04022": {"n":"Los héroes más poderosos","t":"Acción de Héroe: agota un personaje VENGADOR que controles → prepara otro personaje VENGADOR que controles.","f":"\"Nos unimos para luchar contra aquello que no podríamos solos.\" —Luke Cage"},
  "04023": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "04024": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "04025": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "04026": {"n":"Pasado criminal","t":"Dale esta carta al jugador que lleva a Clint Barton.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n• Agota a Clint Barton → retira del juego Pasado criminal.\n• Descarta del juego el Arco de Ojo de Halcón. Descarta esta Obligación."},
  "04027": {"n":"Fuego Cruzado","t":"Ataque veloz.\nLos ataques de Fuego Cruzado ganan Penetrante.\n[star] Aumento: si este aumento se resuelve durante un ataque, dicho ataque gana Penetrante."},
  "04028": {"n":"En el punto de mira","t":"Cuando se muestre esta carta: el jugador que lleva a Clint Barton busca a Pájaro Burlón en su mano, su mazo, su pila de descartes y su zona de juego, y la coloca boca arriba debajo de esta carta. Cuando se derrote esta etapa del Plan, devuelve Pájaro Burlón a la mano de su propietario."},
  "04029": {"n":"Fusil de Fuego Cruzado","t":"Vincula esta carta a Fuego Cruzado. De no ser así, vincula esta carta al Villano.\n[star] Cuando el enemigo vinculado ataque, ese ataque gana A distancia.\nAcción de Héroe: agota tu Héroe y gasta un recurso [wild] → descarta el Fusil de Fuego Cruzado."},
  "04030": {"n":"Disparo de francotirador","t":"Cuando se muestre esta carta (Alter ego): coloca 3 de Amenaza sobre el Plan principal.\nCuando se muestre esta carta (Héror): inflige 3 de Daño a tu Héroe.","f":"\"Me gusta dejar que corran un poco antes de dispararles.\" —Fuego Cruzado"},
  "04031a": {"n":"Spiderwoman","t":"Agilidad sobrehumana — Interrupción: cuando juegues una carta de Aspecto, Spiderwoman recibe +1 INT, +1 ATQ y +1 DEF hasta el final de la ronda. (Límite de una vez por ronda para cada aspecto.)"},
  "04031b": {"t":"Agente Doble — Elige dos aspectos en vez de uno durante la creación de tu mazo. Debes incluir en tu mazo la misma cantidad de cartas de ambos aspectos.\nAcción: mira la primera carta de cualquier mazo. (Límite de una vez por ronda.)"},
  "04032": {"n":"Capitana Marvel","t":"Respuesta: después de que la Capitana Marvel use un atributo básico, roba 1 carta.","f":"\"Chica, te lo reconozco. Pocos desastres he visto más impresionantes que éste.\""},
  "04033": {"n":"Sutileza","t":"Recurso de Héroe: agota Sutileza → genera un recurso [wild] para una carta de Aspecto."},
  "04034": {"n":"Apartamento de Jessica Drew","t":"Acción de Alter ego: agota el Apartamento de Jessica Drew → busca una carta de Aspecto entre las 5 primeras cartas de tu mazo y añádela a tu mano. Baraja tu mazo."},
  "04035": {"n":"Rayo venenoso","t":"Acción de Héroe (ataque): inflige 5 de Daño a un enemigo.\n(Esta carta es de Spiderwoman y también de Agresividad.)"},
  "04036": {"n":"Feromonas","t":"Acción de Héroe: aturde y confunde a un enemigo.\n(Esta carta es de Spiderwoman y también de Liderazgo.)","f":"\"La próxima vez que vayas a usar ese poder, avisa, ¿vale?\" —Peter Parker"},
  "04037": {"n":"Inmunidad a toxinas","t":"Acción de Héroe: cura 3 de Daño a Spiderwoman y dale una carta de Estado \"Duro\".\n(Esta carta es de Spiderwoman y también de Protección.)"},
  "04038": {"n":"Pasar desapercibida","t":"Acción de Héroe (intervención): quita un total de 3 de Amenaza de entre todos los planes que haya en juego.\n(Esta carta es de Spiderwoman y también de Justicia.)","f":"\"Ahora sólo me queda infiltrarme, hacer de arañita espía…\" —Jessica Drew"},
  "04039": {"n":"Planeo controlado","t":"Acción de Héroe: prepara a Spiderwoman. Gana AÉREO hasta el final de la ronda.","f":"\"Todo el mundo cree que puedo volar. Y no puedo. Pero planear se me da de escándalo.\" —Jessica Drew"},
  "04040": {"n":"Spidergirl","t":"Respuesta: después de que juegues a Spidergirl desde tu mano, aturde y confunde a un Esbirro.","f":"\"¡Vale, panda de pringaos! ¿Quién quiere un pedazo de mí?\""},
  "04041": {"n":"Entrenamiento de combate","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nTu Héroe recibe +1 ATQ.","f":"\"¡Tony! ¡Lo ha vuelto a hacer!\" —Janet Van Dyne"},
  "04042": {"n":"Unidad táctica","t":"Usos (3 contadores de Ataque). (Entra en juego con 3 contadores. Cuando se acaben, descarta esta carta)\nAcción: agota la Unidad táctica y quítale 1 contador de Ataque → inflige 2 de Daño a un enemigo."},
  "04043": {"n":"Aprovechar la ventaja","t":"Acción de Héroe (ataque): inflige 2 de Daño a un enemigo. Si ese enemigo está aturdido o confundido, roba 1 carta.","f":"\"¡Ahora estás en Wakanda!\" —T'Challa"},
  "04044": {"n":"Golpe imparable","t":"Acción de Héroe (ataque): inflige 3 de Daño a un enemigo. Este ataque gana Penetrante."},
  "04045": {"n":"Spiderman","t":"Respuesta: después de que juegues a Spiderman desde tu mano, quita 3[per_hero] de Amenaza de un Plan secundario.","f":"\"En serio, ¿qué tiene Nueva York? ¿Por qué nunca os da por invadir Denver?\""},
  "04046": {"n":"Intuición heroica","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nTu Héroe recibe +1 INT."},
  "04047": {"n":"Investigador sagaz","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nRespuesta de Héroe: después de que se derrote un Plan secundario, agota Investigador sagaz → roba 1 carta."},
  "04048": {"n":"Sala de interrogatorios","t":"Máximo de 1 por jugador.\nRespuesta: después de que derrotes a un Esbirro, agota la Sala de interrogatorios → quita 1 de Amenaza de un Plan.","f":"\"¡Ah, que lo sientes! Pues nada, ahora mismo te quito las esposas y te pido un taxi\" —Misty Knight"},
  "04049": {"n":"Despejar la zona","t":"Acción de Héroe (intervención): quita 2 de Amenaza de un Plan. Si con esto se quita la última ficha de Amenaza de ese Plan, roba 1 carta.","f":"\"No te asustes, pequeña. Piensa en lo celosos que se pondrán los demás niños cuando les cuentes cómo te ha rescatado Iron Man.\" —Tony Stark"},
  "04050": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "04051": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "04052": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "04053": {"n":"Lealtad dudosa","t":"Dale esta carta al jugador que lleva a Jessica Drew.\nPuedes adoptar la identidad de ti Alter ego. Elige una opción:\n• Agota a Jessica Drew → retira del juego Lealtad dudosa.\n• Coloca 3 de Amenaza sobre el Plan principal. Descarta esta Obligación."},
  "04054": {"n":"Víbora","t":"Mientras Víbora esté enfrentada a ti, el tamaño de tu mano se reduce en 1.\n(Esbirro Archienemigo de Spiderwoman.)","f":"\"Es hora de que vuelvas a casa, Jessica.\""},
  "04055": {"n":"La ambición de Víbora","t":"Cuando se muestre esta carta: coloca 1[per_hero] de Amenaza sobre esta carta.","f":"Víbora se ha entregado a Hydra en cuerpo y alma a cambio de la promesa de poder."},
  "04056": {"n":"Tropa de Hydra","t":"Incitar 1. (Cuando se muestre esta carta, coloca 1 de Amenaza sobre el Plan principal.)","f":"\"Teniendo en cuenta qué tipo de personas se unirían a una organización terrorista obsesionada con dominar el mundo, es obvio por qué las tropas de Hydra dejan tanto que desear.\" —Jessica Drew"},
  "04057": {"n":"¡Hail, Hydra!","t":"Cuando se muestre esta carta: todo Esbirro HYDRA que esté enfrentado a un Héroe ataca a ese Héroe. Cada jugador que no sea atacado de este modo busca un Esbirro HYDRA en el mazo y la pila de descartes de Encuentros y lo pone en juego enfrentado a él. Baraja el mazo de Encuentros si se ha buscado en él."},
  "04058": {"n":"Calavera","t":"Mientras Calavera tenga vinculado un Accesorio ARMA, sus ataques ganan Penetrante. (Las cartas de Estado \"Duro\" del objetivo se descartan antes de infligirle Daño.)","f":"\"Me considero un artista. Un auténtico artesano especializado en asesinato, destrucción y terror.\""},
  "04059": {"n":"Calavera","t":"[star] Mientras Calavera tenga vinculado un Accesorio ARMA, sus ataques ganan Penetrante.\nCuando se muestre esta carta: busca la Ametralladora de Calavera en el mazo y la pila de descartes de Encuentros y vincúlala a Calavera. Baraja el mazo de Encuentros."},
  "04060": {"n":"Calavera","t":"[star] Mientras Calavera tenga vinculado un Accesorio ARMA, sus ataques ganan Penetrante.\nCuando se muestre esta carta: muestra la primera carta del mazo de Armas experimentales.","f":"\"Mucho superpoder y mucha fuerza, pero ninguno de ellos tiene mi estilo.\""},
  "04061a": {"n":"Ataque al monte Atenea","t":"Contenido: Calavera (I) y Calavera (II). Conjuntos de Encuentros de Calavera, Armas experimentales y Normal. Tres conjuntos de Encuentros modulares (Asalto de Hydra, Maestro de armas y Legiones de Hydra).\nPreparación: crea el mazo de Armas experimentales y colócalo junto al mazo del Plan principal. (ver página 5 del cuaderno de reglas.)"},
  "04061b": {"n":"Ataque al monte Atenea","t":"Cuando se muestre esta carta: muestra la primera carta del mazo de Armas experimentales.","f":"Calavera lidera un contingente de soldados de Hydra en una ofensiva directa contra las instalaciones del Proyecto Pegaso en las montañas de Adirondack."},
  "04062a": {"n":"La piedra del infinito","f":"En el interior del complejo del Proyecto Pegaso, los agentes de S.H.I.E.L.D. libran una batalla desesperada para evitar que Hydra se apodere de la Gema de la Realidad."},
  "04062b": {"n":"La piedra del infinito","t":"Cuando se muestre esta carta: muestra la primera carta del mazo de Armas experimentales."},
  "04063a": {"n":"La huida","f":"Hydra se ha apoderado de la piedra del infinito y Calavera ha ordenado la retirada. ¡Tenéis que detenerlos antes de que se escapen!"},
  "04063b": {"n":"La huida","t":"Cuando se muestre esta carta: muestra la primera carta del mazo de Armas experimentales.\nSi se completa esta etapa, los jugadores pierden la partida."},
  "04064": {"n":"Ametralladora de Calavera","t":"Vincula esta carta a Calavera. Usos (2[per_hero] contadores de Munición).\n[star] Interrupción obligada: cuando Calavera te ataque, quita 1 contador de Munición de esta carta y descarta la primera carta del mazo de Encuentros → sufres tanto Daño indirecto como el número de iconos de Aumento que haya en la carta descartada."},
  "04065": {"n":"Armadura de Calavera","t":"Vincula esta carta a Calavera.\nInterrupción obligada: cuando Calavera vaya a sufrir cualquier cantidad de Daño, en vez de eso coloca ese Daño sobre esta carta. Si hay al menos 5 de Daño aquí, descarta la Armadura de Calavera."},
  "04066": {"n":"Terrorista de Hydra","t":"Cuando se muestre esta carta: elige entre sufrir 2 de Daño o colocar 1 de Amenaza sobre el Plan principal.","f":"\"Sé que si cortas una cabeza, otras dos ocupan su lugar. Pero ¿y si explota?\" —Hulka"},
  "04067": {"n":"Fuego automático","t":"Cuando se muestre esta carta (Alter ego): Oleada.\nCuando se muestre esta carta (Héroe): descarta X cartas de la parte superior del mazo de Encuentros, siendo X el ATQ de Calavera. Sufres 1 de Daño indirecto por cada icono de Aumento que se haya descartado de este modo."},
  "04068": {"n":"Duro de pelar","t":"Cuando se muestre esta carta: dale al Villano una carta de Estado \"Duro\". Si no es posible, en vez de eso cúrale 3 de Daño.\n[star] Aumento: dale al Villano una carta de Estado \"Duro\". Si no es posible, en vez de eso cúrale 3 de Daño."},
  "04069": {"n":"Saquear el arsenal","t":"Incitar 1. (Cuando se muestre esta carta, coloca 1 de Amenaza sobre el Plan principal.)\nCuando se muestre esta carta: descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Accesorio ARMA. Muestra esa carta."},
  "04070": {"n":"El ataque de Calavera","t":"Cuando se derrote esta carta: Calavera se activa contra el jugador que haya derrotado este Plan.","f":"Calavera es un asesino desalmado, pero no es ningún psicópata. Su asalto al Proyecto Pegaso es despiadado y efectivo."},
  "04071": {"n":"Personal acorralado","t":"Cuando se muestre esta carta: descarta 1[per_hero] cartas de la parte superior del mazo de Encuentros. Coloca 1 de Amenaza adicional sobre esta carta por cada icono de Aumento que haya en las cartas que se descartasen de este modo.","f":"Hydra ha arrinconado a los empleados del Proyecto Pegaso para utilizarlos como rehenes."},
  "04072": {"n":"Fusil láser","t":"Vincula esta carta al Villano.\n[star] Interrupción obligada: cuando el Villano vinculado ataque, ese ataque gana A distancia.\nAcción de Héroe: gasta recursos [energy][physical] → descarta esta carta."},
  "04073": {"n":"Escudo de energía","t":"Vincula esta carta al Villano.\nEl Villano vinculado gana Represalia 1.\nAcción de Héroe: gasta recursos [energy][mental] → descarta esta carta.","f":"\"Nunca convencerás al Capi de que un escudo de energía es mejor que su viejo disco arrojadizo.\" —Carol Danvers"},
  "04074": {"n":"Servopuños","t":"Vincula esta carta al Villano.\n[star] Respuesta obligada: después de que el Villano vinculado ataque y te inflija Daño, descarta 1 carta de tu mano.\nAcción de Héroe: gasta recursos [mental][physical] → descarta esta carta."},
  "04075": {"n":"Exoarmadura","t":"Vincula esta carta al Villano.\nAcción de Héroe: gasta recursos [energy][mental][physical] → descarta esta carta.","f":"\"Jamás debí compartir mi tecnologóa con S.H.I.E.L.D.\" —Tony Stark"},
  "04076": {"n":"Hombre Absorbente","t":"El Hombre Absorbente gana el rasgo de todo Entorno que haya en juego.","f":"\"¿Sabes que una vez le di una paliza a Thor? Imagínatelo: 'Aplastador' Creel, triunfante, con el Dios del Trueno tirado a sus pies. ¿Y te crees que tú me asustas?\""},
  "04077": {"n":"Hombre Absorbente","t":"El Hombre Absorbente gana el rasgo de todo Entorno que haya en juego.\nCuando se muestre esta carta: si está en juego Poder de absorción superior, dale 1 carta de Encuentro a cada jugador. De no ser así, busca Poder de absorción superior en el mazo y la pila de descartes de Encuentros y muéstralo. Baraja el mazo de Encuentros si se ha buscado en él de este modo."},
  "04078": {"n":"Hombre Absorbente","t":"El Hombre Absorbente gana el rasgo de todo Entorno que haya en juego.\n[star] Respuesta obligada: después de que el Hombre Absorbente se active contra ti, si tiene los rasgos:\n• HIELO o PIEDRA, coloca 1 de Amenaza sobre el Plan principal.\n• METAL o MADERA, sufres 1 de Daño indirecto."},
  "04079a": {"n":"Por aquí no pasa nadie","t":"Contenido: Hombre Absorbente (I) y Hombre Absorbente (II). Conjuntos de Encuentros del Hombre Absorbente y Normal. Un conjunto de Encuentros modular (Patrulla de Hydra).\nPreparación: descarta cartas del mazo de Encuentros hasta que se descarte un Entorno. Pon en juego esa carta y baraja el mazo de Encuentros junto con su pila de descartes."},
  "04079b": {"n":"Por aquí no pasa nadie","t":"[star] Respuesta obligada: después de resolver el paso uno de la fase del Villano, coloca 1 contador de Demora sobre esta carta.\nInterrupción obligada: cuando entre en juego un Entorno, descarta todos los demás Entornos que haya en juego.\nSi se completa esta etapa, los jugadores pierden la partida."},
  "04080": {"n":"Bosque frondoso","t":"Oleada.\nRespuesta obligada: después de que el Hombre Absorbente realice un ataque no defendido contra ti, sufres 1 de Daño indirecto (2 de Daño indirecto si hay al menos 5 contadores de Demora sobre el Plan principal).\n[star] Aumento: pon en juego esta carta."},
  "04081": {"n":"Colina nevada","t":"Oleada.\nRespuesta obligada: después de que el Hombre Absorbente realice un ataque no defendido contra ti, coloca 1 de Amenaza sobre el Plan principal (2 de Amenaza si hay al menos 5 contadores de Demora sobre el Plan principal).\n[star] Aumento: pon en juego esta carta."},
  "04082": {"n":"Promontorio rocoso","t":"Oleada.\nRespuesta obligada: después de que el Hombre Absorbente realice un ataque no defendido contra ti, cúrale 1 de Daño (2 de Daño si hay al menos 5 contadores de Demora sobre el Plan principal).\n[star] Aumento: pon en juego esta carta."},
  "04083": {"n":"Complejo abandonado","t":"Oleada.\nRespuesta obligada: después de que el Hombre Absorbente realice un ataque no defendido contra ti, descarta 1 icono de recurso de tu mano (2 iconos de recurso si hay al menos 5 contadores de Demora sobre el Plan principal).\n[star] Aumento: pon en juego esta carta."},
  "04084": {"n":"Bola y cadena","t":"Vincula esta carta al Hombre Absorbente.\nAcción de Héroe: gasta un recurso [physical] → añade esta carta al mazo de Encuentros y barájalo.\n[star] Aumento: muestra esta carta."},
  "04085": {"n":"Tácticas dilatorias","t":"Cuando se muestre esta carta: coloca 1 de Amenaza sobre el Plan principal por cada 2 contadores de Demora que haya sobre el Plan principal. Si no se coloca Amenaza de este modo, esta carta gana Oleada.\n[star] Aumento: si hay al menos 5 contadores de Demora sobre el Plan principal, sufres 1 de Daño indirecto."},
  "04086": {"n":"Barrido pétreo","t":"Cuando se muestre esta carta (Alter ego): el Hombre Absorbente ejecuta el Plan. Si el Hombre Absorbente posee el rasgo PIEDRA, recibe +1 PLA para esta activación.\nCuando se muestre esta carta (Héroe): el Hombre Absorbente te ataca. Si el Hombre Absorbente posee el rasgo PIEDRA, recibe +1 ATQ para esta activación."},
  "04087": {"n":"Patada de acero","t":"Cuando se muestre esta carta (Alter ego): coloca 2 de Amenaza sobre el Plan principal (3 de Amenaza si el Hombre Absorbente posee el rasgo Metal.)\nCuando se muestre esta carta (Héroe): sufres 3 de Daño indirecto (4 de Daño indirecto si el Hombre Absorbente posee el rasgo Metal.)"},
  "04088": {"n":"Espinas perforantes","t":"Cuando se muestre esta carta: descarta 1 carta de tu mano al azar. Si el Hombre Absorbente posee el rasgo MADERA, descarta 1 carta que controles.\n[star] Aumento: si el Hombre Absorbente posee los rasgos PIEDRA o MADERA, quedas aturdido."},
  "04089": {"n":"Duplicación omnimórfica","t":"Cuando se muestre esta carta: si el Hombre Absorbente posee el rasgo:\n- HIELO, agota tu carta de Superhéroe.\n- METAL, dale al Hombre Absorbente una carta de Estado \"Duro\" y cúrale 1 de Daño.\n- PIEDRA, dale al Hombre Absorbente 1 carta de aumento boca abajo.\n- MADERA, descarta 1 carta de tu mano al azar."},
  "04090": {"n":"Presa gélida","t":"Cuando se muestre esta carta: quedas aturdido. Si el Hombre Absorbente posee el rasgo HIELO, sufres 2 de Daño indirecto.\n[star] Aumento: si el Hombre Absorbente posee los rasgos HIELO o METAL, dale una carta de Estado \"Duro\"."},
  "04091": {"n":"¡Avalancha!","t":"Cuando se muestre esta carta: cada jugador debe elegir entre gastar un recurso [energy] o bien sufrir 2 de Daño indirecto (3 de Daño indirecto si hay al menos 5 contadores de Demora sobre el Plan principal.)"},
  "04092": {"n":"Poder de absorción superior","t":"El Hombre Absorbente gana los rasgos HIELO, METAL, PIEDRA, y MADERA.\n[star] Aumento: muestra esta carta.","f":"Creel posee la habilidad de absorber las propiedades de varios materiales al mismo tiempo, pero esto le exige una intensa concentración."},
  "04093": {"n":"Supervisor","t":"Respuesta obligada: después de que un jugador adopte su identidad de Héroe, ese jugador descarta la primera carta del mazo de Encuentros y sufre tanto Daño como el número de iconos de Aumento que haya en esa carta.","f":"\"No hay nada de lo que haces que yo no pueda hacer mejor que tú.\""},
  "04094": {"n":"Supervisor","t":"Cuando se muestre esta carta: dale una carta de Encuentro a cada jugador.\nRespuesta obligada: después de que un jugador adopte su identidad de Héroe, ese jugador descarta la primera carta del mazo de Encuentros y sufre tanto Daño como el número de iconos de Aumento que haya en esa carta."},
  "04095": {"n":"Supervisor","t":"Cuando se muestre esta carta: dale una carta de Encuentro a cada jugador.\nRespuesta obligada: después de que un jugador adopte su identidad de Héroe, ese jugador descarta la primera carta del mazo de Encuentros y sufre tanto Daño como el número de iconos de Aumento que haya en esa carta."},
  "04096a": {"n":"A la caza del héroe","t":"Contenido: Supervisor (I) y Supervisor (II). Conjuntos de Encuentros del Supervisor, Patrulla de Hydra y Normal. Un conjunto de Encuentros modular (Maestro de armas).\nPreparación: aparta todos los Aliados CAUTIVO a un lado, fuera del juego. Busca la carta Patrulla de Hydra en el mazo de Encuentros y ponla en juego. Baraja el mazo de Encuentros."},
  "04096b": {"n":"A la caza del héroe","t":"[star] Respuesta obligada: después de resolver el paso uno de la fase del Villano, cada jugador que tenga adoptada su identidad de Héroe debe elegir entre colocar 1 de Amenaza sobre esta carta o bien sufrir 1 de Daño.\nSi se completa esta etapa, los jugadores pierden la partida.","f":"El infame Supervisor ha sido nombrado jefe de policía en el nuevo régimen de Hydra. Su principal prioridad consiste en dar caza a los héroes proscritos."},
  "04097": {"n":"Caballero Luna","t":"Respuesta: después de que juegues al Caballero Luna desde tu mano, gasta un recurso [wild] → roba 2 cartas.","f":"\"Hydra se hizo con el poder tan deprisa que aquello no parecía real.\""},
  "04098": {"t":"Respuesta: después de que juegues a Shang-Chi desde tu mano, gasta un recurso [energy] → aturde a un enemigo.","f":"\"Un equipo de asalto de Hydra irrumpió en mi casa mientras meditaba. Los eché a patadas, pero fuera había otras dos unidades esperándome.\""},
  "04099": {"n":"Tigre Blanco","t":"Respuesta: después de que juegues a Tigre Blanco desde tu mano, gasta un recurso [mental] → quita 3 de Amenaza de un Plan.","f":"\"Cuando Hydra subió al poder e ilegalizó los superhéroes, un vecino me delató al nuevo jefe de policía.\""},
  "04100": {"t":"Respuesta: después de que juegues a Elektra desde tu mano, gasta un recurso [physical] → inflige 3 de Daño a un enemigo.","f":"\"Me atraparon intentando ayudar a unos civiles a escapar de una patrulla de Hydra. Resultó que los civiles eran agentes de paisano en una operación encubierta.\""},
  "04101": {"n":"Cazador de Hydra","t":"[star] Los ataques del Cazador de Hydra ganan A distancia y Penetrante.\n[star] Aumento: si tienes adoptada tu identidad de Héroe, sufres 1 de Daño. De no ser así, coloca 1 de Amenaza sobre el Plan principal."},
  "04102": {"n":"Espada del Supervisor","t":"Vincula esta carta al Supervisor.\n[star] Los ataques del Supervisor ganan Penetrante.\nAcción de Héroe: agota tu Héroe y gasta recursos [mental][physical] → descarta esta carta."},
  "04103": {"n":"Escudo del Supervisor","t":"Vincula esta carta al Supervisor.\nEl Supervisor gana Represalia 1.\nAcción de Héroe: agota tu Héroe y gasta recursos [mental][physical] → descarta esta carta.","f":"\"Aprendí este movimiento del capitán América.\" —Supervisor"},
  "04104": {"n":"Reflejos fotográficos","t":"Vincula esta carta al Supervisor.\nInterrupción obligada: cuando un jugador ataque al Supervisor, se evita todo el Daño que vaya a infligir al Supervisor y se inflige esa misma cantidad de Daño a la carta de Superhéroe de ese jugador. Luego descarta Reflejos fotográficos. (Máximo de una vez por ataque.)"},
  "04105": {"n":"Imitación","t":"Cuando se muestre esta carta (Alter ego): descarta las 5 primeras cartas de tu mazo. Si se ha descartado de este modo una carta con INTERVENCIÓN, el Supervisor ejecuta el Plan.\nCuando se muestre esta carta (Héroe): descarta las 5 primeras cartas de tu mazo. Si se ha descartado de este modo una carta con ATAQUE, el Supervisor te ataca."},
  "04106": {"n":"Perseguidos por Hydra","t":"Incitar 1. (Cuando se muestre esta carta, coloca 1 de Amenaza sobre el Plan principal.)\nCuando se muestre esta carta: cada jugador que tenga adoptada su identidad de Héroe sufre 1 de Daño y descarta 1 carta de su mano al azar.","f":"\"Es mal momento para ser héroe.\" —Bucky Barnes"},
  "04107": {"n":"Capturado por Hydra","t":"Cuando se muestre esta carta: coloca boca abajo y debajo de este Plan 1 Aliado CAUTIVO al azar que esté apartado. Cuando se derrote este Plan, el jugador que lo haya derrotado añade ese Aliado a su mano y retira del juego este Plan."},
  "04108": {"n":"Campamento de instrucción del Supervisor","t":"Respuesta obligada: después de que entre en juego un Esbirro, dale una carta de Estado \"Duro\".","f":"El Supervisor únicamente acepta a los mejores reclutas en su cuerpo de policía. Todo soldado de Hydra que desea alistarse debe sobrevivir primero a su campo de instrucción."},
  "04109": {"t":"Represalia 1.","f":"\"¡Mi programa de mutados transformará estas patéticas criaturas en soldados de choque de élite para Hydra!\""},
  "04110": {"t":"Represalia 1.\nCuando se muestre esta carta: busca el Plan secundario \"Sujetos de prueba\" en el mazo y la pila de descartes de Encuentros y muéstralo. Baraja el mazo de Encuentros."},
  "04111": {"t":"Represalia 1.\nCuando se muestre esta carta: cada jugador busca un Esbirro en el mazo y la pila de descartes de Encuentros y lo muestra. Baraja el mazo de Encuentros."},
  "04112a": {"n":"La isla del doctor Zola","t":"Contenido: Zola (I) y Zola (II). Conjuntos de Encuentros de Zola y Normal. Un conjunto de Encuentros modular (Civiles en peligro).\nPreparación: busca la carta Prisión de Hydra en el mazo de Encuentros y muéstrala. Cada jugador busca en el mazo de Encuentros una copia del Biosiervo definitivo y la pone en juego enfrentada a él. Baraja el mazo de Encuentros."},
  "04112b": {"n":"La isla del doctor Zola","t":"[star] Respuesta obligada: después de resolver el paso uno de la fase del Villano, coloca 1 contador de Prueba sobre esta carta. Luego, si hay al menos 3 contadores de Prueba sobre esta carta, descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Esbirro. Pon en juego ese Esbirro enfrentado al jugador inicial y quita 3 contadores de Prueba de este Plan."},
  "04113a": {"n":"El científico loco","t":"Cuando se muestre esta carta: cada jugador busca un Esbirro en el mazo y la pila de descartes de Encuentros y lo muestra. Baraja el mazo de Encuentros.","f":"Los mutados de Zola os atacan con obediencia ciega y furia salvaje. ¡De vosotros depende poner fin a esta pesadilla antes de que el científico loco la desate sobre el mundo!"},
  "04113b": {"n":"El científico loco","t":"[star] Respuesta obligada: después de resolver el paso uno de la fase del Villano, coloca 1 contador de Prueba sobre esta carta. Luego, si hay al menos 3 contadores de Prueba sobre esta carta, descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Esbirro. Pon en juego ese Esbirro enfrentado al jugador inicial y quita 3 contadores de Prueba de este Plan..\nSi se completa esta etapa, los jugadores pierden la partida."},
  "04114": {"n":"Biosiervo definitivo","t":"Dureza.\n[star] El Biosiervo definitivo recibe +1 ATQ por cada Accesorio que tenga vinculado.\n[star] Aumento: dale al Villano una carta de Estado \"Duro\"."},
  "04115": {"n":"Mutado de Zola","t":"Cuando se muestre esta carta: descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Accesorio TECNOLOGÍA. Vincula esta carta al Mutado de Zola.\n[star] Aumento: añade el Mutado de Zola al mazo de Encuentros y barájalo."},
  "04116": {"n":"Mutado rabioso","t":"Ataque veloz.\n[star] Aumento: coloca 1 contador de Prueba sobre el Plan principal. Por cada contador de Prueba que haya sobre el Plan principal, Zola recibe +1 PLA y +1 ATQ para esta activación."},
  "04117": {"n":"Programación defensiva","t":"Vincula esta carta al Esbirro que tenga más Vida restante y que no tenga ya vinculada otra copia de Programación defensiva. Si no puedes hacerlo, esta carta gana Oleada.\nEl Esbirro vinculado recibe +2 de Vida y gana Guardia."},
  "04118": {"n":"Inhibidores del dolor","t":"Vincula esta carta al Esbirro que tenga más Vida restante y que no tenga ya vinculada otra copia de Inhibidores del dolor. Si no puedes hacerlo, esta carta gana Oleada.\nEl Esbirro vinculado recibe +2 de Vida y gana Represalia 1."},
  "04119": {"n":"Implantes neurológicos","t":"Vincula esta carta al Esbirro que tenga más Vida restante y que no tenga ya vinculada otra copia de Implantes neurológicos. Si no puedes hacerlo, esta carta gana Oleada.\nEl Esbirro vinculado recibe +2 de Vida."},
  "04120": {"n":"Rayo mental","t":"Cuando se muestre esta carta (Alter ego): Zola ejecuta el Plan. Quedas confundido.\nCuando se muestre esta carta (Héroe): Zola te ataca. Quedas aturdido.","f":"\"¿Creías que Zola estaba indefenso? ¡Necio arrogante!\" —Arnim Zola"},
  "04121": {"n":"Mejoras tecnológicas","t":"Incitar 1.\nCuando se muestre esta carta: coloca 1 contador de Prueba sobre el Plan principal.\n[star] Aumento: coloca 1 contador de Prueba sobre el Plan principal."},
  "04122": {"n":"Prisión de Hydra","t":"Cuando se muestre esta carta: cada jugador busca en su mano, su mazo y su pila de descartes un Aliado de un Héroe específico y lo coloca boca abajo debajo de este Plan. Coloca X de Amenaza sobre este Plan, siendo X el coste total de todos los Aliados que tenga debajo. Cada jugador baraja su mazo.\nCuando se derrote esta carta: este Plan se retira del juego y todos los Aliados que tenga debajo se devuelven a las manos de sus propietarios."},
  "04123": {"n":"Sujetos de prueba","t":"Cuando se derrote esta carta: el jugador inicial descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Esbirro. Muestra ese Esbirro.","f":"Es un destino peor que la muerte."},
  "04124": {"n":"Los experimentos de Zola","t":"Respuesta obligada: después de que entre en juego un Esbirro, vincúlale el primer Accesorio TECNOLOGÍA que haya en la pila de descartes del mazo de Encuentros.","f":"El científico loco nunca se cansa de experimentar con sus víctimas."},
  "04125": {"n":"Cráneo Rojo","t":"[star] Cráneo Rojo recibe +1 ATQ por cada Plan secundario que haya en juego.","f":"\"¡La liberta es tan sólo para los que gobiernan! ¡Todos los demás deben ser esclavos!\""},
  "04126": {"n":"Cráneo Rojo","t":"[star] Cráneo Rojo recibe +1 ATQ por cada Plan secundario que haya en juego.\nCuando se muestre esta carta: dale una carta de Encuentro a cada jugador.","f":"\"¡Nadie se interpondrá en mis planes!\""},
  "04127": {"n":"Cráneo Rojo","t":"[star] Cráneo Rojo recibe +1 ATQ por cada Plan secundario que haya en juego.\nCuando se muestre esta carta: dale una carta de Encuentro a cada jugador.","f":"\"¡El mundo entero se postrará ante Cráneo Rojo!\""},
  "04128a": {"n":"La tiranía de Cráneo Rojo","t":"Contenido: Cráneo Rojo (I) y Cráneo Rojo (II). Conjuntos de Encuentros de Cráneo Rojo y Normal. Dos conjuntos de Encuentros modulares (Asalto de Hydra y Patrulla de Hydra).\nPreparación: pon en juego La Casa Roja. Añade todos los demás Planes secundarios al mazo de Planes secundarios, barájalo y colócalo junto al mazo de Encuentros (ver cuaderno de reglas).\nAparta El Durmiente a un lado, fuera del juego."},
  "04128b": {"n":"La tiranía de Cráneo Rojo","t":"[star] Respuesta obligada: después de resolver el paso uno de la fase del Villano, muestra la primera carta del mazo de Planes secundarios y ponla en juego.","f":"Cráneo Rojo planea conquistar el mundo con el poder de la Gema de la Realidad. El villano emplea sus excepcionales dotes de estratega para manteneros ocupados mientras él pone en marcha sus planes."},
  "04129a": {"n":"El nuevo mundo de Hydra","t":"Cuando se muestre esta carta: muestra la primera carta del mazo de Planes secundarios y ponla en juego.","f":"Cráneo Rojo está un paso más cerca de dominar el poder de la piedra del infinito en toda su plenitud. Tenéis que detenerlo antes de que lo consiga y moldee la realidad a su maligna voluntad."},
  "04129b": {"n":"El nuevo mundo de Hydra","t":"[star] Respuesta obligada: después de resolver el paso uno de la fase del Villano, muestra la primera carta del mazo de Planes secundarios y ponla en juego.\nSi se completa esta etapa, los jugadores pierden la partida."},
  "04130": {"n":"El Durmiente","t":"Guardia. Represalia 1. Dureza.\nCuando se muestre esta carta: El Durmiente se enfrenta al jugador inicial.\nCuando se derrote esta carta: retira del juego El Durmiente."},
  "04131": {"n":"Soldado de Hydra con exoarmadura","t":"Dureza.\n[star] Aumento: dale al Villano una carta de Estado \"Duro\" y otra carta de aumento.","f":"\"Cuidado, equipo. ¡Estos tíos pegan duro!\" —Capitán América"},
  "04132": {"n":"Luger de Cráneo Rojo","t":"Vincula esta carta a Cráneo Rojo.\n[star] Los ataques de Cráneo Rojo ganan A distancia y Penetrante.\nAcción de Héroe: gasta recursos [energy][mental][physical] → descarta esta carta.\n[star] Aumento: vincula esta carta a Cráneo Rojo."},
  "04133": {"n":"Derechazo de Cráneo Rojo","t":"Vincula esta carta a Cráneo Rojo.\nCráneo Rojo gana Represalia 1.\nAcción de Héroe: gasta recursos [energy][mental][physical] → descarta esta carta.","f":"\"¡Soy superior a ti en todos los aspectos!\" —Cráneo Rojo"},
  "04134": {"n":"Estratega consumado","t":"Vincula esta carta a Cráneo Rojo.\n[star] Interrupción obligada: cuando Cráneo Rojo se active, dale una carta de aumento adicional por cada Plan secundario que haya en juego. Luego descarta esta carta. (Máximo una vez por activación.)","f":"\"En el ajedrez, la única pieza que realmente importa es el rey, y ése soy yo.\" —Cráneo Rojo"},
  "04135": {"n":"Realidad distorsionada","t":"Incitar 1.\nVincula esta carta a un Plan secundario.\nRespuesta obligada: cuando el Plan secundario vinculado sea derrotado, dale una carta de Encuentro al jugador inicial.","f":"La piedra del infinito otorga a Cráneo Rojo el poder de moldear la realidad a su antojo."},
  "04136": {"n":"Enemigo acérrimo","t":"Cuando se muestre esta carta: agota un personaje que controles por cada Plan secundario que haya en juego.\n[star] Aumento: agota un personaje que controles.","f":"\"¡Éste será tu final, Herr Capitán!\" —Cráneo Rojo"},
  "04137": {"n":"Difundir mentiras","t":"Cuando se muestre esta carta: coloca 2 de Amenaza sobre cada Plan que haya en juego.\n[star] Aumento: dale a Cráneo Rojo una carta de estado \"Duro\".","f":"\"¡Gracias a mi incomparable astucia, la supremacía de Hydra será absoluta!\" —Cráneo Rojo"},
  "04138": {"n":"Poder infinito","t":"Cuando se muestre esta carta (Alter ego): dale a Cráneo Rojo una carta de Estado \"Duro\". Cráneo Rojo ejecuta el Plan.\nCuando se muestre esta carta (Héroe): dale a Cráneo Rojo una carta de Estado \"Duro\". Cráneo Rojo te ataca."},
  "04139": {"n":"La Casa Roja","t":"Cráneo Rojo no puede sufrir Daño.\nInterrupción: cuando un personaje intervenga contra este Plan secundario, puede usar su ATQ en vez de su INT.","f":"Cráneo Rojo ha erigido su fortaleza sobre la Casa Blanca como símbolo de la supremacía de Hydra sobre los Estados Unidos."},
  "04140": {"n":"El Durmiente ha despertado","t":"Este Plan no puede abandonar el juego mientras El Durmiente esté en juego.\nCuando se muestre esta carta: pon en juego El Durmiente enfrentado al jugador inicial. Cuando El Durmiente sea derrotado, retira esta carta del juego.","f":"El Durmiente ha despertado y se alza de las profundidades del río Potomac para responder a la llamada de Cráneo Rojo."},
  "04141": {"n":"Campos de concentración","t":"Cuando se derrote esta carta: el jugador que haya derrotado este Plan busca un Aliado en su mazo y su pila de descartes, lo pone en juego y luego baraja su mazo.","f":"Bajo el régimen de Hydra, familias enteras son separadas y encarceladas sin un juicio justo."},
  "04142": {"n":"Censurar el pasado","t":"Cuando se derrote esta carta: cada jugador elige hasta 3 cartas de su pila de descartes, las añade a su mazo y lo baraja.","f":"Hydra controla todos los medios de comunicación y recurre a la propaganda para enfrentar a la opinión pública contra los antiguos héroes."},
  "04143": {"n":"Refuerzos de Hydra","t":"Cuando se derrote esta carta: el jugador que haya derrotado este Plan descarta un Esbirro que no sea de ÉLITE.","f":"Hydra compensa la falta de aptitudes de sus tropas con una ingente superioridad numérica."},
  "04144": {"n":"Caos generalizado","t":"Cuando se muestre esta carta: cada jugador descarta las 5 primeras cartas de su mazo y coloca 1 de Amenaza sobre esta carta por cada tipo distinto de icono de recurso ([energy],[mental],[physical], o [wild]) que haya descartado de este modo.","f":"Cráneo Rojo provoca catástrofes por todo el país para mantener ocupados a sus enemigos."},
  "04145": {"n":"Soldado de Hydra con lanzallamas","t":"[star] Respuesta obligada: después de que el Soldado de Hydra con lanzallamas efectúe un ataque no defendido contra ti, descarta un Apoyo que controles.\n[star] Aumento: si esta carta se resuelve durante un ataque no defendido, descarta un Apoyo que controles."},
  "04146": {"n":"Soldado colador de Hydra","t":"Ataque veloz.\n[star] Aumento: si tienes adoptada tu identidad de Héroe, el Villano te ataca después de esta activación. No des al Villano cartas de aumento para ese ataque."},
  "04147": {"n":"¡Hail, Hydra!","t":"Cuando se muestre esta carta: todo Esbirro Hydra que esté enfrentado a un Héroe ataca a ese Héroe. Cada jugador que no sea atacado de este modo busca un Esbirro Hydra en el mazo y la pila de descartes de Encuentros y lo pone en juego enfrentado a él. Baraja el mazo de Encuentros si se ha buscado en él."},
  "04148": {"n":"Cuchillo de combate","t":"Vincula esta carta al Villano.\n[star] Los ataques del Villano vinculado ganan Penetrante.\nAcción de Héroe: gasta recursos [mental][physical] → descarta esta carta."},
  "04149": {"n":"Arma corta de Hydra","t":"Vincula esta carta al Villano.\n[star] Interrupción obligada: cuando el Villano vinculado ataque, ese ataque gana A distancia.\nAcción de Héroe: gasta recursos [mental][physical] → descarta esta carta."},
  "04150": {"n":"Maestro de armas","t":"Cuando se muestre esta carta (Alter ego): el Villano ejecuta el Plan. Si tiene un Accesorio ARMA, esta carta gana Oleada.\nCuando se muestre esta carta (Héroe): el Villano te ataca. Si tiene un Accesorio ARMA, esta carta gana Oleada."},
  "04151": {"n":"Granada de conmoción","t":"Cuando se muestre esta carta (Alter ego): quedas confundido. Coloca 1 de Amenaza sobre el Plan principal (2 de Amenaza si ya estabas confundido).\nCuando se muestre esta carta (Héroe): quedas aturdido. Inflige 1 de Daño a tu Héroe (2 de Daño si ya estabas aturdido)."},
  "04152": {"n":"Tropa de Hydra","t":"Incitar 1. (Cuando se muestre esta carta, coloca 1 de Amenaza sobre el Plan principal.)","f":"\"Teniendo en cuenta qué tipo de personas se unirían a una organización terrorista obsesionada con dominar el mundo, es obvio por qué las tropas de Hydra dejan tanto que desear.\" —Jessica Drew"},
  "04153": {"n":"Soldado de Hydra","t":"Guardia. (Mientras este Esbirro esté enfrentado a ti, no podrás atacar al Villano.)\nCuando se derrote esta carta: reparte una carta de Encuentro al jugador enfrentado."},
  "04154": {"n":"Patrulla de Hydra","t":"Cuando se derrote esta carta: cada jugador busca un Esbirro HYDRA en el mazo y la pila de descartes de Encuentros y lo pone en juego enfrentado a él. Baraja el mazo de Encuentros.","f":"Los soldados de Hydra organizan patrullas rutinarias para mantener el control en su territorio."},
  "04155": {"n":"Estimulantes adrenales","t":"Inicio.\nAcción de Héroe: descarta esta carta y quítala de la hoja de campaña → prepara tu Héroe y cúrale 5 de Daño."},
  "04156": {"n":"Escáner táctico","t":"Inicio.\nAcción de Héroe: descarta esta carta y quítala de la hoja de campaña → roba 5 cartas."},
  "04157": {"n":"Teletransportador de emergencia","t":"Inicio.\nAcción de Héroe: descarta esta carta y quítala de la hoja de campaña → busca un Aliado en tu mazo y tu pila de descartes, ponlo en juego y dale una carta de Estado \"Duro\"."},
  "04158": {"n":"Cañón láser","t":"Inicio.\nAcción de Héroe: descarta esta carta y quítala de la hoja de campaña → inflige 5 de Daño al Villano y a cada enemigo que esté enfrentado a ti."},
  "04159a": {"n":"Mejora básica de Intervención","t":"Permanente. Inicio.\nRecibes +2 de Vida.\nTu Héroe recibe +1 INT."},
  "04159b": {"n":"Mejora superior de Intervención","t":"Permanente. Inicio.\nRecibes +2 de Vida.\nTu Héroe recibe +1 INT.\nRespuesta: después de que derrotes un Plan secundario, agota esta carta → roba 1 carta."},
  "04160a": {"n":"Mejora básica de Ataque","t":"Permanente. Inicio.\nRecibes +1 de Vida.\nTu Héroe recibe +1 ATQ."},
  "04160b": {"n":"Mejora superior de Ataque","t":"Permanente. Inicio.\nRecibes +1 de Vida.\nTu Héroe recibe +1 ATQ.\nRespuesta: después de que derrotes a un Esbirro, agota esta carta → roba 1 carta."},
  "04161a": {"n":"Mejora básica de Defensa","t":"Permanente. Inicio.\nRecibes +3 de Vida.\nTu Héroe recibe +1 DEF."},
  "04161b": {"n":"Mejora superior de Defensa","t":"Permanente. Inicio.\nRecibes +3 de Vida.\nTu Héroe recibe +1 DEF.\nRespuesta: después de que te defiendas contra un ataque, agota esta carta → roba 1 carta."},
  "04162a": {"n":"Mejora básica de Recuperación","t":"Permanente. Inicio.\nRecibes +4 de Vida.\nTu Héroe recibe +1 REC."},
  "04162b": {"n":"Mejora superior de Recuperación","t":"Permanente. Inicio.\nRecibes +4 de Vida.\nTu Héroe recibe +1 REC.\nRespuesta: después de que uses tu REC, agota esta carta → roba 1 carta."},
  "04163": {"n":"Algoritmo de Zola","t":"Acción de Alter ego: agota tu Alter ego y gasta un recurso [mental] → descarta esta carta.","f":"\"Un hermoso parásito que crece en el seno de los sistemas informáticos más seguros del mundo.\" —Arnim Zola"},
  "04164": {"n":"Emergencia médica","t":"Respuesta obligada: al final de tu turno, sufres 1 de Daño si tienes adoptada tu identidad de Héroe.\nAcción de Alter ego: descarta las 5 primeras cartas de tu mazo y gasta un recurso [physical] → descarta esta carta.","f":"\"Esto va a necesitar puntos de sutura.\" —Stephen Extraño"},
  "04165": {"n":"Ley marcial","t":"El tamaño de tu mano se reduce en 1.\nAcción de Alter ego: date a ti mismo una carta de Encuentro y gasta un recurso [energy] → descarta esta carta.","f":"\"Lleváoslo a un lado para interrogarlo.\" —Soldado de Hydra"},
  "04166": {"n":"Propaganda antiheroica","t":"Tu Héroe recibe -1 INT, -1 ATQ y -1 DEF.\nAcción de Alter ego: sufre 2 de Daño y gasta un recurso [wild] → descarta esta carta.","f":"\"Estos disidentes siembran el conflicto. Ellos son vuestro verdadero enemigo.\" —Boletín informativo de Hydra"},
  "05001a": {"t":"\"Morfogenética\" — Respuesta: después de que juegues un Evento de ATAQUE, INTERVENCIÓN o DEFENSA, agota a Ms. Marvel → devuelve ese Evento a tu mano.","f":"\"Podéis llamarme Ms. Marvel. Y si cooperáis, no os volveré a tirar.\""},
  "05001b": {"t":"Fervor adolescente — Acción: descarta cartas de la parte superior de tu mazo hasta que descartes una carta de Ms. Marvel, luego añade esa carta a tu mano. (Límite de una vez por ronda.)","f":"\"Quiero ser bella e impresionante y abrumadora y menos complicada.\""},
  "05002": {"n":"Puñal Rojo","t":"Interrupción: cuando Puñal Rojo sea derrotado, gasta 2 recursos de distintos tipos → inflige 2 de Daño a un enemigo y devuelve Puñal Rojo a tu mano.","f":"\"Karachi es mi casa. Patrullo estos barrios.\""},
  "05003": {"n":"Manos grandes","t":"Acción de Héroe (ataque): inflige 4 de Daño a un enemigo.","f":"\"Esto de la mano... se me está yendo de las manos...\" —Ms. Marvel"},
  "05004": {"n":"Escabullirse","t":"Acción de Héroe (intervención): quita 3 de Amenaza de un Plan.","f":"\"Así se podría describir mi vida entera, con una metáfora mala.\" —Kamala Khan"},
  "05005": {"n":"Flexibilidad","t":"Interrupción de Héroe (defensa): cuando vayas a sufrir cualquier cantidad de Daño, evita 3 de ese Daño. Roba 1 carta.","f":"\"Ya que nos estamos conociendo, un dato: no me gusta que me pillen por sorpresa.\" —Ms. Marvel"},
  "05006": {"t":"Acción de Alter ego: agota a Aamir Khan → coloca 1 carta de tu pila de descartes en la parte inferior de tu mazo, luego roba 1 carta.","f":"\"¿Estás... bien? O sea... aparte de haberte buscado el lío más gordo de tu vida.\""},
  "05007": {"t":"Acción de Alter ego: agota a Bruno Carrelli → vincula una carta de tu mano boca abajo a esta carta.\nAcción: agota a Bruno Carrelli → añade a tu mano un máximo de 3 cartas que estén vinculadas a esta carta."},
  "05008": {"t":"Acción de Alter ego: agota a Nakia Bahadir → reduce en 1 el coste de la siguiente carta que juegues en esta fase.","f":"\"Eres demasiado dulce, magdalenita esponjosa. Confías demasiado en la gente.\" —Nakia Bahadir"},
  "05009": {"n":"Traje de polímero biocinético","t":"Recurso de Héroe: agota el Traje de polímero biocinético → genera un recurso [wild] para un Evento.","f":"\"¿Y ese polímero en el que trabajabas para la beca? ¿El supermoco?\" —Kamala Khan"},
  "05010": {"n":"¡Agrandar!","t":"Interrupción de Héroe: cuando juegues un Evento de ATAQUE, agota ¡Agrandar! → incrementa en 2 la cantidad de Daño que inflija ese Evento.","f":"\"¡AGRANDAR!\" —Ms. Marvel"},
  "05011": {"n":"Encoger","t":"Interrupción de Héroe: cuando juegues un Evento de INTERVENCIÓN, agota Encoger → incrementa en 2 la cantidad de Amenaza que quite ese Evento.","f":"\"¡Encoger encoger encoger!\" —Ms. Marvel"},
  "05012": {"t":"Interrupción: cuando un enemigo inicie un ataque contra ti, gasta un recurso [energy] → inflige 2 de Daño a ese enemigo.","f":"\"Supongo que mamá se equivocaba. ¡Todos esos años jugando a los videojuegos han merecido la pena!\""},
  "05013": {"n":"¡Poneos detrás de mí!","t":"Interrupción de Héroe: cuando se muestre una carta de Perfidia del mazo de Encuentros, anula su efecto de \"Cuando se muestre esta carta\". En vez de eso, el Villano te ataca a ti.","f":"\"¡Ejem! ¡A un lado, ciudadanos!\" —Ms. Marvel"},
  "05014": {"n":"Ataque preventivo","t":"Interrupción de Héroe (defensa): al poner boca arriba una carta de Aumento cuando el Villano ataque, anula todos los iconos de Aumento ([boost]) de esa carta. Luego inflige 1 de Daño al Villano por cada icono de Aumento que se haya anulado de este modo."},
  "05015": {"n":"Arremetida","t":"Acción de Héroe (ataque): aturde a un enemigo. Si has pagado el coste de esta carta usando un recurso [physical], inflige 3 de Daño a ese enemigo.","f":"Mañana no voy a poder ni moverme."},
  "05016": {"n":"El poder de la protección","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta de Protección (verde)."},
  "05017": {"n":"Barrera de energía","t":"Usos (3 contadores de Reflejo).\nInterrupción: cuando vayas a sufrir cualquier cantidad de Daño, quita 1 contador de Reflejo de esta carta → evita 1 de ese Daño e inflige 1 de Daño a un enemigo."},
  "05018": {"n":"Mandíbulas","t":"Puedes jugar a Mandíbulas desde tu pila de descartes durante tu turno (pagando su coste en recursos).","f":"\"Ahhh... espera un segundo, Bruno. Creo que mi nuevo perro acaba de teleportarse dentro de mi cuarto.\" —Kamala Khan"},
  "05019": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "05020": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "05021": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "05022": {"n":"Mansión de los Vengadores","t":"Máximo de 1 por jugador.\nAcción: agota la Mansión de los Vengadores → elige un jugador. Ese jugador roba 1 carta.","f":"\"¿Te has acordado de cerrar con llave?\" —Janet Van Dyne"},
  "05023": {"n":"Aguante","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nRecibes +3 de Vida."},
  "05024": {"n":"Reflejos mejorados","t":"Usos (3 contadores de Energía).\nRecurso de Héroe: agota Reflejos mejorados y quítale 1 contador de Energía → genera un recurso [energy]."},
  "05025": {"n":"En casa de madrugada","t":"Dale esta carta al jugador que lleva a Kamala Khan.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n• Agota a Kamala Khan → retira del juego En casa de madrugada.\n• Descarta 1 Apoyo INDIVIDUO que controles. Si no se descarta ningún Apoyo de este modo, esta carta gana Oleada. Descarta esta Obligación."},
  "05026": {"n":"Generación \"¿Por qué?\"","t":"Cuando se muestra esta carta: descarta la primera carta del mazo de cada jugador por cada Apoyo INDIVIDUO y cada Aliado que haya en juego.","f":"El inventor ha persuadido a los jóvenes de Jersey City de que se presten como baterías humanas para sus experimentos."},
  "05027": {"t":"Thomas Edison no puede sufrir Daño mientras estés enfrentado a otro Esbirro.\n(Esbirro Archienemigo de Ms. Marvel.)","f":"\"¡NO SOY UN PÁJARO!\""},
  "05028": {"n":"Robot gigante de Edison","t":"El Robot gigante de Edison no puede sufrir Daño.\nAcción de Héroe: gasta un recurso [mental] → hasta el final de la fase, trata esta carta como si su texto de reglas impreso estuviese en blanco."},
  "05029": {"n":"Cosecha","t":"Cuando se muestre esta carta: agota todos los Apoyos INDIVIDUO que haya en juego. Por cada Apoyo que se agote de este modo, el Villano se cura 1 de Daño. Si no se agota ningún Apoyo INDIVIDUO de este modo, esta carta gana Oleada."},
  "05030": {"n":"Cuerpo a cuerpo","t":"Acción de Héroe (ataque): inflige 3 de Daño a un enemigo. Inflige 3 de Daño a otro enemigo."},
  "05031": {"n":"Golpe contundente","t":"Acción de Héroe (ataque): confunde a un enemigo. Si has pagado el coste de esta carta usando un recurso [physical], inflige 3 de Daño a ese enemigo."},
  "05032": {"n":"Moral elevada","t":"Acción de Héroe: elige un Héroe. Hasta el final de la ronda, ese Héroe recibe +1 INT, +1 ATQ, y +1 DEF.","f":"\"Es una posición que tengo que tomar. Esta vez, sin concesiones.\" —Sam Wilson"},
  "05033": {"n":"Tomarse un respiro","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nTu Alter ego recibe +2 REC.","f":"\"Deberíamos hacer esto más a menudo.\""},
  "06001a": {"t":"\"¡Defiéndete!\" — Respuesta: después de que te enfrentes a un Esbirro, roba 2 cartas. (Límite de una vez por fase.)","f":"\"¡Ahora te enfrentas al Vengador más poderoso!\""},
  "06001b": {"t":"Digno — Acción: busca en tu mazo y tu pila de descartes la Mejora Mjolnir y añádela a tu mano. Baraja tu mazo. (Límite de una vez por ronda.)"},
  "06002": {"n":"Dama Sif","t":"Respuesta: después de que la Dama Sif entre en juego, prepara a Thor o a Odinson.","f":"\"Cuando mi amado avanza... ¡su dama Sif estará a su lado!\""},
  "06003": {"n":"Defensor de los Nueve Reinos","t":"Acción de Héroe (intervención): descarta cartas de la parte superior del mazo de Encuentros hasta que descartes un Esbirro. Pon en juego ese Esbirro enfrentado a ti → quita 3 de Amenaza de un Plan."},
  "06004": {"n":"¡Por Asgard!","t":"Acción de Alter ego: busca en tu mazo y tu pila de descartes una carta que tenga el rasgo Asgard y añádela a tu mano. Baraja tu mazo.","f":"\"¡Por el honor! ¡Por la gloria! ¡Por Asgard!\" —Thor"},
  "06005": {"n":"Lanzamiento de martillo","t":"Acción de Héroe (ataque): agota Mjolnir → inflige 8 de Daño a un enemigo y devuelve Mjolnir a tu mano. Este ataque gana Brutalidad.","f":"\"¡Ahora, Mjolnir! ¡Vuela certero!\" —Thor"},
  "06006": {"n":"Relámpago","t":"Acción de Héroe: gasta X recursos [energy] → inflige X de Daño al Villano y a cada Esbirro que esté enfrentado a ti. Este ataque ignora las cartas de Estado \"Duro\" si posees el rasgo AÉREO.","f":"\"¡Yo digo NO!\" —Thor"},
  "06007": {"t":"Recibes +1 al tamaño de tu mano.","f":"Odín vela por los Nueve Reinos desde la reluciente ciudad de Asgard, donde también se crió el príncipe Thor."},
  "06008": {"n":"Dios del Trueno","t":"Recurso de Héroe: agota Dios del Trueno → genera un recurso [energy].","f":"\"Soy el dios del trueno, señor del salvaje rayo... ¡y los mismos cielos tiemblan cuando habla el poderoso Thor!\" —Thor"},
  "06009": {"t":"Restringida. (Máximo de 2 cartas Restringidas por jugador.)\nThor recibe +1 ATQ y gana el rasgo AÉREO.","f":"Quien sostenga este martillo, si es digno, poseerá el poder de Thor."},
  "06010": {"n":"Yelmo de Thor","t":"Recibes +5 de Vida.","f":"\"Hermanos y hermanas... preparaos: hoy entramos en guerra.\" —Thor"},
  "06011": {"n":"Hércules","t":"El coste para jugar a Hércules se reduce en 1 por cada Esbirro que esté enfrentado a ti.","f":"Cualquier cosa que Thor pueda hacer... ¡Hércules la puede lograr con más poder!"},
  "06012": {"n":"Valquiria","t":"Respuesta: después de que la Valquiria entre en juego, inflige 2 de Daño a un Esbirro (3 de Daño si has pagado el coste de esta carta usando un recurso [energy]).","f":"Soy la Valquiria, doncella escudera de Asgard."},
  "06013": {"n":"A por ellos","t":"Respuesta (intervención): después de que tu Héroe ataque y derrote a un enemigo, quita 2 de Amenaza de un Plan.","f":"\"Kamala, no tenemos banda sonora propia. Deja ya de tatarear...\" —Capitana Marvel"},
  "06014": {"n":"¡Ven aquí!","t":"Acción de Héroe (ataque): inflige 1 de Daño a un Esbirro. Si tienes el rasgo AÉREO, te enfrentas a ese enemigo.","f":"\"¡Mi martillo tendrá unas palabras contigo!\" —Thor"},
  "06015": {"n":"Golpetazo","t":"Interrupción de Héroe: cuando tu Héroe realice un ataque básico, agota una Mejora ARMA vinculada a tu Héroe → tu Héroe recibe +3 ATQ para este ataque.","f":"¡PUM!"},
  "06016": {"n":"El poder de la agresividad","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta de Agresividad (roja)."},
  "06017": {"n":"Salón de los Héroes","t":"Respuesta: después de que derrotes a un Esbirro, coloca 1 contador de Gloria sobre esta carta.\nAcción de Alter ego: agota el Salón de los Héroes y quítale 3 contadores de Gloria → roba 3 cartas."},
  "06018": {"n":"Furia de combate","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nRespuesta: después de que tu Héroe ataque y derrote a un Esbirro, inflige 1 de Daño a tu Héroe y descarta Furia de combate → prepara a tu Héroe."},
  "06019": {"t":"Restringida. (Máximo de 2 cartas Restringidas por jugador.)\nRespuesta: después de que tu Héroe ataque a un enemigo, gasta un recurso [physical] → inflige 2 de Daño a un enemigo."},
  "06020": {"t":"Respuesta: después de que Heimdall entre en juego, mira las 3 primeras cartas del mazo de Encuentros. Descarta 1 de ellas y vuelve a colocar las demás en el orden que prefieras.","f":"\"¿Deseas saber lo que veo?\""},
  "06021": {"n":"Invulnerabilidad","t":"Acción de Héroe: dale a tu Héroe una carta de Estado \"Duro\".","f":"\"Tío, mi piel es impenetrable. ¿Es que no sabes quién soy?\" —Luke Cage"},
  "06022": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "06023": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "06024": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "06025": {"n":"Mansión de los Vengadores","t":"Máximo de 1 por jugador.\nAcción: agota la Mansión de los Vengadores → elige un jugador. Ese jugador roba 1 carta.","f":"\"¿Te has acordado de cerrar con llave?\" —Janet Van Dyne"},
  "06026": {"n":"La ira de Odín","t":"Dale esta carta al jugador que lleva a Odinson.\nPuedes adoptar la identidad de tu Alter ego. Elige:\n• Agota a Odinson → retira del juego La ira de Odín.\n• Descarta Mjolnir de tu mano o del juego. Quedas aturdido. Descarta esta Obligación."},
  "06027": {"n":"Rencilla familiar","t":"Cuando se muestre esta carta: coloca 1 de Amenaza adicional sobre esta carta por cada carta ASGARD que haya en juego.","f":"Loki, el sempiterno embaucador, es incapaz de dejar pasar una oportunidad para frustrar a su hermano Thor."},
  "06028": {"t":"Interrupción obligada: cuando Loki vaya a ser derrotado, descarta la primera carta del mazo de Encuentros. Si esa carta es una Perfidia, Loki se cura todo el Daño en vez de ser derrotado.\n(Esbirro Archienemigo de Thor.)","f":"\"Pareces decepcionado, hermano. Me alegro.\""},
  "06029": {"n":"Gigante de hielo","t":"Dureza. (Este personaje entra en juego con una carta de Estado \"Duro\".)\n[star] Aumento: Si el Villano está atacando y este ataque inflige Daño a un personaje, aturde a ese personaje."},
  "06030": {"n":"Embaucador","t":"Cuando se muestre esta carta: descarta las 3 primeras cartas de tu mazo. Coloca 1 de Amenaza sobre el Plan principal por cada tipo de carta distinto que se haya descartado de este modo.","f":"\"¿Cuántas veces vas a caer en esa artimaña?\" —Loki"},
  "06031": {"n":"Bajo vigilancia","t":"Vincula esta carta al Plan principal. Máximo de 1 por Plan.\nEl umbral de Amenaza del Plan vinculado se incrementa en 4."},
  "06032": {"n":"Trabajo en equipo","t":"Interrupción de Héroe: cuando uses tu atributo básico de Intervención (INT) o tu atributo básico de Ataque (ATQ), agota un Aliado que controles → suma el atributo correspondiente de ese Aliado al de tu Héroe para este uso."},
  "06033": {"n":"Fuerzas de flaqueza","t":"Acción: cura 4 de Daño a una carta de Superhéroe (5 de Daño si has pagado el coste de esta carta usando un recurso [mental])."},
  "06034": {"n":"Vigor mejorado","t":"Usos (3 contadores Físicos).\nRecurso de Héroe: agota Vigor mejorado y quítale 1 contador Físico → genera un recurso [physical]."},
  "07001a": {"n":"Fuga de prisión","t":"Contenido: Destructor A, Bola de Trueno A, Martinete A y Bulldozer A como Villanos. (Usa las versiones B para aumentar la dificultad.) Mazos de Encuentros de Destructor, Bola de Trueno, Martinete y Bulldozer.\nPreparación: pon en juego los Planes secundarios Ajuste de cuentas, Poderoso como el trueno, Ejercer presión y Despejar el camino. Coloca el contador de Villano activo sobre Destructor. Avanza a la etapa 1B."},
  "07001b": {"n":"Fuga de prisión","t":"[star]Respuesta obligada: después del paso uno de la fase del Villano, coloca 1 de Amenaza sobre cada Plan secundario. Traslada el contador de Villano activo al Villano cuyo Plan tenga más Amenaza. (En caso de empate, decide el jugador inicial.)\nSi se completa esta etapa, los jugadores pierden la partida."},
  "07002": {"n":"Destructor","t":"[star] Cuando Destructor ejecuta el Plan, la Amenaza se coloca sobre su Plan secundario en vez del Plan principal.\n[star] Mientras Destructor esté atacando, recibe +2 ATQ si es un ataque no defendido."},
  "07003": {"n":"Destructor","t":"[star] Cuando Destructor ejecuta el Plan, la Amenaza se coloca sobre su Plan secundario en vez del Plan principal.\n[star] Mientras Destructor esté atacando, recibe +2 ATQ si es un ataque no defendido."},
  "07004": {"n":"Ajuste de cuentas","t":"Plan secundario de Destructor.\nEsta carta no puede abandonar el juego mientras Destructor esté en juego.\nPegada fuerte — Respuesta obligada: después de que se coloque Amenaza sobre esta carta, si hay al menos 10 de Amenaza sobre ella, inflige 2 de Daño a cada personaje amigo. Retira toda la Amenaza de este Plan excepto 3."},
  "07005": {"n":"Toma de rehenes","t":"Vincula esta carta al Plan secundario del Villano activo.\nNo puede quitarse Amenaza del Plan vinculado mediante una intervención.\nAcción de Héroe: el Villano correspondiente al Plan secundario vinculado te ataca. Luego descarta esta carta."},
  "07006": {"n":"Palanca mágica","t":"Vincula esta carta a Destructor.\n[star] Respuesta obligada: después de que Destructor ataque, coloca 1 de Amenaza sobre el Plan secundario que tenga menos Amenaza.\nAcción de Héroe: agota tu Héroe y descarta 1 carta de tu mano al azar → descarta esta carta."},
  "07007": {"n":"Liderados por Destructor","t":"Vincula esta carta a Destructor.\n[star] Respuesta obligada: después de que Destructor ejecute el Plan, coloca 1 de Amenaza sobre los Planes secundarios de los demás Villanos.\nAcción de Héroe: gasta recursos [physical] [physical] → descarta esta carta."},
  "07008": {"n":"Celador corrupto","t":"Guardia. (Mientras este Esbirro esté enfrentado a ti, no podrás atacar al Villano.)"},
  "07009": {"n":"Preso fugado","t":"Oleada\nAumento: traslada el contador de Villano activo al Villano cuyo Plan secundario tenga menos amenaza. Si tienes adoptada tu identidad de Héroe, ese Villano te ataca después de este ataque. Ese ataque no recibe una carta de aumento."},
  "07010": {"n":"Compañerismo","t":"Cuando se muestre esta carta: elige al Villano cuyo Plan secundario tenga menos Amenaza. Muestra la primera carta de su mazo (las 2 primeras cartas si es el único Villano que está en juego).\n[star] Aumento: Traslada el contador de Villano activo al Villano cuyo Plan secundario tenga menos Amenaza."},
  "07011": {"n":"Caos en la cárcel","t":"Cuando se muestre esta carta: elige entre descartar una Mejora que controles o bien colocar 1 de Amenaza sobre el Plan secundario del Villano activo por cada Mejora que controles. Si no controlas ninguna Mejora, esta carta gana Oleada.\n[star] Aumento: Si este ataque no es defendido, descarta una Mejora que controles."},
  "07012": {"n":"Lanzamiento de palanca","t":"Cuando se muestre esta carta (Alter ego): Destructor ejecuta el Plan. Luego traslada el contador de Villano activo al Villano cuyo Plan secundario tenga menos Amenaza.\nCuando se muestre esta carta (Héroe): Destructor te ataca. Luego traslada el contador de Villano al Villano cuyo Plan secundario tenga menos Amenaza."},
  "07013": {"n":"¡Destrozadlos!","t":"Cuando se muestre esta carta (Alter ego): el Villano cuyo Plan secundario tenga más amenaza ejecuta el Plan.\nCuando se muestre esta carta (Héroe): el Villano cuyo Plan secundario tenga menos Amenaza te ataca."},
  "07014": {"n":"¡Lo estaba deseando!","t":"Cuando se muestre esta carta: el Villano activo se cura 3 de Daño. Dale a ese Villano una carta de Estado \"Duro\".\n[star] Aumento: Traslada el contador de Villano al Villano cuyo Plan secundario tenga menos Amenaza. Ese Villano ejecuta el Plan."},
  "07015": {"n":"Vínculo místico","t":"Cuando se muestre esta carta: coloca 2 de Amenaza sobre cada Plan secundario.\n[star] Aumento: Destructor recibe +3 ATQ para esta activación a menos que coloques 2 de Amenaza sobre su Plan secundario."},
  "07016": {"n":"¡Date por muerto!","t":"Cuando se muestre esta carta: inflige 1 de Daño al Héroe o Aliado que tenga menos Vida restante. Si esto derrota a ese personaje, coloca 3 de Amenaza sobre el Plan secundario de Destructor."},
  "07017": {"n":"Bola de Trueno","t":"[star] Cuando Bola de Trueno ejecuta el Plan, la Amenaza se coloca sobre su Plan secundario en vez del Plan principal.\n[star] Respuesta obligada: después de que Bola de Trueno te ataque, inflige 1 de Daño a todos los personajes que controles."},
  "07018": {"n":"Bola de Trueno","t":"[star] Cuando Bola de Trueno ejecuta el Plan, la Amenaza se coloca sobre su Plan secundario en vez del Plan principal.\n[star] Respuesta obligada: después de que Bola de Trueno te ataque, inflige 1 de Daño a todos los personajes que controles."},
  "07019": {"n":"Poderoso como el trueno","t":"Plan secundario de Bola de Trueno.\nEsta carta no puede abandonar el juego mientras Bola de Trueno esté en juego.\nEstallido gamma — Respuesta obligada: después de que se coloque Amenaza sobre esta carta, si hay al menos 10 de Amenaza sobre ella, aturde a todos los personajes amigos. Retira toda la Amenaza de este Plan excepto 3."},
  "07020": {"n":"Bola y cadena","t":"Vincula esta carta a Bola de Trueno.\n[star] Respuesta obligada: después de que Bola de Trueno ataque, coloca 1 de Amenaza sobre el Plan principal.\nAcción de Héroe: agota tu Héroe y descarta 1 carta de tu mano al azar → descarta esta carta."},
  "07021": {"n":"Toma de rehenes","t":"Vincula esta carta al Plan secundario del Villano activo.\nNo puede quitarse Amenaza del Plan vinculado mediante una intervención.\nAcción de Héroe: el Villano correspondiente al Plan secundario vinculado te ataca. Luego descarta esta carta."},
  "07022": {"n":"Acumulación de radiación","t":"Vincula esta carta a Bola de Trueno.\nEl daño sobrante infligido por Bola de Trueno se coloca como Amenaza sobre su correspondiente Plan secundario.\n[star] Respuesta obligada: después de que Bola de Trueno ataque, descarta esta carta."},
  "07023": {"n":"Celador corrupto","t":"Guardia. (Mientras este Esbirro esté enfrentado a ti, no podrás atacar al Villano.)"},
  "07024": {"n":"Preso fugado","t":"Oleada.\n[star] Aumento: Traslada el contador de Villano activo al Villano cuyo Plan secundario tenga menos amenaza. Si tienes adoptada tu identidad de Héroe, ese Villano te ataca después de este ataque. Ese ataque no recibe una carta de aumento."},
  "07025": {"n":"Compañerismo","t":"Cuando se muestre esta carta: elige al Villano cuyo Plan secundario tenga menos Amenaza. Muestra la primera carta de su mazo (las 2 primeras cartas si es el único Villano que está en juego).\n[star] Aumento: Traslada el contador de Villano activo al Villano cuyo Plan secundario tenga menos Amenaza."},
  "07026": {"n":"Caos en la cárcel","t":"Cuando se muestre esta carta: elige entre descartart una Mejora que controles o bien colocar 1 de Amenaza sobre el Plan secundario del Villano activo por cada Mejora que controles. Si no controlas ninguna Mejora, esta carta gana Oleada.\n[star] Aumento: Si este ataque no es defendido, descarta una Mejora que controles."},
  "07027": {"n":"Proyectiles de energía","t":"Cuando se muestre esta carta: inflige 1 de Daño a cada personaje amigo que controles.\n[star] Aumento: Inflige 1 de Daño al personaje defensor."},
  "07028": {"n":"¡Destrozadlos!","t":"Cuando se muestre esta carta (Alter ego): el Villano cuyo Plan secundario tenga más amenaza ejecuta el Plan.\nCuando se muestre esta carta (Héroe): el Villano cuyo Plan secundario tenga menos Amenaza te ataca."},
  "07029": {"n":"¡Lo estaba deseando!","t":"Cuando se muestre esta carta: el Villano activo se cura 3 de Daño. Dale a ese Villano una carta de Estado \"Duro\".\n[star] Aumento: Traslada el contador de Villano al Villano cuyo Plan secundario tenga menos Amenaza. Ese Villano ejecuta el Plan."},
  "07030": {"n":"Descarga energética","t":"Cuando se muestre esta carta (Alter ego): coloca 3 de Amenaza sobre el Plan secundario que tenga más Amenaza.\nCuando se muestre esta carta (Héroe): Bola de Trueno te ataca. Si este ataque no es defendido, coloca 3 de Amenaza sobre el Plan secundario de Bola de Trueno."},
  "07031": {"n":"Destreza táctica","t":"Cuando se muestre esta carta: traslada toda la Amenaza que haya sobre el Plan secundario con menos Amenaza hasta el Plan secundario que tenga más Amenaza. Si esto no hace que se aplique la capacidad de \"Respuesta obligada\" de ese Plan, esta carta gana Oleada."},
  "07032": {"n":"Martinete","t":"Represalia 1.\n[star] Cuando Martinete ejecuta el Plan, la Amenaza se coloca sobre su Plan secundario en vez del Plan principal."},
  "07033": {"n":"Martinete","t":"Represalia 1.\n[star] Cuando Martinete ejecuta el Plan, la Amenaza se coloca sobre su Plan secundario en vez del Plan principal."},
  "07034": {"n":"Ejercer presión","t":"Plan secundario de Martinete.\nEsta carta no puede abandonar el juego mientras Martinete esté en juego.\nMartillo pilón — Respuesta obligada: después de que se coloque Amenaza sobre esta carta, si hay al menos 10 de Amenaza sobre ella, cada jugador descarta la Mejora o Apoyo que controle que tenga el coste más alto. Retira toda la Amenaza de este Plan excepto 3."},
  "07035": {"n":"Bravatas","t":"Vincula esta carta a Martinete.\nMartinete recibe +3 de Vida. Los jugadores no pueden atacar a otros Villanos.\nRespuesta: después de que tu Héroe ataque a Martinete, gasta recursos [physical] [physical] → descarta esta carta."},
  "07036": {"n":"Toma de rehenes","t":"Vincula esta carta al Plan secundario del Villano activo.\nNo puede quitarse Amenaza del Plan vinculado mediante una intervención.\nAcción de Héroe: el Villano correspondiente al Plan secundario vinculado te ataca. Luego descarta esta carta."},
  "07037": {"n":"Celador corrupto","t":"Guardia. (Mientras este Esbirro esté enfrentado a ti, no podrás atacar al Villano.)"},
  "07038": {"n":"Preso fugado","t":"Oleada.\n[star] Aumento: Traslada el contador de Villano activo al Villano cuyo Plan secundario tenga menos amenaza. Si tienes adoptada tu identidad de Héroe, ese Villano te ataca después de este ataque. Ese ataque no recibe una carta de aumento."},
  "07039": {"n":"Compañerismo","t":"Cuando se muestre esta carta: elige al Villano cuyo Plan secundario tenga menos Amenaza. Muestra la primera carta de su mazo (las 2 primeras cartas si es el único Villano que está en juego).\n[star] Aumento: Traslada el contador de Villano activo al Villano cuyo Plan secundario tenga menos Amenaza."},
  "07040": {"n":"¡Destrozadlos!","t":"Cuando se muestre esta carta (Alter ego): el Villano cuyo Plan secundario tenga más amenaza ejecuta el Plan.\nCuando se muestre esta carta (Héroe): el Villano cuyo Plan secundario tenga menos Amenaza te ataca."},
  "07041": {"n":"¡Lo estaba deseando!","t":"Cuando se muestre esta carta: el Villano activo se cura 3 de Daño. Dale a ese Villano una carta de Estado \"Duro\".\n[star] Aumento: Traslada el contador de Villano al Villano cuyo Plan secundario tenga menos Amenaza. Ese Villano ejecuta el Plan."},
  "07042": {"n":"Puños enormes","t":"Cuando se muestre esta carta: descarta el Apoyo que controles que tenga el coste más alto. Si no descartas ningún Apoyo de este modo, coloca 2 de Amenaza sobre el Plan del Villano activo.\n[star] Aumento: Descarta 1 Apoyo que controles."},
  "07043": {"n":"Plan de huida","t":"Cuando se muestre esta carta: quedas confundido. Si ya estabas confundido, Martinete ejecuta el Plan.\n[star] Aumento: Dale al Villano activo una carta de estado \"Duro\". Si ya tenía una carta de Estado \"Duro\", coloca 2 de Amenaza sobre su Plan."},
  "07044": {"n":"Aporrear","t":"Cuando se muestre esta carta (Alter ego): Martinete ejecuta el Plan. Si Martinete es Duro, recibe +2 PLA para esta activación.\nCuando se muestre esta carta (Héroe): Martinete te ataca. Si Martinete es Duro, recibe +2 ATQ para esta activación."},
  "07045": {"n":"Resistencia extraordinaria","t":"Cuando se muestre esta carta: retira todas las cartas de Estado \"Aturdido\" y \"Confundido\" de todos los Villanos. Si no se retira ninguna carta de Estado de este modo, esta carta gana Oleada.\n[star] Aumento: Quedas confundido."},
  "07046": {"t":"[star] Cuando Bulldozer ejecuta el Plan, la Amenaza se coloca sobre su Plan secundario en vez del Plan principal.\n[star] Interrupción obligada: cuando Bulldozer ataca, su ataque gana Brutalidad."},
  "07047": {"t":"[star] Cuando Bulldozer ejecuta el Plan, la Amenaza se coloca sobre su Plan secundario en vez del Plan principal.\n[star] Interrupción obligada: cuando Bulldozer ataca, su ataque gana Brutalidad."},
  "07048": {"n":"Despeja el camino","t":"Plan secundario de Bulldozer.\nEsta carta no puede abandonar el juego mientras Bulldozer esté en juego.\n¡A la carga! — Respuesta obligada: después de que se coloque Amenaza sobre esta carta, si hay al menos 10 de Amenaza sobre ella, cada jugador debe descartar las 10 primeras cartas de su mazo. Retira toda la Amenaza de este Plan excepto 3."},
  "07049": {"n":"Casco de Bulldozer","t":"Vincula esta carta a Bulldozer.\n[star] Respuesta obligada: después de que Bulldozer te ataque, descarta tantas cartas de la parte superior de tu mazo como la cantidad de Daño que inflija este ataque.\nAcción de Héroe: agota tu Héroe y descarta 1 carta de tu mano al azar → descarta esta carta."},
  "07050": {"n":"Toma de rehenes","t":"Vincula esta carta al Plan secundario del Villano activo.\nNo puede quitarse Amenaza del Plan vinculado mediante una intervención.\nAcción de Héroe: el Villano correspondiente al Plan secundario vinculado te ataca. Luego descarta esta carta."},
  "07051": {"n":"Velocidad de embestida","t":"Vincula esta carta a Bulldozer.\n[star] Interrupción obligada: cuando Bulldozer te ataque, debes defenderte de los ataques de Bulldozer con un Aliado que controles (si puedes).\n[star] Respuesta obligada: después de que Bulldozer te ataque, descarta esta carta."},
  "07052": {"n":"Celador corrupto","t":"Guardia. (Mientras este Esbirro esté enfrentado a ti, no podrás atacar al Villano.)"},
  "07053": {"n":"Preso fugado","t":"Oleada.\n[star] Aumento: Traslada el contador de Villano activo al Villano cuyo Plan secundario tenga menos amenaza. Si tienes adoptada tu identidad de Héroe, ese Villano te ataca después de este ataque. Ese ataque no recibe una carta de aumento."},
  "07054": {"n":"Compañerismo","t":"Cuando se muestre esta carta: elige al Villano cuyo Plan secundario tenga menos Amenaza. Muestra la primera carta de su mazo (las 2 primeras cartas si es el único Villano que está en juego).\n[star] Aumento: Traslada el contador de Villano activo al Villano cuyo Plan secundario tenga menos Amenaza."},
  "07055": {"n":"Acometida","t":"Cuando se muestre esta carta (Alter ego): Bulldozer ejecuta el Plan. Descarta tantas cartas de la parte superior de tu mazo como la cantidad de Amenaza que se coloque con esta activación.\nCuando se muestre esta carta (Héroe): Bulldozer te ataca. Descarta tantas cartas de la parte superior de tu mazo como la cantidad de Daño que inflija este ataque."},
  "07056": {"n":"Caos en la cárcel","t":"Cuando se muestre esta carta: elige entre descartart una Mejora que controles o bien colocar 1 de Amenaza sobre el Plan secundario del Villano activo por cada Mejora que controles. Si no controlas ninguna Mejora, esta carta gana Oleada.\n[star] Aumento: Si este ataque no es defendido, descarta una Mejora que controles."},
  "07057": {"n":"¡Destrozadlos!","t":"Cuando se muestre esta carta (Alter ego): el Villano cuyo Plan secundario tenga más amenaza ejecuta el Plan.\nCuando se muestre esta carta (Héroe): el Villano cuyo Plan secundario tenga menos Amenaza te ataca."},
  "07058": {"n":"Cabezazo","t":"Cuando se muestre esta carta: descarta 1 carta de tu mano al azar. Si tienes adoptada tu identidad de Héroe, sufres tanto Daño como el coste impreso de esa carta. Si tienes adoptada tu identidad de Alter ego, coloca tanta Amenaza sobre el Plan secundatio de Bulldozer como el coste impreso de esa carta."},
  "07059": {"n":"Liderar la carga","t":"Cuando se muestre esta carta: descarta las X primeras cartas de tu mazo, siendo X el valor de ATQ de Bulldozer. Coloca 1 de Amenaza sobre el Plan secundario por cada tipo de carta distinto que se haya descartado de este modo."},
  "08001a": {"n":"Viuda Negra","t":"Hacedora de viudas — Respuesta: después de que apliques la capacidad de una carta de PLANIFICACIÓN que controles, inflige 1 de Daño a un enemigo.","f":"\"Mi nombre es madame Natasha… ¡pero podéis llamarme la Viuda Negra!\""},
  "08001b": {"t":"Preparativos para la misión — Respuesta: después de que juegues una carta de PLANIFICACIÓN, roba 1 carta. (Límite de una vez por fase.)","f":"\"Ésta es mi misión, y la completaré con éxito.\""},
  "08002": {"n":"Soldado de Invierno","t":"El coste para jugar al Soldado de Invierno se reduce en 1 por cada carta de PLANIFICACIÓN que controles.","f":"\"Le has disparado a Natasha. Y eso va a ser lo último que has hecho en este mundo, colega.\""},
  "08003": {"n":"Operación encubierta","t":"Acción (intervención): quita 4 de Amenaza de un Plan. Confunde al Villano.","f":"\"El comportamiento humano consite en calcular cuán ciega está dispuesta a mostrarse voluntariamente una persona… y explotarlo.\" —Natasha Romanoff"},
  "08004": {"n":"Danza mortal","t":"Acción de Héroe: efectúa los 3 ataques siguientes por orden:\n- Inflige 1 de Daño a un enemigo.\n- Inflige 2 de Daño a un enemigo.\n- Inflige 3 de Daño a un enemigo."},
  "08005": {"n":"Piso franco n.º 29","t":"Acción de Alter ego: agota el Piso franco n.º 29 y elige una carta de PLANIFICACIÓN que esté en tu pila de descartes → añade esa carta a tu mano.","f":"\"Aquí deberíamos estar a salvo.\" —Viuda Negra"},
  "08006": {"n":"Combate acrobático","t":"Interrupción de Héroe (ataque): cuando se ponga boca arriba una carta de aumento, descarta Combate acrobático → anula los iconos de Aumento de esa carta. Inflige 1 de Daño al Villano por cada icono de Aumento que se haya anulado de este modo."},
  "08007": {"n":"Brazaletes de la Viuda Negra","t":"Recurso: agota los Brazaletes de la Viuda Negra → genera un recurso [wild] para una carta de PLANIFICACIÓN.","f":"\"No sólo son letales; también me quedan estupendamente.\" —Viuda Negra"},
  "08008": {"n":"Gancho de escalada","t":"Interrupción de Héroe: cuando muestres una carta de Perfidia, descarta el Gancho de escalada → anula los efectos de esa carta de Perfidia y descártala.","f":"\"¡Bozhe moi!\" —Viuda Negra"},
  "08009": {"n":"Traje sintético","t":"La Viuda Negra recibe +1 DEF.\nRespuesta de Héroe: después de que apliques la capacidad de una carta de PLANIFICACIÓN que controles, agota el Traje sintético → prepara a la Viuda Negra."},
  "08010": {"n":"Picadura de Viuda","t":"Respuesta de Héroe (ataque): después de que entre en juego un Esbirro, descarta la Picadura de Viuda → inflige 2 de Daño a ese Esbirro y atúrdelo.","f":"\"A dormir.\" —Viuda Negra"},
  "08011": {"n":"Agente Coulson","t":"Respuesta: después de que el Agente Coulson entre en juego, busca una carta de PLANIFICACIÓN en tu mazo y en tu pila de descartes y añádela a tu mano. Baraja tu mazo.","f":"\"Soy el tío que tiene un plan.\""},
  "08012": {"n":"Temblor","t":"Respuesta: después de que un Esbirro ejecute el Plan, agota a Temblor → inflige 2 de Daño a ese Esbirro.","f":"\"¡Haré que todo el edificio os caiga encima!\""},
  "08013": {"n":"Ataque sigiloso","t":"Acción de Héroe (ataque): inflige 4 de Daño a un enemigo. Si este ataque derrota a ese enemigo, quita 2 de Amenaza de un Plan.","f":"\"Ni siquiera lo verán venir.\" —Viuda Negra"},
  "08014": {"n":"El poder de la justicia","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta de Justicia (amarilla)."},
  "08015": {"n":"Sala de interrogatorios","t":"Máximo de 1 por jugador.\nRespuesta: después de que derrotes a un Esbirro, agota la Sala de interrogatorios → quita 1 de Amenaza de un Plan.","f":"\"¡Ah, que lo sientes! Pues nada, ahora mismo te quito las esposas y te pido un taxi\" —Misty Knight"},
  "08016": {"n":"Equipo de vigilancia","t":"Usos (3 contadores de Escucha). (Entra en juego con 3 contadores. Cuando se acaben, descarta esta carta)\nAcción: agota el Equipo de vigilancia y quítale 1 contador de Escucha → quita 1 de Amenaza de un Plan."},
  "08017": {"n":"Contraespionaje","t":"Máximo de 1 por jugador.\nInterrupción: cuando vaya a colocarse cualquier cantidad de Amenaza sobre el Plan Principal, descarta Contraespionaje → evita 3 de esa Amenaza."},
  "08018": {"n":"Tácticas de infiltración","t":"Juega esta carta sólo si controlas un personaje ESPÍA.\nInterrupción: cuando muestres una carta de Encuentro, descarta Tácticas de infiltración → anula los efectos de esa carta y descártala. Luego muestra otra carta del mazo de Encuentros."},
  "08019": {"n":"Nick Furia","t":"Respuesta obligada: después de que Nick Furia entre en juego, elige una de estas opciones: quita 2 de Amenaza de un Plan, roba 3 cartas o inflige 4 de Daño a un enemigo. Al final de la ronda, si Nick Furia aún sigue en juego, descártalo."},
  "08020": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "08021": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "08022": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "08023": {"n":"Quintransporte","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo VENGADOR.\nRecurso: agota el Quintransporte → genera un recurso [wild].","f":"\"Lástima que sólo tengamos uno de esos.\" —Ojo de Halcón"},
  "08024": {"n":"Objetivo fijado","t":"Máximo de 1 por jugador.\nRespuesta de Héroe: después de que se ponga boca arriba una carta de aumento, descarta Objetivo fijado → anula la capacidad de aumento de esa carta."},
  "08025": {"n":"En la lista negra","t":"Dale esta carta al jugador que lleva a Natasha Romanoff\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n• Agota a Natasha Romanoff → retira del juego En la lista negra.\n• Descarta la carta de PLANIFICACIÓN que controles que tenga el coste más alto. Si no puedes hacerlo, esta carta gana Oleada. Descarta esta Obligación."},
  "08026": {"n":"Supervisor","t":"[star] El Supervisor recibe +1 PLA y +1 ATQ por cada mejora que controles.\n(Esbirro Archienemigo de la Viuda Negra.)\n[star] Aumento: Para esta activación, el Villano recibe +1 PLA y +1 ATQ por cada Mejora que controles."},
  "08027": {"n":"Asesino de alquiler","t":"Cuando se muestre esta carta: coloca 1[per_hero] de Amenaza adicional sobre esta carta."},
  "08028": {"n":"Mercenario de Hydra","t":"Guardia. (Mientras este Esbirro esté enfrentado a ti, no podrás atacar al Villano.)","f":"\"¿Qué hace Hydra aquí?\" —Carol Danvers"},
  "08029": {"n":"Disparo letal","t":"Cuando se muestre esta carta (Alter ego): descarta una Mejora que controles y coloca 1 de Amenaza sobre el Plan principal.\nCuando se muestre esta carta (Héroe): descarta una Mejora que controles y sufres 1 de Daño."},
  "08030": {"n":"Contraataque","t":"Máximo de 1 por jugador.\nRespuesta de Héroe (ataque): después de que sufras Daño infligido por un ataque enemigo, descarta Contraataque → inflige la misma cantidad de Daño a ese enemigo."},
  "08031": {"n":"Respuesta rápida","t":"Máximo de 1 por jugador.\nRespuesta de Héroe: después de que un Aliado que controles sea derrotado, descarta Respuesta rápida → pon en juego ese Aliado desde tu pila de descartes e inflígele 1 de Daño."},
  "08032": {"n":"Postura defensiva","t":"Máximo de 1 por jugador.\nInterrupción de Héroe: cuando vayas a sufrir cualquier cantidad de Daño, descarta Postura defensiva → evita 3 de ese Daño."},
  "08033": {"n":"Espionaje","t":"Juega esta carta sólo si controlas un personaje ESPÍA.\nInterrupción: cuando vaya a resolverse la palabra clave Oleada de una carta de Encuentro, descarta Espionaje → roba 2 cartas."},
  "09001a": {"n":"Doctor Extraño","t":"Dominio de la magia — Accción: agota al Doctor Extraño y paga el coste de la primera carta del mazo de INVOCACIÓN → resuelve la capacidad \"Especial\" de esa carta.","f":"\"¡Por las hirsutas huestes de Hoggoth!\""},
  "09001b": {"n":"Stephen Extraño","t":"Stephen Extraño empieza la partida con un mazo de INVOCACIÓN (ver hoja de reglas).\nTalento Innato — Acción: descarta la primera carta del mazo de INVOCACIÓN. (Límite de una vez por fase.)"},
  "09002": {"t":"Acción: agota a Wong → elige entre curar 1 de Daño a tu carta de Superhéroe o bien descartar la primera carta del mazo de INVOCACIÓN.","f":"\"El juramento que hice de proteger a mi amo anula cualquier otra directiva.\""},
  "09003": {"n":"Proyección astral","t":"Acción de Héroe (intervención): elige un Plan → quita 3 de Amenaza de ese Plan y mira la primera carta del mazo de Encuentros. Por cada icono de Aumento que haya en esa carta, quita 1 de Amenaza adicional del Plan elegido."},
  "09004": {"n":"Rayo mágico","t":"Acción de Héroe (ataque): inflige 5 de Daño a un enemigo y descarta la primera carta de tu mazo. Si el recurso impreso de esa carta tiene:\n[physical] - Aturde a ese enemigo.\n[energy] - Inflige 2 de Daño a ese enemigo.\n[mental] - Confunde a ese enemigo.\n[wild] - Todo lo anterior."},
  "09005": {"n":"Maestro de las artes místicas","t":"Acción de Héroe: paga el coste impreso de la primera carta del mazo de INVOCACIÓN → resuelve su capacidad \"Especial\". Luego colócala otra vez en la parte superior del mazo de INVOCACIÓN boca arriba.","f":"\"¡Nada es imposible para el Hechicero Supremo!\" —Doctor Extraño"},
  "09006": {"n":"Estudios místicos","t":"Acción de Alter ego: busca una carta del Doctor Extraño en tu mazo y en tu pila de descartes y añádela a tu mano. Baraja tu mazo.","f":"\"Creo que la observación y el saber deben preceder a la acción.\" —Doctor Extraño"},
  "09007": {"n":"Salvaguarda arcana","t":"Interrupción de Héroe: cuando se muestre una carta de Perfidia del mazo de Encuentros, anula todos sus efectos y descártala.","f":"\"Éste es uno de los primeros hechizos que aprendí.\" —Doctor Extraño"},
  "09008": {"n":"Sancta Sanctorum","t":"Acción de Alter ego: agota el Sancta Sanctorum → añade a tu mazo una carta HECHIZO que esté en tu pila de descartes, barájalo y roba 1 carta.","f":"\"Un poco ostentoso para la calla Bleecker, ¿no te parece?\" —Zelma Stanton"},
  "09009": {"n":"Capa de levitación","t":"Ganas el rasgo AÉREO.\nAcción de Héroe: agota la Capa de levitación → prepara al Doctor Extraño.","f":"\"Si te vas a hacer llamar 'Hechicero supremo', qué menos que tener una capa voladora.\" —Spiderman"},
  "09010": {"n":"Mejoras mágicas","t":"Juega esta carta poniéndola bajo el control de cualquier jugador.\nTu héroe recibe +1 INT, +1 ATQ y +1 DEF.\nInterrupción obligada: cuando termine la ronda, descarta Mejoras mágicas."},
  "09011": {"n":"El Ojo de Agamotto","t":"Recurso de Héroe: agota El Ojo de Agamotto → genera un recurso [wild].","f":"\"El Ojo de Agamotto revelará la verdad.\" —Doctor Extraño"},
  "09012": {"n":"Hermano Vudú","t":"Respuesta: después de que el Hermano Vudú entre en juego, busca una carta de Evento entre las 5 primeras cartas de tu mazo y añádela a tu mano. Baraja tu mazo.","f":"\"Me llamo Jericho Drumm. Me llaman Hermano Vudú.\""},
  "09013": {"t":"Interrupción: cuando Clea sea derrotada, devuélvela al mazo de su propietario y barájalo.","f":"\"Procedo de lo que tú llamas Dimensión Oscura. No me asusto con facilidad.\""},
  "09014": {"n":"Puño de Hierro","t":"Puño de Hierro entra en juego con 2 contadores Místicos.\nInterrupción: cuando Puño de Hierro ataque a un enemigo, quítale 1 contador Místico → aturde a ese enemigo e inflígele 1 de Daño."},
  "09015": {"n":"Defensa desesperada","t":"Interrupción de Héroe (defensa): cuando tu Héroe defienda contra un ataque, recibe +2 DEF para ese ataque. Si no sufres Daño a causa de ese ataque, prepara a tu Héroe."},
  "09016": {"n":"Invertir las tornas","t":"Acción de Héroe (ataque): cura 2 de Daño a tu Héroe → inflige 2 de Daño a un enemigo.","f":"\"¡Siéntate!\" —Colleen Wing"},
  "09017": {"n":"El poder de la protección","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta de Protección (verde)."},
  "09018": {"n":"Equipo médico","t":"Usos (3 contadores de Medicina). (Entra en juego con 3 contadores. Cuando se acaben, descarta esta carta.)\nAcción: agota al Equipo médico y quítale 1 contador de Medicina → cura 2 de Daño a un personaje amigo."},
  "09019": {"n":"La Enfermera de Noche","t":"Usos (3 contadores de Medicina).\nAcción: agota La Enfermera de Noche y quítale 1 contador de Medicina → cura 1 de Daño a un Héroe y descarta 1 carta de Estado que tenga asignada."},
  "09020": {"n":"Imperturbable","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nRespuesta: después de que defiendas contra un ataque y no sufrás Daño, agota Imperturbable → roba 1 carta."},
  "09021": {"n":"Alerta","t":"Interrupción (defensa): cuando un Héroe vaya a sufrur cualquier cantidad de Daño, reduce esa cantidad en 1.","f":"\"¡Nos atacan!\" —Iron Man"},
  "09022": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "09023": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "09024": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "09025": {"n":"Mansión de los Vengadores","t":"Máximo de 1 por jugador.\nAcción: agota la Mansión de los Vengadores → elige un jugador. Ese jugador roba 1 carta.","f":"\"¿Te has acordado de cerrar con llave?\" —Janet Van Dyne"},
  "09026": {"n":"El Hechicero Supremo","t":"Juega esta carta sólo si tienes el rasgo MÍSTICO.\nRecibes +1 al tamaño de tu mano mientras tengas adoptada tu identidad de Héroe.","f":"\"El Anciano me otorgó el título de Hechicero Supremo.\" —Stephen Extraño"},
  "09027": {"n":"Desgaste físico","t":"Dale esta carta al jugador que lleva a Stephen Extraño\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n• Agota a Stephen Extraño → retira del juego Desgaste físico.\n• El próximo Evento que jueges costará 3 recursos adicionales. Descarta esta Obligación después de que juegues un Evento."},
  "09028": {"n":"Barón Mordo","t":"Interrupción obligada: cuando el Barón Mordo te ataque, descarta la primera carta de tu mazo. Si el recurso impreso de esa carta tiene:\n[physical] - Quedas aturdido.\n[energy] - Sufres 2 de Daño.\n[mental] - Quedas confundido.\n[wild] - Todo lo anterior."},
  "09029": {"n":"Abrir un portal a la Dimensión Oscura","t":"Cuando se muestre esta carta: coloca la primera carta del mazo de INVOCACIÓN boca abajo debajo de este Plan.\nCuando se derrote esta carta: devuelve la carta de INVOCACIÓN que tiene debajo al mazo de INVOCACIÓN y barájalo."},
  "09030": {"n":"Contrahechizo","t":"Vincula esta carta a tu Héroe.\nInterrupción obligada: cuando juegues un Evento, anula sus efectos y descártalo. Luego descarta esta carta.","f":"\"Yo debería haber sido nombrado Hechicero Supremo, Extraño. ¡Yo, y no tú!\" —Barón Mordo."},
  "09031": {"n":"Intrusión mental","t":"Cuando se muestre esta carta (Alter ego): descarta una carta de tu mano que tenga el coste más alto. Coloca tanta Amenaza sobre el Plan principal como el coste impreso de esta carta.\nCuando se muestre esta carta (Héroe): descarta una carta de tu mano que tenga el coste más alto. Sufres tanto Daño como el coste impreso de esta carta."},
  "09032": {"n":"Bandas Carmesí de Cyttorak","t":"Especial: aturde a un enemigo e inflígele 7 de Daño. Coloca esta carta en la pila de descartes del mazo de INVOCACIÓN.","f":"\"Eso debería retenerlo de momento.\" —Doctor Extraño"},
  "09033": {"n":"Imágenes de Ikonn","t":"Especial: confunde al Villano y quita 3 de Amenaza de un Plan. Coloca esta carta en la pila de descartes del mazo de INVOCACIÓN.","f":"\"Sólo ves lo que yo quiero que veas.\" —Doctor Extraño"},
  "09034": {"n":"Siete Anillos de Raggador","t":"Especial: dale una carta de Estado \"Duro\" a un máximo de 3 personajes. Coloca esta carta en la pila de descartes del mazo de INVOCACIÓN.","f":"\"¡Que los Siete Anillos de Raggador te protejan!\" —Doctor Extraño"},
  "09035": {"n":"Vapores de Valtorr","t":"Especial: elige una carta de Estado que esté en juego. Sustituye esa carta de Estado por otra carta de Estado distinta.Coloca esta carta en la pila de descartes del mazo de INVOCACIÓN.","f":"\"¡Que los Vapores de Valtorr te transformen!\" —Doctor Extraño"},
  "09036": {"n":"Vientos de Watoomb","t":"Especial: roba 3 cartas. Coloca esta carta en la pila de descartes del mazo de INVOCACIÓN.","f":"\"¡Por los sagrados Vishanti!\" —Doctor Extraño"},
  "09037": {"n":"Golpe diestro","t":"Interrupción: cuando tu Héroe realice un ataque básico, recibe +2 ATA para ese ataque.","f":"\"Tienes mucho que aprender.\" —Karnak"},
  "09038": {"n":"¡No tan deprisa!","t":"Interrupción: cuando se ponga boca arriba una carta de aumento durante una activación para ejecutar el Plan, anula sus iconos de Aumento.","f":"\"¡Esta vez no, Kingpin!\" —Spiderman"},
  "09039": {"t":"Reduce en 1 el coste de cada Mejora que se juegue sobre Iron Man.","f":"\"Se me ocurren algunas ideas para mejorar aún más esta armadura.\""},
  "10001a": {"t":"Enfurecido — Interrupción obligada: cuando termine tu turno, descarta tu mano.","f":"\"Hulk no está arrepentido. Hulk es Hulk.\""},
  "10001b": {"t":"Investigación experimental — Acción: roba 1 carta. Elige 1 carta de tu mano y descártala. (Límite de una vez por ronda.)","f":"\"No hagas que me enfade. No te gustaría verme enfadado.\""},
  "10002": {"n":"Golpe aplastante","t":"Sólo puedes gastar recursos [physical] para pagar el coste de esta carta.\nAcción de Héroe (ataque): inflige tanto Daño a un enemigo como tu ATQ.","f":"\"Monstruo débil.\" —Hulk"},
  "10003": {"n":"Hulk aplasta","t":"Interrupción de Héroe: cuando realices un ataque básico, recibes +10 ATQ para ese ataque. Si has pagado el coste de esta carta exclusivamente con recursos [physical], ese ataque gana Brutalidad.","f":"\"¡Cuando Hulk aplasta algo, se queda aplastado!\" —Hulk"},
  "10004": {"n":"Salto suborbital","t":"Acción de Héroe (intervención): quita 3 de Amenaza de un Plan (5 de Amenaza si has pagado el coste de esta carta exclusivamente con recursos [physical]).","f":"\"¡Dejad en paz a Hulk!\" —Hulk"},
  "10005": {"n":"Palmada atronadora","t":"Acción de Héroe: elige hasta 3 enemigos distintos. Inflige 3 de Daño a cada uno de ellos.","f":"\"¿Te da miedo el viento de Hulk?\" —Hulk"},
  "10006": {"n":"Fuerza imparable","t":"Acción de Héroe: prepara a Hulk. Si has pagado el coste de esta carta exclusivamente con recursos [physical], roba 1 carta.","f":"\"¡Nadie detiene a Hulk!\" —Hulk"},
  "10007": {"n":"Fuerza ilimitada","t":"Gasta esta carta únicamente cuando tengas adoptada tu identidad de Héroe."},
  "10008": {"n":"Laboratorio de Banner","t":"Bruce Banner recibe +2 REC.\nRecurso de Alter ego: agota el Laboratorio de Banner → genera un recurso [mental].","f":"\"Lo mejor de mi laboratorio es que aquí nunca me molesta nadie.\" —Bruce Banner"},
  "10009": {"n":"Furia desatada","t":"Sólo identidad de Héroe. Hulk recibe +1 ATQ.\nRespuesta obligada: después de que cambies de identidad, descarta esta carta.","f":"\"Cuanto más me enfurezco, más fuerza tengo.\" —Bruce Banner"},
  "10010": {"n":"Objeto inamovible","t":"Recibes +4 de Vida.\nHulk gana Represalia 1.","f":"\"Hulk nunca cede. Nunca se rinde.\" —Hulk"},
  "10011": {"n":"Vigor","t":"Respuesta: después de que Vigor ataque, quita 1 de Amenaza de un Plan.","f":"\"Soy el más fuerte que existe. Y el más inteligente. Ésa es toda la autoridad que necesito.\""},
  "10012": {"n":"El Vigía","t":"Respuesta obligada: después de que El Vigía entre en juego controlado por ti, roba 1 carta de Encuentro.","f":"\"Cuando uso mis poderes de un millón de soles, desato el Vacío. Viene y ataca el mundo cada vez que yo intento salvarlo.\""},
  "10013": {"n":"Hulka","t":"[star] Hulka recibe +1 ATQ por cada ficha de Daño que haya sobre esta carta.","f":"\"Te pediría que te rindieses… pero la verdad es que esperamos que te resistas.\""},
  "10014": {"n":"Patada doble voladora","t":"Acción de Héroe (ataque): inflige 4 puntos de Daño a un enemigo. Si has pagado el coste de esta carta exclusivamente con recursos [physical], aturde a ese enemigo y roba 1 carta.","f":"\"¡Hulk se quedará a machacar al monstruo! !Es lo que saba hacer mejor!\" —Hulk"},
  "10015": {"n":"Cara a cara","t":"Acción de Héroe (ataque): elige un enemigo. Ese enemigo te ataca. Inflige 5 de Daño a ese Enemigo.","f":"\"¿Y si pruebas un poco de tu propia medicina?\" —Capitana Marvel"},
  "10016": {"n":"\"¡Pagarás por eso!\"","t":"Respuesta de Héroe (intervención): después de que el Villano te ataque, quita tanta Amenaza de un Plan como la cantidad de Daño que hayas sufrido a consecuencia de ese ataque (hasta un máximo de 5)."},
  "10017": {"n":"El poder de la agresividad","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta de Agresividad (roja)."},
  "10018": {"n":"Destreza marcial","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nRecurso: agota Destreza marcial → genera un recurso [physical] para un Evento que tenga el rasgo ATAQUE."},
  "10019": {"n":"¡Al rescate!","t":"Acción de Héroe (intervención): quita 2 de Amenaza de un Plan."},
  "10020": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "10021": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "10022": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "10023": {"n":"Mansión de los Vengadores","t":"Máximo de 1 por jugador.\nAcción: agota la Mansión de los Vengadores → elige un jugador. Ese jugador roba 1 carta.","f":"\"¿Te has acordado de cerrar con llave?\" —Janet Van Dyne"},
  "10024": {"n":"Helitransporte","t":"Máximo de 1 por jugador.\nAcción: agota el Helitransporte → elige un jugador. Reduce en 1 el coste en recursos de la siguiente carta jugada por ese jugador en esta fase.","f":"\"¿Un portaaviones volador? Estás de guasa, ¿no?\" —Jennifer Walters"},
  "10025": {"n":"Demonios interiores","t":"Dale esta carta al jugador que lleva a Bruce Banner.\nCambia de identidad (dale la vuelta a tu carta de Superhéroe). Luego:\n• Si eres Bruce Banner, descarta 2 cartas de tu mano. Descarta esta Obligación.\n• Si eres Hulk, agota tu Héroe. Descarta esta Obligación."},
  "10026": {"n":"Abominación","t":"[star] Respuesta obligada: después de que la Abominación te ataque, descarta la primera carta de tu mazo. Si se ha descartado un recurso [physical] de este modo, sufres 2 de daño.","f":"\"¡Escoria miserable! ¡Vuestras patéticas armas no son nada comparadas con mi nuevo poder!\""},
  "10027": {"n":"Destrucción total","t":"No puede quitarse Amenaza de este Plan mientras la Abominación esté en juego."},
  "10028": {"n":"Duelo de titanes","t":"Cuando se muestre esta carta: el enemigo que tenga la puntuación más alta de ATQ ataca al Héroe o Aliado que tenga la puntuación más alta de ATQ (en caso de empate, decide el jugador inicial). Si no se produce ningún ataque de este modo, esta carta gana Oleada.","f":"\"¡Eres inferior! ¡Como todos los demás!\" —Abominación"},
  "10029": {"n":"Policía de barrio","t":"Acción: agota a la Policía de barrio → traslada 1 de Amenaza desde un Plan hasta esta carta.\nAcción: agota a la Policía de barrio y descártala → inflige tanto Daño a un Esbirro como la cantidad de Amenaza que haya sobre esta carta."},
  "10030": {"n":"Presencia inspiradora","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo VENGADOR.\nAcción de Héroe: cura 1 de Daño a un Aliado y prepáralo."},
  "10031": {"n":"Armadura electrostática","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nRespuesta: después de que defiendas contra un ataque, inflige 1 de Daño al personaje atacante."},
  "10032": {"n":"Ingenio","t":"Recurso: descarta Ingenio → genera un recurso [wild]","f":"\"La innovación es el arma definitiva.\" —Visión"},
  "11001": {"n":"Kang (El Conquistador)","t":"Dureza.\n[star] Interrupción obligada: cuando Kang te ataque, elige entre colocar 1 de Amenaza sobre el Plan principal o que Kang recuba +2 ATQ para este ataque.\nCuando se derrote esta carta: el Plan principal avanza a la etapa 2 al final de la fase."},
  "11002": {"n":"Kang (Inmortus)","t":"Dureza.\nEste Villano no puede sufrir Daño mientras haya en juego un Esbirro.\nCuando se derrote esta carta: retira del juego Cronópolis. Al final de la fase, únete a otra zona de partida."},
  "11003": {"t":"Represalia 1. Dureza.\nCuando se derrote esta carta: retira del juego Destino inexorable. Al final de la fase, únete a otra zona de partida."},
  "11004": {"t":"Dureza.\n[star] Este Villano recibe +1 ATQ por cada Obligación que haya en juego.\nCuando se derrote esta carta: retira del juego En el reino de Rama-Tut. Al final de la fase, únete a otra zona de partida."},
  "11005": {"n":"Kang (Centurión Escarlata)","t":"Dureza.\n[star] Los ataques de este Villano ganan Penetrante.\nCuando se derrote esta carta: retira del juego La actual guerra del futuro. Al final de la fase, únete a otra zona de partida."},
  "11006": {"n":"Kang (El Conquistador)","t":"Dureza.\n[star] Interrupción obligada: cuando Kang te ataque, elige entre colocar 1 de Amenaza sobre el Plan principal o que Kang reciba +2 ATQ para este ataque.\nCuando se derrote esta carta: los jugadores ganan la partida."},
  "11007a": {"n":"La llegada de Kang","t":"Contenido: Kang (I), todos los Kang (II), and Kang (III). Conjuntos de Encuentro de Kang y Normal. Un conjunto de Encuentros modular (Temporal).\nPreparación: aparta a un lado todas las cartas de Kang (II), Kang (III), y el Plan secundario \"El dominio de Kang\". Retira del juego las cartas de Obligación de cada jugador. Baraja el mazo de Encuentros."},
  "11007b": {"n":"La llegada de Kang","t":"Cuando se muestre esta carta: dale una carta de Encuentro a cada jugador.\nSi se completa esta etapa, los jugadores pierden la partida.","f":"Kang cree que, si derrota a los héroes más poderosos de la Tierra, el resto del planeta se someterá a su reinado."},
  "11008a": {"n":"El amo del tiempo","t":"Cuando se muestre esta carta: coloca 1 ficha de Aceleración sobre esta carta por cada Plan secundario que haya en juego, luego descarta todos los Planes secundarios. Cada jugador muestra una etapa 3A al azar, siguiendo el orden de jugadores. Retira del juego todos los Planes de etapa 3 que no se hayan utilizado.","f":"Kang ha recibido un duro golpe, pero logra salvarse separando a los héroes a través del tiempo y el espacio."},
  "11008b": {"n":"El amo del tiempo","t":"Interrupción obligada: cuando vaya a colocarse una ficha de Aceleración sobre otro Plan, en vez de eso se coloca sobre esta carta.\nNingún jugador puede unirse a esta zona de partida a menos que sea la única que queda. Cuando todos los jugadores se hayan unido a esta zona de partida, este Plan avanza a la etapa 4A."},
  "11009a": {"n":"Cronópolis","t":"Cuando se muestre esta carta: crea tu propia zona de partida y coloca este Plan en ella. Añade a Kang (Inmortus) a la zona de partida y coge una carta de Encuentro."},
  "11009b": {"n":"Cronópolis","t":"Respuesta obligada: después de que se complete esta etapa, coloca 1 copia apartada de El dominio de Kang boca abajo debajo de la etapa 4A. Al final de la fase, retira del juego a Kang (Inmortus) y esta etapa, y combina tu zona de partida con otra zona de partida.\nSi todos los jugadores presentes en esta etapa son derrotados, esta etapa se completa."},
  "11010a": {"n":"Destino inexorable","t":"Cuando se muestre esta carta: crea tu propia zona de partida y coloca este Plan en ella. Añade a Kang (Iron Lad) a la zona de partida y coge una carta de Encuentro."},
  "11010b": {"n":"Destino inexorable","t":"Respuesta obligada: después de que se complete esta etapa, coloca 1 copia apartada de El dominio de Kang boca abajo debajo de la etapa 4A. Al final de la fase, retira del juego a Kang (Iron Lad) y esta etapa, y combina tu zona de partida con otra zona de partida.\nSi todos los jugadores presentes en esta etapa son derrotados, esta etapa se completa."},
  "11011a": {"n":"En el reino de Rama-Tut","t":"Cuando se muestre esta carta: crea tu propia zona de partida y coloca este Plan en ella. Añade a Kang (Rama-Tut) a la zona de partida y coge una carta de Encuentro."},
  "11011b": {"n":"En el reino de Rama-Tut","t":"Respuesta obligada: después de que se complete esta etapa, coloca 1 copia apartada de El dominio de Kang boca abajo debajo de la etapa 4A. Al final de la fase, retira del juego a Kang (Rama-Tut) y esta etapa, y combina tu zona de partida con otra zona de partida.\nSi todos los jugadores presentes en esta etapa son derrotados, esta etapa se completa."},
  "11012a": {"n":"La actual guerra del futuro","t":"Cuando se muestre esta carta: crea tu propia zona de partida y coloca este Plan en ella. Añade a Kang (Centurión Escarlata) a la zona de partida y coge una carta de Encuentro."},
  "11012b": {"n":"La actual guerra del futuro","t":"Respuesta obligada: después de que se complete esta etapa, coloca 1 copia apartada de El dominio de Kang boca abajo debajo de la etapa 4A. Al final de la fase, retira del juego a Kang (Centurión Escarlata) y esta etapa, y combina tu zona de partida con otra zona de partida.\nSi todos los jugadores presentes en esta etapa son derrotados, esta etapa se completa."},
  "11013a": {"n":"La ira de Kang","t":"Cuando se muestre esta carta: muestra Kang (III) y añádelo a la zona de partida. Muestra todas las copias de El dominio de Kang que estén boca abajo debajo de esta etapa.","f":"Habéis utilizado la tecnología de vuestro enemigo para reuniros en el presente, justo a tiempo para responder a la ofensiva de Kang contra la Tierra."},
  "11013b": {"n":"La ira de Kang","t":"Cuando se muestre esta carta: cada jugador busca su Esbirro Archienemigo en el mazo de Encuentros, la pila de descartes y la zona apartada y lo pone en juego enfrentado a él. Baraja el mazo de Encuentros.\nSi se completa esta etapa, los jugadores pierden la partida."},
  "11014": {"n":"Escudo temporal","t":"Vincula esta carta a Kang.\nInterrupción obligada: cuando Kang sea atacado, descarta Escudo temporal → evita todo el Daño de este ataque e inflige 1 de Daño al atacante. (Máximo de 1 por ataque.)","f":"\"¡Deponed esas armas pueriles! ¡Para mí son sólo juguetes!\" - Kang"},
  "11015": {"n":"Arma del futuro","t":"Vincula esta carta a Kang.\n[star] Interrupción obligada: cuando Kang ataque, su ataque gana Brutalidad. Si este ataque inflige Daño a un Héroe, éste queda aturdido. Después de este ataque, descarta Arma del futuro.","f":"\"¡Como yo, sabéis que el combate significa algo y el honor más!\" - Kang"},
  "11016": {"n":"Congelado en el tiempo","t":"Vincula esta carta a tu Superhéroe.\nInterrupción obligada: cuando el personaje vinculado vaya a prepararse, en vez de eso descarta esta carta.\n[star] Aumento: Vincula esta carta a tu Superhéroe."},
  "11017": {"t":"Guardia. Represalia 1.\n[star] Aumento: dale a Kang una carta de Estado \"Duro\"."},
  "11018": {"n":"Debilitado","t":"Respuesta obligada: después de que uses un atributo básico de Héroe, sufres 1 de Daño.\nAcción de Alter ego: descarta un recurso [physical] de tu mano → descarta esta Obligación.","f":"\"¡La historia se hace! ¡Por los hechos de los fuertes! ¡Y los valientes! ¡Y el destino se forja!\" - Kang"},
  "11019": {"n":"Recuerdos robados","t":"Cuando se muestre esta carta: coloca las 8 primeras cartas de tu mazo boca abajo debajo de esta carta.\nAcción de Alter ego: descarta un recurso [mental] de tu mano → descarta esta Obligación. (Todas las cartas que haya boca abajo debajo de esta Obligación se descartan.)"},
  "11020": {"n":"Sin poderes","t":"No puedes jugar cartas específicas de Héroes.\nAcción de Ater ego: descarta una carta específica de un Héroe de tu mano → descarta esta Obligación.","f":"\"Hombres mejores que tú tiemblan al oír mi nombre. ¡Y los peores se desmayan al oírlo!\" - Kang"},
  "11021": {"n":"Enredos temporales","t":"Cuando se muestre esta carta: descarta ña carta de mayor coste que controles y luego colócala boca abajo debajo de esta carta.\nAcción de Alter ego: descarta un recurso [energy] de tu mano → descarta esta Obligación. (Todas las cartas que haya boca abajo debajo de esta Obligación se descartan.)"},
  "11022": {"n":"Flujo temporal corrompido","t":"Los jugadores no pueden aplicar las capacidades de tipo \"Acción de Alter ego\" que haya en las cartas de Obligación.\nCuando se muestre esta carta: cada jugador debe elegir entre descartar 1 carta al azar de su mano o bien colocar 2 de Amenaza sobre esta carta."},
  "11023": {"n":"El dominio de Kang","t":"Kang no puede sufrir Daño.\nCuando se derrote esta carta: dale una carta de Encuentro al jugador que haya derrotado este Plan.","f":"\"¡El futuro pertenece a Kang! ¡A Kang!\" - Kang"},
  "11024": {"n":"Retenido","t":"Cuando se muestre esta carta: coloca 2 de Amenaza sobre esta carta por cada Obligación que haya en juego."},
  "11025": {"n":"Desbocado","t":"Cuando se derrote esta carta: descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Esbirro. Pon en juego ese Esbirro enfrentado al jugador que haya derrotado este Plan."},
  "11026": {"n":"Rayo de energía","t":"Cuando se muestre esta carta (Alter ego): descarta un Aliado o Apoyo que controles. Si no puedes hacerlo, esta carta gana Oleada.\nCuando se muestre esta carta (Héroe): Kang te ataca."},
  "11027": {"n":"Manipular el flujo temporal","t":"Cuando se muestre esta carta: descarta todos los Eventos de tu mano. Si no se descarta ningún Evento de este modo, esta carta gana Oleada.","f":"\"¡Son los conquistadores quienes cambian el mundo!.\" - Kang"},
  "11028": {"n":"Tácticas de viaje en el tiempo","t":"Oleada.\nCuando se muestre esta carta: cada jugador sufre 1 de Daño indirecto por cada Obligación que haya en su zona de juego.\n[star] Aumento: esta carta gana [boost] por cada Obligación que haya en tu zona de juego."},
  "11029": {"n":"Designios del pasado","t":"Incitar 1. (Cuando se muestre esta carta, coloca 1 de Amenaza sobre el Plan principal.)\nCuando se muestre esta carta: cada jugador busca una Obligación distinta en el mazo y la pila de descartes de Encuentros y la muestra. Baraja el mazo de Encuentros."},
  "11030": {"n":"Guerrero de la antigüedad","t":"Ataque veloz.\n[star] Aumento: quedas aturdido."},
  "11031": {"n":"Soldado chitauri","t":"[star] Interrupción obligada: cuando el Soldado chitauri te ataque, descarta la primera carta del mazo de Encuentros → sufres tanto Daño indirecto como el número de iconos de Aumento que haya en esa carta."},
  "11032": {"n":"Tiranosaurio rex","t":"Dureza.\n[star] Los ataques del Tiranosaurio rex ganan Penetrante."},
  "11033": {"n":"Portal a través del tiempo","t":"Interrupción obligada: cuando se derrote este Plan, barájalo junto con el mazo de Encuentros en vez de descartarlo."},
  "11034": {"n":"Kang (El Conquistador)","t":"Dureza.\n[star] Interrupción obligada: cuando Kang te ataque, elige entre colocar 1 de Amenaza sobre el Plan principal o que Kang reciba +2 ATQ para este ataque.\nCuando se derrote esta carta: el Plan principal avanza a la etapa 2 al final de la fase."},
  "11035": {"n":"Kang (Inmortus)","t":"Dureza.\nEste Villano no puede sufrir Daño mientras haya en juego un Esbirro.\nCuando se derrote esta carta: retira del juego Cronópolis. Al final de la fase, únete a otra zona de partida."},
  "11036": {"t":"Represalia 1. Dureza.\nCuando se derrote esta carta: retira del juego Destino inexorable. Al final de la fase, únete a otra zona de partida."},
  "11037": {"t":"Dureza.\n[star] Este Villano recibe +1 ATQ por cada Obligación que haya en juego.\nCuando se derrote esta carta: retira del juego En el reino de Rama-Tut. Al final de la fase, únete a otra zona de partida."},
  "11038": {"n":"Kang (Centurión Escarlata)","t":"Dureza.\n[star] Los ataques de este Villano ganan Penetrante.\nCuando se derrote esta carta: retira del juego La actual guerra del futuro. Al final de la fase, únete a otra zona de partida."},
  "11039": {"n":"Kang (El Conquistador)","t":"Dureza.\n[star] Interrupción obligada: cuando Kang te ataque, elige entre colocar 1 de Amenaza sobre el Plan principal o que Kang reciba +2 ATQ para este ataque.\nCuando se derrote esta carta: Lo jugadores ganan la partida."},
  "11040": {"n":"Apócrifus","t":"Cuando se muestre esta carta: descarta un Aliado o Apoyo que controles.\n[star] Aumento: agota un personaje que controles. Dale otra carta de aumento a este enemigo."},
  "11041": {"n":"Caza Mortal 9000","t":"Dureza. Infame. (Cuando este Esbirro se active, dale una carta de aumento.)\n[star] Aumento: dale a este enemigo una carta de Estado \"Duro\" y otra carta de aumento."},
  "11042": {"t":"Guardia. Represalia 1.\n[star] Aumento: sufres 1 de Daño. Dale otra carta de aumento a este enemigo."},
  "11043": {"t":"Ataque veloz.\n[star] Los ataques de Terminatrix ganan Penetrante.\n[star] Aumento: dale otras 2 cartas de aumento a este enemigo."},
  "11044": {"t":"Cuando se muestre esta carta: descarta 1 carta al azar de tu mano.\n[star] Aumento: descarta 1 carta al azar de tu mano. Dale otra carta de aumento a este enemigo."},
  "11045": {"n":"Los Anacronautas","t":"Cuando se derrote esta carta: devuelve al mazo de Encuentros todas las cartas TEMPORAL que haya en su pila de descartes y barájalo."},
  "11046": {"n":"Los elegidos de Kang","t":"Incitar 1. (Cuando se muestre esta carta, coloca 1 de Amenaza sobre el Plan principal.)\nCuando se muestre esta carta: descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Esbirro TEMPORAL. Muestra ese Esbirro."},
  "11047": {"n":"Kang (Amo del tiempo)","t":"Dureza. Infame. (Cuando este Esbirro se active, dale una carta de aumento.)\nKang (Amo del tiempo) recibe +1 PLA y +1 ATQ por cada Obligación que haya en tu zona de juego."},
  "11048": {"n":"Soldado de otra época","t":"Incitar 1. Oleada.\n[star] Aumento: coge 1 carta de Encuentro boca abajo."},
  "11049": {"n":"Miedo a Kang","t":"No puedes atacar a Kang.\nAcción de Alter ego: descarta una carta al azar de tu mano → descarta esta Obligación."},
  "11050": {"n":"La esfera con la luz de los siglos","t":"Cuando se derrote esta carta: descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Esbirro. Pon en juego ese Esbirro enfrentado al jugador que haya derrotado este Plan."},
  "11051": {"n":"Antigua rencilla","t":"Cuando se muestre esta carta: Kang (Amo del tiempo) se activa contra ti. Si Kang (Amo del tiempo) no está en juego, búscalo en el mazo y la pila de descartes de Encuentros y ponlo en juego enfrentado a ti. Baraja el mazo de Encuentros."},
  "12001a": {"n":"Hombre Hormiga","t":"Insecto irritante — Respuesta: después de que cambies a esta identidad, quita 1 de Amenaza de un Plan.","f":"\"¿Por qué no te metes con alguien de tu tamaño?\""},
  "12001b": {"t":"Tiempo para relajarse — Respuesta: después de que cambies a esta identidad, cura 1 de Daño a Scott Lang.","f":"\"Ser el héroe de Cassie es lo que siempre he querido en la vida.\""},
  "12001c": {"n":"Hombre Hormiga","t":"Molestia mayúscula — Respuesta: después de que cambies a esta identidad, inflige 1 de Daño a un enemigo.","f":"\"¡El chiquitín ya no es pequeño!\""},
  "12002": {"n":"Avispa","t":"Respuesta de Héroe: después de que la Avispa entre en juego, inflige 2 de Daño a un enemigo si tu identidad de Héroe es Gigante, o quita 2 de Amenaza de un Plan si tu identidad de Héroe es Diminuto."},
  "12003": {"n":"Pisotón de gigante","t":"Juega esta carta sólo si tu identidad de Héroe es Gigante.\nAcción de Héroe (ataque): inflige 1 de Daño a cada Esbirro. Inflige 8 de Daño a un enemigo.","f":"\"Yo de ti echaría a correr.\" - Scott Lang"},
  "12004": {"n":"Mente colmena","t":"Juega esta carta sólo si tu identidad de Héroe es Diminuto.\nAcción de Héroe (intervención): quita 2 de Amenaza de un Plan. Quita 1 de Amenaza adicional de ese Plan por cada Apoyo \"Ejército de hormigas\" que controles."},
  "12005": {"n":"Cambio de tamaño","t":"Acción de Héroe: cambia a tu otra identidad de Héroe. Roba 1 carta.","f":"\"¡Esto es una pasada!\" - Scott Lang"},
  "12006": {"n":"Partículas Pym","t":"Respuesta de Héroe: después de que gastes esta carta, cura 2 de Daño a tu Héroe si tu identidad de Héroe es Gigante, o roba 1 carta si tu identidad de Héroe es Diminuto."},
  "12007": {"n":"Ejército de hormigas","t":"Acción de Héroe: si tu identidad de Héroe es Diminuto, agota Ejército de hormigas → inflige 1 de Daño a un enemigo.","f":"\"¡Hormigadores, reuníos!\" - Scott Lang"},
  "12008": {"n":"Casco del Hombre Hormiga","t":"Respuesta de Héroe: después de que cambies a tu identidad de Héroe Gigante, cura 2 de Daño a tu Héroe.\nRespuesta de Héroe: después de que cambies a tu identidad de Héroe Diminuto, roba 1 carta."},
  "12009": {"n":"Fuerza de gigante","t":"Respuesta de Héroe: después de que cambies a tu identidad de Héroe Gigante, recibes +1 ATQ hasta el final de este turno.","f":"\"A mi hija se la ha perdido el móvil. Y he pensado que a lo mejor estaba debajo de estos edificios.\" - Scott Lang"},
  "12010": {"n":"Guantes de descargas","t":"Acción de Héroe: si tu identidad de Héroe es Gigante, agota los Guantes de descargas y gasta recursos [physical][physical] → aturde a un enemigo.\nAcción de Héroe: si tu identidad de Héroe es Diminuto, agota los Guantes de descargas y gasta recursos [energy][energy] → confunde a un enemigo."},
  "12011": {"n":"Hombre Hormiga","t":"El Hombre Hormiga recibe +1 de Vida por cada contador Pym que tenga encima.\nInterrupción: cuando el Hombre Hormiga entre en juego, coloca 1 contador Pym sobre su carta (hasta un máximo de 4) por cada recurso que hayas pagado de más al cubrir su coste."},
  "12012": {"n":"Hombre Gigante","t":"El Hombre Gigante recibe +2 ATQ mientras tenga al menos 3 de Vida restante.","f":"\"El tamaño no lo es todo. A menos que tengas que pasar por encima de un puente.\""},
  "12013": {"t":"Ronin recibe +1 INT y +1 ATQ mientras tenga vinculada una mejora.","f":"\"No sé quién llevará el traje ahora, pero está claro que sabe como manejarse en una pelea.\" - Spectrum"},
  "12014": {"n":"Aguijón","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Vengador.\nAguijón no se cuenta de cara a tu límite de Aliados."},
  "12015": {"n":"Pedir ayuda","t":"Acción de Héroe: descarta cartas de la parte superior de tu mazo hasta que descartes un Aliado Vengador, luego añade ese Aliado a tu mano.","f":"\"¿Has llamado?\" - Tony Stark"},
  "12016": {"n":"Aplomo","t":"Respuesta de Héroe: después de que cambies de identidad, tu Héroe recibe +1 INT, +1 ATQ y +1 DEF hasta el final de la ronda.","f":"\"Si te metes con uno de nosotros, ¡te las ves con todos! Aunque sea el último.\" - Nova"},
  "12017": {"n":"Guanteletes de energía","t":"Vincula esta carta a un Aliado Vengador. Máximo de 1 por Aliado.\nRespuesta: después de que el Aliado vinculado ataque o intervenga, inflige 1 de Daño a un enemigo."},
  "12018": {"n":"Traje reforzado","t":"Vincula esta carta a un Aliado. Máximo de 1 por Aliado.\nEl Aliado vinculado recibe +2 de Vida.","f":"\"Recuerda que el poder no está en el traje, sino en el uso que le das.\" - Hank Pym"},
  "12019": {"n":"Primeros auxilios","t":"Acción: cura 2 de Daño a cualquier personaje.","f":"\"¿Sigue llamándose 'primeros auxilios' si es ya el segundo día que me paso en el hospital?\" —Clint Barton"},
  "12020": {"n":"Tácticas de enjambre","t":"Equipo (Hombre Hormiga y Avispa). Máximo de 1 por mazo.\nAcción de Héroe: cambia a tu otra identidad de Héroe. Prepara a tu Héroe."},
  "12021": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "12022": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "12023": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "12024": {"n":"Espíritu de equipo","t":"Acción de Héroe: agota Espíritu de equipo → juega una carta de tu mano que tenga un rasgo en común con tu Héroe, reduciendo en 1 su coste en recursos."},
  "12025": {"n":"Cuidar de Cassie","t":"Dale esta carta al jugador que lleva a Scott Lang.\nPuedes adoptar la identidad de tu Alter Ego. Elige una opción:\n• Agota a Scott Lang → retira del juego Cuidar de Cassie.\n• Elige 1 carta de tu mano y descártala. No puedes cambiar de identidad hasta que termine tu próximo turno. Descarta esta Obligación."},
  "12026": {"n":"Robo de tecnología","t":"Todas las cartas de Jugador que posean el rasgo Tecnología se tratan como si su texto de reglas impreso estuviese en blanco.","f":"Chaqueta Amarilla ha robado la valiosísima tecnología de partículas Pym."},
  "12027": {"n":"Chaqueta Amarilla","t":"Mientras tu identidad de Héroe sea Gigante, Chaqueta Amarilla gana el rasgo Gigante y Represalia 1.\nMientras tu identidad de Héroe sea Diminuto, Chaqueta Amarilla gana el rasgo Diminuto y recibe +1 ATQ.\n(Esbirro Archienemigo del Hombre Hormiga)."},
  "12028": {"n":"Aumento de tamaño","t":"Vincula esta carta a Chaqueta Amarilla si es posible. Si no es posible, vincula esta carta al Villano.\nUsos (3 contadores de Tamaño).\n[star] Respuesta obligada: después de que el enemigo vinculado se active, quita 1 contador de Tamaño de esta carta."},
  "12029": {"n":"El plan de Chaqueta Amarilla","t":"Cuando se muestre esta carta: descarta cartas del mazo de Encuentros hasta que se descarte de este modo una carta del conjunto de Archienemigo del Hombre Hormiga. Muestra esa carta.","f":"\"¡¿Crees que puedes detener el futuro?!\" - Chaqueta Amarilla"},
  "12030": {"n":"Momento triunfal","t":"Respuesta de Héroe: después de que ataques y derrotes a un enemigo, cura 1 de Daño a tu Héroe por cada punto de Daño sobrante infligido a ese enemigo mediante ese ataque."},
  "12031": {"n":"Imponer la ley","t":"Respuesta de Héroe (intervención): después de que cambies de identidad, quita 3 de Amenaza de un Plan (4 de Amenaza si has pagado el coste de esta carta usando un recurso [mental]).","f":"\"¡Que esto te sirva de lección!\" - Capitán América"},
  "12032": {"n":"Armarse de valor","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Vengador.\nAcción de Héroe: dale una carta de Estado \"Duro\" a no más de X personajes amigos (hasta un máximo de 3 personajes), siendo X igual al número de la etapa del Villano."},
  "12033": {"n":"Evaluar la situación","t":"Acción: recibes +1 al tamaño de tu mano hasta el final de la fase.","f":"\"Bueno, si huyo, no molo. Y si me quedo y me zumban… tampoco. Es un dilema.\" - Tony Stark"},
  "13001a": {"n":"Avispa","t":"Pequeña pero poderosa — Respuesta: después de que la Avispa (o un Evento jugado por ti) derrote a un Esbirro o Plan secundario, inflige 1 de Daño al Villano.","f":"\"¡Deberíais aprender a llevaros bien con los demás!\""},
  "13001b": {"t":"C.H.I.C.A. — Acción: coge hasta 2 cartas de tu pila de descartes que tengan impreso un recurso [mental], añádelas a tu mazo y barájalo. (Límite de una vez por ronda.)","f":"\"C.H.I.C.A. se dedica a buscar mujeres brillantes que no sólo salvarán el mundo, sino que lo cambiarán.\""},
  "13001c": {"n":"Avispa","t":"[star] La Amenaza que quites usando tu atributo básico de Intervención (INT) puede quitarse de varios Planes en la proporción que elijas.\n[star] El Daño que inflijas usando tu atributo básico de Ataque (ATQ) puede repartirse entre varios enemigos en la proporción que elijas.","f":"\"¡Ay, qué pequeñitos y qué monos que estáis!\""},
  "13002": {"n":"Hombre Hormiga","t":"Mientras tu identidad de Héroe sea Gigante, el Hombre Hormiga gana el rasgo Gigante y recibe +1 ATQ.\nMientras tu identidad de Héroe sea Diminuto, el Hombre Hormiga gana el rasgo Diminuto y recibe +1 INT."},
  "13003": {"n":"De gran ayuda","t":"Acción de Héroe (intervención): quita 3 de Amenaza de un Plan (quita un total de 4 de Amenaza repartido entre varios Planes de tu elección si tu identidad de Héroe es Gigante).","f":"\"¡Ha sido un placer ayudaros!\" - Avispa"},
  "13004": {"n":"Golpe certero","t":"Acción de Héroe (ataque): inflige 7 de Daño a un enemigo. Si tu identidad de Héroe es Diminuto, este ataque inflige 1 de Daño adicional a ese enemigo y gana Brutalidad.","f":"\"Más te vale ponerte algo de hielo si no quieres que se te hinche.\" - Avispa"},
  "13005": {"n":"Crecimiento rápido","t":"Interrupción de Héroe: cuando uses uno de los atributos básicos de tu Héroe (INT, ATQ o DEF), cambia a tu identidad de Héroe Gigante y recibe +2 a ese atributo para este uso.","f":"\"Seguro que no esperabas ver algo así.\" - Avispa"},
  "13006": {"n":"Aguijón de avispa","t":"Acción de Héroe (ataque): si tu identidad de Héroe es Gigante, inflige un total de 4 de Daño repartido entre enemigos de tu elección.\nAcción de Héroe (ataque): si tu identidad de Héroe es Diminuto, inflige 5 de Daño a un enemigo."},
  "13007": {"n":"Partículas Pym","t":"Respuesta de Héroe: después de que gastes esta carta, cura 2 de Daño a tu Héroe si tu identidad de Héroe es Gigante, o roba 1 carta si tu identidad de Héroe es Diminuto."},
  "13008": {"n":"Entrenamiento en la Sala Roja","t":"Mientras tu identidad de Héroe sea Gigante, ganas Represalia 1.\nMientras tu identidad de Héroe sea Diminuto, tus ataques básicos ganan Penetrante."},
  "13009": {"n":"Alas biosintéticas","t":"La Avispa gana el rasgo Aéreo.\nInterrupción: cuando vayas a sufrir cualquier cantidad de Daño, si tu identidad de Héroe es Diminuto, agota Alas biosintéticas → evita 1 de ese Daño."},
  "13010": {"n":"Casco de la Avispa","t":"Mientras tu identidad de Héroe sea Gigante, recibes +1 INT.\nMientras tu identidad de Héroe sea Diminuto, recibes +1 ATQ."},
  "13011": {"t":"Respuesta: después de que juegues a Thor desde tu mano, inflige 2 de Daño al Villano (3 de Daño si has pagado el coste de esta carta usando un recurso [physical]).","f":"\"¿Quieres comerte mi martillo? Pues adelante… ¡dale un mordisco!\""},
  "13012": {"n":"Avispa","t":"La Avispa recibe +1 de Vida por cada contador Pym que tenga encima.\nInterrupción: cuando la Avispa entre en juego, coloca 1 contador Pym sobre su carta (hasta un máximo de 3) por cada recurso [energy] que hayas pagado de más al cubrir su coste."},
  "13013": {"n":"Entrar en combate","t":"Acción de Héroe (ataque): inflige 6 de Daño a un Esbirro. Por cada punto de Daño sobrante infligido por este ataque, quita 1 de Amenaza del Plan principal."},
  "13014": {"n":"Ataque sorpresa","t":"Respuesta de Héroe (ataque): después de que cambies de identidad, inflige 3 de Daño a un enemigo (4 de Daño si has pagado el coste de esta carta usando un recurso [physical])."},
  "13015": {"n":"El poder de la agresividad","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta de Agresividad (roja)."},
  "13016": {"n":"Centro de entrenamiento","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nCada Aliado que controles recibe +1 ATQ.","f":"\"¡¿A ESO LLAMAS HACER FLEXIONES?! ¡HASTA MI ABUELA LAS HACE MEJOR!\""},
  "13017": {"n":"Al acecho","t":"Máximo de 1 por jugador.\nRespuesta de Héroe (ataque): después de que un Esbirro se enfrente a ti, descarta Al acecho → inflige 3 de Daño a ese esbirro."},
  "13018": {"t":"Respuesta: después de que juegues a Ironheart desde tu mano, roba 1 carta.","f":"\"Voy a ser Tony Stark completamente. Salvo por ese vello facial absurdo.\""},
  "13019": {"n":"Spiderman","t":"Respuesta: después de que juegues a Spiderman desde tu mano, elige entre INT o ATQ. Spiderman recibe +2 para el atributo elegido hasta el final de la fase.","f":"\"La gente me necesita. Y sólo por eso, ya no hay nada más importante.\""},
  "13020": {"n":"Tácticas de enjambre","t":"Equipo (Hombre Hormiga y Avispa). Máximo de 1 por mazo.\nAcción de Héroe: cambia a tu otra identidad de Héroe. Prepara a tu Héroe."},
  "13021": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "13022": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "13023": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "13024": {"n":"El poder de todos unidos","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta Básica (gris)."},
  "13025": {"n":"Quintransporte","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo VENGADOR.\nRecurso: agota el Quintransporte → genera un recurso [wild].","f":"\"Lástima que sólo tengamos uno de esos.\" —Ojo de Halcón"},
  "13026": {"n":"Sueños rojos","t":"Dale esta carta al jugador que lleva a Nadia Van Dyne.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n• Agota a Nadia Van Dyne → retira del juego Sueños rojos.\n• Descarta de tu mano todas las cartas que tengan impreso un recurso [mental] y sufre 1 de Daño. Descarta esta Obligación."},
  "13027": {"n":"Órdenes de Madre","t":"Como coste adicional para que un Héroe efectúe un ataque básico, ese Héroe debe gastar 1 recurso de cualquier tipo.","f":"Madre ha enviado a una de sus mejores agentes tras la Avispa, con la esperanza de volver a capturar a la heroína tras fugarse de la Sala Roja."},
  "13028": {"n":"Escarabajo","t":"Guardia.\nInterrupción obligada: cuando la Escarabajo sea derrotada, elige entre gastar un recurso [physical] o bien añadir la Escarabajo al mazo de Encuentros y barajarlo."},
  "13029": {"n":"Armadura de Escarabajo MK IV","t":"Vincula esta carta a la Escarabajo si es posible. Si no es posible, vincula esta carta al Villano.\nEl personaje vinculado recibe +4 de Vida.","f":"\"¡Uf! ¡Aquí no hay quien encuentre nunca nada!\" - Janice Lincoln"},
  "13030": {"n":"La obsesión de la Escarabajo","t":"Cuando se muestre esta carta (Alter ego): esta carta gana Oleada.\nCuando se muestre esta carta (Héroe): la Escarabajo te ataca con +1 ATQ. Si no se produce ningún ataque de este modo, esta carta gana Oleada.","f":"\"Estaba esperando que llegase este momento.\" - Escarabajo"},
  "13031": {"n":"Impedimentos","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Vengador.\nAcción de Héroe (intervención): quita 2 de Amenaza del Plan princial. Quita X de Amenaza adicional del Plan principal (hasta un máximo de 3), siendo X igual al número de etapa del Villano."},
  "13032": {"n":"Todos para uno","t":"Acción de Héroe (ataque): inflige 3 de Daño a un enemigo y agota cualquier cantidad de personajes Vengador que controles. Inflige 1 de Daño adicional a ese enemigo por cada personaje que se haya agotado de este modo."},
  "13033": {"n":"Perseverancia","t":"Respuesta de Héroe: después de que cambies de identidad, dale a tu Héroe una carta de Estado \"Duro\".","f":"\"Sabes que la puerta delantera no está cerrada con llave, ¿no?\" - Spiderman"},
  "13034": {"n":"Preparación física","t":"Acción de Héroe: descarta 1 carta de Estado \"Aturdido\" o \"Confundido\" de tu Héroe.","f":"\"Descuida, los oídos dejarán de pitarte… un día de estos.\" - Nadia Van Dyne"},
  "14001a": {"n":"Mercurio","t":"Supervelocidad — Respuesta: después de que uses uno de los atributos básicos de Mercurio (INT, ATQ o DEF), prepáralo. (Límite de una vez por fase.)","f":"\"Supervelocidad. Búscalo en Google.\""},
  "14001b": {"t":"Hermanos con superpoderes — Acción: descarta 2 cartas de tu mano → roba 2 cartas (roba 3 cartas si Wanda Maximoff está en juego). (Límite de una vez por ronda.)"},
  "14002": {"n":"Bruja Escarlata","t":"Interrupción: cuando uses uno de los atributos básicos de la Bruja Escarlata, descarta la primera carta del mazo de Encuentros. Por cada icono de Aumento que de descarte de este modo, la Bruja Escarlata recibe +1 a ese atributo para este uso."},
  "14003": {"n":"Siempre corriendo","t":"Acción de Héroe: prepara a Mercurio.","f":"\"Soy el hombre más rápido del mundo.\" - Mercurio"},
  "14004": {"n":"Por partida doble","t":"Acción de Héroe: elige dos de las siguientes opciones (puedes elegir la misma dos veces):\n- Inflige 2 de Daño a un enemigo.\n- Quita 2 de amenaza de un Plan."},
  "14005": {"n":"Máxima velocidad","t":"Máximo de 1 por fase.\nAcción de Héroe: recibes +2 INT, +2 ATQ y +2 DEF hasta el final de la ronda.","f":"\"¿Alguna vez te han dado un puñetazo a velocidad supersónica?\" - Mercurio"},
  "14006": {"n":"Velocidad de huracán","t":"Acción de Héroe: aturde a X enemigos.","f":"\"¡Traga polvo!\" - Mercurio"},
  "14007": {"n":"Industrias Serval","t":"Acción de Alter ego: agota Industrial Serval → coge 2 cartas de Mercurio de tu pila de descartes, añádelas a tu mazo y barájalo.","f":"La corporación que patrocina el equipo de superhéroes conocido como Factor-X."},
  "14008": {"n":"Reflejos acelerados","t":"Mercurio recibe +1 DEF.","f":"\"¿Eso es todo lo que tienes?\" - Mercurio"},
  "14009": {"n":"Resistencia a la fricción","t":"Respuesta de Héroe: después de que prepares a Mercurio, prepara esta carta.\nRecurso: agota Resistencia a la fricción → genera un recurso [physical]."},
  "14010": {"n":"Percepción superior","t":"Mercurio recibe +1 INT.","f":"\"Seguro que puedes hacerlo mejor.\" - Mercurio"},
  "14011": {"n":"Tendones reforzados","t":"Mercurio recibe +1 ATQ.","f":"\"El futuro lo escriben los vencedores.\" - Mercurio"},
  "14012": {"n":"Hombre Múltiple","t":"Respuesta: después de que el Hombre Múltiple entre en juego, busca en tu mazo y tu mano una copia del Hombre Múltiple y ponla en juego. Baraja tu mazo si se ha buscado en él de este modo.","f":"\"¿Quién quiere un bocadillo?\""},
  "14013": {"t":"Acción: gasta un recurso [mental] → cura hasta 2 de Daño a Warlock.","f":"\"Yo cree que esto es un error. Pero yo es muy joven y sabe muy poco.\""},
  "14014": {"n":"Ni un paso atrás","t":"Interrupción de Héroe (defensa): cuando defiendas contra un ataque, recibes +2 DEF para este ataque. Si el ataque no te inflige Daño, aturde al enemigo atacante.","f":"\"¡A la carga, Campeones!\" - Ms. Marvel"},
  "14015": {"n":"Esquiva lateral","t":"Interrupción de Héroe (defensa): cuando vayas a sufrir cualquier cantidad de Daño, evita 3 de ese Daño. Si has pagado el coste de esta carta usando un recurso [energy], inflige 1 de Daño a un enemigo.","f":"\"¡Has fallado!\" - Avispa"},
  "14016": {"n":"Chaleco blindado","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nTu Héroe recibe +1 DEF.","f":"Te salva la vida con estilo."},
  "14017": {"n":"Nervios de acero","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nRecurso: agota Nervios de acero → genera un recurso [energy] para un Evento con Defensa."},
  "14018": {"n":"Orden y caos","t":"Equipo (Mercurio y Bruja Escarlata). Máximo de 1 por mazo.\nInterrupción de Héroe: cuando se muestre una carta de Perfidia del mazo de Encuentros, anula su efecto de \"Cuando se muestre esta carta\" y luego inflige 2 de Daño al villano."},
  "14019": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "14020": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "14021": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "14022": {"n":"Descarga de adrenalina","t":"Acción de Héroe: descarta Descarga de adrenalina → tu Héroe recibe +1 ATQ hasta el final de la fase.","f":"\"¡Jo, tía! Y yo que creía que a Gamora se le iba la pinza.\" - Mapache Cohete."},
  "14023": {"n":"Deber cívico","t":"Acción de Héroe: descarta Deber cívico → tu Héroe recibe +1 INT hasta el final de la fase.","f":"\"¡Por favor, mantengan la calma! ¡Todo va a salir bien!\" - Ms. Marvel"},
  "14024": {"n":"Vivir con prisa","t":"Dale esta carta al jugador que lleva a Pietro Maximoff.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n• Agota a Pietro Maximoff → retira del juego Vivir con prisa.\n• Agota tu carta de Superhéroe. No puedes preparar tu carta de Superhéroe hasta que termine tu próximo turno. Descarta esta Obligación."},
  "14025": {"n":"Extorsión de proporciones sísmicas","t":"Incitar 1. (Cuando se muestre esta carta, coloca 1 de Amenaza sobre el Plan principal.)"},
  "14026": {"n":"Avalancha","t":"Incitar 2. (Cuando se muestre esta carta, coloca 2 de Amenaza sobre el Plan principal.)\nCuando se muestre esta carta: cada jugador debe elegir entre sufrir 2 de Daño indirecto o agotar su carta de Superhéroe.\n(Esbirro Archienemigo de Mercurio.)"},
  "14027": {"n":"Resistencia a las vibraciones","t":"Vincula esta carta a Avalancha si es posible. Si no es posible, vincula esta carta al Villano.\nReduce en 1 el Daño que sufra el enemigo vinculado en cada ataque.\nAcción de Héroe: agota tu Héroe → descarta esta carta."},
  "14028": {"n":"Terremoto","t":"Incitar 1.\nCuando se muestre esta carta: descarta 2 cartas de tu mano y agota tu carta de Superhéroe.\n[star] Aumento: Elige entre gastar recursos [physical] [physical] o agotar tu carta de Superhéroe."},
  "14029": {"n":"Fuerza bruta","t":"Tu Héroe recibe +1 ATQ. Tus ataques básicos ganan Penetrante.\nRespuesta obligada: después de que realices un ataque básico, descarta Fuerza bruta."},
  "14030": {"n":"Sentido de la justicia","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nRecurso: agota Sentido de la justicia → genera un recurso [mental] para un Evento con Intervención."},
  "14031": {"n":"Unidos resistimos","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Vengador.\nAcción de Héroe: cura 1 de Daño a no más de X personajes amigos (hasta un máximo de 3 personajes), siendo X igual al número de la etapa del Villano."},
  "14032": {"n":"Paliza","t":"Acción de Héroe: inflige 1 de Daño al Villano y a cada Esbirro que esté enfrentado a ti.","f":"\"Demasiado fácil.\" - Hulka"},
  "15001a": {"n":"Bruja Escarlata","t":"Control del caos — Interrupción: cuando vayan a contarse los iconos de Aumento de una carta de Encuentro, en vez de eso descarta la primera carta del mazo de Encuentros y cuenta el número de iconos de Aumento de esa carta. (Límite de una vez por fase.)"},
  "15001b": {"t":"Hermanos con superpoderes — Acción: descarta 2 cartas de tu mano → roba 2 cartas (roba 3 cartas si Pietro Maximoff está en juego). (Límite de una vez por ronda.)"},
  "15002": {"n":"Mercurio","t":"Acción: prepara a Mercurio. (Límite de una vez por fase.)","f":"\"¡Te advertí que no amenazases a mi hermana!\""},
  "15003": {"n":"Magia del caos","t":"Acción de Héroe: juega una carta de tu mano ignorando su coste en recursos. Descarta tantas cartas de la parte superior del mazo de Encuentros como el coste en recursos impreso en esa carta.","f":"\"El mundo adoptará la forma que yo considere apropiada.\" —Bruja Escarlata"},
  "15004": {"n":"Maleficio","t":"Acción de Héroe: descarta las 3 primeras cartas del mazo de Encuentros. Por cada carta descartada de este modo que tenga un número de iconos de Aumento igual a:\n- 0, inflige 2 de Daño a un enemigo.\n- 1, quita 2 de Amenaza de un Plan.\n- 2, roba 1 carta.\n- 3+, coloca una carta de Estado sobre un personaje."},
  "15005": {"n":"Descomposición molecular","t":"Acción de Héroe (ataque): inflige 5 de Daño a un enemigo y descarta las 2 primeras cartas del mazo de Encuentros. Por cada icono de Aumento que se haya descartado de este modo, inflige 1 de Daño adicional a ese enemigo.","f":"\"¡No existe defensa alguna contra la Bruja Escarlata!\""},
  "15006": {"n":"Alterar la realidad","t":"Interrupción de Héroe: cuando se muestre una carta de Encuentro del mazo de Encuentros, anula todos sus efectos y descártala. Descarta tantas cartas de la parte superior del mazo de Encuentros como el número de iconos de Aumento que haya en esa carta."},
  "15007": {"t":"Acción de Alter ego: agota a Agatha Harkness → mira las 3 primeras cartas de tu mazo. Añade 1 de esas cartas a tu mano y coloca las demás en la parte inferior de tu mazo, en el orden que prefieras.","f":"\"No te dejes llevar por la ira, Wanda.\""},
  "15008": {"n":"Escudo mágico","t":"Interrupción de Héroe: cuando un personaje amigo vaya a sufrir cualquier cantidad de Daño, descarta el Escudo mágico → evita 3 de ese Daño."},
  "15009": {"n":"Tiara de la Bruja Escarlata","t":"Interrupción: cuando se cuenten los iconos de Aumento de una carta de Encuentro, agota la Tiara de la Bruja Escarlata → incrementa o reduce en 1 el número de iconos de Aumento de esa carta para este recuento."},
  "15010": {"n":"Veloz","t":"Respuesta: después de que Veloz intervenga, prepáralo. (Límite de una vez por ronda.)","f":"\"¡Eh, ancianos! Vamos a darnos prisa. ¡Los Vengadores nos necesitan!\""},
  "15011": {"t":"Respuesta: después de que Wiccan intervenga, descarta la primera carta del mazo de Encuentros. Por cada icono de Aumento que se haya descartado de este modo, inflige 1 de Daño a un enemigo.","f":"\"Soy el hijo de una bruja y un androide. Soy su deseo hecho realidad.\""},
  "15012": {"n":"Crisis resuelta","t":"Acción de Héroe (intervención): quita 6 de Amenaza del Plan principal. Si has pagado el coste de esta carta usando un recurso [mental], esta intervención ignora el icono de Crisis ([crisis])."},
  "15013": {"n":"Multitarea","t":"Acción de Héroe (intervención): quita 2 de Amenaza de un Plan. Si has pagado el coste de esta carta usando un recurso [mental], quita 2 de Amenaza de un Plan distinto.","f":"\"Un héroe no es el que gana siempre. Es el que siempre lo intenta.\" —Spiderman"},
  "15014": {"n":"Castigo inmediato","t":"Acción de Héroe (ataque): el Villano ejecuta el Plan. Inflige 4 de Daño al Villano.","f":"\"Devolved lo que habéis robado y os dejaré marchar. Por esta vez. Pero la próxima no tendréis tanta suerte. Y yo no seré tan generoso.\" —Caballero Luna"},
  "15015": {"n":"Cambiar la situación","t":"Respuesta (ataque): después de que tu Héroe intervenga y quite toda la Amenaza de un Plan, inflige 3 de Daño a un enemigo.","f":"\"¡Atrás, chusma!\" —Bruja Escarlata"},
  "15016": {"n":"El poder de la justicia","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta de Justicia (amarilla)."},
  "15017": {"n":"Intuición heroica","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nTu Héroe recibe +1 INT."},
  "15018": {"n":"Orden y caos","t":"Equipo (Mercurio y Bruja Escarlata). Máximo de 1 por mazo.\nInterrupción de Héroe: cuando se muestre una carta de Perfidia del mazo de Encuentros, anula su efecto de \"Cuando se muestre esta carta\" y luego inflige 2 de Daño al villano."},
  "15019": {"n":"Meditación espiritual","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Místico.\nAcción: roba 2 cartas. Elige 1 carta de tu mano y descártala.","f":"\"Cada hechizo, cada signo, cada manipulación… debes tenerlo todo vigilado para que no te explote en las narices.\""},
  "15020": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "15021": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "15022": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "15023": {"n":"Al borde de la locura","t":"Dale esta carta al jugador que lleva a Wanda Maximoff.\nPuedes adoptar la identidad de tu Alter Ego. Elige una opción:\n• Agota a Wanda Maximoff → retira del juego Al borde la locura.\n• Descarta las 5 primeras cartas del mazo de Encuentros. Por cada icono de estrella ([star]) que haya en el recuadro de aumentos de las cartas descartadas de este modo, coloca 1 de Amenaza sobre el Plan principal. Descarta esta Obligación."},
  "15024": {"n":"La siguiente evolución","t":"Incrementa en 1 el número de iconos de Aumento de cada carta de Encuentro.","f":"\"¡El Alto Evolucionador pretende crear un dios adecuado para el siglo XXI!\" - Alto Evolucionador"},
  "15025": {"n":"Luminosa","t":"Respuesta obligada: después de que Luminosa se active contra ti, descarta la primera carta del mazo de Encuentros. Si se han descartado al menos 2 iconos de Aumento de este modo, coge 1 carta de Encuentro.\n(Esbirro Archienemigo de la Bruja Escarlata.)"},
  "15026": {"n":"Suspensión mágica","t":"Vincula esta carta a tu Superhéroe.\nCada carta que juegues cuesta 1 recurso adicional.\nAcción de Héroe: agota tu Héroe → descarta esta carta."},
  "15027": {"n":"Manipulación del caos","t":"Cuando se muestre esta carta: busca a Luminosa en el mazo y la pila de descartes de Encuentros y ponla en juego enfrentada a ti. Descarta la primera carta del mazo de Encuentros. Si se han descartado al menos 2 iconos de Aumento de este modo, Luminosa se activa contra ti."},
  "15028": {"n":"Amedrentar","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Vengador.\nAcción de Héroe (ataque): inflige 2 de Daño al Villano. Inflige X de Daño adicional al Villano (hasta un máximo de 3), siendo X igual al número de la etapa del Villano."},
  "15029": {"n":"Un último asalto","t":"Interrupción de Héroe: cuando un Aliado controlado por ti ataque, recibe +3 ATQ para ese ataque. Después de resolver ese ataque, descarta a ese aliado.","f":"\"¡En guardia, diablo! ¡No vencerás tan fácilmente!\" —Dama Sif"},
  "15030": {"n":"Maniobra engañosa","t":"Acción de Héroe (intervención): el Villano te ataca. Quita 4 de Amenaza del Plan principal.","f":"\"No te habrás creído que me ibas a engañar con eso, ¿verdad?\" —Spiderman"},
  "15031": {"n":"Restablecimiento","t":"Acción de Alter ego: cura a tu Alter ego tanto Daño como tu REC.","f":"\"Parece que ya empiezas a sentirte mejor.\" —Stephen Extraño"},
  "16001a": {"t":"Flora Colossus — Interrupción obligada: cuando Groot vaya a sufrir cualquier cantidad de Daño, quítale ese mismo número de contadores de Crecimiento. Por cada contador de Crecimiento que se quite de este modo, se evita 1 de ese Daño."},
  "16001b": {"t":"Crecimeinto súbito — Acción: coloca 2 contadores de Crecimiento sobre Groot (hasta un máximo de 10). (Límite de una vez por ronda.)"},
  "16002": {"n":"Germinación","t":"Acción: coloca 2 contadores de Crecimiento sobre Groot (hasta un máximo de 10).","f":"\"Soy Groot…\" - Groot"},
  "16003": {"n":"\"Soy Groot\"","t":"Acción de Héroe (intervención): quita tanta Amenaza de un Plan como el número de contadores de Crecimiento que haya sobre Groot.","f":"\"¡¡¡Spy Groot!!!\" - Groot"},
  "16004": {"n":"\"¡SOY… GROOT!\"","t":"Acción de Héroe (ataque): inflige tanto Daño a un enemigo como el número de contadores de Crecimiento que haya sobre Groot.","f":"\"¡SOY… GROOT!\" - Groot"},
  "16005": {"n":"Raíz aplastante","t":"Acción de Héroe (ataque): inflige 5 de Daño a un enemigo. Si este ataque derrota a ese enemigo, coloca 1 contador de Crecimiento sobre Groot (hasta un máximo de 10).","f":"\"Soy… Groot\" - Groot"},
  "16006": {"n":"\"Somos Groot\"","t":"Acción de Héroe: quita hasta 4 contadores de Crecimiento de Groot → elige ese mismo número de personajes amigos. Dale una carta de Estado \"Duro\" a cada uno de esos personajes.","f":"\"Somos Groot.\" - Groot"},
  "16007": {"n":"Terreno fértil","t":"Acción de Alter ego: agota Terreno fértil → coloca 1 contador de Crecimiento sobre Groot (hasta un máximo de 10) y roba 1 carta.","f":"\"Soy… Groot.\" - Groot"},
  "16008": {"n":"Enredaderas","t":"Interrupción de Héroe: cuando Groot realice una intervención básica, quítale 1 contador de Crecimiento y agota Enredaderas → Groot recibe +2 INT para esa intervención.","f":"\"¡Soy… GROOT!\" - Groot"},
  "16009": {"n":"Lianas lacerantes","t":"Respuesta de Héroe: después de que Groot use un atributo básico, quítale 2 contadores de Crecimiento y agota Liana lacerantes → prepara a Groot.","f":"\"SOY Groot.\" - Groot"},
  "16010": {"n":"Escudo de lianas","t":"Interrupción de Héroe: cuando Groot defienda contra un ataque, quítale 1 contador de Crecimiento y agota Escudo de lianas → Groot recibe +3 de DEF para ese ataque.","f":"\"¿Soy Groot?\" - Groot"},
  "16011": {"n":"Lianas puntiagudas","t":"Interrupción de Héroe: cuando Groot realice un ataque básico, quítale 1 contador de Crecimiento y agota Lianas puntiagudas → Groot recibe +2 ATQ para ese ataque.","f":"\"Que sí, que eres Groot, ya lo sabemos.\" - Mapache Cohete"},
  "16012": {"n":"Halcón Estelar","t":"Interrupción: cuando Halcón Estelar sufra una cantidad de Daño exactamente igual a su Vida restante, devuévelo a tu mano.","f":"\"Soy alguien que sabe.\""},
  "16013": {"n":"Defensa desesperada","t":"Interrupción de Héroe (defensa): cuando tu Héroe defienda contra un ataque, recibe +2 DEF para ese ataque. Si no sufres Daño a causa de ese ataque, prepara a tu Héroe."},
  "16014": {"n":"En plena forma","t":"Acción de Héroe (ataque): inflige 2 de Daño al Villano (5 de Daño si la Vida restante de tu Héroe es igual o superior a su Vida inicial).","f":"\"Prepárate, necio.\" - Drax"},
  "16015": {"n":"El poder de la protección","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta de Protección (verde)."},
  "16016": {"n":"Intrépido","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nMientras la Vida restante de tu Héroe sea igual o superior a su Vida inicial, tu Héroe gana Represalia 1."},
  "16017": {"n":"Difícil de ignorar","t":"Respuesta de Héroe: después de que tu Héroe defienda contra un ataque y no sufra Daño, agota Díficil de ignorar → quita 1 de Amenaza del Plan principal","f":"\"¡Moriré antes que rendirme!\" - Drax"},
  "16018": {"n":"Indómito","t":"Respuesta: después de que tu Héroe defienda, descarta Indómito → prepara a tu Héroe.","f":"\"No tenemos elección. Lucharemos... y venceremos. No hay otra opción.\" —Capitán América"},
  "16019": {"n":"Mapache Cohete","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Guardián.\nInterrupción: cuando Mapache Cohete ataque a un Esbirro, recibe +3 ATQ para ese ataque. Ese ataque gana Brutalidad."},
  "16020": {"n":"Flora y fauna","t":"Equipo (Groot y Mapache Cohete). Máximo de 1 por mazo.\nAcción de Héroe: coloca 2 contadores de Crecimiento sobre Groot (hasta un máximo de 10) y prepáralo, o bien coloca 2 contadores de Carga sobre una Mejora del conjunto de Mapache Cohete y prepara esa mejora."},
  "16021": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "16022": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "16023": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "16024": {"n":"Concentración eficaz","t":"Máximo de 1 por jugador.\nAcción de Héroe: agota Concentración eficaz → reduce en 1 el coste en recursos de la próxima carta Superpoder que juegues en este turno."},
  "16025": {"n":"Marchitamiento","t":"Dale esta carta al jugador que lleva a Groot.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n• Agota tu Alter ego → retira del juego Marchitamiento.\n• Quita 3 contadores de Crecimiento a Groot. Si no se quita ningún contador de Crecimiento de este modo, esta carta gana Oleada. Descarta esta Obligación."},
  "16026": {"n":"Infierno abrasador","t":"Respuesta obligada: después de que empiece la fase del Villano, inflige 2 de Daño indirecto a cada jugador.","f":"Furnax ha desatado su furia sobre el planeta X, el mundo natal de Groot, sembrando la muerte y la destrucción a su paso."},
  "16027": {"t":"[star] Respuesta obligada: después de que Furnax se active, inflige 2 de Daño indirecto a cada jugador.\n(Esbirro Archienemigo de Groot.)"},
  "16028": {"n":"Avivar las llamas","t":"Cuando se muestre esta carta: sufres 2 de Daño indirecto. Si está en juego Infierno abrasador, sufres 1 de Daño indirecto adicional. Si está en juego Furnax, sufres 1 de Daño indirecto adicional."},
  "16029a": {"n":"Mapache Cohete","t":"\"Estás muerto!\" — Respuesta: después de que inflijas Daño sobrante a un enemigo, roba 1 carta.","f":"\"¡Se acabó! Podéis atacarme, podéis insultarme, ¡pero nadie, NADIE toca mi pistola!\""},
  "16029b": {"n":"Mapache Cohete","t":"Mañoso — Acción: descarta una Mejora Tecnología de tu elección que controles → roba 2 cartas. (Límite de una vez por ronda.)","f":"\"No hay nada como yo, salvo yo.\""},
  "16030": {"n":"Tengo un plan","t":"Respuesta de Héroe: después de que realices una intervención básica (usando tu INT), prepara a Mapache Cohete. Mapache Cohete recibe +1 INT hasta el final de la fase mientras tenga adoptada su identidad de Héroe.","f":"\"No pensé que tendría gracia. ¿La ha tenido?\" - Mapache Cohete"},
  "16031": {"n":"Recarga","t":"Acción de Héroe: prepara todas las Mejoras Tecnología que controles.","f":"\"La gente no me importa. Me paso gran parte del tiempo disparándoles.\" - Mapache Cohete"},
  "16032": {"n":"Mala baba","t":"Acción de Héroe: hasta el final del turno, cura 2 de Daño a Mapache Cohete cada vez que inflijas cualquier cantidad de Daño a un enemigo.","f":"\"Me van las cosas sencillas… como saber cuánto va a doler esto.\" - Mapache Cohete"},
  "16033": {"n":"Reutilizar piezas","t":"Respuesta: después de que gastes esta carta, coge una Mejora Tecnología de tu pila de descartes y colócala en la parte superior de tu mazo."},
  "16034": {"n":"Batería auxiliar","t":"Esta carta entra en juego con 2 contadores de Carga.\nAcción: agota la Batería auxiliar → traslada 1 contador de Carga desde esta carta hasta otra Mejora Tecnología que controles."},
  "16035": {"n":"Esquéleto cibernético","t":"Recibes +3 de Vida.\nMientras tenga adoptad su identidad de Héroe, Mapache Cohete recibe +1 ATQ.","f":"\"Sí, eso, mirad al bicho raro mientras podáis.\" - Mapache Cohete"},
  "16036": {"n":"Cañón de partículas","t":"Restringida. Esta carta entra en juego con 2 contadores de Carga.\nAcción de Héroe (ataque): agota el Cañón de partículas y quítale 1 contador de Carga → inflige 4 de Daño a un enemigo. Ese ataque gana A distancia y Brutalidad."},
  "16037": {"n":"Lanzacohetes","t":"Restringida. Esta carta entra en juego con 2 contadores de Carga.\nAcción de Héroe: agota el Lanzacohetes y quítale 1 contador de Carga → elige un Jugador. Inflige 2 de Daño al Villano y a cada Esbirro que esté enfrentado a ese jugador."},
  "16038": {"n":"Pistola de Cohete","t":"Restringida. Esta carta entra en juego con 3 contadores de Carga.\nAcción de Héroe (ataque): agota la Pistola de Cohete y quítale 1 contador de Carga → inflige 2 de Daño a un enemigo."},
  "16039": {"n":"Aerobotas","t":"Mientras tenga adoptada su identidad de Héroe, Mapace Cohete recibe +1 INT y gana el rasgo Aéreo.","f":"\"Visto desde aquí arriba, tienes que ser el humano más feo que he visto en la vida. Y mira que suelo ir con Peter Quill.\" - Mapache Cohete"},
  "16040": {"n":"Bicho","t":"Respuesta de Héroe: después de que tu Héroe realice un ataque Básico, cura 1 Daño a Bicho.","f":"\"¡Yupi! ¡Volvemos a ser *tic* un equipo! ¡Ahora no habrá *tic* quien nos detenga!\""},
  "16041": {"n":"A por ellos","t":"Respuesta (intervención): después de que tu Héroe ataque y derrote a un enemigo, quita 2 de Amenaza de un Plan.","f":"\"Kamala, no tenemos banda sonora propia. Deja ya de tatarear...\" —Capitana Marvel"},
  "16042": {"n":"Entrar en combate","t":"Acción de Héroe (ataque): inflige 6 de Daño a un Esbirro. Por cada punto de Daño sobrante infligido por este ataque, quita 1 de Amenaza del Plan principal."},
  "16043": {"n":"Buscando problemas","t":"Acción de Héroe (intervención): descarta cartas de la parte superior del mazo de Encuentros hasta que descartes un Esbirro. Pon en juego ese Esbirro enfrentado a ti → quita 3 de Amenaza del Plan principal."},
  "16044": {"n":"Asalto implacable","t":"Acción de Héroe (ataque): inflige 5 de Daño a un Esbirro. Si has pagado el coste de esta carta usando un recurso [physical], este ataque gana Brutalidad. (El Daño sobrante de este ataque se inflige al Villano.)"},
  "16045": {"n":"Ensañamiento","t":"Interrupción de Héroe: cuando el ataque de tu Héroe inflija cualquier cantidad de Daño sobrante, aumenta esa cantidad en 1.","f":"\"Te has pasado un poco…\""},
  "16046": {"n":"Pistolón","t":"Restringida. Usos (3 contadores de Carga).\nInterrupción de Héroe: cuando tu Héroe realice un ataque básico, agota el Pistolón y quítale 1 contador de Carga → tu Héroe recibe +2 ATQ para ese ataque. Ese ataque gana Brutalidad."},
  "16047": {"t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Guardián.\nRespuesta: después de que Groot defienda contra un ataque, cúrale 2 de Daño.","f":"\"¡Soy Groot!\""},
  "16048": {"n":"Flora y fauna","t":"Equipo (Groot y Mapache Cohete). Máximo de 1 por mazo.\nAcción de Héroe: coloca 2 contadores de Crecimiento sobre Groot (hasta un máximo de 10) y prepáralo, o bien coloca 2 contadores de Carga sobre una Mejora del conjunto de Mapache Cohete y prepara esa mejora."},
  "16049": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "16050": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "16051": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "16052": {"n":"Botas impulsoras","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Guardián. Máximo de 1 por jugador.\nInterrupción de Héroe: cuando vayas a sufrir cualquier cantidad de Daño a consecuencia de un ataque, agota las Botas impulsoras y descarta la primera carta de la parte superior de tu mazo → evita 1 de ese Daño."},
  "16053": {"n":"Crisis en Medio Mundo","t":"Dale esta carta al jugador que lleva a Mapache Cohete.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n• Agota tu Alter ego → retira del juego Crisis en Medio Mundo.\n• Descarta la Mejora con el coste más alto que controles. Si no se descarta ninguna Mejora de este modo, esta carta gana Oleada. Descarta esta Obligación."},
  "16054": {"n":"Venganza personal","f":"\"Sé que odias esa palabra. Pero oye, si parece un pato, hace 'cuac' como un pato y camina como un pato... ¡es un mapache!\" - Blackjack O'Hare"},
  "16055": {"t":"Ataque veloz.\nInfame. (Cuando este Esbirro se active, dale una carta de aumento.)\n(Esbirro Archienemigo de Mapache Cohete.)","f":"¡Jajajajajajajajajajajajajaja!"},
  "16056": {"n":"Bazuca de Blackjack","t":"Vincula esta carta a Blackjack O'Hare. Si no es posible, vincula esta carta al Villano.\nAcción de Héroe: gasta recursos [mental][mental][mental] → descarta esta carta."},
  "16057": {"n":"Invasión planetaria","t":"Cuando se muestre esta carta: descarta cartas de la parte superior del mazo de Encuentros hasta que descartes un Esbirro. Muestra ese Esbirro y luego dale una carta de Estado \"Duro\".","f":"\"¿Qué piensas hacer al respecto?\" - Blackjack O'Hare"},
  "16058": {"t":"[star] Respuesta obligada: después de que Drang ejecute el Plan, resuelve la capacidad \"Cargar los cañones\" de la Nave badoon.","f":"\"¡Someteos al poder de los Badoon!\""},
  "16059": {"t":"Cuando se muestre esta carta: si la Lanza de Drang está en juego, dale a Drang 1 carta de aumento boca abajo; de no ser así, busca la Lanza de Drang en el mazo y la pila de descartes de Encuentros, muéstrala y baraja el mazo de Encuentros.\n[star] Respuesta obligada: después de que Drang ejecute el Plan, resuelve la capacidad \"Cargar los cañones\" de la Nave badoon."},
  "16060": {"t":"Cuando se muestre esta carta: descarta las 4[per_hero] primeras cartas del mazo de Encuentros. Cada vez que se descarte un Esbirro de este modo, ponlo en juego enfrentado al jugador que esté enfrentado con menos Esbirros.\n[star] Respuesta obligada: después de que Drang se active, resuelve la capacidad \"Cargar los cañones\" de la Nave badoon."},
  "16061a": {"n":"Invasión extraterrestre","t":"Contenido: Drang (I) and Drang (II). (Drang (II) and Drang(III) para jugar en modo Experto.) Conjuntos de Encuentros Hermandad de los Badoon, Nave espacial y Normal. Un conjunto de Encuentros modular (Banda badoon).\nPreparación: pon en juego el Entorno Nave badoon y el Apoyo Milano."},
  "16061b": {"t":"[star] Respuesta obligada: después de resolver el paso uno de la fase del Villano, resuelve la capacidad \"Cargar los cañones\" de la Nave badoon.\nAcción del jugador inicial: agota la Milano → quita 3 de Amenaza de este Plan.","f":"¡Las avasalladoras huestes de Drang han lanzado un ataque sorpresa contra la Tierra!"},
  "16062a": {"n":"Proteger el planeta","t":"Cuando se muestre esta carta: resuelve la capacidad \"Cargar los cañones\" de la Nave badoon.","f":"¡Los badoon han atravesado las defensas de la Tierra! Rechazad su ofensiva antes de que sea demasiado tarde."},
  "16062b": {"n":"Proteger el planeta","t":"[star] Respuesta obligada: después de resolver el paso uno de la fase del Villano, resuelve la capacidad \"Cargar los cañones\" de la Nave badoon.\nAcción del jugador inicial: agota la Milano → elige entre quitar 3 de Amenaza de este Plan o bien infligir 3 de Daño a un Esbirro.\nSi se completa esta etapa, los jugadores pierden la partida."},
  "16063": {"n":"Nave badoon","t":"Cargar los cañones — Especial: coloca 1 contador de Andanada sobre esta carta. Luego, si hay al menos 4 contadores de Andanada sobre esta carta, inflige 2 de Daño indirecto a cada jugador y quita todos los contadores de Andanada de esta carta.","f":"La nave de la Hermandad de los Badoon está cargando sus cañones para lanzar un ataque devastador contra los héroes que se encuentran en tierra."},
  "16064": {"n":"Lanza de Drang","t":"Vincula esta carta a Drang.\nDrang gana Firmeza. (No puede quedar aturdido ni confundido.)\nAcción de Héroe: gasta recursos [mental][physical][physical] → descarta esta carta."},
  "16065": {"t":"[star] Respuesta obligada: después de que el Ingeniero badoon se enfrente a ti o se active contra ti, resuelve la capacidad \"Cargar los cañones\" de la Nave badoon.\n[star] Aumento: Resuelve la capacidad \"Cargar los cañones\" de la Nave badoon."},
  "16066": {"n":"Bloqueo orbital","t":"Complicación 2[per_hero]. (Cuando se muestre esta carta, coloca 2[per_hero] de Amenaza sobre ella.)\nAcción del jugador inicial: agota la Milano → quita 3 de Amenaza de este Plan."},
  "16067": {"n":"Bombardeo","t":"Respuesta obligada: después de resolver el paso uno de la fase del Villano, resuelve la capacidad \"Cargar los cañones\" de la Nave badoon.\nAcción del jugador inicial: agota la Milano → quita 3 de Amenaza de este Plan."},
  "16068": {"n":"Armada opresora","t":"Complicación 3[per_hero]. (Cuando se muestre esta carta, coloca 3[per_hero] de Amenaza sobre ella.)\nAcción del jugador inicial: agota la Milano → quita 3 de Amenaza de este Plan."},
  "16069": {"n":"Orientación espacial","t":"Acción del jugador inicial: agota la Milano → quita 3 de Amenaza de este Plan."},
  "16070": {"n":"El Coleccionista","t":"Interrupción obligada: cuando una carta (de Jugador o de Encuentro) que esté en juego vaya a colocarse en una pila de descartes, en vez de eso colócala boca arriba en la Colección.","f":"\"¡Tengo un expositor ya preparado y esperando a nuestras más recientes adquisiciones!\""},
  "16071": {"n":"El Coleccionista","t":"Cuando se muestre esta carta: siguiendo el orden de jugadores, cada jugador debe elegir entre coger la primera carta de su mazo y colocarla boca arriba en la Colección, o bien sufrir 3 de Daño.\nInterrupción obligada: cuando una carta que esté en juego vaya a colocarse en una pila de descartes, en vez de eso colócala boca arriba en la Colección."},
  "16072": {"n":"El Coleccionista","t":"Cuando se muestre esta carta: coge la primera carta del mazo de cada jugador y colócala boca arriba en la Colección. Coloca 1 de Amenaza sobre el Plan principal por cada carta que haya en la Colección.\nInterrupción obligada: cuando una carta que esté en juego vaya a colocarse en una pila de descartes, en vez de eso colócala boca arriba en la Colección, luego coloca 1 de Amenaza sobre el Plan principal."},
  "16073a": {"n":"La gran colección","t":"Contenido: El Coleccionista (I) y El Coleccionista (II). (El Coleccionista (II) y El Coleccionista (III) para jugar en modo Experto.) Conjuntos de Encuentros Infiltrados en el museo, Artefactos galácticos y Normal. Un conjunto de Encuentros modular (Bestiario galáctico).\nPreparación: crea la zona de juego de la \"Colección\" (ver reglas). Coge la primera carta del mazo de cada jugador y colócala boca arriba en la Colección."},
  "16073b": {"n":"La gran colección","t":"Acción de Héroe: elige entre agotar tu Héroe o gastar 2 recursos de cualquier tipo → descarta 1 carta de la Colección (se coloca en la pila de descartes de su propietario). (Límite de una vez por ronda y jugador.)\nSi hay al menos 5[per_hero] cartas en la Colección o si se completa esta etapa, los jugadores pierden la partida."},
  "16074": {"n":"Imagen biogramática","t":"Vincula esta carta a El Coleccionista.\nInterrupción obligada: cuando El Coleccionista vaya a sufrir cualquier cantidad de Daño, coloca esta carta boca arriba en la Colección → se evita todo ese Daño, luego coloca tanta Amenaza sobre el Plan principal como la cantidad de Daño evitada de este modo.\n[star] Aumento: Después de que termine esta activación, muestra esta carta."},
  "16075": {"n":"Monark Starstalker","t":"Infame. (Cuando este Esbirro se active, dale una carta de aumento.)","f":"\"Nadie puede esconderse de mí.\""},
  "16076": {"n":"Caja poco llamativa","t":"Cuando se muestre esta carta: coloca en la Colección la carta con el coste más bajo que controles. Si no puedes hacerlo, esta carta gana Oleada.\n[star] Aumento: Si hay 3[per_hero] cartas o menos en la Colección, coge la primera carta de tu mazo y colócala boca arriba en la Colección."},
  "16077": {"n":"Observar el cosmos","t":"Cuando se muestre esta carta: Elige una opción:\n- Coloca boca arriba en la Colección la carta de tu mano que tenga el coste más alto.\n- Descarta la carta de tu mano que tenga el coste más alto y luego coloca tanta Amenaza sobre el Plan principal como su coste impreso."},
  "16078": {"n":"Quedaos un rato","t":"Cuando se muestre esta carta (Alter ego): elige entre gastar recursos [physical][physical] o bien coger la primera carta de tu mazo y colocarla boca arriba en la Colección.\nCuando se muestre esta carta (Héroe): El Coleccionista te ataca con +1 ATQ. Si sufres cualquier cantidad de Daño a consecuencia de este ataque, coge la primera carta de tu mazo y colócala boca arriba en la Colección."},
  "16079": {"n":"Con la guardia baja","t":"Cuando se muestre esta carta: descarta una Mejora o Apoyo que controles. Si no se descarta ninguna carta de este modo, esta carta gana Oleada."},
  "16080a": {"n":"El Coleccionista","t":"[star] El Coleccionista recibe +X PLA y +X ATQ, siendo X igual al número de la etapa actual del Plan principal.\nInterrupción obligada: cuando El Coleccionista vaya a ser derrotado, en vez de eso quita 3[per_hero] de Amenaza del Plan principal y dale la vuelta a esta carta."},
  "16080b": {"n":"El Coleccionista","t":"El Coleccionista no puede ser derrotado.\nInterrupción obligada: cuando termine la ronda, dale la vuelta a esta carta, luego fija el medidor de Vida de El Coleccionista en su puntuación impresa de Vida.","f":"\"Sois más astutos de lo que me había figurado. Tanto da. Probemos otra vez.\""},
  "16081a": {"n":"El Coleccionista","t":"[star] El Coleccionista recibe +X PLA y +X ATQ, siendo X igual al número de la etapa actual del Plan principal.\nInterrupción obligada: cuando El Coleccionista vaya a ser derrotado, en vez de eso quita 3[per_hero] de Amenaza del Plan principal y dale la vuelta a esta carta."},
  "16081b": {"n":"El Coleccionista","t":"El Coleccionista no puede ser derrotado.\nInterrupción obligada: cuando termine la ronda, dale la vuelta a esta carta, luego fija el medidor de Vida de El Coleccionista en su puntuación impresa de Vida.","f":"\"Sois más astutos de lo que me había figurado. Tanto da. Probemos otra vez.\""},
  "16082a": {"n":"En busca de la Milano","t":"Contenido: El Coleccionista (A1) (El Coleccionista (B1) para jugar en modo Experto.) Conjuntos de Encuentros Artefactos galácticos, Huida del museo, Nave espacial y Normal. Un conjunto de Encuentros modular (Bestiario galáctico).\nPreparación: pon en juego la carta de Entorno Biblioteca laberíntica. Aparta a un lado el conjunto de Encuentros modular Nave espacial."},
  "16082b": {"n":"En busca de la Milano","t":"Interrupción obligada: cuando se quite la última ficha de Amenaza de este Plan, avanza a la etapa 2A (los jugadores ganan avanzando el Plan).\nSi se completa esta etapa, los jugadores pierden la partida.","f":"Estáis atrapados dentro del museo del Coleccionista. Antes de escapar, tenéis que encontrar la Milano."},
  "16083a": {"n":"Perdidos en el museo","t":"Cuando se muestre esta carta: coge el Apoyo apartado Milano (del conjunto de Encuentros Nave espacial) y ponlo en juego controlado por el jugador inicial.","f":"La Milano está guardada en una vitrina gigante. Intentáis forzar un panel lateral, pero al final optáis por golpear el cristal con todas vuestras fuerzas."},
  "16083b": {"n":"Perdidos en el museo","t":"Interrupción obligada: cuando se quite la última ficha de Amenaza de este Plan, avanza a la etapa 3A (los jugadores ganan avanzando el Plan).\nSi se completa esta etapa, los jugadores pierden la partida.","f":"¡Ahora que habéis sacado la Milano de su prisión, es hora de usarla para encontrar la puerta principal!"},
  "16084a": {"n":"La gran fuga","t":"Cuando se muestre esta carta: dale la vuelta a la Biblioteca laberíntica. Coloca 1 ficha de Aceleración sobre el Plan principal. Devuelve al mazo de Encuentros las demás cartas apartadas del conjunto de Encuentros Nave espacial y barájalo.","f":"¡Habéis encontrado la salida! Mientras la Milano emerge al vacío del espacio y enciende sus propulsores, veis que los cañones de la nave museo se disponen a abrir fuego."},
  "16084b": {"n":"La gran fuga","t":"Acción del jugador inicial: agota la Milano → quita 3 de Amenaza de esta carta.\nSi no hay Amenaza sobre esta carta, los jugadores ganan la partida.\nSi se completa esta etapa, los jugadores pierden la partida.","f":"¡Ya casi sois libres! ¡Salid del alcance de los cañones de la nave museo para escapar!"},
  "16085a": {"n":"Biblioteca laberíntica","t":"\"¿Es por aquí?\" — Acción de Héroe: coge 1 carta de Encuentro boca abajo → quita 5 de Amenaza del Plan principal. (Límite de una vez por ronda y jugador.)","f":"El museo del Coleccionista es un laberinto de expositores que contienen artefactos variados de todas las culturas y criaturas indefensas de todos los sistemas estelares."},
  "16085b": {"n":"Nave museo","t":"\"¡Agarraos los traseros!\" — Interrupción obligada: cuando empiece la fase del Villano, elige una opción:\n- Agota la Milano → reparte 2[per_hero] de Daño indirecto entre los jugadores.\n- Reparte 3[per_hero] de Daño indirecto entre los jugadores."},
  "16086": {"n":"\"¡Ya sois míos!\"","t":"Cuando se muestre esta carta (Alter ego): agota tu carta de Superhéroe. El Coleccionista ejecuta el Plan.\nCuando se muestra esta carta (Héroe): quedas aturdido. El Coleccionista te ataca.\n[star] Aumento: Dale a El Coleccionista una carta de Estado \"Duro\"."},
  "16087": {"n":"Geometría imposible","t":"Incitar 1. (Cuando se muestre esta carta, coloca 1 de Amenaza sobre el Plan principal.)\nCuando se muestre esta carta: quedas confundido. Si ya estabas confundido, descarta 1 carta que controles de tu elección.","f":"\"Yo... soy... ¿Groot?\" - Groot"},
  "16088": {"n":"Nébula","t":"El primer Accesorio Técnica mostrado en cada ronda gana Oleada.\n[star]Interrupción obligada: cuando Nébula inicie una activación contra ti, resuelve la capacidad \"Especial\" de todos los Accesorios Técnica que haya en juego, luego descarta esos Accesorios."},
  "16089": {"n":"Nébula","t":"El primer Accesorio Técnica que muestre cada jugador en cada ronda gana Oleada..\n[star]Interrupción obligada: cuando Nébula inicie una activación contra tu, resuelve la capacidad \"Especial\" de todos los Accesorios Técnica que haya en juego, luego elige y descarta 1 de esos Accesorios."},
  "16090": {"n":"Nébula","t":"El primer Accesorio Técnica que muestre cada jugador en cada ronda gana Oleada.\n[star]Interrupción obligada: cuando Nébula inicie una activación contra ti, resuelve la capacidad \"Especial\" de todos los Accesorios Técnica que haya en juego. Luego puedes retirar del juego la primera carta de tu mazo para elegir y descartar 1 de esos Accesorios."},
  "16091a": {"n":"El arte de la evasión","t":"Contenido: Nébula (I) y Nébula (II). (Nébula (II) y Nébula (III) para jugar en modo Experto.) Conjuntos de Encuentros Gema del Poder, Nave espacial, Nébula y Normal. Un conjunto de Encuentros modular (Piratas espaciales).\nPreparación: pon en juego el Entorno Nave de Nébula y el Apoyo Milano. Vincula la Gema del Poder a Nébula. Descarta las 2[per_hero] primeras cartas del mazo de Encuentros, luego vincula a Nébula cada Accesorio Técnica que se haya descartado de este modo."},
  "16091b": {"n":"El arte de la evasión","t":"X es igual al número de contadores de Evasión que haya sobre la Nave de Nébula.","f":"Seguís el rastro de la nave de Nébula, que maniobra en un intento desesperado por escabullirse de vosotros. Esta podría ser vuestra única oportunidad para arrebatarle la Gema del Poder."},
  "16092a": {"n":"Motor de cuvatura activado","t":"Cuando se muestre esta carta: coloca 2 contadores de Evasión sobre la Nave de Nébula. Por cada contador de Evasión que haya sobre la Nave de Nébula, descarta las 2 primeras cartas del mazo de cada jugador y del mazo de Encuentros.","f":"La nave de Nébula cabecea y vira con experta precisión, eludiendo a la Milano y ganando suficiente distancia como para que la hija de Thanos tenga una oportunidad de escapar."},
  "16092b": {"n":"Motor de curvatura activado","t":"X es igual al número de contadores de Evasión que haya sobre la Nave de Nébula.\nSi se completa esta etapa, los jugadores pierden la partida.","f":"Los motores de la astronave de Nébula están encendidos y a punto. ¡Inutilizadlos antes de que efectúe un salto al hiperespacio!"},
  "16093": {"n":"Nave de Nébula","t":"Interrupción obligada: cuando empiece la fase del Villano, coloca 1 contador de Evasión sobre esta carta.\n¡Disparad a los propulsores! — Acción del jugador inicial: agota la Milano y gasta un máximo de 2 recursos de cualquier tipo → quita 1 contador de Evasión de esta carta por cada recurso gastado de este modo."},
  "16094": {"n":"Ambición sin escrúpulos","t":"Vincula esta carta a Nébula.\nNébula no puede sufrir más de 5 puntos de Daño a consecuencia de un solo ataque.\nEspecial: coloca 1 de Amenaza sobre el Plan principal.\n[star] Aumento: Después de que termine esta activación, vincula esta carta a Nébula y resuelve su capacidad \"Especial\"."},
  "16095": {"n":"Maniobras evasivas","t":"Vincula esta carta a Nébula.\nNébula gana Firmeza.\nEspecial: quedas aturdido. Si ya estabas aturdido, dale a Nébula 1 carta de aumento boca abajo.\n[star] Aumento: Después de que termine esta activación, vincula esta carta a Nébula y resuelve su capacidad \"Especial\"."},
  "16096": {"n":"Constancia férrea","t":"Vincula esta carta a Nébula.\nNébula gana Firmeza.\nEspecial: dale a Nébula una carta de Estado \"Duro\". Si Nébula ya tenía una carta de Estado \"Duro\", dale 1 carta de aumento boca abajo.\n[star] Aumento: Después de que termine esta activación, vincula esta carta a Nébula y resuelve su capacidad \"Especial\"."},
  "16097": {"n":"Maestría con las armas","t":"Vincula esta carta a Nébula.\nNébula gana Represalia 1.\nEspecial: sufres 1 de Daño.\n[star] Aumento: Después de que termine esta activación, vincula esta carta a Nébula y resuelve su capacidad \"Especial\"."},
  "16098": {"n":"Guardia abierta","t":"Vincula esta carta a Nébula.\nLa cantidad de Daño que sufre Nébula de cada ataque se reduce en 1.\nEspecial: descarta 1 carta de tu mano al azar.\n[star] Aumento: Después de que termine esta activación, vincula esta carta a Nébula y resuelve su capacidad \"Especial\"."},
  "16099": {"n":"Intenciones asesinas","t":"Cuando se muestre esta carta: descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Accesorio Técnica. Muestra esa carta."},
  "16100": {"n":"Tonel volado","t":"Incitar 1. Oleada.\nCuando se muestre esta carta: coloca 1 contador de Evasión sobre la Nave de Nébula.\n[star] Aumento: Coloca 1 contador de Evasión sobre la Nave de Nébula."},
  "16101": {"n":"Lista para el combate","t":"Cuando se muestre esta carta: descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Accesorio Técnica. Muestra esa carta, luego resuelve su capacidad \"Especial\".","f":"\"No terminaré nunca hasta que haya conseguido lo que quiero.\" - Nébula"},
  "16102": {"n":"Despiadada","t":"Cuando se muestre esta carta (Alter ego): Nébula ejecuta el Plan. Si se coloca Amenaza a consecuencia de esta activación, coloca 1 contador de Evasión sobre la Nave de Nébula.\nCuando se muestre esta carta (Héroe): Nébula te ataca. Si se inflige Daño a consecuencia de esta activación, coloca 1 contador de Evasión sobre la Nave de Nébula."},
  "16103": {"n":"Ronan el Acusador","t":"Dureza.\n[star]Interrupción obligada: cuando Ronan el Acusador se active contra ti, dale 1 carta de aumento adicional si controlas la Gema del Poder..","f":"\"No habrá discusiones ni debates. Sois culpables.\""},
  "16104": {"n":"Ronan el Acusador","t":"Dureza.\nCuando se muestre esta carta: busca el Plan secundario \"Corte de energía\" en el mazo y la pila de descartes de Encuentros y muéstralo. (Baraja el mazo.)\n[star]Interrupción obligada: cuando Ronan el Acusador se active contra ti, dale 1 carta de aumento adicional si controlas la Gema del Poder."},
  "16105": {"n":"Ronan el Acusador","t":"Represalia 1. Dureza.\nCuando se muestre esta carta: busca el Plan secundario \"Superioridad táctica\" en el mazo y la pila de descartes de Encuentros y muéstralo. (Baraja el mazo.)\n[star]Interrupción obligada: cuando Ronan el Acusador se active contra ti, dale 1 carta de aumento adicional si controlas la Gema del Poder."},
  "16106a": {"n":"Intercepción inminente","t":"Contenido: Ronan el Acusador (I) y Ronan el Acusador (II). (Ronan el Acusador (II) y Ronan el Acusador (III) para jugar en modo Experto.) Conjuntos de Encuentros Ronan el Acusador, Gema del Poder, Nave espacial y Normal. Un conjunto de Encuentros modular (Militantes kree).\nPreparación: pon en juego el Entorno Nave de mando kree y el Apoyo Milano. Vincula el Arma universal a Ronan el Acusador. Vincula la Gema del Poder al jugador inicial."},
  "16106b": {"n":"Intercepción inminente","t":"Acción del jugador inicial: agota la Milano → quita 3 de Amenaza de este Plan.","f":"Las fuerzas de Ronan el Acusador han tendido una emboscada a la Milano con intención de robar la Gema del Poder. Con un ingenio vivo y pericia en los mandos, quizá podáis frenar su avance."},
  "16107a": {"n":"\"Tomaré lo que me pertenece\"","t":"Cuando se muestre esta carta: vincula la Gema del Poder a Ronan el Acusador. Si ya estaba vinculada a él, dale una carta de aumento boca abajo..","f":"La nave de Ronan el Acusador se ha acoplado a la vuestra. Tras abordar la Milano, os derriba a todos con un solo golpe de su arma universal. Antes de que tengáis ocasión de recuperaros, Ronan coge la Gema del Poder."},
  "16107b": {"n":"\"Tomaré lo que me pertenece\"","t":"Mientras la Gema del Poder esté vinculada a Ronan el Acusador, no se podrá quitar Amenaza de este Plan.\nSi se completa esta etapa, los jugadores pierden la partida.","f":"¡Ronan el Acusador tiene la Gema del Poder! Tenéis que arrebatársela antes de que sea demasiado tarde."},
  "16108": {"n":"Nave de mando kree","t":"Interrupción del jugador inicial: cuando se muestre una carta de Perfidia del mazo de Encuentros, agota la Milano y gasta 1 recurso de cualquier tipo → anula los efectos de \"Cuando se muestre esta carta\" de esa carta de Perfidia."},
  "16109": {"n":"Arma universal","t":"Vincula esta carta a Ronan el Acusador.\nRonan el Acusador gana Firmeza.\nAcción de Héroe: sufre 2 de Daño y coge 1 carta de Encuentro boca abajo → devuelve el Arma universal al mazo de Encuentros y barájalo.\n[star] Aumento: Vincula el Arma universal a Ronan el Acusador."},
  "16110": {"n":"Fanatismo","t":"Oleada.\nVincula esta carta a Ronan el Acusador. Usos (1 contador de Furia, más 1[per_hero] contadores de Furia adicionales).\n[star]Interrupción obligada: cuando Ronan el Acusador te ataque, ese ataque gana Brutalidad y Penetrante. Al final de ese ataque, quita 1 contador de Furia de esta carta."},
  "16111": {"n":"Corte de energía","t":"[star] Aumento: elige entre agotar la Milano o bien colocar 2 de Amenaza sobre el Plan principal."},
  "16112": {"n":"Maniobra de pinza","t":"Complicación 2[per_hero] (Cuando se muestre esta carta, coloca 2[per_hero] de Amenaza sobre ella.).\nAcción del jugador inicial: agota la Milano → quita 3 de Amenaza de este Plan."},
  "16113": {"n":"Superioridad táctica","t":"La Gema del Poder no puede desvincularse de Ronan el Acusador.\nCuando se muestre esta carta: vincula la Gema del Poder a Ronan el Acusador. Si ya estaba vinculada a él, coloca 1[per_hero] de Amenaza sobre esta carta.","f":"El avanzado entrenamiento kree de Ronan el Acusador y su determinación fanática lo convierten en un adversario inigualable."},
  "16114": {"n":"Furia obstinada","t":"Cuando se muestre esta carta: Ronan el Acusador ataca al jugador que controle la Gema del Poder (incluso aunque tenga adoptada la identidad de su Alter ego). Si no se produce ningún ataque de este modo, esta carta gana Oleada.\n[star] Aumento: Vincula la Gema del Poder a Ronan el Acusador."},
  "16115": {"n":"Fisiología kree","t":"Oleada.\nCuando se muestre esta carta: dale a Ronan el Acusador una carta de Estado \"Duro\". Si ya tenía una carta de Estado \"Duro\", sufres 1 de Daño.","f":"\"¡Arrodillaos ante mí!\" - Ronan el Acusador"},
  "16116": {"n":"\"¡Se os acusa!\"","t":"Cuando se muestre esta carta (Alter ego): Ronan el Acusador ejecuta el Plan con +1 PLA.\nCuando se muestre esta carta (Héroe): Ronan el Acusador te ataca con +1 ATQ.\n[star] Aumento: Dale al Villano 1 carta de aumento adicional para esta activación."},
  "16117": {"n":"Asesino badoon","t":"Respuesta obligada: después de que el Asesino badoon se enfrente a tu Héroe, te ataca con +2 ATQ.\n[star] Aumento: Si esta activación es un ataque, gana A distancia, Brutalidad y Penetrante."},
  "16118": {"n":"Infantería badoon","t":"Interrupción obligada: después de que la Infantería badoon se enfrente a ti, si no hay ningún otro Esbirro enfrentado a ti, coge 1 carta de Encuentro boca abajo.\n[star] Aumento: Pon en juego la Infantería badoon enfrentada a ti."},
  "16119": {"n":"Lugarteniente badoon","t":"Patrulla. (Mientras este Esbirro esté enfrentado a ti, no podrás intervenir en el Plan principal.)\n[star] Aumento: Si esta activación es una ejecución del Plan, esta carta recibe +2 iconos de aumento ([boost][boost]) para esta activación."},
  "16120": {"n":"Centinela badoon","t":"Represalia 1.\n[star] Aumento: Dale al Villano una carta de Estado \"Duro\". Si el Villano ya tenía una carta de Estado \"Duro\", esta carta recibe +2 iconos de Aumento ([boost][boost]) para esta activación."},
  "16121": {"n":"Caudillo badoon","t":"[star] Los ataque del Caudillo badoon ganan Brutalidad.\n[star] Aumento: Si esta activación es un ataque, esta carta recibe +2 iconos de Aumento ([boost][boost]) para esta activación."},
  "16122": {"n":"Manto de Hércules","t":"Vincula esta carta al enemigo que tenga la puntuación más baja de ATQ.\nAcción de Héroe: gasta recursos [physical][physical][physical] → descarta esta carta.","f":"El manto de Hércules, el legendario semidiós. Esta prenda confiere una fuerza inimaginable a quienes tienen la fortuna de vestirla."},
  "16123": {"n":"Poción de obediencia","t":"Vincula esta carta a tu Superhéroe.\nEl personaje vinculado recibe -1 INT, -1 ATQ, y -1 DEF.\nAcción de Héroe: sufre 1 de Daño y gasta recursos [mental][mental] → descarta esta carta. (Cualquier jugador puede hacer esto.)"},
  "16124": {"n":"Chaqueta del Todopoderoso","t":"Vincula esta carta al enemigo que tenga la puntuación más alta de PLA.\nAcción de Héroe: coloca 2 de Amenaza sobre el Plan principal y gasta 2 recursos del mismo tipo → descarta esta carta."},
  "16125": {"n":"El Veneno","t":"Vincula esta carta a tu Superhéroe.\nInterrupción obligada: cuando empiece tu turno, coloca 1 contador de Veneno sobre esta carta; luego sufres 1 de Daño por cada contador de Veneno que haya sobre esta carta.\nAcción de Héroe: gasta 3 recursos de distintos tipos → descarta esta carta. (Cualquier jugador puede hacer esto.)","f":"La toxina más mortífera de la galaxia."},
  "16126": {"n":"Varita vandariana de energía","t":"Vincula esta carta al enemigo que tenga la puntuación más baja de PLA.\nAcción de Héroe: gasta recursos [energy][energy][energy] → descarta esta carta."},
  "16127": {"n":"Huevo del monarca hujahdariano","t":"Complicación 2[per_hero]. Victoria 0.\nCuando se derrote esta carta: el jugador que haya derrotado este Plan puede preparar su carta de Superhéroe."},
  "16128": {"n":"Tetera mágica","t":"Complicación 2[per_hero]. Victoria 0.\nCuando se derrote esta carta: el jugador que haya derrotado este Plan puede curar 4 de Daño a su Superhéroe."},
  "16129": {"n":"Piedra filosofal","t":"Complicación 2[per_hero]. Victoria 0.\nCuando se derrote esta carta: el jugador que haya derrotado este Plan puede robar 2 cartas."},
  "16130": {"n":"Bola de cristal","t":"Complicación 2[per_hero]. Victoria 0.\nCuando se derrote esta carta: el jugador que haya derrotado este Plan puede jugar una carta desde su mano, reduciendo en 3 su coste en recursos."},
  "16131": {"n":"Armadura de combate kree","t":"Vincula esta carta al enemigo que tenga la puntuación más alta de ATQ.\nReduce en 1 el Daño que sufra el personaje vinculado en cada ataque.\nAcción de Héroe: gasta 3 recursos de un mismo tipo → descarta esta carta."},
  "16132": {"n":"Comando kree","t":"Patrulla. (Mientras este Esbirro esté enfrentado a ti, no podrás intervenir en el Plan principal.)\n[star] Aumento: Si esta activación es un ataque, este ataque gana Penetrante."},
  "16133": {"n":"Lugarteniente kree","t":"Guardia. Firmeza. (Este personaje no puede quedar aturdido ni confundido.)\n[star] Aumento: Si esta activación es un ataque, esta carta recibe +3 iconos de Aumento ([boost][boost]) para esta activación."},
  "16134": {"n":"Soldado kree","t":"Ataque veloz. (Después de que este Esbirro se enfrente a tu Héroe, te ataca.)\n[star] Aumento: Si esta activación es un ataque, este ataque gana Brutalidad."},
  "16135": {"n":"Fantasma psiónico","t":"Cuando se muestre esta carta: quedas confundido. Si ya estabas confundido, sufres 1 de Daño.\n[star] Aumento: Pon en juego al Fantasma psiónico enfrentado a ti."},
  "16136": {"n":"Siervo robótico","t":"Guardia. (Mientras este Esbirro esté enfrentado a ti, no podrás atacar al Villano.)\nPatrulla. (Mientras este Esbirro esté enfrentado a ti, no podrás intervenir en el Plan principal.)","f":"\"ENCONTRAR-A-LOS-INTRUSOS.\""},
  "16137": {"n":"Tiburón espacial","t":"Ataque veloz.\n[star] Los ataques del Tiburón espacial infligen Daño indirecto.\n[star] Aumento: Inflige 1 de Daño a cada personaje que controles."},
  "16138": {"n":"Comandante pirata","t":"Ataque veloz.\n[star] Respuesta obligada: después de que este Esbirro ataque y te inflija Daño, retira del juego 1 carta de tu mano al azar.\n[star] Aumento: Dale al Villano 1 carta de aumento adicional para esta activación."},
  "16139": {"n":"Lacaya pirata","t":"Ataque veloz.\n[star] Respuesta obligada: después de que este Esbirro ataque y te inflija Daño, retira del juego la primera carta de tu mazo.\n[star] Aumento: Dale al Villano 1 carta de aumento adicional para esta activación."},
  "16140": {"n":"Dar la voz de alarma","t":"Todos los enemigos reciben +1 ATQ.\n[star] Aumento: Muestra esta carta."},
  "16141": {"n":"Honor entre ladrones","t":"Cuando se muestre esta carta: descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Esbirro Criminal. Muestra ese Esbirro, luego dale a ese Esbirro una carta de Estado \"Duro\" y dale al Villano 1 carta de aumento boca abajo.","f":"La familia que roba unida permanece unida."},
  "16142": {"t":"Permanente. Inicio.\nEl jugador inicial controla la Milano.\nPilotaje — Recurso: agota la Milano → genera un recurso [wild] para cualquier jugador."},
  "16143": {"n":"Nave hostil","t":"Oleada.\nInterrupción obligada: cuando termine la fase del Villano, inflige 1 de Daño a cada jugador.\nAcción del jugador inicial: agota la Milano y gasta 2 recursos de cualquier tipo → descarta esta carta."},
  "16144": {"n":"A cañonazos","t":"Complicación 3[per_hero] (Cuando se muestre esta carta, coloca 3[per_hero] de Amenaza sobre ella.).\nAcción del jugador inicial: agota la Milano → quita 3 de Amenaza de este Plan."},
  "16145": {"n":"Punto ciego","t":"Peligro. (Mientras estés resolviendo esta carta, los demás jugadores no podrán ayudarte.)\nCuando se muestre esta carta: elige una opción:\n-Agota la Milano.\n-Gasta recursos [physical][physical].\n-Aturde al jugador inicial."},
  "16146": {"n":"Brecha en el casco","t":"Peligro. (Mientras estés resolviendo esta carta, los demás jugadores no podrán ayudarte.)\nCuando se muestre esta carta: Elige una opción:\n-Agota la Milano.\n-Gasta recursos [mental][mental].\n-Inflige 3 de Daño al jugador inicial."},
  "16147": {"n":"Pérdida de energía","t":"Peligro. (Mientras estés resolviendo esta carta, los demás jugadores no podrán ayudarte.)\nCuando se muestre esta carta: Elige una opción:\n-Agota la Milano.\n-Gasta recursos [energy][energy].\n-Descarta 1 carta al azar de la mano del jugador inicial."},
  "16148": {"n":"Entrega especial","t":"Cuando se muestre esta carta (Alter ego): puedes agotar la Milano. Si no lo hacer, el Villano ejecuta el Plan con +1 PLA.\nCuando se muestre esta carta (Héroe): puedes agotar la Milano. Si no lo haces, el Villano te ataca con +1 ATQ."},
  "16149": {"n":"Gema del Poder","t":"Inicio. Vincula esta carta al Villano.\nPermanente.\nInterrupción obligada: después de que un Héroe o Villano inflija al menos 3 de Daño al personaje vinculado con un solo ataque, vincula la Gema del Poder al Héroe o Villano atacante."},
  "16150": {"n":"Compartir ideas","t":"Coste en créditos: 1.\nAcción de Héroe (intervención): nombre un tipo de carta y luego mira la primera carta de tu mazo. Si esa carta es del tipo que has nombrado, quita 3 de Amenaza del Plan principal. Coloca esa carta en la parte superior o inferior de tu mazo y luego roba 1 carta."},
  "16151": {"n":"Por cualquier medio","t":"Coste en créditos: 1.\nAcción de Héroes (ataque): coloca 2 de Amenaza sobre el Plan principal. Inflige 3 de Daño al Villano. Roba 1 carta."},
  "16152": {"n":"Plan de contingencia","t":"Coste en créditos: 1.\nAcción de Héroe (ataque): descarta las 4 primeras cartas de tu mazo. Por cada tipo de recurso distinto que hayas descartado de este modo, inflige 1 de Daño a un enemigo. Roba 1 carta."},
  "16153": {"n":"Actitud desafiante","t":"Coste en créditos: 1.\nInterrupción de Héroes: cuando un Superhéroe vaya a sufrir cualquier cantidad de Daño a consecuencia de un ataque, evita 2 de ese Daño. Roba 1 carta."},
  "16154": {"n":"Cálculo de probabilidades","t":"Coste en créditos: 2.\nAcción de Héroe: roba 1 carta y elige un jugador. Ese jugador puede robar 1 carta, luego elige y descarta 1 carta de su mano."},
  "16155": {"n":"Solución creativa","t":"Coste en créditos: 2.\nAcción de Héroe: roba 1 carta y quítale una carta de Estado a cualquier personaje. Si la carta de Estado que se ha quitado de este modo es:\n- Duro - Inflige 3 de Daño a un enemigo.\n- Aturdido - Quita 3 de Amenaza de un Plan.\n- Confundido - Cura 3 de Daño a un Superhéroe."},
  "16156": {"n":"Forcejeo","t":"Coste en créditos: 2.\nAcción de Héroe: inflige 1 de Daño a un enemigo y atúrdelo. Aturde a tu Héroe. Roba 1 carta."},
  "16157": {"n":"Improvisar sobre la marcha","t":"Coste en créditos: 2.\nAcción de Héroe: inflige 1 de Daño a un enemigo y confúndelo. Confunde a tu Héroe. Roba 1 carta."},
  "16158": {"n":"Por poco","t":"Coste en créditos: 3.\nInterrupción de Héroe: cuando se ponga boca arriba una carta de aumento, anula su capacidad de \"Aumento\" y todos sus iconos de Aumento ([boost]), luego descártala. Roba 1 carta."},
  "16159": {"n":"Afrontar el peligro","t":"Coste en créditos: 3.\nAcción de Héroe (ataque): inflige 5 de Daño a un enemigo y descarta la primera carta del mazo de Encuentros. Sufres 1 de Daño por cada icono de Aumento ([boost]) que se haya descartado de este modo."},
  "16160": {"n":"Vidas en peligro","t":"Coste en créditos: 3.\nAcción de Héroe (intervención): sufres 2 de Daño. Quita 5 de Amenaza de un Plan."},
  "16161": {"n":"Pasar la ofensiva","t":"Coste en créditos: 3.\nAcción de Héroe: mira las 2[per_hero] primeras cartas del mazo de Encuentros. Descarta cualquier cantidad de esas cartas, luego coloca el resto en la parte superior o inferior del mazo de Encuentros, en cualquier combinación y orden que prefieras. Roba 1 carta."},
  "16162": {"n":"Blindaje","t":"Coste en créditos: 4.\nInterrupción de Héroe: cuando un Superhéroe vaya a sufrir cualquier cantidad de Daño, agota el Blindaje → evita 1 de ese Daño (2 de ese Daño si controlas la Milano)."},
  "16163": {"n":"Cañón pesado","t":"Coste en créditos: 4.\nAcción de Héroe: agota el Cañón pesado → inflige 1 de Daño a todos los enemigos. Si controlas la Milano, inflige 1 de Daño adicional al Villano."},
  "16164": {"n":"Hiperpropulsores","t":"Coste en créditos: 4.\nAcción de Héroe: agota los Hiperpropulsores → quita 1 de Amenaza de cada Plan. Si controlas la Milano, quita 1 de Amenaza adicional del Plan principal."},
  "16165": {"n":"Núcleo del reactor","t":"Coste en créditos: 4\nAcción de Héroe: agota el Núcleo del reacto y descarta las 2 primeras cartas de tu mazo (sólo la primera carta si controlas la Milano) → reduce en 1 el coste en recursos del próximo Evento que juegues en este turno."},
  "16166": {"n":"Feroz determinación","t":"Coste en créditos: 5.\nAcción de Héroe: prepara un personaje amigo. Roba 1 carta."},
  "16167": {"n":"Carga impetuosa","t":"Coste en créditos: 5.\nInterrupción de Héroe: cuando se muestre una carta del mazo de Encuentros, anula sus efectos y descártala."},
  "16168": {"n":"Resguardo","t":"Coste en créditos: 5.\nAcción de Héroe: dale una carta de Estado \"Duro\" a un máximo de 2 personajes amigos. Roba 1 carta."},
  "16169": {"n":"Apuesta segura","t":"Coste en créditos: 5.\nAcción de Héroe: reduce en 3 el coste en recursos de la próxima carta que se juegue en esta fase."},
  "16170": {"n":"Bodega de carga","t":"Coste en créditos: 6.\nAcción de Héroe: agota la Bodega de carga → cura 1 de Daño a un personaje amigo. Si controlas la Milano, cura 1 de Daño a tu Superhéroe."},
  "16171": {"n":"Láser fijo","t":"Coste en créditos: 6.\nAcción de Héroe: agota el Láser fijo → inflige 2 de Daño a un enemigo (3 de Daño si controlas la Milano)."},
  "16172": {"n":"Consola de navegación","t":"Coste en créditos: 6.\nAcción de Héroe: agota la Consola de navegación, elige 1 carta de tu mano y descártala (descarta en su lugar la primera carta de tu mazo si controlas la Milano) → roba 1 carta."},
  "16173": {"n":"Pantalla de selección de blancos","t":"Coste en créditos: 6.\nAcción de Héroe: agota la Pantalla de selección de blancos → quita 2 de Amenaza de un Plan (3 de Amenaza si controlas la Milano)."},
  "16174": {"n":"Gran estrategia","t":"Coste en créditos: 7.\nAcción de Héroe: roba cartas hasta alcanzar el tamaño máximo de tu mano. Retira esta carta del juego."},
  "16175": {"n":"Poder desatado","t":"Coste en créditos: 7.\nAcción de Héroe: inflige 5 de Daño al Villano y quita 5 de Amenaza del Plan principal. Retira esta carta del juego."},
  "16176": {"n":"Eficacia probada","t":"Coste en créditos: 7.\nAcción de Héroe: elige un jugador. Ese jugador puede añadir a su mano hasta 3 cartas de su pila de descartes. Retira esta carta del juego."},
  "16177": {"n":"Triple ventaja","t":"Coste en créditos: 7.\nAcción de Héroe: prepara un máximo de 3 personajes. Retira esta carta del juego."},
  "16178a": {"n":"Incursión badoon","t":"Sólo en modo Normal.\nComplicación 3[per_hero]. Victoria 1.\nCuando se derrote esta carta: cada jugador puede robar 1 carta."},
  "16178b": {"n":"Incursión badoon","t":"Sólo en modo Experto.\nComplicación 4[per_hero]. Victoria 1.\nCuando se derrote esta carta: cada jugador debe elegir 1 carta de su mana y descartarla."},
  "16179a": {"n":"Galería del Esplendor","t":"Sólo en modo Normal.\nComplicación 3[per_hero]. Victoria 1.\nCuando se derrote esta carta: coge la primera carta del mazo de cada jugador y colócala boca arriba en la Colección."},
  "16179b": {"n":"Galería del Esplendor","t":"Sólo en modo Experto.\nComplicación 4[per_hero]. Victoria 1.\nCuando se derrote esta carta: cada jugador debe coger 1 carta de su mano al azar y colocarla boca arriba en la Colección."},
  "16180a": {"n":"\"No hay escapatoria\"","t":"Sólo en modo Normal.\nComplicación 3[per_hero]. Victoria 1.\nCuando se derrote esta carta: inflige 1 de Daño a cada jugador."},
  "16180b": {"n":"\"No hay escapatoria\"","t":"Sólo en modo Experto.\nComplicación 4[per_hero]. Victoria 1.\nCuando se derrote esta carta: inflige 2 de Daño a cada jugador."},
  "16181a": {"n":"Tácticas de guerrilla","t":"Sólo en modo Normal.\nComplicación 3[per_hero]. Victoria 1.\nCuando se derrote esta carta: coloca 2 contadores de Evasión sobre la Nave de Nébula."},
  "16181b": {"n":"Tácticas de guerrilla","t":"Sólo en modo Experto.\nComplicación 4[per_hero]. Victoria 1.\nCuando se derrote esta carta: coloca 3 contadores de Evasión sobre la Nave de Nébula."},
  "16182a": {"n":"Supremacía kree","t":"Sólo en modo Normal.\nComplicación 3[per_hero]. Victoria 1."},
  "16182b": {"n":"Supremacía kree","t":"Sólo en modo Experto.\nComplicación 4[per_hero]. Victoria 1."},
  "16183": {"n":"Cazador de cabezas badoon","t":"Victoria 2. Infame.\n[star] Aumento: Pon en juego al Cazador de cabezas badoon enfrentado a ti."},
  "16184": {"n":"De cacería","t":"Oleada.\nCuando se muestre esta carta: elige entre sufrir 2 de Daño o bien descartar 1 carta de tu mano al azar.\n[star] Aumento: Dale al Villano 1 carta de aumento adicional para esta activación."},
  "16185": {"n":"Culpable de un delito","t":"Oleada.\nCuando se muestre esta carta: agota tu carta de Superhéroe. Si no puedes hacerlo, coloca 2 de Amenaza sobre el Plan principal.\n[star] Aumento: Dale al Villano 1 carta de aumento adicional para esta activación."},
  "16186": {"n":"Secuaz de cazador de cabezas","t":"Oleada. Patrullas."},
  "16187": {"n":"Captura de fugitivos","t":"Oleada. Complicación 3[per_hero]."},
  "17001a": {"n":"Starlord","t":"Todos los aliados que controles ganan el rasgo Guardián.\n\"¿Qué podría salir mal?\" — Interrupción: cuando juegues una carta desde tu mano, coge 1 carta de Encuentro boca abajo → reduce en 3 el coste en recursos para jugar esa carta. (Límite de una vez por ronda.)"},
  "17001b": {"t":"Preparación: busca una copia de la Mejora Pistola elemental en tu mazo y en tu pila de descartes y añádela a tu mano. Baraja tu mazo.\nLabia — Acción: elige una carta de tu mano. Intercambia esa carta por la primera carta de tu mazo. (Límite de una vez por ronda.)"},
  "17002": {"t":"Respuesta: después de que juegues a Nova Prime desde tu mano, derrota a un Esbirro que no sea Élite.","f":"\"¡Esto es por el Cuerpo Nova!\" - Nova Prime"},
  "17003": {"n":"Huida temeraria","t":"Acción de Héroe: coge 1 carta de Encuentro boca abajo → prepara tu Héroe y roba 1 carta.","f":"\"No es por fardar, pero fijo que eso ha sido lo más valiente que ha hecho ninguno de nosotros.\" - Starlord"},
  "17004": {"n":"Maniobra audaz","t":"Acción de Héroe (intervención): quita 2 de Amenaza de un Plan. Quita 2 de Amenaza adicional de ese Plan por cada carta de Encuentro que tengas boca abajo delante de ti."},
  "17005": {"n":"Deslizarse disparando","t":"Juega esta carta sólo si controlas una Pistola elemental.\nAcción de Héroe (ataque): inflige 5 de Daño a un enemigo. Inflige 2 de Daño adicional a ese enemigo por cada carta de Encuentro que tengas boca abajo delante de ti."},
  "17006": {"n":"Chico Malo","t":"Interrupción de Héroe: cuando vayas a sufrir cualquier cantidad de Daño causado por el ataque del Villano, descarta esta carta → evita todo ese Daño. Adopta la identidad de tu Alter ego y roba 2 cartas.","f":"\"¡Volando con estilo!\" - Peter Quill"},
  "17007": {"n":"Pistola elemental","t":"Restringida. (Máximo de 2 cartas Restringidas por jugador.)\nAcción de Héroe (ataque): agota la Pistola elemental y gasta 1 recurso de cualquier tipo → inflige 3 de Daño a un enemigo. Este ataque gana Penetrante."},
  "17008": {"n":"Botas de vuelo","t":"Starlord gana el rasgo Aéreo.\nInterrupción de Héroe: cuando Starlord vaya a sufrir cualquier cantidad de Daño, agota las Botas de vuelo → evita 1 de ese Daño por cada carta de Encuentro que tengas boca abajo delante de ti."},
  "17009": {"n":"Líder de los Guardianes","t":"Cada personaje Guardián que controles recibe +1 INT.","f":"\"Sé que nos odiamos todos y que todos tratamos de matarnos unos a otros. Pero a partir de ahora, y hasta que el trabajo esté hecho… somos Guardianes.\" - Peter Quill"},
  "17010": {"n":"Casco de Starlord","t":"Mientras tengas adoptada tu identidad de Héroe, recibes +1 al tamaño de tu mano por cada carta de Encuentro que tengas boca abajo delante de ti (hasta un máximo de +3 al tamaño de tu mano).","f":"\"No puedes ver mi cara de reproche, pero tengo cara de reproche.\" - Starlord"},
  "17011": {"t":"Respuesta: después de que Adam Warlock ataque o intervenga, descarta 1 carta de tu mano al azar. Si el recurso impreso de esa carta tiene:\n[physical] - Quita 3 de Amenaza de un plan.\n[energy] - Cura 3 de Daño a un Superhéroe.\n[mental] - Inflige 3 de Daño a un enemigo.\n[wild] - Elige una de las opciones anteriores."},
  "17012": {"n":"Bill Rayos Beta","t":"Respuesta: después de que Bill Rayos Beta ataque y derrote a un Esbirro, quita 2 de Amenaza del Plan principal.","f":"\"Puede que no sea nativo del reino eterno, pero el poder de mi martillo viene directamente de Odín. ¡Así que lucho por Asgard, en este día y en todos los mañanas!\""},
  "17013": {"t":"[star] Los ataques de Yondu ganan A distancia. (Los ataques con A distancia ignoran la Represalia.)","f":"\"No necesito a nadie. Hago lo que quiero, cuando quiero y como quiero.\" - Yondu"},
  "17014": {"n":"Supremacía aérea","t":"Acción de Héroe: elige hasta X enemigos, siendo X el número de personajes Aéreo que controles → inflige 3 de Daño a cada enemigo elegido."},
  "17015": {"n":"Heroísmo suicida","t":"Máximo de 1 por ronda.\nAcción de Héroe: todo personaje Guardián recibe +2 INT y +2 ATQ en esta fase. Al final de la fase, inflige 1 de Daño a cada personaje Guardián."},
  "17016": {"n":"Preparación","t":"Acción: prepara un Aliado.","f":"\"Nos entrenamos sin descanso todos los días para estar preparados cuando llegue el momento.\" —Steve Rogers"},
  "17017": {"n":"Prácticas de tiro","t":"Interrupción: cuando un Aliado que tenga una Mejora Arma realice un ataque, descarta Prácticas de tiro → ese Aliado recibe +2 ATQ para ese ataque.","f":"\"Nos lo están poniendo muy fácil.\" - Starlord"},
  "17018": {"n":"El poder del liderazgo","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta de Liderazgo (azul)."},
  "17019": {"n":"Pistola láser","t":"Vincula esta carta a un Aliado Guardián. Máximo de 1 por aliado.\nEl Aliado vinculado recibe +1 ATQ y sus ataques ganan Brutalidad.","f":"\"Acabaré contigo enseguida.\" - Nébula"},
  "17020": {"t":"Interrupción: cuando Cosmo ataque o intervenga, nombra un tipo de carta y luego descarta la primera carta de un mazo. Si esa carta es del tipo nombrado, Cosmo no sufre Daño derivado (el Daño que figura debajo de INT o ATQ) con este uso."},
  "17021": {"n":"N.G.I.I.","t":"Acción de Héroe: agota N.G.I.I. y gasta 2 recursos de cualquier tipo → prepara un personaje Guardián.","f":"\"No sé, a mí me gusta llamarla Nave Guay Interestelar Interesteladora.\" - Peter Quill"},
  "17022": {"n":"Sapiencial","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Guardián.\nTu límite de Aliados se incrementa en 1.\nRespuesta: después de que un jugador juege un Aliado Guardián, agota Sapiencial → ese jugador roba 1 carta."},
  "17023": {"n":"Granada de pulsos","t":"Acción de Héroe (ataque): descarta la Granada de pulsos y elige un enemigo → descarta las 2 primeras cartas del mazo de Encuentros. Inflige 1 de Daño al enemigo elegido por cada icono de Aumento ([boost]) que se haya descartado de este modo."},
  "17024": {"n":"Destierro","t":"Dale esta carta al jugador que lleva a Peter Quill.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n• Agota a Peter Quill → retira del juego Destierro.\n• Descarta una Pistola elemental que esté en juego. Si no puedes hacerlo, coloca 3 de Amenaza sobre el Plan principal. Descarta esta Obligación."},
  "17025": {"n":"Sindicato del crimen en ciernes","t":"Complicación 2[per_hero]. (Cuando se muestre esta carta, coloca 2[per_hero] de Amenaza sobre ella.)","f":"\"Tal vez en tu diminuto cerebro la línea entre los actos criminales y un imperio sea fina. En realidad, no le importa a nadie. Lo único que les interesa es quién sostiene el arma y adónde apunta ésta.\" - J'son"},
  "17026": {"n":"Señor Cuchillo","t":"Represalia 1.\nLa primera carta de Perfidia que muestre el jugador enfrentado en cada fase del Villano gana Oleada.\n(Esbirro Archienemigo de Starlord.)"},
  "17027": {"n":"Astucia spartoi","t":"Cuando se muestre esta carta: descarta 1 carta de tu mano al azar, sufre 1 de Daño y coloca 1 de Amenaza sobre el Plan principal.","f":"\"¿Cómo esperas triunfar cuando tienes a toda la galaxia en tu contra?\" - J'son"},
  "17028": {"n":"Arrojarse en picado","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Aéreo.\nAcción de Héroe (ataque): inflige 7 de Daño a un enemigo. Inflige 1 de Daño a todos los demás enemigos."},
  "17029": {"n":"Vuelo ágil","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Aéreo.\nAcción de Héroe (intervención): quita un total máximo de 5 de Amenaza de diversos Planes (a tu elección)."},
  "17030": {"n":"Vigilancia constante","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Aéreo.\nAcción de Héroe: prepara tu Héroe y quita 2 de Amenaza del Plan principal.","f":"\"Me siento como si todo el peso del mundo recayera sobre mis hombros.\" - Capitana Marvel"},
  "17031": {"n":"Consciencia mejorada","t":"Usos (3 contadores Mentales).\nRecurso de Héroe: agota la Consciencia mejorada y quítale 1 contador Mental → genera un recurso [mental]."},
  "18001a": {"t":"Sutileza — Respuesta: después de que juegues un Evento Ataque, quita 1 de Amenaza de un Plan. (Límite de una vez por fase).\nPrecisión — Respuesta: después de que juegues un Evento Intervención, inflige 1 de Daño a un enemigo. (Límite de una vez por fase.)"},
  "18001b": {"t":"Experta en tácticas — Puedes incluir en tu mazo hasta 6 Eventos de Ataque e Intervención de otros aspectos que no sean el que has elegido.\nAcción: mira la primera carta de tu mazo. Si esa carta es un Evento Ataque o Intervención, róbala. (Límite de una vez por ronda.)"},
  "18002": {"n":"Nébula","t":"Respuesta: después de que Nébula entre en juego, busca en tu mazo un Evento Ataque o Intervención y añádelo a tu mano. Baraja tu mazo.","f":"\"Será un combate breve.\""},
  "18003": {"n":"Movimiento acrobático","t":"Acción de Héroe (ataque): inflige 2 de Daño a un enemigo.","f":"\"Si me conocieras tan bien como crees, no me habrías atacado.\" —Gamora"},
  "18004": {"n":"Devolver el golpe","t":"Interrupción de Héroe (ataque/defensa/intervención): cuando vayas a sufrir cualquier cantidad de Daño, evita 3 de ese Daño. Inflige 1 de Daño a un enemigo. Quita 1 de Amenaza de un Plan.","f":"\"¡Esa decisión será la última que tomarás!\" —Gamora"},
  "18005": {"n":"Marcar el ritmo","t":"Acción de Héroe (intervención): quita 1 de Amenaza de un Plan.","f":"\"No se dan cuenta de que ha terminado.\" —Gamora"},
  "18006": {"n":"Golpe decisivo","t":"Acción de Héroe (ataque): inflige 4 de Daño a un enemigo (7 de Daño si has jugado un Evento Intervención en este turno).","f":"\"Thanos me creó para un único propósito: matar. Pronto comprenderá que fua una mala decisión.\" —Gamora"},
  "18007": {"n":"Ímpetu","t":"Acción de Héroe (intervención): quita 3 de Amenaza de un Plan (5 de Amenaza si has jugado un Evento Ataque en ester turno).","f":"\"Esto no va a acabar bien para ti.\" —Gamora"},
  "18008": {"n":"Sala de ejercicio","t":"Acción de Alter ego: agota la Sala de ejercicio → coge el primer Evento de Ataque o Intervención que haya en la parte inferior de tu pila de descartes y devuélvelo a tu mano. Cura 1 de Daño a Gamora.","f":"\"Yo siempre estoy preparada.\" —Gamora"},
  "18009": {"n":"Instinto agudizado","t":"Recurso: agota Instinto agudizado → genera un recurso [wild] para un Evento Ataque o Intervención.","f":"\"Arriésgate conmigo. No lo lamentarás.\" —Gamora"},
  "18010": {"n":"Espada de Gamora","t":"Restringida.\nRespuesta: después de que juegues un Evento Ataque, inflige 1 de Daño a un enemigo."},
  "18011": {"t":"Respuesta obligada: después de que Angela entre en juego controlada por ti, busca un Esbirro entre las 10 primeras cartas del mazo de Encuentros y ponlo en juego enfrentado a ti. Baraja el mazo de Encuentros. Si no se pone en juego un Esbirro de este modo, descarta a Angela."},
  "18012": {"n":"Vapuleo","t":"Acción de Héroe (ataque) inflige 3 de Daño a un enemigo. Si ésta es la primera carta que has jugado en la ronda actual, devuévela a tu mano.","f":"\"Como tenga que golpearte otra vez, ya no volverás a levantarte. Nunca.\" —Gamora"},
  "18013": {"n":"Plan de ataque","t":"Acción: busca un Evento Ataque entre las 4 primeras cartas de tu mazo (las primeras 7 si tienes adoptada tu identidad de Alter ego) y añádelo a tu mano. Baraja tu mazo.","f":"\"No, ya tengo un plan. Atacar.\" - Starlord"},
  "18014": {"n":"Gancho","t":"Acción de Héroe (ataque): inflige 5 de Daño a un enemigo.","f":"¡PAF!"},
  "18015": {"n":"Primer impacto","t":"Acción de Héroe (ataque): inflige 2 de Daño al Villano.\nInterrupción de Héroe (ataque): cuando un Esbirro inicie un ataque, inflígele 2 de Daño."},
  "18016": {"n":"Cortar el paso","t":"Acción de Héroe (intervención): quita 3 de Amenaza del Plan principal. Si ésta es la primera carta que has jugado en la ronda actual, devuévela a tu mano.","f":"\"Primero vais a tener que pasar por encima de mí.\" - Starlord"},
  "18017": {"n":"Entrenamiento de combate","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nTu Héroe recibe +1 ATQ.","f":"\"¡Tony! ¡Lo ha vuelto a hacer!\" —Janet Van Dyne"},
  "18018": {"n":"Matadioses","t":"Restringida.\nInterrupción de Héroe: cuando tu Héroe realice un ataque básico contra un enemigo único ([unique]), agota Matadioses → tu Héroe recibe +2 ATQ para ese ataque."},
  "18019": {"t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Guardián.\nDrax no puede atacar a Esbirros.","f":"\"¡Fijaos, este combate me ha levantado el ánimo!\""},
  "18020": {"n":"Ataque relámpago","t":"Acción de Héroe (ataque/intervención): inflige 2 de Daño a un enemigo. Quita 2 de Amenaza de un Plan.","f":"\"¿Sabes, mi señora Gamora? Aun cuando nos conocimos y te estaba dando una paliza tremenda, pensé: seguro que podríamos ser amigas.\" - Angela"},
  "18021": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "18022": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "18023": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "18024": {"n":"Destino inconcluso","t":"Dale esta carta al jugador que lleva a Gamora.\nPuedes adoptar la identidad de tu Alter ego. Eliga una opción:\n• Agota tu Alter ego → retira del juego Destino inconcluso.\n• Elige 2 Eventos de tu mano y descártalos. Descarta esta Obligación."},
  "18025": {"n":"Rivalidad entre hermanas","t":"Ningún jugador que no lleve a Gamora puede quitar Amenaza de Rivalidad entre hermanas.\nInterrupción obligada: después de que empiece la fase del Villano, dale 1 carta de Encuentro boca abajo a Gamora.","f":"\"Algún día, hermana, nuestro padre se dará cuenta de que soy mucho más digna que tú.\" - Nébula"},
  "18026": {"n":"Nébula","t":"Represalia 2.\nInterrupción obligada: cuando este Esbirro vaya a entrar en juego, descarta del juego la carta de Aliado de Nébula.\n(Esbirro Archienemigo de Gamora.)"},
  "18027": {"n":"Contra las cuerdas","t":"Vincula esta carta a Gamora.\nEl texto de reglas impreso de Gamora se trata como si estuviese en blanco (a excepción de los rasgos).\nAcción de Héroe: elige y descarta un Evento ataque de tu mano e inflige 1 de Daño a Gamora → descarta esta carta."},
  "18028": {"n":"Atacada a traición","t":"Cuando se muestre esta carta: aturde y confunde a Gamora. Si Gamora ya estaba aturdida o confundida, esta carta gana Oleada.","f":"\"No seguirás siendo la favorita de padre durante mucho tiempo, querida hermana.\" - Nébula"},
  "18029": {"n":"Punto de inflexión","t":"Acción de Héroe (ataque): inflige 2 de Daño al Villano (5 de Daño si no hay Amenaza sobre el Plan principal).","f":"\"No es exactamente lo que tenía pensado… ¡pero me vale!\" - Mapache Cohete"},
  "18030": {"n":"Comunicador implantado","t":"Vincula esta carta a un Aliado Guardián. Máximo de 1 por Aliado.\nEl Aliado vinculado recibe +1 INT y +1 de Vida.","f":"\"Esto… ¿vienes mucho por aquí?\" - Peter Quill"},
  "18031": {"n":"Brío","t":"Respuesta (intervención): después de que tu Héroe defienda contra un ataque enemigo, quita tanta Amenaza de un Plan como la INT de tu Héroe.","f":"\"¡Pero recordad que no he empezado yo\" - Luke Cage"},
  "18032": {"n":"Reflejos mejorados","t":"Usos (3 contadores de Energía).\nRecurso de Héroe: agota Reflejos mejorados y quítale 1 contador de Energía → genera un recurso [energy]."},
  "19001a": {"t":"Drax recibe +1 ATQ por cada contador de Venganza que tenga.\nRespuesta: después de que el Villano ataque a Drax, coloca 1 contador de Venganza sobre esta carta (hasta un máximo de 3). Si no es posible, roba 1 carta."},
  "19001b": {"t":"Respuesta obligada: después de que cambies a esta identidad, quita todos los contadores de Venganza de Drax. Cúrale 2 de Daño por cada contador de Venganza que se haya quitado de este modo."},
  "19002": {"t":"Acción: agota a Mantis e inflígele 1 de Daño → cura 3 de Daño a un Superhéroe.","f":"\"¡Hazle daño a ésta y lo lamentarás!\""},
  "19003": {"n":"\"¡Enfréntate a mí, cobarde!\"","t":"Acción de Héroe: prepara tu Héroe y roba 1 carta. El Villano te ataca.","f":"\"¡Escúchame, Thanos! ¡Seas titán o dios, te aniquilaré!\" - Drax"},
  "19004": {"n":"Intimidación","t":"Acción de Héroe (intervención): quita X de Amenaza de un Plan, siendo X igual a tu ATQ.","f":"\"Presta mucha atención, porque sólo te lo voy a decir una vez: márchate y vivirás.\" - Drax"},
  "19005": {"n":"Salto y apuñalamiento","t":"El coste para jugar esta carta se reduce en 1 por cada contador de Venganza que haya sobre Drax.\nInterrupción de Héroe: cuando realices un ataque básico, recibes +5 ATQ para ese ataque. Ese ataque gana Brutalidad y Penetrante."},
  "19006": {"n":"Parada","t":"Interrupción de Héroe (defensa): cuando vayas a sufrir cualquier cantidad de Daño, evita X de ese Daño (siendo X igual al doble de tu ATQ).","f":"\"¡Eres un necio si crees que voy a sucumbir ante alguien de tu calaña!\" - Drax"},
  "19007": {"n":"Vengar afrenta","t":"Respuesta de Héroe (ataque): después de que el Villano te ataque, inflige X de Daño al Villano (siendo X igual a tu ATQ).","f":"\"¿Apuñalarla ayudaría?\" - Drax"},
  "19008": {"n":"El puñal de Drax","t":"Restringida. (Máximo de 2 cartas Restringidas por jugador.)\nMientras tenga adoptada su identidad de Héroe, Drax recibe +1 ATQ."},
  "19009": {"n":"El otro puñal de Drax","t":"Restringida. (Máximo de 2 cartas Restringidas por jugador.)\nMientras tenga adoptada su identidad de Héroe, Drax gana Represalia 1."},
  "19010": {"n":"Maestro de dwi theet","t":"Respuesta de Héroe: después de que Drax realice un ataque básico, roba 1 carta.","f":"\"¡Me vengaré de Thanos!\" - Drax"},
  "19011": {"n":"Demasiado terco para morir","t":"Interrupción de Héroe: cuando Drax vaya a ser derrotado, en vez de eso fija su medidor de Vida en 4, cámbialo a su identidad de Alter ego y retira esta carta del juego."},
  "19012": {"n":"Mártir","t":"Respuesta: después de que Mártir sufra Daño derivado al realizar un ataque, si dicho ataque ha derrotado a un enemigo, dale una carta de Estado \"Duro\".","f":"\"¿Queréis aprender sobre el dolor? ¡Yo os enseñaré!\""},
  "19013": {"n":"Dragón Lunar","t":"Acción: agota y descarta a Dragón Lunar → elige un Esbirro. Ese Esbirro ataca a otro enemigo de tu elección.","f":"\"¡¿Cómo te atreves a interrumpir mi meditación?!\""},
  "19014": {"n":"Contragolpe","t":"Respuesta (ataque): después de que tu Héroe defienda contra un ataque enemigo, inflige tanto Daño a ese enemigo como el ATQ de tu Héroe.","f":"\"¡Te lo tienes bien merecido!\" —Puño de Hierro"},
  "19015": {"n":"Desvío","t":"Interrupción de Héroe: cuando un Superhéroe vaya a sufrir cualquier cantidad de Daño a consecuencia de un ataque, evita hasta 5 de ese Daño. Descarta tantas cartas de la parte superior de tu mazo como la cantidad evitada de este modo."},
  "19016": {"n":"Una dura lección","t":"Acción de Héroe (ataque): inflige 4 de Daño a un enemigo. Si este ataque derrota a ese enemigo, dale a tu Héroe una carta de Estado \"Duro\".","f":"\"Así aprenderás a no subestimarme.\" - Starlord"},
  "19017": {"n":"Golpe de tanteo","t":"Interrupción de Héroe: cuando tu Héroe realice un ataque básico, descarta la primera carta del mazo de Encuentros → el ATQ de tu Héroe para ese ataque se reduce en tantos puntos como número de iconos de Aumento que haya impresos en esa carta. Si aun así el ataque inflige Daño, prepara a tu Héroe."},
  "19018": {"n":"Sometimiento","t":"Interrupción de Héroe: cuando un enemigo inicie un ataque, ese enemigo recibe -3 ATQ para ese ataque.","f":"\"¡Atrás, bestia!\" - Capitán América"},
  "19019": {"n":"Indómito","t":"Respuesta: después de que tu Héroe defienda, descarta Indómito → prepara a tu Héroe.","f":"\"No tenemos elección. Lucharemos... y venceremos. No hay otra opción.\" —Capitán América"},
  "19020": {"t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Guardián.\nRespuesta de Héroe: después de que Gamora ataque o intervenga, descarta cartas de la parte superior de tu mazo hasta que descartes un Evento, luego añade esa carta a tu mano."},
  "19021": {"n":"Preparación física","t":"Acción de Héroe: descarta 1 carta de Estado \"Aturdido\" o \"Confundido\" de tu Héroe.","f":"\"Descuida, los oídos dejarán de pitarte… un día de estos.\" - Nadia Van Dyne"},
  "19022": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "19023": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "19024": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "19025": {"n":"Recuerdos de otra vida","t":"Dale esta carta al jugador que lleva a Drax.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n• Agota tu Alter ego → retira del juego Recuerdos de otra vida.\n• Quedas aturdido. Si ya estabas aturdido, esta carta gana Oleada. Descarta esta Obligación."},
  "19026": {"n":"Sacrifica a los débiles","t":"Todos los enemigos reciben +2 ATQ.","f":"Yotat el Destructor se ha propuesto librar la galaxia de todos aquellos a quienes considere inferiores."},
  "19027": {"n":"Yotat el Destructor","t":"Guardia. Represalia 1.\n(Esbirro Archienemigo de Drax.)","f":"\"¡Te postrarás ante el verdadero Destructor!\""},
  "19028": {"n":"Reto aceptado","t":"Oleada.\nVincula esta carta al enemigo que tenga la puntuación más alta de ATQ.\nRespuesta obligada: después de que Drax inflija al menos 4 de Daño al enemigo vinculado con un solo ataque, descarta esta carta."},
  "19029": {"n":"\"¡Te destruiré!\"","t":"Cuando se muestre esta carta (Alter ego): esta carta gana Oleada.\nCuando se muestre esta carta (Héroe): Yotat el Destructor te ataca con +1 ATQ. Si no se produce ningún ataque de este modo, el Villano te ataca.","f":"\"¡No si yo te destruyo antes!\" - Drax"},
  "19030": {"n":"\"¡Os reviento!\"","t":"Máximo de 1 por fase.\nAcción de Héroe: roba 1 carta por cada Esbirro que esté enfrentado a ti.","f":"\"¡Has escogido un mal día para meterte conmigo, colega!\" - Mapache Cohete"},
  "19031": {"n":"\"¡Espabila!\"","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Guardián.\nAcción de Héroe: sufres 1 de Daño. Confunde al Villano.","f":"\"¡Oye, no te enfades conmigo! Que te he avisado.\" - Mapache Cohete"},
  "19032": {"n":"Reagrupamiento","t":"Interrupción: cuando un Aliado sea derrotado por un ataque enemigo, devuévelo a la mano de su propietario en vez de descartarlo.\nInterrupción obligada: cuando termine la ronda, descarta esta carta."},
  "19033": {"n":"Vigor mejorado","t":"Usos (3 contadores Físicos).\nRecurso de Héroe: agota Vigor mejorado y quítale 1 contador Físico → genera un recurso [physical]."},
  "20001a": {"n":"Veneno","t":"Puedes controlar 1 Mejora adicional que tenga la palabra clave Restringida.\nUnión simbiótica — Recurso: sufre 1 de Daño → genera un recurso [wild]. (Límite de una vez por fase.)"},
  "20001b": {"t":"Puedes controlar 1 Mejora adicional que tenga la palabra clave Restringida.\nBien pertrechado — Preparación: descarta cartas de la parte superior de tu mazo hasta que descartes una Mejora Arma, luego añade esa carta a tu mano."},
  "20002": {"n":"Tras las líneas enemigas","t":"Acción de Héroe: (intervención): quita 3 de Amenaza de un Plan. Si has pagado el coste de esta carta exclusivamente con recursos [mental], confunde a un enemigo.","f":"\"Lo entiendo, señor. El país es lo primero.\" - Veneno"},
  "20003": {"n":"Tentáculos constrictores","t":"Interrupción de Héroe (defensa): cuando el Villano inicie un ataque contra ti, evita ese ataque. Si has pagado el coste de esta carta exclusivamente con recursos [physical], aturde al Villano."},
  "20004": {"n":"Armas a punto","t":"Acción busca en tu mazo una Mejora Arma y añádela a tu mano. Baraja tu mazo.","f":"\"¡Estaba deseando que llegara este momento!\" - Veneno"},
  "20005": {"n":"Disparo en movimiento","t":"Acción de Héroe: prepara a Veneno y todas las Mejoras Arma que controles.","f":"\"Pues tendrá que ser por las malas.\" - Veneno"},
  "20006": {"n":"Ataque feroz","t":"Acción de Héroe (ataque): inflige 5 de Daño a un enemigo. Si has pagado el coste de esta carta exclusivamente con recursos [energy], este ataque gana Brutalidad.","f":"\"La rabia alimenta a mi simbionte. La rabia lo hace fuerte\" - Flash Thompson"},
  "20007": {"n":"Proyecto Renacimiento 2.0","t":"Acción de Alter ego: agota el Proyecto Renacimiento 2.0 → elige entre robar 1 carta o curar 3 de Daño a Flash Thompson.","f":"\"El segundo proyecto de supersoldados del gobierno estadounidense consistía en injertar simbiontes a los veteranos de mayor talento.\""},
  "20008": {"n":"Multicañón","t":"Restringida.\nAcción de Héroe: agota el Multicañón → elige una de las siguientes opciones:\nInflige 2 de Daño a un enemigo.\nElige un jugador. Inflige 1 de Daño a cada Esbirro que esté enfrentado a ese jugador.\nQuita 2 de Amenaza de un Plan."},
  "20009": {"n":"Sentido arácnido","t":"Interrupción de Héroe: cuando el Villano inicie un ataque contra ti, roba 1 carta.","f":"\"Siento una especie de... cosquilleo.\" - Veneno"},
  "20010": {"n":"Pistola de Veneno","t":"Restringida. (Máximo de 2 cartas Restringidas por jugador.)\nInterrupción de Héroe: cuando uses uno de los atributos básicos de Veneno, agota la Pistola de Veneno → Veneno suma +1 a ese atributo para este uso."},
  "20011": {"n":"Jack Bandera","t":"Respuesta: después de que Jack Bander intervenga, colócale encima 1 contador de Munición.\nAcción de Héroe: agota a Jack Bandera y quítale 1 contador de Munición → inflige 2 de Daño a un enemigo."},
  "20012": {"n":"Táctica intimidatoria","t":"Acción de Héroe: (ataque): inflige 3 de Daño a un enemigo que esté confundido.","f":"\"¡Bu!\""},
  "20013": {"n":"Entrada espectacular","t":"Interrupción de Héroe: cuando tu Héroe realice una intervención básica, recibe +2 INT para esa intervención. Después de que termine esa intervención, si tu Héroe ha quitado toda la Amenaza de un Plan gracias a ella, cura 2 de Daño a tu Héroe."},
  "20014": {"n":"El poder de la justicia","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta de Justicia (amarilla)."},
  "20015": {"n":"Fusil sónico","t":"Restringida. Usos (2 contadores de Carga).\nAcción de Héroe: agota el Fusil sónico y quítale 1 contador de Carga → confunde a un enemigo (si ya está confundido, en vez de eso inflige 3 de Daño a ese enemigo)."},
  "20016": {"n":"Starlord","t":"[star] Los ataques de Starlord ganan A distancia.\nRespuesta obligada: después de que Starlord entre en juego controlado por ti, coge 1 carta de Encuentro boca abajo.","f":"El que no arriesga, no gana."},
  "20017": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "20018": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "20019": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "20020": {"n":"Ingenio","t":"Recurso: descarta Ingenio → genera un recurso [wild]","f":"\"La innovación es el arma definitiva.\" —Visión"},
  "20021": {"n":"Pistolera de cinto","t":"Juega esta carta poniéndola bajo el control de cualquier jugador.\nMáximo de 1 por jugador.\nPuedes controlar 1 Mejora Arma adicional que tenga la palabra clave Restringida."},
  "20022": {"n":"Pistola de plasma","t":"Restringida. (Máximo de 2 cartas Restringidas por jugador.)\nUsos (3 contadores de Carga).\nAcción de Héroe: agota la Pistola de plasma y quítale 1 contador de Carga → inflige 1 de Daño a un enemigo."},
  "20023": {"n":"Luchar por el control","t":"Dale esta carta al jugador que lleva a Flash Thompson.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n• Agota a Flash Thompson y sufre 2 de Daño → descarta Luchar por el control.\n• Coge 1 copia de Simbionte rabioso que esté apartada y ponla en juego enfrentada al jugador inicial. Si no puedes hacerlo, esta carta gana Oleada. Descarta esta Obligación."},
  "20024": {"n":"Frenesí Klyntar","t":"No puede quitarse Amenaza de este Plan mientras haya en juego un enemigo Simbionte.","f":"El simbionte de Veneno está descontrolado; se une a todos los que entran en contacto con él y les provoca arrebatos de furia destructiva."},
  "20025": {"n":"Simbionte rabioso","t":"Guardia. Patrulla.\n(Esbirro Archienemigo de Veneno.)\n[star] Aumento: Pon en juego al Simbionte rabioso enfrentado a ti."},
  "20026": {"n":"Lluvia de balas","t":"Acción de Héroe (ataque): agota una Mejora Arma que controles → inflige 5 de Daño a un enemigo.","f":"\"Dadme algo a lo que disparar.\""},
  "20027": {"n":"\"Bienvenido a bordo\"","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Guardián. Máximo de 1 por ronda.\nAcción de Héroe: reduce en 2 el coste en recursos del próximo Aliado que se juegue en esta fase.","f":"\"¿Guardianes, uníos? ¿Agrupaos? Jo, pues no se me ocurre nada.\" - Peter Quill"},
  "20028": {"n":"Ignorar las heridas","t":"Respuesta de Héroe: después de que un personaje Guardián sufra cualquier cantidad de Daño a consecuencia de un ataque, dale a ese personaje una carta de Estado \"Duro\".","f":"\"Groot, colega, ya sé que puedes regenerarte y todo eso, pero deberías tener más cuidado.\" - Mapache Cohete"},
  "20029": {"n":"Camarote de tripulante","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nAcción de Alter ego: agota el Camarote de tripulante → cura 1 de Daño a un Alter ego."},
  "21001a": {"t":"Transformación de energía — Respuesta obligada: después de que cambies a esta identidad, elige una Mejora de Identidad de energía que esté boca abajo → pon esa carta boca arriba para cambiar a esa identidad de energía.","f":"\"Llámame Mónica. O Spectrum, si eres malo.\""},
  "21001b": {"t":"Preparación: pon en juego las 3 Mejoras de Identidad de energía, boca abajo.\nAhorro de energía — Respuesta obligada: después de que cambies a esta identidad, pon boca abajo todas tus Mejoras de Identidad de energía."},
  "21002": {"t":"Identidad de energía. Permanente.\nSpectrum recibe +2 ATQ.\nRespuesta de Héroe: después de que cambies a esta identidad de energía, inflige 1 de Daño a un enemigo."},
  "21003": {"n":"Fotones","t":"Identidad de energía. Permanente.\nSpectrum recibe +2 INT.\nRespuesta de Héroe: después de que cambies a esta identidad de energía, quita 1 de Amenaza de un Plan."},
  "21004": {"n":"Púlsar","t":"Identidad de energía. Permanente.\nSpectrum recibe +2 DEF.\nRespuesta de Héroe: después de que cambies a esta identidad de energía, cura 1 de Daño a Spectrum."},
  "21005": {"n":"Maravilla Azul","t":"Respuesta de Héroe: después de que Maravilla Azul entre en juego, cambia tu identidad de energía.","f":"\"Hago lo que es correcto, donde y cuando haga falta hacerlo, y no me importa lo que nadie piense.\""},
  "21006": {"n":"Duplicación energética","t":"Recurso de Héroe: agota Duplicación energética → genera el recurso impreso en la Mejora de Identidad de energía que tengas boca arriba.","f":"\"Puedo adoptar la forma de cualquier tipo de energía que se me antoje.\" —Spectrum"},
  "21007": {"n":"Estallido gamma","t":"Acción de Héroe (ataque): cambia a tu identidad de energía Gamma e inflige 7 de Daño a un enemigo. Si ya tenías adoptada la identidad de energía Gamma, este ataque gana Brutalidad.","f":"\"Yo tampoco me haría enfadar.\" — Spectrum"},
  "21008": {"n":"Velocidad fotónica","t":"Acción de Héroe (intervención): cambia a tu identidad de energía Fotones y quita 4 de Amenaza de un Plan. Si ya tenías adoptada la identidad de energía Fotones, ignora el icono de Crisis ([crisis]) durante esta intervención.","f":"\"¿Buscabas esto?\" — Spectrum"},
  "21009": {"n":"Escudo púlsar","t":"Interrupción de Héroe (defensa): cuando Spectrum defienda, cambia a tu identidad de energía Púlsar y prepara a Spectrum. Si ya tenías adoptada la identidad de energía Púlsar, Spectrum gana Represalia 1 hasta el final de la fase."},
  "21010": {"n":"Velocidad de la luz","t":"Acción de Héroe: cambia de identidad de energía y roba 1 carta.","f":"\"Llegaré en un centelleo.\" — Spectrum"},
  "21011": {"n":"Capitán América","t":"Dureza.\nEl coste para jugar al Capitán América se reduce en 1 por cada personaje Vengador que controles.","f":"\"¡Vengadores, reuníos!\""},
  "21012": {"t":"Power Man entra en juego con 2 contadores de Chi.\nAcción: descarta cualquier número de contadores de Chi de Power Man → Power Man recibe +2 ATQ hasta el final de la fase por cada contador de Chi descartado de este modo."},
  "21013": {"n":"Tigre Blanco","t":"Respuesta: después de que juegues a Tigre Blanco desde tu mano, roba X cartas (hasta un máximo de 3), siendo X igual al número de la etapa del Villano. Si el Villano no tiene número de etapa, roba 1 carta."},
  "21014": {"t":"Respuesta: después de que Kaluu entre en juego, busca un Evento entre las 5 primeras cartas de tu mazo → añade ese Evento a tu mano. Baraja tu mazo."},
  "21015": {"n":"Poderosos Vengadores","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 carta de Grupo por jugador.\nSi todos tus personajes tienen el rasgo Vengador, todos los Aliados que controles reciben +1 INT y +1 ATQ."},
  "21016": {"n":"Ataque masivo","t":"Acción de Héroe (ataque): agota 3 Aliados que controles y que compartan un Rasgo con tu Héroe → inflige X de Daño a un enemigo, siendo X la puntuación combinada de ATQ de esos Aliados y tu Héroe."},
  "21017": {"n":"Aplomo","t":"Respuesta de Héroe: después de que cambies de identidad, tu Héroe recibe +1 INT, +1 ATQ y +1 DEF hasta el final de la ronda.","f":"\"Si te metes con uno de nosotros, ¡te las ves con todos! Aunque sea el último.\" - Nova"},
  "21018": {"n":"Todos juntos","t":"Esta carta genera un recurso [wild] por cada Aliado que controles (máximo 3)."},
  "21019": {"t":"[star] Respuesta obligada: después de que Blade intervenga o ataque, elige entre gastar un recurso [physical] de tu mano o descartar a Blade.","f":"\"¿Y a ti cuántas veces te voy a tener que matar?\""},
  "21020": {"n":"Torre de los Vengadores","t":"Si todos tus Aliados tienen el rasgo VENGADOR, tu límite de Aliados se incrementa en 1.\nAcción: agota la Torre de los Vengadores → reduce en 1 el coste del siguiente Aliado VENGADOR que se juegue en esta fase."},
  "21021": {"n":"Mansión de los Vengadores","t":"Máximo de 1 por jugador.\nAcción: agota la Mansión de los Vengadores → elige un jugador. Ese jugador roba 1 carta.","f":"\"¿Te has acordado de cerrar con llave?\" —Janet Van Dyne"},
  "21022": {"n":"En pie de guerra","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nRespuesta de Héroe: después de que cambies de identidad, descarta esta carta → prepara tu Héroe."},
  "21023": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "21024": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "21025": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "21026": {"n":"Pérdida de control","t":"Dale esta carta al jugador que lleva a Monica Rambeau.\nNo puedes cambiar de identidad de energía.\nAcción de Alter ego: agota a Mónica Rambeau → retira del juego Pérdida de control."},
  "21027": {"n":"Hombre Radiactivo","t":"[star] Respuesta obligada: después de que el Hombre Radiactivo se active contra ti, inflige 1 de Daño a cada personaje que controles.\n[star] Aumento: inflige 1 de Daño a cada personaje que controles."},
  "21028": {"n":"Fusión de núcleo","t":"Cuando se derrote esta carta: inflige 1 de Daño a cada personaje amigo que esté en juego.","f":"¡El Hombre Radiactivo está usando su poder para sobrecargar un reactor nuclear!"},
  "21029": {"n":"Consumir energía","t":"Vincula esta carta a tu Superhéroe.\nRespuesta obligada: después de que termine tu turno, sufres 1 de Daño.\nAcción de Alter ego: gasta recursos [energy][energy] → descarta esta carta."},
  "21030": {"n":"Descarga radiactiva","t":"Cuando se muestre esta carta (Alter ego): coloca 2 de Amenaza sobre el Plan principal.\nCuando se muestre esta carta (Héroe): sufres 2 de Daño.","f":"\"No puedes ganar esta pelea.\" -Hombre Radiactivo"},
  "21031a": {"t":"Magia de combate — Acción: descarta 1 carta de tu mano. Límite de una vez por fase. Si esa carta es de:\n- Agresividad — Inflige 2 de Daño a un enemigo.\n- Justicia — Quita 2 de Amenaza de un Plan.\n- Protección — Cura 1 de Daño a un Aliado.\n- Liderazgo — Dale a un Héroe +1 INT, +1 ATQ y +1 DEF en esta ronda."},
  "21031b": {"t":"Avatar de la vida — Durante la creación de tu mazo, debes incluir la misma cantidad de cartas de cada uno de los 4 aspectos. No puedes incluir más de 1 copia de ninguna carta que no sea de Adam Warlock.\nAcción: descarta una carta de tu mano → quita una carta de Estado a Adam Warlock."},
  "21032": {"n":"Pip el Troll","t":"Dureza.\nMientras Pip el Troll esté en tu mano, gana: \"Interrupción: cuando un jugador sea atacado, gasta recursos [energy][mental] → pon en juego a Pip el Troll controlado por ese jugador."},
  "21033": {"n":"Mundo del alma","t":"Respuesta: después de que se acaben las cartas de tu mazo, coloca 1 contador de Alma sobre esta carta.\nAcción de Alter ego: agota el Mundo del alma y quítale 1 contador de Alma → cura todo el Daño que haya sufrido tu Superhéroe."},
  "21034": {"n":"Vara kármica","t":"Recurso: agota la Vara Kármica → genera un recurso [wild]."},
  "21035": {"n":"Capa de Warlock","t":"Respuesta de Héroe: después de que resuelvas la capacidad \"Magia de combate\" de Adam Warlock, agota la Capa de Warlock → prepara a Adam Warlock.","f":"\"Una cosa te digo sobre Adam: el tío sabe cómo lucir una capa.\" —Starlord"},
  "21036": {"n":"Salvaguardia cósmica","t":"Interrupción obligada: cuando muestres una carta de Perfidia, anula los efectos de su enunciado \"Cuando se muestre esta carta\" y descártala. Luego descarta Salvaguardia cósmica.","f":"\"Mientras siga en pie, desafío vuestro poder… ¡y lo contrarrestaré con el mío propio!\" —Adam Warlock"},
  "21037": {"n":"Sentidos místicos","t":"Respuesta de Héroe: después de que resuelvas la capacidad \"Magia de combate\" de Adam Warlock, roba 1 carta.","f":"\"Los recuerdos de la omnipotencia huyen con la experiencia.\" —Adam Warlock"},
  "21038": {"n":"Rayo kármico","t":"Acción de Héroe (ataque): inflige 4 de Daño a un enemigo y descarta hasta 4 cartas de la parte superior de tu mazo → inflige 1 de Daño adicional a ese enemigo por cada aspecto distinto que se haya descartado de este modo (Agresisivdad, Justicia, Liderazgo y Protección´)."},
  "21039": {"n":"Conciencia cósmica","t":"Acción de Héroe (intervención): quita 3 de Amenaza de un Plan y descarta hasta 4 cartas de la parte superior de tu mazo → quita 1 de Amenaza adicional de ese Plan por cada aspecto distinto que se haya descartado de este modo (Agresividad, Justicia, Liderazgo y Protección´)."},
  "21040": {"n":"Magia cuántica","t":"Acción: elige una carta que esté en tu pila de descartes → añade esa carta a tu mano.","f":"\"Creen que estoy muerto. Y, mientras crean eso, no esperarán en absoluto lo que estoy a punto de desatar.\" —Adam Warlock"},
  "21041": {"t":"Interrupción: cuando Marvel Boy ataque, gasta un recurso [physical] → este ataque gana A distancia y Penetrante.","f":"\"Venid conmigo si queréis molar.\""},
  "21042": {"n":"El Intermediador","t":"Acción: añade esta carta al mazo de Encuentros y barájalo (sin mirar).\nCuando se muestre esta carta: inflige 2 de Daño al Villano y retira esta carta del juego. Este efecto no puede anularse."},
  "21043": {"n":"Ataque mágico","t":"Juega esta carata sólo si tu Superhéroe tiene el rasgo Místico. Máximo de 1 por mazo.\nAcción de Héroe (ataque): elige un enemigo y descarta hasta 5 cartas de la parte superior de tu mazo → inflige 1 de Daño a ese enemigo por cada carta descartada de este modo."},
  "21044": {"n":"Gancho","t":"Acción de Héroe (ataque): inflige 5 de Daño a un enemigo.","f":"¡PAF!"},
  "21045": {"n":"Entrenamiento de combate","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nTu Héroe recibe +1 ATQ.","f":"\"¡Tony! ¡Lo ha vuelto a hacer!\" —Janet Van Dyne"},
  "21046": {"n":"Audacia","t":"Máximo de 1 por mazo.\nRespuesta de Héroe: después de que gastes esta carta, inflige 1 de Daño al Villano."},
  "21047": {"t":"Respuesta: después de que Quasar entre en juego, quita 1 de Amenaza de cada Plan que haya en juego.","f":"\"Soy el protector del universo. Esto es a lo que me dedico.\""},
  "21048": {"n":"Tribunal Viviente","t":"Acción: añade esta carta al mazo de Encuentros y barájalo (sin mirar).\nCuando se muestre esta carta: quita 2 de Amenaza del Plan principal y retira esta carta del juego. Este efecto no puede anularse."},
  "21049": {"n":"¡Por la justicia!","t":"Acción de Héroe (intervención): quita 3 de Amenaza de un Plan (4 de Amenaza si has pagado el coste de esta carta usando un recurso [mental]).","f":"\"Has perdido. Y vas a responder por tus actos.\" —Capitán América"},
  "21050": {"n":"Zona de silencio","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Místico. Máximo de 1 por mazo.\nAcción de Héroe (intervención): elige un Plan y descarta hasta 4 cartas de la parte superior de tu mazo → quita 1 de Amenaza de ese Plan por cada carta descartada de este modo."},
  "21051": {"n":"Intuición heroica","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nTu Héroe recibe +1 INT."},
  "21052": {"n":"Determinación","t":"Máximo de 1 por mazo.\nRespuesta de Héroe: después de que gastes esta carta, quita 1 de Amenaza del Plan principal."},
  "21053": {"n":"Mayor Victoria","t":"Interrupción: cuando el Mayor Victoria sea derrotado, elige un personaje Guardián amigo → prepara ese personaje.","f":"\"Un gran hombre llevó este escudo y murió defendiéndo a otros. Estoy dispuesto a hacer lo mismo si fuera necesario."},
  "21054": {"n":"Eternidad","t":"Acción: añade esta carta al mazo de Encuentros y barájalo (sin mirar).\nCuando se muestre esta carta: roba 1 carta y retira esta carta del juego. Este efecto no puede anularse."},
  "21055": {"n":"Hechizo de convocación","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Místico. Máximo de 1 por mazo.\nAcción de Héroe: descarta cartas de la parte superior de tu mazo hasta que descartes un Aliado → pon en juego ese Aliado controlado por ti."},
  "21056": {"n":"Hacer la llamada","t":"Acción: paga el coste impreso de un Aliado que esté en la pila de descartes de cualquier jugador → pon en juego ese Aliado controlado por ti.","f":"\"¡Código rojo! ¡Todo el mundo a sus puestos!\" —María Hill"},
  "21057": {"n":"Inspiración","t":"Vincula esta carta a un Aliado. Máximo de 1 por Aliado.\nEl Aliado vinculado recibe +1 INT y +1 ATQ.","f":"\"Menos mal que está de nuestra parte.\" —Starlord"},
  "21058": {"n":"Innovación","t":"Máximo de 1 por mazo.\nRespuesta de Héroe: después de que gastes esta carta, cura 1 de Daño a un Aliado que controles."},
  "21059": {"t":"Represalia 1. Dureza."},
  "21060": {"n":"El Jardinero","t":"Acción: añade esta carta al mazo de Encuentros y barájalo (sin mirar).\nCuando se muestre esta carta: cura 2 de Daño a tu Superhéroe y retira esta carta del juego. Este efecto no puede anularse."},
  "21061": {"n":"Hechizo de escudo","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Místico. Máximo de 1 por mazo.\nInterrupción de Héroe (defensa): cuando vayas a sufrir cualquier cantidad de Daño a consecuencia de un ataque, descarta ese mismo número de cartas de la parte superior de tu mazo → evita todo el Daño de este ataque."},
  "21062": {"n":"Contragolpe","t":"Respuesta (ataque): después de que tu Héroe defienda contra un ataque enemigo, inflige tanto Daño a ese enemigo como el ATQ de tu Héroe.","f":"\"¡Te lo tienes bien merecido!\" —Puño de Hierro"},
  "21063": {"n":"Chaleco blindado","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nTu Héroe recibe +1 DEF.","f":"Te salva la vida con estilo."},
  "21064": {"n":"Preservación","t":"Máximo de 1 por mazo.\nRespuesta de Héroe: después de que gastes esta carta, cura 1 de Daño a tu Héroe."},
  "21065": {"t":"El coste para jugar a Martinex se reduce en 1 si tu Superhéroe tiene el rasgo Guardián.","f":"\"Albergo mis dudas sobre esta realidad.\""},
  "21066": {"n":"Ciclo de regeneración","t":"Dale esta carta al jugador que lleva a Adam Warlock.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n-Agota tu Alter ego → retira del juego Ciclo de regeneración.\n-Descarta las 5 primeras cartas de tu mazo. Coloca 1 de Amenaza sobre el Plan principal por cada aspecto distinto que se haya descartado de este modo. Descarta esta Obligación."},
  "21067": {"n":"El Magus","t":"Ataque veloz. Dureza.\n[star] Respuesta obligada: después de que El Magus se active contra ti, descarta las 5 primeras cartas de tu mazo.\n(Esbirro Archienemigo de Adam Warlock.)"},
  "21068": {"n":"Iglesia Universal de la Verdad","t":"Respuesta obligada: después de que un jugador restablezca su mazo, agota al Superhéroe de ese jugador y atúrdelo.\n[star] Aumento: muestra esta carta."},
  "21069": {"n":"Fanático de la Verdad","t":"No puede quitarse Amenaza del Plan secundario \"Iglesia Universal de la Verdad\".\n[star] Aumento: pon en juego al Fanático de la Verdad enfrentado a ti."},
  "21070": {"n":"Inquisición cósmica","t":"Incitar 2.\nCuando se muestre esta carta: si está en juego el Plan secundario \"Iglesia Universal de la Verdad\", descarta las 10 primeras cartas de tu mazo. De no ser así, busca la Iglesia Universal de la Verdad en el mazo de Encuentros, en su pila de descartes y en la zona apartada, y muéstrala. Baraja el mazo de Encuentros."},
  "21071": {"n":"Fauces Negras","t":"[star]Interrupción obligada: cuando Fauces Negras se active contra tu, quita un contador de Invocación de cada carta Hechizo que haya en tu zona de juego.","f":"\"Tus poderes son curiosos. Deja que te enseñe cómo es la magia de verdad.\""},
  "21072": {"n":"Fauces Negras","t":"[star]Interrupción obligada: cuando Fauces Negras se active contra ti, quita un contador de Invocación de cada carta Hechizo que haya en tu zona de juego.\nCuando se muestre esta carta: cada jugador descarta cartas de la parte superior del mazo de Encuentros hasta que descarte un Hechizo, y pone en juego esa carta en su zona de juego."},
  "21073": {"n":"Fauces Negras","t":"[star]Interrupción obligada: cuando Fauces Negras se active contra ti, quita un contador de Invocación de cada carta Hechizo que haya en tu zona de juego.\nCuando se muestre esta carta: cada jugador descarta cartas de la parte superior del mazo de Encuentros hasta que descarte un Hechizo, y pone en juego esa carta en su zona de juego."},
  "21074a": {"n":"Ataque a Sapiencial","t":"Contenido: Fauces Negras (I) y Fauces Negras (II). (Fauces Negras (II) y Fauces Negras (III) para jugar en modo Experto.) Conjuntos de Encuentros de Fauces Negras y Normal. Dos conjuntos de Encuentros modulares (Ejércitos de Titán y Orden Negra)."},
  "21074b": {"n":"Ataque a Sapiencial","t":"Cuando se muestre esta carta: cada jugador descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Entorno Hechizo, y pone en juego esa carta en su zona de juego. Baraja el mazo de Encuentros junto con su pila de descartes.","f":"Fauces Negras lidera el asalto a Sapiencial con el prorósito de conseguir la Gema del Poder custodiada en su interior."},
  "21075a": {"n":"La Gema del Poder","t":"Cuando se muestre esta carta: baraja el mazo de Encuentros junto con su pila de descartes. Cada jugador descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Entorno Hechizo, y pone en juego esa carta en su zona de juego."},
  "21075b": {"n":"La Gema del Poder","t":"Si se completa esta etapa, los jugadores pierden la partida.","f":"Fauces Negras emplea su poderosa magia para manteneros ocupados mientras sus agentes buscan la Gema del Poder."},
  "21076": {"n":"Bola de fuego","t":"Oleada.\nEntra en juego con 4 contadores de Invocación.\nRespuesta obligada: después de que se quite el último contador de Invocación de la Bola de fuego, descártala → inflige 4 de Daño a tu Superhéroe."},
  "21077": {"n":"Manipulación","t":"Oleada.\nEntra en juego con 2 contadores de Invocación.\nRespuesta obligada: después de que se quite el último contador de Invocación de Manipulación, descártala → descarta 1 carta de tu mano al azar. Quedas confundido."},
  "21078": {"n":"Pacificación","t":"Oleada.\nEntra en juego con 3 contadores de Invocación.\nRespuesta obligada: después de que se quite el último contador de Invocación de Pacificación, descártala → agota todas las Mejoras que controles. Quedas aturdido."},
  "21079": {"n":"Rociada de escombros","t":"Oleada.\nEntra en juego con 3 contadores de Invocación.\nRespuesta obligada: después de que se quite el último contador de Invocación de Rociada de escombros, descártala → inflige 2 de Daño a cada personaje que controles."},
  "21080": {"n":"Agente de Thanos","t":"Cuando se muestre esta carta (Alter ego): coloca 1 de Amenaza sobre el Plan principal por cada Entorno Hechizo que haya en tu zona de juego. Si no colocas Amenaza de este modo, esta carta gana Oleada.\nCuando se muestre esta carta (Héroe): inflige 1 de Daño a tu Héroe por cada Entorno Hechizo que haya en tu zona de juego. Si no sufres ningún Daño de este modo, esta carta gana Oleada."},
  "21081": {"n":"Trance canalizador","t":"Cuando se muestre esta carta: quita 1 contador de Invocación de cada Entorno Hechizo que haya en tu zona de juego. Si no hay ningún Entorno Hechizo en tu zona de juego, descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Entorno Hechizo. Pon en juego esa carta en tu zona de juego."},
  "21082": {"n":"Abjuración","t":"Vincula esta carta a Fauces Negras.\nEvita todo el Daño recibido por Fauces Negras.\nRespuesta obligada: después de que la Abjuración evite al menos 2 de Daño en un solo ataque, descártala."},
  "21083": {"n":"Retención","t":"Vincula esta carta al personaje amigo que tenga la puntuación más alta de ATQ y agótalo.\nEl personaje vinculado no puede prepararse.\nAcción de Héroe: gasta recursos [energy][physical] → descarta esta carta.","f":"\"Chist. Ya has incordiado bastante.\" —Fauces Negras"},
  "21084": {"n":"Sobrecarga del reactor","t":"Cuando se muestre esta carta: cada jugador debe elegir entre sufrir 2 de Daño o colocar 2 de Amenaza sobre esta carta.","f":"Las tropas de Fauces han asaltado la sala de máquinas de Sapiencial y han iniciado la sobrecarga de su reactor principal."},
  "21085": {"n":"Enano Negro","t":"[star] Los ataques de Enano Negro ganan Brutalidad.","f":"\"Enano Negro es una herramienta tosca, pero tiene su utilidad.\" -Thanos"},
  "21086": {"n":"Supergiganta","t":"Ataque veloz.\n[star] Respuesta obligada: después de que Supergiganta ataque a un personaje y le cause Daño, ese personaje queda aturdido.","f":"\"Dicen que mi mente se ha quebrado; pero no importa, puedo devorar la tuya.\""},
  "21087": {"n":"La Orden Negra","t":"Mientras haya en juego un Esbirro Orden Negra, no podrá quitarse Amenaza de este Plan secundario.","f":"\"Thanos ha reclutado a los mercenarios más peligrosos de la galaxia para formar la Orden Negra.\""},
  "21088": {"n":"Tenemos sangre de sobra","t":"Cuando se muestre esta carta: cada Esbirro que esté enfrentado a un juegador se activa contra ese jugador. Cada jugador que no esté enfrentado a un Esbirro busca un Esbirro Orden Negra en el mazo de Encuentros y en su pila de descartesm y lo pone en juego enfrentado a él. Baraja el mazo de Encuentros."},
  "21089": {"n":"Infantería de la Orden Negra","t":"Guardia.\nCuando se derrote esta carta: dale al Villano una carta de Estado \"Duro\".\n[star] Aumento: dale al Villano una carta de Estado \"Duro\"."},
  "21090": {"n":"Batidor","t":"Cuando se muestre esta carta: descarta 1 carta de tu mano al azar.\n[star] Aumento: descarta 1 carta de tu mano al azar.","f":"\"Los batidores son criaturas diseñadas genéticamente y sometidas por completo a la voluntad de su creador.\""},
  "21091": {"n":"Nave de desembarco","t":"Cuando se derrote esta carta: descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Esbirro. Pon en juego ese Esbirro enfrentado al jugador que haya derrotado este Plan."},
  "21092": {"n":"Medianoche Próxima","t":"[star] Interrupción obligada: cuando Medianoche Próxima te ataque, elige entre infligir 1 de Daño a la Torre de los Vengadores o bien que Medianoche Próxima reciba +2 ATQ para este ataque.\nMedianoche Próxima no puede ser derrotada mientras a Corvus Glaive le quede Vida."},
  "21093": {"n":"Medianoche Próxima","t":"[star] Interrupción obligada: cuando Medianoche Próxima te ataque, elige entre infligir 1 de Daño a la Torre de los Vengadores o bien que Medianoche Próxima reciba +2 ATQ para este ataque.\nMedianoche Próxima no puede ser derrotada mientras a Corvus Glaive le quede Vida."},
  "21094": {"n":"Medianoche Próxima","t":"[star] Interrupción obligada: cuando Medianoche Próxima te ataque, elige entre infligir 1 de Daño a la Torre de los Vengadores o bien que Medianoche Próxima reciba +2 ATQ para este ataque.\nMedianoche Próxima no puede ser derrotada mientras a Corvus Glaive le quede Vida."},
  "21095": {"t":"[star] Respuesta obligada: después de que Corvus Glaive realice un ataque no defendido, descarta la primera carta de la parte superior del mazo de Encuentros → inflige 1 de Daño a la Torre de los Vengadores por cada icono de Aumento ([boost]) que haya en esa carta.\nCorvus Glaive no puede ser derrotado mientras a Medianoche Próxima le quede Vida."},
  "21096": {"t":"[star] Respuesta obligada: después de que Corvus Glaive realice un ataque no defendido, descarta la primera carta de la parte superior del mazo de Encuentros → inflige 1 de Daño a la Torre de los Vengadores por cada icono de Aumento ([boost]) que haya en esa carta.\nCorvus Glaive no puede ser derrotado mientras a Medianoche Próxima le quede Vida."},
  "21097": {"t":"[star] Respuesta obligada: después de que Corvus Glaive realice un ataque no defendido, descarta la primera carta de la parte superior del mazo de Encuentros → inflige 1 de Daño a la Torre de los Vengadores por cada icono de Aumento ([boost]) que haya en esa carta.\nCorvus Glaive no puede ser derrotado mientras a Medianoche Próxima le quede Vida."},
  "21098a": {"n":"Bajo asedio","t":"Contenido: Medianoche Próxima I y Medianoche Próxima II (etapas II y III para jugar en modo Experto). Corvus Glaive I y II (etapas II y III para jugar en modo Experto). Conjuntos de Encuentros Defender la Torre y Normal. Un conjunto de Encuentros modular (Ejércitos de Titán).\nPreparación: muestra la etapa 2A y ponla en juego junto a esta etapa de modo que haya dos Planes principales y dos Villanos en juego."},
  "21098b": {"n":"Bajo asedio","t":"Plan de Medianoche Próxima.\nInterrupción obligada: cuando vaya a completarse esta etapa, en vez de eso quita toda la Amenaza que haya sobre esta etapa. Luego inflige 6[per_hero] de Daño a la Torre de los Vengadores.","f":"Medianoche Próxima lidera a la Orden Negra en un ataque directo contra la Torre de los Vengadores."},
  "21099a": {"n":"Los ejércitos de Thanos","t":"Cuando se muestre esta carta: pon en juego el Entorno Torre de los Vengadores con la cara de Fortaleza boca arriba. Pon en juego el Accesorio Defensa tenaz vinculado a esta etapa. Cada jugador busca en el mazo de Encuentros una copia de Tropa de asedio de la Orden Negra y la pone en juego enfrentada a él. Baraja el mazo de Encuentros."},
  "21099b": {"n":"Los ejércitos de Thanos","t":"Plan de Corvus Glaive.\nInterrupción obligada: cuando vaya a completarse esta etapa, en vez de eso quita toda la Amenaza que haya sobre esta etapa. Luego dale a cada jugador 1 carta de Encuentro boca abajo.","f":"Corvus Glaive encabeza el ataque al frente de sus tropas, empleando su ingenio táctico para contrarrestar las defensas de los Vengadores."},
  "21100a": {"n":"Torre de los Vengadores","t":"La regla de las cartas únicas no se aplica a la Torre de los Vengadores.\nRespuesta obligada: después de que se coloque Daño sobre esta carta, si hay al menos 9[per_hero] de Daño sobre ella, quítalo todo. Luego dale la vuelta a la Torre de los Vengadores."},
  "21100b": {"n":"Torre de los Vengadores","t":"Cuando se muestre esta carta: descarta del juego todas las demás cartas de Torre de los Vengadores.\nRespuesta obligada: después de que se coloque Daño sobre esta carta, si hay al menos 9[per_hero] de Daño sobre ella, los jugadores pierden la partida."},
  "21101": {"n":"Defensa tenaz","t":"Permanente.\nEl Villano correspondiente al Plan vinculado es el Villano activo.\nRespuesta obligada: después de que termine la fase de los Jugadores, vincula esta carta al otro Plan principal."},
  "21102": {"n":"Tropa de asedio de la Orden negra","t":"Respuesta obligada: después de que la Tropa de asedio de la Orden Negra se enfrente a ti, elige entre infligir 1 de Daño a la Torre de los Vengadores o bien infligir 2 de Daño a tu Superhéroe."},
  "21103": {"n":"Lanza de Medianoche","t":"Vincula esta carta a Medianoche Próxima.\n[star] Los ataques de Medianoche Próxima ganan Brutalidad y Penetrante.\nAcción de Héroe: sufre 1 de Daño y gasta recursos [energy][mental] → descarta esta carta."},
  "21104": {"n":"Guja de Corvus","t":"Vincula esta carta a Corvus Glaive.\nCorvus Glaive gana Represalia 1.\nAcción de Héroe: sufre 1 de Daño y gasta recursos [energy][physical] → descarta esta carta."},
  "21105": {"n":"Asalto directo","t":"Vincula esta carta al Villano que no sea el Villano activo.\n[star] Interrupción obligada: cuando el Villano vinculado ataque, ese ataque gana A distancia. Si ese ataque derrota a un Aliado, inflige 3 de Daño a la Torre de los Vengadores. Al final de ese ataque, descarta Asalto directo."},
  "21106": {"n":"El poder de Medianoche","t":"Cuando se muestre esta carta: Medianoche Próxima se activa contra ti.\n[star] Aumento: añade las puntuaciones de PLA y ATQ del otro Villano a las de este Villano para esta activación.","f":"\"¡En nombre de Thanos! ¡Muere!\" —Medianoche Próxima"},
  "21107": {"n":"La astucia de Corvus","t":"Cuando se muestre esta carta: Corvus Glaive se activa contra ti.\n[star] Aumento: añade las puntuaciones de PLA y ATQ del otro Villano a las de este Villano para esta activación.","f":"\"He aquí tu tributo, Thanos.\" —Corvus Glaive"},
  "21108": {"n":"Lazos de sangre","t":"Cuando se muestre esta carta: cura 2 de Daño a cada Villano. Dale a cada Villano una carta de Estado \"Duro\".\n[star] Aumento: cura 2 de Daño al Villano activo y dale una carta de Estado \"Duro\"."},
  "21109": {"n":"Lluvia de fuego","t":"Cuando se muestre esta carta: inflige 3 de Daño a la Torre de los Vengadores.\n[star] Aumento: si el Daño causado por este ataque derrota a un Aliado, inflige 3 de Daño a la Torre de los Vengadores."},
  "21110": {"n":"Atacan la ciudad","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: el jugador que haya derrotado este Plan roba 1 carta.","f":"\"Corvus ha ordenado a un regimiento de sus tropas que ataquen la ciudad de Nueva York para hacer salir a los Vengadores.\""},
  "21111": {"t":"Firmeza. (Este personaje no puede quedar aturdido ni confundido.)\nRespuesta obligada: después de que se acaben las cartas del mazo de Gema del infinito, dale a Thanos 1 carta de aumento boca abajo.","f":"\"Pronto conoceréis la derrota.\""},
  "21112": {"t":"Firmeza. Dureza.\nCuando se muestre esta carta: busca el Casco de Thanos en el mazo de Encuentros y en su pila de descartes y muéstralo. (Baraja el mazo.)\nRespuesta obligada: después de que se acaben las cartas del mazo de Gema del infinito, dale a Thanos 1 carta de aumento boca abajo."},
  "21113": {"t":"Firmeza. Dureza.\nCuando se muestre esta carta: busca la Armadura de Thanos en el mazo de Encuentros y en su pila de descartes y muéstrala. (Baraja el mazo.)\nRespuesta obligada: después de que se acaben las cartas del mazo de Gema del infinito, dale a Thanos 1 carta de aumento boca abajo."},
  "21114a": {"n":"Las Gemas del Infinito","t":"Contenido: Thanos I y Thanos II (Thanos II y Thanos III para jugar en modo Experto). Conjuntos de Encuentros de Thanos, Guantelete del Infinito y Normal. Dos conjuntos de Encuentros modulares (Hijos de Thanos y Orden Negra). Las mecánicas del Guantelete del Infinito se explican en el cuaderno de reglas."},
  "21114b": {"n":"Las Gemas del Infinito","t":"Cuando se muestre esta carta: pon en juego la primera carta de la parte superior del mazo de Gema del infinito. Busca en el mazo de Encuentros el Plan secundario \"Santuario\" y muéstralo. (Baraja el mazo de Encuentros.)","f":"\"Thanos ha reunido las seis Gemas del Infinito y las ha encajado en el Guantelete del Infinito. Ya no le resta más que aprender a dominar su poder para llevar a cabo su plan genocida.\""},
  "21115a": {"n":"Equilibrar la balanza","t":"Cuando se muestre esta carta: cada jugador devuelve su pila de descartes a su mazo y lo baraja. Cada jugador retira del juego la mitad superior de su mazo (redondeando hacia abajo)."},
  "21115b": {"n":"Equilibrar la balanza","t":"Si se completa esta etapa, los jugadores pierden la partida.","f":"\"Con sólo chasquear los dedos, Thanos ha exterminado a la mitad de todos los seres vivos del universo. Si lográis arrebatar el Guantelete al titán loco, quizá podáis utilizar su poder para revertir esta tragedia. Pero si fracasáis, no quedará nadie capaz de hacerle frente.\""},
  "21116": {"t":"Complicación 1[per_hero]. Victoria 1.\nThanos no puede sufrir Daño.\nCuando se derrote esta carta: cada jugador puede gastar hasta 3 recursos [physical] de su mano. Inflige 2 de Daño a Thanos por cada recurso [physical] que se haya gastado de este modo. Este Daño ignora la carta de Estado \"Duro\"."},
  "21117": {"n":"Armadura de Thanos","t":"Vincula esta carta a Thanos.\nInterrupción obligada: cuando Thanos vaya a sufrir cualquier cantidad de Daño, reduce esa cantidad en 1.\nRespuesta de Héroe: después de que un Héroe realice un ataque básico contra Thanos, gasta recursos [energy][physical] → descarta esta carta."},
  "21118": {"n":"Casco de Thanos","t":"Vincula esta carta a Thanos.\nThanos gana Represalia 1.\nRespuesta de Héroe: después de que un Héroe realice un ataque básico contra Thanos, gasta recursos [mental][physical] → descarta esta carta."},
  "21119": {"n":"Amo de las gemas","t":"Vincula esta carta a Thanos.\n[star] Interrupción obligada: cuando Thanos se active, pon en juego la primera carta de la parte superior del mazo de Gema del Infinito. Al final de esta activación, descarta Amo de las gemas.","f":"\"El universo me pertenece.\" —Thanos"},
  "21120": {"n":"Avatar de la muerte","t":"Cuando se muestre esta carta (Alter ego): Thanos ejecuta el Plan.\nCuando se muestre esta carta (Héroe): Thanos te ataca. Ese ataque gana Brutalidad y Penetrante.","f":"\"Huid. Escondeos. La muerte os encontrará de todos modos.\" —Thanos"},
  "21121": {"n":"Sindrome desviante","t":"Incitar 1.\nCuando se muestre esta carta: dale a Thanos una carta de Estado \"Duro\". Si no puedes hacerlo, coloca 2 de Amenaza sobre el Plan principal.\n[star] Aumento: dale a Thanos una carta de Estado \"Duro\"."},
  "21122": {"n":"\"Yo soy inevitable\"","t":"Cuando se muestre esta carta: dale a Thanos 1 carta de aumento boca abajo.\n[star] Aumento: descarta la primera carta de la parte superior del mazo de Gema del infinito. Aplica sus iconos de Aumento ([boost]) en esta activación como si fuese una carta de aumento."},
  "21123": {"n":"El titán loco","t":"Cuando se muestre esta carta: pon en juego la primera carta de la parte superior del mazo de Gema del infinito.\n[star] Aumento: si el Daño causado por este ataque derrota a un Aliado, pon en juego la primera carta de la parte superior del mazo de Gema del infinito.","f":"\"¡Soy Thanos! Y tú... no eres nada.\" —Thanos"},
  "21124": {"n":"El trono del titán","t":"Cuando se derrote esta carta: elige una Gema del infinito y descártala del juego.","f":"\"Desde su salón del trono en las profundidades de Santuario, Thanos urde un plan para destruir todo lo que existe.\""},
  "21125": {"t":"Represalia 1. Dureza.\n[star] Aumento: descarta un Aliado o Apoyo que controles.","f":"\"Soy el sirviente de mi amo, Thanos, un destructor de mundos. Soy uno de los cinco, Corvus Glaive.\""},
  "21126": {"n":"Medianoche Próxima","t":"[star] Los ataques de Medianoche Próxima ganan Penetrante.\n[star] Aumento: descarta un Aliado o Mejora que controles.","f":"\"Luchad, corred, someteos; nada de eso importará. Ahora este mundo pertenece a Thanos.\""},
  "21127": {"n":"Fauces Negras","t":"Infame. (Cuando este Esbirro se active, dale una carta de aumento.)\n[star] Aumento: dale a este enemigo 1 carta de aumento adicional.","f":"\"Deja de imaginar terribles finales para el mundo... porque uno muy real llegará muy pronto.\""},
  "21128": {"n":"Tributo","t":"Cuando se derrote esta carta: dale una carta de Encuentro boca abajo al jugador que haya derrotado este Plan.","f":"\"La Orden Negra rinde culto a la muerte y exige un tributo a los mundos que conquistan.\""},
  "21129": {"n":"Guantelete del Infinito","t":"Permanente. Inicio.\n[star] Respuesta obligada: después de que el Villano vinculado se active, resuelve la capacidad Especial de cada Gema del infinito que haya en juego. De no ser así, pon en juego la primera carta de la parte superior del mazo de Gema del infinito.","f":"\"El poder infinito está al alcance de mi mano.\" —Thanos"},
  "21130": {"n":"Gema de la Mente","t":"Especial: quedas confundido. Si ya estabas confundido, descarta 1 carta de tu mano al azar. Coloca esta carta en la pila de descartes del mazo de Gema del infinito.","f":"\"La Gema de la Mente confiere a su propietario facultades psiónicas casi ilimitadas.\""},
  "21131": {"n":"Gema del Poder","t":"Especial: quedas aturdido. Si ya estabas aturdido, sufres 3 de Daño. Coloca esta carta en la pila de descartes del mazo de Gema del infinito.","f":"\"La Gema del Poder incrementa la fuerza y resistencia de su propietario, además de potenciar todas las aptitudes sobrehumanas que tenga.\""},
  "21132": {"n":"Gema de la Realidad","t":"Especial: descarta un Aliado, Mejora o Apoyo que controles. Coloca esta carta en la pila de descartes del mazo de Gema del infinito.","f":"\"Toda la realidad se doblega al poder de la Gema de la Realidad y a la voluntad de quien la posee.\""},
  "21133": {"n":"Gema del Alma","t":"Especial: cura 3 de Daño al Villano y dale una carta de aumento boca abajo. Coloca esta carta en la pila de descartes del mazo de Gema del infinito.","f":"\"La Gema del Alma imbuye a su propietario de una inconmensurable fortaleza de espíritu y la capacidad de trascender su condición natural.\""},
  "21134": {"n":"Gema del Espacio","t":"Especial: descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Esbirro → pon en juego ese Esbirro enfrentado a ti. Coloca esta carta en la pila de descartes del mazo de Gema del infinito.","f":"\"La Gema del Espacio otorga a su propietario la capacidad de teletransportarse para recorrer grandes distancias en un instante.\""},
  "21135": {"n":"Gema del Tiempo","t":"Especial: descarta las 4 primeras cartas de tu mazo y coloca 1 de Amenaza sobre el Plan principal por cada tipo distinto de carta que se haya descartado de este modo. Coloca esta carta en la pila de descartes del mazo de Gema del infinito.","f":"\"El propietario de la Gema del Tiempo puede someter el tiempo a su voluntad, acelerándolo, ralentizándolo o incluso invirtiendo su curso.\""},
  "21136a": {"t":"[star] Hela recibe +1 PLA, +1 ATQ y +2[per_hero] de Vida por cada Plan secundario que haya en la zona de victoria.\nCuando Hela sea derrotada, si Odín no está vinculado al Plan principal, los jugadores ganan la partida."},
  "21136b": {"t":"Hela no puede ser derrotada.\nRespuesta obligada: después de que se derrote un Plan secundario, dale la vuelta a Hela para poner boca arriba su cara de Místico.","f":"\"¡No se puede matar a la diosa de la muerte!\""},
  "21137a": {"t":"[star] Hela recibe +1 PLA, +1 ATQ y +3[per_hero] de Vida por cada Plan secundario que haya en la zona de victoria.\nCuando Hela sea derrotada, si Odín no está vinculado al Plan principal, los jugadores ganan la partida."},
  "21137b": {"t":"Hela no puede ser derrotada.\nRespuesta obligada: después de que se derrote un Plan secundario, dale la vuelta a Hela para poner boca arriba su cara de Místico.","f":"\"¡No se puede matar a la diosa de la muerte!\""},
  "21138a": {"n":"El tormento de Odín","t":"Contenido: Mazo de Villano de Hela A Hela B para jugar en modo Experto). Conjuntos de Encuentros de Hela y Normal. Dos conjuntos de Encuentros modulares (Legiones de Hel y Gigantes de hielo).\nPreparación: vincula a Odín al Plan principal con la cara de Cautivo boca arriba. Muestra Gnipahellir y a Garm. Aparta Gjallerbru, Skurge, Salón de Nastrond y Nidhogg a un lado, fuera del juego. Baraja el mazo de Encuentros."},
  "21138b": {"n":"El tormento de Odín","t":"Interrupción obligada: cuando Hela vaya a ser derrotada, si Odín está vinculado a este Plan, en vez de eso descarta todos los Accesorios vinculados a Hela y dale la vuelta para poner boca arriba su cara de Herido\nSi se completa esta etapa, los jugadores pierden la partida.","f":"\"Para rescatar a Odín, debéis emprender un peligroso viaje a través de Hel.\""},
  "21139a": {"n":"Odín","t":"Mientras Odín no esté vinculado al Plan principal, gana: \"El jugador inicial toma el control de Odín. No se pueden vincular cartas a Odín, y tampoco cuenta de cara al límite de Aliados.\""},
  "21139b": {"n":"Odín","t":"El jugador inicial toma el control de Odín.\nNo se pueden vincular cartas de Encuentro a Odín, y tampoco cuenta de cara al límite de Aliados.\nInterrupción obligada: cuando Odín abandone el juego, retíralo del juego."},
  "21140": {"t":"Complicación 1[per_hero]. Victoria 2.\nCuando se derrote esta carta: el jugador inicial muestra Gjallerbru y a Skurge, y los pone en juego. Dales a los demás jugadores 1 carta de Encuentro boca abajo a cada uno."},
  "21141": {"n":"Salón de Nastrond","t":"Complicación 1[per_hero]. Victoria 4.\nCuando se derrote esta carta: el jugador inicial desvincula a Odín del Plan principal y toma el control de su carta. Dale 1 carta de Encuentro boca abajo a cada uno."},
  "21142": {"t":"Complicación 1[per_hero]. Victoria 3.\nCuando se derrote esta carta: el jugador inicial muestra el Saón de Nastrond y a Nidhogg, y los pone en juego. Dales a los demás jugadores 1 carta de Encuentro boca abajo a cada uno."},
  "21143": {"t":"Dureza. Victoria 2.\nGarm se enfrenta al jugador inicial.\nNo puede quitarse Amenaza de Gnipahellir.","f":"\"Este monstruoso sabueso infernal custodia la entrada al inframundo.\""},
  "21144": {"t":"Dureza. Victoria 3.\nSkurge se enfrenta al jugador inicial.\n[star] Los ataques de Skurge ganan Penetrante.\nNo puede quitarse Amenaza de Gjallerbru."},
  "21145": {"t":"Dureza. Victoria 4.\nNidhogg se enfrenta al jugador inicial.\n[star] Los ataques de Nidhogg ganan Brutalidad.\nNo puede quitarse Amenaza del Salón de Nastrond."},
  "21146": {"n":"Espada Nocturna","t":"Vincula esta carta a Hela.\n[star] Los ataques de Hela ganan Penetrante.\n[star] Aumento: vincula la Espada Nocturna a Hela.","f":"\"Muchos héroes han sucumbido víctimas de Hela y su espada maldita.\""},
  "21147": {"n":"Corona de Hela","t":"Vincula esta carta a Hela.\n[star] Respuesta obligada: después de que Hela ejecute el Plan, dale una carta de aumento boca abajo.\n[star] Aumento: vincula la Corona de Hela a Hela."},
  "21148": {"n":"Capa de Hela","t":"Vincula esta carta a Hela.\nHela gana Firmeza.\n[star] Aumento: vincula la Capa de Hela a Hela.","f":"\"¡Hela no es una guerrera ordinaria, y las mías no son armas ordinarias!\" —Hela"},
  "21149": {"n":"Los dominios de Hela","t":"Cuando se muestre esta carta: coloca 1 de Amenaza sobre el Plan principal. Coloca 1 de Amenaza adicional sobre el Plan principal por cada Plan secundario que haya en la zona de victoria.\n[star] Aumento: si el Daño causado por este ataque derrota a un Aliado, coloca 2 de Amenaza sobre el Plan principal."},
  "21150": {"n":"La Reina de Hel","t":"Cuando se muestre esta carta (Alter ego): Hela ejecuta el Plan. Coloca 1 de Amenaza sobre cada Plan secundario.\nCuando se muestre esta carta (Héroe): Hela te ataca. Coloca 1 de Amenaza sobre cada Plan secundario."},
  "21151": {"n":"Yermo helado de Niffleheim","t":"Cuando se muestre esta carta: sufres 1 de Daño indirecto. Sufres 1 de Daño indirecto adicional por cada Plan secundario que haya en la zona de victoria.\n[star] Aumento: esta carta gana tantos iconos de Aumento ([boost]) como el número de Planes secundarios que haya en la zona de victoria."},
  "21152": {"t":"Guardia.\nCuando se muestre esta carta: elige entre sufrir 1 de Daño o colocar 1 de Amenaza sobre el Plan principal.","f":"Los draugr son guerreros caídos condenados a servir a Hela por toda la eternidad."},
  "21153": {"n":"Guerrero caído","t":"El Aliado vinculado se trata como si fuera un Esbirro No muerto con el texto de reglas en blanco. La puntuación de PLA del Esbirro vinculado es igual a su puntuación impresa de INT, y no sufre Daño derivado.\nCuando se muestre esta carta: descarta cartas de la parte superior de tu mazo hasta que descartes un Aliado. Pon en juego ese Aliado enfrentado a ti con Guerrero caído vinculado a su carta."},
  "21154": {"n":"No es lugar para los vivos","t":"Cuando se muestre esta carta: cada jugador debe elegir entre descartar la Mejora o Apoyo con el coste más alto de entre todos los que controle, o bien sufrir tanto Daño como el número total de Mejoras y Apoyos que controle."},
  "21155": {"n":"Legiones de Hel","t":"Cuando se muestre esta carta: coloca 2 de Amenaza adicional sobre esta carta por cada Esbirro No muerto que haya en juego. Si no hay Esbirros No muerto en juego, esta carta gana Oleada.","f":"\"Con cada soldado que cae en combate, las huestes de Hel engrosan su número.\""},
  "21156": {"t":"Dureza.\n[star] Respuesta obligada: después de que Laufey ataque a un personaje y le inflija Daño, aturde a ese personaje.","f":"\"Rey de Jotunheim y padre de Loki, con el corazón tan gélido como sus dominios de hielo.\""},
  "21157": {"n":"Gigante de hielo","t":"Dureza. (Este personaje entra en juego con una carta de Estado \"Duro\".)\n[star] Aumento: si el Villano está atacando y este ataque inflige Daño a un personaje, aturde a ese personaje."},
  "21158": {"n":"Congelado","t":"Vincula esta carta a tu Superhéroe.\nEl Superhéroe vinculado no puede prepararse.\nAcción de Alter ego: gasta recursos [energy][physical] → descarta esta carta.","f":"\"El frío nunca me ha molestado.\" —Loki"},
  "21159": {"n":"Tormenta antinatural","t":"Ni Héroes ni Aliados pueden prepararse mediante efectos de cartas de Jugador.\nCuando se muestre esta carta: agota todos los Aliados que estén en juego.","f":"\"El letal frío de Jotunheim es capaz de congelar los héroes más resistentes.\""},
  "21160": {"t":"Victoria 1.\nLoki no puede surfir Daño mientras haya en juego un Plan secundario.\nCuando se derrote esta carta: descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Plan secundario. Muestra ese Plan secundario."},
  "21161": {"t":"Represalia 1. Victoria 1.\nCuando se derrote esta carta: descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Plan secundario. Muestra ese Plan secundario.","f":"\"¡Si es guerra lo que quieres, yo te la proporcionaré!\""},
  "21162": {"t":"Firmeza. Victoria 1.\nCuando se derrote esta carta: descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Plan secundario. Muestra ese Plan secundario.","f":"\"¡Ahora todos los reinos sabrán que Loki ha nacido para gobernar!\""},
  "21163": {"t":"Firmeza. Victoria 1. Cuando se derrote esta carta: descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Plan secundario. Muestra ese Plan secundario.","f":"El engaño es una simiente. Con el tiempo, acaba germinando en caos."},
  "21164": {"t":"Victoria 1.\n[star] Los ataques de Loki ganan Penetrante.\nCuando se derrote esta carta: descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Plan secundario. Muestra ese Plan secundario."},
  "21165a": {"n":"Alabado sea el rey Loki","t":"Contenido: Conjuntos de Encuentros de Loki, Guantelete del Infinito y Normal. Dos conjuntos de Encuentros modulares (Encantadora y Gigantes de hielo).\nPreparación: aparta todas las copias del Villano Loki a un lado, fuera del juego. Pon en juego el Plan secundario \"Guerra en Asgard\". Baraja el mazo de Encuentros. Muestra 1 de los Villanos Loki apartados (elegido al azar). Muestra la primera carta de la parte superior del mazo de Gema del infinito."},
  "21165b": {"n":"Alabado sea el rey Loki","t":"Interrupción obligada: cuando Loki sea derrotado, se avanza a uno de los Villanos Loki apartados (elegido al azar).\nSi el número de Lokis que hay en la zona de victoria es igual a la condición de victoria, los jugadores ganan la partida (ver cuaderno de reglas). Si se completa esta etapa, los jugadores pierden la partida."},
  "21166": {"n":"Cofre de los Antiguos Inviernos","t":"Complicación 1[per_hero],\nCuando se derrote esta carta: muestra la primera carta de la parte superior del mazo de Gema del infinito. Intercambia a Loki por uno de los Villanos Loki apartados (elegido al azar).","f":"\"Mientras saqueaba la armería de Odín, Loki ha encontrado el arma ancestral de los gigantes de hielo.\""},
  "21167": {"n":"Guerra en Asgard","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: muestra la primera carta de la parte superior del mazo de Gema del infinito. Intercambia a Loki por uno de los Villanos Loki apartados (elegido al azar).","f":"\"Los seguidores de Loki combaten a quienes aún se mantienen leales a Odín.\""},
  "21168": {"n":"Locura en Midgard","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: muestra la primera carta de la parte superior del mazo de Gema del infinito. Intercambia a Loki por uno de los Villanos Loki apartados (elegido al azar).","f":"\"El dios de las mentiras siembra el caos en la Tierra por mera diversión.\""},
  "21169": {"n":"Abrir el Bifrost","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: muestra la primera carta de la parte superior del mazo de Gema del infinito. Intercambia a Loki por uno de los Villanos Loki apartados (elegido al azar).","f":"\"Loki utiliza el Bifrost para desplegar sus fuerzas a lo largo y ancho de los Nueve Reinos.\""},
  "21170": {"n":"Bastón de Loki","t":"Vincula esta carta a Loki.\nRespuesta de Héroe: después de que realices un ataque básico contra Loki, gasta recursos [energy][physical] → descarta esta carta.\n[star] Aumento: vincula esta carta a Loki."},
  "21171": {"n":"Corona de Loki","t":"Vincula esta carta a Loki.\nRespuesta de Héroe: después de que realices un ataque básico contra Loki, gasta recursos [mental][physical] → descarta esta carta.\n[star] Aumento: vincula esta carta a Loki."},
  "21172": {"n":"Capa de Loki","t":"Vincula esta carta a Loki.\nRespuesta obligada: después de que Loki sea intercambiado por uno de los Villanos Loki apartados, dale una carta de Estado \"Duro\".\nRespuesta de Héroe: después de que realices un ataque básico contra Loki, gasta recursos [energy][mental] → descarta esta carta."},
  "21173": {"n":"Maestro de las ilusiones","t":"Vincula esta carta a Loki.\nInterrupción obligada: cuando Loki vaya a sufrir Daño a consecuencia de un ataque, descarta la primera carta de la parte superior del mazo de Encuentros. Si es una carta de Perfidia, se evita todo el Daño de este ataque y se descarta esta carta.","f":"\"¿Cuándo dejarás de caer en esa trampa?\" —Loki"},
  "21174": {"n":"Artimañas mágicas","t":"Cuando se muestre esta carta (Alter ego): quedas aturdido. Si ya estabas aturdido, coloca 2 de Amenaza sobre el Plan princiapl.\nCuando se muestre esta carta (Héroe): quedas aturdido. Si ya estabas aturdido, sufres 2 de Daño."},
  "21175": {"n":"Mentira infinita","t":"Cuando se muestre esta carta: baraja el mazo de Gema del infinito junto con su pila de descartes y muestra la primera carta de la parte superior.\n[star] Aumento: descarta la primera carta de la parte superior del mazo de Gema del infinito. Aplica sus iconos de Aumento ([boost]) en esta activación como si fuese una carta de aumento."},
  "21176": {"n":"El Embaucador","t":"Cuando se muestre esta carta: intercambia a Loki por uno de los Villanos Loki apartados (elegido al azar). Loki se activa contra ti.\n[star] Aumento: dale a Loki una carta de aumento adicional y una carta de Estado \"Duro\"."},
  "21177": {"n":"Encantadora","t":"Cuando se muestre esta carta: busca una copia de Seducido en el mazo de Encuentros, en su pila de descartes y entre las cartas apartadas, y vincúlala a tu Superhéroe. Baraja el mazo.)","f":"\"No puedes luchar contra aquello que deseas.\""},
  "21178": {"n":"Hechizado","t":"El Aliado vinculado se trata como si fuera un Esbirro Subyugado con el texto de reglas en blanco. La puntuación de PLA del Esbirro vinculado es igual a su puntuación impresa de INT, y no sufre Daño derivado.\nCuando se muestre esta carta: vincula esta carta al Aliado que tenga el coste más alto y que no tenga ya vinculada una carta de Hechizado. El Aliado vinculado se enfrenta al jugador que lo controla. Si no puedes hacerlo, esta carta gana Oleada."},
  "21179": {"n":"Seducido","t":"Vincula esta carta a tu Superhéroe.\nNo puedes realizar ataques básicos ni jugar Eventos de Ataque.\nAcción de Alter ego: gasta recursos [energy][mental] → descarta esta carta.","f":"\"Me amas, ¿no es cierto?\" —La Encantadora"},
  "21180a": {"n":"Asegurar la plataforma de aterrizaje","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: dale la vuelta a esta carta.","f":"\"Cosmo y el Cuerpo Sapiencial están haciendo lo posible por evitar que aterricen más tropas de la Orden Negra en la estación, ¡pero necesitan ayuda!\""},
  "21180b": {"t":"El jugador inicial toma el control de Cosmo.\nCosmo no se cuenta de cara al límite de Aliados.\nInterrupción obligada: cuando Cosmo abandone el juego, retíralo del juego."},
  "21181": {"n":"Violación de seguridad","t":"Complicación 2[per_hero]. Victoria 2.\nCuando se muestre esta carta: cada jugador coge al azar una carta de su mano y la coloca boca abajo sobre esta carta.\nCuando se derrote esta carta: devuelve a la mano de su propietario las cartas que estén boca abajo sobre esta carta."},
  "21182a": {"n":"Salvar el local de shawarmas","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: cada jugador añade a su mazo 1 copia de Shawarma y lo baraja. Dale la vuelta a esta carta.","f":"\"Los soldados de la Orden Negra causan estragos por las calles que rodean la Torre de los Vengadores, amenazando con destruir el restaurante favorito de los héroes.\""},
  "21182b": {"n":"Cisne Negro","t":"Dureza. Victoria 2.\nCisne Negro se enfrenta al jugador inicial.\nRespuesta obligada: después de que Cisne Negro se enfrente a ti, descarta 1 carta de tu mano.","f":"\"Todo muere.\""},
  "21183": {"t":"Máximo de 1 por mazo.","f":"\"¿Habéis probado el shawarma?\" -Tony Stark"},
  "21184a": {"n":"Piratear los sistemas de Santuario","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: cada jugador busca 1 carta en su mazo y en su pila de descartes, la añade a su mano y baraja su mazo. Dale la vuelta a esta carta.","f":"\"Para derrotar a Thanos, primero tenéis que desactivar las numerosas defensas de su nave.\""},
  "21184b": {"n":"Protocolos de defensa","t":"Complicación 2[per_hero]. Victoria 2.\nInterrupción obligada: cuando termine la fase de los Jugadores, coloca 1 contador de Bloqueo sobre esta carta. Si hay 2 contadores de Bloqueo sobre esta carta, cada jugador añade a su mano 1 copia de la Obligación Calambrazo. Retira esta carta del juego.","f":"\"¡Habéis activado sin querer los sistemas de seguridad de Santuario!\""},
  "21185": {"n":"Calambrazo","t":"No puedes descartar esta carta de tu mano por elección propia.\nMientras esta carta esté en tu mano, gana: \"Acción de Alter ego: gasta un recurso [mental] → retira esta carta del juego.\""},
  "21186a": {"n":"En busca de las piedras de las nornas","t":"No puede quitarse Amenaza de este Plan a menos que Hela tenga el rasgo Herido.\nCuando se derrote esta carta: cada jugador pone en juego una copia de la Mejora Piedra de las nornas, con la cara de Inicio boca arriba y controlada por él. Dale la vuelta a esta carta."},
  "21186b": {"n":"Recuperar la armadura de Odín","t":"Complicación 2[per_hero]. Victoria 1.\nNo puede quitarse Amenaza de este Plan a menos que el jugador inicial controle a Odín.\nCuando se derrote esta carta: cura todo el Daño a Odín y dale la vuelta a su carta para dejar boca arriba su cara de Rey.","f":"\"Habéis rescatado a Odín, pero Hela aún guarda su armadura en una cámara acorazada.\""},
  "21187a": {"n":"Piedra de las nornas","t":"Permanente. Inicio.\nTu Héroe recibe +1 INT, +1 ATQ y +1 DEF.\nAcción de Héroe: prepara tu Héroe. Dale la vuelta a esta carta."},
  "21187b": {"n":"Piedra de las nornas","t":"Permanente.\nTu Héroe recibe +1 INT, +1 ATQ y +1 DEF.\nAcción de Alter ego: agota la Piedra de las nornas para curar 1 de Daño a tu Superhéroe."},
  "21188": {"n":"Convocado de entre los muertos","t":"Peligro. Oleada.\nCuando se muestre esta carta: busca tu Esbirro Archienemigo en el mazo de Encuentros, en su pila de descartes y entre las cartas apartadas, y ponlo en juego enfrentado a ti. Baraja el mazo de Encuentros."},
  "21189a": {"n":"Abrir las mazmorras","t":"Cuando se derrote esta carta: cada jugador elige 1 Aliado Cautivo del conjunto de Campaña y lo pone en juego controlado por él. Dale la vuelta a esta carta.","f":"\"Sif y los Tres Guerreros han sido hechos prisioneros por el usurpador Loki. ¡Rescatadlos y contaréis con unos aliados muy valiosos!\""},
  "21189b": {"t":"Vincula esta carta a Loki.\nLoki recibe +4[per_hero] de Vida.\nInterrupción obligada: cuando Loki sea derrotado, retira esta carta del juego."},
  "21190": {"n":"Dama Sif","t":"Acción: gasta un recurso [physical] → prepara a la Dama Sif.","f":"\"¿Alguna doncella se ha enfrentado a un problema como éste?\""},
  "21191": {"t":"[star] Cuando Fandral use su atributo básico de INT, ignora todos los iconos de Crisis ([crisis]) que haya en juego.","f":"\"Aunque aprecio mucho mi vida, los actos de Loki no han de quedar sin respuesta.\""},
  "21192": {"t":"[star] Los ataques de Hogun ganan Penetrante.","f":"\"Esta vez Loki ha ido demasiado lejos. Ha de perecer por ello.\""},
  "21193": {"t":"Represalia 1. (Después de que se ataque a este personaje, se inflige 1 de Daño al personaje atacante.)\nDureza. (Este personaje entra en juego con una carta de Estado \"Duro\".)","f":"\"¡El poderoso Volstagg desfacerá este entuerto!\""},
  "22001a": {"n":"Nébula","t":"Protocolos de combate — Respuesta obligada: después de que empiece tu turno, resuelve la capacidad \"Especial\" de todas las Mejoras Técnica que controles, luego descarta todas las Mejoras Técnica que se hayan resuelto de este modo."},
  "22001b": {"n":"Nébula","t":"Mejoras cibernéticas — Respuesta: después de que juegues una Mejora Técnica, roba 2 cartas. (Límite de una vez por ronda.)","f":"\"Thanos me creó para un único propósito: matar. Al final lamentará haberlo hecho."},
  "22002": {"t":"Respuesta: después de que juegues a Gamora, elige una Mejora Técnica que controles y luego resuelve su capacidad \"Especial\".","f":"\"Thanos nos ha adiestrado para el mismo cometido.\""},
  "22003": {"n":"Nave de Nébula","t":"Recurso: agota la Nave de Nébula → genera un recurso [wild]","f":"\"Me gustaba más cuando era yo quien disparaba.\""},
  "22004": {"n":"Ambición sin escrúpulos","t":"Mientras Nébula tenga adoptada su identidad de Héroe, sus ataques ganan Brutalidad y Penetrante.\nEspecial (intervención): quita 3 de Amenaza de un Plan.","f":"\"¡Soy tan buena guerrera como tú!\" —Nébula"},
  "22005": {"n":"Maniobras evasivas","t":"Mientras tenga adoptada su identidad de Héroe, Nébula ignora la palabra clave Guardia, la palabra clave Patrulla y el icono de Crisis ([crisis]).\nEspecial: elige entre aturdir o confundir a un enemigo."},
  "22006": {"n":"Constancia férrea","t":"Mientras tenga adoptada su identidad de Héroe, Nébula recibe +1 INT, +1 ATQ y gana Firmeza.\nEspecial: dale a Nébula una carta de Estado \"Duro\"."},
  "22007": {"n":"Maestra en armas","t":"Mientras tenga adoptada su identidad de Héroe, Nébula gana Represalia 1.\nEspecial (ataque): inflige 4 de Daño a un enemigo."},
  "22008": {"n":"Guardia abierta","t":"Mientras Nébula tenga adoptada su identidad de Héroe, la cantidad de Daño que reciba de cada ataque se reduce en 1.\nEspecial: mira las 3 primeras cartas del mazo de Encuentros. Descartaa 1 de ellas y vuelve a colocar las demás en el orden que prefieras."},
  "22009": {"n":"Lista para el combate","t":"Acción de Alter ego: elige una opción:\n- Coge hasta 2 Mejoras Técnica de tu pila de descartes, devuélvelas a tu mazo y barájalo.\n- Descarta cartas de la parte superior de tu mazo hasta que descartes una Mejora Técnica. Pon enjuego ese Mejora, luego resuelve su capacidad \"Especial\"."},
  "22010": {"n":"Intenciones asesinas","t":"Acción de Héroe: elige hasta X Mejoras Técnica que controles. Resuelve todas sus capacidades \"Especial\" (en el orden que prefieras)","f":"\"Los Guardianes fueron sensatos al temerme, y aún más al contratarme.\" —Nébula"},
  "22011": {"t":"Respuesta: después de que juegues a Eros desde tu mano, confunde a un Esbirro por cada recurso [mental] que hayas utilizado para cubrir su coste.","f":"\"No será fácil, pero salvaremos este universo… guardaremos esta galaxia."},
  "22012": {"n":"Fantasma","t":"Interrupción de Héroe: cuando se ponga boca arriba una carta de aumento, agota a Fantasma e inflígele 1 de Daño → anula el efecto \"Aumento\" de esa carta.","f":"\"No desesperes: todos somos esclavos del destino.\""},
  "22013": {"n":"Veneno","t":"Mientras no haya Amenaza sobre el Plan principal, todo el Daño derivado que reciba Veneno se reduce en 1.","f":"\"Pues tendrá que ser por las malas.\""},
  "22014": {"n":"Se ha hecho justicia","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nRespuesta de Héroe: después de que intervengas y quites la última ficha de Amenaza de un Plan, descarta Se ha hecho justicia → prepara tu Héroe."},
  "22015": {"n":"De un modo u otro","t":"Máximo de 1 por ronda.\nAcción de Héroe: busca un Plan secundario en el mazo de Encuentros. Muestra ese Plan secundario → roba 3 cartas. (Baraja el mazo de Encuentros.)"},
  "22016": {"n":"Determinación","t":"Máximo de 1 por mazo.\nRespuesta de Héroe: después de que gastes esta carta, quita 1 de Amenaza del Plan principal."},
  "22017": {"n":"El poder de la justicia","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta de Justicia (amarilla)."},
  "22018": {"n":"Más maña que fuerza","t":"Respuesta de Héroe (ataque): después de que tu Héroe realice una intervención básica, inflige tanto Daño a un enemigo como la puntuación de INT de tu Héroe.","f":"Pese a su increíble fuerza, Spiderman suele vencer a sus enemigos siendo más listo que ellos."},
  "22019": {"n":"Intuición heroica","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nTu Héroe recibe +1 INT."},
  "22020": {"t":"Interrupción: cuando Cosmo ataque o intervenga, nombra un tipo de carta y luego descarta la primera carta de un mazo. Si esa carta es del tipo nombrado, Cosmo no sufre Daño derivado (el Daño que figura debajo de INT o ATQ) con este uso."},
  "22021": {"n":"Sapiencial","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Guardián.\nTu límite de Aliados se incrementa en 1.\nRespuesta: después de que un jugador juege un Aliado Guardián, agota Sapiencial → ese jugador roba 1 carta."},
  "22022": {"n":"Hijas de Thanos","t":"Equipo (Gamora y Nébula). Máximo de 1 por mazo.\nAcción de Héroe: roba 3 cartas.","f":"\"De niñas, Thanos nos enfrentó la una con la otra, pero ahora somos hermanas. Ahora por fin estamos unidads.\" —Gamora"},
  "22023": {"n":"Primeros auxilios","t":"Acción: cura 2 de Daño a cualquier personaje.","f":"\"¿Sigue llamándose 'primeros auxilios' si es ya el segundo día que me paso en el hospital?\" —Clint Barton"},
  "22024": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "22025": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "22026": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "22027": {"n":"Complejo de inferioridad","t":"Dale esta carta al jugador que lleva a Nébula.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n• Agota tu Alter ego → retira del juego Complejo de inferioridad.\n• Elige 2 Mejoras TÉCNICA que controles y descártalas. Si no se descarta ninguna Mejora de este modo, esta carta gana Oleada. Descarta esta Obligación."},
  "22028": {"t":"Interrupción obligada: cuando este Esbirro vaya a entrar en juego, descarta del juego la carta de Aliado de Gamora.\n[star] Respuesta obligada: después de que Gamora ataque y te inflija Daño, elige una Mejora que controles y descártala.\n(Esbirro Archienemigo de Nébula)."},
  "22029": {"n":"Cuestión de supervivencia","t":"Nébula recibe -1 INT, -1 ATQ y -1 DEF.\nGamora recibe +1 ATQ y sus ataques ganan Penetrante.","f":"\"Las dos hicimos lo necesario para sobrevivir. ¿Por qué no puedes superarlo de una vez?\" — Gamora"},
  "22030": {"n":"Arma leta","t":"Vincula esta carta a Gamora. Si no es posible, vincula esta carta al Villano.\nAcción de Héroe: descarta una Mejora que controles → descarta este Accesorio.","f":"\"¡Sólo hay una 'mujer más peligrosa de la galaxia', y ésa soy yo!\" — Gamora"},
  "22031": {"n":"Rivales de por vida","t":"Cuando se muestre esta carta: Gamora te ataca. Si no se produce ningún ataque de este modo, esta carta gana Oleada. (Si Gamora está en juego como Héroe o Aliado, resuelve su ATQ contra ti sin agotarse.)","f":"\"Esto ha sido un error.\" — Gamora"},
  "22032": {"n":"Lanza de energía","t":"Vincula esta carta a un Aliado Guardián. Máximo de 1 por Aliado.\nEl Aliado vinculado recibe +2 ATQ y sus ataques ganan Penetrante."},
  "22033": {"n":"Guardianes de la Galaxia","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 carta de Grupo por jugador.\nSi todos tus personajes tienen el rasgo Guardián, esta carta gana: \"Respuesta: después de que juegues una Mejora en un Aliado, roba 1 carta.\""},
  "22034": {"n":"Entrenamiento defensivo","t":"Máximo de 2 por mazo. Usos (2 contadores de Entrenamiento).\nAcción de Alter ego: agota esta carta y quítale 1 contador de Entrenamiento → elige un Evento de Protección (verde) que esté en tu pila de descartes, añadelo a tu mazo y barájalo."},
  "22035": {"n":"Guardián honorario","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Guardián.\nVincula esta carta a un personaje amigo. Máximo de 1 por personaje.\nEl personaje vinculado recibe +1 de Vida y gana el rasgo Guardián."},
  "23001a": {"n":"Máquina de Guerra","t":"Armas a punto — Respuesta: después de que cambies a esta identidad, coloca 5 contadores de Munición sobre Máquina de Guerra.","f":"\"¡Bum! ¿Buscabas esto?\" —James Rhodes"},
  "23001b": {"t":"Acción: elige una carta de Máquina de Guerra que esté en tu pila de descartes, añádela a tu mazo y barájalo.\nRespuesta obligada: después de que cambies a esta identidad, descarta todos los contadores de Munición de tu Superhéroe."},
  "23002": {"t":"Respuesta: después de que Iron Man entre en juego, busca en tu mazo y en tu pila de descartes una Mejora tecnología y añádela a tu mano. Baraja tu mazo.","f":"\"¿Qué le has hecho a mi armadura, Rhodey?\""},
  "23003": {"n":"Depósito de municiones","t":"Acción de Alter ego: agota el Depósito de municiones → coloca 2 contadores de Munición sobre esta carta.\nAcción de Héroe: agota el Depósito de municiones → traslada a Máquina de Guerra todos los contadores de Munición que haya sobre esta carta."},
  "23004": {"n":"Chasis mejorado","t":"Máquina de Guerra gana el rasgo aéreo.\nRespuesta de Héroe: después de que cambies a tu identidad de Héroe, agota el Chasis mejorado → dale a Máquina de Guerra una carta de Estado \"Duro\"."},
  "23005": {"n":"Guantelete artillado","t":"Recurso: agota el Guantelete artillado → genera un recurso [wild] para un Evento de Máquina de Guerra y coloca 1 contador de Munición sobre Máquina de Guerra.","f":"\"Vamos a ver qué hace esta preciosidad.\" —James Rhodes"},
  "23006": {"n":"Lanzamisiles","t":"Acción de Héroe (ataque): agota el Lanzamisiles y quítale 1 contador de Munición a Máquina de Guerra → inflige 2 de Daño a un enemigo. Este ataque gana A distancia."},
  "23007": {"n":"Ametralladora dorsal","t":"Acción de Héroe (ataque): agota la Ametralladora dorsal → inflige 1 de Daño a un enemigo. Puedes quitar 1 contador de Munición a Máquina de Guerra para preparar la Ametralladora dorsal.","f":"\"¡RATATATATATA!\""},
  "23008": {"n":"Rayos repulsores","t":"Acción de Héroe (ataque): quítale 1 contador de Munición a Máquina de Guerra → inflige 4 de Daño a un enemigo.","f":"\"Ah, ¿tú también quieres un poco?\" —James Rhodes"},
  "23009": {"n":"Ataque dirigido","t":"Acción de Héroe (intervención): quítale 1 contador de Munición a Máquina de Guerra → quita 3 de Amenaza de un Plan.","f":"\"¡Ésta es la parte en la que te rindes! —James Rhodes"},
  "23010": {"n":"Tierra quemada","t":"Acción de Héroe: quítale 3 contadores de Munición a Máquina de Guerra → inflige 3 de Daño a todos los enemigos que haya en juego.","f":"\"Yo digo que despeguemos y arrasemos toda la zona desde el aire. Es el único modo de asegurarse.\" —James Rhodes"},
  "23011": {"n":"Fuego automático","t":"Acción de Héroe (ataque): quítale 4 contadores de Munición a Máquina de Guerra y elige un enemigo → inflige 8 de Daño a ese enemigo. Este ataque gana Brutalidad.","f":"\"¡Eh, Tony! ¡A ver si tu Mark V puede hacer esto!\" —James Rhodes"},
  "23012": {"n":"Pantera Negra","t":"Puedes jugar el Evento vinculado a Pantera Negra como si estuviera en tu mano.\nRespuesta: después de que Pantera Negra entre en juego, elige un Evento de Liderazgo (azul) que esté en tu pila de descartes y vincúlalo a Pantera Negra boca abajo."},
  "23013": {"n":"Capitana Marvel","t":"Respuesta: después de que la Capitana Marvel entre en juego, descarta las 4 primeras cartas de tu mazo. Si descartas un recurso [energy] impreso, inflige 3 de Daño a un enemigo. Si descartas más de un recurso [energy] impreso, aturde también a ese enemigo."},
  "23014": {"n":"Halcón","t":"Respuesta: después de que el Halcón entre en juego, mira las 3 primeras cartas del mazo de Encuentros. Por cada carta de Perfidia que mires de este modo, quita 1 de Amenaza de un Plan."},
  "23015": {"n":"Goliat","t":"Acción: Goliat recibe +4 ATQ hasta el final de la fase. Al final de la fase, descarta a Goliat. (Máximo de una vez por fase.)","f":"\"A veces para ser un caballero hay que sostener la puerta, y el resto del edificio.\""},
  "23016": {"n":"Grupo de mando","t":"Usos (3 contadores de Mando).\nAcción: agota el Grupo de mando y quítale 1 contador de Mando → prepara un Aliado."},
  "23017": {"n":"Ataque furtivo","t":"Acción: elige un Aliado de tu mano que comparta un rasgo con tu Superhéroe → pon en juego ese Aliado. Si ese Aliado continúa en juego al final de la fase, descártalo.","f":"\"¡Sorpresa!\" —Starlord"},
  "23018": {"n":"Salvados del desastre","t":"Acción de Héroe: descarta un Aliado que controles → quita tanta Amenaza de un Plan como el coste impreso de ese Aliado.","f":"\"Hay días intensos, ¡y el de hoy ha sido la pera!\" —Spiderman"},
  "23019": {"n":"Hasta el último aliento","t":"Acción de Héroe: descarta un Aliado que controles → inflige tanto Daño a un enemigo como el coste impreso de ese Aliado.","f":"\"Spiderman puede llegar a ser muy irritante con tanto chiste, pero te diré una cosa: el chaval nunca se rinde.\" —Capitán América"},
  "23020": {"n":"Hacer la llamada","t":"Acción: paga el coste impreso de un Aliado que esté en la pila de descartes de cualquier jugador → pon en juego ese Aliado controlado por ti.","f":"\"¡Código rojo! ¡Todo el mundo a sus puestos!\" —María Hill"},
  "23021": {"n":"Innovación","t":"Máximo de 1 por mazo.\nRespuesta de Héroe: después de que gastes esta carta, cura 1 de Daño a un Aliado que controles."},
  "23022": {"n":"Pájaro Burlón","t":"Respuesta: después de que Pájaro Burlón entre en juego, aturde a un enemigo.","f":"\"¡¿Llamas a eso 'ciencia'?!\""},
  "23023": {"n":"Quintransporte","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo VENGADOR.\nRecurso: agota el Quintransporte → genera un recurso [wild].","f":"\"Lástima que sólo tengamos uno de esos.\" —Ojo de Halcón"},
  "23024": {"n":"Dos contra el mundo","t":"Equipo (Iron Man y Máquina de Guerra). Máximo de 1 por mazo.\nAcción de Héroe: busca en tu mazo una Mejora tecnología y ponla en juego. Baraja tu mazo. Prepara a Iron Man y a Máquina de Guerra."},
  "23025": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "23026": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "23027": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "23028": {"n":"Equipo averiado","t":"Dale esta carta al jugador que lleva a James Rhodes.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n• Agota a James Rhodes → retira del juego Equipo averiado.\n• Quítale a tu Superhéroe todos sus contadores de Munición. Si no se quitan más de 2 contadores de Munición de este modo, esta carta gana Oleada. Descarta esta Obligación."},
  "23029": {"n":"Láser Viviente","t":"Ataque veloz.\n[star] Los ataques del Láser Viviente ganan penetrante.\n(Esbirro Archienemigo de Máquina de Guerra.)","f":"\"Stark y tú; los dos recibiréis vuestro merecido!\""},
  "23030": {"n":"Espectáculo de luces mortal","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: inflige 1 de Daño a cada Superhéroe.","f":"El láser Viviente está atacando unas oficinas del gobierno. ¡Los empleados necesitan vuestra ayuda!"},
  "23031": {"n":"Impacto láser","t":"Cuando se muestre esta carta: descarta una Mejora que controles. Si no puedes hacerlo, esta carta gana Oleada.\n[star] Aumento: Si esto se resuelve durante un ataque no defendido, descarta una Mejora que controles."},
  "23032": {"n":"¡Como uno solo!","t":"Alianza.\nAcción de Héroe (ataque): agota un personaje vengador y un personaje guardián → inflige X de Daño a un enemigo, siendo X la puntuación combinada de ATQ de esos personajes. Este ataque gana Brutalidad."},
  "23033": {"n":"Entrenamiento de justiciero","t":"Máximo de 2 por mazo. Usos (2 contadores de Entrenamiento).\nAcción de Alter ego: agota esta carta y quítale 1 contador de Entrenamiento → elige un Evento de Justicia (amarillo) que esté en tu pila de descartes y barájalo."},
  "23034": {"n":"Codo con codo","t":"Alianza.\nInterrupción de Héroe: cuando un personaje amigo vaya a sufrir cualquier cantidad de Daño a consecuencia de un ataque, agota un personaje vengador y un personaje guardián → evita todo ese Daño. Inflige esa misma cantidad de Daño al enemigo atacante."},
  "23035": {"n":"Arma secundaria","t":"Vincula esta carta a un Aliado. Máximo de 1 por Aliado.\nEl Aliado vinculado recibe +1 ATQ y sus ataques ganan A distancia.","f":"\"¡Caray! ¡Tío, qué disfraz más chulo!\" —Niño"},
  "24001": {"n":"El Encapuchado","t":"Juego sucio - Especial: descarta la primera carta del mazo de Encuentros. Si esa carta no pertenece al conjunto de Encuentros de El Encapuchado, quédatela como carta de Encuentro boca abajo.","f":"\"Si no estáis conmigo, estáis solos\""},
  "24002": {"n":"El Encapuchado","t":"Cuando se muestre esta carta: elige al azar 1 conjunto de Encuentros modular que esté apartado, luego añádelo al mazo de Encuentros y barájalo.\nJuego sucio - Especial: descarta las 2 primeras cartas del mazo de Encuentros. Quédate como carta de Encuentro boca abajo la primera carta descartada de este modo que no pertenezca al conjunto de Encuentros de El Encapuchado."},
  "24003": {"n":"El Encapuchado","t":"Cuando se muestre esta carta: elige al azar 1 conjunto de Encuentros modular que esté apartado, luego añádelo al mazo de Encuentros y barájalo.\nJuego sucio - Especial: descarta las 2 primeras cartas del mazo de Encuentros. Quédate como carta de Encuentro boca abajo todas las cartas descartadas de este modo que no pertenezcan al conjunto de Encuentros de El Encapuchado."},
  "24004a": {"n":"Búsqueda de contactos","t":"Contenido: El Encapuchado (I) y El Encapuchado (II). (El Encapuchado (II) y El Encapuchado (III) para jugar en modo Experto.) Conjuntos de Encuentros de El Encapuchado y Normal.\nPreparación: elige 7 conjuntos de Encuentros modulares y apártalos a un lado (puedes elegirlos al azar). Elige al azar 1 de esos conjuntos, añádelo al mazo de Encuentros y barájalo."},
  "24004b": {"n":"Búsqueda de contactos","t":"Cuando se muestre esta carta: cada jugador debe resolver la capacidad \"Juego sucio\" de El Encapuchado siguiendo el orden de jugadores.","f":"El Encapuchado pretende formar un ejército, y para ello ha de convencer a varios villanos de que juntos serían más fuertas que separados."},
  "24005a": {"n":"Promesa de prosperidad","t":"Cuando se muestre esta carta: elige al azar 1 conjunto de Encuentros modular que esté apartado, luego añádelo al mazo de Encuentros y barájalo. Coloca 1 ficha de Aceleración sobre el Plan principal.","f":"Con esfuerzo, determinación y numerosas actividades ilegales, el Encapuchado ha logrado expandir su imperio y reunir una fuerza formidable que supone una amenaza para la seguridad de todos los ciudadanos de Nueva York."},
  "24005b": {"n":"Promesa de prosperidad","t":"Cuando se muestre esta carta: ca jugador debe resolver la capacidad \"Juego sucio\" de El Encapuchado siguiendo el orden de jugadores. Por cada jugador que no haya recibido al menos 1 carta de Encuentro boca abajo de este modo, coloca 2 de Amenaza sobre esta carta."},
  "24006a": {"n":"Estado criminal","t":"Cuando se muestre esta carta: elige al azar 1 conjunto de Encuentros modular que esté apartado, luego añádelo al mazo de Encuentros y barájalo. Coloca 1 ficha de Aceleración sobre el Plan principal. Cada jugador debe resolver la capacidad \"Juego sucio\" de El Encapuchado siguiendo el orden de jugadores.","f":"Con una legión de villanos de su parte, el Encapuchado ha fundado un imperio de depravación que incluso el más poderoso de los héroes haría bien en temer."},
  "24006b": {"n":"Estado criminal","t":"[star] Respuesta obligada: después de colocar Amenaza sobre esta carta durante el primer paso de la fase del Villano, cada jugador debe resolver la capacidad \"Juego sucio\" de El Encapuchado siguiendo el orden de jugadores.\nSi se completa esta etapa, los jugadores pierden la partida."},
  "24007": {"n":"Imponerse a la competencia","t":"Vincula esta carta a tu Superhéroe.\nRespuesta obligada: después de que El Encapuchado se active contra ti, resuelve su capacidad \"Juego sucio\".\nAcción de Alter ego: agota tu Superhéroe y coloca 2 de Amenaza sobre el Plan principal → descarta esta carta."},
  "24008": {"n":"Capa del Encapuchado","t":"Vincula esta carta a El Encapuchado.\nEl Encapuchado gana Represalia 1 y Tesón. (Un personaje con Tesón requiere 2 cartas de Estado del mismo tipo para quedar aturdido o confundido.)\nAcción de Héroe: gasta recursos [energy][mental][physical] → descarta esta carta."},
  "24009": {"n":"Pistola de El Encapuchado","t":"Vincula esta carta a El Encapuchado.\nAcción de Héroe: gasta recursos [mental][physical] → descarta esta carta.\n[star] Aumento: muesta esta carta."},
  "24010": {"n":"Madame Máscara","t":"Guardia.\nCuando se muestre esta carta: resuelve la capacidad \"Juego sucio\" de El Encapuchado.\nCuando se derrote esta carta: el jugador que la ha derrotado debe resolver la capacidad \"Juego sucio\" de El Encapuchado."},
  "24011": {"n":"Ambición desmedida","t":"Complicación 2[per_hero]. (Cuando se muestre esta carta, coloca 2[per_hero] de Amenaza sobre ella.)\nInterrupción obligada: cuando empiece la fase del Villano, cada jugador debe resolver la capacidad \"Juego sucio\" de El Encapuchado siguiendo el orden de jugadores."},
  "24012": {"n":"Reclutar sobre la marcha","t":"Cuando se muestre esta carta: elige al azar 1 conjunto de Encuentros modular que esté apartado, luego añádelo al mazo de Encuentros y barájalo. Resuelve la capacidad \"Juego sucio\" de El Encapuchado. Retira esta carta de la partida.\n[star] Aumento: después de que termine esta activación, resuelve la capacidad \"Juego sucio\" de El Encapuchado."},
  "24013": {"n":"Tomar la delantera","t":"Cuando se muestre esta carta (Alter ego): El Encapuchado ejecuta el Plan. Resuelve la capacidad \"Juego sucio\" de El Encapuchado.\nCuando se muestre esta carta (Héroe): El Encapuchado te ataca. Resuelve la capacidad \"Juego sucio\" de El Encapuchado."},
  "24014": {"n":"A lo bestia","t":"Interrupción obligada: cuando un personaje amigo que esté aturdido o confundido vaya a sufrir cualquier cantidad de Daño, dicha cantidad aumenta en 1.","f":"\"El único superhéroe bueno es el superhéroe muerto.\" —Grifo"},
  "24015": {"t":"Ataque veloz.\n[star] Respuesta obligada: después de que el Grifo ataque a un personaje y le inflija Daño, aturde a ese personaje.\nCuando se derrote esta carta: si hay en juego algún personaje amigo aturdido, devuelve el Grifo al mazo de Encuentros y barájalo."},
  "24016": {"n":"Mandril","t":"El Mandril gana Represalia X, siendo X el número de personajes confundidos (amigos o enemigos) que haya en juego.\nCuando se muestre esta carta: confunde a todos los personajes que controles."},
  "24017": {"n":"Doble amenaza","t":"Cuando se muestre esta carta: aturde a un personaje que controles. Confunde a un personaje que controles.\n[star] Aumento: resuelve la capacidad \"Cuando se muestre esta carta\" de esta carta."},
  "24018": {"n":"Hermanos Grimm","t":"[star]interrupción obligada: cuando los Hermanos Grimm se activen contra ti, descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Accesorio. Muestra esa carta.\n[star] Aumento: después de que termine esta activación, pon en juego a los Hermanos Grimm enfrentados al jugador inicial."},
  "24019": {"n":"Mirlos encapsulados","t":"Vincula esta carta a un Esbirro Místico. Si no es posible, vincula esta carta al Villano.\n[star]Respuesta obligada: después de que el enemigo vinculado se active contra ti, descarta esta carta → descarta 1 carta de tu mano al azar y coge 1 carta de Encuentro boca abajo."},
  "24020": {"n":"Huevo bomba corrosivo","t":"Vincula esta carta a un Esbirro Místico. Si no es posible, vincula esta carta al Villano.\n[star]Respuesta obligada: después de que el enemigo vinculado se active contra ti, descarta esta carta → sufre 3 de Daño indirecto y coge 1 carta de Encuentro boca abajo."},
  "24021": {"n":"Polvo de estrellas paralizante","t":"Vincula esta carta a un Esbirro Místico. Si no es posible, vincula esta carta al Villano.\n[star]Respuesta obligada: después de que el enemigo vinculado se active contra ti, descarta esta carta → aturde a tu Superhéroe y coge 1 carta de Encuentro boca abajo."},
  "24022": {"n":"Hilo irrompible","t":"Vincula esta carta a un Esbirro Místico. Si no es posible, vincula esta carta al Villano.\n[star]Respuesta obligada: después de que el enemigo vinculado se active contra ti, descarta esta carta → elige y descarta 1 Aliado, Apoyo o Mejora que controles y coge 1 carta de Encuentro boca abajo."},
  "24023": {"n":"Sed de sangre","t":"Cuando se muestre esta carta: inflige 1 de Daño al personaje amigo que tenga menos Vida restante. Si esto derrota a ese personaje, repite este efecto.\n[star] Aumento: resuelve la capacidad \"Cuando se muestre esta carta\"."},
  "24024": {"n":"Controlador","t":"[star] Interrupción obligada: cuando el ataque del Controlador vaya a infligir cualquier cantidad de Daño a un personaje, aumenta esa cantidad tantos puntos como el ATQ de ese personaje.","f":"\"¡Nadie evita llevar mis discos diabólicos!\""},
  "24025": {"t":"Cuando se muestre esta carta: agota todos los Aliados que controles. Coloca 1 de Amenaza sobre el Plan principal por cada Aliado que se haya agotado de este modo.\n[star] Aumento: elige un personaje que controles y agótalo."},
  "24026": {"n":"Fuego Cruzado","t":"Ataque veloz.\n[star] Interrupción obligada: cuando Fuego Cruzado ataca, ataca al personaje amigo que tenga menos Vida restante. Ese ataque gana A distancia y Brutalidad."},
  "24027": {"n":"Mr. Miedo","t":"Como coste adicional para que el jugador enfrentado prepare un Héroe o Aliado que controle, ese jugador debe gastar un recurso [mental].\n[star] Aumento: descarta cartas de la parte superior de tu mazo hasta que descartes un Aliado."},
  "24028": {"n":"Atrapado en el fuego cruzado","t":"Cuando se muestre esta carta: descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Esbirro de la Banda de fuego cruzado. Muestra ese Esbirro. Sufres tanto Daño indirecto como el número de Esbirro de la Banda de fuego cruzado que haya en juego."},
  "24029": {"n":"Crueles intenciones","t":"Peligro. Oleada.\nCuando se muestre esta carta: reparte a cada jugador 1 carta de Encuentro boca abajo. Dale al Villano 1 carta de aumento boca abajo.\n[star] Aumento: coge 1 carta de Encuentro boca abajo."},
  "24030": {"n":"Devastación","t":"Incitar 1. Peligro.\nCuando se muestre esta carta: descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Plan secundario. Muestra esa carta. Coloca 2 de Amenaza sobre cada Plan que haya en juego."},
  "24031": {"n":"Búsqueda y eliminación","t":"Incitar 1. Peligro.\nCuando se muestre esta carta: busca tu Esbirro Archienemigo en el mazo de Encuentros, en su pila de descartes y entre las cartas apartadas, y ponlo en juego enfrentado a ti. Baraja el mazo.)"},
  "24032": {"n":"A brazo partido","t":"Peligro. Oleada.\nCuando se muestre esta carta: agota tu carta de Superhéroe. Sufres 2 de Daño.\n[star] Aumento: inflige 1 de Daño a cada personaje que controles. Dale al Villano 1 carta de aumento adicional para esta activación."},
  "24033": {"n":"Autoexperimentación","t":"Cuando se muestre esta carta: busca a Mr. Hyde en el mazo de Encuentros y en su pila de descartes y muéstralo. (Baraja el mazo.)\nInterrupción obligada: cuando un enemigo Bruto vaya a sufrir cualquier cantidad de Daño, en vez de eso quita esa misma cantidad de Amenaza de este Plan."},
  "24034": {"t":"Cuando se muestre esta carta: si Mr. Hyde está en juego, descarta esta carta → Mr. Hyde te ataca con +2 ATQ. Ese ataque gana Brutalidad.\nCuando se derrote esta carta: busca a Mr. Hyde en el mazo de Encuentros y en su pila de descartes y ponlo en juego enfrentado al jugador que estuviera enfrentado a Calvin Zabo."},
  "24035": {"n":"Mr. Hyde","t":"Cuando se muestre esta carta: si Calvin Zabo está enfrentado a un jugador, descarta a Calvin Zabo → Mr. Hyde se enfrenta a ese jugador. Dale a Mr. Hyde una carta de Estado \"Duro\" e inflige 1 de Daño a todos los Héroes y Aliados que estén en juego.","f":"\"Me convertí en lo que siempre quise ser.\""},
  "24036": {"n":"Fórmula Hyde","t":"Cuando se muestre esta carta: si Calvin Zabo está en juego, ejecuta el Plan con +3 PLA y luego sufre 4 de Daño. Si Mr. Hyde está en juego, dale una carta de Estado \"Duro\" y te ataca (incluso aunque tengas adoptada la identidad de tu Alter ego). Si ninguno de los dos está en juego, esta carta gana Oleada."},
  "24037": {"n":"Lanzallamas","t":"Vincula esta carta al Esbirro que tenga más Vida restante. Si no es posible, busca un Esbirro en el mazo de Encuentros y en su pila de descartes, ponlo en juego enfrentado a ti y vincúlales esta carta. (Baraja el mazo.)\n[star] Los ataques del Esbirro vinculado infligen Daño indirecto."},
  "24038": {"n":"Generador de holoescudo","t":"Vincula esta carta al Esbirro que tenga más Vida restante. Si no es posible, busca un Esbirro en el mazo de Encuentros y en su pila de descartes, ponlo en juego enfrentado a ti y vincúlale esta carta. (Baraja el mazo.)\nEl Esbirro vinculado recibe +4 de Vida y gana Represalia 2."},
  "24039": {"n":"Mochila propulsora","t":"Vincula esta carta al Esbirro que tenga más Vida restante. Si no es posible, esta carta gana Oleada.\nInterrupción obligada: cuando el Esbirro vinculado vaya a sufrir cualquier cantidad de Daño a consecuencia de un ataque, descarta la primera carta de la parte superior del mazo de Encuentros. El Daño infligido por ese ataque se reduce en tantos puntos como el número de iconos de Aumento ([boost]) que se hayan descartado de este modo."},
  "24040": {"n":"Guanteletes tecnificados","t":"Vincula esta carta al Esbirro que tenga más Vida restante. Si no es posible, esta carta gana Oleada.\nEl Esbirro vinculado recibe +3 de Vida.\n[star] Los ataques del Esbirro vinculado ganan Brutalidad."},
  "24041": {"n":"Guardia acorazado","t":"Guardia. (Mientras este Esbirro esté enfrentado a ti, no podrás atacar al Villano.)\nDureza. (Este personaje entra en juego con una carta de Estado \"Duro\".)"},
  "24042": {"n":"El crimen compensa","t":"Cuando se muestre esta carta: busca un Esbirro Criminal en el mazo de Encuentro y ponlo en juego enfrentado a ti. (Baraja el mazo.) Si no se pone en juego ningún Esbirro de este modo, esta carta gana Oleada."},
  "24043": {"n":"Escarabajo","t":"[star] Respuesta obligada: después de que la Escarabajo ataque y te inflija Daño, descarta la Mejora de coste más bajo que controles.\n[star] Aumento: elige una Mejora que controle y decártala."},
  "24044": {"n":"Búmerang","t":"[star] Respuesta obligada: después de que Búmerang te ataque, inflige 1 de Daño a cada Aliado que controles.\n[star] Aumento: inflige 2 de Daño a un Aliado que controles."},
  "24045": {"n":"Conmocionador","t":"Respuesta obligada: después de que el Conmocionador sea atacado, aturde al personaje atacante.\n[star] Aumento: aturde al personaje que controles que tenga la puntuación más alta de ATQ."},
  "24046": {"n":"Demonio Veloz","t":"Interrupción obligada: cuando un personaje ataque a Demonio Veloz, éste ataca a ese personaje. (El ataque de Demonio Veloz se resuelve primero.)\n[star] Aumento: descarta el Apoyo con el coste más bajo que controles."},
  "24047": {"n":"Coneja Blanca","t":"[star] Interrupción obligada: cuando Coneja Blanca te ataque, descarta 1 carta de tu mano al azar.\n[star] Aumento: elije 1 carta de tu mano que sea específica de un Superhéroe y descártala."},
  "24048": {"n":"Ofensiva siniestra","t":"Cuando se muestre esta carta (Alter ego): cada enemigo Criminal que esté en juego ejecuta el Plan. Si ningún enemigo ejecuta el Plan de este modo, esta carta gana Oleada.\nCuando se muestre esta carta (Héroe): cada enemigo Criminal que esté en juego te ataca. Si ningún enemigo ataca de este modo, esta carta gana Oleada."},
  "24049a": {"n":"Adversario formidable","t":"Permanente. Inicio.\nEl Villano gana Tesón. (Un personaje con Tesón requiere 2 cartas de Estado del mismo tipo para quedar aturdido o confundido.)"},
  "24049b": {"n":"Adversario formidable","t":"Usa esta carta en modo Experto.\nPermanente. Inicio.\nTodos los enemigos ganan Tesón. (Un personaje con Tesón requiere 2 cartas de Estado del mismo tipo para quedar aturdido o confundido.)"},
  "24050": {"n":"Tratos turbios","t":"Cuando se muestre esta carta: el Villano ejecuta el Plan con +1 PLA.\n[star] Aumento: dale al Villano 1 carta de aumento adicional para esta activación."},
  "24051": {"n":"Ataque en tropel","t":"Cuando se muestre esta carta (Alter ego): descarta las 7 primeras cartas del mazo de Encuentros. Pon en juego enfrentado a ti al primer Esbirro descartado de este modo.\nCuando se muestre esta carta (Héroe): el Villano y todos los Esbirros que estén enfrentados a ti te atacan. Esta carta gana Oleada."},
  "24052": {"n":"Fuerza abrumadora","t":"Cuando se muestre esta carta: descarta la Mejora o Apoyo con el coste más alto que controles. Si no se descarta ninguna carta de este modo, esta carta gana Oleada.\n[star] Aumento: dale al Villano 1 carta de aumento adicional para esta activación."},
  "24053": {"n":"Una sombra del pasado","t":"Cuando se muestre esta carta: muestra tu Esbirro Archienemigo que está apartado y ponlo en juego enfrentado a ti. Muestra el Plan secundario de tu Archienemigo que está apartado y ponlo en juego. Mezcla el resto del conjunto de Encuentros apartado de tu Archienemigo con el mazo de Encuentros y barájalo. Si tu Esbirro Archienemigo no estra en juego de este modo, esta carta gana Oleada."},
  "24054": {"n":"Aniquilación total","t":"Oleada.\nCuando se muestre esta carta (Héroe): el Villano te ataca. Ese ataque gana Brutalidad.\n[star] Aumento: si el Villano está atacando, este ataque gana Brutalidad."},
  "24055": {"n":"Robo sobre ruedas","t":"Cuando se muestre esta carta: descarta la carta con el coste más alto de tu mano.","f":"De algún modo, los villanos han identificado un furgón camuflado que transporta artefactos de un valor incalculable."},
  "24056": {"n":"Desastre en el puerto","t":"Cuando se muestre esta carta: sufres 3 de Daño indirecto.","f":"Un buque portacontenedores ha encallado en el puerto de la bahía."},
  "24057": {"n":"Infierno en alta mar","t":"Cuando se muestre esta carta: descarta la carta con el coste más bajo que controles.","f":"Se ha declarado un terrible incendio en una plataforma petrolífera y muchos de los operarios han quedado atrapados entre las llamas."},
  "24058": {"n":"Persecución intensa","t":"Cuando se muestre esta carta: descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Esbirro, luego pon en juego ese Esbirro enfrentado a ti."},
  "24059": {"n":"Emergencias por toda la ciudad","t":"Cuando se muestre esta carta: resuelve las capacidades del tipo \"Cuando se muestre esta carta\" de todos los Planes secundarios que haya en juego. Si no se resuelve ninguna capacidad del tipo \"Cuando se muestre esta carta\" de este modo, coloca 2 de Amenaza sobre cada Plan.\n[star] Aumento: resuelve la capacidad \"Cuando se muestre esta carta\" de esta carta."},
  "24060": {"n":"Callejón trasero","t":"Oleada. Cuando se muestre esta carta: descarta todos los demás Entornos Ubicación que haya en juego.\nCada personaje que esté en juego recibe +1 ATQ."},
  "24061": {"n":"Guarida secreta","t":"Oleada. Cuando se muestre esta carta: descarta todos los demás Entornos Ubicación que haya en juego.\nCada enemigo que esté en juego gana 1 icono de Aceleración ([acceleration]).\nCada Héroe y Aliado que estén en juego reciben +1 INT."},
  "24062": {"n":"Túneles del alcantarillado","t":"Oleada. Cuando se muestre esta carta: descarta todos los demás Entornos Ubicación que haya en juego.\nCada personaje que esté en juego gana Represalia 1."},
  "24063": {"n":"Almacenes portuarios","t":"Oleada. Cuando se muestre esta carta: descarta todos los demás Entornos Ubicación que haya en juego.\nTodos los personajes que estén en juego ganan Tesón. Un personaje con Tesón requiere 2 cartas de Estado del mismo tipo para quedar aturdido o confundido.)"},
  "24064": {"n":"Expertos en demoliciones","t":"Complicación 2[per_hero]. (Cuando se muestre esta carta, coloca 2[per_hero] de Amenaza sobre ella.)\nEl Villano y todos los Esbirros Élite ganan Represalia 1.","f":"La Brigada de Demolición está desbocada y emplea sus músculos imbuidos de magia para sembrar el caos y la destrucción."},
  "24065": {"n":"Destructor","t":"Infame. (Cuando este Esbirro se active, dale una carta de aumento.)\n[star] Mientas Destructor esté atacando, recibe +2 ATQ si es un ataque no defendido.","f":"\"¡Eres carne muerta a punto para ser macerada!\""},
  "24066": {"t":"Infame. (Cuando este Esbirro se active, dale una carta de aumento.)\n[star] Los ataques de Bulldozer ganan Brutalidad.","f":"\"¡Nada se interpone en el camino de Bulldozer!\""},
  "24067": {"n":"Martinete","t":"Represalia 1.\nInfame. (Cuando este Esbirro se active, dale una carta de aumento.)","f":"\"Estos puños están hechos para demoler... y eso es lo que van a hacer.\""},
  "24068": {"n":"Bola de Trueno","t":"Infame. (Cuando este Esbirro se active, dale una carta de aumento.)\n[star] Respuesta obligada: después de que Bola de Trueno te ataque, inflige 1 de Daño a todos los personajes que controles.","f":"\"¡Dadles duro! ¡Es la hora e la demolición!\""},
  "24069": {"n":"Esfuerzo combinado","t":"Cuando se muestre esta carta: cada Esbirro Élite que esté en juego se activa contra el jugador al que esté enfrentado. Si no se activa ningún Esbirro de este modo, esta carta gana Oleada.\n[star] Aumento: por cada Esbirro Élite que haya en juego, esta carta recibe +1 icono de Aumento ([boost]) para esta activación."},
  "24070": {"n":"Músculos mágicos","t":"Cuando se muestre esta carta: dale una carta de Estado \"Duro\" a cada enemigo Bruto que haya en juego. Si no se da ninguna carta de Estado \"Duro\" de este modo, descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Esbirro Bruto y muestra ese Esbirro.","f":"\"Estate quieto, que me haces cosquillas.\""},
  "25001a": {"n":"Valquiria","t":"Presentir la muerte — Acción de Héroe: juega la Mejora apartada Halo de muerte como si estuviera en tu mano.","f":"\"Soy quien escoge entre los muertos.\""},
  "25001b": {"n":"Brunilda","t":"Preparación: aparta la Mejora Halo de muerte a un lado, fuera del juego.\n\"Hoy no.\" — Acción: desvincula el Halo de muerte y apártalo a un lado, fuera del juego."},
  "25002": {"n":"Halo de muerte","t":"Vincula esta carta a un enemigo.\nInterrupción obligada: cuando el enemigo vinculado sea derrotado, aparta esta carta a un lado, fuera del juego. Si Valquiria ha derrotado a ese enemigo, prepárala."},
  "25003": {"t":"Acción de Alter ego: agota a Annabelle Riggs → busca una carta de Valquiria entre las 5 primeras cartas de tu mazo y añádela a tu mano. Devuelve las demás cartas a tu mazo y barájalo.","f":"\"Tengo amigos en la Tierra que necesitan mi ayuda.\""},
  "25004": {"t":"Respuesta: después de que Valquiria ataque y derrote al enemigo que tenga vinculado el Halo de muerte, agota Valhalla → roba 1 carta y cura 1 de Daño a Valquiria."},
  "25005": {"n":"Lanza de Valquiria","t":"Restringida.\nValquiria recibe +1 DEF (+2 DEF cuando defienda contra el enemigo que tenga vinculado el Halo de muerte)."},
  "25006": {"n":"Colmillo de Dragón","t":"Restringida.\nValquiria recibe +1 ATQ (+2 ATQ cuando el ataque al enemigo que tenga vinculado el Halo de muerte).","f":"\"Colmillo de Dragón corta rápida y profundamente. Sería inteligente rendirse.\" —Valquiria"},
  "25007": {"t":"Valquiria recibe +4 de Vida y gana el rasgo aéreo.","f":"\"Una montura indómita. Si con su vida o su muerte pudiese salvarnos, lo haría.\" —Valquiria"},
  "25008": {"n":"Cabalgata de las valquirias","t":"Respuesta: después de que el enemigo que tenga vinculado el Halo de muerte sea derrotado, descarta la Cabalgata de las valquirias → quita 5 de Amenaza de un Plan.","f":"\"Las valquirias transportan los espíritus de los guerreros caídos al Valhalla, si son juzgados dignos.\""},
  "25009": {"n":"Visitar el Valhalla","t":"Acción de Alter ego: devuelve a tu mano una carta de Valquiria que esté en tu pila de descartes.","f":"\"Como guía de los caídos, Valquiria puede abrir un portal al Valhalla siempre que lo desea.\""},
  "25010": {"n":"Elegir entre los caídos","t":"Acción de Héroe: busca un Esbirro en el mazo de Encuentros y en su pila de descartes, y ponlo en juego enfrentado a ti → roba 2 cartas.","f":"\"Ha llegado tu hora. Muere con honor.\" —Valquiria"},
  "25011": {"n":"Doncella escudera","t":"Interrupción de Héroe: cuando el enemigo que tenga vinculado el Halo de muerte ataque, declara a Valquiria como defensora sin agotarla. Valquiria recibe +2 DEF para este ataque."},
  "25012": {"n":"¡Defiéndete!","t":"Acción de Héroe (ataque): inflige 7 de Daño a un enemigo. Si ese enemigo tiene vinculado el Halo de muerte, este ataque gana Brutalidad."},
  "25013": {"t":"Dureza.\nInterrupción: cuando Thor ataque a un Esbirro que esté enfrentado a un jugador, gasta un recurso [energy] → resuelve este ataque contra todos los Esbirros que estén enfrentados a ese jugador (en el orden que prefieras)."},
  "25014": {"t":"Respuesta: después de que Throg entre en juego, dale una carta de Estado \"Duro\" si estás enfrentado a un Esbirro.","f":"\"¡Croac!\""},
  "25015": {"t":"Respuesta obligada: después de que Angela entre en juego controlada por ti, busca un Esbirro entre las 10 primeras cartas del mazo de Encuentros y ponlo en juego enfrentado a ti. Baraja el mazo de Encuentros. Si no se pone en juego un Esbirro de este modo, descarta a Angela."},
  "25016": {"n":"Salón de los Héroes","t":"Respuesta: después de que derrotes a un Esbirro, coloca 1 contador de Gloria sobre esta carta.\nAcción de Alter ego: agota el Salón de los Héroes y quítale 3 contadores de Gloria → roba 3 cartas."},
  "25017": {"n":"Entrenamiento de combate","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nTu Héroe recibe +1 ATQ.","f":"\"¡Tony! ¡Lo ha vuelto a hacer!\" —Janet Van Dyne"},
  "25018": {"n":"Golpe veloz","t":"Acción de Héroe (ataque): inflige tanto Daño a un enemigo como tu ATQ.","f":"\"¡Y no te levantes!\" —Power Man"},
  "25019": {"n":"Resolver el problema a golpes","t":"Acción de Héroe (intervención): agota tu Héroe → quita tanta Amenaza de un Plan como la puntuación de ATQ de tu Héroe.","f":"\"¡Mjolnir hablará por mí!\" —Thor"},
  "25020": {"n":"La mejor defensa...","t":"Interrupción de Héroe (defensa): cuando tu Héroe defienda contra un ataque, usa su ATQ en vez de su DEF para este ataque.","f":"\"Ya sé que somos los Guardianes de la Galaxia, pero preferimos disparar a que nos disparen.\" —Mapache Cohete"},
  "25021": {"n":"Audacia","t":"Máximo de 1 por mazo.\nRespuesta de Héroe: después de que gastes esta carta, inflige 1 de Daño al Villano."},
  "25022": {"n":"El poder de la agresividad","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta de Agresividad (roja)."},
  "25023": {"n":"El Bifrost","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Asgard.\nAcción: agota El Bifrost → busca en tu mazo un Aliado Asgard y juégalo (pagando su coste). Baraja tu mazo."},
  "25024": {"n":"Resistencia divina","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Asgard.\nAcción: cura 2 de Daño a tu Superhéroe. Puedes descartar una carta de Estado de tu Superhéroe.","f":"\"Fanfarrón.\" —Jane Foster"},
  "25025": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "25026": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "25027": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "25028": {"n":"Problemas en Otromundo","t":"Dale esta carta al jugador que lleva a Brunilda.\nValquiria no puede atacar al enemigo que tenga vinculado el Halo de muerte.\nAcción de Alter ego: gasta recursos [energy][mental] → retira del juego Problemas en Otromundo."},
  "25029": {"n":"Encantadora","t":"Cuando se muestre esta carta: busca una copia de Seducido en el mazo de Encuentros, en su pila de descartes y entre las cartas apartadas, y vincúlala a tu Superhéroe. (Baraja el mazo.)","f":"\"No puedes luchar contra aquello que deseas.\""},
  "25030": {"n":"Encantamientos poderosos","t":"Complicación 1[per_hero].\nLos jugadores no pueden descartar Accesorios que estén vinculados a personajes amigos.","f":"Tras los encantos de Amora se ocultan una cruel ambición y el poder para subyugar a quienes se interponen en su camino."},
  "25031": {"n":"Hechizado","t":"El Aliado vinculado se trata como si fuera un Esbirro Subyugado con el texto de reglas en blanco. La puntuación de PLA del Esbirro vinculado es igual a su puntuación impresa de INT, y no sufre Daño derivado.\nCuando se muestre esta carta: vincula esta carta al Aliado que tenga el coste más alto y que no tenga ya vinculada una carta de Hechizado. El Aliado vinculado se enfrenta al jugador que lo controla. Si no puedes hacerlo, esta carta gana Oleada."},
  "25032": {"n":"Seducido","t":"Vincula esta carta a tu Superhéroe.\nNo puedes realizar ataques básicos ni jugar Eventos de Ataque.\nAcción de Alter ego: gasta recursos [energy][mental] → descarta esta carta.","f":"\"Me amas, ¿no es cierto?\" —La Encantadora"},
  "25033": {"n":"Solucionadores de problemas","t":"Alianza.\nAcción de Héroe (intervención): agota un personaje Vengador y un personaje Guardián → quita X de Amenaza de cada Plan, siendo X igual a la puntuación combinada de INT de esos personajes."},
  "25034": {"n":"Entrenamiento en liderazgo","t":"Máximo de 2 por mazo. Usos (2 contadores de Entrenamiento).\nAcción de Alter ego: agota esta carta y quítale 1 contador de Entrenamiento → elige un Evento de Liderazgo (azul) que esté en tu pila de descartes, añádelo a tu mazo y barájalo."},
  "25035": {"n":"Anticipación","t":"Máximo de 1 por jugador.\nInterrupción de Héroe: cuando te enfrentes a un Esbirro, descarta esta carta → prepara tu Héroe.","f":"\"¡Ya era hora de que aparecierais!\" —Ojo de Halcón"},
  "25036": {"n":"Alianza cósmica","t":"Alianza.\nAcción de Héroe: elige un personaje Vengador y un personaje Guardián → prepara todos esos personajes."},
  "26001a": {"n":"La Visión","t":"Manipulación de la densidad — Acción: cambia tu identidad de masa dándole la vuelta a tu Mejora de Identidad de masa. (Límite de una vez por ronda.)","f":"\"Es extraño que haya quien diga que soy menos que humano, cuando en realidad soy muy superior.\""},
  "26001b": {"n":"La Visión","t":"Mientras tu identidad de masa sea Denso, recibes +2 REC.\nMientras tu identidad de masa sea Intangible, recibes +1 al tamaño de tu mano.\nPreparación: pon en juego tu Mejora de Identidad de masa con la cara de Intangible boca arriba."},
  "26002": {"t":"Identidad de masa. Permanente.\nLa Visión no puede atacar ni defenderse.\nLa cantidad de Daño que sufre La Visión de cada ataque se reduce en 2."},
  "26003": {"t":"Mientras tu identidad de masa sea Intangible, Vivian recibe +2 INT.\nMientras tu identidad de masa sea Denso, Vivian recibe +2 ATQ.","f":"\"Te quiero, papá.\""},
  "26004": {"n":"616 de la calle Hickory Branch","t":"Acción de Alter ego: agota esta carta → busca un Aliado Androide en tu mazo y en tu pila de descartes, y añádelo a tu mano. (Baraja el mazo.)","f":"\"Me encuentro continuamente en una encrucijada de mente y corazón.\" —La Visión"},
  "26005": {"n":"Gema solar","t":"La Visión gana el rasgo Aéreo.\nRecurso: agota la Gema solar → genera un recurso [wild].","f":"\"La gema que la Visión tiene incrustada en la frente absorbe energía solar, que luego su cuerpo transforma en poder mediante un proceso similar a la fotosíntesis.\""},
  "26006": {"n":"Capa de la Visión","t":"Mientras tu identidad de masa sea Denso, ganas Represalia +1.\nMientras tu identidad de masa sea Intangible, ganas Firmeza.","f":"\"La capacidad de la Visión para controlar su propia densidad se extiende a su traje y su capa.\""},
  "26007": {"n":"Control de la densidad","t":"Respuesta de Héroe: después de que cambies de identidad de masa, descarta esta carta → coge un Evento de La Visión que esté en tu pila de descartes y añádelo a tu mano.","f":"\"No te vas a morir por utilizar la puerta alguna vez.\" —Ojo de Halcón"},
  "26008": {"n":"Rayo solar","t":"Acción de Héroe (ataque): si la identidad de masa de La Visión es Denso, inflige 7 de Daño a un enemigo.\nAcción de Héroe (intervención): si la identidad de masa de La Visión es Intangible, quita 5 de Amenaza de un Plan."},
  "26009": {"n":"Golpe superdenso","t":"Juega esta carta sólo si la identidad de masa de La Visión es Denso.\nAcción de Héroe (ataque): inflige 5 de Daño a un enemigo. Este ataque gana Penetrante.","f":"\"He calculado todas las probabilidades, y no existe ningún desenlace en el que ganes esta pelea.\" -La Visión"},
  "26010": {"n":"Pasar a través","t":"Juega esta carta sólo si la identidad de masa de La Visión es Intangible.\nAcción de Héroe (intervención): quita 3 de Amenaza de un Plan, ignorando la palabra clave Patrulla y el icono de Crisis ([crisis])."},
  "26011": {"n":"Disrupción de fase","t":"Juega esta carta sólo si la identidad de masa de La Visión es Intangible.\nAcción de Héroe: confunde a un enemigo. Elige un Accesorio vinculado a ese enemigo que contenga las palabras \"Acción de Héroe\" o \"Respuesta de Héroe\" y descarta dicho Accesorio."},
  "26012": {"n":"Aumento de masa","t":"Juega esta carta sólo si la identidad de masa de La Visión es Denso.\nInterrupción de Héroe (defensa): cuando La Visión defienda, evita todo el Daño infligido por ese ataque. Aturde al enemigo atacante después de resolver ese ataque."},
  "26013": {"n":"Yocasta","t":"Puedes jugar el Evento vinculado a Yocasta como si estuviera en tu mano.\nRespuesta: después de que Yocasta entre en juego, elige un Evento Defensa que esté en tu pila de descartes y vincúlalo a Yocasta boca abajo."},
  "26014": {"n":"Protectora","t":"Interrupción: cuando la Protectora vaya a sufrir cualquier cantidad de Daño, gasta un recurso [mental] → reduce en 1 esa cantidad. (Límite de una vez por ronda.)"},
  "26015": {"t":"La cantidad de Daño que sufre Victor Mancha de cada ataque se reduce en 1.","f":"\"¿Quieres matarme? Pues será mejor que te des prisa…\""},
  "26016": {"n":"Fluir como el agua","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nRespuesta: después de que juegues una carta con Defensa, inflige 1 de Daño al enemigo atacante."},
  "26017": {"n":"Indómito","t":"Respuesta: después de que tu Héroe defienda, descarta Indómito → prepara a tu Héroe.","f":"\"No tenemos elección. Lucharemos... y venceremos. No hay otra opción.\" —Capitán América"},
  "26018": {"n":"Desafío","t":"Interrupción de Héroe (defensa): cuando vaya a ponerse boca arriba una carta de aumento para un enemigo que te esté atacando, en vez de eso descártala."},
  "26019": {"n":"Esquiva lateral","t":"Interrupción de Héroe (defensa): cuando vayas a sufrir cualquier cantidad de Daño, evita 3 de ese Daño. Si has pagado el coste de esta carta usando un recurso [energy], inflige 1 de Daño a un enemigo.","f":"\"¡Has fallado!\" - Avispa"},
  "26020": {"n":"¡Poneos detrás de mí!","t":"Interrupción de Héroe: cuando se muestre una carta de Perfidia del mazo de Encuentros, anula su efecto de \"Cuando se muestre esta carta\". En vez de eso, el Villano te ataca a ti.","f":"\"¡Ejem! ¡A un lado, ciudadanos!\" —Ms. Marvel"},
  "26021": {"n":"Preservación","t":"Máximo de 1 por mazo.\nRespuesta de Héroe: después de que gastes esta carta, cura 1 de Daño a tu Héroe."},
  "26022": {"n":"Hombre Máquina","t":"Interrupción: cuando el Hombre Máquina ataque o intervenga, gasta un máximo de 3 recursos de cualquier tipo → el Hombre Máquina recibe +1 INT y +1 ATQ por cada recurso gastado de este modo.","f":"\"¡Aquí llega el metal pesado!\""},
  "26023": {"n":"Mansión de los Vengadores","t":"Máximo de 1 por jugador.\nAcción: agota la Mansión de los Vengadores → elige un jugador. Ese jugador roba 1 carta.","f":"\"¿Te has acordado de cerrar con llave?\" —Janet Van Dyne"},
  "26024": {"n":"Reinicio","t":"Acción: prepara un personaje Androide amigo y cúrale 1 de Daño.","f":"\"¿Has probado a apagarlo y volverlo a encender?\" —Ironheart"},
  "26025": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "26026": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "26027": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "26028": {"n":"Programación corrupta","t":"Dale esta carta al jugador que lleva a La Visión.\nEl texto de reglas de tu Mejora de Identidad de masa se trata como si estuviese en blanco (a excepción de las palabras clave).\nAcción de Alter ego: agota tu Superhéroe → retira del juego Programación corrupta."},
  "26029": {"n":"Ultrón","t":"Dureza.\n[star] Interrupción obligada: cuando Ultrón te ataque, si Drones de Ultrón está en juego, pon en juego la primera carta de tu mazo enfrentada a ti boca abajo como un Esbirro Dron."},
  "26030": {"n":"Ultrón desatado","t":"Cuando se muestre esta carta: busca Drones de Ultrón en el mazo de Encuentros, en su pila de descartes y entre las cartas apartadas, y ponla en juego. Baraja el mazo de Encuentros. Cada jugador pone en juego la primera carta de su mazo boca abajo y enfrentada a él como un Esbirro Dron."},
  "26031": {"n":"Drones de Ultrón","t":"Cada Esbirro Dron que esté enfrentado boca abajo a un jugador tiene un PLA básico de 1, un ATQ básico de 1 y una Vida básica de 1.\nRespuesta obligada: después de que un Esbirro Dron que esté boca abajo sea derrotado, coloca esa carta en la pila de descartes de su propietario."},
  "26032": {"n":"Androide implacable","t":"Cuando se muestre esta carta: si Drones de Ultrón está en juego, pon en juego las 2 primeras cartas de tu mazo boca abajo y enfrentadas a ti como Esbirros Dron. De no ser así, descarta 2 cartas de tu mano al azar.","f":"\"La innovación es el arma definitiva\" -Ultrón"},
  "26033": {"n":"Entrenamiento en asalto","t":"Máximo de 2 por mazo. Usos (2 contadores de Entrenamiento).\nAcción de Alter ego: agota esta carta y quítale 1 contador de Entrenamiento → elige un Evento de Agresividad (rojo) que esté en tu pila de descartes y añádelo a tu mazo y barájalo."},
  "26034": {"n":"Encuentro fortuito","t":"Vincula esta carta a un Plan secundario. Máximo de 1 por Plan.\nInterrupción: cuando se derrote el Plan secundario vinculado, busca un Aliado en tu mazo y en tu pila de descartes y añádelo a tu mano. Baraja tu mazo."},
  "26035": {"n":"Unir fuerzas","t":"Alianza.\nAcción de Héroe: los jugadores ponen en juego entre todos un total de 1 Aliado Vengador y 1 Aliado Guardián desde sus manos."},
  "26036": {"n":"Meditación","t":"Acción de Alter ego: agota tu Alter ego → juega una carta de tu mano, reduciendo en 3 su coste en recursos.","f":"\"La iluminación se alcanza mediante la práctica.\" —Dragón Lunar"},
  "27001a": {"t":"Reflejos vertiginosos — Respuesta: después de que resuelvas una capacidad de \"Interrupción\" o \"Respuesta\" de un Evento, prepara a Ghost-Spider. (Límite de una vez por fase.)","f":"\"Así que tengo que salva a un hombre adulto de un monstruo. No es la peor manera de pasar la noche del viernes para una adolescente.\""},
  "27001b": {"t":"Acción: elige entre coger el Billete al multiverso de tu pila de descartes y añadirlo a tu mazo (barajándolo después), o bien preparar a George Stacy. (Límite de una vez por ronda.)","f":"\"¡Toma solo de batería!\""},
  "27002": {"n":"Patada fantasma","t":"Respuesta de Héroe (ataque): después de que Ghost-Spider use un atributo básico, inflige 6 de Daño a un enemigo. (Máximo de 1 por cada uso de un atributo básico).","f":"\"Creí que por lo menos INTENTARÍAS resistirte un poco.\" —Ghost-Spider"},
  "27003": {"n":"Consejos paternos","t":"Acción de Alter ego:\n- Si George Stacy está en juego, coge 1 Evento de tu mano o pila de descartes y vincúlalo boca abajo a George Stacy.\n- Si George Stacy no está en juego, búscalo en tu mazo y pila de descartes y añádeló a tu mano. (Baraja el mazo.)"},
  "27004": {"n":"Voltereta espectral","t":"Respuesta de Héroe (intervención): después de que Ghost-Spider use un atributo básico, quita 5 de Amenaza de un Plan. (Máximo de 1 por cada uso de un atributo básico.)","f":"\"Veo la vida mucho más clara cuando todo está del revés.\" —Gwen Stacy"},
  "27005": {"n":"Piruetas y puñetazos","t":"Interrupción de Héroe: cuando se muestre una carta del mazo de Encuentros, inflige tanto Daño al Villano como 1 más el número de iconos de Aumento ([boost]) que tenga esa carta. Anula sus efectos de \"Cuando se muestre esta carta\"."},
  "27006": {"n":"Ataduras de red","t":"Requisito ([mental]).\nInterrupción de Héroe: cuando un enemigo vaya a activarse, anula esa activación. Si se anula la activación de un Esbirro de este modo, inflige 4 de Daño a ese Esbirro."},
  "27007": {"t":"Los Eventos vinculados a George Stacy pueden jugarse como si estuvieran en tu mano.\nAcción: agota a George Stacy → vincula boca abajo a esta carta 1 Evento de tu mano (hasta un máximo de 3).","f":"\"Hacedme cado, Ghost-Spider no es el problema.\""},
  "27008": {"n":"Billete al multiverso","t":"Acción: retira el Billete al multiverso de la partida → descarta tu mano, mezcla tu pila de descartes con tu mazo, roba cartas hasta alcanzar el tamaño máximo de tu mano y prepara todas las cartas de Ghost-Spider que controles."},
  "27009": {"n":"Pulsera lanzarredes","t":"Respuesta de Héroe: después de que resuelvas una capacidad de \"Interrupción\" o \"Respuesta\" de un Evento, agota la Pulsera lanzarredes → roba 1 carta. (Máximo de 1 por Evento.)","f":"\"Estos chismes me serán muy útiles.\" —Gwen Stacy"},
  "27010": {"n":"Seda","t":"Respuesta: después de que juegues a Seda desde tu mano, si controlas otra carta Guerrero Araña, busca una carta de Perfidia en el mazo de Encuentros y descártala. (Baraja el mazo.)","f":"\"Tal vez sí le esté cogiendo el tranquillo a esto del superheroísmo.\""},
  "27011": {"n":"Spiderman","t":"Respuesta: después de que juegues a Spiderman desde tu mano, aturde y confunde a un enemigo si controlas al menos 3 cartas Guerrero Araña.","f":"\"A Brooklyn no le gusta que la dominen. Somos así de salvajes.\""},
  "27012": {"t":"Interrupción: cuando Spider-UK defienda contra un ataque, inflige tanto Daño al enemigo atacante como el número de cartas Guerrero Araña que controles.","f":"\"La gente necesitará protección y ayuda, y somos los únicos que pueden dársela.\""},
  "27013": {"n":"Maniobra engañosa","t":"Acción de Héroe (intervención): el Villano te ataca. Quita 4 de Amenaza del Plan principal.","f":"\"No te habrás creído que me ibas a engañar con eso, ¿verdad?\" —Spiderman"},
  "27014": {"n":"Salto con giro","t":"Interrupción de Héroe (defensa): cuando vayas a sufrir cualquier cantidad de Daño, evita 2 de ese Daño. Si has pagado el coste de esta carta usando un recurso [energy], quita 2 de Amenaza del Plan principal.","f":"\"¡Por arriba! ¡Por abajo! Ay, qué lento eres.\" —Ghost-Spider"},
  "27015": {"n":"Devolver el favor","t":"Acción de Héroe (ataque): descarta cartas de la parte superior del mazo de Encuentros hasta que descartes una carta de Perfidia. Muesta esa carta de Perfidia → inflige 5 de Daño al Villano."},
  "27016": {"n":"Lo que no me mata","t":"Requisito ([physical]).\nAcción de Héroe: cura 2 de Daño a tu Héroe → prepara tu Héroe.","f":"\"¡En cuanto salga de aquí, te vas a enterar!\""},
  "27017": {"t":"Juega esta carta sólo si controlas una carta Guerrero Araña.\nInterrupción: cuando Spiderman abandone el juego, descarta las 3 primeras cartas del mazo de Encuentros. Inflige tanto Daño al Villano como el número de iconos de Aumento ([boost]) que se hayan descartado de este modo."},
  "27018": {"n":"Multiverso arácnido","t":"Máximo de 1 por mazo.\nAcción de Héroe: agota una carta Guerrero Araña que controles → busca un Aliado Guerrero Araña en tu pila de descartes y ponlo en juego, luego elige a un jugador. Ese jugador puede gastar 3 recursos de cualquier tipo para volver a usar esta capacidad."},
  "27019": {"n":"Amor juvenil","t":"Equipo (Gwen Stacy y Miles Morales). Máximo de 1 por mazo.\nAcción de Alter ego: cura 3 de Daño a Gwen Stacy y Miles Morales."},
  "27020": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "27021": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "27022": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "27023": {"n":"La Red de la Vida y el Destino","t":"Ignora el coste en recursos de esta carta si tu Superhéroe tiene el rasgo Guerrero Araña.\nRespuesta: después de que un Aliado Guerrero Araña abandone el juego, elige a un jugador → ese jugador roba 1 carta."},
  "27024": {"t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nAcción de Héroe: agota Plan B y descarta 1 carta de tu mano al azar → inflige 2 de Daño a un enemigo."},
  "27025": {"n":"Padre preocupado","t":"Dale esta carta al jugador que lleva a Gwen Stacy.\nBusca a George Stacy en tu mazo, mano, pila de descartes y zona de juego, y apártalo a un lado. Vincúlale esta Obligación.\nAcción de Alter ego: agota a Gwen Stacy y retira esta Obligación de la partida → añade a George Stacy a tu mano."},
  "27026": {"n":"Investigación sobre regeneración","t":"Interrupción obligada: cuando empiece la fase del Villano, cura 1 de Daño a cada enemigo.","f":"¡Mientras investigaba las propiedades regenerativas del ADN de lagarto, Peter Parker ha sufrido un terrible accidente que lo ha transformado a él y a todos los que entran en contacto con su suero en reptiles monstruosos!"},
  "27027": {"n":"Lagarto","t":"Interrupción obligada: cuando empiece la fase del Villano, cura 1 de Daño al Lagarto.\n(Esbirro Archienemigo de Ghost-Spider.)"},
  "27028": {"n":"Inyección experimental","t":"Vincula esta carta el Esbirro que tenga más vida restante. Si no es posible, esta carta gana Oleada.\nEl Esbirro vinculado gana el rasgo Criatura y recibe +4 de Vida.","f":"\"¡¡¡GRAAARRRRRRRG!!!\""},
  "27029": {"n":"A sangre fría","t":"Cuando se muestre esta carta: el Lagarto te ataca. No puedes jugar Eventos hasta después de que se resuelva ese ataque. Si no se produce ningún ataque de este modo, esta carta gana Oleada.","f":"\"Carne fresca…\" —El Lagarto"},
  "27030a": {"n":"Spiderman","t":"Rayo de veneno — Especial: inflige 2 de Daño a un enemigo. Aturde a ese enemigo.\nCamuflaje arácnido — Especial: dale a Spiderman una carta de estado \"Duro\". Confunde a un enemigo."},
  "27030b": {"t":"Respuesta: después de que cambies a esta identidad, coge 1 carta específica de Spiderman que esté en tu pila de descartes, añádela a tu mazo y barájalo.","f":"\"Cuando has saltado desde rascacielos y luchado contra supervillanos, te acabas aburriendo de todo lo demás.\""},
  "27031": {"n":"Acrobacia arácnida","t":"Acción de Héroe (ataque): inflige 2 de Daño a un enemigo. Si ese enemigo tiene una carta de Estado \"Aturdido\", inflígele 3 de Daño adicional. Si ese enmigo tiene una carta de Estado \"Confundido\", inflígele 3 de Daño adicional.","f":"\"No suelo renunciar al recochineo.\" —Spiderman"},
  "27032": {"n":"Doble vida","t":"Máximo de 1 por ronda.\nAcción: cambia de identidad. Si has pagado el coste de esta carta usando un recurso [physical], prepara tu Superhéroe.","f":"\"Yo no pedí este poder, esta… responsabilidad. Pero no pienso desperdiciarlo.\" —Miles Morales"},
  "27033": {"n":"Llegar columpiándose","t":"Acción de Héroe (intervención): quita 4 de Amenaza de un Plan. Si has pagado el coste de esta carta usando un recurso [mental], resuelve la capacidad \"Camuflaje arácnido\" de Spiderman.","f":"\"Veo que no te alegras de verme… ¡o de no verme!\" —Spiderman"},
  "27034": {"n":"Descarga de telaraña","t":"Acción de Héroe (ataque): inflige 4 de Daño a un enemigo. Si has pagado el coste de esta carta usando un recurso [energy], resuelve la capacidad \"Rayo de veneno\" de Spiderman.","f":"\"Si eso no basta para contenerte, sé de otra cosas que si lo hará.\" —Spiderman"},
  "27035": {"t":"Acción: agota a Ganke Lee → roba 1 carta. Si tienes adoptada tu identidad de Héroe, elige 1 carta de tu mano y descártala.","f":"\"Soy el tío que le ayuda desde casa.\""},
  "27036": {"t":"Acción de Alter ego: agota a Jefferson Davis → quita 1 de Amenaza del Plan que tenga menos Amenaza.","f":"\"No me enorgullezco de mi pasado, pero tampoco me arrepiento de lo que hice. Así he llegado hasta donde estoy hoy.\""},
  "27037": {"n":"Poder interior","t":"Respuesta de Héroe: después de que tu Héroe use un atributo básico, descarta Poder interior → resuelve la capacidad \"Rayo de veneno\" de Spiderman."},
  "27038": {"n":"Mecanismo de defensa","t":"Respuesta de Héroe: después de que tu Héroe use un atributo básico, descarta Mecanismo de defensa → resuelve la capacidad \"Camuflaje arácnido\" de Spiderman."},
  "27039": {"n":"Lanzarredes","t":"Usos (3 contadores de Telaraña).\nRecurso de Héroe: agota los Lanzarredes y quítales 1 contador de Telaraña → genera un recurso [wild]."},
  "27040": {"t":"Respuesta: después de que Monica Chang entre en juego, busca una copia de la carta de Apoyo Equipo de vigilancia en tu mazo, tu mano y tu pila de descartes, y ponla en juego. Coloca 1 contado de Escucha sobre cada Equipo de vigilancia que controles."},
  "27041": {"n":"SpiderWoman","t":"El coste para jugar a Spiderwoman se reduce en 1 por cada enemigo confundido que haya en juego.","f":"\"¿Sois la primera opción? ¿De verdad? ¿Hasta dónde llegaron buscando en las páginas amarillas hasta conformarse con vosotros?\""},
  "27042": {"n":"Intervención de S.H.I.E.L.D.","t":"Acción: agota hasta 3 cartas S.H.I.E.L.D. que controles y elige un Plan → quita 2 de Amenaza de ese Plan por cada carta que hayas agotado de este modo.","f":"\"¡A partir de este momento, esta situación entra dentro de la jurisdicción del Servicio Homologado de Inteligencia, Espionaje, Logística y Defensa!\""},
  "27043": {"n":"Logística internacional","t":"Acción: agota 1 carta S.H.I.E.L.D. que controles → mira las 4 primeras cartas de un mazo de Jugador o del mazo de Encuentros. Descarta cualquier cantidad de esas cartas y coloca el resto en la parte superior o inferior de ese mazo en el orden que prefieras."},
  "27044": {"n":"Agente sobre el terreno","t":"Usos (3 contadores de Refuerzos).\nInterrupción de Héroe: cuando un Aliado S.H.I.E.L.D. vaya a sufrir cualquier cantidad de Daño derivado, agota al Agente sobre el terreno y quítale 1 contador de Refuerzos → evita 1 de ese Daño."},
  "27045": {"n":"Equipo de vigilancia","t":"Usos (3 contadores de Escucha). (Entra en juego con 3 contadores. Cuando se acaben, descarta esta carta)\nAcción: agota el Equipo de vigilancia y quítale 1 contador de Escucha → quita 1 de Amenaza de un Plan."},
  "27046": {"n":"Agente 13","t":"[star] Respuesta: después de que la Agente 13 ataque o intervenga, elige un Apoyo S.H.I.E.L.D. → prepara ese Apoyo.","f":"\"Llevo en todo mi cuerpo las cicatrices del pasado. Pero soy más que eso. Ahora soy la mejor. Más fuerte. Más sabia.\""},
  "27047": {"t":"Interrupción: cuando uses uno de los atributos básicos de Dum Dum Dugan, agota hasta 3 cartas S.H.I.E.L.D. que controles. Por cada carta que agotes de este modo, Dum Dum Dugan suma +1 a ese atributo para este uso."},
  "27048": {"t":"Juega esta carta sólo si controlas una carta Guerrero Araña.\nInterrupción: cuando Ghost-Spider abandone el juego, busca en tu mazo un Evento específico de un Superhéroe y añádelo a tu mano. (Baraja el mazo.)"},
  "27049": {"n":"Spiderman","t":"Requisito ([energy] [mental] [physical]).\nRespuesta: después de que Spiderman ataque o intervenga, elige otro personaje Guerrero Araña → prepara ese personaje.","f":"\"¿Te das cuenta, Miles? Así es como se hace.\""},
  "27050": {"n":"Amor juvenil","t":"Equipo (Gwen Stacy y Miles Morales). Máximo de 1 por mazo.\nAcción de Alter ego: cura 3 de Daño a Gwen Stacy y Miles Morales."},
  "27051": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "27052": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "27053": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "27054": {"n":"Enlace con el Gobierno","t":"Acción de Héroe: agota el Enlace con el Gobierno → juega una carta S.H.I.E.L.D. desde tu mano, reduciendo en 1 su coste en recursos.","f":"\"Mi gente se pondrá en contacto con su gente.\""},
  "27055": {"n":"Destructor aéreo","t":"Respuesta: después de que juegues una carta S.H.I.E.L.D., agota el Destructor aéreo → inflige 2 de Daño a un enemigo.","f":"\"No tenemos por costumbre desplegar destructores aéreos. Pero cuando lo hacemos, ten por seguro que la situación se ha puesto seria.\" —Nick Furia"},
  "27056": {"n":"Secretos guardados","t":"Dale esta carta al jugador que lleva a Miles Morales.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\nAgota a Miles Morales → retira de la partida Secretos guardados.\nDescarta a Ganke Lee y Jefferson Davis del juego. Si no se descarta ninguno de los dos de este modo, esta carta gana Oleada. Descarta esta Obligación."},
  "27057": {"n":"El rastro de la presa","t":"Cuando se muestre esta carta: si tienes adoptada la identidad de tu Alter ego, coloca 1 ficha de Aceleración sobre esta carta.","f":"El Merodeador está de cacería y no se detendrá hasta haber acorralado a su presa."},
  "27058": {"n":"Merodeador","t":"Firmeza.\nCuando se muestre esta carta: si tienes adoptada la identidad de tu Alter ego, dale al Merodeador una carta de Estado \"Duro\".\n(Esbirro Archienemigo de Spiderman.)","f":"\"Voy a darte un consejo: procura que no te encuentre\""},
  "27059": {"n":"Garras afiladas","t":"Vincula esta carta al Esbirro que tenga el valor impreso más alto de Vida. Si no es posible, esta carta gana Oleada.\n[star] Los ataques del Esbirro vinculado ganan Penetrante.","f":"Garras diseñadas para triturar acero."},
  "27060": {"n":"Hacer picadillo","t":"Cuando se muestre esta carta: el Merodeador ataca al jugador que tenga menos Vida restante (incluso aunque tenga adoptada la identidad de su Alter ego). Si el ataque derrota a un personaje o no se produce ningún ataque de este modo, esta carta gana Oleada."},
  "27061": {"n":"Hombre de Arena","t":"Chorro de arena — [star] Interrupción obligada: cuando el Hombre de Arena te ataque, su ataque inflige Daño indirecto. Si tu Superhéroe sufre Daño a consecuencia de ese ataque, resuelve la capacidad \"Acumulación de arena\" de Calles de la ciudad.","f":"\"¡Sigo siendo más poderoso que todos vosotros, capullos!\""},
  "27062": {"n":"Hombre de Arena","t":"Cuando se muestre esta carta: resuelve la capacidad \"Acumulación de arena\" de Calles de la ciudad.\nChorro de arena — [star] Interrupción obligada: cuando el Hombre de Arena te ataque, su ataque inflige Daño indirecto. Si tu Superhéroe sufre Daño a consecuencia de ese ataque, resuelve la capacidad \"Acumulación de arena\" de Calles de la ciudad."},
  "27063": {"n":"Hombre de Arena","t":"Cuando se muestre esta carta: coloca 1 contador de Arena sobre Calles de la ciudad. Resuelve su capacidad \"Acumulación de arena\".\nOla de arena — [star] Interrupción obligada: cuando el Hombre de Arena te ataque, su ataque gana Brutalidad. Si tu Superhéroe sufre Daño a consecuencia de ese ataque, resuelve la capacidad \"Acumulación de arena\" de Calles de la ciudad."},
  "27064a": {"n":"Peatones indefensos","t":"Contenido: Hombre de Arena (I) y Hombre de Arena (II). (Hombre de Arena (II) y Hombre de Arena (III) para jugar en modo Experto.) Conjuntos de Encuentros del Hombre de Arena, Caos en la ciudad y Normal. Un conjunto de Encuentros modular Con los pies en la tierra.\nPreparación: busca la carta de Entorno Calles de la ciudad en el mazo de Encuentros y ponla en juego. Colócale encima 4 contadores de Arena."},
  "27064b": {"n":"Peatones indefensos","t":"Respuesta obligada: después de que se coloque una ficha de Aceleración sobre este Plan, inflige 3 de Daño indirecto al jugador inicial.\nSi se completa esta etapa, los jugadores pierden la partida.","f":"\"¡El Hombre de Arena inunda las calles de la ciudad con un torrente de arena poniendo en grave peligro a los inocentes transeúntes!\""},
  "27065": {"n":"Calles de la ciudad","t":"Acumulación de arena — Especial: coloca 1 contador de Arena sobre esta carta. Descarta tantas cartas de la parte superior del mazo de Encuentros como el número de contadores de Arena que haya sobre esta carta.\nAcción de Héroe: agota un personaje que controles → quita tantos contadores de Arena de esta carta como la puntuación de ATQ de ese personaje. (Límite de una vez por ronda y jugador.)"},
  "27066": {"n":"Forma arenosa","t":"Vincula esta carta al Hombre de Arena.\nInterrupción obligada: cuando vayass a infligir cualquier cantidad de Daño al Hombre de Arena, en vez de eso descarta Forma arenosa → resuelve la capacidad \"Acumulación de arena\" de Calles de la ciudad.\n[star] Aumento: Muestra esta carta."},
  "27067": {"n":"Duplicado de arena","t":"X es igual al número de contadores de Arena que haya sobre Calles de la ciudad.\nCuando se derrote esta carta: resuelve la capacidad \"Acumulación de arena\" de Calles de la ciudad.","f":"\"Si queréis pillarme, vais a tener que pasar por encima de... ¡MÍ!\" —Hombre de Arena"},
  "27068": {"n":"Trampa de tierra","t":"Cuando se derrote esta carta: resuelve la capacidad \"Acumulación de arena\" de Calles de la ciudad. Vuelve a resolverla.","f":"\"Una tromba de color marrón inunda las calles a vuestro alrededor. No importa hacia dónde avancéis, el Hombre de Arena siempre está ahí, esperando."},
  "27069": {"n":"Marea arenosa","t":"Cuando se muestre esta carta: coloca X de Amenaza adicional sobre esta carta, siendo X igual al número de contadores de Arena que haya sobre Calles de la ciudad."},
  "27070": {"n":"Avalancha de arena","t":"Cuando se muestre esta carta: coloca 2 contadores de Arena sobre Calles de la ciudad, luego resuelve su capacidad \"Acumulación de arena\". Si se descarta al menos 1 carta del Hombre de Arena de este modo, quedas aturdido.\n[star] Aumento: Resuelve la capacidad \"Cuando se muestre esta carta\" de esta carta."},
  "27071": {"n":"Tormenta de arena","t":"Cuando se muestre esta carta: inflige X de Daño indirecto a los jugadores (repártelo entre ellos como prefieras), siendo X igual al número de contadores de Arena que haya sobre Calles de la ciudad. Si no hay contadores sobre Calles de la ciudad, coloca 3 contadores de Arena sobre esa carta, devuelve esta carta al mazo de Encuentros y barájalo."},
  "27072": {"n":"Ariete de arena","t":"Cuando se muestre esta carta (Alter ego): resuelve la capacidad \"Acumulación de arena\" de Calles de la ciudad. Esta carta gana Oleada.\nCuando se muestre esta carta (Héroe): el Hombre de Arena te ataca con +1 ATQ.","f":"\"¡Os enterraré!\""},
  "27073": {"n":"Veneno","t":"Dureza. (Este personaje entra en juego con una carta de Estado \"Duro\".)\nVenganza — Respuesta obligada: después de que ataques e inflijas Daño a Veneno con una carta que controles, coloca 1 carta de aumento boca abajo sobre tu Superhéroe."},
  "27074": {"n":"Veneno","t":"Dureza. Tesón.\nCuando se muestre esta carta: busca el Plan secundario Con uñas y dientes en el mazo y la pila de descartes de Encuentros y ponlo en juego. (Baraja el mazo.)\nVenganza — Respuesta obligada: después de que ataques e inflijas Daño a Veneno con una carta que controles, coloca 1 carta de aumento boca abajo sobre tu Superhéroe."},
  "27075": {"n":"Veneno","t":"Represalia 1. Tesón. Dureza.\nCuando se muestre esta carta: coloca 2 cartas de aumento boca abajo sobre cada Superhéroe.\nRetribución — Respuesta obligada: después de que ataques e inflijas Daño a Veneno con una carta que controles, coloca 1 carta de aumento boca abajo sobre tu Superhéroe (2 cartas de aumento boca abajo si éste ha sido el primer ataque del turno)."},
  "27076a": {"n":"\"¡Dejadnos en paz!\"","t":"Contenido: Veneno (I) y Veneno (II). (Veneno (II) y Veneno (III) para jugar en modo Experto.) Conjuntos de Encuentros de Veneno, Fuerza simbiótica y Normal. Un conjunto de Encuentros modular (Con los pies en la tierra).\nPreparación: pon en juego la carta de Entorno Campanario, con la cara de En silencio boca arriba.","f":"Nada más veros, Veneno enloquece de furia y os araca sin descanso, dejando un rastro de destrucción por toda la ciudad."},
  "27076b": {"n":"\"¡Dejadnos en paz!\"","t":"Contenido: Veneno (I) y Veneno (II). (Veneno (II) y Veneno (III) para jugar en modo Experto.) Conjuntos de Encuentros de Veneno, Fuerza simbiótica y Normal. Un conjunto de Encuentros modular (Con los pies en la tierra).\nPreparación: pon en juego la carta de Entorno Campanario, con la cara de En silencio boca arriba.","f":"Nada más veros, Veneno enloquece de furia y os araca sin descanso, dejando un rastro de destrucción por toda la ciudad."},
  "27077a": {"n":"Campanario","t":"Si hay al menos 3[per_hero] contadores de Campanada sobre esta carta, dale la vuelta a esta carta.\nInterrupción: cuando se vaya a infligir cualquier cantidad de Daño a Veneno como consecuencia de un ataque, en vez de eso puedes (si quieres) colocar ese mismo número de contadores de Campanada sobre esta carta.","f":"El simbionte Veneno es muy sensible a los ruidos fuertes..."},
  "27077b": {"n":"Campanario","t":"Aumenta en 1 todo el Daño que sufra Veneno.\nSi no hay contadores de Campanada sobre esta carta, dale la vuelta a esta carta.\nInterrupción obligada: cuando el ataque de Veneno vaya a infligir cualquier cantidad de Daño a un Superhéroe, quita esa misma cantidad de contadores de Campanada de esta carta. Se evita 1 de ese Daño por cada contador de Campanada que se haya retirado de este modo."},
  "27078": {"n":"\"¡Ahora si que nos hemos enfadado!\"","t":"Vincula esta carta a Veneno.\nUsos (2 contadores de Ira).\n[star] Los ataques de Veneno ganan Brutalidad.\nRespuesta obligada: después de que Veneno sufra cualquier cantidad de Daño a consecuencia de un ataque, quita 1 contador de Ira de esta carta.\n[star] Aumento: Muestra esta carta."},
  "27079": {"n":"Defensa del campanario","t":"El texto de reglas impreso del Campanario se trata como si estuviese en blanco (a excepción de los rasgos).\nCuando se muestre esta carta: quita todos los contadores de Campanada del Campanario y dale la vuelta para dejar boca arriba su cara de en silencio."},
  "27080": {"n":"Dando guerra","t":"Respuesta: después de que Veneno sufra cualquier cantidad de Daño a consecuencia de un ataque, quita esa misma cantidad de Amenaza de esta carta.\n[star] Aumento: si esta activación es un ataque, sufres 2 de Daño indirecto."},
  "27081": {"n":"Con uñas y dientes","t":"Respuesta: después de que Veneno sufra cualquier cantidad de Daño a consecuencia de un ataque, quita esa misma cantidad de Amenaza de esta carta.\n[star] Aumento: si esta activación es un ataque, gana Penetrante."},
  "27082": {"n":"Réplica mordaz","t":"Cuando se muestre esta carta: Veneno se activa contra ti. Cada carta de aumento que se ponga boca arriba durante esa activación recibe +1 icono de Aumento [boost].\n[star] Aumento: quita 1 contador de Campanada del Campanario."},
  "27083": {"n":"Por quién doblan las campanas","t":"Cuando se muestre esta carta: quita 2 contadores de Campanada del Campanario. Si el Campanario tiene boca arriba su cara de En silencio, sufres 1 de Daño. Si tiene boca arriba su cara de sonando, quita 1 de Amenaza del Plan principal.\n[star] Aumento: Resuelve la capacidad \"Cuando se muestre esta carta \" de esta carta."},
  "27084": {"t":"Miedo incipiente — [star] Respuesta obligada: después de que resuelvas una carta de aumento durante la activación de Mysterio, coloca esa carta en tu pila de descartes si tiene el rasgo [ilusión]].","f":"¡Bienvenidos a vuestra peor pesadilla!"},
  "27085": {"t":"Cuando se muestre esta carta: siguiendo el orden de jugadores, añade la primera carta del mazo de Encuentros al mazo de cada jugador y barájalo.\nMiedo en aumento — [star] Respuesta obligada: después de que resuelvas una carta de aumento durante la activación de Mysterio, coloca esa carta en la parte inferior de tu mazo si tiene el rasgo ilusión."},
  "27086": {"t":"Cuando se muestre esta carta: descarta las 5 primeras cartas del mazo de cada jugador.\nPresa del pánico - [star] Respuesta obligada: después de que resuelvas una carta de aumento durante la activación de Mysterio, coloca esa carta en la parte superior de tu mazo si tiene el rasgo ilusión."},
  "27087a": {"n":"Laberinto de espejos","t":"Interrupción obligada: cuando vayas a robar o descartar una carta de Encuentro de tu mazo, quédatela como carta de Encuentro boca abajo → roba 1 carta."},
  "27087b": {"n":"Laberinto de espejos","t":"Contenido: Mysterio (I) y Mysterio (II). (Mysterio (II) y Mysterio (III) para jugar en modo Experto.) Conjuntos de Encuentros de Mysterio, Pesadilla personal y Normal. Un conjunto de Encuentros modular (Susurros paranoides.)\nPreparación: pon en juego un Esbirro Aparición omnipresente efrentado a cada jugador. (Baraja el mazo.)","f":"En cada recodo del camino aparecen innumerables copias vuestras. Los cristales rotos se vuelven a recompone, y pese a todos vuestros intentos por buscar la salida del laberinto, sólo conseguís adentraros aún más en él. Tal vez el único modo de escapar sea derrotar a Mysterio."},
  "27088a": {"n":"Los límites de la realidad","t":"Interrupción oblligada: cuando vayas a robar o descartar una carta de Encuentro de tu mazo, quédatela como carta de Encuentro boca abajo → roba 1 carta.\nSi se completa esta etapa, los jugadores pierden la partida."},
  "27088b": {"n":"Los límites de la realidad","t":"Cuando se muestre esta carta: siguiendo el orden de jugadores, añade las 2 primeras cartas del mazo de Encuentros al mazo de cada jugador y barájalo.","f":"¡Si no os dais prisa, las alucinaciones podrían acabar convirtiéndose en una parte permanente de vuestra psique y quedaríais atrapados en una pesadilla eterna!"},
  "27089": {"n":"Alucinación descomunal","t":"Vincula esta carta a Mysterio.\nAcción de Héroe: gasta 1 recurso de cualquier tipo, añade a tu mazo las 2 primeras cartas del mazo de Encuentros y baraja tu mazo → descarta esta carta.","f":"\"¡Y ahora te aplastaré como el insecto que eres!\" —Mysterio"},
  "27090": {"n":"Espejismo magistral","t":"Vincula esta carta a Mysterio.\nInterrupción obligada: cuando vayas a infligir cualquier cantidad de Daño a Mysterio, en vez de eso descarta las 4 primeras cartas de la parte superior de tu mazo. Descarta esta carta.\n[star] Aumento: dale a Mysterio 1 carta de aumento adicional para esta activación."},
  "27091": {"n":"Aparición omnipresente","t":"Guardia. (Mientras este Esbirro esté enfrentado a ti, no podrás atacar al Villano.)\nCuando se derrote esta carta: si se ha derrotado a este Esbirro inflingiéndole Daño sobrante, el jugador que lo ha derrotado coge la primera carta del mazo de Encuentros, la añade a su mazo y lo baraja."},
  "27092": {"n":"Reminiscencia","t":"Peligro. (Mientras estés resolviendo esta carta, los demás jugadores no podrán ayudarte.)\nCuando se muestre esta carta: elige entre sufrir 1 de Daño o colocar 1 de Amenaza sobre el Plan principal. Añade Reminiscencia al mazo de cualquier jugador y barájalo.\n[star] Aumento: Muestra esta carta."},
  "27093": {"n":"Maestro del terror","t":"Oleada.\nCuando se muestre esta carta: descarta tu mano de cartas. Roba cartas hasta restablecer el tamaño de tu mano.\n[star] Aumento: elige entre gastar recursos [mental][mental] o bien quedarte esta carta como carta de Encuentro boca abajo."},
  "27094": {"t":"[star] Respuesta obligada: después de que el Doctor Octopus ataque y te inflija Daño, coloca 1 de Amenaza sobre cada Plan. Traslada el contador de Villano activo al siguiente Villano en el orden de activación.\nCuando se derrote esta carta: quita 4 de Amenaza de un Plan secundario (7 de Amenaza si no hay ningún otro Villano en juego). Aparta este Villano a un lado."},
  "27095": {"t":"[star] Respuesta obligada: después de que Electro ataque y te inflija Daño, descarta las 7 primeras cartas de la parte superior de tu mazo. Traslada el contador de Villano activo al siguiente Villano en el orden de activación.\nCuando se derrote esta carta: quita 4 de Amenaza de un Plan secundario (7 de Amenaza si no hay ningún otro Villano en juego). Aparta este Villano a un lado."},
  "27096": {"n":"Duende","t":"[star] Respuesta obligada: después de que el Duende ataque y te inflija Daño, sufres 2 de Daño indirecto. Traslada el contador de Villano activo al siguiente Villano en el orden de activación.\nCuando se derrote esta carta: quita 4 de Amenaza de un Plan secundario (7 de Amenaza si no hay ningún otro Villano en juego). Aparta este Villano a un lado."},
  "27097": {"n":"Kraven el Cazador","t":"[star] Respuesta obligada: después de que Kraven el Cazador ataque y te inflija Daño, elige 1 Apoyo o Mejora que controles y descártalo. Traslada el contador de Villano activo al siguiente Villano en el orden de activación.\nCuando se derrote esta carta: quita 4 de Amenaza de un Plan secundario (7 de Amenaza si no hay ningún otro Villano en juego). Aparta este Villano a un lado."},
  "27098": {"n":"Escorpión","t":"[star] Respuesta obligada: después de que el Escorpión ataque y te inflija Daño, aturde a un personaje que controles. Traslada el contador de Villano activo al siguiente Villano en el orden de activación.\nCuando se derrote esta carta: quita 4 de Amenaza de un Plan secundario (7 de Amenaza si no hay ningún otro Villano en juego). Aparta este Villano a un lado."},
  "27099": {"n":"Buitre","t":"[star] Respuesta obligada: después de que Electro ataque y te inflija Daño, descarta las 7 primeras cartas de la parte superior de tu mazo. Traslada el contador de Villano activo al siguiente Villano en el orden de activación.\nCuando se derrote esta carta: quita 4 de Amenaza de un Plan secundario (7 de Amenaza si no hay ningún otro Villano en juego). Aparta este Villano a un lado."},
  "27100a": {"n":"Sincronización siniestra","t":"Contenido: Doctor Octopus, Electro, Duende, Kraven el Cazador, Escorpión y Buitre. Conjuntos de Encuentros de Los seis siniestros, Tácticas de guerrilla y Normal.\nPreparación: elige X Villanos al azar, siendo X 1 más que el número de jugadores. Pon en juego esos Villanos, coloca el contador de Villano activo sobre el Villano que tenga la puntuación más baja en el orden de activación y aparta a un lado los demás Villanos. Pon en juego el Plan secundario La luz al final del túnel, con la cara de ¡trampa! boca arriba."},
  "27100b": {"n":"Sincronización siniestra","t":"¡Emboscada! — Especial: elige al azar un Villano que esté apartado, ponlo en juego y colócale encima el contador de Villano activo. (En modo Experto, coloca 2 de Amenaza sobre La luz al final del túnel).\nInterrupción obligada: cuando vaya a activarse un Villano, si no hay ninguno en juego, resuelve la capacidad \"¡Emboscada!\" de esta carta. Reanuda esa activación."},
  "27101a": {"n":"Zurra siniestra","t":"Cuando se muestre esta carta: eliga al azar un Villano que esté apartado, ponlo en juego y colócale encima el contador de Villano activo (incluso aunque otro Villano tenga el contador en este momento). Si no se pone en juego ningún Villano de este modo, o si es una partida en modo Experto, dale al jugador inicial 1 carta de Encuentro boca abajo.","f":"Los seis villanos están más confiados que nunca y se muestran decididos a acabar con vosotros de una vez por todas."},
  "27101b": {"n":"Zurra siniestra","t":"¡Emboscada! — Especial: elige al azar un Villano que esté apartado, ponlo en juego y colócale encima el contador de Villano activo. (En modo Experto, caloca 2 de Amenaza sobre La luz al final del túnel).\nInterrupción obligada: cuando vaya a activarse un Villano, si no hay ninguno en juego, resuelve la capacidad \"¡Emboscada!\" de esta carta. Reanuda esa activación.\nSi se completa esta etapa, los jugadores pierden la partida."},
  "27102a": {"n":"La luz al final del túnel","t":"Permanente. Complicación 10[per_hero].\nLos jugadores no pueden ganar a menos que logren escapar.\nInterrupción obligada: cuando se quite la última ficha de Amenaza de este Plan, resuelve la capacidad \"¡Emboscada!\" del Plan principal. Dale la vuelta a esta carta. (Los jugadores podrán escapar por la otra cara.)"},
  "27102b": {"n":"La luz al final del túnel","t":"Permanente. Complicación 10[per_hero].\nLos jugadores no pueden ganar a menos que logren escapar.\nInterrupción obligada: cuando se quite la última ficha de Amenaza de este Plan, los jugadores logran escapar y ganan la partida."},
  "27103": {"n":"Moral reforzada","t":"Vincula esta carta al Villano que tenga la puntuación más alta dentro del orden de activación. Si no es posible, resuelve la capacidad \"¡Emboscada!\" del Plan principal y luego vincula esta carta al Villano activo.\nX es igual al número de Villanos que haya en juego."},
  "27104": {"n":"Presencia provocadora","t":"Vincula esta carta al Villano que tenga más Vida restante. Si no es posible, resuelve la capacidad \"¡Emboscada!\" del Plan principal y luego vincula esta carta al Villano activo.\nNo puede quitarse Amenaza de La luz al final del túnel."},
  "27105": {"n":"Líder del grupo","t":"Vincula esta carta al Villano que tenga la puntuación más baja dentro del orden de activación. Si no es posible, resuelve la capacidad \"¡Emboscada!\" del Plan principal y luego vincula esta carta al Villano activo."},
  "27106": {"n":"Sacrificio por el equipo","t":"Vincula esta carta al Villano que tenga la puntuación más alta de ATQ. Si no es posible, resuelve la capacidad \"¡Emboscada!\" del Plan principal y luego vincula esta carta al Villano activo.\nNo puedes atacar a Villanos que no tengan vinculada una copia de Sacrificio por el equipo."},
  "27107": {"n":"Barrera de fuerza bruta","t":"Victoria 1. (Cuando esta carta sea derrotada, añádela a la zona de victoria.)\nNo puede quitarse Amenaza de otros Planes secundarios.\n[star] Aumento: Dale al Villano 1 carta de aumento adicional para esta activación."},
  "27108": {"t":"En modo Experto, esta carta gana Incitar 1 y no puede anularse.\nCuando se muestre esta carta: pon en juego las cartas apartadas del Duende y el Buitre. Si el Duende ya está en juego, sufres 2 de Daño indirecto. Si el Buitre ya está en juego, descarta 1 carta de tu mano al azar."},
  "27109": {"n":"Vestuario exótico","t":"En modo Experto, esta carta gana Incitar 1 y no puede anularse.\nCuando se muestre esta carta: pon en juego las cartas apartadas de Electro y Kraven el Cazador. Si Electro ya está en juego, descarta la carta que controles que tenga el coste más alto. Si Kraven el Cazador ya está en juego, descarta la carta que controles que tenga el coste más bajo."},
  "27110": {"n":"Mejoras robóticas","t":"En modo Experto, esta carta gana Incitar 1 y no puede anularse.\nCuando se muestre esta carta: pon en juego las cartas apartadas del Doctor Octopus y el Escorpión. Si el Doctor Octopus ya está en juego, confunde a un personaje que controles. Si el Escorpión ya está en juego, aturde a un personaje que controles."},
  "27111": {"n":"Cómplices en crueldad","t":"Cuando se muestre esta carta (Alter ego): el Villano que tenga la puntuación más baja en el orden de activación ejecuta el Plan con +X PLA, siendo X igual a la suma de las puntuaciones de PLA de todos los demás Villanos que haya en juego.\nCuando se muestre esta carta (Héroe): el Villano que tenga la puntuación más alta en el orden de activación te ataca con +X ATQ, siendo X igual a la suma de las puntuaciones de ATQ de todos los demás Villanos que haya en juego."},
  "27112": {"n":"¡Sorpresa!","t":"En modo Experto, esta carta gana Oleada y no puede anularse.\nCuando se muestre esta carta: resuelve la capacidad \"¡Emboscada!\" del Plan principal. Si no se pone en juego ningún Villano de este modo, coloca 3 de Amenaza sobre La luz al final del túnel.","f":"\"...\" —Spiderman"},
  "27113": {"n":"Duende Veneno","t":"Tesón.\nInfestar la ciudad — [star] Respuesta obligada: después de que el Duende Veneno se active contra ti, traslada el contador de Planeador al Plan principal que tenga menos Amenaza. Elige entre colocar 2 de Amenaza sobre ese Plan o bien resolver su capacidad \"Especial\"."},
  "27114": {"n":"Duende Veneno","t":"Tesón. Dureza.\nCuando se muestre esta carta: reparte 2 cartas de Encuentro boca abajo a cada jugador.\nReclamar el trono — [star] Respuesta obligada: después de que el Duende Veneno se active contra ti, traslada el contador de Planeador al Plan principal que tenga menos Amenaza. Resuelve su capacidad \"Especial\"."},
  "27115": {"n":"Duende Veneno","t":"Represalia 1. Firmeza. Dureza.\nCuando se muestre esta carta: reparte 3 cartas de Encuentro boca abajo a cada jugador.\nReinado de terror — [star]Respuesta obligada: después de que el Duende Veneno se active contra ti, traslada el contador de Planeador al Plan principal que tenga menos Amenaza. Coloca 1 de Amenaza sobre ese Plan y resuelve su capacidad \"Especial\"."},
  "27116a": {"n":"El cielo de Nueva York","t":"Contenido: Duende Veneno (I) y Duende Veneno (II) (Duende Veneno (II) y Duende Veneno (III) para jugar en modo Experto.) Conjuntos de Encuentros del Duende Veneno, Fuerza simbiótica y Normal. Un conjunto de Encuentros modular (Artilugios de duende).\nPreparación: pon en juego los Planes principales Lower Manhattan, Midtown Manhattan y Upper Manhattan. Coloca el contador de Planeador sobre Midtown Manhattan. Dale la vuelta a esta carta y apártala a un lado."},
  "27116b": {"n":"El cielo de Nueva York","t":"Las cartas de Jugador que afecten al Plan principal pueden aplicarse a cualquier Plan principal.\nLas cartas de Encuentro que afecten al Plan principal sólo se aplican al Plan que tenga asignado el contador de Planeador (esto incluye la colocación de gichas de Aceleración).\nCada Plan principal acumula Amenaza cada ronda en función de su valor de Aceleración y de las fichas de Aceleración que tenga encima."},
  "27117a": {"t":"Especial: coloca 1 de Amenaza sobre cada Plan. Si hay en juego algún Entorno simbionte, coloca 1 de Amenaza adicional sobre este Plan.","f":"La zona sur de Manhattan es un hervidero de actividad comercial; la mayoría de sus ciudadanos están tan concentrados en sus finanzas que apenas han reparado en el intento del Duende Veneno por apoderarse de la ciudad."},
  "27117b": {"t":"Cuando se muestre esta carta: traslada el contador de Planeador y todas las fichas de Aceleración que haya sobre esta carta al Plan principal que tenga menos Amenaza.\nSi hay al menos 2 cartas de Entorno simbionte en juego, los jugadores pierden la partida."},
  "27118a": {"t":"Especial: sufres 2 de Daño indirecto. Si hay en juego algún Entorno simbionte, sufres 1 de Daño indirecto adicional.","f":"Los emblemáticos edificios y las concurridas calles de la zona central de Manhattan os impiden seguir con claridad el vuelo zigzagueante del Duende Veneno."},
  "27118b": {"t":"Cuando se muestre esta carta: traslada el contador de Planeador y todas las fichas de Aceleración que haya sobre esta carta al Plan principal que tenga menos Amenaza.\nSi hay al menos 2 cartas de Entorno simbionte en juego, los jugadores pierden la partida."},
  "27119a": {"t":"Especial: descarta 1 carta de tu mano. Si hay en juego algún Entorno simbionte, descarta las 4 primeras cartas de la parte superior de tu mazo.","f":"Los habitantes de la zona norte de Manhattan disfrutan de un día soleado en Central Park y Harlem, sin ser conscientes de que el Duende Veneno planea infestar su comunidad."},
  "27119b": {"t":"Cuando se muestre esta carta: traslada el contador de Planeador y todas las fichas de Aceleración que haya sobre esta carta al Plan principal que tenga menos Amenaza.\nSi hay al menos 2 cartas de Entorno simbionte en juego, los jugadores pierden la partida."},
  "27120": {"n":"Somos uno","t":"Vincula esta carta al Duende Veneno.\nAcción de Héroe: gasta recursos impresos [energy][mental][physical] → descarta esta carta.","f":"El Duende Verde era débil y patético. Pero NOSOTROS somos más poderosos de lo que él había soñado jamás."},
  "27121": {"n":"Simbionte enloquecido","t":"[star] Mientras haya en juego un Entorno simbionte, el Simbionte enloquecido gana Ataque veloz.\n[star] Aumento: traslada el contador de Planeador al Plan principal que tenga más Amenaza. Coloca 1 de Amenaza sobre ese Plan."},
  "27122": {"n":"Monstruosidad simbiótica","t":"Represalia 1. Tesón. Dureza.\n[star] Mientras haya en juego un Entorno simbionte, la Monstruosidad simbiótica recibe +3 de Vida.\n[star] Aumento: si esta activación es un ataque, inflige Daño indirecto."},
  "27123": {"n":"Esclavo simbiótico","t":"Guardia.\nMientras haya en juego un Entorno simbionte, el Esclavo simbiótico gana Patrulla.\n[star] Aumento: coloca 1 de Amenaza sobre cada Plan principal que no tenga asignado el contador de Planeador."},
  "27124": {"n":"Masa infecciosa","t":"Mientras no haya en juego ningún otro Entorno simbionte, esta carta se considera un Entorno simbionte.\n[star] Aumento: muestra esta carta."},
  "27125": {"n":"Escapada aérea","t":"Complicación 2[per_hero].\nCuando se muestre esta carta: traslada el contador de Planeador al Plan principal que tenga más Amenaza. Resuelve la capacidad \"Especial:\" de ese Plan."},
  "27126": {"n":"Sembrar el pánico","t":"Cuando se muestre esta carta: resuelve la capacidad \"Especial:\" del Plan que tenga asignado el contador de Planeador.\n[star] Aumento: resuelve la capacidad \"Especial:\" del Plan que tenga asignado el contador de Planeador."},
  "27127": {"n":"Pánico en las calles","t":"El texto de reglas impreso de todos los Apoyos lugar e individuo se trata como si estuviese en blanco (a excepción de los rasgos)."},
  "27128": {"n":"Rino","t":"Tesón. (Un personaje con Tesón requiere 2 cartas de Estado del mismo tipo para quedar aturdido o confundido.)\n[star] Los ataques del Rino ganan Brutalidad y Penetrante."},
  "27129": {"n":"Favores pendientes","t":"Cuando se muestre esta carta: el Rino ejecuta el Plan con +2 PLA. Si el Rino no está en juego, busca un Esbirro llamado Rino en el mazo y la pila de descartes de Encuentros y ponlo en juego enfrentado a ti. (Baraja el mazo.)","f":"\"Os ayudaré, pero sólo si dejáis que rompa cosas y me las quede luego.\" —Rino"},
  "27130": {"n":"Ahora o nunca","t":"Peligro. (Mientras estés resolviendo esta carta, los demás jugadores no podrán ayudarte.)\nCuando se muestre esta carta: elige una opción:\nColoca 1 ficha de Aceleración sobre el Plan principal.\nAgota un personaje que controles y gasta 1 recurso de cualquier tipo."},
  "27131": {"n":"Criminal de poca monta","t":"Oleada.\nAcción de Alter ego: gasta un recurso [physical] → inflige 3 de Daño al Criminal de poca monta. Si este Esbirro es derrotado de este modo, elige entre robar 1 carta o quitar 3 de Amenaza de un Plan secundario."},
  "27132": {"n":"Amigos y familiares","t":"Mientras tengas adoptada tu identidad de Héroe, el coste en recursos de todos los Eventos que juegues se incrementa en 1.\nAcción de Alter ego: descarta 1 carta específica de un Superhéroe de tu mano → descarta esta Obligación.","f":"\"Ya lo sé, tienes que hacer lo que tienes que hacer. Y yo no voy a impedírtelo... pero tú tampoco puedes impedirme que me preocupe por mi niñita.\" —Ronnie Williams"},
  "27133": {"n":"Voluntariado","t":"No se puede intervenir contra este Plan.\nAcción de Alter ego: gasta 2 recursos de cualquier tipo → quita tanta Amenaza de este Plan como la puntuación de REC de tu Alter ego. Si tu Superhéroe tiene el rasgo civil, roba 1 carta."},
  "27134": {"n":"\"¿Peligro o amenaza?\"","t":"Cuando se muestre esta carta: puedes cambiar de identidad. Si tienes adoptada tu identidad de Héroe, coloca 2 de Amenaza sobre el Plan principal. Si tienes adoptada la identidad de tu Alter ego, no podrás cambiar de identidad durante tu próximo turno.","f":"\"¡Lo sabéis tan bien como yo! ¡Todas esas personas disfrazadas de araña no son más que un hatajo de maleantes! Después de todo, quien va con la cara tapada es porque no trama nada bueno.\" —J. Jonah Jameson"},
  "27135": {"n":"Cabos sueltos","t":"Cuando se muestre esta carta: busca tu Obligación en el mazo de Encuentros, en su pila de descartes, entre las cartas apartadas y entre las cartas que se han retirado de la partida, y luego muéstrala. Al mostrarla, si cambias a la identidad de tu Alter ego, descarta 1 carta de tu mano al azar. Si tu Obligación no se ha mostrado de este modo, esta carta gana Oleada."},
  "27136": {"n":"Planeador avanzado","t":"Vincula esta carta al Villano.\nRespuesta obligada: después de que el Villano vinculado se active contra tu, vuelve a activarse contra ti. (Límite de una vez por ronda y jugador.)\nAcción de Héroe: descarta cualquier número de cartas de ataque de tu mano que sumen entre todas un coste en recursos de 3 o más → descarta esta carta."},
  "27137": {"n":"Bombas de impacto","t":"Vincula esta carta al Villano.\nUsos (2 contadores de Bomba).\n[star] Respuesta obligada: después de que el Villano te ataque, quita 1 contador de Bomba de esta carta → agota 1 Mejora y 1 Apoyo que controles.","f":"Su onda expansiva es tan potente que puede resquebrajar el acero."},
  "27138": {"n":"Bombas incendiarias","t":"Vincula esta carta al Villano.\nUsos (2 contadores de Bomba).\n[star] Respuesta obligada: después de que el Villano te ataque, quita 1 contador de Bomba de esta carta → sufres 2 de Daño indirecto.","f":"Están rellenas con un combustible sumamente volátil que arde con una intensidad abrasadora."},
  "27139": {"n":"Bombas de humo","t":"Vincula esta carta al Villano.\nUsos (2 contadores de Bomba).\n[star] Respuesta obligada: después de que el Villano te ataque, quita 1 contador de Bomba de esta carta → descarta 1 Evento de tu mano que tenga el coste más bajo.","f":"La densa humareda tóxica que liberan estas bombas puede incapacitar en el acto incluso a los enemigos más duros."},
  "27140": {"n":"Suministro ilimitado","t":"Todos los Accesorios tecnología ganan Oleada.","f":"Norman Osborn ha estado muy atareado fabricado y almacenando dispositivos tecnológicos, y ahora tanto él como sus compinches disponen de un cuantioso arsenal de armas y artilugios."},
  "27141": {"n":"Control remoto","t":"Cuando se muestre esta carta: si está en juego el Planeador avanzado, el Villano se activa contra ti. Si no está en juego, busca el Planeador avanzado en el mazo y la pila de descartes de Encuentros y muéstralo.\n[star] Aumento: dale al Villano 2 cartas de aumento adicionales para esta activación."},
  "27142": {"n":"Señuelo en tamaño real","t":"En modo Experto, el Señuelo en tamaño real gana Dureza.\nEl juegador enfrentado no puede intervenir contra Planes secundarios.\n[star] Aumento: pon en juego este Esbirro enfrentado a ti."},
  "27143": {"n":"Esfuerzo coordinado","t":"Cada enemigo gana 1 icono de Aceleración ([acceleration]).\n[star] Aumento: coloca 1 de Amenaza sobre cada Plan. (En modo Experto, coloca 1 de Amenaza adicional sobre el Plan principal.)"},
  "27144": {"n":"Oculto entre las sombras","t":"Cada enemigo gana 1 icono de Riesgo ([hazard]).\n[star] Aumento: inflige 1 de Daño indirecto a cada jugador. (en modo Experto, inflige 1 de Daño indirecto adicional al jugador inicial.)"},
  "27145": {"n":"La unión hace la fuerza","t":"Cada enemigo recibe +1 PLA y +1 ATQ.\n[star] Aumento: en modo Experto, esta carta recibe +2 iconos de Aumento ([boost][boost]) para esta activación."},
  "27146": {"n":"A diestro y siniestro","t":"En modo Experto, esta gana Oleada.\nCuando se muestre esta carta: coloca 1 de Amenaza sobre el Plan principal por cada enemigo que haya en juego.","f":"La oscuridad baila con intenciones siniestras."},
  "27147": {"n":"Cañón de antebrazo","t":"Oleada.\nVincula esta carta al Villano.\n[star] Los ataques del Villano vinculado ganan Brutalidad y Penetrante.\nAcción de Héroe: descarta la Mejora con el coste más alto que controles → descarta esta carta."},
  "27148": {"n":"Botas iónicas","t":"Oleada.\nVincula esta carta al Villano.\n[star] Respuesta obligada: después de que el Villano vinculado ataque e inflija Daño a tu Superhéroe, coloca 2 de Amenaza sobre el Plan principal.\nAcción de Héroe: gasta recursos [energy][mental][physical] → descarta esta carta."},
  "27149": {"n":"Blindaje cinético","t":"Oleada.\nVincula esta carta al Villano.\nEl Villano vinculado gana Represalia 1.\nAcción de Héroe: sufre 3 de Daño indirecto → descarta esta carta."},
  "27150": {"n":"Malla de neocarbono","t":"Oleada.\nVincula esta carta al Villano.\nReduce en 1 el Daño que sufre el Villano vinculado en cada ataque.\nAcción de Héroe: dale al Villano una carta de Estado \"Duro\" y 1 carta de aumento boca abajo → descarta esta carta."},
  "27151": {"n":"Guantelete con pinchos","t":"Oleada.\nVincula esta carta al Villano.\nAcción de Héroe: el Villano te ataca. Después de que termine ese ataque, si tu Superhéroe no ha sufrido Daños a consecuencia del mismo, descarta esta carta."},
  "27152": {"n":"Visor de localización","t":"Oleada.\nVincula esta carta al Villano.\n[star] Ningún personaje puede defender contra los ataques del Villano vinculado.\nAcción de Héroe: agota un personaje que controles y descarta 1 carta de tu mano al azar → descarta esta carta."},
  "27153": {"n":"Pánico inducido","t":"Vincula esta carta a tu Superhéroe.\nNo puedes resolver las capacidades aplicadas impresas en el texto de reglas de tu Héroe. (Las capacidades aplicadas son las que tienen un encabezado en negrita que señala el momento en que se aplican.)/nAcción de Alter ego: descarta de tu mano 1 carta al azar que sea específica de un Superhéroe → descarta esta carta."},
  "27154": {"n":"Doble malvado","t":"El Doble malvado recibe +X PLA y +X ATQ, siendo X igual al número de cartas específicas de Superhéroes que haya en la mano del jugador enfrentado.\n[star] Aumento: roba 3 cartas. Descarta 3 cartas de tu mano al azar."},
  "27155": {"n":"En las nubes","t":"Victoria 1. (Cuando esta carta sea derrotada, añádela a la zona de victoria.)\nCada Superhéroe recibe +2 al tamaño de su mano."},
  "27156": {"n":"Debilidad interior","t":"Cuando se muestre esta carta: coloca 1 de Amenaza adicional sobre esta carta por cada carta que tengas en la mano.","f":"Mysterio es un maestro del terror capaz de identificar las fobias de sus víctimas estudiando hasta el menor de sus respingos."},
  "27157": {"n":"Los miedos más profundos","t":"Peligro. (Mientras estés resolviendo esta carta, los demás jugadores no podrán ayudarte.)\nCuando se muestre esta carta: descarta tantas cartas de la parte superior de tu mazo como el número de cartas que tengas en la mano. Si se descarta de este modo al menos 1 carta específica de un Superhéroe, coloca 1 de Amenaza sobre el Plan principal. Si no se descarta ninguna carta específica de un Superhéroe, sufres 1 de Daño."},
  "27158": {"t":"Incitar 2. Infame.\n[star] Respuesta obligada: después de que el Doctor Octopus se active contra tu, coloca 1 de Amenaza sobre cada Plan.","f":"¡Mira cómo atrapo una araña en mi propia tela formada con mis nuevos brazos!"},
  "27159": {"t":"Represalia 1. Infame.\nRespuesta obligada: después de que Electro se enfrente a ti o se active contra ti, descarta cartas de la parte superior de tu mazo hasta que descartes un recurso [energy] o [wild].","f":"¡Con mis grandes poderes, nada podrá detenerme!"},
  "27160": {"n":"Duende","t":"Patrulla. Infame.\n[star] Respuesta obligada: después de que el Duende te ataque, sufres 2 de Daño indirecto.","f":"No te imaginas cuánto voy a disfrutar esto."},
  "27161": {"n":"Kraven el Cazador","t":"Tesón. Infame.\n[star] Respuesta obligada: después de que Kraven el Cazador ataque e inflija Daño a un personaje que controles, descarta 1 Mejora o Apoyo que controles.","f":"Mis cuchillos están tan afilados como mi instinto."},
  "27162": {"n":"Escorpión","t":"Dureza. Infame.\n[star] Respuesta obligada: después de que el Escorpión ataque e inflija Daño a un personaje, aturde a ese personaje. Si ya estaba aturdido, le inflige 2 de Daño.","f":"Esto es la última batalla de Spiderman, ¿no? No me la perdería por nada del mundo."},
  "27163": {"n":"Buitre","t":"Ataque veloz. Infame.\n[star] Respuesta obligada: después de que el Buitre se active contra ti, descarta 1 carta de tu mano al azar.","f":"Nadie odia más que yo al trepamuros."},
  "27164": {"n":"Armas improvisadas","t":"Vincula esta carta al Villano.\nAcción de Héroe: gasta recursos [mental][physical][energy] → descarta esta carta."},
  "27165": {"n":"Tendencias violentas","t":"Vincula esta carta al Villano.\nRespuesta obligada: después de que el Villano vinculado sufra cualquier cantidad de Daño a consecuencia de un ataque, dale 1 carta de aumento boca abajo. Si el ataque ha infligido al menos 3 de Daño al Villano vinculado, descarta esta carta..","f":"Mmm, sesos..."},
  "27166": {"n":"Envuelto en telaraña","t":"Vincula esta carta a tu Superhéroe.\nInterrupción obligada: cuando tu Héroe vaya a atacar, en vez de eso descarta Envuelto en telaraña. Luego quedas aturdido.\n[star] Aumento: quedas aturdido. Si ya estabas aturdido, sufres 2 de Daño."},
  "27167": {"n":"Simbionte rabioso","t":"Guardia. Patrulla. (Mientras este Esbirro esté enfrentado a ti, no podrás intervenir en el Plan principal.)\n[star] Aumento: pon en juego al Simbionte rabioso enfrentado a ti."},
  "27168": {"n":"Ataque en balanceo","t":"Cuando se muestre esta carta (Alter ego): cambia a tu identidad de Héroe. El Villano te ataca.\nCuando se muestre esta carta (Héroe): el Villano te ataca. Dale al Villano 1 carta de aumento adicional para esa activación.","f":"\"¿Es que no aprenderéis nunca, perdedores?\" —Veneno"},
  "27169": {"n":"Inteligencia inestable","t":"Oleada.\nCuando se muestre esta carta: dale al Villano 1 carta de aumento boca abajo.\n[star] Aumento: si esta activación es un ataque, esta carta recibe +2 iconos de Aumento ([boost][boost]) para este ataque, y además este ataque gana Brutalidad."},
  "27170": {"n":"Manía persecutoria","t":"Vincula esta carta a tu Superhéroe.\nNo puedes preparar Aliados ni tampoco Apoyos individuo que controles.\nAcción de Alter ego: descarta un Aliado o un Apoyo individuo que controles → descarta esta carta.\n[star] Aumento: si este ataque derrota a un Aliado, sufres tanto Daño indirecto como el coste impreso de ese Aliado."},
  "27171": {"n":"Mente manipulada","t":"El Aliado vinculado se trata como si fuera un Esbirro con el texto de reglas impreso en blanco (a excepción de los rasgos). La puntuación de PLA del Esbirro vinculado es igual a su puntuación impresa de INT, y no sufre Daño derivado.\nCuando se muestre esta carta: vincula esta carta al Aliado controlado por ti que tenga el coste más bajo. Si no es posible, esta carta gana Oleada."},
  "27172": {"n":"Vieja rencilla","t":"El Esbirro vinculado recibe +1 de Vida.\nCuando se muestre esta carta: busca a tu Esbirro Archienemigo en el mazo de Encuentros, en su pila de descartes y en la zona de cartas apartadas, y luego muestra a ese Esbirro. Vincúlale la Vieja rencilla. (Baraja el mazo.)\n[star] Aumento: inflige 1 de Daño a cada personaje que controles."},
  "27173": {"n":"Paralizados por la duda","t":"Cuando se muestre esta carta: busca el Plan secundario de tu Archienemigo en el mazo de Encuentros, en su pila de descartes y en la zona de cartas apartadas, y luego muéstralo. Coloca X de Amenaza adicional sobre esta carta, siendo X igual a la cantidad de Amenaza que haya sobre ese Plan secundario."},
  "27174a": {"n":"Clamor popular","t":"Sólo en modo Normal\nVictoria 1. Usos (2[per_hero] contadores de Mala fama).\nRespuesta: después de que se derrote a un Esbirro o Plan secundario, quita 1 contador de Mala fama de esta carta."},
  "27174b": {"n":"Clamor popular","t":"Sólo en modo Experto\nVictoria 1. Usos (3[per_hero] contadores de Mala fama).\nRespuesta: después de que se derrote a un Esbirro o Plan secundario, quita 1 contador de Mala fama de esta carta."},
  "27175": {"n":"Campaña de difamación","t":"En modo Experto, esta carta gana Oleada.\nCuando se muestre esta carta: si está en juego Clamor popular, colócale encima 2 contadores de Mala fama, luego retira esta carta de la partida. Si Clamor popular no está en juego, coloca 2 de Amenaza sobre el Plan principal."},
  "27176": {"n":"Atraco en un callejón","t":"Oleada.\nVictoria 1.\nRespuesta obligada: después de que intervengas contra este Plan, elige entre gastar 1 recurso [physical] o bien descartar 1 carta de tu mano al azar."},
  "27177": {"n":"Gato subido a un árbol","t":"Oleada.\nVictoria 1.\nComo coste adicional para intervenir contra este Plan, sufres 2 de Daño indirecto."},
  "27178": {"n":"Secuaces atracadores","t":"Oleada.\nVictoria 1.\nRespuesta obligada: después de que si quite cualquier cantidad de Amenaza de este Plan, coloca esa misma cantidad de Amenaza sobre el Plan principal."},
  "27179": {"n":"Descarrilamiento","t":"Oleada.\nVictoria 1.\nInterrupción obligada: cuando empiece la fase del Villano, coloca 1 contado de Velocidad sobre esta carta. Si hay al menos 2 contadores de Velocidad sobre esta carta, retírala de la partida y descarta las 3 primeras cartas del mazo de cada jugar."},
  "27180": {"n":"Rescate entre los escombros","t":"Oleada.\nVictoria 1.\nInterrupción: cuando un personaje realice una intervención básica contra este Plan secundario, puede usar su ATQ en vez de su INT."},
  "27181": {"n":"No hay traición sin castigo","t":"Victoria -1.\nVincula esta carta a Veneno (Eddie Brock). Si no es posible, esta carta gana Oleada.\nInterrupción obligada: cuando un Villano ataque, atacará a Veneno. Si Veneno es derrotado por ese ataque, añade esta carta y la carta de Veneno a la zona de victoria.\nAcción: agota a Veneno y gasta 2 recursos del mismo tipo → descarta esta carta."},
  "27182a": {"n":"Dardos compactos","t":"Inicio. Permanente.\nRespuesta de Héroe: después de que tu Héroe ataque, quita 1 contador de Dardos de esta carta → inflige 1 de Daño a un enemigo.\nAcción de Alter ego: gasta 1 recurso de cualquier tipo → coloca 3 contadores de Dardos sobre esta carta. (Límite de una vez por ronda.)"},
  "27182b": {"n":"Dardos compactos","t":"Permanente.\nRespuesta de Héroe: después de que tu Héroe ataque, quita 1 contador de Dardos de esta carta → inflige 1 de Daño a un máximo de 2 enemigos distintos.\nAcción de Alter ego: gasta 1 recurso de cualquier tipo → coloca 3 contadores de Dardos sobre esta carta. (Límite de una vez por ronda.)"},
  "27183a": {"n":"Tejido antichoque","t":"Inicio. Permanente.\nTu Superhéroe recibe +2 de Vida.\nInterrupción de Héroe: cuando empiece la fase del Villano, gasta 1 recurso de cualquier tipo → hasta el final de la fase, se reduce en 1 la cantidad de Daño que sufra tu Héroe de cada ataque enemigo."},
  "27183b": {"n":"Tejido antichoque","t":"Permanente.\nTu Superhéroe recibe +3 de Vida.\nInterrupción de Héroe: cuando tu Héroe vaya a sufrir cualquier cantidad de Daño a consecuencia de un ataque enemigo, descarta la primera carta de tu mazo → evita 1 de ese Daño."},
  "27184a": {"n":"Lentes láser","t":"Inicio. Permanente.\nTu Héroe recibe -1 INT.\nTu Héroe recibe +1 ATQ, y sus ataques básicos ganan Brutalidad."},
  "27184b": {"n":"Lentes láser","t":"Permanente.\nTu Héroe recibe -1 INT.\nTu Héroe recibe +2 ATQ, y sus ataques básicos ganan Brutalidad y Penetrante."},
  "27185a": {"n":"Guantelete propulsor","t":"Inicio. Permanente.\nAcción de Héroe: agota el Guantelete propulsor y sufre 2 de Daño indirecto → prepara tu Héroe."},
  "27185b": {"n":"Guantelete propulsor","t":"Permanente.\nAcción de Héroe: agota el Guantelete propulsor y sufre 2 de Daño indirecto → prepara tu Héroe. Tu Héroe recibe +1 INT, +1 ATQ y +1 DEF hasta el final de la fase."},
  "27186a": {"n":"Proyector de retina","t":"Inicio. Permanente.\nEl atributo básico de intervención de tu Héroe (INT) sólo puede quitar Amenaza del Plan que tenga más Amenaza.\nTu Héroe recibe +1 INT, y sus intervenciones básicas ignoran el icono de Crisis ([crisis])."},
  "27186b": {"n":"Proyector de retina","t":"Permanente.\nEl atributo básico de intervención de tu Héroe (INT) sólo puede quitar Amenaza del Plan que tenga más Amenaza.\nTu Héroe recibe +2 INT, y sus intervenciones básicas ignoran el icono de Crisis ([crisis]) y la palabra clave Patrulla."},
  "27187a": {"n":"Nudilleras eléctricas","t":"Inicio. Permanente.\nRespuesta de Héroe: después de que tu Héroe realice un ataque básico contra un enemigo, descarta la primera carta del mazo de Encuentros. Si no se ha descartado ningún icono de aumento ([boost]) de este modo, aturde a ese enemigo."},
  "27187b": {"n":"Nudilleras eléctricas","t":"Permanente.\nTu Héroe recibe +1 ATQ.\nRespuesta de Héroe: después de que tu Héroe realice un ataque básico contra un enemigo, descarta la primera carta del mazo de Encuentros. Si se ha descartado como máximo 1 icono de Aumento ([boost]) de este modo, aturde a ese enemigo."},
  "27188a": {"n":"Brazales de ondas","t":"Inicio. Permanente.\nTu Héroe recibe -1 ATQ.\nTu Héroe recibe +1 DEF, y gana Represalia 1 y Tesón."},
  "27188b": {"n":"Brazales de ondas","t":"Permanente.\nTu Héroe recibe -1 ATQ.\nTu Héroe recibe +2 DEF, y gana Represalia 1 y Firmeza."},
  "27189a": {"n":"Rastreador de muñeca","t":"Inicio. Permanente.\nRespuesta obligada: después de que entre en juego un Esbirro o Plan secundario, vincúlale el Rastreador de muñeca.\nInterrupción: cuando la carta vinculada sea derrotada, roba 1 carta. (Devuelve esta carta a tu zona de juego.)"},
  "27189b": {"n":"Rastreador de muñeca","t":"Permanente.\nRespuesta obligada: después de que entre en juego un Esbirro o Plan secundario, vincúlale el Rastreador de muñeca.\nInterrupción: cuando la carta vinculada sea derrotada, roba 2 cartas y luego descarta 1 carta de tu mano."},
  "27190": {"n":"Veneno","t":"Respuesta: después de que muestres una carta de Encuentro, inflige 1 de Daño a Veneno → inflige tanto Daño a un enemigo como el número de iconos ([star] y [boost]) que haya en el recuadro de aumentos de esa carta."},
  "27191": {"n":"Traje simbionte","t":"Máximo de 1 por mazo.\nTu Superhéroe recibe +1 a cada uno de sus atributos básicos, +1 al tamaño de su mano y +10 de Vida"},
  "28001a": {"t":"Respuesta: después de que uses uno de los atributos básicos de Nova (INT, ATQ o DEF), prepara el Casco de Supernova.","f":"\"¿No habéis oído hablar de Nova? ¡Pude con Hulk! ¡Soy un Vengador no oficial en período de prueba!\""},
  "28001b": {"t":"Acción de Alter ego: gasta 1 recurso de cualquier tipo → busca el Casco de Supernova en tu mazo y pila de descartes. Añádelo a tu mano (o ponlo en juego si has pagado el coste de esta capacidad usando un recurso [wild])."},
  "28002": {"t":"Respuesta de Héroe: después de que juegues un Evento, agota a Ms. Marvel e inflígele 1 de Daño → devuelve ese Evento a tu mano.","f":"\"Haré lo que pides. Con honor, compromiso, coraje y todo eso.\""},
  "28003": {"n":"Proyección de campo de fuerza","t":"Interrupción de Héroe: cuando un personaje amigo vaya a sufrir cualquier cantidad de Daño a consecuencia de un ataque, evita 3 de ese Daño. Si has pagado el coste de esta carta usando un recurso [wild], inflige 3 de Daño a un enemigo."},
  "28004": {"n":"Volar a la velocidad de la luz","t":"Duplica el número de recursos [wild] generados al pagar el coste de esta carta.\nAcción de Héroe (intervención): quita 3 de Amenaza de un Plan.","f":"\"Es flipante. Es todo lo que me contó papá. La velocidad. El poder. ¡Es como ser un cohete humano!\" —Nova"},
  "28005": {"n":"Disparar sin mirar","t":"Duplica el número de recursos [wild] generados al pagar el coste de esta carta.\nAcción de Héroe (ataque): inflige 4 de Daño a un enemigo.","f":"\"Nunca deja de molar.\" —Nova"},
  "28006": {"n":"Liberar la Fuerza Nova","t":"Máximo de 1 por ronda.\nAcción de Héroe: hasta el final de la ronda, cada vez que Nova derrote a un enemigo o quite la última ficha de Amenaza de un Plan, prepara a Nova y roba 1 carta."},
  "28007": {"n":"Conexión con la Mundomente","t":"Esta carta no se cuenta de carta al tamaño de tu mano."},
  "28008": {"t":"Acción de Alter ego: agota a Jesse Alexander → coge 1 copia de Conexión con la Mundomente de tu pila de descartes, añádela a tu mazo y barájalo. Roba 1 carta.","f":"\"No siempre estuve a tu lado, pero jamás dejé de creer en ti.\""},
  "28009": {"n":"Casco de Supernova","t":"Nova gana el rasgo Aéreo.\nRecurso de Héroe: agota el Casco de Supernova → genera un recurso [wild].","f":"\"El casco oye lo que pienso, y eso hace que haga cosas.\" —Sam Alexander"},
  "28010": {"n":"Langosta","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Campeón.\nRespuesta de Héroe: después de que la Langosta entre en juego, coge 1 Evento de Agresividad (rojo) de tu pila de descartes y añádelo a tu mano."},
  "28011": {"n":"A por ellos","t":"Respuesta (intervención): después de que tu Héroe ataque y derrote a un enemigo, quita 2 de Amenaza de un Plan.","f":"\"Kamala, no tenemos banda sonora propia. Deja ya de tatarear...\" —Capitana Marvel"},
  "28012": {"n":"Viraje agresivo","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Aéreo.\nRespuesta de Héroe (ataque): después de que tu Héroe ataque, inflige 4 de Daño a un enemigo."},
  "28013": {"n":"Sin cuartel","t":"Requisito ([physical]).\nAcción de Héroe (ataque): inflige 4 de Daño a un enemigo. Por cada punto de Daño sobrante infligido a ese enemigo mediante este ataque, descarta la primera carta de la parte superior de tu mazo y añade a tu mano todas las cartas de Agresividad (rojas) que se descarten de este modo."},
  "28014": {"n":"Uno por uno","t":"Acción de Héroe (ataque): inflige 2 de Daño a un enemigo. Si este ataque derrota a ese enemigo, inflige 2 de Daño a un enemigo.","f":"\"Tengo muchos más trucos en la manga, damas y caballeros.\" —Moon Girl"},
  "28015": {"n":"El poder de la agresividad","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta de Agresividad (roja)."},
  "28016": {"n":"Movimiento fluido","t":"Respuesta de Héroe: después de que juegues un Evento Ataque, agota esta carta → tu Héroe recibe +1 ATQ hasta el final de la fase. (Máximo de 1 por Evento Ataque)."},
  "28017": {"n":"Técnica depurada","t":"Requisito ([mental][mental]). Máximo de 1 por jugador.\nInterrupción: cuando juegues un Evento Ataque de Agresividad, si has pagado su coste usando un recurso [mental], la cantidad de Daño que inflija ese Evento aumenta en tantos puntos como su coste impreso."},
  "28018": {"t":"Juega esta carta sólo si tu Superhéroe tiene los rasgos Campeón o Genio.\nRespuesta: después de que juegues a Moon Girl desde tu mano, roba 1 carta por cada recurso [mental] que hayas usado para pagar su coste."},
  "28019": {"n":"Héroe sin capa","t":"Mientras tu Superhéroe tenga el rasgo Civil, esta carta podrá gastarse en beneficio de cualquier jugador y gana este texto de reglas: \"Respuesta: después de que gastes esta carta en beneficio de un jugador, cura 1 de Daño al Superhéroe de ese jugador.\"."},
  "28020": {"n":"Búnker móvil de los Campeones","t":"Acción de Héroe: agota el Búnker móvil de los Campeones → elige un Superhéroe que tenga el rasgo Campeón. El jugador que controle ese Superhéroe puede robar 2 cartas, luego descarta 2 cartas de su mano."},
  "28021": {"n":"El peso del mundo","t":"Dale esta carta al jugador que lleva a Sam Alexander\nMientras esta carta esté en juego, el Casco de Supernova no podrá prepararse.\nAcción de Alter ego: agota a Sam Alexander → retira de la partida El peso del mundo."},
  "28022": {"n":"\"¡Que comience la guerra!\"","t":"Cuando se muestre esta carta: cada jugador descarta 1 carta que controle y que tenga un recurso [wild] impreso. Por cada carta que se haya descartado de este modo, coloca 1 de Amenaza sobre esta carta."},
  "28023": {"n":"Emprendeguerras","t":"[star] Interrupción obligada: cuando Emprendeguerras te ataque, recibe +1 ATQ para ese ataque por cada carta de tu mano que tenga impreso un recurso [wild]. Ese ataque gana Brutalidad.\n(Esbirro Archienemigo de Nova.)"},
  "28024": {"n":"Belicismo","t":"Cuando se muestre esta carta: puedes gastar un recurso [wild]. Si no lo haces, el Villano y Emprendeguerras te atacan (incluso aunque tengas adoptada la identidad de tu Alter ego).\n[star] Aumento: Coloca 1 de Amenaza sobre el Plan principal por cada carta de tu mano que tenga impreso un recurso [wild]."},
  "28025": {"n":"\"La guerra ha comenzado\"","t":"Oleada.\nCuando se muestre esta carta: descarta X cartas de la parte superior del mazo de Encuentros, siendo X igual al número total de recursos [wild] impresos en las cartas que tengas en la mano, que controles y que estén en tu pila de descartes."},
  "28026": {"n":"Alabeo y guiñada","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Aéreo.\nRespuesta de Héroe (intervención): después de que tu Héroe intervenga, quita 3 de Amenaza de un Plan."},
  "28027": {"n":"Altitud ventajosa","t":"Mientras tu Superhéroe tenga el rasgo Aéreo, el Daño que sufras de cada ataque enemigo se reduce en 1.\nInterrupción obligada: cuando empiece tu turno, descarta esta carta."},
  "28028": {"n":"Asalto acorazado","t":"Todo enemigo que tenga una carta de Estado \"Duro\" recibe +3 ATQ.","f":"Armadillo atraviesa la ciudad como una apisonadora, arrollando todo lo que se interpone en su camino."},
  "28029": {"t":"Dureza.\nArmadillo puede tener cualquier cantidad de cartas de Estado \"Duro\".\n[star] Respuesta obligada: después de que Armadillo se active contra ti, dale una carta de Estado \"Duro\"."},
  "28030": {"n":"Bola rodante","t":"Vincula esta carta a Armadillo. Si Armadillo no está en juego, búscalo en el mazo de Encuentros y en su pila de descartes, ponlo en juego enfrentado a ti y vincúlale esta carta. (Baraja el mazo.)\n[star] Mientras Armadillo tenga una carta de Estado \"Duro\", ningún personaje podrá defender contra sus ataques."},
  "28031": {"n":"Juego duro","t":"Cuando se muestre esta carta (Alter ego): todo enemigo que tenga una carta de Estado \"Duro\" ejecuta el Plan. Si no se activa ningún enemigo de este modo, esta carta gana Oleada.\nCuando se muestre esta carta (Héroe): todo enemigo que tenga una carta de Estado \"Duro\" te ataca. Si no se activa ningún enemigo de este modo, esta carta gana Oleada."},
  "28032": {"n":"Aguantar el tipo","t":"Cuando se muestre esta carta: dale a Armadillo y al Villano sendas cartas de Estado \"Duro\". Si no se da más de 1 carta de Estado \"Duro\" de este modo, esta carta gana Oleada.","f":"\"No me pegues muy fuerte. Podrías romperte la mano.\" —Armadillo"},
  "29001a": {"t":"¡Subida de nivel! — Acción: quita 6 contadores de Progreso de Ironheart → prepárala e intercámbiala por la Versión 2 de Ironheart.","f":"\"Vale, probemos algo nuevo…\""},
  "29001b": {"t":"Empiezas la partida con esta carta. Aparta a un lado tus demás cartas de Superhéroe (ver hoja de reglas).\nJoven prodigio — Acción: gasta un recurso [mental] → coloca 1 contador de Progreso sobre Riri Williams. (Límite de una vez por ronda.)"},
  "29002a": {"t":"¡Subida de nivel! — Acción: quita 6 contadores de Progreso de Ironheart → prepárala, dale una carta de Estado \"Duro\" e intercámbiala por la Versión 3 de Ironheart.","f":"\"Me llamo Ironheart, tío.\""},
  "29002b": {"t":"Joven prodigio — Acción: gasta un recurso [mental] o bien 2 recursos de cualquier tipo → coloca 1 contador de Progreso sobre Riri Williams. (Límite de una vez por ronda.)","f":"\"Deja que termine esto y luego comeré y retozaré y lo que quieras.\""},
  "29003a": {"t":"Máxima eficacia — Acción de Héroe: quita 1 contador de Progreso de Ironheart → inflige 2 de Daño a un enemigo.","f":"\"Así que quieres jugar con el sonido, ¿eh, villano?\""},
  "29003b": {"t":"Joven prodigio — Acción: gasta 1 recurso de cualquier tipo → coloca 1 contador de Progreso sobre Riri Williams. (Límite de 1 vez por ronda.)","f":"\"Puedo construir algo más ligero, más rápido y más fuerte.\""},
  "29004": {"n":"Vigor","t":"Mientras Vigor esté agotado, gana: \"Recurso: genera un recurso [mental]. (Límite de una vez por fase.)\".","f":"\"No, yo no soy Banner. Soy mejor.\""},
  "29005": {"n":"Sobrevolar la zona","t":"Acción de Héroe (intervención): quita 3 de Amenaza de un Plan y coloca 1 contador de Progreso sobre Ironheart (2 contadores de Progreso si con esta intervención se quita la última ficha de Amenaza de ese Plan).","f":"¡VROOSSSH!"},
  "29006": {"n":"Rayo de fotones","t":"Acción de Héroe (ataque): inflige 4 de Daño a un enemigo y coloca 1 contador de Progreso sober Ironheart (2 contadores de Progreso si se derrota a ese enemigo con este ataque).","f":"¡¡FSHHAAMMM!!"},
  "29007": {"n":"Nueva y mejorada","t":"Acción de Héroe: elige X opciones distintas, siendo X igual al número de Versión de Ironheart.\n- Bsuca una carta de Ironheart en tu mazo y añádela a tu mano. (Baraja el mazo.)\n- Dale a Ironheart una carta de Estado \"Duro\".\n- Prepara a Ironheart."},
  "29008": {"n":"Escanear el sector","t":"El coste para jugar esta carta se reduce en X, siendo X igual al número de Versión de Ironheart.\nAcción de Héroe: hasta el final de la ronda, puedes mirar en cualquier momento la primera carta del mazo de Encuentros."},
  "29009": {"n":"Genialidad","t":"Respuesta: después de que gastes esta carta, coloca 1 contado de Progreso sobre tu Superhéroe y roba 1 carta."},
  "29010": {"t":"Acción de Alter ego: agota a Ronnie Williams → elige una opción:\n- Cura 2 de Daño a Riri Williams.\n- Coloca 1 contador de Progreso sobre Riri Williams."},
  "29011": {"n":"IA de Tony Stark","t":"Acción: agota la IA de Tony Stark → mira las 2 primeras cartas de la parte superior de tu mazo. Añade 1 a tu mano y descarta la otra.","f":"\"He cargado mi fabuloso yo en un marco digital por si alguna vez mi cuerpo… ya sabes, dejara de funcionar.\""},
  "29012": {"n":"Repulsores fotónicos","t":"Recibes +2 de Vida.\nAcción de Héroe: agota los Repulsores fotónicos → inflige tanto Daño a un enemigo como el número de Versión de Ironheart."},
  "29013": {"n":"Retropropulsores","t":"Recibes +2 de Vida.\nAcción de Héroe: agota los Retropropulsores → quita tanta Amenaza de un Plan como el número de Versión de Ironheart."},
  "29014": {"n":"Nube 9","t":"Acción de Héroe: agota a Nube 9 → elige un jugador. Hasta el final de la fase, todo personaje Aéreo controlado por ese jugador recibe +1 INT.","f":"\"¡Sólo estoy aquí porque quiero volar!\""},
  "29015": {"n":"Halcón","t":"Respuesta de Héroe: después de que el Halcón ataque o intervenga, gasta un recurso [energy] → prepara otro personaje Campeón que controles.","f":"\"Eh, esto, soy Joaquín. He venido a rescatarte… y, eh, bien, ¿no?\""},
  "29016": {"n":"Patriota","t":"Respuesta de Héroe: después de que Patriota entre en juego, elige un personaje Campeón → ese personaje recibe +1 a todos sus atributos básicos hasta el final de la ronda.","f":"\"Estoy rodeado de gente que se juega la vida por unos principios que la mayoría da por hechos.\""},
  "29017": {"n":"Atacar con todo","t":"Requisito ([energy]).\nAcción de Héroe (ataque): agota tu Héroe → inflige tanto Daño a un enemigo como la suma total de tus puntuaciones de INT, ATQ y DEF."},
  "29018": {"n":"Emplearse a fondo","t":"Requisito ([mental]).\nAcción de Héroe (intervención): agota tu Héroe → quita tanta Amenaza de un Plan como la suma total de tus puntuaciones de INT, ATQ y DEF."},
  "29019": {"n":"Moral elevada","t":"Acción de Héroe: elige un Héroe. Hasta el final de la ronda, ese Héroe recibe +1 INT, +1 ATQ, y +1 DEF.","f":"\"Es una posición que tengo que tomar. Esta vez, sin concesiones.\" —Sam Wilson"},
  "29020": {"n":"Centro de I+D","t":"Requisito ([mental][mental]). Usos (3 contadores de Investigación).\nAcción de Héroe: agota el Centro de I+D y quítale 1 contador de Investigación → elige un personaje amigo que esté en juego. Ese personaje recibe +1 INT y +1 ATQ hasta el final de la fase."},
  "29021": {"n":"El poder del liderazgo","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta de Liderazgo (azul)."},
  "29022": {"n":"Agente 13","t":"[star] Respuesta: después de que la Agente 13 ataque o intervenga, elige un Apoyo S.H.I.E.L.D. → prepara ese Apoyo.","f":"\"Llevo en todo mi cuerpo las cicatrices del pasado. Pero soy más que eso. Ahora soy la mejor. Más fuerte. Más sabia.\""},
  "29023": {"n":"Guardia Nevada","t":"Respuesta: después de que Guardia Nevada entre en juego, coloca hasta 3 contadores de Cambio sobre esta carta. Mientras haya (X) contadores de Cambio sobre esta carta, Guardia Nevada recibe:\n(1) +3 ATQ y sus ataques ganan Brutalidad.\n(2) +3 INT y gana el rasgo Aéreo.\n(3) +5 de Vida y gana Represalia 1."},
  "29024": {"t":"Respuesta de Héroe: después de que Vivian entre en juego, elige un Accesorio, un Esbirro que no sea de Élite o un Plan secundario que no sea Permanente. Hasta el final de la ronda, el texto de reglas impreso de esa carta se trata como si estuviese en blanco (a excepción de los Rasgos)."},
  "29025": {"n":"\"¡Adelante, Campeones!\"","t":"Máximo de 1 por mazo.\nJuega esta carta sólo si tu Superhéroe tiene el rasgo Campeón.\nAcción de Héroe: ningún personaje Campeón que esté en juego podrá sufrir Daño hasta el final de la ronda."},
  "29026": {"n":"Helitransporte","t":"Máximo de 1 por jugador.\nAcción: agota el Helitransporte → elige un jugador. Reduce en 1 el coste en recursos de la siguiente carta jugada por ese jugador en esta fase.","f":"\"¿Un portaaviones volador? Estás de guasa, ¿no?\" —Jennifer Walters"},
  "29027": {"n":"Inventiva","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Genio. Máximo de 1 por jugador.\nRecurso: agota Inventiva → genera un recurso [mental]."},
  "29028": {"n":"Un leve contratiempo","t":"Dale esta carta al jugador que lleva a Riri Williams.\nQuita 1 cotnador de Progreso de tu carta de Superhéroe, luego descarta esta carta. Si no se ha quitado ningún contador de Progreso de este modo, data a ti mismo 1 carta de Encuentro boca abajo, luego añade esta carta al mazo de Encuentros y barájalo."},
  "29029": {"n":"Gobernar por la fuerza","t":"Mientras Lucia von Bardas esté en juego, esta carta gana un icono de Riesgo.\nMientras Lucia von Bardas no esté en juego, esta carta gana un icono de Aceleración.","f":"Lucia von Bardas ha tomado el control de Latveria y no se detendrá ante nada con tal de dejar patente el poderío de esta nación."},
  "29030": {"t":"Mientras Lucia von Bardas tenga una carta de Estado \"Duro\", recibe +1 PLA y +1 ATQ.\nRespuesta obligada: después de que termine la fase del Villano, dale a Lucia von Bardas una carta de Estado \"Duro\".\n(Esbirro Archienemigo de Ironheart.)"},
  "29031": {"n":"Tecnología cíborg","t":"Vincula esta carta al Esbirro que tenga más Rasgos. Si no es posible, esta carta gana Oleada.\nEl Esbirro vinculado recibe +3 de Vida y gana Represalia 1.\n[star] Aumento: Quédate esta carta como carta de Encuentro boca abajo."},
  "29032": {"n":"Represalia política","t":"Cuando se muestre esta carta: si Lucia von Bardas está en juego, ejecuta el Plan. Si Gobernar por la fuerza está en juego, colócale encima 3 de Amenaza. Si ninguna de las dos cartas está en juego, esta carta gana Oleada.","f":"\"Os felicito por vuestra perseverancia y patriotismo. Se supone que la mayoría deberíais estar muertos a estas alturas.\""},
  "29033": {"n":"Bomba","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Campeón.\n[star] El Daño infligido por el ataque de Bomba se reparte entre todos los enemigos lo más equitativamente posible."},
  "29034": {"n":"Avispa","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Campeón.\nLa Avispa ignora el icono de Crisis ([crisis]) y las palabras clave Guardia y Patrulla.","f":"\"¡Primero tendrás que encontrarme!\""},
  "29035": {"n":"Precisión","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Campeón.\nInterrupción de Héroe: cuando una carta de Jugador que esté en juego vaya a colocarse en la pila de descartes, agota a Precisión → en vez de eso, devuelve esa carta al mazo de su propietario y barájalo."},
  "29036": {"n":"Bucle de retroalimentación","t":"Cuando se muestre esta carta: cada jugador debe colocar tanta Amenaza sobre esta carta como el número total de recursos [energy] que haya en las cartas de su mano y en las cartas que controle.","f":"¡Zzzax controla el suministro eléctrico de la ciudad y está sembrando el caos en el sistema!"},
  "29037": {"t":"[star] Zzzax recibe +X ATQ y +X de Vida, siendo X igual al número total de recursos [energy] que haya en las cartas controladas por el jugador enfrentado.\n[star] Aumento: Si tienes al menos [energy][energy] entre los recursos de las cartas de tu mano, pon en juego a Zzzax enfrentado a ti."},
  "29038": {"n":"Cables cruzados","t":"Vincula esta carta a tu carta de Superhéroe.\nTrata el recurso impreso de cada carta que tengas en tu mano como si fuera [energy].\nAcción de Héroe: elige entre descartar una carta que controles y que tenga impreso un recurso [energy] o bien sufrir 2 de Daño indirecto → descarta esta carta."},
  "29039": {"n":"Electricidad estática","t":"Interrupción obligada: cuando empiece la fase del Villano, inflige 2 de Daño indirecto a cada jugador que tenga un recurso [energy] en su mano o en una carta que controle.\nAcción de Héroe: elige entre descartar una carta que controles y que tenga impreso un recurso [energy] o bien sufrir 2 de Daño indirecto → descarta esta carta."},
  "29040": {"n":"¡Zzzap!","t":"Cuando se muestre esta carta: sufres tanto Daño indirecto como el número total de recursos [energy] que tengas en tu mano. Si se ha infligido como máximo 1 de Daño a tu Superhéroe de este modo, esta carta gana Oleada.","f":"\"¡Yo Zzzax! ¡Tú zzzap!\""},
  "30001a": {"n":"Spiderham","t":"Cada contador de Dibujo animado que haya sobre Spiderham puede gastarse como si fuera un recurso [wild].\nSinsentido arácnido — Respuesta: después de que Spiderham sufra cualquier cantidad de Daño, colócale encima 1 contador de Dibujo animado."},
  "30001b": {"t":"Poder de dibujo animado — Respuesta: después de que realices una recuperación básica, coloca 1 contador de Dibujo animado sobre Peter Porker.","f":"\"¿Alguna vez te has sentido como si te estuvieran controlando, como si no fueras más que un personaje en un videojuego?\""},
  "30002": {"n":"Gaticán América","t":"Respuesta: después de que el Gaticán América entre en juego, saluda a alguien con un \"¡choca esos cinco!\". Coloca 1 contador de Dibujo animado sobre tu Superhéroe, coge 1 carta de Spiderham de tu pila de descartes, añádela a tu mazo y barájalo.","f":"\"¡Daré mis siete vidas por la libertad y la justicia!\""},
  "30003": {"n":"Marranazo","t":"Acción de Héroe (intervención): quita 1 de Amenaza de un Plan por cada contador de Dibujo animado que haya sobre Spiderham.","f":"\"Te va a extrañar… ¡pero los cerdos pueden volar!\" —Spiderham"},
  "30004": {"n":"Manitas de cerdo","t":"Acción de Héroe: quítale 1 contador de Dibujo animado a Spiderham → lee en voz alta el texto de ambientación de esta carta. Elige entre infligir 5 de Daño a un Esbirro o quitar 5 de Amenaza de un Plan secundario.","f":"¡PUM! ¡PAM! ¡ZASCA! ¡ZUMBA! ¡CATACROC!"},
  "30005": {"n":"\"¡De eso nada!\"","t":"Interrupción de Héroe: cuando muestres una carta del mazo de Encuentros, quítale 1 contador de Dibujo animado a Spiderham → exclama \"¡De eso nada!\" imitando a Spiderham. Anula los efectos de esa carta y descártala."},
  "30006": {"n":"Puerco petulante","t":"Acción de Héroe: sácale la lengua al Villano. El Villano te ataca. Roba 3 cartas.","f":"\"BLEBLEBLEBLEBLE!\" —Spiderham"},
  "30007": {"n":"Telaraña cochina","t":"Acción de Héroe (ataque): inflige 6 de Daño a un enemigo. Confunde a ese enemigo.","f":"\"¿Soy un cerdo con la fuerza y agilidad proporcionales de una araña? ¿O una araña con las limitaciones físicas de un cerdo?\" —Peter Porker"},
  "30008": {"n":"El Daily Beagle","t":"Acción de Alter ego: agota El Daily Beagle → coloca 1 contador de Dibujo animado sobre Peter Porker.","f":"\"¡Soy J. Jonah Chacal, transmitiendo una tremebunda tertulia televisiva sobre ese tarado teatrero del trepamuros!\" —J. Jonah Chacal"},
  "30009": {"n":"Física de dibujos animados","t":"Interrupción: cuando tu Superhéroe vaya a sufrir cualquier cantidad de Daño, descarta esta carta → menea el cuerpo y evita todo ese Daño menos 1.","f":"\"Apenas lo he notado…\" —Spiderham"},
  "30010": {"n":"Mazo de madera enorme","t":"Spiderham recibe +1 ATQ.\nInterrupción de Héroe: cuando Spiderham realice un ataque básico, agota el Mazo de madera enorme y quítale 1 contador de Dibujo animado a Spiderham → Spiderham recibe +2 ATQ para ese ataque. Ese ataque gana Brutalidad."},
  "30011": {"n":"Lanzarredes orgánicos","t":"Spiderham recibe +1 INT.\nAcción de Héroe: agota los Lanzarredes orgánicos y quítale 1 contador de Dibujo animado a Spiderham → prepara a Spiderham. Gana el rasgo Aéreo hasta el final de la fase."},
  "30012": {"t":"[star] Respuesta: después de que Lady Spider intervenga y quite Amenaza de un Plan, si controlas otra carta Guerrero Araña, quita esa misma cantidad de Amenaza de un Plan diferente.","f":"\"Que nadie te encierre.\""},
  "30013": {"n":"Spiderman","t":"Respuesta: después de que Spiderman entre en juego, quita 1 de Amenaza de un Plan por cada carta Guerrero Araña que controles (incluido Spiderman).","f":"\"Villanos de dibujos del futuro de Ham. Y ahora robots gigantes. Mundos diferentes de la Red que se están enredando.\""},
  "30014": {"n":"Igualar las posibilidades","t":"Requisito ([energy]).\nAcción de Héroe (intervención): quita 1[per_hero] de Amenaza de cada Plan secundario. Inflige 1 de Daño al Villano por cada Plan secundario que se haya derrotado de este modo."},
  "30015": {"n":"Una gran responsabilidad","t":"Interrupción de Héroe: cuando vaya a colocarse cualquier cantidad de Amenaza sobre un Plan, en vez de eso tú sufres esa misma cantidad de Daño."},
  "30016": {"n":"Entrada espectacular","t":"Interrupción de Héroe: cuando tu Héroe realice una intervención básica, recibe +2 INT para esa intervención. Después de que termine esa intervención, si tu Héroe ha quitado toda la Amenaza de un Plan gracias a ella, cura 2 de Daño a tu Héroe."},
  "30017": {"n":"De un modo u otro","t":"Máximo de 1 por ronda.\nAcción de Héroe: busca un Plan secundario en el mazo de Encuentros. Muestra ese Plan secundario → roba 3 cartas. (Baraja el mazo de Encuentros.)"},
  "30018": {"n":"Seguimiento","t":"Vincula esta carta a un Plan. Máximo de 1 por Plan.\nRespuesta: cuando se derrote el Plan vinculado, inflige 4 de Daño a un enemigo."},
  "30019": {"n":"Vigilar de cerca","t":"Vincula esta carta a un Plan. Máximo de 1 por Plan.\nInterrupción de Héroe: cuando se quite cualquier cantidad de Amenaza del Plan vinculado mediante una intervención, descarta esta carta → quita esa misma cantidad de Amenaza de un Plan diferente."},
  "30020": {"n":"Araña Escarlata","t":"Juega esta carta sólo si controlas una carta Guerrero Araña.\nInterrupción: cuando vayas a mostrar una carta de Encuentro, nombra un tipo de carta y luego mira la que vas a mostrar. Si la carta es del tipo que has nombrado, inflige 1 de Daño a la Araña Escarlata y roba 1 carta."},
  "30021": {"t":"Juega esta carta sólo si controlas una carta Guerrero Araña.\nCuando se derrote esta carta: añade SP//dr a tu mano si ha sido derrotada con Daño derivado sobrante."},
  "30022": {"n":"Espíritu de equipo","t":"Acción de Héroe: agota Espíritu de equipo → juega una carta de tu mano que tenga un rasgo en común con tu Héroe, reduciendo en 1 su coste en recursos."},
  "30023": {"n":"La Red de la Vida y el Destino","t":"Ignora el coste en recursos de esta carta si tu Superhéroe tiene el rasgo Guerrero Araña.\nRespuesta: después de que un Aliado Guerrero Araña abandone el juego, elige a un jugador → ese jugador roba 1 carta."},
  "30024": {"n":"\"¡Quiero un perrito caliente!\"","t":"Dale esta carta al jugador que lleva a Peter Porker.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n• Agota a Peter Porker y quítale 1 contador de Dibujo animado → retira de la partida \"¡Quiero un perrito caliente!\".\n• Qudas aturdido. Si ya estabas aturdido, esta carta gana Oleada. Descarta esta Obligación."},
  "30025": {"n":"Trampa maliciosa","t":"Cuando se derrote esta carta: el Pavo Verde ataca al jugador que haya derrotado este Plan. Si el Pavo Verde no está en juego, búscalo´en el mazo de Encuentros y en su pila de descartes y ponlo en juego enfrentado al jugador que haya derrotado este Plan."},
  "30026": {"n":"Pavo Verde","t":"Respuesta obligada: después de que el Pavo Verde se enfrente a ti, descarta todos los contadores de todas las cartas que controles.\n(Esbirro Archienemigo de Spiderham.)","f":"\"¡Emplearé todos los medios necesarios para triunfar, aunque me vaya el plumaje en ello.\" —El Pavo Verde"},
  "30027": {"n":"Pavoneador","t":"Oleada.\nVincula esta carta al Pavo Verder. Si no es posible, vincula esta carta a un Esbirro.\nEl Esbirro vinculado gana el rasgo Aéreo.","f":"\"Cuando haya terminado contigo, no quedará de ti ni para hacer embutido.\" —El Pavo Verde"},
  "30028": {"n":"\"¡Cómete esto!\"","t":"Cuando se muestre esta carta: sufres 2 de Daño. Quedas confundido. Si ya estabas confundido, esta carta gana Oleada.","f":"\"¡Come calabaza hasta que REVIENTES!\" —El Pavo Verde"},
  "30029": {"n":"Guerrero de la Gran Red","t":"Vincula esta carta a un personaje cuyo nombre contenga las palabras \"Spider\" o \"Araña\". Máximo de 1 por personaje.\nEl personaje vinculado gana el rasgo Guerrero Araña.\nRespuesta: después de que un Aliado Guerrero Araña abandone el juego, el personaje vinculado recibe +1 ATQ hasta el final de la fase."},
  "30030": {"n":"Cacería de tótems araña","t":"Interrupción obligada: cuando empiece la fase del Villano, descarta las 3 primeras cartas del mazo de Encuentros. Cada Esbirro Heredero descartado de este modo se pone en juego enfrentado a un jugador que controle un Personaje Guerrero Araña, si es posible. De no ser así, cada Esbirro Heredero descartado de este modo se pone en juego enfrentado al jugador inicial.","f":"\"No hay 'misión'. Esto es lo que hacen los míos. Matamos arañas. Es nuestra vida.\" —Karn"},
  "30031": {"t":"Cada Esbirro Heredero gana 1 icono de Aceleración ([acceleration]).\nCuando se muestre esta carta: si hay en juego algún Personaje Guerrero Araña, coloca 1 de Amenaza sobre cada Plan.","f":"\"¡Queridos hermanos, démonos un festín con ellos!\""},
  "30032": {"t":"Cada Esbirro Heredero gana Patrulla.\nCuando se muestre esta carta: si hay en juego algún Personaje Guerrero Araña, coloca 2 de Amenaza sobre el Plan principal.","f":"\"En un alarde de ironía, la Red de la Vida y el Destino nos ha guiado hasta este preciso momento. El momento de tu muerte.\""},
  "30033": {"t":"Cada Esbirro Heredero gana Firmeza.\nCuando se muestre esta carta: si hay en juego algún Personaje Guerrero Araña, aturde a un personaje que controles.","f":"\"Soy Daemos, hijo de Solus. Uno de los herederos de toda la creación. Y tú… eres una mota. Una pizca. Polvo al viento.\""},
  "30034": {"t":"Cada Esbirro Heredero gana Guardia.\nCuando se muestre esta carta: si hay en juego algún Personaje Guerrero Araña, dale a Jennix una carta de Estado \"Duro\".","f":"\"PRefiero que se resistan. Me encanta el sabor de la adrenalina.\""},
  "30035": {"t":"Todos los ataques de Esbirros Heredero ganan Brutalidad y Penetrante.\nCuando se muestre esta carta: si hay en juego algún Personaje Guerrero Araña, descarta una Mejora o Apoyo que controles.","f":"\"Me saciaré contigo.\""},
  "30036": {"t":"Cada Esbirro Heredero recibe +1 ATQ.\nCuando se muestre esta carta: si hay en juego algún Personaje Guerrero Araña, sufres 2 de Daño.","f":"\"Hum. Nunca había rpobado una fuerza vital tan dulce.\""},
  "30037": {"t":"Cada Esbirro Heredero gana Infame.\nCuando se muestre esta carta: si hay en juego algún Personaje Guerrero Araña, dale a Solus 1 carta de aumento boca abajo.","f":"\"Soy Solus, heraldo de la muerte de todos vosotros.\""},
  "30038": {"t":"Cada Esbirro Heredero gana Represalia 1.\nCuando se muestre esta carta: si hay en juego algún Personaje Guerrero Araña, inflige 1 de Daño a cada Personaje que controles.","f":"\"¡Me comeré tus huesos!\""},
  "31001a": {"n":"Robot SP//dr","t":"Tasa de sincronización — Recurso: agota una Mejora Interfaz que controles → genera los recursos de esa Mejora.","f":"\"Nos llaman SP//dr, y protegemos la ciudad.\""},
  "31001b": {"n":"Robot SP//dr","t":"Permanente. El texto de reglas impreso de esta carta no puede tratarse como si estuviera en blanco.\nRegresar a la base — Interrupción obligada: cuando pongas estar cara boca arriba, dale la vuelta a SP//dr para poner a Peni Parker boca arriba. Desvincula a Peni Parker de esta carta; todos los contadores y cartas vinculadas que tuviera Peni Parker se trasladan a esta carta."},
  "31003": {"t":"[star] VEN#m recibe +1 INT y +1 ATQ por cada contador de Sym que tenga encima.\nRespuesta de Héroe: después de que VEN#m entre en juego, colócale encima 1 contador de Sym por cada recurso que generase la capacidad \"Tasa de sincronización\" del Robot SP//dr a fin de pagar el coste de VEN#m."},
  "31004": {"n":"¡Todos los sistemas operativos!","t":"Acción de Héroe: elige una opción:\n- Prepara todas las Mejoras Interfaz que controles.\n- Busca una Mejora Interfaz en tu mazo y tu pila de descartes, y añádela a tu mano. (Baraja el mazo.)"},
  "31005": {"n":"Despliegue rápido","t":"Acción de Héroe (intervención): quita 3 de Amenaza de un Plan. Si has pagado el coste de esta carta usando un recurso generado por la capacidad \"Tasa de sincronización\" del Robot SP//dr, quita 3 de Amenaza de un Plan.","f":"\"Protegeremos esta ciudad cueste lo que cueste.\" —SP//dr"},
  "31006": {"n":"Trampa de red","t":"Acción de Héroe (ataque): inflige 5 de Daño a un enemigo. Si has pagado el coste de esta carta usando un recurso generado por la capacidad \"Tasa de sincronización\" del Robot SP//dr, aturde a ese enemigo.","f":"\"May siempre quiso que SP//dr fuera mejor, que fuera lo mejor posible. Por eso nos ayudó a desarrollar estas trampas de red.\""},
  "31007": {"n":"Tía May y tío Ben","t":"Acción: agota a Tía May y tío Ben y descarta las 2 primeras cartas de la parte superior de tu mazo (las 3 primeras cartas si tienes adopatada la identidad de tu Alter ego) → añade a tu mano todas las cartas específicas de SP//dr que hayas descartado de este modo."},
  "31008": {"n":"Protocolo de eyección","t":"Acción de Héroe: descarta el Protocolo de eyección → agota todas las Mejoras Interfaz que controles, fija tu medidor de Vida en 6, dale a tu Superhéroe una carta de Estado \"Duro\" y cambia a la identidad de tu Alter ego.","f":"\"¡Alerta! ¡Amenaza inminente!\""},
  "31009": {"n":"Centro de mando de SP//dr","t":"Acción de Héroe: agota el Centro de mando de SP//dr y una mejora Interfaz → roba 1 carta.\nAcción de Héroe: agota el Centro de mando de SP//dr, elige 1 carta de tu mano y descártala → prepara una Mejora Interfaz.","f":"\"Peni, sigue nuestras órdenes cuidadosamente.\""},
  "31010": {"n":"Araña de enlace","t":"Acción de Héroe: agota la Araña de enlace → prepara el Robot SP//dr.","f":"\"Ella confía en vosotros. Yo también.\" —Peni Parker"},
  "31011": {"n":"Enlace psíquico","t":"Interrupción de Héroe: cuando el Robot SP//dr realice una intervención básica, agota el Enlace psíquico → recibe +2 INT para esa intervención.","f":"\"¿Podemos escuchar música? Nos ayuda a concentrarnos.\" —Peni Parker"},
  "31012": {"n":"Aleación de speed-metal","t":"Interrupción de Héroe: cuando el Robot SP//dr defienda contra un ataque, agota Aleación de speed-metal → el Robot SP//dr recibe +2 DEF para esa defensa.","f":"\"Creí que dijiste que ra un traje. ¡Esto es speed-metal!\" —Spiderham"},
  "31013": {"n":"Compresor de fluido arácnido","t":"Interrupción de Héroe: cuando el Robot SP//dr realice un ataque básico, agota el Compresor de fluido arácnido → el Robot SP//dr recibe +2 ATQ para ese ataque.","f":"\"El progreso exige paciencia. Por eso tenemos que seguir mejorándolas.\" —Tía May"},
  "31014": {"t":"Respuesta: después de que Daredevil defienda contra un ataque, traslada 1 de Daño desde su carta hasta la del enemigo atacante.","f":"\"El silencio se rompe, se deshace, así que la ciudad se estira. Escucha… esperando… Otra estación para una señal, y todos somos algún tipo de ruido. Sé del tipo bueno, Peni.\""},
  "31015": {"n":"Spiderman Noir","t":"X es igual al número de cartas vinculadas boca abajo a Spiderman Noir.\nRespuesta: después de que resuelvas una carta de Perfidia, si controlas otra carta Guerrero Araña, vincula esa carta de Perfidia boca abajo a Spiderman Noir (hasta un máximo de 3 cartas)."},
  "31016": {"n":"Readaptación","t":"Acción de Héroe: descarta una Mejora Tecnología que controles → prepara tu Héroe y elige entre INT, ATQ o DEF. Hasta el final de la ronda, tu Héroe recibe +X en el atributo elegido, siendo X igual al coste impreso de esa Mejora."},
  "31017": {"n":"¡Thwip, thwip!","t":"Acción de Héroe: inflige 1 de Daño a un personaje Guerrero Araña que controles → coloca un total de 2 cartas de Estado \"Aturdido\" sobre un máximo de 2 enemigos.","f":"\"Así tendréis toda la tarde para replantearos qué hacer con vuestras vidad. De nada.\" —Spiderman"},
  "31018": {"n":"Barrera de energía","t":"Usos (3 contadores de Reflejo).\nInterrupción: cuando vayas a sufrir cualquier cantidad de Daño, quita 1 contador de Reflejo de esta carta → evita 1 de ese Daño e inflige 1 de Daño a un enemigo."},
  "31019": {"n":"Generador de campo de fuerza","t":"Usos (6 contadores de Energía). Máximo de 1 por jugador.\nInterrupción obligada: cuando vayas a sufrir cualquier cantidad de Daño, quita ese mismo número de contadores de Energía de esta carta. Por cada contador de Energía que se quite de este modo, se evita 1 de ese Daño."},
  "31020": {"n":"Zumbido arácnido","t":"Interrupción: cuando vayas a mostrar una carta de Encuentro, inflige 1 de Daño a un personaje Guerrero Araña que controles → si la carta es de Perfidia, anula sus efectos de \"Cuando se muestre esta carta\" y descarta el Zumbido arácnido."},
  "31021": {"n":"Spiderham","t":"Juega esta carta sólo si controlas una carta Guerrero Araña.\n[star] Respuesta obligada: después de que Spiderham ataque o intervenga, descarta la primera carta del mazo de Encuentros. Por cada icono de Aumento ([boost]) descartado de este modo, inflige 1 de Daño a Spiderham."},
  "31022": {"n":"Spiderman","t":"Juega esta carta sólo si controlas una carta Guerrero Araña.\nRespuesta: después de que juegues a Spiderman desde tu mano, prepara una Mejora que controles. Si esa Mejora tiene el rasgo Tecnología, roba 1 carta."},
  "31023": {"n":"Aguante ilimitado","t":"Juega esta carta sólo si tu Superhéroe tiene una Vida impresa mínima de 14.\nAcción de Héroe: prepara tu Héroe.","f":"\"¿Qué pasa, te crees que la pelea se ha acabado? Eso sólo ha sido el calentamiento.\" —Thor"},
  "31024": {"n":"Inquebrantable","t":"Juega esta carta sólo si tu Superhéroe tiene una Vida impresa mínima de 14.\nTu Superhéroe gana Tesón."},
  "31025": {"n":"Legado abrumador","t":"Dale esta carta al jugador que lleva a Peni Parker.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n• Agota a Peni Parker → retira de la partida Legado abrumador.\n• Elige 1 Mejora Interfaz que controles y descártala. Descarta esta Obligación."},
  "31026": {"n":"Ataque de monstruo gigante","t":"Como coste adicional para intervenir contra este Plan, debes gastar un recurso [energy].","f":"M.O.R.B.I.U.S. está atacando la ciudad, sembrando la destrucción y absorbiendo la energía de su red eléctrica."},
  "31027": {"t":"Respuesta obligada: después de que el Héroe enfrentado genere cualquier cantidad de recursos, inflige esa misma cantidad de Daño a ese Héroe.\n(Esbirro Archienemigo de SP//dr.)","f":"\"¡Esta amenaza no se parece a ninguna contra la que te hayas enfrentado!\" —Uncle Ben"},
  "31028": {"n":"Drenaje de energía","t":"Cuando se muestre esta carta (Alter ego): elige entre gastar recursos [energy][energy] o agotar tu carta de Superhéroe.\nCuando se muestre esta carta (Héroe): elige entre gastar recursos [energy][energy] o sufrir 3 de Daño."},
  "31029": {"n":"Propósito claro","t":"Vincula esta carta a un personaje amigo. Máximo de 1 por personaje.\nRecurso de Héroe: agota esta carta e inflige 1 de Daño al personaje vinculado → genera un recurso [wild]."},
  "31030": {"n":"Robo a gran escala","t":"No puede quitarse Amenaza de este Plan mientras haya en juego un Esbirro Criminal.","f":"Los Seis Siniestros de Iron Spider están perpetrando una oleada de robos en todos los establecimientos que encuentran a su paso."},
  "31031": {"n":"Bomba","t":"[star] El Daño causdao por el ataque de Bomba se reparte lo más equitativamente posible entre todos los personajes controlados por el jugador atacado.\n[star] Aumento: Inflige 1 de Daño indirecto a cada jugador. Agota a todos los personajes que hayan resultado dañados de este modo."},
  "31032": {"t":"[star] Electro recibe +1 de Vida por cada recurso [energy] que tenga vinculado.\n[star] Respuesta obligada: después de que Electro se enfrente a ti o se active contra ti, elige 1 carta de tu mano que tenga impreso un recurso [energy] y vincúlaselo."},
  "31033": {"n":"Duende","t":"[star] Interrupción obligada: cuando el Duende vaya a atacarte, en vez de eso, descarta tantas cartas de la parte superior del mazo de Encuentros como la puntuación de ATQ del Duende. Sufres 1 de Daño indirecto por cada icono de Aumento ([boost]) descartado de este modo."},
  "31034": {"t":"Guardia. Patrulla. Represalia 1. Dureza.\n[star] Los ataques de Iron Spider ganan Brutalidad.","f":"\"No me obligues a darte una paliza.\""},
  "31035": {"n":"Hombre de Arena","t":"Respuesta obligada: después de que el Hombre de Arena sufra cualquier cantidad de Daño a consecuencia de un ataque, descarta las 7 primeras cartas del mazo de Encuentros.\n[star] Aumento: Descarta las 7 primeras cartas del mazo de Encuentros."},
  "31036": {"n":"Mancha","t":"Cuando se derrote esta carta: si Mancha ha sido derrotado sin Daño sobrante, añádelo al mazo de Encuentros y barájalo.\n[star] Aumento: Pon en juego este Esbirro enfrentado a ti."},
  "31037": {"n":"Oleada de crímenes","t":"Oleada.\nCada Esbirro Criminal gana Oleada.\nAcción de Héroe: si no hay ningún Esbirro Criminal en juego, gasta 2 recursos de cualquier tipo → descarta esta carta."},
  "32001a": {"n":"Coloso","t":"Coloso puede tener 1 carta de Estado \"Duro\" adicional.\nPiel de acero - Respuesta: después de que cambies a esta identidad, dale a Coloso una carta de Estado \"Duro\"."},
  "32001b": {"t":"Preparación: busca en tu mazo una copia de Acero orgánico y añádela a tu mano.\nArtista en ciernes - Respuesta: después de que cambies a esta identidad, coge 1 carta de Coloso que esté en tu pila de descartes, añádela a tu mazo y barájalo."},
  "32002": {"n":"Gatasombra","t":"Gatasombra ignora las palabras clave Guardia y Patrulla, así como los iconos de Crisis ([crisis]) que haya en juego.","f":"\"¡Peter, grandísimo bobo! ¡Lo que está hecho de metal es tu cuerpo, no tu cerebro!\""},
  "32003": {"n":"Estudio de Piotr","t":"Acción de Alter ego: agota el Estudio de Piotr → descarta cartas de tu mazo hasta que descartes una carta de Coloso. Añade esa carta a tu mano.","f":"\"Bajo esa piel de acero late el corazón de un artista que prefiere pintar a pelear\""},
  "32004": {"n":"Voluntad Férrea","t":"Coloso recibe +1 INT.\nRespuesta: después de que se descarte una carta de Estado \"Duro\" de Coloso, roba 1 carta.","f":"\"La voluntad de Petey es tan fuerte como su piel blindada. No se rinde nunca.\" —Lobezno"},
  "32005": {"n":"Músculos de titanio","t":"Coloso recibe +1 ATQ.\nRecurso de Héroe: agota esta carta → genera un recurso [physical] por cada carta de Estado \"Duro\" que tenga Coloso."},
  "32006": {"n":"Acero orgánico","t":"Usos (2 contadores de Acero).\nRespuesta de Héroe: después de que se descarte una carta de Estado \"Duro\" de Coloso, agota esta carta y quítale 1 contador de Acero → dale a Coloso una carta de Estado \"Duro\"."},
  "32007": {"n":"Hecho de rabia","t":"Interrupción de Héroe: cuando realices un ataque básico, descarta una carta de Estado \"Duro\" de tu Héroe → recibes +6 ATQ para ese ataque. Ese ataque gana Brutalidad.","f":"\"¡¡Aaarrrrrrhhhhhh!!\" —Coloso"},
  "32008": {"n":"Puño de acero","t":"Acción de Héroe (ataque): inflige 5 de Daño a un enemigo. Puedes descartar una carta de Estado \"Duro\" de tu Héroe → aturde y confunde a ese enemigo.","f":"\"Entonces, camaradas.. ¡terminemos esta batalla de una vez por todas!\" —Coloso"},
  "32009": {"n":"Protector a prueba de balas","t":"Acción de Héroe: descarta una carta de Estado \"Duro\" de tu Héroe → elige una opción:\n• Dale a tu Héroe 2 cartas de Estado \"Duro\".\n• Prepara tu Héroe."},
  "32010": {"n":"Acorazarse","t":"Interrupción de Alter ego: cuando el Villano se active, cambia a tu identidad de Héroe.","f":"\"Has jugado conmigo, cuando deberías haberme matado. Y me has dado tiempo para convertirme de Piotr Rasputin..¡en Coloso!\" —Coloso"},
  "32011": {"n":"Rondador Nocturno","t":"Interrupción: cuando un personaje PATRULLA-X vaya a sufrir cualquier cantidad de Daño a causa de un ataque enemigo, gasta un recurso [energy] y devuelve a Rondador Nocturno a tu mano → evita todo ese Daño."},
  "32012": {"t":"Respuesta: después de que Polaris entre en juego, dale una carta de Estado \"Duro\" a un personaje PATRULLA-X."},
  "32013": {"n":"Entrenamiento de protección","t":"Vincula esta carta a un Aliado PATRULLA-X. Máxima de 1 Mejora ENTRENAMIENTO por Aliado.\nEl Aliado vinculado recibe +3 de Vida."},
  "32014": {"n":"Puñetazo potente","t":"Interrupción de Héroe (ataque/defensa): cuando un enemigo inicie un ataque, inflige 4 de Daño a ese enemigo.","f":"\"¿Te apetece un poco de jarabe de palo?\" —Gatasombra"},
  "32015": {"n":"Maniobra engañosa","t":"Acción de Héroe (intervención): el Villano te ataca. Quita 4 de Amenaza del Plan principal.","f":"\"No te habrás creído que me ibas a engañar con eso, ¿verdad?\" —Spiderman"},
  "32016": {"n":"Perseverancia","t":"Respuesta de Héroe: después de que cambies de identidad, dale a tu Héroe una carta de Estado \"Duro\".","f":"\"Sabes que la puerta delantera no está cerrada con llave, ¿no?\" - Spiderman"},
  "32017": {"n":"Protectores mutantes","t":"Juega esta carta sólo si tu Héroe tiene el rasgo PATRULLA-X.\nInterrupción de Héroe (defensa): cuando un enemigo ataque, pon en juego un Aliado PATRULLA-X desde tu mano. Agótalo y decláralo como denfensor para este ataque."},
  "32018": {"n":"Energía defensiva","t":"Máximo de 2 por mazo.\nInterrupción de Héroe: cuando gastes esta carta para jugar un Evento de DEFENSA, roba 1 carta."},
  "32019": {"n":"Profesor X","t":"Respuesta obligada: después de que el Profesor X entre el juego, elige una de estas opciones: confundir al Villano, aturdir a un Esbirro o preparar un personaje PATRULLA-X. Al final de la ronda, si el Profesor X aún sigue en juego, descártalo."},
  "32020": {"n":"Jet-X","t":"Recurso: agota el Jet-X → genera un recurso [wild] para un jugador cuyo Superhéroe tenga el rasgo PATRULLA-X.","f":"\"¡Forja se ha superado a sí mismo con esta maravilla!\" -Bestia"},
  "32021": {"n":"Sombra y acero","t":"Equipo (Coloso y Gatasombra).\nMáximo de 1 por mazo.\nInterrupción de Héroe (ataque/defensa): cuando un enemigo ataque, evita todo el Daño de ese ataque e inflige 4 de Daño al enemigo atacante."},
  "32022": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "32023": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "32024": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "32025": {"n":"Morriña","t":"Dale esta carta al jugador que lleva a Piotr Rasputin.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n• Agota a Piotr Rasputin → retira de la partida Morriña.\n• Descarta esta carta y todas las cartas de Estado \"Duro\" que tenga tu Superhéroe. Si no has descartado ninguna carta de Estado \"Duro\" de este modo, esta carta gana Oleada."},
  "32026": {"t":"Firmeza. Dureza.\n[star] Aumento: si esta activación es un ataque, éste gana Brutalidad y Penetrante.","f":"\"¡Nada detiene al Juggernaut!\""},
  "32027": {"n":"Juggernaut desbocado","t":"Cuando se muestre esta carta: descarta todas las cartas de Estado \"Duro\" que tenga cada personaje amigo. Coloca 2 de Amenaza sobre esta carta por cada carta de Estado \"Duro\" que se haya descartado de este modo.","f":"\"Juggernaut posee el poder de Cyttorak, pero éste también le hace enloquecer.\""},
  "32028": {"n":"Imparable","t":"Vincula esta carta al enemigo que tenga el valor impreso más alto de ATQ y que no tenga ya vinculada una copia de Imparable. De no ser posible, esta carta gana Oleada.\n[star] Interrupción obligada: cuando el enemigo vinculado ataque, dicho ataque gana Brutalidad y Penetrante. Al final de este ataque, descarta Imparable."},
  "32029": {"n":"Arrollamiento","t":"Cuando se muestre esta carta: quedas aturdido. Si ya estabas aturdido, sufres 2 de Daño.\n[star] Aumento: muestra esta carta.","f":"\"¿Es que no sabes quién soy?\"-Juggernaut"},
  "32030a": {"n":"Gatasombra","t":"Intangibilidad selectiva - Mientras tengas adoptada la identidad de masa En fase, Gatasombra ignora las palabras clave Guardia y Patrulla, así como los iconos de Crisis ([crisis]) que haya en juego.","f":"\"¡No puedes detener lo que no puedes tocar!\""},
  "32030b": {"t":"Preparación: pon en juego tu Mejora de identidad de masa con la cara de Sólida boca arriba.\nControl de fase - Acción: dale la vuelta a tu Mejora de identidad de masa. (Límite de una vez por ronda.)"},
  "32031a": {"n":"Sólida","t":"Identidad de masa. Permanente.\nRecurso de Héroe: agota esta carta → genera un recurso [physical] para un Evento de ATAQUE o DEFENSA.\nRespuesta: después de que ataques o defiendas en tu identidad de masa Sólida, dale la vuelta a esta carta."},
  "32031b": {"n":"En fase","t":"Identidad de masa. Permanente.\nMientras Gatasombra esté defendiendo, no podrá sufrir Daño.\nRespuesta obligada: después de que ataques o defiendas en tu identidad de masa En fase, dale la vuelta a esta carta."},
  "32032": {"t":"Respuesta: después de que Lockheed entre en juego, si tu identidad de masa es:\n• Sólida, inflige 2 de Daño a un enemigo.\n• En fase, quita 2 de Amenaza de un Plan."},
  "32033": {"n":"El cuarto de Kitty","t":"Acción de Alter ego: agota El cuarto de Kitty → si tu identidad de masa es:\n• Sólida, cura 2 de Daño a Kitty Pryde.\n• En fase, roba 1 carta."},
  "32034": {"n":"Control preciso","t":"Respuesta de Héroe: después de que ignores la palabra clave Guardia o Patrulla de un Esbirro, agota Control preciso → inflige 2 de Daño a ese Esbirro.","f":"\"¿Tienes idea de cuánto he de concentrarme para cambiar de fase sólo el pie?\" -Gatasombra"},
  "32035": {"n":"Interferencia intangible","t":"Respuesta de Héroe: después de que ignores el icono de Crisis ([crisis]) de un Plan, agota Interferencia intangible → quita 2 de Amenaza de ese Plan.","f":"\"El poder de Gatasombra para cambiar de fase ejerce un efecto disruptivo en los aparatos electrónicos.\""},
  "32036": {"n":"Desfase de fase","t":"Sólo identidad de Héroe. Vincula esta carta a un enemigo. Máximo de 1 por enemigo.\nInterrupción obligada: cuando el enemigo vinculado vaya a atacar, en vez de ese descarta esta carta. Luego confunde a ese enemigo."},
  "32037": {"n":"Sorpresa de Gatasombra","t":"Acción de Héroe (ataque): inflige 3 de Daño a un enemigo. Prepara tu Héroe.","f":"\"Vais a ver algo más para lo que probablemente no estéis preparados.\" -Gatasombra"},
  "32038": {"n":"Golpe en fase","t":"Acción de Héroe (ataque): inflige 6 de Daño a un enemigo. Si tu identidad de masa es En fase, puedes descartar un Accesorio de ese enemigo que tenga el encabezado \"Acción de Héroe\" o \"Respuesta de Héroe\"."},
  "32039": {"n":"Caminar por el aire","t":"Acción de Héroe (intervención): quita 2 de Amenaza de un Plan (4 de Amenaza si tu identidad de masa es En fase).","f":"\"Soy intocable. ¡Porque no hay nada que tocar!\" -Gatasombra"},
  "32040": {"n":"Cambio rápido","t":"Interrupción de Héroe (defensa): cuando un enemigo ataque, si tu identidad de masa es:\n• Sólida, cambia a tu identidad de masa En fase.\n• En fase, roba 2 cartas."},
  "32041": {"n":"Lobezno","t":"[star] Los ataques de Lobezno ganan Penetrante.\nRespuesta: después de que empiece tu turno, cura 1 de Daño a Lobezno.","f":"\"¿Te sientes afortunado,nene?\""},
  "32042": {"t":"Respuesta: después de que juegues a Magik desde tu mano, gasta un recurso [mental] → elige un Esbirro que no sea ÉLITE y que esté enfrentado a un Héroe PATRULLA-X. Añade ese Esbiro al mazo de Encuentros y barájalo."},
  "32043": {"n":"Entrenamiento de ataque","t":"Vincula esta carta a un Aliado PATRULLA-X. Máximo de 1 Mejora ENTRENAMIENTO por Aliado.\nEl Aliado vinculado recibe +1 ATQ y +2 de Vida."},
  "32044": {"n":"Guardia en la entrada","t":"Vincula esta carta a un Esbirro.\nEl Esbirro vinculado recibe +2 de Vida y gana Patrulla.\nInterrupción: cuando el Esbirro vinculado sea derrotado, quita 4 de Amenaza del Plan principal."},
  "32045": {"n":"Ataque en Equipo","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo PATRULLA-X.\nAcción de Héroe (ataque): agota tu Héroe y cualquier número de Aliados PATRULLA-X → inflige X de Daño repartidos entro todos los enemigos que haya en juego, siendo X la suma del ATQ de todos los personajes que hayas agotado de este modo."},
  "32046": {"n":"Cara a cara","t":"Acción de Héroe (ataque): elige un enemigo. Ese enemigo te ataca. Inflige 5 de Daño a ese Enemigo.","f":"\"¿Y si pruebas un poco de tu propia medicina?\" —Capitana Marvel"},
  "32047": {"n":"Energía agresiva","t":"Máximo de 2 por mazo.\nInterrupción de Héroe: cuando gastes esta carta para jugar un Evento de ATAQUE, ese Evento inflige 1 de Daño adicional."},
  "32048": {"n":"Coloso","t":"Reduce en 1 el coste para jugar a Coloso si tu Superhéroe tiene el rasgo MUTANTE o PATRULLA-X.\nDureza.","f":"\"¡Ponte detrás de mí, tovarisch!\""},
  "32049": {"n":"Mansión X","t":"Acción de Alter ego: agota la Mansión X → cura 1 de Daño a un personaje MUTANTE o PATRULLA-X. Cualquier jugador cuyo Alter ego tenga el rasgo MUTANTE puede aplicar esta capacidad."},
  "32050": {"n":"Sombra y acero","t":"Equipo (Coloso y Gatasombra).\nMáximo de 1 por mazo.\nInterrupción de Héroe (ataque/defensa): cuando un enemigo ataque, evita todo el Daño de ese ataque e inflige 4 de Daño al enemigo atacante."},
  "32051": {"n":"En pie de guerra","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nRespuesta de Héroe: después de que cambies de identidad, descarta esta carta → prepara tu Héroe."},
  "32052": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "32053": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "32054": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "32055": {"n":"En fase permanente","t":"Dale esta carta al jugador que lleva a Kitty Pryde.\nDale la vuelta a tu Mejora de identidad de masa para cambiarla a En fase.\nNo puedes atacar, defender ni cambiar de identidad de masa.\nAcción de Alter ego: agota a Kitty Pryde → retira de la partida En fase permanente."},
  "32056": {"n":"Reina Blanca","t":"Infame.\nMientras la Reina Blanca esté enfrentada a ti, quedas confundido.\n(Esbirro Archienemigo de Gatasombra.)\n[star] Aumento: quedas confundido."},
  "32057": {"n":"El Club Fuego Infernal","t":"Cuando se derrote esta carta: el jugador que haya derrotado este Plan busca una copia del Esbirro Peón del Fuego Infernal en el mazo de Encuentros, la pila de descartes y la zona apartada, y lo pone en juego enfrentado a él. (Baraja el mazo.)"},
  "32058": {"n":"Peón del Fuego Infernal","t":"Guardia. Patrulla. Oleada.\n[star] Aumento: pon en juego el Peon del fuego Infernal enfrentado a ti."},
  "32059": {"n":"Contención telepática","t":"Vincula esta carta a tu Superhéroe.\nMientras la Contención telepática esté vinculada a tu Superhéroe, quedas aturdido.\nAcción: gasta recursos [mental][mental] → descarta esta carta.","f":"\"Pórtate bien y no te muevas...ni hables.Así está mejor.\"-Reina Blanca"},
  "32060": {"n":"Dientes de Sable","t":"[star] Respuesta obligada: después de que Dientes de Sable se active contra ti, descarta la primera carta del mazo de Encuentros. Cura a Dientes de Sable tanto Daño como el número de iconos de Aumento ([boost]) que se hayan descartado de este modo.","f":"\"¡Te voy a arrancar las tripas!\""},
  "32061": {"n":"Dientes de Sable","t":"Dureza.\n[star] Respuesta obligada: después de que Dientes de Sable se active contra ti, descarta la primera carta del mazo de Encuentros. Cura a Dientes de Sable tanto Daño como el número de iconos de Aumento ([boost]) que se hayan descartado de este modo."},
  "32062": {"n":"Dientes de Sable","t":"Represalia 1. Dureza.\n[star] Respuesta obligada: después de que Dientes de Sable se active contra ti, descarta la primera carta del mazo de Encuentros. Cura a Dientes de Sable tanto Daño como el número de iconos de Aumento ([boost]) que se hayan descartado de este modo."},
  "32063a": {"n":"Acosado por Dientes de Sable","t":"Contenido: Dientes de Sable (I) y Dientes de Sable (II). (Dientes de Sable [II] y Dientes de Sable [III] para jugar en modo Experto.) Conjuntos de Encuentros de Dientes de Sable y Normal. Dos conjuntos de Encuentros modulares (Hermandad y Mística).\nPreparación: pon en juego el Plan secundario Buscar al senador. Vincúlale la carta de Aliado de Robert Kelly. Mientras esté vinculado a Buscar al senador, Robert Kelly está en juego pero no lo controla ningún jugador."},
  "32063b": {"n":"Acosado por Dientes de Sable","t":"[star] Respuesta obligada: después de resolver el paso uno de la fase de Villano, inflige 2 de Daño a Robert Kelly (3 de Daño si hay al menos 6[per_hero] de Amenaza sobre esta carta).\nMientras Robert Kelly esté vinculado a Buscar al senador, trata su texto de reglas como si estuviese en blanco.\nSi Robert Kelly abandona el juego, los jugadores pierden la partida."},
  "32064a": {"n":"El Senador herido","t":"Cuando se muestre esta carta: reparte a cada jugador 1 carta de Encuentro boca abajo.","f":"\"¡Dientes de Sable ha herido al senador Kelly y continúa hostigándolo!\""},
  "32064b": {"n":"El Senador herido","t":"Cuando se complete esta carta: derrota a Robert Kelly.\nSi Robert Kelly abandona el juego, los jugadores pierden la partida.","f":"Poned a salvo a Robert Kelly antes de que Dientes de Sable termine el trabajo."},
  "32065a": {"n":"Busca al Senador","t":"Robert Kelly no puede curarse mediante efectos de cartas de Jugador y tampoco se le pueden vincular Mejoras.\nCuando se derrote esta carta: el jugador inicial desvincula a Robert Kelly de este Plan y toma el control de su carta. El Plan principal avanza a la etapa 2A. Dale la vuelta a esta carta y colócala junto al Plan principal."},
  "32065b": {"n":"Proteger al Senador","t":"Robert Kelly no puede curarse mediante efectos de cartas de Jugador y tampoco se le pueden vincular Mejoras.\nRespuesta de Héroe: después de que tu Héroe defienda contra un ataque de Dientes de Sable, gasta 2 recursos de cualquier tipo → prepara a tu Héroe. El jugador que controla a Robert Kelly es el único que puede aplicar esta capacidad."},
  "32066": {"t":"El jugador inicial controla a Robert Kelly. No se cuenta de cara a tu límite de Aliados y tampoco se le pueden vincular cartas de Jugador.\nInterrupción obligada: cuando un enemigo resuelva un ataque no defendido contra ti, inflige ese Daño a Robert Kelly."},
  "32067": {"n":"Garras de Adamántium","t":"Vincula esta carta a Dientes de Sable.\nLos ataques de Dientes de Sable ganan Penetrante.\nAcción de Héroe: gasta recursos [energy][mental][physical] → descarta esta carta.\n[star] Aumento: Vincula esta carta a Dientes de Sable."},
  "32068": {"n":"Ferocidad Animal","t":"Vincula esta carta a Dientes de Sable.\nDientes de Sable gana Firmeza.\nAcción de Héroe: gasta recursos [energy][mental][physical] → descarta esta carta.\n[star] Aumento: Vincula esta carta a Dientes de Sable."},
  "32069": {"n":"Dientes de Sable ataca","t":"Cuando se muestre esta carta: inflige 1 de Daño a Robert Kelly. Puedes agotar a tu Héroe para evitar esto.\n[star] Aumento: si este ataque derrota a un Aliado, coloca 2 de Amenaza sobre el Plan principal."},
  "32070": {"n":"Salvajismo impaclabe","t":"Cuando se muestre esta carta (Alter ego): Dientes de Sable ejecuta el Plan. Si no tiene Daño acumulado, recibe +1 PLA para esta activación.\nCuando se muestre esta carta (Héroe): Dientes de Sable te ataca. Si no tiene Daño acumulado, recibe +1 ATQ para esta activación."},
  "32071": {"n":"Emergencia médica","t":"Complicación 2[per_hero].\nVictoria 1.\nCuando se derrote esta carta: cura 2 de Daño a Robert Kelly."},
  "32072": {"n":"Rabia salvaje","t":"Cuando se derrote esta carta: Dientes de Sable ataca al jugador que haya derrotado este Plan (incluso aunque tenga adoptada la identidad de su Alter ego).","f":"\"La caza de Kelly ha inducido un frenesí rabioso en Dientes de Sable. ¡Tenéis qué desviar su atención del senador!\""},
  "32073": {"n":"Avalancha","t":"[star] Respuesta obligada: después de que Avalancha te ataque, agota un personaje que controles.\n[star] Aumento: agota un personaje que controles."},
  "32074": {"n":"Mole","t":"Guardia.\n[star] Respuesta obligada: después de que la Mole ataque e inflija Daño a un personaje, aturde a ese personaje.","f":"\"¡Nada mueve a la Mole!\""},
  "32075": {"n":"Piros","t":"[star] Respuesta obligada: después de que Piros te ataque, descarta las 2 primeras cartas de tu mazo. Sufres 1 de Daño indirecto por cada icono de recurso impreso que se haya descartado de este modo.","f":"\"Piros juega con fuego, chicos...¡pero nunca se quema!\""},
  "32076": {"n":"Sapo","t":"[star] Respuesta obligada: después de que Sapo ataque e inflija Daño a un personaje que controles, descarta 1 carta de tu mano al azar.\n[star] Aumento: descarta 1 carta de tu mano al azar."},
  "32077": {"t":"Vincula esta carta a un Esbirro y dale una carta de Estado \"Duro\". De no ser posible, esta carta gana Oleada.\nEl Esbirro vinculado recibe +5 de Vida.\n[star] Aumento: vincula esta carta a un Esbirro y dale una carta de Estado \"Duro\"."},
  "32078": {"n":"Terroristas mutantes","t":"Cuando se muestre esta carta: busca el Plan secundario La Hermandad en el mazo y la pila de descartes de Encuentros y muéstralo. (Baraja el mazo.) Si no ha entrado en juego de este modo, descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Esbirro HERMANDAD DE MUTANTES y muéstralo."},
  "32079": {"n":"La Hermandad","t":"Complicación 2[per_hero].\nTodos los Esbirros HERMANDAD DE MUTANTES ganan Ataque veloz.","f":"\"Magneto fundó la Hermandad de Mutantes para llevar a cabo su plan de supremacía mutante.\""},
  "32080": {"n":"Mística","t":"Dureza.\nLos jugadores no pueden atacar al Villano.\n[star] El valor de PLA de Mística es igual al PLA del Villano, y su ATQ es igual al ATQ del Villano.","f":"\"¡Conmigo no se juega!\""},
  "32081": {"n":"Malicia metamórfica","t":"Cuando se derrote esta carta: el jugador que haya derrotado este Plan coge todas las cartas Cambiaformas que haya en la pila de descartes del mazo de Encuentros, las añade a su mazo y lo baraja.","f":"El poder de Mística para adoptar cualquier apariencia la convierte en una enemiga impredecible."},
  "32082": {"n":"Infiltración","t":"Cuando se muestre esta carta: añade esta carta a tu mazo y barájalo. Esta carta gana Oleada.\nRespuesta obligada: después de que esta carta entre en tu mano, descarta un Aliado o Apoyo que controles. (Puedes descartar esta carta de tu mano al final de la la fase de los Jugadores como cualquier otra carta.)"},
  "32083": {"n":"Impostora imprevisible","t":"Cuando se muestre esta carta: añade esta carta a tu mazo y barájalo. Esta carta gana Oleada.\nRespuesta obligada: después de que esta carta entre en tu mano, Mística se activa contra ti. De no ser así, busca a Mística en el mazo y la pila de descartes de Encuentros y muéstrala."},
  "32084": {"n":"Centinela","t":"Dureza.\nCuando se muestre esta carta: el jugador inicial busca en el mazo y la pila de descartes de Encuentros una copia del Plan secundario Protocolos de captura y lo muestra.(Baraja el mazo.)","f":"\"MUTANTE DETECTADO, INICIANDO SECUENCIA DE CAPTURA.\""},
  "32085": {"n":"Centinela","t":"Tesón. Dureza.\nCuando se muestre esta carta: el jugador inicial busca en el mazo y la pila de descartes de Encuentros una copia del Plan secundario Protocolos de captura y lo muestra (Baraja el mazo.) Reparte a los demás jugadores 1 carta de Encuentro boca abajo a cada uno."},
  "32086": {"n":"Centinela","t":"Firmeza. Dureza.\nCuando se muestre esta carta: el jugador inicial busca en el mazo y la pila de descartes de Encuentros una copia del Plan secundario Protocolos de captura y lo muestra (Baraja el mazo.) Reparte a los demás jugadores 1 carta de Encuentro boca abajo a cada uno."},
  "32087a": {"n":"Noche de los centinelas","t":"Contenido: Centinela (I) y Centinela (II). (Centinela [II] y Centinela [III] para jugar en modo Experto.) Conjuntos de Encuentros del Proyecto Despertar, Tolerancia Cero y Normal. Un conjunto de Encuentros modular (Centinelas).\nPreparación: aparta a un lado todos los Aliados ([Cautivo]). Muestra los Planes Tolerancia Cero y Mutantes en el centro comercial."},
  "32087b": {"n":"Noche de los centinelas","t":"Operación Tolerancia Cero gana Permanente.\nRespuesta obligada: después de que se coloque Amenaza sobre esta carta, si hay al menos 5[per_hero] de Amenaza sobre ella, el jugador inicial coge la primera carta de su mazo y la coloca boca abajo debajo de Operación Tolerancia Cero. Luego retira 5[per_hero] de Amenaza de este Plan."},
  "32088a": {"n":"Mutantes en el centro comercial","t":"Cuando se derrote esta carta: el jugador inicial busca un Esbirro CENTINELA en el mazo y la pila de descartes de Encuentros y lo muestra. Dale la vuelta a esta carta y pon en juego a Júbilo, descartando cualquier otra versión suya que haya en juego."},
  "32088b": {"n":"Júbilo","t":"Victoria -1.\nEl jugador inicial controla a Júbilo. No se cuenta de cara a tu límite de Aliados.\nAcción: Agota a Júbilo y gasta un recurso [energy] → inflige 2 de Daño a un enemigo."},
  "32089": {"t":"Respuesta: después de que Rictor ataque, inflige 1 de Daño al Villano y a cada Esbirro que esté enfrentado a ti.","f":"\"Tío...qué vida tan rara te espera.\""},
  "32090": {"n":"Bum Bum","t":"Respuesta: después de que Bum Bum ataque a un enemigo, colócale encima 1 contador de Bomba. Al final de la fase de los Jugadores, retira del juego todos los contadores de Bomba e inflige 2 de Daño a cada enemigo por cada contador de Bomba que se le haya retirado de este modo."},
  "32091": {"n":"Bala de Cañón","t":"[star] Bala de Cañon sufre -1 de Daño derivado después de que ataque y derrote a un Esbirro.","f":"\"Buen intento, pero cuando despego, soy casi invulnerable.\""},
  "32092": {"n":"Loba Venenosa","t":"[star] Los ataques de Loba Venenosa ganan Penetrante.","f":"\"No sé por qué haces esto. ¡Pero como lastimes a mis amigos, vas a saber lo que es el dolor!\""},
  "32093": {"n":"Centinela Mark IV","t":"Guardia. Patrulla.\n[star] Aumento: pon en juego al Centinela Mark IV."},
  "32094": {"n":"Guantelete lanzarrayos","t":"Vincula esta carta al Villano.\n[star] Los ataques del Villano ganan A distancia y Penetrante.\nAcción de Héroe: gasta recursos [physical][physical][physical] → descarta esta carta.\n[star] Aumento: agota tu carta de Superhéroe."},
  "32095": {"n":"IA de aprendizaje","t":"Vincula esta carta al Villano.\n[star] El Villano gana Represalia 1.\nAcción de Héroe: gasta recursos [mental][mental][mental] → descarta esta carta.\n[star] Aumento: vincula esta carta al Villano."},
  "32096": {"n":"Blindaje adaptativo","t":"Vincula esta carta al Villano.\n[star] El Villano recibe +8 de Vida.\nAcción de Héroe: gasta recursos [energy][energy][energy] → descarta esta carta.\n[star] Aumento: vincula esta carta al Villano."},
  "32097": {"n":"Reparaciones automatizadas","t":"Cuando se muestre esta carta: descarta todas las cartas de Estado que tenga el Villano. Dale al Villano una carta de Estado \"Duro\"y cúrale 5 de Daño.\n[star] Aumento: dale al Villano una carta de Estado \"Duro\"."},
  "32098": {"n":"Mutante Detectado","t":"Cuando se muestre esta carta: elige una opción:\n• Coge la primera carta de tu mazo y colócala boca abajo debajo de Operación Tolerancia Cero.\n• El Villano y todos los Esbirros que estén enfrentados a ti te atacan (incluso aunque tengas adoptada la identidad de Alter ego)."},
  "32099": {"n":"Avisar a los demás","t":"Respuesta obligada: después de que termine tu turno, coloca esta carta boca abajo debajo de Operación Tolerancia Cero.\nRespuesta obligada: agota tu Superhéroe → descarta esta carta.","f":"\"¡Si no encontramos primero a nuestros amigos, los capturarán a todos!\"-Hombre de Hielo"},
  "32100": {"n":"Protocolos de captura","t":"Complicación 2[per_hero]. Victoria 2.\nCuando se muestre esta carta: el jugador que haya derrotado este Plan coge al azar 1 Aliado Cautivo que esté apartado y lo pone en juego controlado por él."},
  "32101": {"n":"Centinela Mark II","t":"Cuando se muestre esta carta: si está en juego Operación Tolerancia Cero, el Centinela Mark II gana Oleada. De no ser así, busca el Plan secundario Operación Tolerancia Cero en el mazo y la pila de descartes de Encuentros y muéstralo. (Baraja el mazo.)"},
  "32102": {"n":"Centinela Mark III","t":"Dureza.\nCuando se muestre esta carta: busca el Accesorio Barrera de energía en el mazo y la pila de descartes de Encuentros y vincúlalo a este Esbirro.\n[star] Aumento: quedas aturdido. Si ya estabas aturdido, sufres 2 de Daño."},
  "32103": {"n":"Barrera de energía","t":"Vincula esta carta a un Esbirro CENTINELA que no tenga vinculada Barrera de energía y dale una carta de Estado \"Duro\". De no ser posible, esta carta gana Oleada.\nRespuesta obligada: después de que el Esbirro vinculado ataque, dale una carta de Estado \"Duro\"."},
  "32104": {"n":"Operación Tolerancia Cero","t":"Respuesta obligada: después de que un enemigo ataque y derrote a un Aliado, coloca ese Aliado boca abajo debajo de este Plan.\nSi hay X cartas boca abajo debajo de este Plan, los jugadores pierden la partida. X es igual al número de jugadores más 3."},
  "32105": {"n":"Centinela Mark V","t":"Cuando se muestre esta carta: si tu Superhéroe tiene vinculado Objetivo designado, el Centinela Mark V te ataca (incluso aunque tengas adoptada la identidad de tu Alter ego). De no ser así, busca el Accesorio Objetivo designado en el mazo y la pila de descartes de Encuentros y muéstralo."},
  "32106": {"n":"Centinela Mark VI","t":"Ataque veloz.\n[star] Aumento: si Objetivo designado esta vinculado a un Superhéroe, dale esta carta a ese jugador como una carta de Encuentro boca abajo."},
  "32107": {"n":"Objetivo designado","t":"Vincula esta carta a tu Superhéroe si no tienes ya vinculada una copia de Objetivo designado.De no ser así, esta carta gana Oleada.\nMientras estés enfrentado a un Esbirro ([CENTINELA]), no podrás cambiar a tu identidad de Héroe a Alter ego.\nAcción: agota tu carta de Superhéroe → descarta esta carta."},
  "32108": {"n":"Robots implacables","t":"Ningún jugador que esté enfrentado a un Esbirro CENTINELA puede intervenir este Plan.","f":"Los centinelas se construyeron con el único propósito de cazar mutantes. No se cansan. No se detendrán hasta haber capturado a su objetivo."},
  "32109": {"n":"Molde Maestro","t":"Firmeza. Dureza.\n[star] Interrupción obligada: cuando el Molde Maestro ejecute el Plan contra ti, descarta cartas del mazo de Encuentros hasta que se descarte un Esbirro CENTINELA. Pon en juego ese Esbirro enfrentado a ti. No des una carta de aumento al Molde Maestro para esta activación."},
  "32110": {"n":"Molde Maestro","t":"Firmeza. Dureza.\n[star] Interrupción obligada: cuando el Molde Maestro ejecute el Plan contra ti, descarta cartas del mazo de Encuentros hasta que se descarte un Esbirro CENTINELA. Pon en juego ese Esbirro enfrentado a ti. No des una carta de aumento al Molde Maestro para esta activación."},
  "32111": {"n":"Molde Maestro","t":"Firmeza. Dureza.\n[star] Interrupción obligada: cuando el Molde Maestro ejecute el Plan contra ti, descarta cartas del mazo de Encuentros hasta que se descarte un Esbirro CENTINELA. Pon en juego ese Esbirro enfrentado a ti. No des una carta de aumento al Molde Maestro para esta activación."},
  "32112a": {"n":"La fábrica de centinelas","t":"Contenido: Molde Maestro (I) y Molde Maestro (II). (Molde Maestro [II] y Molde Maestro [III] para jugar en modo Experto.) Conjuntos de Encuentros del Molde Maestro, Centinelas y Normal. Un conjunto de Encuentros modular (Tolerancia Cero).\nPreparación: pon en juego el Aliado Magneto (172B) controlado por el jugador inicial."},
  "32112b": {"n":"La fábrica de centinelas","t":"Todos los Esbirros CENTINELA ganan Guardia.\nCuando se muestre esta carta: cada jugador descarta cartas del mazo de Encuentros hasta que se descarte un Esbirro CENTINELA, luego lo pone en juego enfrentado a él."},
  "32113a": {"n":"El plan del Molde Maestro","t":"Cuando se muestre esta carta: baraja el mazo de Encuentros junto con su pila de descartes. Cada jugador descarta cartas del mazo de Encuentros hasta que descarte un Esbirro CENTINELA, luego lo pone en juego enfrentado a él."},
  "32113b": {"n":"El plan del Molde Maestro","t":"Todos los Esbirros CENTINELA ganan Guardia\nSi se completa esta etapa, los jugadores pierden la partida..","f":"¡La programación del Molde Maestro lo ha vuelto contra sus creadores! ¡Tras concluir que los mutantes proceden de los humanos, el gigantesco centinela está programando a su \"prole\" para someter a todos los habitantes del planeta!"},
  "32114": {"n":"Centinela Mark VIII","t":"Respuesta obligada: después de que este Esbirro se enfrente a ti, vincúlale el primer Accesorio CENTINELA que hata en la parte superior de la pila de descartes.","f":"\"¡Han mejorado su blindaje!\"-Cíclope"},
  "32115": {"n":"Mejora de unidad","t":"Vincula esta carta a un Esbirro CENTINELA. De no ser posible, esta cata gana Oleada.\nEl Esbirro vinculado recibe +2 de Vida y gana Represalia 1.\n[star] Aumento: vincula esta carta a un Esbirro ([CENTINELA])."},
  "32116": {"n":"Rayo aturdidor","t":"Vincula esta carta a un Esbirro CENTINELA que no tenga ya vinculado un Rayo aturdidor. De no ser posible, esta carta gana Oleada.\nRespuesta obligada: después de que el Esbirro vinculado ataque e inflija Daño a un personaje, aturde a ese personaje."},
  "32117": {"n":"Hijos del Molde Maestro","t":"Cuando se muestre esta carta (Alter ego): todo Esbirro qué esté enfrentado a ti ejecuta el Plan. Si no estás enfrentado a nigún Esbirro, el Molde Maestro ejecuta el Plan.\nCuando se muestre esta carta (Héroe): todo Esbirro que esté enfrentado a ti te ataca. Si no estás enfrentado a nigún Esbirro, el Molde Maestro te ataca."},
  "32118": {"n":"Activar los escudos","t":"Cuando se muestre esta carta: dale una carta de Estado \"Duro\" a cada Esbirro CENTINELA que esté enfrentado a ti. De no ser posible, esta carta gana Oleada.\n[star] Aumento: dale al Villano una carta de Estado \"Duro\"."},
  "32119": {"n":"¡Alerta de intrusos!","t":"Cuando se muestre esta carta: el jugador que haya derrotado este Plan descarta cartas del mazo de Encuentros hasta que descarte un Esbirro CENTINELA, luego lo pone enfrentado a él."},
  "32120": {"n":"Cargar virus informático","t":"Complicación 2[per_hero]. Victoria 1.\nCuando se derrote esta carta: inflige 2 de Daño a cada enemigo CENTINELA.","f":"Si lográis introducir un virus informático en el ordenador central del Molde Maestro, lo debilitaréis desde dentro."},
  "32121a": {"n":"Avalancha A","t":"Dureza. Victoria 2.\nRespuesta obligada: después de que Avalacha te ataque, agota un Aliado que controles.","f":"\"¡Salid a pelear o derribaré el edificio entero!\""},
  "32121b": {"n":"Avalancha B","t":"Dureza. Victoria 2.\nRespuesta obligada: después de que Avalacha te ataque, agota un Aliado que controles.","f":"\"¡Salid a pelear o derribaré el edificio entero!\""},
  "32122a": {"n":"Mole A","t":"Dureza. Victoria 2.\nRespuesta obligada: después de que Mole te ataque e inflija Daño, aturde a ese personaje.","f":"\"¡Primero os voy a aplastar!¡Y luego os vaciaré la nevera!\""},
  "32122b": {"n":"Mole B","t":"Dureza. Victoria 2.\nRespuesta obligada: después de que Mole te ataque e inflija Daño, aturde a ese personaje.","f":"\"¡Primero os voy a aplastar!¡Y luego os vaciaré la nevera!\""},
  "32123a": {"n":"Piros A","t":"Dureza. Victoria 2.\nRespuesta obligada: después de que Piros te ataque, deacarta las 2 primeras cartas de tu mazo. Sufres 1 de Daño indirecto por cada icono de recurso impreso que se haya descartado de este modo."},
  "32123b": {"n":"Piros B","t":"Dureza. Victoria 2.\nRespuesta obligada: después de que Piros te ataque, deacarta las 2 primeras cartas de tu mazo. Sufres 1 de Daño indirecto por cada icono de recurso impreso que se haya descartado de este modo."},
  "32124a": {"n":"Sapo A","t":"Dureza. Victoria 2.\nRespuesta obligada: después de que Sapo te ataque e inflija Daño a un personaje que controles, descarta 1 carta de tu mano al azar.","f":"\"¡En la Patrulla-X todos os creéis mejores que yo!¡Pues os vais a enterar!\""},
  "32124b": {"n":"Sapo B","t":"Dureza. Victoria 2.\nRespuesta obligada: después de que Sapo te ataque e inflija Daño a un personaje que controles, descarta 1 carta de tu mano al azar.","f":"\"¡En la Patrulla-X todos os creéis mejores que yo!¡Pues os vais a enterar!\""},
  "32125a": {"n":"¡La Hermandad ataca!","t":"Contenido: Avalancha (A), Mole (A), Piros (A) y Sapo (A). (Usa sus caras (B) para jugar en modo Experto.) Conjuntos de Encuentros de Ataque a la mansión, Hermandad y Normal. Un conjunto de Encuentros modular (Mística).\nPreparación: pon en juego la carta de Entorno Salvar el instituto. Baraja todas las copias del Plan principal 2A y amontónalas debajo de este Plan. Baraja los Villanos (sin mirarlos) para crear el mazo de Villanos. La carta que quede en la parte superior de este mazo está en juego."},
  "32125b": {"n":"¡La Hermandad ataca!","t":"Cuando se muestre esta carta: reparte a cada jugador 1 carta de Encuentro boca abajo. Avanza a la siguiente carta del mazo del Plan principal. Añade esta carta a la zona de victoria.","f":"¡La hermandad de Mutantes está atacando el Instituto Xavier!"},
  "32126a": {"n":"El vestíbulo","t":"Cuando se muestre esta carta: dale la vuelta a esta carta.","f":"Los miembros de la Hermandad atacan todos a una, concentrando su ofensiva en..."},
  "32126b": {"n":"El vestíbulo","t":"Todos los personajes ganan Tesón.\ncuando se complete esta etapa: añade este Plan a la zona de victoria. Avanza a la siguiente carta del mazo del Plan principal.\nSi hay 3 Planes principales en la zona de victoria, los jugadores pierden la partida."},
  "32127a": {"n":"La cafetería","t":"Cuando se muestre esta carta: dale la vuelta a esta carta.","f":"Los miembros de la Hermandad atacan todos a una, concentrando su ofensiva en..."},
  "32127b": {"n":"La cafetería","t":"Todos los personajes ganan Represalia 1.\ncuando se complete esta etapa: añade este Plan a la zona de victoria. Avanza a la siguiente carta del mazo del Plan principal.\nSi hay 3 Planes principales en la zona de victoria, los jugadores pierden la partida."},
  "32128a": {"n":"La cancha de baloncesto","t":"Cuando se muestre esta carta: dale la vuelta a esta carta.","f":"Los miembros de la Hermandad atacan todos a una, concentrando su ofensiva en..."},
  "32128b": {"n":"La cancha de baloncesto","t":"Todos los Aliados y Esbirros ganan Dureza.\ncuando se complete esta etapa: añade este Plan a la zona de victoria. Avanza a la siguiente carta del mazo del Plan principal.\nSi hay 3 Planes principales en la zona de victoria, los jugadores pierden la partida."},
  "32129a": {"n":"El patio","t":"Cuando se muestre esta carta: dale la vuelta a esta carta.","f":"Los miembros de la Hermandad atacan todos a una, concentrando su ofensiva en..."},
  "32129b": {"n":"El patio","t":"Todos los personajes ganan +1 ATQ.\ncuando se complete esta etapa: añade este Plan a la zona de victoria. Avanza a la siguiente carta del mazo del Plan principal.\nSi hay 3 Planes principales en la zona de victoria, los jugadores pierden la partida."},
  "32130": {"n":"Salvar el instituto","t":"Respuesta obligada: después de que el Villano sea derrotado, si hay X Villanos en la zona de victoria, los jugadores ganan la partida (ver pagina 15 del reglamento). De no ser así, reparte a cada jugador una carta de Encuentro y muestra al siguiente Villano. Si algún jugador está enfrentado a un Esbirro que se llama igual que el nuevo Villano, se descarta ese Esbirro y se activa el Villano contra ese jugador."},
  "32131": {"n":"Vapuleados por la Hermandad","t":"Cuando se muestre esta carta: por cada uno de los siguientes enemigos que esté en juego:\n• Avalancha: agota tu carta de Superhéroe.\n• Mole: quedas aturdido.\n• Piros: sufres 2 de Daño indirecto.\n• Sapo: descarta 1 carta de tu mano al azar."},
  "32132": {"n":"Erupción de tierra","t":"Cuando se muestre esta carta: Avalacha se activa contra ti. Si no está en juego, busca el Esbirro Avalancha en el mazo y la pila de descartes de Encuentros y muéstralo.\n[star] Aumento: si el Villano es Avalacha, dale una carta de aumento adicional para esta activación."},
  "32133": {"n":"Immovible","t":"Cuando se muestre esta carta: Mole se activa contra ti. Si no está en juego, busca el Esbirro Mole en el mazo y la pila de descartes de Encuentros y muéstralo.\n[star] Aumento: si el Villano es Mole, dale una carta de aumento adicional para esta activación."},
  "32134": {"n":"Pirómano","t":"Cuando se muestre esta carta: Piros se activa contra ti. Si no está en juego, busca el Esbirro Piros en el mazo y la pila de descartes de Encuentros y muéstralo.\n[star] Aumento: si el Villano es Piros, dale una carta de aumento adicional para esta activación."},
  "32135": {"n":"Sapos y culebras","t":"Cuando se muestre esta carta: Sapo se activa contra ti. Si no está en juego, busca el Esbirro Sapo en el mazo y la pila de descartes de Encuentros y muéstralo.\n[star] Aumento: si el Villano es Sapo, dale una carta de aumento adicional para esta activación."},
  "32136": {"n":"Proteger a los alumnos","t":"Complicación 2[per_hero]\nCuando se derrote esta carta: el jugador que haya derrotado este Plan busca un Aliado en su mazo y su pila de descartes y lo añade a su mano."},
  "32137": {"n":"Bajo asedio","t":"Cuando se muestre esta carta: coloca 3 de Amenaza sobre este Plan por cada personaje HERMANDAD DE MUTANTES que haya en juego."},
  "32138": {"t":"Tesón. Dureza.\n[star] Respuesta obligada: después de que Magneto te ataque, coloca 1 contador de Magnetismo sobre el Plan principal.","f":"\"¡Oponerse al Amo del Magnetismo es una invitación para ser destruido!\""},
  "32139": {"t":"Tesón. Dureza.\nCuando se muestre esta carta: reparte a cada jugador 1 carta de Encuentro boca abajo.\n[star] Respuesta obligada: después de que Magneto te ataque, coloca 1 contador de Magnetismo sobre el Plan principal."},
  "32140": {"t":"Tesón. Dureza.\nCuando se muestre esta carta: reparte a cada jugador 1 carta de Encuentro boca abajo.\n[star] Respuesta obligada: después de que Magneto te ataque, coloca 1 contador de Magnetismo sobre el Plan principal."},
  "32141a": {"n":"Asteroide M","t":"Contenido: Magneto (I) y Magneto (II). (Magneto (II) y Magneto (III) para jugar en modo Experto.) Conjuntos de Encuentros de Magneto y Normal. Un conjunto de Encuentros modular (Acólitos).\nPreparación: aparta a un lado el Plan secundario Caída de órbita. Muestra el Plan secundario Misión de abordaje.","f":"El santuario orbital de Magneto flota alrededor de la Tierra."},
  "32141b": {"n":"Asteroide M","t":"Respuesta obligada: después de que coloques un contador de Magnetismo sobre este Plan, si hay al menos 3 contadores de magnetismo aquí, descarta cartas del mazo de Encuentros hasta que se descarte una con el rasgo Magnético. Muestra esa carta, luego quita 3 contadores de Magnetismo de este Plan."},
  "32142a": {"n":"Fábrica operativa","t":"Cuando se muestre esta carta: coloca 1 contador de Magnetismo sobre esta carta. Si Sabotear el Molde Maestro no esta en la zona de victoria, el jugador inicial busca una copia del Esbirro Centinela tipo M en el mazo y la pila de descartes de Encuentros y lo muestra."},
  "32142b": {"n":"Fábrica operativa","t":"Respuesta obligada: después de que coloques un contador de Magnetismo sobre este Plan, si hay al menos 3 contadores de magnetismo aquí, descarta cartas del mazo de Encuentros hasta que se descarte una con el rasgo Magnético. Muestra esa carta, luego quita 3 contadores de Magnetismo de este Plan."},
  "32143a": {"n":"La dictadura de Magnus","t":"Cuando se muestre esta carta: coloca 2 contadores de Magnetismo sobre esta carta. Si Magneto no tiene vunculado Esfuerzo físico, el jugador inicial busca un Accesorio Magnético en el mazo y la pila de descartes de Encuentros y lo muestra."},
  "32143b": {"n":"La dictadura de Magnus","t":"Respuesta obligada: después de que coloques un contador de Magnetismo sobre este Plan, si hay al menos 3 contadores de magnetismo aquí, descarta cartas del mazo de Encuentros hasta que se descarte una con el rasgo Magnético. Muestra esa carta, luego quita 3 contadores de Magnetismo de este Plan.\nSi se completa esta etapa, los jugadores pierden la partida."},
  "32144a": {"n":"Misión de abordaje","t":"Magneto no puede tener más de 6[per_hero] de Daño acumulado.\nCuando se derrote esta carta: dale la vuelta a esta carta y muestra Sabotear el Molde Maestro.","f":"Para frustar los malignos planes de Magneto, primero debéis subir a bordo del Asteroide M."},
  "32144b": {"n":"Sabotear el Molde Maestro","t":"Magneto no puede tener más de 12[per_hero] de Daño acumulado.\nCuando se derrote esta carta: muestra el Plan secundario Caída de órbita que está apartado. Añade esta carta a la zona de victoria.","f":"El Molde Maestro ha sido reprogramado.¡Tenéis que desconectarlo antes de que logre fabricar centinelas cazadores de humanos!"},
  "32145a": {"n":"Caída de Órbita","t":"Magneto no puede tener más de 18[per_hero] de Daño acumulado.\nCuando se derrote esta carta: dale la vuelta a esta carta y muestra Esfuerzo físico.","f":"Magneto es un adversario indómito. El único modo de garantizar su derrota consiste en destruir su base orbital haciendo que se estrelle contra la Tierra."},
  "32145b": {"n":"Esfuerzo Físico","t":"Vincula esta carta a Magneto.\nPermanente.\nMagneto pierde Tesón.","f":"¡Cuando el Asteroide M se precipita fuerade control hacia la superficie del planeta, Magneto emplea su poder para evitar que se desintegre mientras lucha contra vosotros!"},
  "32146": {"n":"Centinela tipo M","t":"Guardia.\nCuando se derrote esta carta: dale a Magneto una carta de Estado \"Duro\".\n[star] Aumento: dale a Magneto una carta de Estado \"Duro\" y una carta de aumento boca abajo."},
  "32147": {"n":"Casco de Magneto","t":"Vincula esta carta a Magneto.\nMagneto no puede quedar confundido.\nRespuesta de Héroe: después de que tu Héroe realice un ataque básico contra Magneto, gasta recursos [energy][mental][physical] → descarta esta carta.","f":"Magneto diseñó su casco para protegerse de los poderes telepáticos de Xavier."},
  "32148": {"n":"Armadura de Magneto","t":"Vincula esta carta a Magneto.\nMagneto no puede quedar aturdido.\nRespuesta de Héroe: después de que tu Héroe realice un ataque básico contra Magneto, gasta recursos [energy][mental][physical] → descarta esta carta.","f":"La armadura de Magneto es lo bastante resistente como para sobrevivir al impacto directo del rayo de un centinela."},
  "32149": {"n":"Burbuja Magnética","t":"Vincula esta carta a Magneto.\nMagneto gana Represalia 1.\nInterrupción obligada: cuando Magneto vaya a sufrir cualquier cantidad de Daño, en vez de eso coloca ese Daño sobre esta carta. Luego, si hay al menos 8 de Daño aquí, descarta esta carta."},
  "32150": {"n":"Envoltura Metálica","t":"Vincula esta carta a tu Superhéroe.\nEl Superhéroe vinculado no puede intervenir, atacar, defender ni recuperarse.\nAcción: agota a tu Superhéroe y gasta un recurso [physical] → descarta esta carta.","f":"\"Vaya, esto no es bueno\"—Arcángel"},
  "32151": {"n":"El amo del magnetismo","t":"Cuando se muestre esta carta: coge la primera carta Magnético que haya en la parte superior de la pila de descartes del mazo de Encuentros y dáserla a Magneto como carta de aumento boca abajo. Magneto se activa contra ti.","f":"\"¡Ni siquiera vuestros poderes podrán salvaros de mi cólera!\"—Magneto"},
  "32152": {"n":"Sacudida eléctrica","t":"Cuando se muestre esta carta (Alter ego): quedas confundido. Coloca 1 de Amenaza sobre el Plan principal por cada contador de magnetismo que tenga encima.\nCuando se muestre esta carta (Héroe): quedas aturdido. Sufres 1 de Daño por cada contador de magnetismo que haya sobre el Plan principal."},
  "32153": {"n":"Estallido electromagnético","t":"Cuando se muestre esta carta: agota todas las Mejoras y Apoyos que controles. Coloca 1 contador de Magnetismo sobre el Plan principal.\n[star] Aumento: agota tu carta de Superhéroe."},
  "32154": {"n":"Fragmentos de metal","t":"Cuando se muestre esta carta: inflige 1 de Daño a cada personaje que controles. Coloca 1 contador de Magnetismo sobre el Plan principal.\n[star] Aumento: si esto es un ataque y derrota a un Aliado, coloca 1 contador de Magnetismo sobre el Plan principal."},
  "32155": {"n":"Proyectil magnético","t":"Oleada.\nCuando se muestre esta carta: derrota a un Esbirro CENTINELA que esté en juego. Luego sufres 5 de Daño. Puedes descartar X cartas de tu mano para evitar X de ese Daño.","f":"\"¡Debería haberlo visto venir!\"—Cíclope"},
  "32156": {"n":"Malevolencia magnética","t":"Cuando se derrote esta carta: el jugador que haya derrotado este Plan descarta las 4 primeras cartas del mazo de Encuentros. Ese jugador coloca 1 contador de Magnetismo sobre el Plan principal por cada carta con el rasgo Magnético que se haya descartado de este modo."},
  "32157": {"n":"Sellado magnético","t":"Cuando se muestre esta carta: coloca 2 de Amenaza adicional sobre esta carta por cada Aliado que haya en juego.\n[star] Aumento: agota todos los Aliados que controles."},
  "32158": {"n":"¡Apresado!","t":"Cuando se muestre esta carta: cada jugador coloca las 6 primeras cartas de su mazo debajo de esta carta, boca abajo.\nCuando se derrote esta carta: Magneto se activa contra el jugador que haya derrotado este Plan.(Las carta que haya debajo de este Plan se descartan.)"},
  "32159": {"t":"Trabajo en equipo (ACÓLITO). Infame.\nCuando se derrote esta carta: el jugador que haya derrota a Fabian Cortez descarta cartas del mazo de Encuentros hasta que se descarte un Esbirro ACÓLITO, luego pone en juego ese Esbirro enfrentado a él."},
  "32160": {"t":"Firmeza. Trabajo en equipo (ACÓLITO).\nCuando se derrote esta carta: el jugador que haya derrota a Amelia Voght queda confundido. Si ya estaba confundido, coloca 2 de Amenaza sobre el Plan principal."},
  "32161": {"t":"Trabajo en equipo (ACÓLITO).\n[star] Los ataques de Senyaka gana Penetrante.\nCuando se derrote esta carta: el jugador que haya derrota a Senyaka queda aturdido. Si ya estaba aturdido, sufre 3 de Daño."},
  "32162": {"t":"Represalia 1. Trabajo en equipo (ACÓLITO).\nCuando se derrote esta carta: descarta todas las cartas de Estado \"Aturdido\" y \"Confundido\"que tenga el Villano y dale una carta de aumento boca abajo."},
  "32163": {"t":"Trabajo en equipo (ACÓLITO). Dureza.\nCuando se derrote esta carta: dale al Villano una carta de Estado \"Duro\". Si el villano ya tenia una carta de Estado \"Duro\", cúrale 4 de Daño."},
  "32164": {"n":"Fanatismo por la causa","t":"Cuando se muestre esta carta: resuelve la capacidad \"Cuando se derrote esta carta:\" de todos los Esbirros ACÓLITO que estén enfrentados a ti. Si no estás enfrentado a nigún Esbirro ACÓLITO, descarta cartas del mazo de Encuentros hasta que se descarte un Esbirro y luego muéstralo."},
  "32165": {"n":"Los Acólitos","t":"Todos los Esbirros (ACÓLITO) ganan Guardia.\n[star] Aumento: coge todos los Esbirros (ACÓLITO) que haya en la pila de descartes, añádelos al mazo de Encuentros y barájalo."},
  "32166": {"t":"Firmeza. Victoria 1.\nNimrod no puede sufrir más de 3 de Daño en cada fase.","f":"\"He regresado.\""},
  "32167": {"n":"Bastión","t":"Dureza. Infame. Victoria 1.\n[star] Aumento: quédate esta carta como carta de Encuentro boca abajo.","f":"\"Debo destruir a los mutantes para salvaguardar el futuro de la humanidad.\""},
  "32168": {"n":"Portal de Nimrod","t":"Victoria 1.\nCuando se derrote esta carta: siguiendo el orden de jugadores, cada jugador descarta las 2 primeras cartas del mazo de Encuentros y sufre tanto Daño indirecto como el número de iconos de Aumento ([boost]) que se descarten de este modo."},
  "32169": {"n":"Las maquinaciones de Bastión","t":"Victoria 1.\nCuando se muestre esta carta: cada jugador coloca las 9 primeras cartas de su mazo debajo de esta carta, boca abajo.","f":"Bastión ha manipulado el curso de los acontecimientos para hacer realidad el futuro del que procede."},
  "32170": {"n":"Tecnología de Nanocentinela","t":"Victoria 1.\nEl Esbirro vinculado recibe +4 de Vida y gana el rasgo CENTINELA.\nCuando se muestre esta carta: busca a tu Esbirro Archienemigo en el mazo de Encuentros, la pila de descartes y la zona apartada. Ponlo en juego enfrentado a ti y vincúlale esta carta."},
  "32171a": {"n":"Policías asustados","t":"Cuando se derrote esta carta: coge la primera carta del mazo del Futuro pasado, añádela al mazo de Encuentros y barájalo. Dale la vuelta a esta carta y pon en juego la Policía local","f":"\"En pleno caos, la policía ha confundido a la Patrulla-X con el enemigo.\""},
  "32171b": {"n":"Policía local","t":"Permanente.\nEl jugador inicial controla a la Policía local.\nAcción: agota la Policía local → elige entre infligir 1 de Daño a un enemigo o bien quitar 1 de Amenaza de un Plan."},
  "32172a": {"n":"El enemigo de mi enemigo","t":"Cuando se derrote esta carta: coge la primera carta del mazo del Futuro pasado, añádela al mazo de Encuentros y barájalo. Dale la vuelta a esta carta y pon en juego a Magneto controlado por el jugador inicial.","f":"\"Magneto también lucha para proteger a mutantes indefensos de los centinelas."},
  "32172b": {"t":"Victoria 1.\nEl jugador inicial controla a Magneto. No se cuenta de cara a tu límite de Aliados.\nRespuesta: después de que Magneto ataque y derrote a un Esbirro ([CENTINELA]), cura 1 de Daño a Magneto."},
  "32173a": {"n":"Localizar a los prisioneros","t":"Cuando se muestre esta carta: cada jugador busca un Aliado en su mazo y lo coloca boca abajo debajo de esta carta.\nCuando se derrote esta carta: coge la primera carta del mazo del Futuro pasado, añádela al mazo de Encuentros y barájalo. Dale la vuelta a esta carta y muestra Rescatar a los cautivos. (Las cartas que estén boca abajo se mantienen debajo de Rescatar a los cautivos.)"},
  "32173b": {"n":"Rescatar a los cautivos","t":"Respuesta: después de que derrotes a un Esbirro ([CENTINELA]), gasta 1 recurso de cualquier tipo → elige un Aliado que esté boca abajo debajo de esta carta y ponlo en juego controlado por ti. (Cualquier jugador puede aplicar esta capacidad.)"},
  "32174a": {"n":"Ataque sorpresa","t":"Cuando se derrote esta carta: coge la primera carta del mazo del Futuro pasado, añádela al mazo de Encuentros y barájalo. El jugador que haya derrotado este Plan le da la vuelta a esta carta y coloca Restablecer las defensas en su zona de juego."},
  "32174b": {"n":"Restablecer las defensas","t":"Acción de Alter ego: gasta recursos [energy][mental][physical] → inflige 5 de Daño a cada enemigo que esté en juego. Retira esta carta de la partida."},
  "32175a": {"n":"La fortaleza de Magneto","t":"Cuando se derrote esta carta: coge la primera carta del mazo del Futuro pasado, añádela al mazo de Encuentros y barájalo. Dale la vuelta a esta carta.","f":"\"Magneto se ha anticipado a vuestro ataque y ha fortificado su santuario orbital."},
  "32175b": {"n":"El poder de Magneto","t":"Vincula esta carta a Magneto.\nPermanente."},
  "32176": {"n":"Golpe de gracia","t":"Interrupción de Héroe: cuando ataques, este ataque inflige 3 de Daño adicional y gana Brutalidad. Retira esta carta de la partida y de la campaña.","f":"\"¡Cuidado, que voy!\"—Rondador Nocturno"},
  "32177": {"n":"Chuleria","t":"Interrupción de Héroe (defensa): cuando realices una defensa básica, recibes +3 DEF. Prepara tu Héroe. Retira esta carta de la partida y de la campaña.","f":"\"Adelante, nene. ¡Alégranos el día!\"—Lobezno"},
  "32178": {"n":"Defensa impetuosa","t":"Interrupción de Héroe (ataque/defensa): cuando un enemigo ataque, gasta 1 recurso de cualquier tipo → evita 3 de Daño de ese ataque e inflige 3 de Daño a ese enemigo. Retira esta carta de la partida y de la campaña."},
  "32179": {"n":"Agresión feroz","t":"Acción de Héroe (ataque): gasta 3 recursos de cualquier tipo → inflige 6 de Daño a un enemigo y prepara tu Héroe. Retira esta carta de la partida y de la campaña."},
  "32180": {"n":"Grito de guerra","t":"Recurso de Héroe: genera recursos [wild][wild] para un Evento de ([ATAQUE]) o ([DEFENSA]). Ganas una carta de Estado \"Duro\". Retira esta carta de la partida y de la campaña.","f":"\"¡Rrrrrrraaaaargh!\"—Lobezno"},
  "32181": {"n":"Golpe de gracia","t":"Interrupción de Héroe: cuando ataques, este ataque inflige 3 de Daño adicional y gana Brutalidad. Retira esta carta de la partida y de la campaña.","f":"\"¡Cuidado, que voy!\"—Rondador Nocturno"},
  "32182": {"n":"Compasión","t":"Respuesta de Alter ego: después de que te recuperes, cura 3 de Daño en total entre todos los personajes que controles y roba 1 carta. Retira esta carta de la partida y de la campaña.","f":"\"Todos hemos pasado por lo mismo, hijo.\"—Cíclope"},
  "32183": {"n":"Atacar en grupo","t":"Acción de Héroe: hasta el final de la fase, evita todo el Daño derivado que vaya a sufrir cada Aliado al atacar. Retira esta carta de la partida y de la campaña."},
  "32184": {"n":"Despliegue abrumador","t":"Acción de Héroe (ataque): gasta 3 recursos de cualquier tipo → inflige 6 de Daño a un enemigo y prepara todos los Aliados que controles. Retira esta carta de la partida y de la campaña."},
  "32185": {"n":"Improvisación","t":"Recurso de Héroe: genera recursos [wild][wild] para un Evento de ([ATAQUE]) o ([TÁCTICA]). Prepara un Aliado y cúrale 2 de Daño. Retira esta carta de la partida y de la campaña."},
  "32186": {"n":"Chuleria","t":"Interrupción de Héroe (defensa): cuando realices una defensa básica, recibes +3 DEF. Prepara tu Héroe. Retira esta carta de la partida y de la campaña.","f":"\"Adelante, nene. ¡Alégranos el día!\"—Lobezno"},
  "32187": {"n":"¡Sorpresa!","t":"Respuesta de Héroe: después de que intervengas, quita 3 de Amenaza en total de entre todos los Planes que haya en juego. Confunde a un enemigo. Retira esta carta de la partida y de la campaña.","f":"\"¡Guten Tag!\"—Rondador Nocturno"},
  "32188": {"n":"Intervención heroica","t":"Acción de Héroe (intervención): gasta 3 recursos de cualquier tipo → quita 5 de Amenaza en total entre todos los Planes que haya en juego. Ganas una carta de Estado \"Duro\". Retira esta carta de la partida y de la campaña."},
  "32189": {"n":"Defensa firme","t":"Interrupción de Héroe (defensa/intervención): cuando defiendas contra un ataque, gasta 2 recursos de cualquier tipo → ese ataque quita Amenaza del Plan principal en vez de infligir Daño. Retira esta carta de la partida y de la campaña."},
  "32190": {"n":"Guardaespaldas","t":"Recurso de Héroe: genera recursos [wild][wild] para un Evento de ([DEFENSA]) o ([INTERVENCIÓN]). Roba 1 carta. Retira esta carta de la partida y de la campaña.","f":"\"Atrás.\"—Cíclope"},
  "32191": {"n":"¡Sorpresa!","t":"Respuesta de Héroe: después de que intervengas, quita 3 de Amenaza en total de entre todos los Planes que haya en juego. Confunde a un enemigo. Retira esta carta de la partida y de la campaña.","f":"\"¡Guten Tag!\"—Rondador Nocturno"},
  "32192": {"n":"Compasión","t":"Respuesta de Alter ego: después de que te recuperes, cura 3 de Daño en total entre todos los personajes que controles y roba 1 carta. Retira esta carta de la partida y de la campaña.","f":"\"Todos hemos pasado por lo mismo, hijo.\"—Cíclope"},
  "32193": {"n":"Operación de rescate","t":"Acción de Héroe: hasta el final de la fase, evita todo el Daño derivado que vaya a sufrir cada Aliado al intervenir. Retira esta carta de la partida y de la campaña."},
  "32194": {"n":"Tutela","t":"Acción de Héroe (intervención): gasta 3 recursos de cualquier tipo → quita 5 de Amenaza en total entre todos los Planes que haya en juego. Prepara todos los Aliados que controles. Retira esta carta de la partida y de la campaña."},
  "32195": {"n":"Fortaleza","t":"Recurso de Héroe: genera recursos [wild][wild] para un Evento de ([TÁCTICA]) o ([INTERVENCIÓN]). Aturde a un enemigo. Retira esta carta de la partida y de la campaña."},
  "33001a": {"n":"Cíclope","t":"Rayo óptico - Acción (ataque): gasta 1 recurso de cualquier tipo → infige 3 de Daño a un enemigo que tenga vinculada una Mejora. (Límite de una vez por ronda.)","f":"\"El profesor tenía un sueño; yo tengo un plan.\""},
  "33001b": {"t":"Puedes incluir en tu mazo Aliados PATRULLA-X de cualquier aspecto.\nEntrenamiento constante - Acción: busca en tu mazo una Mejora TÁCTICA y añádela a tu mano. (Límite de una vez por ronda.)."},
  "33002": {"n":"Fénix","t":"Respuesta: después de que Fénix entre en juego, elige una carta de Cíclope que esté en tu pila de descartes y añádela a tu mano.","f":"\"Estamos en esto juntos, Scott. Hasta que la muerte nos separe.\""},
  "33003": {"n":"Visor de cuarzo de rubí","t":"Recurso de Héroe: agota esta carta → genera un recurso [energy] para tu capacidad \"Rayo óptico\". Ese ataque gana A distancia y Penetrante.","f":"\"El visor de Cíclope le ayuda a concentrar y controlar sus rayos ópticos.\""},
  "33004": {"n":"Dotes de mando","t":"Tú juegas el primer turno durante la fase de los jugadores. (Cuando termine tu turno, se reanuda el orden de jugadores empezando por el jugador inicial. Tú no juegas otro turno.)\nTodas las Mejoras de Cíclope vinculadas a un Esbirro pierden la palabra clave Temporal."},
  "33005": {"n":"Aprovechar una debilidad","t":"Vincula esta carta a un enemigo. Máximo de 1 por enemigo.\nTemporal.\nAumenta en 1 el Daño que sufre el enemigo vinculado en cada ataque."},
  "33006": {"n":"Defensa practicada","t":"Vincula esta carta a un enemigo. Máximo de 1 por enemigo.\nTemporal.\nEl enemigo vinculado recibe -1 ATQ."},
  "33007": {"n":"Objetivo prioritario","t":"Vincula esta carta a un enemigo. Máximo de 1 por enemigo.\nTemporal.\nInterrupción: cuando el enemigo vinculado sea derrotado, el jugador que lo haya derrotado roba 2 cartas."},
  "33008": {"n":"Rayo a plena potencia","t":"Interrupción de Héroe: cuando uses tu capacidad \"Rayo óptico\", agota a Cíclope → este ataque inflige 8 de Daño adicional y gana Brutalidad.","f":"\"Quiero esta cosa fuera de mi césped.\" —Cíclope"},
  "33009": {"n":"Rayo rebotado","t":"Acción de Héroe (ataque): inflige 3 de Daño a un enemigo. Inflige 3 de Daño a un enemigo que tenga una Mejora vinculada.","f":"\"Rayo óptico, banda izquierda y a la tronera de la esquina.\" —Cíclope"},
  "33010": {"n":"Agudeza táctica","t":"Acción de Héroe (intervención): quita 3 de Amenaza de un Plan. Elige una carta TÁCTICA que esté en tu pila de descartes y añádela.","f":"\"Aunque sus rayos ópticos son formidables, el verdadero poder de Cíclope reside en su capacidad para inspirar a su equipo y conducirlos a la victoria.\""},
  "33011": {"n":"Bestia","t":"Respuesta: después de que Bestia entre en juego, busca una carta de Recurso en tu mazo y en tu pila de descartes y añádela a tu mano. (Baraja el mazo.)","f":"\"¡Oh, por las barras y estrellas!\""},
  "33012": {"n":"Arena","t":"[star] Interrupción: cuando Arena ataca a un Esbirro, ataca a todos los Esbirros que estén en juego. Arena sufre +1 de Daño derivado ([cost]) después de este ataque.","f":"\"Muy bien. ¡No me contrendré!\""},
  "33013": {"n":"Alud","t":"Represalia 1.","f":"\"Caeré peleando. Porque soy un hombre-X, y eso es lo que hacen los hombres-X.\""},
  "33014": {"n":"Vendas","t":"Respuesta: después de que Vendas entre en juego, mira las 5 primeras cartas del mazo de Encuentros. Descarta 1 de esas cartas y devuelve el resto al mazo colocándolas en el mismo orden.","f":"\"Para encontrar algo que es invisible, necesitas tener los ojos invisibles.\""},
  "33015": {"n":"Entrenamiento en la Sala de Peligro","t":"Vincula esta carta a un Aliado Patrulla-X. Máximo de 1 Mejora ENTRENAMIENTO por Aliado.\nEl Aliado vinculado recibe +1 INT, +1 ATQ y +1 de Vida."},
  "33016": {"n":"Ataque coordinado","t":"Vincula esta carta a un Esbirro. Máximo de 1 por Esbirro.\nCada Aliado sufre -1 de Daño derivado ([cost]) cuando ataca al Esbirro vinculado."},
  "33017": {"n":"Trabajo en equipo","t":"Interrupción de Héroe: cuando uses tu atributo básico de Intervención (INT) o tu atributo básico de Ataque (ATQ), agota un Aliado que controles → suma el atributo correspondiente de ese Aliado al de tu Héroe para este uso."},
  "33018": {"n":"Liderazgo eficaz","t":"Máximo de 2 por mazo.\nInterrupción: cuando gastes esta carta para jugar un Aliado, ese Aliado recibe +1 INT y +1 ATQ hasta el final de la fase."},
  "33019": {"n":"Ángel","t":"Reduce en 1 el coste para jugar al Ángel si tu Superhéroe tiene el rasgo MUTANTE o PATRULLA-X.","f":"\"¡Lo único mejor que ser multimillonario es ser un multimillonario capaz de volar!\" —Ángel"},
  "33020": {"n":"Utopía","t":"Si todos tus Aliados tienen el rasgo PATRULLA-X, tu límite de Aliados se incrementa en 1.\nRespuesta: después de que entre en juego un Aliado PATRULLA-X, agota Utopía → prepara un personaje PATRULLA-X."},
  "33021": {"n":"Sala de Peligro","t":"Respuesta de Alter ego : después de que entre en juego un Aliado PATRULLA-X, agota la Sala de Peligro → busca una Mejora ENTRENAMIENTO en tu mazo y tu pila de descartes y vincúlala a ese Aliado. Cualquier jugador cuyo Alter ego tenga el rasgo MUTANTE puede aplicar esta capacidad."},
  "33022": {"n":"Hora de jugar","t":"Acción de Héroe: elige un Aliado que tenga vinculada una Mejora ENTRENAMIENTO → prepara ese Aliado y cúrale 1 de Daño.","f":"\"Adelante,Patrulla-X. ¡Tal y como lo ensayamos!\" -Cíclope"},
  "33023": {"n":"Conexión Psíquica","t":"Equipo (Cíclope y Fénix). Máximo de 1 por mazo.\nAcción de Héroe: prepara a Cíclope y a Fénix. Elige entre devolver a tu mano una carta de Cíclope que esté en tu pila de descartes, o bien colocar 2 contadores de Poder sobre la Fuerza Fénix."},
  "33024": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "33025": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "33026": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "33027": {"n":"Visor perdido","t":"Dale esta carta al jugador que lleva a Scott Summers.\nBusca el Visor de cuarzo de rubí en tu mano, mazo, pila de descartes y zona de juego, y colócalo boca abajo debajo de esta carta.\nCíclope no puede atacar.\nAcción de Alter ego: agota a Scott Summers → añade el Visor de cuarzo de rubí a tu mano y retira de la partida Visor perdido."},
  "33028": {"n":"Mister Siniestro","t":"Firmeza. Dureza. Infame.\n[star] Aumento: quedas aturdido. Si ya estabas aturdido, sufres 2 de Daño.","f":"\"El destino de la raza mutante está en mis manos.\""},
  "33029": {"n":"Manipulación genética","t":"Cuando se derrote esta carta: busca Terapia genética en el mazo de Encuentros y en su pila de descartes y muéstrala. (Baraja el mazo.)","f":"\"Mister Siniestro emplea genes mutantes para aumentar sus propios poderes.\""},
  "33030": {"n":"Terapia genética","t":"Vincula esta carta al enemigo que tenga el valor impreso más bajo de ATQ y que no tenga ya vinculada una copia de Terapia genética. De no ser posible, esta carta gana Oleada.\n[star] Interrupción obligada: cuando el enemigo vinculado ataque, el ataque gana Brutalidad y Penetrante. Al final de este ataque, descarta Terapia genética."},
  "33031": {"n":"Rayo de impacto","t":"Cuando se muestre esta carta(Alter ego): si Mister Siniestro está en juego, ejecuta el Plan. De no ser así, coloca 2 de Amenaza sobre el Plan principal.\nCuando se muestre esta carta(héroe): si Mister Siniestro está en juego, te ataca. De no ser así, sufres 2 de Daño."},
  "33032": {"n":"A tiro","t":"Vincula esta carta a un Esbirro. Máximo de 1 por Esbirro.\nLos ataques efectuados contra el Esbirro vinculado ganan Brutalidad.","f":"\"Objetivo a tiro.\" -Dominó"},
  "33033": {"n":"Desconcierto","t":"Vincula esta carta a un Esbirro. Máximo de 1 por Esbirro.\nInterrupción: cuando un personaje realice un ataque básico contra el Esbirro vinculado, ese personaje una su INT en vez de su ATQ."},
  "33034": {"n":"Retenido","t":"Vincula esta carta a un Esbirro. Máximo de 1 por Esbirro.\nEl Esbirro vinculado recibe -2 ATQ.","f":"\"¡Tío, cálmate un poco!\" -Alud"},
  "33035": {"n":"Miembro honorario de la Patrulla-X","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo PATRULLA-X.\nVincula esta carta a un personaje amigo. Maximo de 1 por personaje.\nEl personaje vinculado recibe +1 de Vida y gana el rasgo PATRULLA-X."},
  "34001a": {"n":"Fénix","t":"Vínculo psiónico - Recurso de Héroe: quita 1 contador de Poder de la Fuerza Fénix → genera un recurso [wild]. (Límite de una vez por fase).","f":"\"¡La Fuerza Fénix me ha escogido, pero sólo yo decido quién soy!\""},
  "34001b": {"t":"Preparación: pon en juego tu Mejora Fuerza Fénix, con la cara de CONTENIDA boca arriba. Colócale encima 4 contadores de Poder.\n[star] Respuesta: después de que realices una recuperación básica, coloca 1 contador de Poder sobre la Fuerza Fénix."},
  "34002a": {"n":"Fuerza Fénix A","t":"Permanente.\nGanas el rasgo CONTENIDA.\nRespuesta obligada: después de que se quite el último contador de Poder de esta carta, dale la vuelta a esta carta."},
  "34002b": {"n":"Fuerza Fénix B","t":"Permanente.\nGanas el rasgo DESATADA.\nFénix recibe -2 INT y +2 ATQ.\nRespuesta obligada: después de que se coloque un contador de Poder sobre esta carta, si hay al menos 4 contadores de Poder sobre ella, dale la vuelta a esta carta."},
  "34003": {"n":"Cíclope","t":"Respuesta: después de que Cíclope entre en juego, coloca 2 contadores de Poder sobre la Fuerza Fénix.\nInterrupción obligada: cuando Cíclope abandone el juego, quita 2 contadores de Poder de la Fuerza Fénix."},
  "34004": {"n":"La Sala Blanca","t":"Acción de Alter ego: agota La Sala Blanca → elige una opción:\n• Coloca 1 contador de Poder sobre la Fuerza Fénix.\n• Cura 2 de Daño a Jean Grey."},
  "34005": {"n":"Traje de Fénix","t":"Fénix gana el rasgo AÉREO.\nMientras tengas el rasgo CONTENIDA, ganas Tesón.\nMientras tengas el rasgo DESATADA, ganas Represalia 1."},
  "34006": {"n":"Resurgir de las cenizas","t":"Interrupción: cuyo vayas a ser derrotado, retira esta carta de la partida → en vez de eso, prepara tu Superhéroe y restablece su Vida a su valor impreso. Quita todos los contadores de Poder que haya sobre la Fuerza Fénix."},
  "34007": {"n":"Escudo telequinético","t":"Vincula esta carta a un personaje amigo.\nInterrupción obligada: cuyo el personaje vinculado vaya a sufrir Daño a consecuencia del ataque de un enemigo, en vez de eso coloca ese Daño sobre esta carta. Luego, si hay al menos 5 de Daño sobre esta carta, descarta el Escudo telequinético."},
  "34008": {"n":"Parálisis mental","t":"Sólo identidad de Héroe. Vincula esta carta a un Ebirro que no sea de ÉLITE.\nEl Esbirro vinculado no puede activarse.\nInterrupción obligada: después de que cambies a la identidad de tu Alter ego, descarta esta carta."},
  "34009": {"n":"Control mental","t":"Vincula esta carta a un Ebirro que no sea de ÉLITE.\nToma el control del Esbirro vinculado y trátalo como su fuese un Aliado CONTROLADO con el texto de reglas en blanco. Su valor de INT a su valor de PLA, y sufre 1 de Daño derivado después de intervenir o atacar."},
  "34010": {"n":"Ataque telequinético","t":"Acción de Héroe (ataque): inflige 7 de Daño a un enemigo. Si tienes el rasgo DESATADA, este ataque inflige 2 de Daño adicional y gana Brutalidad.","f":"\"¡Pobre iluso!¡No tienes ni idea de lo desesperada que es tu situación!\" - Fénix"},
  "34011": {"n":"Estallido psíquico","t":"Acción de Héroe: inflige 4 de Daño al Villano. Si tienes el rasgo DESATADA, inflige 4 de Daño a cada Esbirro que esté enfrentado a ti.","f":"\"Lucharemos en campos de batalla distintos. Tu fuerza no te servirá de nada en el mío.\" - Fénix"},
  "34012": {"n":"Ardid telepático","t":"Acción de Héroe (intervención): quita 4 de Amenaza de un Plan. Si tienes el rasgo DESATADA, aturde y confunde a un enemigo.","f":"\"No pueden vernos porque yo no se lo permito.\" - Fénix"},
  "34013": {"n":"Fénix de Fuego","t":"Acción de Héroe: elige una opción:\n• quita 1 contador de Poder de la Fuerza Fénix → prepara a Fénix.\n• Coloca 2 contadores de Poder sobre la Fuerza Fénix."},
  "34014": {"t":"[star] Respuesta: después de que Banshee intervenga, confunde a un Esbirro.","f":"\"Iros tapando los oídos, chicos... ¡esto va a doler un poco!\""},
  "34015": {"n":"Chica Maravillosa","t":"[star] Interrupción: cuando la Chica Maravillosa Ataque a un Esbirro, quita X de Amenaza del Plan principal, siendo X igual al valor impreso de PLA de ese Esbirro.","f":"\"Sea lo que sea lo que trames, se acabó.\""},
  "34016": {"n":"Entrenado para la misión","t":"Vincula esta carta a un Aliado PATRULLA-X. Máximo de 1 Mejora ENTRENAMIENTO por Aliado.\nEl Aliado vinculado recibe +1 INT y +2 de Vida."},
  "34017": {"n":"Manipulación psíquica","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo PSIÓNICO.\nInterrupción (intervención): cuando el Villano ejecute el Plan, esta activación quita Amenaza en vez de colocarla."},
  "34018": {"n":"Pacificadores mutantes","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo PATRULLA-X.\nAcción de Héroe (intervención): agota tu Héroe y cualquier número de Aliados PATRULLA-X → quita X de Amenaza en total de entre todos los Planes que haya en juego, siendo X el valor total de INT que suman todos esos personajes."},
  "34019": {"n":"Castigo inmediato","t":"Acción de Héroe (ataque): el Villano ejecuta el Plan. Inflige 4 de Daño al Villano.","f":"\"Devolved lo que habéis robado y os dejaré marchar. Por esta vez. Pero la próxima no tendréis tanta suerte. Y yo no seré tan generoso.\" —Caballero Luna"},
  "34020": {"n":"Pasión por la justicia","t":"Máximo de 2 por mazo.\nInterrupción: cuando gastes esta carta para jugar un Evento de INTERVENCIÓN, ese Evento quita 1 de Amenaza adicional."},
  "34021": {"n":"Tormenta","t":"Reduce en 1 el coste para jugar a Tormenta si tu Superhéroe tiene el rasgo MUTANTE o PATRULLA-X.\n[star] Interrupción: cuando Tormenta intervenga contra un Plan, traslada 2 de Amenaza desde ese Plan hasta otro Plan."},
  "34022": {"t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo MUTANTE.\nAcción de Alter ego: agota Cerebro → busca un Aliado PATRULLA-X entre las 5 primeras cartas de tu mazo (busca en todo tu mazo si controlas un personaje PSIÓNICO) y añade ese Aliado a tu mano. (Baraja el mazo.)"},
  "34023": {"n":"Conexión Psíquica","t":"Equipo (Cíclope y Fénix). Máximo de 1 por mazo.\nAcción de Héroe: prepara a Cíclope y a Fénix. Elige entre devolver a tu mano una carta de Cíclope que esté en tu pila de descartes, o bien colocar 2 contadores de Poder sobre la Fuerza Fénix."},
  "34024": {"n":"Tomarse un respiro","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nTu Alter ego recibe +2 REC.","f":"\"Deberíamos hacer esto más a menudo.\""},
  "34025": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "34026": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "34027": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "34028": {"n":"Un fuego insaciable","t":"Dale esta carta al jugador que lleva a Jean Grey.\nCuando se muestre esta carta: si tienes el rasgo DESATADA, busca a Fénix Oscura en el mazo de Encuentros, en su pila de descartes y en la zona apartada, y méstrala. Luego retira de la partida Un fuego insaciable. Si tienes el rasgo CONTENIDA, quita 1 contador de Poder de la Fuerza Fénix y esta carta gana Oleada. Descarta esta carta."},
  "34029": {"n":"Fénix Oscura","t":"Tesón. Dureza. Infame.\n[star] Cuando Fénix Oscura ejecute el Plan, coloca esa Amenaza sobre Consumir el mundo (si es posible).\nCuando se muestre esta carta: busca Consumir el mundo en el mazo de Encuentros,en su pila de descartes y en la zona apartada, y muéstralo."},
  "34030": {"n":"Consumir el mundo","t":"Permanente.\nMientras no haya Amenaza sobre esta carta, este Plan pierde el icono bla.\nRespuesta obligada: después de que se coloque Amenaza sobre esta carta, si hay al menos 12 de Amenaza sobre ella, los jugadores pierden la partida."},
  "34031": {"n":"Rabia ardiente","t":"Peligro. (Mientras estés resolviendo esta carta, los demás jugadores no podrán ayudarte.)\nCuando se muestre esta carta: si Fénix Oscura está en juego, se activa contra ti. Si Fénix Oscura no está en juego, coloca 1 de Amenaza sobre Consumir el mundo y esta carta gana Oleada."},
  "34032": {"n":"Agresión psíquica","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo PSIÓNICO.\nAcción de Héroe (ataque): inflige 3 de Daño a un enemigo. Confunde a ese enemigo."},
  "34033": {"n":"Desvío psíquico","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo PSIÓNICO.\nInterrupción de Héroe (defensa): cuando un enemigo te ataque, elige un enemigo distinto → el Daño de ese ataque se inflige al enemigo elegido en vez de a ti."},
  "34034": {"n":"Estímulo psíquico","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo PSIÓNICO.\nAcción de Héroe: prepara un Aliado. Ese Aliado recibe +2 INT y +2 ATQ para su próxima acción básica de intervención o ataque en esta fase."},
  "34035": {"n":"Hermanas del alma","t":"Equipo (Fénix y Tormenta). Máximo de 1 por mazo.\nAcción de Héroe: prepara a Fénix y a Tormenta. Cura 2 de Daño a cada una de ellas."},
  "35001a": {"n":"Lobezno","t":"Factor curativo - Respuesta: después de que empiece la fase de los Jugadores, cúrate 2 de Daño.","f":"\"Soy el mejor en lo que hago, pero lo que hago no es muy agradecido.\""},
  "35001b": {"t":"Snikt! - Preparación: busca en tu mazo y tu pila de descartes la Mejora Garras de Lobezno y ponla en juego.","f":"\"Soy canadiense, nene ¡Y a mucha honra!\""},
  "35002": {"n":"Garras de Lobezno","t":"Permanente.\nAcción de Héroe: agota las Garras de Lobezno, elige un Evento de ATAQUE de tu mano, y sufre tanto Daño como su coste impreso → juega ese Evento ignorando su coste en recursos. Ese ataque gana Penetrante."},
  "35003": {"n":"Júbilo","t":"Respuesta: después de que Júbilo entre en juego, elige un enemigo. Hasta el final de la fase, mientras Lobezno o Júbilo estén realizando un ataque básico contra ese enemigo, reciben +2 ATQ para ese ataque."},
  "35004": {"n":"Esqueleto de adamántium","t":"Recibes +4 de Vida.\nLobezno recibe +1 ATQ y sus ataques básicos ganan Penetrante.","f":"\"Los huesos de Lobezno poseen un revestimiento de adamántium que los hace irrompibles.\""},
  "35005": {"n":"Frenesí rabioso","t":"Respuesta de Héroe: después de que Lobezno sufra cualquier cantidad de Daño a consecuencia de un ataque enemigo, roba 1 carta.\nRespuesta obligada: después de que cambies a la identidad de tu Alter ego, descarta esta carta."},
  "35006": {"n":"\"Me mataron y mejoré\"","t":"Interrupción: cuando vayas a ser derrotado por un ataque enemigo, en vez de eso fija tu medidor de Vida en 5, prepara tu carta de Superhéroe y descarta esta carta."},
  "35007": {"n":"La cabaña de Logan","t":"Acción de Alter ego: agota La cabaña de Logan → coge 1 carta de Lobezno de tu pila de descartes, añádela a tu mazo y barájalo.","f":"\"Logan es de naturaleza solitaria, y suele retirarse a su cabaña cuando necesita estar apartado del mundo.\""},
  "35008": {"n":"Torbellino de garras","t":"Acción de Héroe (ataque): inflige 4 de Daño a un enemigo. Si este ataque derrota a un enemigo, puedes sufrir 2 de Daño → vuelve a usar esta capacidad.","f":"\"¡Tú no sabes lo que es una buena escabechina hasta que me hayas visto cabreado!\" -Lobezno"},
  "35009": {"n":"Hacer picadillo","t":"Acción de Héroe: efectúa los 2 ataques siguientes por orden:\n• inflige 3 de Daño a un enemigo.\n• inflige 3 de Daño a un enemigo."},
  "35010": {"n":"Tirarse de cabeza","t":"Acción de Héroe (ataque): inflige 8 de Daño a un enemigo. Si has agotado las Garras de Lobezno para jugar esta carta, este ataque gana Brutalidad.","f":"\"No te habrás olvidado de mí, ¿verdad?.\" -Lobezno"},
  "35011": {"n":"Guiarse por el olfato","t":"Acción de Héroe (intervención): quita 3 Amenaza de un Plan. Si con esto se quita la última ficha de Amenaza de ese Plan, roba 2 cartas.","f":"\"Una vez que capto su olor, puedo seguirlos a cualquier parte.\" -Lobezno"},
  "35012": {"n":"Curación regenerativa","t":"Acción: elige una opción:\n• Cura 4 de Daño a tu Superhéroe.\n• Descarta todas las cartas de Estado \"Aturdido\" y \"Confundido\" de tu Superhéroe."},
  "35013": {"n":"Mariposa Mental","t":"Mariposa Mental entra en juego con 2 contadores Psiónicos.\n[star] Interrupción: cuando Mariposa Mental ataque a un enemigo, quítale 1 contador Psiónico → confunde a ese enemigo e inflígele 1 de Daño."},
  "35014": {"n":"Fuego Solar","t":"Respuesta: después de que juegues a Fuego Solar desde tu mano, gasta un recurso [energy] → elige un Accesorio que tenga el encabezado \"Acción de Héroe\" o \"Respuesta de Héroe\" y descártalo."},
  "35015": {"n":"Furia de combate","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nRespuesta: después de que tu Héroe ataque y derrote a un Esbirro, inflige 1 de Daño a tu Héroe y descarta Furia de combate → prepara a tu Héroe."},
  "35016": {"n":"Habilidad de guerrero","t":"Usos (3 contadores de Guerrero). Máximo de 1 por jugador.\nInterrupción: cuando tu Héroe ataque, quita 1 contador de Guerrero de esta carta → ese ataque inflige 1 de Daño adicional."},
  "35017": {"n":"¡Fuera de mi camino!","t":"Acción de Héroe (ataque): inflige 3 de Daño a un enemigo (5 de Daño si ese enemigo tiene la palabra clave Guardia o Patrulla)."},
  "35018": {"n":"Ataque de precisión","t":"Acción de Héroe (ataque): inflige 2 de Daño a un enemigo. Si este ataque derrota a ese enemigo, cura 2 de Daño a tu Héroe.","f":"Un ataque concentrado suele ser más eficaz que la mera fuerza bruta"},
  "35019": {"n":"Golpetazo","t":"Interrupción de Héroe: cuando tu Héroe realice un ataque básico, agota una Mejora ARMA vinculada a tu Héroe → tu Héroe recibe +3 ATQ para este ataque.","f":"¡PUM!"},
  "35020": {"n":"Energía agresiva","t":"Máximo de 2 por mazo.\nInterrupción de Héroe: cuando gastes esta carta para jugar un Evento de ATAQUE, ese Evento inflige 1 de Daño adicional."},
  "35021": {"n":"Coloso","t":"Reduce en 1 el coste para jugar a Coloso si tu Superhéroe tiene el rasgo MUTANTE o PATRULLA-X.\nDureza.","f":"\"¡Ponte detrás de mí, tovarisch!\""},
  "35022": {"n":"Arma X","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo MUTANTE.\nAcción de Alter ego: agota Arma X y sufre 1 de Daño → descarta cartas de tu mazo hasta que descartes una carta específica de un Superhéroe, luego añade esa carta a tu mano."},
  "35023": {"n":"Bola rápida especial","t":"Equipo (Coloso y Lobezno). Máximo de 1 por mazo.\nAcción de Héroe (ataque): inflige X de Daño a un enemigo, siendo X la suma de los valores de ATQ de Coloso y Lobezno. Este ataque gana Brutalidad y Penetrante."},
  "35024": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "35025": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "35026": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "35027": {"n":"Demonios del pasado","t":"Dale esta carta al jugador que lleva a Logan.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n• Agota a Logan → retira de la partida Demonios del pasado.\n• Quedas aturdido y confundido. Descarta esta carta."},
  "35028": {"n":"Rojo Omega","t":"Represalia 1. Tesón.\n[star] Interrupción obligada: cuando Rojo Omega te ataque, inflige 1 de Daño a todos los personajes que controles.","f":"\"¡Mi factor letal absorberá la vida de tu cuerpo!\""},
  "35029": {"n":"El sintetizador de carbonádium","t":"Mientras esté en juego El sintetizador de carbonádium, Rojo Omega no puede ser derrotado.","f":"\"Rojo Omega necesita el sintetizador de carbonádium para evitar que su propio factor letal lo mate.\""},
  "35030": {"n":"Factor letal","t":"Vincula esta carta a tu Superhéroe.\nRespuesta obligada: después de que termine tu turno, sufres 1 de Daño.\nInterrupción de Alter ego: cuando realices una recuperación básica, descarta esta carta en vez de curar Daño."},
  "35031": {"n":"Golpe de Tentáculo","t":"Cuando se muestre esta carta: quedas aturdido. Sufres 1 de Daño (4 de Daño si ya estabas aturdido).\n[star] Aumento: Aumento: quedas aturdido. Sufres 1 de Daño (4 de Daño si ya estabas aturdido)."},
  "35032": {"n":"Centro de mando","t":"Máximo de 1 por jugador.\nRespuesta: después de que un Aliado intervenga y derrote un Plan secundario, agota el Centro de mando → inflige 2 de Daño a un enemigo."},
  "35033": {"t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo PATRULLA-X.\n[star] Respuesta: después de que Longshot ataque a un Esbirro que no sea de ÉLITE, descarta la primera carta del mazo de Encuentros. Si esa carta tiene un icono de estrella ([star]) en el recuadro de aumentos, derrota al Esbirro atacado."},
  "35034": {"n":"Dama Mortal","t":"Ataque veloz.\n[star] Respuesta obligada: después de que Dama Mortal ataque e inflija Daño a un personaje, el propietario de ese personaje descarta 1 carta de su mano al azar.","f":"\"¡Esta vez te arrancaré el corazón del pecho!\""},
  "35035": {"n":"En busca de venganza","t":"Cuando se muestre esta carta: si Dama Mortal está en juego, se activa contra ti. De no ser así, busca a Dama Mortal en el mazo y la pila de descartes de Encuentros y ponla en juego enfrentada a ti."},
  "35036": {"n":"Mejoras de adamántium","t":"Vincula esta carta a un enemigo que no tenga ya vinculada una copia de Mejoras de adamántium. De no ser posible, esta carta gana Oleada.\n[star] Los ataques del enemigo vinculado ganan Penetrante.\nAcción de Héroe: gasta recursos [energy] [mental] [physical] → descarta esta carta."},
  "35037": {"n":"Descuartizamiento","t":"Cuando se muestre esta carta: descarta 1 carta de tu mano al azar y sufre tanto Daño como el número de recursos impresos en ella.\n[star] Aumento: Aumento: descarta 1 carta de tu mano al azar y sufre tanto Daño como el número de recursos impresos en ella."},
  "36001a": {"n":"Tormenta","t":"Control del clima - Acción: intercambia el Apoyo CLIMA que tienes en juego por un Apoyo de tu elección del mazo de CLIMA. Resuelve la capacidad \"Especial\" del Apoyo CLIMA que tienes en juego. (Límite de una vez por ronda)."},
  "36001b": {"t":"Ororo Munroe empieza la partida con un mazo de CLIMA (ver hoja de reglas.)\n\"Se avecina una tormenta...\" - Preparación: elige un Apoyo del mazo de CLIMA y ponlo en juego."},
  "36002": {"n":"Cielo despejado","t":"Permanente.\nTodos los personajes ganan Firmeza.\nEspecial: roba 1 carta."},
  "36003": {"n":"Huracán","t":"Permanente.\nTodos los personajes ganan Represalia 1.\nEspecial: quita 2 de Amenaza de un Plan."},
  "36004": {"n":"Tormenta eléctrica","t":"Permanente.\nTodos los personajes reciben +1 ATQ.\nEspecial: inflige 2 de Daño a un enemigo."},
  "36005": {"n":"Ventisca","t":"Permanente.\nTodos los personajes reciben -1 ATQ.\nEspecial: elige un Esbirro que no sea de ÉLITE → hasta el final de la ronda, el texto de reglas de ese Esbirro se trata como si estiviese en blanco (a excepción de los RASGOS)."},
  "36006": {"n":"Diadema de Tormenta","t":"Tormenta recibe +1 INT.\nRecurso de Héroe: agota la Diadema de Tormenta → genera el recurso impreso en tu Apoyo CLIMA."},
  "36007": {"n":"Capa de Tormenta","t":"Tormenta recibe +1 DEF y gana el rasgo AÉREO.\nRespuesta de Héroe: después de que resuelvas la capacidad \"Especial\" de tu Apoyo CLIMA, agota la Capa de Tormenta → prepara a Tormenta."},
  "36008": {"n":"El jardín de Ororo","t":"Acción de Alter ego: agota El jardín de Ororo → cura 2 de Daño a tu Superhéroe.","f":"\"La auténtica medida de una vida es vivirla.\" -Tormenta"},
  "36009": {"n":"Diosa de los elementos","t":"Acción de Héroe: intercambia el Apoyo CLIMA que tienes en juego por un Apoyo de tu elección del mazo de CLIMA. Resuelve la capacidad \"Especial\" del Apoyo CLIMA que tienes en juego.","f":"\"¡Los elementos dirigen su infinito poder a mis órdenes!\" -Tormenta"},
  "36010": {"n":"Lluvia torrencial","t":"Acción de Héroe (intervención): quita un total de 3 de Amenaza de entre todos los Planes que haya en juego. Si está en juego Huracán, resuelve su capacidad \"Especial\".","f":"\"Siento aguarte la fiesta.\" -Tormenta"},
  "36011": {"n":"Descarga eléctrica","t":"Acción de Héroe (ataque): inflige 8 de Daño a un enemigo. Si está en juego Tormenta eléctrica, resuelve su capacidad \"Especial\".","f":"\"¿Sabes lo que le pasa a un villano cuando le cae un rayo?\" -Tormenta"},
  "36012": {"n":"Congelación instantánea","t":"Interrupción de Héroe (defensa): cuando el Villano te ataque, tanto el Villano como todos los Esbirros enfrentados a ti reciben -3 ATQ mientras te estén atacando en esta fase. Si está en juego Ventisca, resuelve su capacidad \"Especial\"."},
  "36013": {"n":"Ráfaga de viento","t":"Acción de Héroe: elige a un jugador → inflige 3 de Daño al Villano y a todos los Esbirros que estén enfrentados a ese jugador. Resuelve la capacidad \"Especial\" de tu Apoyo CLIMA."},
  "36014": {"n":"Kaos","t":"[star] Interrupción obligada: cuando Kaos ataque, descarta la primera carta del mazo de Encuentros. Por cada icono de Aumento ([boost]) que se haya descartado de este modo, Kaos recibe +1 ATQ para este ataque y sufre +1 de Daño derivado ([consequential])."},
  "36015": {"n":"Espejismo","t":"Respuesta: después de que Espejismo entre en juego, elige un enemigo cuyo valor de PLA sea inferior al valor de INT de Espejismo → aturde a ese enemigo.","f":"\"Lo que ves es lo que hay.\""},
  "36016": {"n":"Gentil","t":"[star] Gentil sufre +1 de Daño derivado ([cost]) después de atacar al Villano.","f":"\"Cuanto más utilizo mi poder, más cerca estoy de la muerte. Pero correré el riesgo con tal de proteger a mis amigos.\""},
  "36017": {"n":"Hada","t":"Respuesta: después de que juegues a Hada desde tu mano, coge un aliado PATRULLA-X de tu pila de descartes y añádelo a tu mano.","f":"\"Cuando descubrí que era mutante, creí que mi vida se había acabado; pero entonces me uní a la Patrulla-X.\""},
  "36018": {"n":"La imposible Patrulla-X","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 carta de Grupo por jugador.\nTodos tus Aliados PATRULLA-X reciben +1 de Vida. Si todos tus personajes tienen el rasgo PATRULLA-X, te costará 1 recurso menos jugar cada uno de tus Aliados PATRULLA-X."},
  "36019": {"n":"Habilidad de liderazgo","t":"Usos (3 contadores de Liderazgo). Máximo de 1 por jugador.\nInterrupción: cuando un Aliado realice una acción básica de intervención o ataque, quita 1 contador de Liderazgo de esta carta → ese Aliado recibe +1 INT y +1 ATQ para esa acción."},
  "36020": {"n":"\"¡A mí, mi Patrulla-X!\"","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo PATRULLA-X.\nAcción de Héroe: busca un Aliado PATRULLA-X entre las 5 primeras cartas de tu mazo y ponlo en juego. Si ese Aliado continúa en juego al final de la fase, añádelo a tu mano."},
  "36021": {"n":"Liderazgo eficaz","t":"Máximo de 2 por mazo.\nInterrupción: cuando gastes esta carta para jugar un Aliado, ese Aliado recibe +1 INT y +1 ATQ hasta el final de la fase."},
  "36022": {"n":"Forja","t":"Respuesta: después de que Forja entre en juego, busca en tu mazo y tu pila de descartes un Apoyo PATRULLA-X o X-FORCE y añádelo a tu mano. (Baraja el mazo.)","f":"\"Me llamo Forja. Lo mío es construir.\""},
  "36023": {"n":"Jet-X","t":"Recurso: agota el Jet-X → genera un recurso [wild] para un jugador cuyo Superhéroe tenga el rasgo PATRULLA-X.","f":"\"¡Forja se ha superado a sí mismo con esta maravilla!\" -Bestia"},
  "36024": {"n":"Utopía","t":"Si todos tus Aliados tienen el rasgo PATRULLA-X, tu límite de Aliados se incrementa en 1.\nRespuesta: después de que entre en juego un Aliado PATRULLA-X, agota Utopía → prepara un personaje PATRULLA-X."},
  "36025": {"n":"Mansión X","t":"Acción de Alter ego: agota la Mansión X → cura 1 de Daño a un personaje MUTANTE o PATRULLA-X. Cualquier jugador cuyo Alter ego tenga el rasgo MUTANTE puede aplicar esta capacidad."},
  "36026": {"n":"Aguante","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nRecibes +3 de Vida."},
  "36027": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "36028": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "36029": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "36030": {"n":"Claustrofobia","t":"Dale esta carta al jugador que lleva a Ororo Munroe.\nCambia a la identidad de tu Alter ego.\nNo puedes cambiar de identidad.\nAcción de Alter ego: agota a Ororo Munroe → retira de la partida Claustrofobia."},
  "36031": {"n":"Calisto","t":"Ataque veloz.\nInterrupción obligada: cuando se muestre una carta de Perfidia de Pelea a cuchillo, dale a Calisto una carta de Estado \"Duro\".","f":"\"¡Voy a rajarte esa cara tan bonita que tienes!\""},
  "36032": {"n":"Líder de los morlocks","t":"Cuando se derrote esta carta: el jugador que haya derrotado este Plan busca Pelea a cuchillo en el mazo de Encuentros, en su pila de descartes y en la zona apartada, y la muestra.","f":"\"Calisto protege a los morlocks, pero no tolera que nadie cuestione su autoridad.\""},
  "36033": {"n":"Navaja automática","t":"Vincula esta carta al Esbirro que tenga el valor impreso más alto de ATQ. Deno ser posible, esta carta gana Oleada.\n[star] Los ataques del Esbirro vinculado ganan Penetrante."},
  "36034": {"n":"Pelea a cuchillo","t":"Cuando se muestre esta carta (Alter ego): esta carta gana Oleada.\nCuando se muestre esta carta (Héroe): elige un enemigo que tenga el valor más alto de ATQ → sufres tanto Daño como su ATQ. Inflige tanto Daño a ese enemigo como tu ATQ."},
  "36035": {"n":"Hangar","t":"Máximo de 1 por jugador.\nRespuesta: después de que un Aliado defienda contra un ataque y no sea derrotado, agota esta carta → prepara ese Aliado."},
  "36036": {"n":"El Rey Sombra","t":"Mientras haya en juego un Esbirro CONTROLADO, El Rey Sombra no puede sufrir Daño.\nCuando se muestre esta carta: busca una copia del Accesorio Posesión en el mazo y la pila de descartes de Encuentros y muéstrala. (Baraja el mazo.)"},
  "36037": {"n":"Soberano del plano astral","t":"Cuando se derrote esta carta: descarta 1 copia de Posesión que esté en juego.\n[star] Aumento: si estás enfrentado a un Esbirro CONTROLADO, muestra esta carta."},
  "36038": {"n":"Posesión","t":"El Aliado vinculado se trata como un Esbirro CONTROLADO con el texto de reglas en blanco. El valor de PLA del Esbirro vinculado es igual a su valor impreso de INT, y no sufre Daño derivado.\nCuando se muestre esta carta: vincula esta carta al Aliado que tenga el valor más bajo de INT y que no tenga ya vinculada a una carta de Posesión. Si no es posible, esta carta gana Oleada."},
  "36039": {"n":"Ataque astral","t":"Cuando se muestre esta carta: todos los Esbirros CONTROLADO se activan contra ti. Si no hay Esbirros CONTROLADO en juego, esta carta gana Oleada.\n[star] Aumento: coge todas las cartas del Rey Sombra que haya en la pila de descartes, añádelas al mazo de Encuentros y barájalo."},
  "37001a": {"n":"Gambito","t":"Cargar el naipe — Acción: coloca 1 contador de Carga sobre esta carta. (Límite de una vez por ronda.)\nArrojar el naipe — Interrupción: cuando jueges un evento de ATAQUE, quita hasta 3 contadores de Carga de esta carta → ese evento inflige +1 de Daño por cada contador que hayas quitado."},
  "37001b": {"t":"Ladrón Extraordinario — Acción (intervención): agota Remy LeBeau y mira las 2 primeras cartas del mazo de Encuentros. Descarta 1 de esas cartas → quita tanta Amenaza de un Plan como el número de iconos de Aumento ([boost]) de esa carta."},
  "37002": {"n":"Pícara","t":"El coste para jugar a Pícara se reduce en 1 por cada contador de Carga que haya sobre tu carta de Superhéroe.\nDureza.","f":"\"¡No puedo cargar con ese cajún pirado a todas partes!\""},
  "37003": {"n":"El Gremio de Ladrones","t":"Respuesta de Alter ego: después de que resuelvas tu capacidad \"Ladrón Extraordinario\", agota El Gremio de Ladrones → quita 1 de Amenaza de un Plan. Si con esto se quita la última ficha de Amenaza de este Plan, roba 1 carta."},
  "37004": {"n":"Vara de Gambito","t":"Interrupción de Héroe: cuando un enemigo ataque, agota la Vara de Gambito → inflige 1 de Daño a ese enemigo.","f":"\"Así que quieres pelear con Gambito, ¿eh?\"\n-Gambito"},
  "37005": {"n":"Armadura gremial de Gambito","t":"Respuesta de Héroe: después de que Gambito defienda contra un ataque y no sufra Daño, agota la Armadura gremial de Gambito → prepara a Gambito.","f":"\"Los miembros del Gremio de Ladrones visten armaduras personalizadas para protegerse de los asesinos.\""},
  "37006": {"n":"Naipe cargado","t":"Acción de Héroe (ataque): inflige 4 de Daño a un enemigo. Para este ataque, si la capacidad \"Arrojar el naipe\" de Gambito ha quitado al menos:\n• 1 contador, este ataque gana A Distancia.\n• 2 contadores, este ataque también gana Penetrante.\n• 3 contadores, este ataque también gana Brutalidad."},
  "37007": {"n":"Escalera real","t":"Acción de Héroe (ataque): coloca 1 contador de Carga sobre Gambito. inflige 0 de Daño a un enemigo. inflige 0 de Daño a un enemigo. inflige 0 de Daño a un enemigo.","f":"\"Tapaos los ojos, mes amis.¡Esta mano está que arde!\"\n-Gambito"},
  "37008": {"n":"Agilidad innata","t":"Interrupción de Héroe (defensa): cuando defiendas contra un ataque, coloca 1 contador de Carga sobre Gambito → por cada contador de Carga que haya sobre Gambito, recibes +1 DEF para ese ataque."},
  "37009": {"n":"Encanto criollo","t":"Acción de Alter ego (intervención): quita 3 de Amenaza de un Plan. Si con esto se quita la última ficha de Amenaza de ese Plan, confunde al Villano.","f":"\"Yo soy el ladrón, chére...y vas tú y me robas el corazón.\"\n-Gambito"},
  "37010": {"n":"Aceleración molecular","t":"Interrupción de Héroe: cuando gastes esta carta, coloca 1 contador de Carga sobre Gambito."},
  "37011": {"t":"Respuesta: después de que un enemigo te ataque, coloca 1 contador de Energía sobre esta carta.\n[star] Interrupción: cuando Bishop ataque, quítale todos los contadores de Energía → para cada contador descartado de este modo, Bishop recibe +2 ATQ para este ataque (hasta un maximo de +6 ATQ)."},
  "37012": {"t":"Respuesta: después de que Dazzler entre en juego, confunde a un enemigo.","f":"\"¿Lo oyes? Esta ciudad es una sinfonía. Y yo soy su altavoz.\""},
  "37013": {"n":"Habilidad de intrusión","t":"Usos (3 contadores de Intrusión). Máximo de 1 por jugador.\nInterrupción: cuando intervengas, quita 1 contador de Intrusión de esta carta → esa intervención quita 1 de Amenaza adicional."},
  "37014": {"n":"Ataque sigiloso","t":"Acción de Héroe (ataque): inflige 4 de Daño a un enemigo. Si este ataque derrota a ese enemigo, quita 2 de Amenaza de un Plan.","f":"\"Ni siquiera lo verán venir.\" —Viuda Negra"},
  "37015": {"n":"Allanamiento de morada","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo ESPÍA o LADRÓN.\nAcción (intervención): quita 3 de Amenaza de un Plan."},
  "37016": {"n":"Pasión por la justicia","t":"Máximo de 2 por mazo.\nInterrupción: cuando gastes esta carta para jugar un Evento de INTERVENCIÓN, ese Evento quita 1 de Amenaza adicional."},
  "37017": {"n":"Profesor X","t":"Respuesta obligada: después de que el Profesor X entre el juego, elige una de estas opciones: confundir al Villano, aturdir a un Esbirro o preparar un personaje PATRULLA-X. Al final de la ronda, si el Profesor X aún sigue en juego, descártalo."},
  "37018": {"n":"Mansión X","t":"Acción de Alter ego: agota la Mansión X → cura 1 de Daño a un personaje MUTANTE o PATRULLA-X. Cualquier jugador cuyo Alter ego tenga el rasgo MUTANTE puede aplicar esta capacidad."},
  "37019": {"n":"La bella y el ladrón","t":"Equipo (Gambito y Pícara). Máximo de 1 por mazo.\nAcción de Héroe (ataque/intervención): inflige 4 de Daño a un enemigo. Quita 4 de Amenaza de un Plan."},
  "37020": {"n":"Ataque relámpago","t":"Acción de Héroe (ataque/intervención): inflige 2 de Daño a un enemigo. Quita 2 de Amenaza de un Plan.","f":"\"¿Sabes, mi señora Gamora? Aun cuando nos conocimos y te estaba dando una paliza tremenda, pensé: seguro que podríamos ser amigas.\" - Angela"},
  "37021": {"n":"Educación para mutantes","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo MUTANTE.\nAcción de Alter ego: elige hasta 2 cartas específicas de Superhéroes que haya en tu pila de descartes, añadelas a tu mazo y barájalo. Si la Mansión esta en juego, roba 1 carta."},
  "37022": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "37023": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "37024": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "37025": {"n":"Asuntos del Gremio","t":"Dale esta carta al jugador que lleva a Remy LeBeau.\nAcción de Alter ego: agota a Remy LeBeau y gasta un recurso [energy] → retira de la partida Asuntos del Gremio."},
  "37026": {"t":"Ataque veloz. Dureza.\n[star] Respuesta obligada: después de que Belladona ataque y derrote a un personaje, coloca 2 de Amenaza sobre el Plan principal."},
  "37027": {"n":"El Gremio de Asesinos","t":"Respuesta obligada: despues de que un Esbirro ASESINO ataque y derrote a un personaje, coloca 2 de Amenaza sobre esta carta.","f":"\"El Gremio de Asesinos ha jurado matar a Gambito y al resto de los miembros del Gremio de Ladrones.\""},
  "37028": {"n":"Asesino del Gremio","t":"Ataque veloz.\n[star] Respuesta obligada: después de que el Asesino del Gremio ataque y derrote a un personaje, coloca 1 de Amenaza sobre el Plan principal."},
  "37029": {"n":"Intento de Asesinato","t":"Cuando se muestre esta carta: todos los Esbirros ASESINO te atacan (incluso aunque tengas adoptada la identidad de tu Alter ego). Si no hay ningún Esbirro ASESINO en juego, busca un Esbirro ASESINO en el mazo y la pila de descartes de Encuentros y muéstralo."},
  "37030": {"n":"Sala de guerra","t":"Máximo 1 por jugador.\nRespuesta: después de que un Aliado ataque y derrote a un Esbirro, agota la Sala de guerra → quita 1 de Amenaza de un Plan."},
  "37031": {"n":"Clases de la Patrulla-X","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo MUTANTE.\nAcción de Alter ego: elige hasta 2 Aliados PATRULLA-X que estén en tu pila de descartes, añádelos a tu mazo y barájalo. Si Mansión X está en juego, roba 1 carta."},
  "37032": {"n":"Éxodo","t":"Represalia 1. Infame.\nCuando se muestre esta carta: busca el Accesorio Escudo psiónico en el mazo y la pila de descartes de Encuentros y vincúlalo a Éxodo. (Baraja el mazo.)","f":"\"¡Sirvo orgulloso a la causa de Magneto!\""},
  "37033": {"n":"Heraldo of Avalón","t":"Cuando se muestre esta carta: el jugador que haya derrotado este Plan busca a Éxodo en el mazo y la pila de descartes de Encuentros y lo muestra. (Baraja el mazo.)","f":"\"Éxodo considera a Magneto como el salvador de la raza mutante y actúa como su heraldo.\""},
  "37034": {"n":"Escudo psiónico","t":"Vincula esta carta a un Esbirro. De no ser así, el Escudo psiónico gana Oleada.\nInterrupción obligada: cuando el Esbirro vinculado vaya a abandonar el juego, en vez de eso cúrale todo el Daño y vuelve a ponerlo en juego. Luego descarta este Accesorio."},
  "37035": {"n":"Acólitos exaltados","t":"Cuando se muestre esta carta: todos los Esbirros ACÓLITO que estén enfrentados a ti se activan contra ti. Si no estás enfrentado a ningún Esbirro ACÓLITO, esta carta gana Oleada.\n[star] Aumento: quedas aturdido y confundido."},
  "38001a": {"n":"Pícara","t":"Tocar la piel — Acción: vincula Contacto físico a otro personaje. Ganas todos los RASGOS del personaje vinculado hasta el final de la ronda. (Límite de una vez por ronda.)\nRespuesta obligada: después de que empiece la fase de los Jugadores, localiza la carta Contacto físico y apártala a un lado."},
  "38001b": {"t":"Preparación: aparta a un lado tu Mejora Contacto físico.\nRetraída — Respuesta obligada: después de que cambies a esta identidad, aparta a un lado Contacto físico.","f":"\"No podrías vivir mi vida.\""},
  "38002": {"n":"Contacto físico","t":"Si Contacto físico está vinculada a un:\nEsbirro — los ataques de Pícara ganan Brutalidad.\nVillano — Pícara gana Represalia 1.\nAliado — Pícara gana el rasgo AÉREO.\nHéroe — Pícara gana Firmeza."},
  "38003": {"n":"Gambito","t":"Gambito entra en juego con 3 contadores de Carga.\n[star]Interrupción: cuando Gambito ataque, quítale 1 contador de Carga → inflige 1 de Daño a un enemigo."},
  "38004": {"n":"Chaqueta de Pícara","t":"Mientras Contacto físico esté vinculada a un personaje amigo, Pícara recibe +1 INT.\nMientras Contacto físico esté vinculada a un personaje enemigo, Pícara recibe +1 ATQ."},
  "38005": {"n":"Al estilo de Pícara","t":"Acción de Héroe (intervención): quita 3 de Amenaza de un Plan. Si Pícara tiene:\n• AÉREO, quita 2 de Amenaza adicional.\n• Represalia, confunde a un enemigo.\n• Firmeza, roba 1 carta."},
  "38006": {"n":"Temperamento sureño","t":"Acción de Héroe (ataque): inflige 6 de Daño a un enemigo. Si Pícara tiene:\n• AÉREO, este ataque inflige 2 de Daño adicional.\n• Represalia, aturde a ese enemigo.\n• Firmeza, roba 1 carta."},
  "38007": {"n":"Transferencia de energía","t":"Acción de Héroe: vincula Contacto físico a un personaje que no sea Pícara e inflige 2 de Daño a ese personaje → cura 2 de Daño a Pícara y prepárala. Ganas todos los (RASGOS) del personaje vinculado hasta el final de la ronda."},
  "38008": {"n":"Belleza a prueba de balas","t":"Interrupción de Héroe (defensa): cuando ataque un enemigo que tenga vinculada la carta Contacto físico, evitas todo el Daño de ese ataque y ganas una carta de Estado \"Duro\".","f":"\"Lo único que consigues es cabrearme, dulzura.\"-Pícara"},
  "38009": {"n":"Robo de superpoder","t":"Acción de Héroe: Si la carta Contacto físico está vinculada a un personaje amigo, busca en la pila de descartes de su propietario un Evento que pertenezca a la misma clasificación que ese personaje (específica de un Superhéroe, de aspecto o Básica) → añade ese Evento a tu mano."},
  "38010": {"n":"Hombre de Hielo","t":"El Hombre de Hielo entre en juego con 3 contadores de Congelación.\nRespuesta: después de que entre en juego un Esbirro, quita 1 contador de Congelación del Hombre de Hielo → aturde a ese Esbirro."},
  "38011": {"t":"Respuesta: después de que jueges a Karma desde tu mano, elige un Esbirro que no sea ÉLITE. Mientras Karma esté en juego, toma el control de ese Esbirro y trátalo como un Aliado CONTROLADO con el texto de reglas en blanco. Su valor de INT es igual a su valor impreso de PLA, y sufre 2 de Daño derivado después de intervenir o atacar."},
  "38012": {"n":"Armadura","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo PATRULLA-X.\nDureza.","f":"\"Sí, a lo mejor tienes suerte y logras atravesar mi impenetrable exoesqueleto psiónico.\""},
  "38013": {"n":"Imperturbable","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nRespuesta: después de que defiendas contra un ataque y no sufrás Daño, agota Imperturbable → roba 1 carta."},
  "38014": {"n":"Habilidad de judo","t":"Usos (3 contadores de Judo). Máximo de 1 por jugador.\nInterrupción: cuando defiendas contra un ataque enemigo, quita 1 contador de Judo de esta carta → ese enemigo recibe -2 ATQ para ese ataque."},
  "38015": {"n":"Ataque preventivo","t":"Interrupción de Héroe (defensa): al poner boca arriba una carta de Aumento cuando el Villano ataque, anula todos los iconos de Aumento ([boost]) de esa carta. Luego inflige 1 de Daño al Villano por cada icono de Aumento que se haya anulado de este modo."},
  "38016": {"n":"¡No será hoy!","t":"Interrupción de Héroe (defensa): cuando tu Héroe defienda contra un ataque, recibe +2 DEF para ese ataque. Si no sufres Daño a consecuencia de ese ataque, quita 2 de Amenaza de un Plan."},
  "38017": {"n":"Energía defensiva","t":"Máximo de 2 por mazo.\nInterrupción de Héroe: cuando gastes esta carta para jugar un Evento de DEFENSA, roba 1 carta."},
  "38018": {"t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo MUTANTE.\nRespuesta: después de que un Alter ego MUTANTE cambie a su identidad de Héroe, agota a Moira MacTaggert → el jugador que controla ese Héroe roba 1 carta."},
  "38019": {"n":"Gen X","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo MUTANTE. Máximo de 1 por jugador\nRecurso: agota Gen X → genera un recurso [wild] para un Evento que sea específico de un Superhéroe."},
  "38020": {"n":"La bella y el ladrón","t":"Equipo (Gambito y Pícara). Máximo de 1 por mazo.\nAcción de Héroe (ataque/intervención): inflige 4 de Daño a un enemigo. Quita 4 de Amenaza de un Plan."},
  "38021": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "38022": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "38023": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "38024": {"n":"Contacto mortal","t":"Dale esta carta al jugador que lleva a Anna Marie.\n• Si Contacto fisico está vinculada a un personaje amigo, inflige 2 de Daño a ese personaje. Descarta esta carta.\n• Si Contacto fisico no está vinculada a un personaje amigo, coloca 2 de Amenaza sobre el Plan principal. Descarta esta carta."},
  "38025": {"n":"Mística","t":"Dureza. Infame.\nRespuesta obligada: después de que Mística se enfrente a ti, busca una copia de la carta Engaño en el mazo de Encuentros, en su pila de descartes y en la zona apartada, añádela a tu mazo y barájalo."},
  "38026": {"n":"Las manipulaciones de Mística","t":"Cuando se derrote esta carta: busca una copia de la carta Engaño en el mazo y la pila de descartes de Encuentros, añádela a tu mazo y barájalo.","f":"\"Aunque sabe bien que Mística no es de fiar, Pícara es incapaz de rechazar a la mujer que la ha criado.\""},
  "38027": {"n":"Engaño","t":"Cuando se muestre esta carta: añade esta carta a tu mazo y barájalo. Esta carta gana Oleada.\nRespuesta obligada: después de que esta carta entre en tu mano, coloca 2 de Amenaza sobre el Plan principal. (Puedes descartar esta carta desde tu mano al final de la fase de los Jugadores como cualquier otra carta.)"},
  "38028": {"n":"Laboratorio médico","t":"Máximo de 1 por jugador.\nRespuesta: después de que un Aliado sea derrotado por Daño derivado, agota el Laboratorio médico → colócalo aquí. (Límite de 1 Aliado cada vez.)\nAcción de Alter ego: agota el Laboratorio médico → juega el Aliado que haya aquí como si estuviese en tu mano. Entra en juego agotado."},
  "38029": {"t":"Trabajo en equipo (COSECHADOR). Infame.\nRespuesta obligada: después de que Donald Pierce se enfrente a ti, muestra el primer Esbirro COSECHADOR que haya en la parte superior de la pila de descartes."},
  "38030": {"n":"Abrecráneos","t":"Trabajo en equipo (COSECHADOR). Dureza.\nRespuesta obligada: después de que Abrecráneos se enfrente a ti, coloca 1 de Amenaza sobre el Plan principal por cada Esbirro COSECHADOR que este enfrentado a ti.","f":"\"¿A quién vas a llamar?\""},
  "38031": {"n":"Rompehuesos","t":"Trabajo en equipo (COSECHADOR). Dureza.\nInterrupción obligada: después de que Rompehuesos se enfrente a ti, sufres 1 de Daño indirecto por cada Esbirro COSECHADOR que este enfrentado a ti.","f":"\"¡Rompehuesos está listo!\""},
  "38032": {"t":"Trabajo en equipo (COSECHADOR).\nCuando se muestre esta carta: busca una copia del Accesorio Aumentos cibernéticos en el mazo y la pila de descartes de Encuentros y vincúlala a Wade Cole. (Baraja el mazo.)"},
  "38033": {"t":"Trabajo en equipo (COSECHADOR).\nCuando se muestre esta carta: busca una copia del Accesorio Aumentos cibernéticos en el mazo y la pila de descartes de Encuentros y vincúlala a Murray Reese. (Baraja el mazo.)"},
  "38034": {"n":"Los Cosechadores","t":"Cuando se derrote esta carta: el jugador que haya derrotado este Plan descarta cartas del mazo de Encuentros hasta que se descarte un Esbirro COSECHADOR, luego muestra ese Esbirro."},
  "38035": {"n":"Aumentos cibernéticos","t":"Vincula esta carta a un Esbirro. De no ser posible, esta carta gana Oleada.\nEl Esbirro vinculado no puede sufrir Daño.\n[star] Respuesta obligada: después de que el Esbirro vinculado ataque, descarta Aumentos cibernéticos."},
  "39001a": {"t":"[star] Respuesta obligada: después de que MaGog ataque e inflija Daño a un personaje, coloca 1 contador de Audiencia sobre El campeón.\nInterrupción obligada: cuando MaGog vaya a ser derrotado, en vez de eso restablece su Vida a 10[per_hero]. coloca 3[per_hero] contadores de Audiencia sobre Los aspirantes y reparte 1 carta de Encuentro boca abajo a cada jugador."},
  "39001b": {"t":"[star] Respuesta obligada: después de que MaGog ataque e inflija Daño a un personaje, coloca 2 contadores de Audiencia sobre El campeón.\nInterrupción obligada: cuando MaGog vaya a ser derrotado, en vez de eso restablece su Vida a 10[per_hero]. coloca 2[per_hero] contadores de Audiencia sobre Los aspirantes y reparte 1 carta de Encuentro boca abajo a cada jugador."},
  "39002a": {"n":"El coliseo de Mojo (1A)","t":"Contenido: MaGog (A) (MaGog (B) para jugar modo Experto). Encuentros de MaGog y Normal. Un conjunto de Encuentros modular (1 conjunto modular aleatorio de la expansión MojoManía).\nPreparación: pon en juego la carta de Entorno El campeón y la carta de Entorno Los aspirantes, ambas con la cara ABUCHEOS boca arriba."},
  "39002b": {"n":"El coliseo de Mojo (1B)","t":"Los jugadores no pueden ganar la partida a menos que deleiten al público como Los aspirantes.\n[star] Interrupción obligada: cuando vaya a completarse este Plan, coloca 2[per_hero] contadores de Audiencia sobre El campeón y quita toda la Amenaza de esta carta.","f":"¡Habeís sido teletransportados a un extraño coliseo en el que deberéis luchar por la diversión del público... y por vuestras vidas!"},
  "39003a": {"n":"El campeón","t":"Si hay al menos 5[per_hero] contadores de Audiencia sobre esta carta, dale la vuelta a este Entorno (sin quitarle los contadores de Audiencia).","f":"\"¡En este rincón tenemos al noventa y nueve veces invicto campeón del Mojoverso, el poderoso MaGog!\" — Mojo"},
  "39003b": {"n":"El campeón","t":"Leváis las de perder — Respuesta obligada: después de que se dé la vuelta a El campeón para poner boca arriba esta cara, cada jugador roba 1 carta.\nSi hay al menos 10[per_hero] contadores de Audiencia sobre esta carta, MaGog vuelve a ganar y los jugadores pierden la partida."},
  "39004a": {"n":"Los aspirantes","t":"Si hay al menos 5[per_hero] contadores de Audiencia sobre esta carta, dale la vuelta a este Entorno (sin quitarle los contadores de Audiencia).\n(Los jugadores deleitan al público colocando contadores de Audiencia sobre esta carta.)","f":"\"¡Y en el otro rincón, procedentes de un planetucho insignificante llamado Tierra, tenemos a los aspirantes!\" — Mojo"},
  "39004b": {"n":"Los aspirantes","t":"Relevos — Respuesta obligada: después de que se dé la vuelta a Los aspirantes para poner boca arriba esta cara, busca al Contendiente sorpresa en el mazo y la pila de descartes de Encuentros y ponlo en juego enfrentado al jugador inicial. Si ya está en juego, dale una carta de Estado \"Duro\".\nSi hay al menos 10[per_hero] contadores de Audiencia sobre esta carta, habéis deleitado al público y los jugadores ganan la partida."},
  "39005": {"n":"Aumento de adrenalina","t":"Vincula esta carta a MaGog.\nMaGog gana Represalia 1 y Firmeza.\nRespuesta obligada: después de que se restablezca la Vida de MaGog, coloca 1[per_hero] contadores de Audiencia sobre Los aspirantes y descarta esta carta.\n[star] Aumento: muestra esta carta."},
  "39006": {"n":"Arrebato de violencia","t":"Vincula esta carta a MaGog.\nRespuesta obligada: después de que se restablezca la Vida de MaGog, coloca 1[per_hero] contadores de Audiencia sobre Los aspirantes y descarta esta carta.\n[star] Aumento: muestra esta carta.","f":"\"¡Quédate quieto para que pueda machacarte!\" — MaGog"},
  "39007": {"n":"Contendiente sorpresa","t":"Infame.\n[star] Respuesta obligada: después de que Contendiente sorpresa ataque e inflija Daño a un personaje, coloca 1 contador de Audiencia sobre El campeón.\nCuando se derrote esta carta: coloca 2[per_hero] contadores de Audiencia sobre Los aspirantes."},
  "39008": {"n":"Animar al público","t":"Cuando se muestre esta carta: si El campeón tiene boca arriba su cara de VÍTORES, coloca 1[per_hero] contador de Amenaza adicional sobre esta carta.\nCuando se derrote esta carta: coloca 1[per_hero] contadores de Audiencia sobre Los aspirantes.","f":"\"¡Va por vosotros!\" — MaGog"},
  "39009": {"n":"Problemas del directo","t":"Cuando se muestre esta carta: quedas Aturdido. Sufres 2 de Daño (4 de Daño si hay más contadores de Audencia sobre Los aspirantes que sobre El campeón). Puedes colocar cualquier cantidad de contadores de Audencia sobre El campeón para reducir este Daño en 1 por cada contador que coloques de este modo."},
  "39010": {"n":"Defender el título","t":"Cuando se muestre esta carta (Alter ego): coloca 2 contadores de Audencia sobre El campeón.\nCuando se muestre esta carta (Héroe): MaGog te ataca. Si un Héroe defiende contra este ataque y no sufre Daño, coloca 2 contadores de Audencia sobre Los aspirantes.","f":"\"¡¿Os habéis divertido?!\" — MaGog"},
  "39011": {"n":"Miedo escénico","t":"Cuando se muestre esta carta: quedas confundido. Coloca 2 de Amenaza sobre el Plan principal (4 de Amenaza si hay más contadores de Audencia sobre Los aspirantes que sobre El campeón).\n[star] Aumento: quedas confundido."},
  "39012a": {"n":"Espiral","t":"Espiral no puede sufrir Daño ni quedar aturdida. No puede quitarse Amenaza del Plan principal.\n[star] Interrupción obligada: cuando Espiral vaya a atacar, en vez de eso ejecuta el Plan."},
  "39012b": {"n":"Espiral","t":"Si hay al menos 3[per_hero] contadores de Teleportarse sobre esta carta, quítalos todos y dale la vuelta a Espiral.\n[star] Respuesta obligada: después de que Espiral se active, coloca 1 contador de Teleportarse sobre esta carta."},
  "39013a": {"n":"Espiral","t":"Espiral no puede sufrir Daño ni quedar aturdida. No puede quitarse Amenaza del Plan principal.\n[star] Interrupción obligada: cuando Espiral vaya a atacar, en vez de eso ejecuta el Plan."},
  "39013b": {"n":"Espiral","t":"Si hay al menos 2[per_hero] contadores de Teleportarse sobre esta carta, quítalos todos y dale la vuelta a Espiral.\n[star] Respuesta obligada: después de que Espiral se active, coloca 1 contador de Teleportarse sobre esta carta."},
  "39014a": {"n":"Espiral","t":"Espiral no puede sufrir Daño ni quedar aturdida. No puede quitarse Amenaza del Plan principal.\n[star] Interrupción obligada: cuando Espiral vaya a atacar, en vez de eso ejecuta el Plan."},
  "39014b": {"n":"Espiral","t":"Si hay al menos 3[per_hero] contadores de Teleportarse sobre esta carta, quítalos todos y dale la vuelta a Espiral.\nCuando se muestres esta carta: Espiral ataca a todos los jugadores siguiendo el orden de jugadores (incluso a los que tengan adoptada la identidad de su Alter ego).\n[star] Respuesta obligada: después de que Espiral se active, coloca 1 contador de Teleportarse sobre esta carta."},
  "39015a": {"n":"Viaje por el Mojoverso (1A)","t":"Contenido: Espiral (I) y Espiral (II) (Espiral (II) y Espiral (III) para jugar modo Experto). Conjuntos de Encuentros de Espiral y Normal. Tres conjuntos de Encuentros modulares de la expansión MojoManía.\nPreparación: pon en juego el Plan secundario La búsqueda de Espiral y 1 Entorno SERIE aleatorio. Baraja todos los demás Entornos SERIE junto con la carta de Perfidia ¡Acorralada! para formar el mazo de Series. (ver página 11 del reglamento). Dale la vuelta a Espiral para poner boca arriba su cara FUGADA."},
  "39015b": {"n":"Viaje por el Mojoverso (1B)","t":"Interrupción obligada: cuando vaya a descartarse un Entorno SERIE, en vez de eso colócalo en la parte inferior del mazo de Series.\nSi se completa esta etapa, los jugadores pierden la partida.","f":"Si queréis volver a casa, necesitaréis la ayuda de Espiral y su don mágico para el teletransporte. Pero no será fácil convencerla."},
  "39016": {"n":"La búsqueda de Espiral","t":"Permanente.\nRespuesta obligada: después de que se quite la última ficha de Amenaza de esta carta, el jugador que la haya quitado muestra la primera carta de la parte superior del mazo de Series y coloca 3[per_hero] de Amenaza sobre esta carta.\nAcción de Héroe: sufres 2 de Daño. Quita 3 de Amenaza de esta carta.","f":"Espiral se oculta en una de las numerosas series de televisión producidas por Mojo"},
  "39017": {"n":"¡Acorralada!","t":"Cuando se muestre esta carta: dale la vuelta a Espiral para poner boca arriba su cara Acorralada. (Esto hará que se resuelva su enunciado \"Cuando se muestre esta carta\", si lo hay.) Muestra la primera carta del mazo de Series. Añade esta carta al mazo de Series y barájalo. Este efecto no puede anularse."},
  "39018": {"n":"Espadas de Espiral","t":"Vincula esta carta a Espiral.\nUsos (3 contadores de Espada).\n[star] Espiral recibe +1 ATQ por cada contador de Espada que haya sobre esta carta.\nAcción de Héroe: si Espiral tiene boca arriba su cara Acorralada, gasta recursos [physical] [physical] → quita 1 contador de Espada de esta carta.","f":"\"No sé cómo se las apaña para no rebanarse un brazo\" — Gambito"},
  "39019": {"n":"Teletransporte errático","t":"Oleada.\nCuando se muestre esta carta: si Espiral tiene boca arriba su cara Acorralada, coloca 1 contador de Teletransporte sobre su carta. Si Espiral tiene boca arriba su cara Fugada, puedes gastar un recurso [mental] para mirar la primera carta del mazo de Series y colocarla en la parte superior o inferior de ese mazo."},
  "39020": {"n":"El espectáculo debe continuar","t":"Cuando se muestre esta carta: cada jugador busca en el mazo y la pila de descartes de Encuentros una carta que pertenezca al mismo conjunto de Encuentros que el Entorno Serie actual y se la queda como carta de Encuentro boca abajo. (Baraja el mazo.)"},
  "39021": {"n":"Armada y peligrosa","t":"Cuando se muestre esta carta:si Espiral tiene vinculada una copia de Espadas de Espiral, te ataca (incluso aunque tengas adoptada la identidad de tu Alter ego). De no ser así, busca en el mazo y la pila de descartes de Encuentros una copia de Espadas de Espiral y vincúlasela.(Baraja el mazo.)"},
  "39022": {"t":"Respuesta obligada (Héroe): después de que termine tu turno, descarta las 3 primeras cartas del mazo de Encuentros. Coloca 1 de Amenaza sobre tu Héroe por cada carta descartada de este modo que no pertenezca al conjunto de Encuentros de Mojo."},
  "39023": {"t":"Cuando se muestres esta carta: coloca 2 de Amenaza sobre cada personaje amigo.\nRespuesta obligada (Héroe): después de que termine tu turno, descarta las 4 primeras cartas del mazo de Encuentros. Coloca 1 de Amenaza sobre tu Héroe por cada carta descartada de este modo que no pertenezca al conjunto de Encuentros de Mojo."},
  "39024": {"t":"Cuando se muestres esta carta: coloca 3 de Amenaza sobre cada personaje amigo.\nRespuesta obligada (Héroe): después de que termine tu turno, descarta las 5 primeras cartas del mazo de Encuentros. Coloca 1 de Amenaza sobre tu Héroe por cada carta descartada de este modo que no pertenezca al conjunto de Encuentros de Mojo."},
  "39025a": {"n":"MojoManía (1A)","t":"Contenido: Mojo (I) y Mojo (II) (Mojo (II) y Mojo (III) para jugar modo Experto). Conjuntos de Encuentros de Mojo y Normal.\nPreparación: elige 1 conjunto modular, más 1[per_hero] conjuntos modulares adicionales, de la expansión Mojomania y apártalos a un lado. Pon en juego la carta de Entorno de la Ruleta de géneros, con la cara GIRANDO boca arriba."},
  "39025b": {"n":"MojoManía (1B)","t":"Cuando se muestre esta carta: elige al azar 1 conjunto de Encuentros apartado, muestra su Entorno SERIE y baraja sus restantes cartas con el mazo de Encuentros.\nInterrupción obligada: cuando un personaje abandone el juego o se dé la vuelta a su carta, traslada a este Plan toda la Amenaza que tuviera encima ese personaje.\nSi se completa esta etapa, los jugadores pierden la partida."},
  "39026a": {"n":"Ruleta de géneros (Girando)","t":"Respuesta obligada: después de que se restablezca el mazo de Encuentros, si no queda ningún conjunto de Encuentros modular apartado, los jugadores pierden la partida. De no ser asi, dale la vuelta a esta carta.","f":"\"Los índices de audencia están cayendo.¡Vamos a animar las cosas metiendo cameos de otras series!\" — Mojo"},
  "39026b": {"n":"Ruleta de géneros (Detenida)","t":"Interrupción obligada: al comienzo del paso 3 de la fase del Villano (repartir cartas de Encuentro), elige al azar 1 conjunto modular apartado y muestra su Entorno SERIE. Baraja el resto de ese conjunto modular y colócalo en la parte superior del mazo de Encuentros. Reparte al jugador inicial2 cartas de Encuentro boca abajo y dale la vuelta a esta carta."},
  "39027": {"n":"Mayor Domo","t":"Vincula esta carta a Mojo.\n[star] Respuesta obligada: después de que Mojo ataque, descarta tantas carta del mazo de Encuentros como la cantidad de Daño infligida por ese ataque.\nAcción de Héroe: gasta recursos [energy] [mental] [physical] → descarta esta carta.","f":"\"Vivo para servir Su ilustre invertebradez.\""},
  "39028": {"n":"Agijón láser","t":"Vincula esta carta a Mojo.\nMojo gana Represalia 2.\nInterrupción obligada: cuando vaya a infligirse cualquier cantidad de Daño a Mojo, en vez de eso coloca ese Daño sobre esta carta. Luego, si hay al menos 5 de Daño sobre esta carta, descarta el Agijón láser.\n[star] Aumento: vincula esta carta a Mojo."},
  "39029": {"n":"Actor de reparto","t":"[star] Respuesta obligada: después de que Actor de reparto se active contra ti, coloca 2 de Amenaza sobre esta carta.\nAumento: coloca 1 de Amenaza sobre cada personaje que controles.","f":"\"Salen más baratos que los actores de verdad.\" — Mojo"},
  "39030": {"t":"Complicación 10.\nAcción: elige entre agotar un personaje que controles o descartar 1 carta de tu mano → quita 2 de Amenaza de esta carta (3 de Amenaza si tienes adoptada la identidad de tu Alter ego).\nInterrupción obligada: cuando termine tu turno, traslada toda la Amenaza de esta carta al Plan principal y descarta esta carta."},
  "39031": {"n":"Mojo de incógnito","t":"Complicación 2[per_hero].\nInterrupción obligada: cuando Mojo vaya a sufrir cualquier cantidad de Daño, en vez de eso quita esa misma cantidad de Amenaza de esta carta.","f":"\"Nunca me reconocerán.\" — Mojo"},
  "39032": {"n":"Llamada a escena","t":"Cuando se muestre esta carta: traslada al Plan principal toda la Amenaza del personaje que tenga más Amenaza encima. Si no se traslada Amenaza de este modo, coloca 1 de Amenaza sobre cada personaje que controles."},
  "39033": {"n":"Direcciones del director","t":"Cuando se muestre esta carta: elige una opción:\n• Gasta 2 recursos diferentes.\n• Mojo ejecuta el Plan.\n• Sufre tanto Daño como la Amenaza que haya sobre tu Superhéroe. Si sufres menos de 2 de Daño de este modo, esta carta gana Oleada."},
  "39034": {"n":"Elenco principal","t":"Cuando se muestre esta carta: cura 1 de Daño a cada personaje que controles. Coloca 2 de Amenaza sobre cada personaje que controles.\nAumento: coloca 1 de Amenaza sobre cada personaje que controles."},
  "39035": {"n":"Mojos criminales","t":"Todas las demas cartas de Encuentro ganan Incitar 1.\nTodos los personajes amigos reciben +1 INT.\nCuando se muestre esta carta: descarta todos los demás Entornos Ubicación que haya en juego. Si esta carta se ha mostrado desde el mazo de Encuentros, gana Oleada."},
  "39036": {"n":"Verificar las pruebas","t":"Respuesta obligada: después de que se derrote un Plan secundario, coloca 1 contador de Pista sobre esta carta. Luego, si hay al menos 3 contadores de Pista sobre esta carta, descarta esta carta."},
  "39037": {"n":"Investigar la escena del crimen","t":"Complicación 1[per_hero].\nNo puede quitarse Amenaza de otros Planes.\nAcción de Héroe: gasta X recursos [mental] → quita X de Amenaza de este Plan.","f":"\"Lo único que hemos encontrado es un pelo.\"\n\"Pues con eso ya tenemos el caso resuelto.\"\n— Detectives Domo y Mojo"},
  "39038": {"n":"Ley y orden","t":"Complicación 1[per_hero].\nTodos los poersonajes amigos reciben -2 ATQ.\nAcción de Héroe: gasta X recursos [energy] → quita X de Amenaza de este Plan.","f":"\"¡Acuso a mis dos yos de desacato a este tribunal!\" — Juez Mojo"},
  "39039": {"n":"Operación de busca y captura","t":"Complicación 1[per_hero].\nEl Villano no puede sufrir Daño.\nAcción de Héroe: gasta X recursos [physical] → quita X de Amenaza de este Plan.","f":"\"Yo no he estado aquí.\" — Jefe Mojo"},
  "39040": {"n":"Elemental , querido Mojo","t":"Cuando se muestre esta carta: elige una opción:\n• Traslada toda la Amenaza de un Plan secundario al Plan principal. (Ese Plan secundario es derrotado.)\n• Descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Plan secundario. Muestra esa carta."},
  "39041": {"n":"Juego de Mojos","t":"Cada jugador recibe +1 al tamaño de su mano.\nCuando se muestre esta carta: descarta todos los demás Entornos Ubicación que haya en juego. Si esta carta se ha mostrado desde el mazo de Encuentros, gana Oleada."},
  "39042": {"n":"Dragón","t":"Represalia 1. Dureza.\nSe duplica la cantidad de Daño que sufre este Esbirro causado por cartas que tenga un recurso [energy] impreso.\nCuando se derrote esta carta: cada jugador roba 4 cartas."},
  "39043": {"n":"Trasgo","t":"Oleada.\nEste Esbirro sólo puede sufrir Daño causado por cartas que tenga un recurso [physical] impreso.\nCuando se derrote esta carta: quita 2 de Amenaza de un Plan."},
  "39044": {"n":"Trol","t":"Dureza.\nEste Esbirro sufre 1 de Daño adicional de cada carta que tenga un recurso [mental] impreso.\nCuando se derrote esta carta: el jugador que ha derrotado a este Esbirro puede coger 1 Aliado de su pila de descartes y ponerlo en juego."},
  "39045": {"n":"Gesta de recaderos","t":"Oleada.\nCuando se derrote esta carta: siguiendo el orden de jugadores, cada jugador puede buscar una carta de su mazo y jugarla gratis. (Baraja el mazo.)\nAumento: pon en juego esta carta.","f":"\"¡Traedme una almáciga!\" — Sir Mojo"},
  "39046": {"n":"Absorción de maná","t":"Cuando se muestre esta carta: elige un tipo de recurso que no sea Universal (no [wild]), luego cada jugador roba 2 cartas. Cada jugador debe descartar todas las cartas de su mano que tengan el tipo de recurso elegido.\nAumento: descarta 1 carta de tu mano."},
  "39047": {"n":"Expediente Mojo","t":"Todos los Esbirros ganan Ataque veloz.\nCada Aliado sufre -1 de Daño derivado después de atacar a un Esbirro.\nCuando se muestre esta carta: descarta todos los demás Entornos Ubicación que haya en juego. Si esta carta se ha mostrado desde el mazo de Encuentros, gana Oleada."},
  "39048": {"n":"Bandolera de estacas","t":"Oleada. Usos (3 contadores de Estacas).\nCuando se muestre esta carta: puedes gastar 1 recurso de cualquier tipo para vincular esta carta a tu Superhéroe. Deno ser así, descarta esta carta.\nInterrupción de Héroe: cuando tu Héroe realice un ataque básico, quita 1 contador de Estacas de esta carta → tu Héroe recibe +1 ATQ para ese ataque y además ese ataque gana Penetrante."},
  "39049": {"n":"Sectario","t":"[star] Respuesta obligada: después de que el Sectario se active contra ti, busca El kraken en el mazo y en la pila de descartes de Encuentros y ponlo en juego enfrentado a ti. (Baraja el mazo.) Luego descarta al Sectario.","f":"\"¡Liberad al kraken!\""},
  "39050": {"n":"El kraken","t":"[star] Respuesta obligada: después de que el kraken se active, todos los demas personajes sufren 1 de Daño.\nCuando se derrote esta carta: todos los personajes amigos se curan 1 de Daño."},
  "39051": {"n":"Vampiro","t":"Los ataques con Penetrante infligen el doble de Daño al Vampiro.\n[star] Respuesta obligada: después de que el Vampiro ataque e inflija Daño, cura todo el Daño del Vampiro. Si no se ha curado el Daño de este modo, dale al Vampiro una carta de Estado \"Duro\"."},
  "39052": {"n":"Jauría de hombres lobo","t":"Cuando se muestre esta carta: derrota a un Aliado que controles y colócalo boca abajo debajo de la Jauría de hombres lobo.\nInterrupción obligada: cuando la Jauría de hombres lobo vaya a ser derrotada, en vez de eso descarta un Aliado que tenga debajo. Luego cura todo el Daño de la Jauría de hombres lobo."},
  "39053": {"n":"CiberMojo","t":"Todos los Esbirros y Aliados ganan Dureza.\nCuando se muestre esta carta: descarta todos los demás Entornos Ubicación que haya en juego. Si esta carta se ha mostrado desde el mazo de Encuentros, gana Oleada.","f":"\">Contraseña admitida. Estableciendo conexión con el servidor.\n>¡Bienvenido a MojoCorp! Todas sus actividades serán monitorizadas.\""},
  "39054": {"n":"Avalancha 9.0","t":"Respuesta obligada: después de que Avalancha 9.0 se enfrente a ti, agota un personaje que controles e inflige 1 de Daño a ese personaje.\nAumento: agota un personaje que controles.","f":"\">Anulando ciclos de CPU de proceso no identificado.\""},
  "39055": {"n":"Mole 3.14","t":"La Mole 3.14 no puede sufrir más de 2 de Daño de cada ataque.\nAumento: quedas aturdido.","f":"\">Almacenando en memoria intermedia...\n>Almacenando en memoria intermedia...\n>Almacenando en memoria intermedia...\""},
  "39056": {"t":"Infame.\n[star] Respuesta obligada: después de que Magneto 2.6 se active contra ti, colócale encima 1 contador de Magnetismo. Luego elige y descarta 1 carta de tu mano por cada contador de Magnetismo que haya sobre Magneto 2.6.","f":"\">Reformateando disco infectado.\""},
  "39057": {"n":"Piros 4.0","t":"Interrupción obligada: cuando Piros 4.0 te ataque, sufres 2 de Daño indirecto.\nAumento: sufres 2 de Daño indirecto.","f":"\">Purgando programa desconocido.\""},
  "39058": {"n":"Sapo 2.0","t":"Respuesta obligada: después de que Sapo 2.0 se enfrente a ti, coloca boca abajo debajo de su carta 1 Mejora que controles.\nCuando se derrote esta carta: devuelve a la mano de su propietario cada carta que haya debajo de Sapo 2.0."},
  "39059": {"n":"AISteroide M","t":"Todos los Esbirros ganan Guardia y Patrulla.\nInterrupción obligada: al final de la ronda (después de ceder la ficha de Jugador inicial), el jugador inicial busca un Esbirro en el mazo y la pila de descartes de Encuentros y lo pone en juego enfrentado a él (Baraja el mazo.).","f":"\">Programas intrusos detectados.\n>Desplegando Algoritmo de Intercepción de Subrutinas.\""},
  "39060": {"n":"Mojo el Travieso","t":"Todas las Obligaciones ganan 1 icono de Aceleración ([acceleration]).\nRespuesta: después de que un jugador descarte una Obligación, ese jugador roba 1 carta.\nCuando se muestre esta carta: descarta todos los demás Entornos Ubicación que haya en juego. Si esta carta se ha mostrado desde el mazo de Encuentros, gana Oleada."},
  "39061": {"n":"Enredos de familia","t":"Trata el texto de reglas impreso de todos los Apoyos que controles como si estuviese en blanco (a excepción de los [rasgos]).\nAcción de Alter ego: agota tu Superhéroe y todos los Apoyos que controles → descarta esta Obligación.","f":"\"¡Nunca seré como tú!\"\n\"¡Si eres un clon de mí!\" —X-23 y Lobezno"},
  "39062": {"n":"Los problemas crecen","t":"El coste para jugar todas tus Mejoras aumenta en 2.\nAcción de Alter ego: descarta una Mejora que controles o bien descarta una Mejora de tu mano. Si tienes más Mejoras en tu pila de descartes que en juego, descarta esta Obligación.","f":"\"¡No ha sido culpa mía!\" —Hope Summers"},
  "39063": {"n":"La extraña pareja","t":"Tu límite de Aliados se reduce en 2.\nAcción de Alter ego: agota 2 personajes que controles → coge un Aliado de tu pila de descartes, añadelo a tu mazo, barájalo y descarta esta Obligación.","f":"\"Ya lo recogeré luego.\" —Júbilo"},
  "39064": {"n":"El episodio de la ruptura","t":"Todas las cartas de Encuentro ganan Peligro.\nAcción de Alter ego: descarta 3 cartas de tu mano y elige un jugador → el jugador elegido roba 1 carta y tú descartas esta Obligación."},
  "39065": {"n":"Miradme jugar","t":"Incitar 3. Peligro.\nInterrupción obligada: cuando tengas que consultar cómo funciona una regla del juego, quedas confundido.\nAcción de Alter ego: agota tu Superhéroe y descarta una carta de Estado \"Confundido\" que tenga → descarta esta Obligación.","f":"\"¿Cómo que 'jugar' y 'poner en juego' no significan lo mismo?\" —Masacre"},
  "39066": {"n":"Mojo ante el peligro","t":"Todos los ataques enemigos ganan Brutalidad.\nInterrupción obligada: cuando un personaje sufra Daño, aumenta eso Daño en 1.\nCuando se muestre esta carta: descarta todos los demás Entornos Ubicación que haya en juego. Si esta carta se ha mostrado desde el mazo de Encuentros, gana Oleada."},
  "39067": {"n":"Vivo o muerto","t":"Vincula esta carta al Esbirro que tenga el valor impreso más altode Vida. Si no es posible, esta carta gana Oleada.\nEl Esbirro vinculado recibe +3[per_hero] de Vida.\nInterrupción obligada: cuando el Esbirro vinculado sea derrotado, cada jugador coge 1 carta de su pila de descartes y la añade a su mano."},
  "39068": {"n":"Tiburón tahúr","t":"[star] Respuesta obligada: después de que el Tiburón tahúr te ataque, descarta las 3 primeras cartas de tu mazo. Sufres tanto Daño indirecto como el número de tipos de recursos impresos distintos ([energy],[mental],[physical] o [wild]) que se hayan descartado de este modo.","f":"Lo único que hace es nadar, comer y desplumarte jugando a las cartas."},
  "39069": {"n":"Pistolero","t":"Ataque veloz.\nInterrupción obligada: cuando este Esbirro se enfrente a ti (antes de resolver su Ataque veloz), puedes gastar recursos [energy][energy]. Si lo haces, inflige tanto Daño a este Esbirro como el ATQ de tu Héroe.","f":"\"¡Desenfunda!\""},
  "39070": {"n":"Mano de póquer","t":"Cuando se muestre esta carta: roba 5 cartas. Elige 5 cartas de tu mano y descártalas. Por cada tipo de recurso impreso distinto ([energy],[mental],[physical] o [wild]) que se haya descartado de este modo, descarta una Mejora o Apoyo que controles.","f":"Cuando se juega a un juego de cartas, sólo se puede ganar o perder. No hay puntos intermedios."},
  "39071": {"t":"[star] Los ataques de Longshot ganan Penetrante.\nLongshot no se cuenta de cara a tu límite de Aliados.\nCuando se muestre esta carta: pon en juego a Longshot controlado por ti. Esta carta gana Oleada. Este efecto no puede anularse."},
  "40001a": {"t":"Respuesta: después de que Cable derrote un Plan secundario, prepáralo. (Límite de una vez por fase.)","f":"\"Puede que hayamos ganado esta batalla, pero la guerra aún no ha terminado.\""},
  "40001b": {"t":"Puedes incluir en tu mazo Planes secundarios de jugador de cualquier aspecto.\nSoldado X — Preparación: busca un Plan secundario de jugador en tu mazo y tu pila de descartes y ponlo en juego. (Baraja el mazo.)"},
  "40002": {"n":"Teleportación","t":"Acción: cambia de identidad. Todos los demás jugadores pueden cambiar a la identidad que tú hayas adoptado.","f":"\"Teleportación para dos.\" -Cable"},
  "40003": {"n":"Exploración mental","t":"Acción de Héroe (intervención): quita 3 de Amenaza de un Plan. Quita 1 de Amenaza adicional de ese Plan por cada Plan secundario que haya en la zona de victoria."},
  "40004": {"n":"Precognición","t":"Acción de Héroe: mira las X primeras cartas del mazo de Encuentros, siendo X el número de Planes secundarios que haya en la zona de victoria. Puedes descartar 1 de esas cartas. Devuelve el resto en el orden que prefieras."},
  "40005": {"n":"Descarga Telequinética","t":"Acción de Héroe (ataque): inflige 6 de Daño a un enemigo. Inflige 1 de Daño adicional a ese enemigo por cada Plan secundario que haya en la zona de victoria."},
  "40006": {"n":"Purga del tecnovirus","t":"Victoria 0.\nNingún personaje que no sea Cable puede quitar Amenaza de Purga de tecnovirus.\nMientras Purga de tecnovirus esté en la zona de victoria, Nathan Summers y Cable ganan el rasgo PSIÓNICO y Cable recibe +1 INT, +1 ATQ y +1 DEF."},
  "40007": {"t":"Respuesta: después de que se derrote un Plan secundario, prepara Graymalkin.\nRecurso: agota Graymalkin → genera un recurso [energy].","f":"La base orbital de Cable, controlada por una inteligencia artificial llamada Profesor."},
  "40008": {"n":"Profesor","t":"Acción de Alter ego: agota Profesor → elige entre robar 1 carta o buscar un Plan secundario de jugador en tu mazo y pila de descartes y añadirlo a tu mano. (Baraja el mazo.)","f":"\"Lo siento, Wade. Me temo que no puedo hacer eso.\""},
  "40009": {"n":"Hijo de Askaki","t":"Respuesta de Héroe (intervención): después de que defiendas contra un ataque enemigo, agota Hijo de Askaki y gasta un recurso de [energy] → quita tanta Amenaza de un Plan como puntuación de INT de tu Héroe."},
  "40010": {"n":"Amnesia inducida","t":"Respuesta de Héroe: después de que se derrote un Plan secundario (que no sea Permanente), añade Amnesia inducida y ese Plan secundario a la zona de victoria."},
  "40011": {"n":"Fusil de plasma","t":"Restringida.\nAcción de Héroe (ataque): agota el Fusil de plasma y gasta un recurso [energy] → inflige 1 de Daño a un enemigo por cada Plan secundario que haya en la zona de victoria (hasta un máximo de 4). Este ataque gana A distancia."},
  "40012": {"n":"Campo de fuerza telequinético","t":"Sólo en identidad de Héroe\nInterrupción de Héroe: cuando un personaje amigo vaya sufrir cualquier cantidad de Daño, descarta el Campo de fuerza telequinético → evita todo ese Daño."},
  "40013": {"n":"Salto en el tiempo","t":"Interrupción de Héroe: cuando vaya a completarse el Plan principal, retira esta carta de la partida y pon en juego un Plan secundario que este en la zona de victoria → traslada 4 de Amenaza desde el Plan principal hasta ese Plan secundario."},
  "40014": {"n":"Calibán","t":"Respuesta: después de que Calibán entre en juego, descarta cartas de la parte superior de tu mazo hasta que se descarte un Aliado FACTOR-X, X-FORCE, or PATRULLA-X. añade ese Aliado a tu mano."},
  "40015": {"t":"Respuesta: después de que Fantomex entre en juego, busca E.V.A. en tu mazo y tu pila de descartes y ponla en juego. (Baraja el mazo.)","f":"\"E.V.A. no es un vehículo. Es mi socia. Es mi mutación.\""},
  "40016": {"n":"Mancha Solar","t":"Respuesta: después de que juegues a Mancha Solar desde tu mano, elige un jugador → inflige 1 de Daño al Villano y a cada Esbirro enfrentado con el jugador elegido por cada recurso [energy] usado para pagar el coste de Mancha Solar."},
  "40017": {"n":"Planificar la misión","t":"Juega esta carta sólo si hay un Plan secundario en la zona de victoria.\nAcción de Héroe: hasta el final de la fase, los Aliados que controles no sufren Daño derivado."},
  "40018": {"n":"Pedir refuerzos","t":"Victoria 0.\nCuando se derrote esta carta: cada jugador puede buscar un Aliado en su mazo y su pila de descartes y ponerlo en juego. (Baraja el mazo.)","f":"\"¡Equipo azul, reagruparos en mi posición!\" — Bishop"},
  "40019": {"n":"Armados hasta los dientes","t":"Victoria 0.\nCuando se derrote esta carta: cada jugador puede buscar en su mazo y su pila de descartes una Mejora ARMA con un coste de 3 o menos y ponerla en juego. (Baraja el mazo.)","f":"\"Necesitaremos armas. A montones.\" — Cable"},
  "40020": {"n":"Establecer un perímetro defensivo","t":"Victoria 0.\nCuando se derrote esta carta: dale a cada Superhéroe una carta de Estado \"Duro\".","f":"\"No os preocupéis, niños. ¡No pasarán de aquí!\" — Armadura"},
  "40021": {"t":"Si Fantomex no está en juego, descarta a E.V.A.\nAcción: agota a E.V.A. → elige una opción:\n• Quita 1 de Amenazade un Plan.\n• Inflige 1 de Daño a un enemigo.\n• Cura 1 de Daño a Fantomex."},
  "40022": {"n":"Los imposibles X-Force","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 carta de GRUPO por jugador.\nSi todos tus personajes tienen el rasgo X-FORCE, Cada Aliado que controles recibe +1 INT y sufre -1 de Daño derivado ([consequential]) después de intervenir en un Plan secundario."},
  "40023": {"n":"Jefe de misión","t":"El coste para jugar Jefe de misión se reduce en 1 si tu Superhéroe tiene el rasgo SOLDADO.\nRespuesta de Héroe: después de que se derrote un Plan secundario, agota Jefe de misión → cada jugador roba 1 carta."},
  "40024": {"n":"Masacre","t":"Interrupción obligada: cuando Masacre vaya a ser derrotado por Daño derivado, en vez de eso cúrale 3 de Daño. Añade 1 ficha de Aceleración al Plan principal.","f":"\"¿Cable? No, no me interesa. Yo lo veo todo online.\""},
  "40025": {"t":"Respuesta de Héroe: después de que Deathlok entre en juego, elige una Mejora que esté en la pila de descartes de cualquier jugador, con un coste de 1 o menos y que se pueda vincular a Deathlok. Vincula esa Mejora a Deathlok."},
  "40026": {"n":"Eneamigos","t":"Equipo (Cable y Masacre). Máximo de 1 por mazo.\nAcción de Héroe (intervención): inflige 1 de Daño a Cable y Masacre. Quita 3 de Amenaza de un Plan y 3 de Amenaza de otro Plan distinto."},
  "40027": {"n":"Conseguir apoyo","t":"Victoria 0.\nCuando se derrote esta carta: cada jugador puede buscar en su mazo y en su pila de descartes un Apoyo con un coste de 3 o menos y ponerlo en juego. (Baraja el mazo.)","f":"\"Tengo lo justo que necesitamos.\" — Forja"},
  "40028": {"n":"El poder de la mente","t":"El número de recursos generados por esta carta se duplica al pagar el coste de una carta con el rasgo PSIÓNICO."},
  "40029": {"n":"Psimitarra","t":"Restringida.\nRespuesta de Héroe (ataque): después de que juegues otra carta con el rasgo PSIÓNICO, agota Psimitarra → inflige 2 de Daño a un enemigo."},
  "40030": {"n":"Arma secundaria","t":"Vincula esta carta a un Aliado. Máximo de 1 por Aliado.\nEl Aliado vinculado recibe +1 ATQ y sus ataques ganan A distancia.","f":"\"¡Caray! ¡Tío, qué disfraz más chulo!\" —Niño"},
  "40031": {"n":"Reaparición del tecnovirus","t":"Dale esta carta al jugador que lleva a Nathan Summers.\nCuando se muestre esta carta: busca Purga del Tecnovirus en tu mazo, tu pila de descartes, tu mano y la zona de victoria,y ponla en juego. (Baraja el mazo.) Vincula esta carta a Purga del Tecnovirus. Si no es posible, descarta esta carta y coge 1 carta de Encuentro boca abajo."},
  "40032": {"n":"Dyscordia","t":"Infame.\nInterrupción obligada: Cuando un jugador juege un Evento PSIÓNICO, anula los efectos de ese Evento e inflige 1 de Daño a Dyscordia.","f":"\"¡No importa cuál de los dos sea el clon, Cable; mi poder es superior sin ninguna duda!\""},
  "40033": {"n":"Regreso al futuro","t":"El jugador que lleva a Cable no puede quitar Amenaza de Planes que no sean Regreso al futuro. Los demás jugadores no pueden quitar Amenaza de Regreso al futuro.\nEl jugador que lleva a Cable no puede infligir Daño a enemigos con los que no esté enfrentado. Los demás jugadores no pueden infligir Daño a los Esbirros enfrentados con el jugador que lleva a Cable."},
  "40034": {"n":"Campo de fuerza telequinético","t":"Vincula esta carta a Dyscordia. De no ser así, vincula esta carta al Villano.\nInterrupción obligada: cuando el personaje vinculado vaya a sufrir cualquier cantidad de Daño, evita ese Daño. Si se ha evitado al menos 2 de Daño de este modo, descarta esta carta.\n[star] Aumento: Vincula esta carta al enemigo que se está activando."},
  "40035": {"n":"Exploración mental","t":"Cuando se muestre esta carta: coloca 2 de Amenaza sobre el Plan principal. Coloca 1 de Amenaza adicional sobre el Plan principal por cada Plan secundario que haya en la zona de victoria.\n[star] Aumento: quedas confundido."},
  "40036": {"n":"Descarga telequinética","t":"Cuando se muestre esta carta: sufres 2 de Daño. Sufres 1 de Daño adicional por cada Plan secundario que haya en la zona de victoria.\n[star] Aumento: quedas aturdido."},
  "40037a": {"n":"Dominó","t":"Cuando cuentes los recursos de las cartas descartadas de la parte superior de tu mazo, cada icono [wild] impreso vale por dos.\nAcción: elige una carta de tu mano. Intercambia esa carta por la primera carta de tu mazo. (Límite de una vez por ronda.)"},
  "40037b": {"t":"Acción: elige una carta de tu mano. Intercambia esa carta por la primera que haya en la parte superior de tu pila de descartes. (Límite de una vez por ronda.)"},
  "40038": {"n":"Iguana","t":"Acción: agota a Iguana, inflígele 1 de Daño y descarta la primera carta de la parte superior de tu mazo → dinflige 1 de Daño a cada enemigo por cada icono de recurso que se haya descartado de este modo."},
  "40039": {"n":"Forajida","t":"Dureza.\n[star]Interrupción: cuando Forajida ataque, descarta la primera carta de la parte superior de tu mazo → Forajida recibe +1 ATQ para este ataque por cada icono de recurso que se haya descartado de este modo."},
  "40040": {"n":"Un buen entrenamiento","t":"Acción de Héroe (ataque): inflige 4 de Daño a un enemigo y descarta la primera carta de la parte superior de tu mazo. Por cada icono de recurso que se haya descartado de este modo, inflige 1 de Daño adicional a ese enemigo."},
  "40041": {"n":"Cuestión de suerte","t":"Acción de Héroe: descarta la primera carta de la parte superior de tu mazo y cuenta los recursos que hay en ella. Por cada recurso que hayas contado de esta modo, si esa:\n[energy] - Cura 2 de Daño a un personaje.\n[mental] - Quita 2 de Amenaza de un Plan.\n[physical] - inflige 3 de Daño a un enemigo.\n[wild] - Elige 1 de las opciones anteriores."},
  "40042": {"n":"En el lugar y momento precisos","t":"Acción de Héroe (intervención): Quita 3 de Amenaza de un Plan y descarta la primera carta de la parte superior de tu mazo. Por cada icono de recurso que se haya descartado de este modo, quita 1 de Amenaza adicional de ese Plan."},
  "40043": {"n":"¡Premio!","t":"Respuesta: después de que se descarte esta carta de la parte superior de tu mazo, devuélvela a tu mazo y barájalo."},
  "40044": {"n":"Pip el perro","t":"Acción de Alter ego: agota a Pip el perro → coge 1 carta de Dominó o de la CUADRILLA que esté en tu pila de descartes y colócala en la parte superior de tu mazo.","f":"\"¿Acabas de hacerme pipí encima. salchichita mala?\" — Dominó"},
  "40045": {"n":"El Dama Pintada","t":"Respuesta: después de que descartes una carta de la parte superior de tu mazo, vincula esa carta a ésta boca abajo (hasta un máximo de 3 cartas).\nAcción de Alter ego: agota El Dama Pintada → añade a tu mano 1 de las cartas que estén viculadas aquí."},
  "40046": {"n":"Pistola de Dominó","t":"Restringida.\nAcción de Héroe (ataque): agota la Pistola de Dominó, elige un enemigo, y descarta la primera carta de la parte superior de tu mazo → inflige 1 de Daño a ese enemigo por cada icono de recurso que se haya descartado de este modo. Este ataque gana A distancia."},
  "40047": {"n":"Suerte y talento","t":"Interrupción de Héroe (defensa): cuando se ponga boca arriba una carta de aumento durante un ataque efectuado contra ti, agota Suerte y talento → anula los iconos de Aumento y la capacidad de \"Aumento\" . Dale al enemigo atacante otra carta de aumento para este ataque."},
  "40048": {"n":"Golpe de suerte","t":"Interrupción de Héroe: cuando muestres una carta de Encuentro, descarta Golpe de suerte → anula los efectos de esa carta y descártala. Muestra otra carta del mazo de Encuentros."},
  "40049": {"n":"Campo de probabilidad","t":"Interrupción: cuando uses un atributo básico, descarta la primera carta de la parte superior de tu mazo → recibes +1 a ese atributo para este uso por cada icono de recurso que se haya descartado de este modo."},
  "40050": {"n":"Feroz","t":"[star] Respuesta: después de que Feroz intervenga, descarta la primera carta de la parte superior de tu mazo. Por cada icono de recurso que se haya descartado de este modo, inflige 1 de Daño al Villano.","f":"\"He captado el rastro de mi presa.\""},
  "40051": {"n":"Loba Venenosa","t":"[star] Respuesta: después de que Loba Venenosa intervenga, nombra un tipo de carta y luego descarta la primera carta de la parte superior de tu mazo. Si esa carta es del tipo nombrado, puedes añadirla a tu mano."},
  "40052": {"n":"Igualar las posibilidades","t":"Requisito ([energy]).\nAcción de Héroe (intervención): quita 1[per_hero] de Amenaza de cada Plan secundario. Inflige 1 de Daño al Villano por cada Plan secundario que se haya derrotado de este modo."},
  "40053": {"n":"Investigación en grupo","t":"Alianza. (Los jugadores pueden pagar los costes de esta carta en grupo.)\nAcción de Héroe: Quita 3[per_hero] de Amenaza de un Plan secundario.","f":"\"Si se me permite acuñar una expresión: muchas mentes aligeran el trabajo.\" — Bestia"},
  "40054": {"n":"Eliminar a los guardias","t":"Victoria 0.\nCuando se derrote esta carta: cada jugador puede descartar del juego 1 Esbirro que no sea ÉLITE.","f":"\"A dormir, nene.\" — Lobezno"},
  "40055": {"n":"Vigilar de cerca","t":"Vincula esta carta a un Plan. Máximo de 1 por Plan.\nInterrupción de Héroe: cuando se quite cualquier cantidad de Amenaza del Plan vinculado mediante una intervención, descarta esta carta → quita esa misma cantidad de Amenaza de un Plan diferente."},
  "40056": {"n":"Osa del Atlas","t":"Acción: agota a la Osa del Atlas → mira la primera carta de la parte superior del mazo de un jugador. Si esa carta es un Evento, puedes inflingir 1 de Daño a la Osa del Atlas para añadir esa carta a la mano de su propietario."},
  "40057": {"t":"Respuesta: después de que White Fox se descarte de la parte superior de tu mazo, ponla en juego controlada por ti.","f":"\"Soy la última de mi especie. ¡Soy la última kumiho!\""},
  "40058": {"n":"La Cuadrilla","t":"Máximo de 1 por mazo.\nJuega esta carta sólo si controlas al menos 3 personajes que tengan el rasgo CUADRILLA.\nAcción de Héroe: cura 1 de Daño a todos los personajes CUADRILLA y prepáralos."},
  "40059": {"n":"Entrenamiento de superpoderes","t":"Victoria 0.\nCuando se derrote esta carta: cada jugador puede buscar en su mazo y en su pila de descartes una Mejora específica de su Superhéroe y ponerla en juego (Baraja el mazo.)","f":"\"La clase ha empezado.\" — Charles Xavier"},
  "40060": {"n":"Reserva interior","t":"Respuesta: después de que se descarte esta carta de la parte superior de tu mazo, añádela a tu mano."},
  "40061": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "40062": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "40063": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "40064": {"n":"Puntería","t":"Máximo de 1 por jugador.\nInterrupción de Héroe: cuando realices un ataque con A distancia, descarta la primera carta de la parte superior de tu mazo → este ataque inflige 1 de Daño adicional por cada icono de recurso que se haya descartado de este modo."},
  "40065": {"n":"Recuerdos del Armagedón","t":"Dale esta carta al jugador que lleva a Neena Thurman.\nEl texto de reglas impreso de tu Superhéroe se trata como si estuviera en blanco (a excepción de los RASGOS).\nAcción de Alter ego: agota tu carta de Superhéroe → descarta Recuerdos del Armagedón.","f":"De niña, Neena fue utilizada como cobaya en un programa de creación de supersoldados denominado Proyecto Armagedón."},
  "40066": {"t":"Cuando se muestre esta carta: busca 1 copia de Retroalimentación de superpoder en el mazo de Encuentros, en su pila de descartes y en la zona apartada, y vincúlala a tu carta de Superhéroe. (Baraja el mazo.)\n(Esbirro Archienemigo de Dominó.)","f":"Topaz puede manipular los poderes de los mutantes ajenos, ya sea potenciándolos."},
  "40067": {"n":"Hoy no es mi día","t":"Cuando se muestre esta carta: cada jugador debe elegir entre sufrir 1 de Daño o colocar 2 de Amenaza sobre esta carta.","f":"Dominó está teniendo un día terrible, horrible, espantoso, horroroso."},
  "40068": {"n":"Prototipo","t":"[star] Prototipo recibe +1 de Vida por cada contador de Suerte que tenga encima.\nCuando se muestre esta carta: coloca tantos contadores de Suerte sobre Prototipo como la cantidad de Daño que tenga acumulado tu Superhéroe.","f":"La buena suerte de Dominó acarrea desgracias para Prototipo, mientras que su sufrimiento le fortalece."},
  "40069": {"n":"Retroalimentación de superpoder","t":"Vincula esta carta a tu Superhéroe.\nRespuesta obligada: después de que resuelvas una capacidad de tu carta de Superhéroe o de alguna carta específica de tu Superhéroe, sufres 1 de Daño.\nAcción de Alter ego: descarta de tu mano 1 carta específica de tu Superhéroe → descarta esta carta."},
  "40070a": {"n":"Arco Voltaico","t":"[star] Interrupción obligada: cuando Arco Voltaico te ataque a ti o a un Aliado que controles, elige una opción:\n• Confunde a un personaje que controles.\n• Arco Voltaico recibe +2 ATQ para este ataque."},
  "40070b": {"n":"Arco Voltaico","t":"[star] Interrupción obligada: cuando Arco Voltaico te ataque a ti o a un Aliado que controles, elige una opción:\n• Confunde al personaje que controles que tenga la puntacion más alta de INT.\n• Arco Voltaico recibe +2 ATQ para este ataque."},
  "40071a": {"n":"Demoledor","t":"[star] Interrupción obligada: cuando Demoledor te ataque a ti o a un Aliado que controles, elige una opción:\n• Dale a Demoledor una carta de Estado \"Duro\".\n• Demoledor recibe +2 ATQ para este ataque."},
  "40071b": {"n":"Demoledor","t":"[star] Interrupción obligada: cuando Demoledor te ataque a ti o a un Aliado que controles, elige una opción:\n• Dale a Demoledor una carta de Estado \"Duro\".\n• Demoledor recibe +2 ATQ para este ataque y además este ataque gana Brutalidad."},
  "40072a": {"n":"Quimera","t":"[star] Interrupción obligada: cuando Quimera te ataque a ti o a un Aliado que controles, elige una opción:\n• gasta un recurso [mental].\n• Quimera recibe +2 ATQ para este ataque."},
  "40072b": {"n":"Quimera","t":"[star] Interrupción obligada: cuando Quimera te ataque a ti o a un Aliado que controles, elige una opción:\n• gasta recursos [mental][mental].\n• Quimera recibe +2 ATQ para este ataque."},
  "40073a": {"n":"Cuervo Gris","t":"[star] Interrupción obligada: cuando Cuervo Gris te ataque a ti o a un Aliado que controles, elige una opción:\n• Descarta la carta con el coste más alto que controles.\n• Cuervo Gris recibe +X ATQ para este ataque, siendo X el coste impreso de la carta con el coste más alto que controles."},
  "40073b": {"n":"Cuervo Gris","t":"[star] Interrupción obligada: cuando Cuervo Gris te ataque a ti o a un Aliado que controles, elige una opción:\n• Descarta todas las cartas que controles con el coste más alto.\n• Cuervo Gris recibe +X ATQ para este ataque, siendo X el coste impreso de la carta con el coste más alto que controles."},
  "40074a": {"n":"Arpón","t":"[star] Interrupción obligada: cuando Arpón te ataque a ti o a un Aliado que controles, elige una opción:\n• Sufres 2 de Daño indirecto.\n• Dale a Arpón 1 carta de aumento adicional boca abajo para este ataque."},
  "40074b": {"n":"Arpón","t":"[star] Interrupción obligada: cuando Arpón te ataque a ti o a un Aliado que controles, elige una opción:\n• Sufres 3 de Daño indirecto.\n• Dale a Arpón 1 carta de aumento adicional boca abajo para este ataque. Este ataque gana Brutalidad."},
  "40075a": {"n":"Marea","t":"[star] Interrupción obligada: cuando Marea te ataque a ti o a un Aliado que controles, elige una opción:\n• Coloca 2 de Amenaza sobre el Plan principal y 1 de Amenaza sobre cada Plan secundario.\n• Marea recibe +2 ATQ para este ataque."},
  "40075b": {"n":"Marea","t":"[star] Interrupción obligada: cuando Marea te ataque a ti o a un Aliado que controles, elige una opción:\n• Coloca 3 de Amenaza sobre el Plan principal y 1 de Amenaza sobre cada Plan secundario.\n• Marea recibe +2 ATQ para este ataque y este ataque gana A distancia y Penetrante."},
  "40076a": {"n":"Vértigo","t":"[star] Interrupción obligada: cuando Vértigo te ataque a ti o a un Aliado que controles, elige una opción:\n• Aturde a un personaje que controles.\n• Vértigo recibe +2 ATQ para este ataque."},
  "40076b": {"n":"Vértigo","t":"[star] Interrupción obligada: cuando Vértigo te ataque a ti o a un Aliado que controles, elige una opción:\n• Aturde al personaje que controles que tenga la puntuación más alta de ATQ.\n• Vértigo recibe +2 ATQ para este ataque."},
  "40077a": {"n":"Toc, Toc","t":"Contenido: Merodeadores por la cara A (usa sus caras B para jugar en modo Experto). Conjunto de Encuentros de Asedio Morlock y Normal. Dos conjuntos de Encuentros modulares (Arsenal militar y Asesinos de mutantes).\nPreparación: pon en juego la carta de Entorno Vencidos. Aparta a un lado la carta de perfidia ¡Escondeos! y todas las cartas de Aliado Morlock. Baraja los Villanos (sin mirarlos) para crear el mazo de Villanos. La carta que quede en la parte superior de este mazo está en juego."},
  "40077b": {"n":"Toc, Toc","t":"[star] Respuesta obligada: después de resolver el paso uno de la fase del Villano, coloca 1 contador de Llamada sobre esta carta. Si hay al menos 3 contadores de Llamada sobre esta carta, avanza a la etapa 2A.\nSi hay 3 Villanos debajo de Vencidos, los jugadores ganan la partida."},
  "40078a": {"n":"Masacre mutante","t":"Cuando se muestre esta carta: cada jugador coge 1 Aliado Morlock que esté apartado y lo pone en juego bajo su control(2 Aliados Morlock si es una partida en solitario). Añade la carta de Perfidia ¡Escondeos! al mazo de Encuentros. Si la etapa previa avanzó a consecuencia de los contadores de Llamada, dale a cada Aliado Morlock una carta de Estado \"Duro\"."},
  "40078b": {"n":"Masacre mutante","t":"Acción: agota un Aliado MORLOCK → coge ¡Escondeos! de la pila de descartes, añádela al mazo de Encuentros y barájalo.\nSi hay 3 Villanos debajo de Vencidos, los jugadores ganan la partida.\nSi se completa esta etapa o no quedan Aliados Morlock en juego, los jugadores pierden la partida."},
  "40079": {"t":"Victoria -1.\nNo se cuenta de cara a tu límite de Aliados. Las capacidades de cartas no pueden retirar este Aliado del juego.\nInterrupción obligada: cuando un enemigo te ataque, en vez de eso atacará a un Morlock que controles."},
  "40080": {"n":"¡Escondeos!","t":"Oleada.\nCuando se muestre esta carta: Dale a 1 Aliado MORLOCK una carta de Estado \"Duro\".\n[star] Aumento: Dale a 1 MORLOCK Aliado una carta de Estado \"Duro\". Dale al Villano 1 carta de aumento adicional para esta activación."},
  "40081a": {"n":"Vencidos","t":"Sólo en modo Normal.\nLas cartas que estén debajo de ésta no se consideran en juego.\nRespuesta obligada: después de que el Villano sea derrotado, coloca su carta debajo de ésta. Descarta a todos los Esbirros que se llamen igual que el primer Villano de la parte superior del mazo de Villanos. (Ese Villano está en juego.) El Villano se activa contra todos los jugadores siguiendo el orden de jugadores."},
  "40081b": {"n":"Vencidos","t":"Sólo en modo Experto.\nLas cartas que estén debajo de ésta no se consideran en juego. El Villano gana Represalia 1 por cada carta que haya debajo de ésta.\nRespuesta obligada: después de que el Villano sea derrotado, coloca su carta debajo de ésta. Descarta a todos los Esbirros que se llamen igual que el primer Villano de la parte superior del mazo de Villanos. (Ese Villano está en juego.) El Villano se activa contra todos los jugadores siguiendo el orden de jugadores."},
  "40082": {"n":"Encolerizado","t":"Vincula esta carta al Villano.\nAcción de Héroe: agota un personaje que controles y gasta X recursos de cualquier tipo, siendo X el número de Villanos que haya debajo de Vencidos → descarta esta carta.\n[star] Aumento: esta carta recibe +X iconos de Aumento ([boost]), siendo X el número de Villanos que haya debajo de Vencidos."},
  "40083": {"n":"Al límite","t":"Vincula esta carta al Villano.\nMientras haya exactamente 1 Villano debajo de Vencidos, el Villano vinculado gana Tesón.\nMientras haya exactamente 2 Villanos debajo de Vencidos, el Villano vinculado gana Firmeza.\nAcción de Héroe: el Villano vinculado te ataque → descarta esta carta."},
  "40084": {"n":"Por cualquier medio","t":"Cuando se muestre esta carta: coloca 1[per_hero] de Amenaza adicional sobre esta carta por cada Villano que haya debajo de Vencidos."},
  "40085": {"n":"En pleno caos","t":"Cuando se muestre esta carta: coloca 1[per_hero] de Amenaza adicional sobre esta carta por cada Villano que haya debajo de Vencidos."},
  "40086": {"n":"Merodear no es fácil","t":"Cuando se muestre esta carta: coloca 1[per_hero] de Amenaza adicional sobre esta carta por cada Villano que haya debajo de Vencidos."},
  "40087": {"n":"Control del territorio","t":"Asalto. (Las intervenciones básicas contra ese Plan usan ATQ en vez de INT.)\nCuando se muestre esta carta: coloca 1[per_hero] de Amenaza adicional sobre esta carta por cada Villano que haya debajo de Vencidos."},
  "40088": {"n":"Volver a la acción","t":"Cuando se muestre esta carta: dale a el Villano una carta de Estado \"Duro\". coloca tanta Amenaza sobre el Plan principal como número de Villanos que haya debajo de Vencidos.\n[star] Aumento: si controlas un Aliado Morlock, elige entre infligirle 1 de Daño o gastar 1 recurso de cualquier tipo."},
  "40089": {"n":"Buscar a los débiles","t":"Cuando se muestre esta carta (Alter ego): esta carta gana Oleada.\nCuando se muestre esta carta (Héroe): el Villano te ataque. Si hay al menos 1 Villano debajo de Vencidos, este ataque gana Brutalidad.\n[star] Aumento: si esta activación es un ataque, gana Brutalidad."},
  "40090": {"n":"Armamento pesado","t":"Vincula esta carta al enemigo que tenga la puntación más alta de ATQ.\nEl enemigo vinculado gana Represalia 2.\nRespuesta de Héroe: después de que ataques al enemigo vinculado, gasta 2 recursos del mismo tipo → descarta esta carta."},
  "40091": {"n":"Exoesqueleto de titanio","t":"Vincula esta carta al enemigo que tenga menos Vida restante.\nEl enemigo vinculado no puede sufrir más de 2 puntos de Daño a consecuencia de un solo ataque.\nAcción de Héroe: elige entre gastar 3 recursos de cualquier tipo o bien quitarle una carta de Estado \"Confundido\" o \"Aturdido\" al enemigo vinculado → descarta esta carta."},
  "40092": {"n":"Collar inhibidor","t":"Vincula esta carta a tu Superhéroe.\nEl texto de reglas impreso de tu Superhéroe se trata como si estuviese en blanco (a excepción de los rasgos).\nAcción: elige entre agota un personaje que controles o sufrir 3 de Daño → descarta esta carta. (Cualquier jugador puede hacer esto.)"},
  "40093": {"n":"El apoyo del senador","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: el jugador inicial descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Accesorio, y muestra esa carta.","f":"This kind of hardware isn't found sobre the black market. Someone high up in the U. S. government must be supplying it."},
  "40094": {"n":"Arco Voltaico","t":"Represalia 1.\n[star] Interrupción obligada: cuando Arco Voltaico te ataque a ti o a un Aliado que controles, elige una opción:\n• Confunde a un personaje que controles.\n• Arco Voltaico recibe +2 ATQ para este ataque."},
  "40095": {"n":"Demoledor","t":"Guardia.\n[star] Interrupción obligada: cuando Demoledor te ataque a ti o a un Aliado que controles, elige una opción:\n• Dale a Demoledor una carta de Estado \"Duro\".\n• Demoledor recibe +2 ATQ para este ataque."},
  "40096": {"n":"Quimera","t":"Patrulla.\n[star] Interrupción obligada: cuando Quimera te ataque a ti o a un Aliado que controles, elige una opción:\n• gasta un recurso [mental].\n• Quimera recibe +2 ATQ para este ataque."},
  "40097": {"n":"Cuervo Gris","t":"Represalia 1.\n[star] Interrupción obligada: cuando Cuervo Gris te ataque a ti o a un Aliado que controles, elige una opción:\n• Descarta la carta con el coste más alto que controles.\n• Cuervo Gris recibe +X ATQ para este ataque, siendo X el coste impreso de la carta con el coste más alto que controles."},
  "40098": {"n":"Arpón","t":"Guardia.\n[star] Interrupción obligada: cuando Arpón te ataque a ti o a un Aliado que controles, elige una opción:\n• Sufres 2 de Daño indirecto.\n• Arpón recibe +2 ATQ para este ataque y este ataque gana Penetrante."},
  "40099": {"n":"Marea","t":"Patrulla.\n[star] Interrupción obligada: cuando Marea te ataque a ti o a un Aliado que controles, elige una opción:\n• coloca 2 de Amenaza sobre el Plan principal y 1 de Amenaza sobre cada Plan secundario.\n• Marea recibe +2 ATQ para este ataque."},
  "40100": {"n":"Vértigo","t":"Guardia.\n[star] Interrupción obligada: cuando Vértigo te ataque a ti o a un Aliado que controles, elige una opción:\n• Aturde a un personaje que controles.\n• Vértigo recibe +2 ATQ para este ataque."},
  "40101": {"n":"Asesinos de mutantes","t":"Todos los Esbirros MERODEADORES ganan Ataque veloz.\nCuando se muestre esta carta: coloca 1 de Amenaza adicional sobre esta carta por cada personaje que esté en juegoy tenga al menos 1 de los siguientes rasgos: MUTANTE, FACTOR-X, X-FORCE o PATRULLA-X."},
  "40102": {"n":"Compinchados","t":"Cuando se muestre esta carta: descarta cartas del mazo de Encuentros hasta que se descarte un Esbirro de los MERODEADORESque no se llame igual que una carta que ya esté en juego. Pon en juego ese Esbirro enfrentado a ti."},
  "40103a": {"n":"Larguémonos de aquí","t":"Contenido: Merodeadores por la cara A (usa sus caras B para jugar en modo Experto). Conjuntos de Encuentros de A la fuga, Asesinos de mutantes, y Normal. Dos conjuntos de Encuentros modulares (Arsenal militar y Chicos Malos).\nPreparación: pon en juego 1 Villano de los MERODEADORES aleatorio. Retira de la partida al Esbirro que se llame igual que el Villano, junto con todos los demás Villanos. Vincula al Villano el Accesorio Secuestrador de Hope, con la cara CONFIADO boca arriba."},
  "40103b": {"n":"Larguémonos de aquí","t":"Todos los Esbirros MERODEADORES ganan Tesón. En modo Experto, el Villano también gana Tesón.\nCuando se muestre esta carta: cada jugador busca un Esbirro de los MERODEADORES en el mazo de Encuentros y lo pone en juego enfrentado a él. (Baraja el mazo.)\nSi se completa esta etapa, los jugadores pierden la partida."},
  "40104a": {"n":"Escapar con Hope","t":"Cuando se muestre esta carta: cada jugador busca un Esbirro de los MERODEADORES en el mazo de Encuentros y lo pone en juego enfrentado a él. (Baraja el mazo.) Dale una carta de Estado \"Duro\" a cada enemigo MERODEADORES.","f":"Having taken a pounding, the Merodeadores redouble their efforts to escape with their captive."},
  "40104b": {"n":"Escapar con Hope","t":"Todos los Esbirros MERODEADORES ganan Guardia y Tesón. En modo Experto, el Villano también gana Tesón.\nSi el Villano es derrotado, los jugadores ganan la partida.\nSi se completa esta etapa, los jugadores pierden la partida."},
  "40105a": {"n":"Secuestrador de Hope","t":"Permanente.\n[star] Interrupción obligada: cuando el Villano vaya a atacarte, si hay un Esbirro de los MERODEADORES enfrentado a ti, en vez de eso el Villano ejecuta el Plan.\nInterrupción obligada: cuando el Villano vaya a ser derrotado,en vez de eso restablece su Vida a su valor impreso. Dale la vuelta a esta carta y muéstrala."},
  "40105b": {"n":"Secuestrador de Hope","t":"Permanente.\nEl Villano recibe +6[per_hero] de Vida.\nCuando se muestre esta carta: el Plan avanza a la etapa 2A. Este efecto no puede anularse.\n[star] Interrupción obligada: cuando el Villano vaya a atacarte, si hay un Esbirro de los MERODEADORES enfrentado a ti, en vez de eso el Villano ejecuta el Plan."},
  "40106": {"n":"Aprovechando la confusión","t":"Vincula esta carta al enemigo que tenga menos Vida restante.\nInterrupción obligada: cuando vaya a infligirse cualquier cantidad de Daño al enemigo vinculado, en vez de eso colócala sobre esta carta. Si hay al menos 3 de Daño sobre esta carta, el enemigo vinculado ataca al jugador que haya infligido el Daño que se acaba de colocar sobre ella. Luego descarta esta carta."},
  "40107": {"n":"Arma favorita","t":"Vincula esta carta a Cuervo Gris o a Arpón. De no ser así, vincula esta carta al enemigo MERODEADORES que tenga la puntación más baja de ATQ.\n[star] Los ataques del enemigo vinculado ganan A distancia, Brutalidad y Penetrante.\nRespuesta de Héroe: después de que tu Héroe defienda contra un ataque del enemigo vinculado y no sufra ningún Daño → descarta esta carta."},
  "40108": {"n":"Encerrona","t":"Cuando se derrote esta carta: el jugador que haya derrotado este Plan busca un Esbirro de los MERODEADORES en el mazo y la pila de descartes de Encuentros y lo pone enfrentado a él. (Baraja el mazo.)"},
  "40109": {"n":"Pura fuerza","t":"Mientras Demoledor esté en juego, este Plan gana el icono de Crisis ([crisis]).\nMientras Quimera esté en juego, este Plan gana el icono de Amplificación ([amplify])."},
  "40110": {"n":"Vorágine","t":"Cuando se muestre esta carta: agota un personaje que controles. Si los siguientes enemigos están en juego:\n• Arco Voltaico — Aturde a un personaje que controles.\n• Marea — Sufres 3 de Daño indirecto.\n• Vértigo — Confunde a un personaje que controles."},
  "40111": {"n":"Relevos","t":"Cuando se muestre esta carta: elige una opción:\n• Cada Esbirro de los MERODEADORES que esté enfrentado a ti se activa contra ti.\n• Descarta 7 cartas de la parte superior del mazo de Encuentros. Coge el primer Esbirro de los MERODEADORES que haya en la pila de descartes de Encuentros y ponlo en juego enfrentado a ti."},
  "40112": {"n":"George el Guapo","t":"Trabajo en equipo (CHICOS MALOS).\n[star] Interrupción obligada: cuando George el Guapo te ataque, agota un personaje que controles.\n[star] Aumento: agota un personaje que controles."},
  "40113": {"n":"Peludo","t":"Oleada. Trabajo en equipo (CHICOS MALOS).\n[star] Aumento: después de esta activación, devuelve a Peludo al mazo de Encuentros y barájalo."},
  "40114": {"n":"Madero","t":"Represalia 1. Trabajo en equipo (CHICOS MALOS).\n[star] Los ataques de Madero ganan Penetrante.\n[star] Aumento: si el Villano está atacando, este ataque gana Penetrante."},
  "40115": {"n":"Jaleo","t":"Trabajo en equipo (CHICOS MALOS).\nCuando se muestre esta carta: aturde a todos los personajes que controles.\n[star] Aumento: quedas aturdido."},
  "40116": {"n":"Tajada","t":"Trabajo en equipo (CHICOS MALOS). Dureza.\n[star] Interrupción obligada: cuando Tajada ataque, ponle encima 1 contador de Crecimiento. Tajada recibe +1 ATQ para este ataque por cada contador de Crecimiento que tenga encima."},
  "40117": {"n":"Por las malas","t":"Todos los Esbirros reciben +1 ATQ.\nCuando se muestre esta carta: coloca 1 de Amenaza sobre esta carta por cada Esbirro que haya en juego (2 de Amenaza por cada Esbirro de los CHICOS MALOS). Busca un Esbirro de los CHICOS MALOS en el mazo y pila de descartes de Encuentros y muéstralo. (Baraja el mazo.)"},
  "40118": {"t":"[star] Juggernaut recibe +1 ATQ por cada contador de Inercia que haya sobre esta carta.\nCuando se muestre esta carta: coloca 1 contador de Inercia sobre esta carta. Dale a Juggernaut una carta de Estado \"Duro\"."},
  "40119": {"t":"[star] Juggernaut recibe +1 ATQ por cada contador de Inercia que haya sobre esta carta.\nCuando se muestre esta carta: coloca 1 contador de Inercia sobre esta carta. Si está en juego Juggernaut desprotegido, dale la vuelta. De no ser así, dale a Juggernaut una carta de Estado \"Duro\"."},
  "40120": {"t":"[star] Juggernaut recibe +1 ATQ por cada contador de Inercia que haya sobre esta carta.\nCuando se muestre esta carta: Busca A toda máquina en el mazo y la pila de descartes de Encuentros y muéstrala. (Baraja el mazo.) Si está en juego Juggernaut desprotegido, dale la vuelta. De no ser así, dale a Juggernaut una carta de Estado \"Duro\"."},
  "40121a": {"n":"El imparable Juggernaut","t":"Contenido: Juggernaut (I) y Juggernaut (II) (Juggernaut (II) y Juggernaut (III) para jugar modo Experto). Conjuntos de Encuentros de Juggernaut, Hope Summers y Normal. Un conjunto de Encuentros modular (Tom Cassidy el Negro).\nPreparación: vincula el Casco de Juggernaut a Juggernaut. Pon en juego a Hope Summers controlada por el jugador inicial."},
  "40121b": {"n":"El imparable Juggernaut","t":"[star] Interrupción obligada: cuando vaya a completarse este Plan, en vez de eso haz todo lo siguiente:\n1. Quita toda la Amenaza de esta carta.\n2. Si está en juego Juggernaut desprotegido, dale la vuelta.\n3. Coloca 1 contador de Inercia sobre Juggernaut.\n4. Juggernaut ataca a todos los jugadores en orden de jugadores (incluso aunque tengan adoptadala identidad de sus Alter egos)."},
  "40122a": {"n":"Casco de Juggernaut","t":"Permanente. Vincula esta carta a Juggernaut.\nJuggernaut gana Firmeza y sus ataques ganan Brutalidad.\nAcción de Héroe: gasta 3 recursos del mismo tipo → quita todos los contadores de Inercia de Juggernaut. Dale la vuelta a esta carta."},
  "40122b": {"n":"Juggernaut desprotegido","t":"Permanente. Vincula esta carta a Juggernaut.\nJuggernaut sufre 1 de Daño adicional de cada carta que tenga un recurso [mental] impreso.\n[star] Respuesta obligada: después de que Juggernaut ejecute el Plan, coloca 1 contador de Inercia sobre Juggernaut. Dale la vuelta a esta carta."},
  "40123": {"n":"A toda máquina","t":"Juggernaut gana Represalia X, siendo X el número de contadores de Inercia sobre Juggernaut.\nCuando se muestre esta carta: vincula A toda máquina a Juggernaut y coloca 1 contador de Inercia sobre su carta.\nRespuesta de Héroe: después de que Juggernaut te ataque, gasta 1 recurso por cada punto de Daño que te inflija ese ataque → descarta esta carta."},
  "40124": {"n":"Cogiendo velocidad","t":"Respuesta de Héroe: después de que defiendas contra un ataque de Juggernaut, quita 1 de Amenaza de este Plan."},
  "40125": {"n":"Abrirse paso","t":"Cuando se muestre esta carta: elige una opción:\n• Sufre tanto Daño como el ATQ de Juggernaut.\n• Descarta la Mejora o Apoyo con el coste más alto que controles.","f":"\"Oh, yeah!\" — Juggernaut"},
  "40126": {"n":"Aplastamiento","t":"Cuando se muestre esta carta: elige entre sufir tanto Daño como el ATQ de Juggernaut o bien coloca 1 contador de Inercia sobre su carta.\n[star] Aumento: dale a Juggernaut una carta de Estado \"Duro\"."},
  "40127": {"n":"Aporrear el suelo","t":"Cuando se muestre esta carta: los jugadores sufren colectivamente tanto Daño indirecto como el ATQ de Juggernaut.\n[star] Aumento: sufres 1 de Daño indirecto."},
  "40128": {"n":"Pisoteo","t":"Cuando se muestre esta carta (Alter ego): Sufres 2 de Daño indirecto.\nCuando se muestre esta carta (Héroe): Juggernaut ataca al Aliado que tenga menos Vida restante.\n[star] Aumento: inflige 1 de Daño a un Aliado que controles."},
  "40129": {"n":"Ejemplar de Cyttorak","t":"En modo Experto, esta carta gana Incitar 1.\nCuando se muestre esta carta: si está en juego Juggernaut desprotegido, dale la vuelta y coloca 1 contador de Inercia sobre Juggernaut. De no ser así, coloca tanta Amenaza sobre el Plan principal como el ATQ de Juggernaut."},
  "40130": {"t":"Inicio. El jugador inicial controla a Hope Summers. Hope Summers no se cuenta de cara a tu límite de Aliados.\n[star] Las puntuaciones básicas de INT y ATQ de Hope Summers son iguales a las puntuaciones de INT y ATQ de tu Héroe.\nSi Hope Summers abandona el juego, los jugadores pierden la partida."},
  "40131": {"n":"Hope capturada","t":"Hope Summers no puede prepararse.\nCuando se muestre esta carta: agota a Hope Summers."},
  "40132": {"n":"Tom Cassidy el Negro","t":"Infame.\nTom Cassidy el Negro no puede sufrir Daño mientras esté en juego un Sauce animado.\nCuando se muestre esta carta: busca 1 copia de Sauce animado en el mazo y la pila de descartes de Encuentros y ponla en juego enfrentado a ti. (Baraja el mazo.)"},
  "40133": {"n":"Sauce animado","t":"Guardia. Ataque veloz.\n[star] Respuesta obligada: después de que Sauce animado ataque a un personaje y le inflija Daño, aturde a ese personaje.\n[star] Aumento: quedas aturdido."},
  "40134": {"n":"Reforestación","t":"Complicación 2[per_hero].\nTodas las copias de Sauce animado ganan Oleada."},
  "40135": {"n":"Malas hierbas","t":"Cuando se muestre esta carta: cada copia de Sauce animado ataca al jugador con el que esté enfrentado (incluso aunque tenga adoptada la identidad de su Alter ego). Si note han atacado de este modo, busca una copia de Sauce animado en el mazo y la pila de descartes de Encuentros y muéstrala. (Baraja el mazo.)"},
  "40136": {"n":"Mister Siniestro","t":"Respuesta obligada: después de que se coloque una carta de Estado sobre Mister Siniestro, coloca 1 de Amenaza sobre el Plan principal."},
  "40137": {"n":"Mister Siniestro","t":"Cuando se muestre esta carta: coloca 1[per_hero] tanta Amenaza sobre el Plan principal (2[per_hero] de Amenaza si Mister Siniestro tiene menos de 2 Accesorios SUPERPODER).\nRespuesta obligada: después de que se coloque una carta de Estado sobre Mister Siniestro, coloca 2 de Amenaza sobre el Plan principal."},
  "40138": {"n":"Mister Siniestro","t":"Cuando se muestre esta carta: coloca 2[per_hero] tanta Amenaza sobre el Plan principal (3[per_hero] de Amenaza si Mister Siniestro tiene menos de 2 Accesorios SUPERPODER).\nRespuesta obligada: después de que se coloque una carta de Estado sobre Mister Siniestro, coloca 3 tanta Amenaza sobre el Plan principal."},
  "40139a": {"n":"Intenciones siniestras","t":"Contenido: Mister Siniestro (I) y Mister Siniestro (II) (Mister Siniestro (II) y Mister Siniestro (III) para jugar modo Experto). Conjuntos de Encuentros de Mister Siniestro, Vuelo, Superfuerza, Telepatía, Hope Summers y Normal. Un conjunto de Encuentros modular (Chicos Malos).\nPreparación: aparta a un lado los conjuntos de Encuentros de Vuelo, Superfuerza y Telepatía. Pon en juego a Hope Summers controlada por el jugador inicial."},
  "40139b": {"n":"Intenciones siniestras","t":"Cuando se muestre esta carta: retira de la partida 1 etapa 2 aleatoria. Luego avanza a una etapa 2A aleatoria.","f":"The secret laboratory hidden deep below the abandoned orphanage is filled with vats containing innocent mutants, subjects of Siniestro's experiments."},
  "40140a": {"n":"Remontar el vuelo","f":"Mister Siniestro pretende incorporar el ADN de otro mutante a su propio genoma."},
  "40140b": {"n":"Remontar el vuelo","t":"Cuando se muestre esta carta: vincula el Accesorio Vuelo a Mister Siniestro, añade el resto del conjunto de Vuelo al mazo de Encuentros y barájalo.\nCuando se complete esta etapa: avanza a la otra etapa 2A. Si no es posible, avanza a la etapa 3A."},
  "40141a": {"n":"Aumentar la musculatura","f":"Mister Siniestro pretende incorporar el ADN de otro mutante a su propio genoma."},
  "40141b": {"n":"Aumentar la musculatura","t":"Cuando se muestre esta carta: vincula el Accesorio Superfuerza a Mister Siniestro, añade el resto del conjunto de Superfuerza al mazo de Encuentros y barájalo.\nCuando se complete esta etapa: avanza a la otra etapa 2A. Si no es posible, avanza a la etapa 3A."},
  "40142a": {"n":"Agudizar la concentración","f":"Mister Siniestro pretende incorporar el ADN de otro mutante a su propio genoma."},
  "40142b": {"n":"Agudizar la concentración","t":"Cuando se muestre esta carta: vincula el Accesorio Telepatía a Mister Siniestro, añade el resto del conjunto de Telepatía al mazo de Encuentros y barájalo.\nCuando se complete esta etapa: avanza a la otra etapa 2A. Si no es posible, avanza a la etapa 3A."},
  "40143a": {"n":"Fines siniestros","t":"Cuando se muestre esta carta: reparte a cada jugador 1 carta de Encuentro boca abajo.","f":"\"Gaze upon my power y despair!\" Siniestro cackles. \"Once I add Hope's mutation into my genetic code, I will be capable of mimicking any mutant's powers, y thus will have attained perfection!\""},
  "40143b": {"n":"Fines siniestros","t":"Interrupción obligada: cuando Mister Siniestro ataque, en vez de eso ataca a Hope Summers. (Otros personajes pueden defender contra este ataque.)\nSi se completa esta etapa, los jugadores pierden la partida.","f":"\"I should thank you,\" Siniestro sneers. \"You've done what my bumbling flunkies could not: You brought me Hope.\""},
  "40144": {"n":"Disfraz siniestro","t":"Vincula esta carta a Minister Siniestro.\nInterrupción obligada: cuando un jugador vaya a infligir Daño a Minister Siniestro, ese jugador puede gastar recursos [mental][mental]. Si no lo hace, en vez de eso infligirá ese Daño al personaje amigo que tenga menos Vida restante. Descarta esta carta (tanto si se han gastado los recursos como si no)."},
  "40145": {"n":"Soldado de Siniestro","t":"[star] Soldado de Siniestro recibe +1 PLA y +1 ATQ por cada Accesorio SUPERPODER viculado a Mister Siniestro.\n[star] Aumento: para esta activación, Mister Siniestro recibe +1 PLA y +1 ATQ por cada Accesorio SUPERPODER que tenga vinculado."},
  "40146": {"n":"Teletransportado a otro lugar","t":"Complicación 1[per_hero].\nMister Siniestro no puede sufrir Daño.\nInterrupción obligada: cuando Mister Siniestro vaya a atacar, en vez de eso ejecuta el Plan."},
  "40147": {"n":"Maestría genética","t":"Cuando se muestre esta carta: si Mister Siniestro posee los siguientes rasgos:\n• AÉREO — Sufres 2 de Daño indirecto.\n• BRUTO — Agota tu carta de Superhéroe.\n• PSIÓNICO — Coloca 2 de Amenaza sobre el Plan principal."},
  "40148": {"n":"Control molecular","t":"Cuando se muestre esta carta: dale a Mister Siniestro una carta de Estado \"Duro\". Si tiene el rasgo BRUTO, se cura 4 Daño.\n[star] Aumento: dale a Mister Siniestro una carta de Estado \"Duro\"."},
  "40149": {"n":"Planes siniestros","t":"Cuando se muestre esta carta: Mister Siniestro ejecuta el Plan. Si tiene el rasgo PSIÓNICO, quedas confundido.\n[star] Aumento: quedas confundido."},
  "40150": {"n":"Descarga siniestra","t":"Cuando se muestre esta carta (Alter ego): esta carta gana Oleada.\nCuando se muestre esta carta (Héroe): Mister Siniestro te ataca. Si tiene el rasgo AÉREO, quedas aturdido.\n[star] Aumento: quedas aturdido."},
  "40151": {"n":"Vuelo","t":"Inicio. Vincula esta carta al Villano.\nPermanente.\nEl Villano vinculado gana el rasgo AÉREO.\n[star] Los ataques del Villano vinculado ganan Brutalidad."},
  "40152": {"n":"Bombardeo Aéreo","t":"Vincula esta carta al Villano.\n[star] El Villano vinculado recibe +1 ATQ e ignora la palabra clave Represalia mientras esté atacando a un personaje que no tenga el rasgo AÉREO.\nAcción de Héroe: agota tu Héroe y gasta recursos [mental][mental] → descarta esta carta."},
  "40153": {"n":"Fuera de alcance","t":"Vincula esta carta al Villano.\nEl Villano no puede sufrir Daño a menos que el atacante o el ataque posean el rasgo AÉREO o la palabra clave A distancia.\nAcción de Héroe: agota tu Héroe y gasta recursos [energy][energy] → descarta esta carta."},
  "40154": {"n":"Posición elevada","t":"Cuando se muestre esta carta: descarta todas las cartas de Estado \"Duro\" que tenga cada personaje amigo. Los jugadores sufren colectivamente 2 de Daño indirecto (4 de Daño indirecto si el Villano tiene el rasgo BRUTO).\n[star] Aumento: si el Villano está atacando, este ataque gana Penetrante."},
  "40155": {"n":"Superfuerza","t":"Inicio. Vincula esta carta al Villano.\nPermanente.\nEl Villano vinculado gana el rasgo BRUTO y Tesón. (Un personaje con Tesón requiere de 2 cartas de Estado del mismo tipo para quedar aturdido o confundido.)"},
  "40156": {"n":"Invulnerable","t":"Vincula esta carta al Villano.\nReduce en 1 la cantidad de Daño que sufre el Villano vinculado de cada ataque.\nAcción de Héroe: gasta recursos [physical][physical] → dale al Villano una carta de Estado \"Duro\" y descarta esta carta."},
  "40157": {"n":"Objeto arrojadizo","t":"Vincula esta carta al Villano.\n[star] Los ataques del Villano vinculado ganan A distancia.\n[star] Respuesta obligada: después de que el Villano ataque, descarta esta carta."},
  "40158": {"n":"\"Dame eso\"","t":"Cuando se muestre esta carta: descarta la Mejora que controles que tenga el coste más bajo (el coste más alto si el Villano posee el rasgo PSIÓNICO). Si no se descarta ninguna Mejora de este modo, esta carta gana Oleada."},
  "40159": {"n":"Telepatía","t":"Inicio. Vincula esta carta al Villano.\nPermanente.\nEl Villano vinculado gana el rasgo PSIÓNICO y Represalia 1. (después de que se ataque a este personaje, se inflige 1 de Daño al personaje atacante.)"},
  "40160": {"n":"Conflicto imaginario","t":"Los Apoyos que controles no se pueden preparar.\nCuando se muestre esta carta: agota todos los Apoyos que controles. Si no se agota ningún Apoyo de este modo, esta carta gana Oleada.\nAcción de Alter ego: agota tu carta de Superhéroe y descarta 1 carta de la parte superior de tu mazo por cada Apoyo que controles → descarta esta carta."},
  "40161": {"n":"Cizaña","t":"Los Aliados que controles no se pueden preparar.\nCuando se muestre esta carta: agota todos los Aliados que controles. Si no se agota ningún Aliado de este modo, esta carta gana Oleada.\nAcción de Alter ego: gasta recursos [mental][mental] → descarta esta carta.","f":"\"I dare you to call me 'Peaches' again!\" — Dominó"},
  "40162": {"n":"Un paso por delante","t":"Cuando se muestre esta carta: descarta 1 carta de tu mano al azar (2 cartas al azar si el Villano tiene el rasgo AÉREO).\n[star] Aumento: si el Villano está atacando, este ataque gana Brutalidad."},
  "40163": {"n":"Dyscordia","t":"[star] Mientras Dyscordia te esté atacando, recibe +X ATQ, siendo X el número de cartas del tipo más común que haya en tu mano."},
  "40164": {"n":"Dyscordia","t":"[star] Mientras Dyscordia te esté atacando, recibe +X ATQ, siendo X el número de cartas del tipo más común que haya en tu mano.\nCuando se muestre esta carta: cada jugador descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Accesorio PSIÓNICO, y muestra esa carta."},
  "40165": {"n":"Dyscordia","t":"[star] Mientras Dyscordia te esté atacando, recibe +X ATQ, siendo X el número de cartas del tipo más común que haya en tu mano.\nRespuesta obligada: después de que ataques a Dyscordia, sufres X de Daño, siendo X el número de cartas del tipo más común que haya en tu mano."},
  "40166a": {"n":"Poder incontrolable","t":"Contenido: Dyscordia (I) y Dyscordia (II) (Dyscordia (II) y Dyscordia (III) para jugar modo Experto). Conjuntos de Encuentros de Dyscordia, Hope Summers y Normal. Dos conjuntos de Encuentros modulares (Medidas extremas e Insurrección mutante).\nPreparación: pon en juego a Hope Summers controlada por el jugador inicial. Muestra En las garras de Dyscordia."},
  "40166b": {"n":"Poder incontrolable","t":"[star] Respuesta obligada: después de resolver el paso uno de la fase del Villano, cada jugador coloca X de Amenaza sobre esta carta, siendo X el número de cartas del tipo más común que haya en sus respectivas mano. Cada jugador puede descartar 1 carta de su mano antes de calcular el valor de X.\nSi se completa esta etapa, los jugadores pierden la partida.","f":"Hope tries to mimic Dyscordia's abilities, but is quickly overwhelmed by the power."},
  "40167a": {"n":"Abandonados a vuestra suerte","f":"Hope breaks free from Dyscordia's grasp, but she struggles to contain his powerful psionic energies.\n\"I will leave Hope to finish the job of killing you all,\" Dyscordia laughs. \"I have work to do bringing about the Apocalypse!\""},
  "40167b": {"n":"Abandonados a vuestra suerte","t":"Dyscordia gana Firmeza.\nCada Superhéroe recibe +2 al tamaño de su mano. El coste en recursos para jugar cada carta de Jugador aumenta en 1.\nSi se completa esta etapa, los jugadores pierden la partida.","f":"Dyscordia is attempting to escape into the past. Who knows what havoc he will wreak?"},
  "40168a": {"n":"En las garras de Dyscordia","t":"Permanente. Complicación 6[per_hero].\nHope Summers sólo puede atacar a Dyscordia y sólo puede intervenir en este Plan.\nRespuesta obligada: después de que Dyscordia sea derrotado o se quite la última ficha de Amenaza de este Plan, dale la vuelta a esta carta y muestra Bomba viviente. Toda la Amenaza que quedara sobre esta carta se coloca sobre Bomba viviente."},
  "40168b": {"n":"Bomba viviente","t":"Victoria 1.\nDyscordia no puede ser derrotado.\nCuando se muestre esta carta: el Plan avanza a la etapa 2A. Este efecto no puede anularse.","f":"Mimicking Dyscordia's power is too much for Hope to control y threatens to overwhelm her...with explosive results!"},
  "40169": {"n":"Transferencia mental","t":"Si está en juego En las garras de Dyscordia, vincula esta carta a Hope Summers. De no ser así, vincula esta carta a tu Superhéroe.\nRespuesta obligada: después de que Dyscordia sufra cualquier cantidad de Daño, el personaje vinculado sufre esa misma cantidad de Daño. Descarta esta carta."},
  "40170": {"n":"Alteración mental","t":"Vincula esta carta a tu Superhéroe.\nRespuesta obligada: después de que juegues un Evento o Mejora, sufres 1 de Daño.\nRespuesta: después de que te recuperes, gasta un recurso [mental] → descarta esta carta."},
  "40171": {"n":"Trampa mental","t":"Vincula esta carta a tu Superhéroe.\nTus Aliados, Mejoras y Apoyos entran en juego agotados.\nAcción de Alter ego: agota 3 cartas que controles → descarta esta carta."},
  "40172": {"n":"Amnesia psiónica","t":"Vincula esta carta a tu Superhéroe.\nAumenta en 2 el coste en recursos de cada Aliado y Apoyo que juegues.\nRespuesta: después de que juegues un Aliado o Apoyo, agota tu carta de Superhéroe → descarta esta carta."},
  "40173": {"n":"Inercia psíquica","t":"Vincula esta carta a tu Superhéroe.\nAcción de Héroe: si tu Héroe ha atacado e intervenido en esta fase → descarta esta carta.","f":"\"It is...as if...something...is holding...Caliban back!\" — Caliban"},
  "40174": {"n":"Cero","t":"Guardia. Patrulla. Dureza.\nCuando se derrote esta carta: si el jugador que ha derrotado a Cero no tiene al menos 3 cartas del mismo tipo en su mano, devuelve a Cero al mazo de Encuentros y barájalo."},
  "40175": {"n":"Borrado cerebral","t":"Cuando se muestre esta carta: devuelve una Mejora o Apoyo que controles a la mano de su propietario.\nCuando se derrote esta carta: el jugador que haya derrotado este Plan devuelve una Mejora o Apoyo que controle a la mano de su propietario."},
  "40176": {"n":"Camuflaje telepático","t":"Cuando se muestre esta carta: cada jugador coloca X de Amenaza sobre esta carta, siendo X el número de cartas del tipo más común que haya en su mano."},
  "40177": {"n":"Oleada psiónica","t":"Cuando se muestre esta carta: descarta las X primeras cartas de la parte superior del mazo de Encuentros, siendo X el número de cartas del tipo más común que haya en tu mano. Quédate como carta de Encuentro boca abajo cada carta con PSIÓNICO que hayas descartado de este modo."},
  "40178": {"n":"Dominación psíquica","t":"Cuando se muestre esta carta: elige un tipo de carta, luego descarta todas las cartas de tu mano que no sean de ese tipo. Roba cartas hasta restablecer el tamaño de tu mano. Coloca 1 de Amenaza sobre el Plan principal por cada carta del tipo elegido que haya en tu mano.\n[star] Aumento: descarta 1 carta de tu mano. Luego roba 1 carta."},
  "40179": {"n":"Onda Telequinética","t":"Cuando se muestre esta carta: devuelve a tu mano una Mejora o Apoyo que controles. Dyscordia se activa contra ti.\n[star] Aumento: si tienes al menos 3 cartas del mismo tipo en tu mano, coloca 3 de Amenaza sobre el Plan principal."},
  "40180": {"n":"Estrobos","t":"Patrulla.\nCuando se muestre esta carta: elige una opción:\n• aturde a todos los personajes que controles.\n• Inflige 1 de Daño a cada personaje que controles."},
  "40181": {"t":"Mientras Tempo esté enfrentado a ti, recibes +1 al tamaño de tu mano.\n[star] Respuesta obligada: después de que Tempo se active contra ti, descarta tantas cartas de la parte superior de tu mazo como el doble del número de cartas que tengas en la mano."},
  "40182": {"n":"Pulgarcita","t":"La cantidad de Daño sufrida por Pulgarcita de cada ataque se reduce en 1 a menos que el atacante tenga el rasgo DIMINUTO.\nCuando se muestre esta carta: devuelve la Mejora con el coste más alto que controles a la mano de su propietario."},
  "40183": {"n":"Salvaje","t":"Cuando se muestre esta carta: elige una opción:\n• Salvaje te ataca.\n• Devuelve el Apoyo con el coste más alto que controles a la mano de su propietario."},
  "40184": {"n":"Medidas extremas","t":"Complicación 2[per_hero].\nRespuesta obligada: después de que entre en juego una carta de Jugador, el jugador que la controla sufre tanto Daño indirecto como el coste impreso de esa carta."},
  "40185": {"n":"Dragonesa","t":"[star] Interrupción obligada: cuando Dragonesa se active contra ti, recibe +X PLA y +X ATQ para esta activación, siendo X el número de recursos [energy] que haya en tu mano."},
  "40186": {"n":"Brazos","t":"[star] Respuesta obligada: después de que Brazos te ataque, descarta X cartas de la parte superior de tu mazo, siendo X el número de recursos [physical] que haya en tu mano.","f":"\"They call me Brazos because I give good back rubs.\""},
  "40187": {"n":"Segador","t":"[star] Interrupción obligada: cuando Segador te ataque, si tienes al menos:\n• [mental][mental] en tu mano, aturde a tu Superhéroe.\n• [mental][mental][mental][mental] en tu mano, agota tu carta de Superhéroe."},
  "40188": {"n":"Samurái","t":"[star] Respuesta obligada: después de que Samurái te ataque, coloca 1 contador de Carga sobre esta carta. Elige una opción:\n• Sufres tanto Daño como el número de contadores de Carga que haya sobre Samurái.\n• Descarta 1 carta que controles cuyo coste impreso sea igual o superior al número de contadores de Carga que haya sobre Samurái."},
  "40189": {"n":"Insurrección mutante","t":"Asalto. (Las intervenciones básicas contra ese Plan usan ATQ en vez de INT.)\nTodos los Esbirros ganan Dureza.\nCuando se muestre esta carta: coloca 2 de Amenaza adicional sobre esta carta por cada personaje del FRENTE MUTANTE DE LIBERACIÓN que haya en juego. Si no se coloca Amenaza adicional de este modo, esta carta gana Oleada."},
  "40190a": {"n":"Reunir al Equipo","t":"Este Plan no se cuenta de cara al límite de Planes secundarios de jugador.\nCuando se derrote esta carta: dale la vuelta a esta carta y pon en juego Equipo reunido.\n(La capacidad de Equipo reunido permite a cada jugador jugar un Aliado gratis desde su mazo.)"},
  "40190b": {"n":"Equipo reunido","t":"Entra en juego con 1 contador de Personal.\nAcción: Quita 1 contador de Personal de esta carta → cada jugador puede buscar en su mazo y en su pila de descartes un Aliado con un coste impreso de 3 o menos y ponerlo en juego. (Cualquier jugador puede hacer esto.)"},
  "40191a": {"n":"Establecer un refugio seguro","t":"Este Plan no se cuenta de cara al límite de Planes secundarios de jugador.\nCuando se derrote esta carta: dale la vuelta a esta carta y pon en juego Refugio seguro establecido.\n(La capacidad de Refugio seguro establecido proporciona a los jugadores la carta de Apoyo Refugio seguro.)"},
  "40191b": {"n":"Refugio seguro establecido","t":"Entra en juego con 1 contador de Refugio.\nAcción: Quita 1 contador de Refugio de esta carta → el jugador inicial pone en juego el Apoyo Refugio seguro bajo su control. (Refugio seguro es una carta de la campaña.)"},
  "40192a": {"n":"Pertecharse","t":"Este Plan no se cuenta de cara al límite de Planes secundarios de jugador.\nCuando se derrote esta carta: dale la vuelta a esta carta y pon en juego Pertrechados.\n(La capacidad de Pertrechados proporciona a cada jugador la carta de Recurso Cartucheras.)"},
  "40192b": {"n":"Pertrechados","t":"Entra en juego con 1 contador de Cartucheras.\nAcción: Quita 1 contador de Cartucheras de esta carta → cada jugador añade a su mazo 1 copia de la carta de Recurso Cartucheras y luego lo baraja. (Cartucheras es una carta de la campaña.)"},
  "40193a": {"n":"Preparativos para la misión","t":"Este Plan no se cuenta de cara al límite de Planes secundarios de jugador.\nCuando se derrote esta carta: dale la vuelta a esta carta y pon en juego Preparados para la misión.\n(La capacidad de Preparados para la misión permite a cada jugador jugar una Mejora gratis desde su mazo.)"},
  "40193b": {"n":"Preparados para la misión","t":"Entra en juego con 1 contador de Preparativos.\nAcción: Quita 1 contador de Preparativos de esta carta → cada jugador busca en su mazo y en su pila de descartes 1 Mejora con un coste impreso de 2 o menos y la pone en juego. (Cualquier jugador puede hacer esto.)"},
  "40194a": {"n":"Practicar maniobras","t":"Este Plan no se cuenta de cara al límite de Planes secundarios de jugador.\nCuando se derrote esta carta: dale la vuelta a esta carta y pon en juego Maniobras practicadas.\n(La capacidad de Maniobras practicadas proporciona a los jugadores un descuento permanente en cartas de Evento de coste elevado.)"},
  "40194b": {"n":"Maniobras practicadas","t":"Reduce en 1 el coste para jugar cada Evento que tenga un coste impreso de 3 o más.","f":"\"¡Quien llegue el último se encarga de hacer la colada durante un mes entero!\" — Mancha Solar"},
  "40195a": {"n":"Preparar las defensas","t":"Este Plan no se cuenta de cara al límite de Planes secundarios de jugador.\nCuando se derrote esta carta: dale la vuelta a esta carta y pon en juego Defensas preparadas.\n(La capacidad de Defensas preparadas otorga a cada jugador una bonificación permanente de +1 DEF y Represalia 1.)"},
  "40195b": {"n":"Defensas preparadas","t":"Cada Héroe recibe +1 DEF y gana Represalia 1.","f":"\"¡Los tenemos encima!\"\n\"Déjalos, que se van a comer mis esquirlas diamantinas.\"\n— Alud y Bling"},
  "40196": {"n":"Cartucheras","f":"\"Nunca me acuerdo de dónde he metido las cosas.\" — Masacre"},
  "40197": {"n":"Refugio seguro","t":"Acción de Alter ego: elige una opción:\n• Cura 2 de Daño a tu Superhéroe.\n• Roba 1 carta.\nCualquier jugador puede aplicar esta capacidad. (Límite de una vez por ronda y jugador.)"},
  "40198": {"n":"Lady Mente Maestra","t":"Oleada.\nCuando se muestre esta carta: sufres X Daño, siendo X el coste impreso del Evento con el coste más alto que haya en tu mano.\n[star] Aumento: descarta un Evento de tu mano."},
  "40199": {"n":"Malicia","t":"Oleada.\nCuando se derrote esta carta: vincula Malicia al Aliado que tenga el coste más alto y no sea PSIÓNICO. El Aliado vinculado se enfrenta al jugador que lo controla. El Aliado vinculado se considera un Esbirro POSEÍDO con el texto de reglas en blanco (a excepción de los RASGOS). El valor de PLA del Esbirro es igual a su INT, y no sufre Daño derivado."},
  "40200": {"n":"Disruptor","t":"Oleada.\nCuando se muestre esta carta: descarta una Mejora que controles."},
  "40201": {"n":"Desvanecedor","t":"Oleada.\nCuando se muestre esta carta: devuelve a tu mano el Apoyo que controles que tenga el coste más alto.\n[star] Aumento: devuelve a tu mano el Apoyo que controles que tenga el coste más alto."},
  "40202": {"n":"Bajo presión","t":"Oleada.\n[star] Aumento: dale al Villano 1 carta de aumento adicional para esta activación."},
  "40203": {"n":"Sobrecargado","t":"Oleada.\nCuando se muestre esta carta: elige entre descartar 1 carta de Recurso de tu mano o bien sufrir 2 de Daño.\n[star] Aumento: elige entre descartar 1 carta de Recurso de tu mano o bien sufrir 2 de Daño."},
  "40204": {"t":"Hope Summers gana todos los RASGOS que haya en tu carta de Superhéroe.\nRespuesta: después de que juegues a Hope Summers desde tu mano, busca una carta con SUPERPODER y añadela a tu mano. (Baraja el mazo.)"},
  "41001a": {"n":"Mariposa Mental","t":"[star] Control de energía psiónica — Interrupción: cuando uses uno de los atributos básicos de Mariposa Mental (INT, ATQ o DEF), dale la vuelta a 1 Mejora ENERGÍA PSIÓNICA.","f":"\"Mi mente es más afilada que cualquier espada\""},
  "41001b": {"t":"Manifestación psiónica — Preparación de la partida: pon en juego tus 2 Mejoras ENERGÍA PSIÓNICA con la cara de Cuchillo psiónico boca arriba.\nAcción: agota 1 Mejora ENERGÍA PSIÓNICA → coge 1 carta con el rasgo PSIÓNICO de tu pila de descartes, añádela a tu mazo y barájalo."},
  "41002a": {"n":"Cuchillo psiónico","t":"Permanente.\nMariposa Mental recibe +1 INT.\nRecurso de Héroe: agota el Cuchillo psiónico → genera un recurso [mental]. Puedes dale la vuelta a esta carta."},
  "41002b": {"n":"Katana psiónica","t":"Permanente. Restringida.\nMariposa Mental recibe +1 ATQ y sus ataques básicos ganan Penetrante.\nRecurso de Héroe: agota la Katana psiónica → genera un recurso [physical]. Puedes dale la vuelta a esta carta."},
  "41003": {"n":"Ángel","t":"Respuesta: después de que juegues al Ángel desde tu mano, prepara tu carta de Superhéroe.","f":"\"¿Alguien ha pedido una ayudita?\""},
  "41004": {"n":"Ráfaga de cuchilladas","t":"Acción de Héroe (ataque): inflige 2 de Daño a un enemigo. Por cada Cuchillo psiónico que controles, confunde a un enemigo de tu elección. Por cada Katana psiónica que controles, inflige 2 de Daño a un enemigo de tu elección."},
  "41005": {"n":"Detección Mental","t":"Acción de Héroe (intervención): quita 1 de Amenaza de un Plan. Por cada Cuchillo psiónico que controles, quita 2 de Amenaza adicionales de ese Plan. Por cada Katana psiónica que controles, roba 1 carta."},
  "41006": {"n":"Redirección psiónica","t":"Interrupción de Héroe (defensa): cuando vayas a sufrir cualquier cantidad de Daño provocado por un ataque enemigo, evita 2 de ese Daño. Por cada Katana psiónica que controles, evitas 2 de Daño adicionales. Por cada Cuchillo psiónico que controles, confunde a ese enemigo."},
  "41007": {"n":"Sugestión telepática","t":"Interrupción de Héroe: cuando muestres una carta del mazo de Encuentros, anula los efectos de \"Cuando se muestre esta carta\". Por cada Katana psiónica que controles, inflige 2 de Daño a un enemigo de tu elección. Por cada Cuchillo psiónico que controles, quita 1 de Amenaza de un Plan de tu elección."},
  "41008": {"n":"Rutina de entrenamiento","t":"Acción: agota Rutina de entrenamiento → busca en tu mazo una carta HABILIDAD y añádela a tu mano. (Baraja el mazo.) Si tienes adoptada tu identidad de Héroe, descarta 1 carta de tu mano.","f":"\"La práctica hace la perfección.\" — Mariposa Mental"},
  "41009": {"n":"Entrenamiento en artes marciales","t":"Mariposa Mental recibe +1 DEF.\nRespuesta de Héroe: después de que Mariposa Mental defienda contra un ataque, descarta Entrenamiento en artes marciales → prepara a Mariposa Mental."},
  "41010": {"n":"Entrenamiento psiónico","t":"Mariposa Mental ignora las palabras clave Guardia y Patrulla.\nRespuesta de Héroe: después de que Mariposa Mental intervenga, descarta Entrenamiento psiónico → confunde a un enemigo."},
  "41011": {"n":"Entrenamiento con armas","t":"Mariposa Mental gana Represalia 1.\nRespuesta de Héroe: después de que Mariposa Mental ataque, descarta Entrenamiento con armas → prepara todas las Mejoras ARMA que controles."},
  "41012": {"n":"Capitán Britania","t":"[star] El Capitán Britania sufre -1 de Daño derivado después de intervenir en un Plan secundario o atacar a un Esbirro.","f":"\"Yo seré tu adalid, ahora y por siempre.\""},
  "41013": {"n":"Cifra","t":"[star] Respuesta: después de que Cifra ataque e inflija Daño a un enemigo confundido, roba 1 carta.","f":"\"Tu lenguaje corporal me dice todo lo que necesito saber para vencerte.\""},
  "41014": {"n":"Golpe contundente","t":"Acción de Héroe (ataque): confunde a un enemigo. Si has pagado el coste de esta carta usando un recurso [physical], inflige 3 de Daño a ese enemigo."},
  "41015": {"n":"Golpe a la cabeza","t":"Respuesta de Héroe: después de que tu Héroe realice un ataque básico e inflija Daño a un enemigo, confunde a ese enemigo. Si ese enemigo ya estaba confundido, en vez de eso atúrdelo."},
  "41016": {"n":"Tender una trampa","t":"Victoria 0.\nCuando se derrote esta carta: el jugador que haya derrotado este Plan inflige 5[per_hero] de Daño al Villano.","f":"\"Tu le das por abajo y yo por arriba.\"\n\"Siempre me toca a mí por abajo.\"\n\"Vale, pues tú por arriba.\"\n\"Es que me gusta dar por abajo.\"\n— Lobezno y Masacre"},
  "41017": {"n":"Aletear como una mariposa","t":"Juega esta carta poniéndola bajo el control de cualquier jugador.\nMáximo de 1 por jugador.\nInterrupción: cuando un personaje que controles ataque a un enemigo confundido, aumenta en 1 la cantidad de Daño que ese ataque inflige a ese enemigo."},
  "41018": {"t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo X-FORCE.\nRespuesta: después de que resuelvas los efectos del enunciado \"Cuando se muestre esta carta\" de una carta de Perfidia, cura 1 de Daño a Pete Wisdom."},
  "41019": {"n":"Fuerza dirigida","t":"Interrupción de Héroe: cuando tu Héroe realice un ataque que tenga una palabra clave (A distancia, Brutalidad o Penetrante), ese ataque inflige 2 de Daño adicionales. (Máximo de 1 por ataque.)"},
  "41020": {"n":"Amor de altos vuelos","t":"Equipo (Ángel y Mariposa Mental). Máximo 1 por mazo.\nAcción de Héroe: busca en tu pila de descartes un Evento específico de Superhéroe y añádelo a tu mano. Prepara al Ángel y a Mariposa Mental."},
  "41021": {"n":"El poder de la mente","t":"El número de recursos generados por esta carta se duplica al pagar el coste de una carta con el rasgo PSIÓNICO."},
  "41022": {"t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo X-FORCE.\nAcción de Héroe: agota IPAC y dale 1 carta de Encuentro boca abajo a un jugador → ese jugador roba 2 cartas."},
  "41023": {"n":"Búnker-X","t":"Acción: agota el Búnker-X y elige un jugador cuyo Superhéroe tenga el rasgo MUTANTE → ese jugador busca cualquier carta entre las X primeras cartas de su mazo, siendo X el número de Planes secundarios que haya en la zona de victoria, y añade esa carta a su mano. (Baraja el mazo.)"},
  "41024": {"n":"Telepatía","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo PSIÓNICO.\nMáximo de 1 por jugador.\nAcción de Héroe (intervención): agota Telepatía y gasta recursos [mental][mental] → quita 2 de Amenaza de un Plan."},
  "41025": {"n":"Intercambio de cuerpos","t":"Dale esta carta al jugador que lleva a Betsy Braddock.\nNo puedes dar la vuelta a tus Mejoras de Katana psiónica.\nCuando se muestre esta carta: da la vuelta a todas tus Mejoras ENERGÍA PSIÓNICA para dejar boca arriba sus caras de Katana psiónica y agótalas.\nAcción de Alter ego: descarta de tu mano 1 carta con el Rasgo PSIÓNICO → descarta esta Obligación."},
  "41026": {"n":"Quimera","t":"[star] Interrupción obligada: cuando Quimera se active contra ti, recibe +X PLA y +X ATQ para esta activación. X es el número de recursos [mental] que hay en las cartas que controlas."},
  "41027": {"n":"Saqueo interdimensional","t":"Cuando se muestre esta carta: coloca 1 de Amenaza sobre esta carta por cada Mejora que haya en juego.","f":"\"De todas las dimensiones en las que he rapiñado, ésta es una de las más agradables.\" — Quimera"},
  "41028": {"n":"Ilusión Psiónica","t":"Vincula esta carta a tu Superhéroe.\nInterrupción obligada: cuando ataques a un enemigo, nombra un tipo de recurso y luego descarta la primera carta de la parte superior de tu mazo. Si esa carta no tiene un recurso del tipo nombrado, el objetivo de ese ataque pasa a ser un personaje amigo de tu elección y se descarta esta carta."},
  "41029": {"n":"Dragón Telequinético","t":"Cuando se muestre esta carta: sufres X de Daño indirecto, siendo X el número de recursos [mental] que haya en las cartas que controlas. Si X es 0, esta carta gana Oleada.\n[star] Aumento: elige entre gastar un recurso [mental] o bien confundir a a tu Superhéroe."},
  "41030": {"n":"Disparo de arco psiónico","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo PSIÓNICO.\nAcción de Héroe (ataque): inflige 4 Daño a un enemigo. Este ataque gana A distancia."},
  "41031": {"n":"Dominó","t":"[star] Respuesta: después de que uses uno de los atributos básicos de Dominó, intercambia una carta de tu mano por la primera carta de la parte superior de tu mazo.","f":"\"¿Quieres tentar a la suerte?\""},
  "41032": {"n":"Mazazo psiónico","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo PSIÓNICO.\nRespuesta de Héroe (ataque): después de que defiendas contra un ataque enemigo, inflige 3 de Daño a ese enemigo y atúrdelo."},
  "41033": {"t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo PSIÓNICO.\nMáximo de 1 por jugador.\nAcción de Héroe (ataque): agota Telekinesis y gasta recursos [mental][mental] → inflige 3 de Daño a un enemigo."},
  "42001a": {"n":"Ángel","t":"Ángel de la vida — Respuesta: después de que juegues un Evento AÉREO, roba 1 carta. (Límite de una vez por fase.)","f":"\"¡Nunca me siento tan libre como cuando vuelo!\""},
  "42001b": {"t":"Regenerar las alas — Acción: cura 1 de Daño a Warren Worthington III. (Límite de una vez por ronda.)","f":"\"Tengo que atarme las alas, ocultar quién soy, para poder encajar en esta sociedad.\""},
  "42001c": {"n":"Arcángel","t":"Ángel de la muerte — Respuesta: después de que juegues un Evento AÉREO, inflige Daño a un enemigo como el coste impreso de ese Evento. (Límite de una vez por fase.)"},
  "42002": {"n":"Mariposa Mental","t":"[star] Respuesta de Héroe: después de que Mariposa Mental ataque, si eres:\n• Ángel, cura 1 Daño a Mariposa Mental.\n• Arcángel, prepara a tu Héroe."},
  "42003": {"n":"Plumaje adaptativo","t":"Acción de Héroe (intervención): Si eres el Ángel, quita 3 de Amenaza de un Plan y confunde a un enemigo.\nAcción de Héroe (ataque): Si eres el Arcángel, inflige 4 de Daño a un enemigo y atúrdelo."},
  "42004": {"n":"Agilidad Aérea","t":"Interrupción de Héroe (defensa): cuando un enemigo ataque, si eres:\n• Ángel, ignora todos los iconos de Aumento ([boost]) y las capacidades de \"Aumento:\" para este ataque.\n• Arcángel, dale a tu Héroe una carta de Estado \"Duro\" y ganas Represalia 1 para este ataque."},
  "42005": {"n":"Metamorfosis","t":"Acción: cambia de identidad. Luego, si eres:\n• Warren Worthington III, roba 1 carta.\n• Ángel, quita 2 de Amenaza de un Plan.\n• Arcángel, inflige 3 de Daño a un enemigo."},
  "42006": {"n":"Vuelo natural","t":"Acción de Héroe (intervención): quita 4 de Amenaza de un Plan. Si eres el Ángel, esta intervención ignora el icono de Crisis ([crisis]) y la palabra clave Patrulla.","f":"\"Tú relájate y disfruta del vuelo.\" — Ángel"},
  "42007": {"n":"Picado cortante","t":"Acción de Héroe (ataque): inflige 6 de Daño a un enemigo. Si eres el Arcángel, este ataque gana Brutalidad y Penetrante.","f":"Apocalipsis reemplazó las alas naturales del Ángel por implantes tecnoorgánicos afilados como cuchillas."},
  "42008": {"n":"Anatomía aviar","t":"Respuesta: después de que gastes a esta carta para pagar el coste de un Evento AÉREO, devuelve ese Evento a tu mano después de resolver sus efectos."},
  "42009": {"n":"Industrias Worthington","t":"Acción: agota Industrias Worthington → coge 1 carta con el rasgo AÉREO de tu pila de descartes, añádela a tu mazo y barájalo. Si tienes adoptada la identidad de tu Alter ego, roba 1 carta.","f":"Como CEO de Industrias Worthington, Warren tiene a su plena disposición los ingentes recursos de su empresa familiar."},
  "42010": {"n":"Alas tecnoorgánicas","t":"Acción de Héroe: agota las Alas tecnoorgánicas → si eres:\n• Ángel, prepara a tu Héroe.\n• Arcángel, reduce en 2 el coste del próximo Evento AÉREO que juegues desde tu mano en esta fase."},
  "42011": {"t":"Juega esta carta sólo si tu Superhéroe tiene los rasgos X-FORCE o PATRULLA-X.\n[star] Respuesta: después de que Elixir ataque o intervenga, cura 1 de Daño a otro personaje amigo."},
  "42012": {"t":"[star] Respuesta: después de que Siryn ataque, aturde a un Esbirro."},
  "42013": {"n":"Sendero de guerra","t":"Dureza.\nRespuesta de Héroe: después de que Sendero de guerra defienda contra un ataque, juega desde tu mano un Evento que tenga una capacidad de \"Acción de Héroe\" (pagando sus costes)."},
  "42014": {"n":"Intervención aérea","t":"Interrupción: cuando un personaje vaya a sufrir cualquier cantidad de Daño de un ataque, agota un personaje AÉREO que controles → evitas hasta 3 de ese Daño."},
  "42015": {"n":"Vigilancia constante","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Aéreo.\nAcción de Héroe: prepara tu Héroe y quita 2 de Amenaza del Plan principal.","f":"\"Me siento como si todo el peso del mundo recayera sobre mis hombros.\" - Capitana Marvel"},
  "42016": {"n":"Provocación","t":"Acción de Héroe: el Villano te ataca. Los demás personajes no pueden defender contra este ataque. Roba 3 cartas.","f":"\"¡Eh,Fido! ¿Quién te ha dejado salir de la perrera?\" — Júbilo"},
  "42017": {"n":"Prestar atención médica","t":"Victoria 0.\nCuando se derrote esta carta: cada jugador cura 5 de Daño en total de entre todos los personajes que controle.","f":"\"LLevad a los heridos graves de vuelta a la mansión para atenderlos.\" — Bestia"},
  "42018": {"n":"Nido del Ángel","t":"Respuesta: después de que defiendas contra un ataque, coloca 1 contador de Fatiga sobre esta carta.\nAcción de Alter ego: quita todos los contadores de Fatiga de esta carta → cura 1 de Daño a tu Superhéroe por cada contador de Fatiga que se haya quitado de este modo."},
  "42019": {"n":"Estrategia de contención","t":"Vincula esta carta a un Plan secundario que no sea Permanente. Máximo de 1 por Plan secundario.\nRespuesta: después de que un Héroe defienda contra un ataque, quita 1 de Amenaza del Plan vinculado (2 de Amenaza si ese Héroe no ha sufrido Daño a consecuencia de ese ataque)."},
  "42020": {"n":"Bala de Cañón","t":"Interrupción: cuando Bala de Cañón vaya a sufrir cualquier cantidad de Daño derivado, reduce esa cantidad en X, siendo X el número de cartas con el rasgo AÉREO que tengas en la mano.","f":"\"¡Mas vale que no te cruces en mi camino cuando salgo disparado'!\""},
  "42021": {"n":"Amor de altos vuelos","t":"Equipo (Ángel y Mariposa Mental). Máximo 1 por mazo.\nAcción de Héroe: busca en tu pila de descartes un Evento específico de Superhéroe y añádelo a tu mano. Prepara al Ángel y a Mariposa Mental."},
  "42022": {"n":"El poder del vuelo","t":"El número de recursos generados por esta carta se duplica al pagar el coste de una carta con el rasgo AÉREO."},
  "42023": {"n":"Acrobacia aérea","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nInterrupción de Héroe: cuando un personaje AÉREO que controles use un atributo básico, agota Acrobacia aérea → ese personaje recibe un +1 a ese atributo para este uso."},
  "42024": {"n":"Influencia Apocalíptica","t":"Dale esta carta al jugador que lleva a Warren Worthington III.\nCuando se muestre esta carta: si tienes adoptada tu identidad de Arcángel, coloca 2 de Amenaza sobre el Plan principal. De no ser asi, cambia a tu identidad de Arcángel.\nAcción de Alter ego: dale al jugador inicial 1 carta de Encuentro → descarta esta carta."},
  "42025": {"n":"Arpón","t":"[star] Arpón recibe +1 ATQ mientras esté atacando a un personaje que tenga el rasgo AÉREO.\nCuando se muestre esta carta: descarta cartas de la parte superior de tu mazo hasta que descartes un Evento. Sufres tanto Daño indirecto como el coste impreso de ese Evento."},
  "42026": {"n":"Morder el anzuelo","t":"Cada ataque de un enemigo BRUTO inflige Daño indirecto.\nRespuesta obligada: después de que un personaje amigo sufra cualquier cantidad de Daño indirecto, agota ese personaje.","f":"\"Voya a cazar un pájaro.\" — Arpón"},
  "42027": {"n":"Arpón de Arpón","t":"Vincula esta carta a Arpón. Si Arpón no esta en juego, búscalo en el mazo de Encuentros y en su pila de descartes, muéstralo y vincúlale esta carta. Si no es posible, esta carta gana Oleada.\n[star] Respuesta obligada: después de que Arpón ¡te ataque, sufres 2 de Daño indirecto."},
  "42028": {"n":"Disparo de Arpón","t":"Cuando se muestre esta carta: descarta cartas de la parte superior de tu mazo hasta que descartes un Evento. Sufres tamtp Daño indirecto como el coste impreso de ese Evento. Si ese Evento tiene el rasgo AÉREO, esta carta gana Oleada.\n[star] Aumento: Sufres 2 de Daño indirecto."},
  "42029": {"n":"Bombas fuera","t":"Acción de Héroe: agota un personaje AÉREO que controles y elije un jugador → inflige 3 de Daño al Villano y a cada Esbirro que esté enfrentado a ese jugador."},
  "42030": {"n":"Vista aérea","t":"Interrupción de Héroe: cuando muestres un Esbirro que no sea ELITE, agota un personaje AÉREO que controles y descarta a esta carta → anula los efectos de esa carta y descártala. Luego muestra otra carta del mazo de Encuentros."},
  "42031": {"n":"Formación de vuelo","t":"Alianza. (Los jugadores pueden pagar los costes de esta carta en grupo.)\nAcción de Héroe: Prepara un máximo de 3 personajes que tengan el rasgo AÉREO.","f":"\"¡Bobby, sitúate a mi lado! — Arcángel"},
  "42032": {"n":"Recluta de X-Force","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo X-FORCE.\nVincula esta carta a un personaje amigo. Máximo de 1 por personaje.\nEl personaje viculado recibe +1 de Vida y gana el rasgo X-FORCE."},
  "43001a": {"t":"Arma viviente — Respuesta: después de que X-23 sufra cualquier cantidad de Daño, prepara a X-23. (Límite de una vez por fase.)","f":"\"La Fundación me creo para matar, pero yo prefiero luchar para salvar vidas.\""},
  "43001b": {"t":"Shhnk! — Preparación de la partida: pon en juego Garras de X-23.\nAcción: coge de tu pila de descartes la carta de Aliado de Honey Tejón o bien la carta de Evento Vinculo entre Hermanas, añádela a tu mazo y barájalo → roba 1 carta. (Límite de 1 vez por ronda.)"},
  "43002": {"n":"Garras de X-23","t":"Permanente.\nAcción de Héroe: Agota Garras de X-23 y sufre 2 de Daño → X-23 recibe +2 ATQ hasta el fina lde la ronda."},
  "43003": {"n":"Honey Tejón","t":"Respuesta de Héroe: después de que Honey Tejón sufra cualquier cantidad de Daño, prepara a X-23.","f":"\"No me asustas. ¡Y no dejaré que sigas jugando con mis amigos!\""},
  "43004": {"n":"Instinto animal","t":"Interrupción de Héroe: cuando X-23 realice una intervención básica, recibe +X INT para esta intervención, siendo X igual a su puntuación de ATQ.","f":"X-23 ha heredado los sentidos sobrehumanos de Lobezno... además de su encantadora personalidad."},
  "43005": {"n":"Maestria con las garras","t":"Máximo de 1 por ronda.\nAcción de Héroe: hasta el final de la ronda, X-23 recibe +2 ATQ (y sus ataques ganan Brutalidad mientras Honey Tejón este en juego)."},
  "43006": {"n":"Longevidad regenerativa","t":"Acción: cura 4 de Daño en total repartidos entre tu Superhéroe y Honey Tejón.","f":"\"Si lo que no te mata te hace más fuerte, a estas alturas yo ya debería tener la fuerza de Coloso.\" — X-23"},
  "43007": {"n":"Vinculo entre hermanas","t":"Interrupción de Héroe: cuando Honey Tejón intervenga o ataque, añade el atributo correspondiente de X-23 al atributo de Honey Tejón para este uso.","f":"\"¡Choca esos cinco!\" — Honey Tejón"},
  "43008": {"n":"Como hermanas","t":"Acción: Agota Como hermanas y descarta de tu mano una carta de X-23 → busca a Honey Tejón en tu mazo y tu pila de descartes y añádetela a tu mano. (Baraja el mazo.)","f":"El vínculo que une a Laura y Gabby va más alla de la simple genética."},
  "43009": {"n":"Revestimiento de Adamántium","t":"Recibes +2 de Vida.\nX-23 gana Represalia 1 y sus ataques básicos ganan Penetrante.","f":"Las garras de X-23 están revestidas de adamántium, por lo que están increíblemente afiladas y son casi indestructibles."},
  "43010": {"n":"Impasible","t":"Recurso: Agota esta carta y sufre 1 de Daño → genera un recurso [wild].","f":"\"¿Eso es todo lo que tienes?\" — X-23"},
  "43011": {"n":"Tolerancia al dolor","t":"Respuesta: después de que juegues una carta de X-23 (incluida ésta), cura 1 de Daño a tu Superhéroe.","f":"\"Apenas lo he notado.\" — X-23"},
  "43012": {"n":"Herida punzante","t":"Vincula esta carta a un enemigo al que X-23 o Honey Tejón haya atacado en este turno.\nEl enemigo vinculado recibe -1 ATQ.\nRespuesta obligada: después de que empiece la fase de los Jugadores, descarta esta carta e inflige 3 de Daño al enemigo vinculado."},
  "43013": {"n":"Bum Bum","t":"Acción: Agota a Bum Bum → añádele 1 contador de Bum. Luego puedes descartar a Bum Bum para infligir 1 de Daño a cada enemigo por cada contador de Bum que tenga encima.","f":"\"Tic... tac... tic... tac\""},
  "43014": {"t":"[star] Respuesta: después de que Rictor ataque, descarta la primera carta de la parte superior de tu mazo. Inflige 1 de Daño a cada Esbirro que esté enfrentado a ti por cada recurso que haya en la carta descartada."},
  "43015": {"n":"Estrella Rota","t":"[star] Interrupción: cuando Estrella Rota ataque a un Esbirro, enfréntate a ese Esbirro. Si ya estabas enfrentado a él, Estrella Rota recibe +1 ATQ para este ataque.","f":"Estrella Rota es un diestro espadachín con la capacidad de rajar el tejido del espacio para teletransportarse a grandes distancias."},
  "43016": {"n":"Impacto crítico","t":"Juega esta carta sólo si hay un Plan secundario en la zona de victoria.\nRespuesta de Héroe: después de que ataques a un enemigo, atúrdelo."},
  "43017": {"n":"Momento triunfal","t":"Respuesta de Héroe: después de que ataques y derrotes a un enemigo, cura 1 de Daño a tu Héroe por cada punto de Daño sobrante infligido a ese enemigo mediante ese ataque."},
  "43018": {"n":"Mantenerlos ocupados","t":"Victoria 0.\nAsalto. (Las intervenciones básicas contra este Plan usan ATQ en vez de INT.)\nCuando se derrote esta carta: el jugador que haya derrotado este plan quita 5[per_hero] de Amenaza del Plan principal."},
  "43019": {"n":"\"Ya me has cabreado\"","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nMientras la Vida restante de tu Héroe sea inferior a la mitad de su Vida inicial, Tu Héroe recibe +1 ATQ y -1 INT."},
  "43020": {"n":"El método directo","t":"Vincula esta carta a un Plan secundario que no sea Permanente. Límite de 1 por Plan secundario.\nEl Plan vinculado gana Asalto. (Las intervenciones básicas contra este Plan usan ATQ en vez de INT.)"},
  "43021": {"n":"Entrenamiento especializado","t":"Victoria 0.\nCuando se derrote esta carta: todo jugador que no controle una Mejora ESPECIALIZACIÓN elige 1 Mejora ESPECIALIZACIÓN que esté apartada y la pone en juego bajo su control."},
  "43022": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "43023": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "43024": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "43025": {"t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo X-FORCE.\nAcción de Héroe: agota IPAC y dale 1 carta de Encuentro boca abajo a un jugador → ese jugador roba 2 cartas."},
  "43026": {"n":"Búnker-X","t":"Acción: agota el Búnker-X y elige un jugador cuyo Superhéroe tenga el rasgo MUTANTE → ese jugador busca cualquier carta entre las X primeras cartas de su mazo, siendo X el número de Planes secundarios que haya en la zona de victoria, y añade esa carta a su mano. (Baraja el mazo.)"},
  "43027": {"n":"Aguante","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nRecibes +3 de Vida."},
  "43028": {"n":"Aislamiento","t":"Dale esta carta la jugador que lleva a Laura Kinney.\nBusca a Honey Tejón en tu mano, mazo, pila de descartes y zona de juego, y colócala boca abajo debajo de esta carta. Si no es posible, descarta esta carta y coge 1 carta de Encuentro boca abajo.\nRespuesta: después de que realices una recuperación básica, descarta esta obligación y a Honey Tejón."},
  "43029": {"n":"Dama Mortal","t":"Cuando se derrote esta carta: el jugador que haya derrotado a este Esbirro descarta la primera carta del mazo de Encuentros y sufre 1 de Daño indirecto por cada icono de Aumento ([boost]) que haya en esta carta."},
  "43030": {"n":"En aras de la venganza","t":"Todos los enemigos ganan Represalia 1.","f":"\"Qué niña tan mona. Sería una lástima que la ocurriese algo malo.\" — Dama Mortal"},
  "43031": {"n":"Modificaciones cibernéticas","t":"Vincula esta carta a dama Mortal. Si no es posible, descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Esbirro. Pon en juego ese Esbirro enfrentado a ti y vincúlale esta carta.\nInterrupción obligada: cuando el Esbirro vinculado vaya a ser descartado, en vez de eso devuélvelo al mazo de Encuentros y barájalo."},
  "43032": {"n":"Herida crítica","t":"Vincula esta carta a tu Superhéroe.\nInterrupción obligada: cuando termine tu turno, descarta esta carta y sufre 4 de Daño."},
  "43033": {"n":"Descuartizamiento","t":"Cuando se muestre esta carta: descarta 1 carta de tu mano al azar y sufre tanto Daño como el número de recursos impresos en ella.\n[star] Aumento: descarta 1 carta de tu mano al azar y sufre tanto Daño como el número de recursos impresos en ella."},
  "43034": {"n":"Especialista en combate","t":"Enlazada (Entrenamiento especializado).\nTu Héroe recibe +1 ATQ.\nRespuesta de Héroe: después de que tu Héroe realice un ataque básico, agota esta carta → roba 1 carta."},
  "43035": {"n":"Especialización en defensa","t":"Enlazada (Entrenamiento especializado).\nTu Héroe recibe +1 DEF.\nRespuesta de Héroe: después de que tu Héroe realice una defensa básica, agota esta carta → roba 1 carta."},
  "43036": {"n":"Especialista en vanguardia","t":"Enlazada (Entrenamiento especializado).\nTu Héroe recibe +4 de Vida.\nRespuesta: después de que tu Superhéroe sufra Daño a consecuencia de un ataque enemigo, agota esta carta → roba 1 carta."},
  "43037": {"n":"Especialista en vigilancia","t":"Enlazada (Entrenamiento especializado).\nTu Héroe recibe +1 INT.\nRespuesta de Héroe: después de que tu Héroe realice una intervención básica, agota esta carta → roba 1 carta."},
  "43038": {"n":"Treta Previsible","t":"Juega esta carta sólo si hay un Plan secundario en la zona de victoria.\nInterrupción de Héroe: cuando se muestre una carta de Perfidia del mazo de Encuentros, anula su efecto de \"Cuando se muestre esta carta\"."},
  "43039": {"n":"Alentar al Equipo","t":"Victoria 0.\nCuando se derrote esta carta: cura 2 de Daño a cada Aliado.","f":"\"¡Adelante, equipo!¡La victoria es nuestra!\" — Cíclope"},
  "43040": {"n":"Anticiparse al Ataque","t":"Juega esta carta sólo si hay un Plan secundario en la zona de victoria.\nInterrupción de Héroe (defensa): cuando un enemigo inicie un ataque, dale a tu Héroe una carta de Estado \"Duro\"."},
  "44001a": {"n":"Masacre","t":"El degenerado regenerante — Interrupción obligada: cuando vayas a ser derrotado, en vez de eso fija tu medidor de vida en 1, cambia a la identidad de Alter ego, y añade 1 ficha de Aceleración al Plan principal."},
  "44001b": {"t":"Romper la cuarta pared — Acción: descarta una carta de tu mano → busca un Evento de Masacre en tu mazo y añádelo a tu mano. (Límite de 1 vez por ronda.)","f":"\"Unas veces soy mutante, y otras no. Depende de a quién le preguntes\""},
  "44002": {"t":"[star] Cable recibe +1 INT y +1 ATQ por cada ficha de Aceleración que haya sobre el Plan principal (hasta un máximo de of +3 INT y +3 ATQ.)","f":"\"Wade, eres mi mejor colega!\""},
  "44003": {"n":"Cansino","t":"Acción de Héroe: elige una opción:\n• Coloca 1 ficha de Aceleración sobre el Plan principal → aturde y confunde al Villano.\n• agota la carta de Superhéroe de un jugador → ese jugador roba 1 carta por cada ficha de Aceleración que haya sobre el Plan principal."},
  "44004": {"n":"Máximo esfuerzo","t":"Acción de Héroe (ataque): sufre cualquier cantidad de Daño, hasta un máximo igual a tu Vida restante → inflige esa misma cantidad de Daño a un enemigo.","f":"\"Esto me va a doler a mí tanto como a ti.\" — Masacre"},
  "44005": {"n":"Metaconocimiento","t":"Interrupción de Héroe: cuando se muestre una carta de Encuentro, anula todos sus efectos y descártala. Sufres 1 de Daño por cada icono ([star] y [boost]) que haya en el recuadro de aumentos de esa carta.","f":"\"It says here I defeat you with a wedgie.\" — Masacre"},
  "44006": {"n":"\"¡Holi!\"","t":"Acción de Héroe (intervención): sufre cualquier cantidad de Daño, hasta un máximo igual a tu Vida restante → quita esa misma cantidad de Amenaza de un Plan.","f":"\"No os importa que me deje caer,¿Verdad?\" — Masacre"},
  "44007": {"n":"Secuencia de entrenamiento","t":"Esta carta genera 1 recurso [wild] por cada ficha de Aceleración que haya sobre el Plan principal (hasta un máximo de 3 recursos adicionales)."},
  "44008": {"n":"Puesto de chimichangas","t":"Respuesta: después de que un Superhéroe realice una recuperación básica, agota el Puesto de chimichangas → prepara esa carta de Superhéroe.","f":"\"¿Alguien ha dicho 'Chimichanga'? Ah, no. Ha sido el sonido de mi cráneo y mi cerebro curándose.\" — Masacre"},
  "44009": {"n":"Armado hasta los dientes","t":"Respuesta: después de que juegues Armado hasta los dientes, busca en tu colección 1 Mejora ARMA de cualquier aspecto y vincúlala boca abajo a esta carta.\nAcción: agota Armado hasta los dientes → intercambia la carta qué esta vinculada aquí por una Mejora ARMA que controles."},
  "44010": {"n":"Katana de Masacre","t":"Restringida.\nAcción de Héroe (ataque): agota la Katana de Masacre y sufre 1 de Daño → inflige 2 de Daño a un enemigo. Este ataque gana Penetrante."},
  "44011": {"n":"Esto no ha terminado...","t":"Vincula esta carta al Plan principal.\nEl umbral de Amenaza del Plan vinculado aumenta en 2 por cada ficha de Aceleración que tenga encima.","f":"\"Te tengo justo donde quería.\" — Masacre"},
  "44012": {"n":"Esta carta está que arde","t":"Respuesta obligada: después de que termine tu turno, si esta carta está en tu mano, sufres 1 de Daño.\nAcción de Héroe (ataque): inflige X de Daño a un enemigo. X es la cantidad de Daño que tengas acumulado."},
  "44013": {"n":"Pulgoso","t":"Represalia 1. Dureza.\nCuando se derrote esta carta: inflige 1 de Daño a un enemigo."},
  "44014": {"n":"Cabezasacre","t":"[star] Respuesta: después de que Cabezasacre ataque e inflija Daño a un Esbirro, ese Esbirro ataca a otro enemigo de tu elección."},
  "44015": {"n":"Niño Masacre","t":"[star] Los ataques del Niño Masacre ganan Penetrante.","f":"\"Enhorabuena por tenerme en tu mazo.\""},
  "44016": {"n":"Lady Masacre","t":"Cuando se derrote esta carta: derrota a un Esbirro que no sea ÉLITE."},
  "44017": {"n":"Es sólo un rasguño","t":"Interrupción de Héroe (defensa): cuando vayas a sufrir cualquier cantidad de Daño a causa de un ataque, evitas 1 de ese Daño por cada [crisis], [acceleration], [amplify], y [hazard] que haya en juego."},
  "44018": {"n":"Sopapo","t":"Máximo de 1 por mazo.\nAcción de Héroe (ataque): inflige 5 de Daño a un enemigo. Aturde a ese enemigo.","f":"¡Poing!"},
  "44019": {"n":"Bombazo","t":"Máximo de 1 por mazo.\nAcción de Héroe: inflige 10 de Daño al Villano. inflige 1 de Daño a cada enemigo y Héroe por cada [crisis], [acceleration], [amplify], y [hazard] que haya en juego."},
  "44020": {"n":"Indignación","t":"Máximo de 1 por mazo.\nAcción: prepara un Aliado. Ese Aliado recibe +1 ATQ hasta el final de la fase.","f":"\"¿Te traigo un taburete, canijo?\" — Sargento Masacre"},
  "44021": {"n":"\"Yo me encargo\"","t":"Acción de Héroe: si los iconos siguientes están al menos en 1 carta que este en juego:\n[crisis] — inflige 3 de Daño a un enemigo.\n[acceleration] — Quita 2 de Amenaza de un Plan.\n[amplify] — Prepara un Aliado que controles.\n[hazard] — Roba 1 carta."},
  "44022": {"n":"No es responsabilidad mía","t":"Máximo de 1 por mazo.\nInterrupción: cuando vaya a colocarse cualquier cantidad de Amenaza sobre un Plan, en vez de eso tú o tu aliado sufrís esa misma cantidad de Daño."},
  "44023": {"n":"Limpieza a fondo","t":"Máximo de 1 por mazo.\nAcción de Héroe (intervención): quita 5 de Amenaza del Plan principal, ignorando el icono de Crisis ([crisis]). Quita 1 de Amenaza de cada Plan por cada [crisis], [acceleration], [amplify], y [hazard] que haya en juego.","f":"\"¡ Esta carta ha hecho llorar al traductor!\" — Masacre"},
  "44024": {"n":"Vivir peligrosamente","t":"Victoria 0.\nCada Superhéroe recibe +2 al tamaño de su mano.","f":"\"♫ ¡Nunca dejo de sentirme bien! Ni aunque me atropelle un tr...♪\" — Masacre"},
  "44025": {"n":"Confianza","t":"Máximo de 1 por mazo.\nEl número de recursos generados por esta carta se duplica si tu carta de Superhéroe ha acumulado menos de 5 de Daño (Se triplica si no tienes ningún Daño)."},
  "44026": {"n":"Autocontrol","t":"Máximo de 1 por mazo.\nEl número de recursos generados por esta carta se duplica si tu carta de Superhéroe ha acumulado menos de 5 de Daño (Se triplica si no tienes ningún Daño)."},
  "44027": {"n":"Instinto de Supervivencia","t":"Máximo de 1 por mazo.\nEl número de recursos generados por esta carta se duplica si tu carta de Superhéroe ha acumulado menos de 5 de Daño (Se triplica si no tienes ningún Daño)."},
  "44028": {"n":"Ponte las pilas","t":"Reduce en 2 el coste para jugar Ponte las pilas si no has ganado tu anterior partida de Marvel Champions.\nInterrupción obligada: cuando un jugador vaya a ser derrotado, en vez de eso fija tu medidor de vida en 1 y cambia a la identidad de Alter ego. Retira esta carta de la partida."},
  "44029": {"n":"Factor curativo","t":"Máximo de 1 por jugador.\nRespuesta: después de que empiece la fase de los Jugadores, agota Factor curativo → cura 2 de Daño a tu Superhéroe.","f":"\"Now I'm the best at whatever it is Wolverine does.\" — Masacre"},
  "44030": {"n":"Cabezonería","t":"Máximo de 1 por mazo.\nAcción de Héroe: gasta un recurso [physical] y agota esta carta → prepara tu Héroe.","f":"\"¿Claudicar? No sé qué significa ese palabro.\" — Masacre"},
  "44031": {"n":"Eneamigos","t":"Equipo (Cable y Masacre). Máximo de 1 por mazo.\nAcción de Héroe (intervención): inflige 1 de Daño a Cable y Masacre. Quita 3 de Amenaza de un Plan y 3 de Amenaza de otro Plan distinto."},
  "44032": {"n":"El mercenario bocazas","t":"Dale esta carta la jugador que lleva a Wade Wilson.\nAgota todos los Aliados que controles. Los Aliados que controles no se pueden preparar. Los demas jugadores no pueden resolver capacidades de cartas de Jugador durante tu turno.\nRespuesta obligada: después de que termine la fase de los Jugadores, si tu no has hablado para nada durante esta fase, descarta esta carta.","f":"\"¡Es por algo que he dicho!\" — Masacre"},
  "44033": {"t":"[star] Interrupción obligada: cuando Butler ejecute el Plan, coloca esa Amenaza sobre Cobaya involuntaria (si es posible).\n(Esbirro Archienemigo de Masacre.)\n[star] Aumento: quedas confundido."},
  "44034": {"n":"Cobaya involuntaria","t":"Respuesta obligada: después de que Masacre sufra cualquier cantidad de Daño, coloca 1 de Amenaza sobre esta carta. Luego, si hay al menos 10 de Amenaza aquí, retira esta carta de la partida.","f":"Butler pretende estudiar los poderes de regeneración de Masacre para curar el cancer de su hermana."},
  "44035": {"t":"Vincula esta carta a tu Superhéroe.\nEl texto de reglas de tu Superhéroe se trata como si estuviese en blanco (a excepción de los RASGOS).\nAcción de Alter ego: gasta recursos [mental][mental] → descarta esta carta.\n[star] Aumento: vincula Tabula Rasa 16 a tu carta de Superhéroe.","f":"Butler utilizó esta droga para borrar el recuerdo de sus experimentos médicos de la memoría de Masacre."},
  "44036": {"n":"Soldado mutado","t":"Dureza.\n[star] Respuesta obligada: después de que el Soldado mutado se active, cúrale todo el Daño.","f":"Butler financió su investigación creando supersoldados para gobiernos extranjeros."},
  "44037": {"n":"Crisis de Masacres infinitos","t":"Cuando se muestre esta carta: muestra las cartas apartadas del Esbirro Malsacre y el Plan secundario Masacre malévola. Mezcla el resto del conjunto de Encuentros apartados de Malsacre con el mazo de Encuentros y barajalo. Retira esta carta de la partida."},
  "44038": {"n":"Malsacre","t":"Malsacre se enfrenta al jugador inicial.\nCuando se derrote esta carta: el jugador que haya derrotado a Malsacre lo recibe como carta de Encuentro boca abajo.","f":"\"Lo que yo hago... lo hago por la causa. Aun así, me siento culpable... pero sólo a veces.\""},
  "44039": {"n":"Malsacre malévola","t":"Cuando se muestre esta carta: Coloca 2 de Amenaza sobre esta carta por cada jugador que controle al menos 1 carta del aspecto Masacrismo (del color rosa).","f":"Malsacre esta convencido de que el único modo de poner fin a su sufrimiento pasa por exterminar a todos los seres vivos del multiverso."},
  "44040": {"n":"Rayo antiregenerante","t":"Vincula esta carta a Malsacre. De no ser posible, vincula esta carta al Villano.\nInterrupción obligada: cuando el personaje vinculado ataque a un personaje que no sea el Villano, el texto de reglas del personaje atacado se trata como si estuviese en blanco (a excepción de los RASGOS)hasta el final del ataque.\nAcción de Héroe: gasta recursos [energy][mental][physical] → vincula esta carta a tu Superhéroe."},
  "44041": {"n":"Masacrizado","t":"El Aliado vinculado se trata como un Esbirro MASACRISMO con el texto de reglas en blanco. El valor de PLA del Esbirro vinculado es igual a su valor impreso de INT y no sufre Daño derivado.\nCuando se muestre esta carta: vincula esta carta al Aliado que tenga el coste más alto y que no tenga ya vinculada una copia de Masacrismo. De no ser posible, esta carta gana Oleada."},
  "44042": {"n":"Tendencias metacidas","t":"Cuando se muestre esta carta: inflige 2 de Daño a cada personaje de MASACRE CORPS (3 de Daño si Malsacre está en juego). Si no se inflige Daño de este modo, coloca 1 ficha de Aceleración sobre el Plan principal."},
  "44043": {"n":"Bob, agente de Hydra","t":"Respuesta: después de qué Bob, agente of Hydra entre en juego, inflige 2 de Daño a un enemigo o bien quita 1 de Amenaza de un Plan."},
  "44044": {"n":"Cabeza Nuclear Adolescente Negasónica","t":"Interrupción: cuando se muestre una carta de Perfidia, inflige 2 de Daño a Cabeza Nuclear Adolescente Negasónica → anula los efectos del enunciado \"Cuando se muestre esta carta\" de la carta mostrada."},
  "44045": {"n":"Pandasacre","t":"Dureza.","f":"¿Qué es blanco y negro y se cubre de rojo si intentas achucharlo?"},
  "44046": {"n":"Un descansito","t":"Alianza. Máximo de 1 por mazo.\nAcción de Alter ego: tomaos un descanso de la partida. levantaos de la mesa. Leed unos comics o algo. Cuando volváis a la partida, cura 1 de Daño a cada Superhéroe por cada minuto que hayáis pasado sin jugar."},
  "44047": {"n":"¡Ponte delante de mí!","t":"Máximo de 1 por mazo.\nInterrupción de Héroe: cuando se muestre una carta de Perfidia del mazo de Encuentros, anula su efecto de \"Cuando se muestre esta carta\". En vez de eso, el Villano te ataca a ti. Si un Aliado u otro Héroe defiende contra este ataque, roba 1 carta."},
  "44048": {"n":"Renovar la mano","t":"No puedes jugar esta carta si ya has jugado otra carta en esta fase.\nAcción: descarta tu mano de cartas. Roba una mano nueva. (Roba cartas hasta restrablecer el tamaño de tu mano.)","f":"\"¡Esta mano podria ser mucho mejor que la de antes!\" — Masacre"},
  "44049": {"n":"Nave de los Masacre Corps","t":"Acción: agota la Nave de los Masacre Corps y coge 1 carta de Encuentro boca abajo → pon en juego desde tu mano un Aliado del aspecto Masacrismo.","f":"Esta nave espacial sirve como base de operaciones móvil de los Masacre Corps."},
  "44050": {"n":"Conveniencia de la trama","t":"Acción: agota Conveniencia de la trama → elige una opción:\n• Elige 1 carta de aspecto de tu mano y vincúlala boca a bajo a esta carta (hasta un máximo de 3).\n• Coge 1 carta que esté vinculada aqui boca abajo y añádela a tu mano.\nCualquier jugador puede aplicar esta capacidad."},
  "44051": {"n":"Emboscada","t":"Vincula esta carta a un Plan secundario. Máximo de 1 por Plan secundario.\nInterrupción: cuando se derrote el Plan secundario vinculado, descarta un Esbirro que no sea ÉLITE."},
  "44052": {"n":"Bazuca","t":"Restringida. Máximo de 2 por mazo.\nAcción de Héroe (ataque): descarta el Bazuca → inflige 1 de Daño a un enemigo por cada [crisis], [acceleration], [amplify], y [hazard] que haya en juego. Este ataque gana A distancia."},
  "44053": {"n":"Tómbola","t":"Acción de Héroe: gasta 1 recurso de cualquier tipo → traslada 1 de Amenaza desde un Plan hasta una de las casillas de la ilustración que contenga el recurso gastado. Si todas las casillas están ocupadas, descarta esta carta y confunde al Villano."},
  "44054": {"n":"Distracción","t":"Vincula esta carta a un Esbirro que no sea ÉLITE. Máximo de 1 por Esbirro.\nEl Esbirro vinculado no puede activarse."},
  "44055": {"n":"Espadas láser","t":"Cuenta como 2 cartas Restringidas. Máximo de 1 por mazo.\nTu Héroe recibe +1 ATQ por cada [crisis], [acceleration], [amplify], y [hazard] que haya en juego (hasta un máximo de +4 ATQ).","f":"\"Fwoom.¡Ksh! Fwoom. ¡Kssssh!\" — El Nene"},
  "44056": {"n":"Piedra, papel, tijeras","t":"Acción de Héroe: agota esta carta, elige 1 carta de tu mano y descarta la primera carta de la parte superior de tu mazo → usando el diagrama de la ilustración, si un recurso impreso en la carta elegida vence (señala) a un recurso impreso en la carta descartada, añade a tu mano la carta descartada."},
  "44057": {"n":"Tres en raya","t":"Acción de Héroe: gasta 1 recurso de cualquier tipo → traslada 1 de Daño desde un personaje hasta una casilla vacia de la ilustración que contenga el recurso gastado. Si hay 3 fichas de Daño formando una linea recta,inflige a un enemigo todo el Daño que haya sobre esta carta y luego descártala."},
  "44058": {"n":"Burro","t":"Acción de Héroe: agota Burro → descarta la primera carta de la parte superior del mazo de Encuentros. Sufres 1 de Daño por cada icono ([star] y [boost]) que haya en el recuadro de aumentos de esa carta. Descarta la primera carta de la parte superior de tu mazo. Inflige tanto Daño a un enemigo como el coste de esa carta."},
  "45001a": {"t":"Absorción de energía — Respuesta: después de que de que Bishop sufra cualquier cantidad de Daño a consecuencia de un ataque, descarta esa misma cantidad de cartas de la parte superior de tu mazo. Añade a tu mano todas las cartas de Recurso que se hayan descartado de este modo."},
  "45001b": {"t":"Desplazado en el tiempo — Respuesta: después de que de que cambies a esta identidad, coge una carta TEMPORAL de tu pila de descartes y añádela a tu mano.","f":"\"Esto no es lo que tenía en mente cuando viajé al pasado para salvar mi futuro.\""},
  "45002": {"t":"Acción: descarta una carta de Recurso de tu mano → prepara a Malcolm. Si esa carta tiene impreso un icono [physical], cura 1 de Daño a Malcolm. (Límite una vez por fase.)","f":"\"Múltiples contactos. Voy a por ellos.\""},
  "45003": {"t":"Acción: descarta una carta de Recurso de tu mano → prepara a Randall. Si esa carta tiene impreso un icono [energy], cura 1 de Daño a Randall. (Límite una vez por fase.)","f":"\"Estamos contigo, jefe. Hasta el final.\""},
  "45004": {"n":"Fusil de Bishop","t":"Restringida.\nAcción de Héroe (ataque): agota el Fusil de Bishop y elige un enemigo → inflige 1 de Daño a ese enemigo por cada Recurso que tengas en la mano. Este ataque gana A distancia."},
  "45005": {"n":"Uniforme de Bishop","t":"Respuesta: después de que de que resuelvas la capacidad \"Absorción de energía\" de Bishop, agota el Uniforme de Bishop → cura 1 de Daño a Bishop por cada carta de Recurso que tengas en la mano."},
  "45006": {"n":"Supercargado","t":"Acción: descarta una carta de Recurso de tu mano → coloca 1 contador de Carga sobre esta carta por cada icono de recurso que haya en la carta descartada.\nInterrupción de Héroe: cuando realices un ataque básico, descarta Supercargado → recibes +2 ATQ para este ataque por cada contador de Carga que haya sobre esta carta (hasta un máximo de +8 ATQ)."},
  "45007": {"n":"Descarga fulminante","t":"Acción de Héroe (ataque): inflige 6 de Daño a un enemigo. Si has pagado el coste de este Evento usando una carta de Recurso, prepara a Bishop.","f":"El poder de Bishop le permite absorber energía y liberarla en forma de poderosas descargas."},
  "45008": {"n":"Asumir el mando","t":"Acción de Héroe (intervención): quita 3 de Amenaza de un Plan. Si has pagado el coste de este Evento usando una carta de Recurso, roba 1 carta.","f":"\"¡Todos conmigo!\" —Bishop"},
  "45009": {"n":"Conversión de energía","t":"Interrupción de Héroe (defensa): cuando un enemigo ataque, devuelve a tu mazo todas las cartas de Recurso que tengas en tu pila de descartes y barájalo. No puedes sufrir mas de 3 puntos de Daño a consecuencia de este ataque."},
  "45010": {"n":"Energía acumulada","f":"\"¡Cuanto más me golpees, más duro será mi contraataque!\" —Bishop"},
  "45011": {"t":"Respuesta: después de que Cable intervenga y derrote un Plan secundario, roba 1 carta.","f":"\"Sé demasiado bien lo que nos depara el futuro.\""},
  "45012": {"t":"Respuesta: después de que X-23 ataque y derrote a un enemigo, prepárala.","f":"\"¡Vuelve a llamarme 'mujer Lobezno' si te atreves!\""},
  "45013": {"n":"Entrenamiento en equipo","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nCada Aliado que controles recibe +1 de Vida.","f":"\"Normalmente esperamos a que el Capi exclame 'Vengadores, reuníos' y atacamos todos en la misma dirección que él.\" —Clint Barton"},
  "45014": {"n":"Traje avanzado","t":"Vincula esta carta a un Aliado X-FORCE o PATRULLA-X. Máximo de 1 por Aliado.\nRespuesta: después de que el Aliado vinculado derrote un Esbirro o Plan secundario, descarta 1 carta desde tu mano → cura 1 de Daño al Aliado vinculado por cada recurso que haya en esa carta."},
  "45015": {"n":"Ayudante","t":"Vincula esta carta a un Aliado específico de Superhéroe que controles. Máximo de 1 por mazo.\nEl Aliado vinculado recibe +2 de Vida y es tu \"ayudante.\"\nRespuesta: después de que realices una recuperación básica, cura 2 de Daño al Aliado vinculado."},
  "45016": {"n":"Espalda contra espalda","t":"Acción de Héroe: prepara a tu ayudante → prepara tu Héroe y elige una opción:\n• Curar 1 de Daño a ambos personajes.\n• Ambos personajes reciben +1 INT y +1 ATQ hasta el final de la fase."},
  "45017": {"n":"Ponerse los trajes","t":"Acción de Alter ego: busca en tu mazo y tu pila de descartes un Aliado y una Mejora que pueda vincularse a ese Aliado. Añade ambas cartas a tu mano. (Baraja el mazo.)"},
  "45018": {"n":"Liderar en vanguardia","t":"Acción de Héroe: elige un jugador. Cada personaje controlado por ese jugador recibe +1 INT y +1 ATQ hasta el final de la fase.","f":"\"¡Seguidme todos!\" —Carol Danvers"},
  "45019": {"n":"El poder del liderazgo","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta de Liderazgo (azul)."},
  "45020": {"n":"Legión","t":"[star] Respuesta: después de que Legion use un atributo básico, descarta la primera carta de la parte superior de tu mazo. Si el recurso impreso de esa carta tiene:\n[energy] — Inflige 2 de Daño a un enemigo.\n[mental] — Quita 2 de Amenaza de un Plan.\n[physical] — Cura 2 de Daño a Legión."},
  "45021": {"n":"Médula","t":"Juega esta carta sólo si tienes los rasgos X-FORCE o PATRULLA-X.\nRespuesta: después de que Médula entre en juego, inflige 2 de Daño a un enemigo.","f":"\"¡Como te coja, despídete de esa cara bonita!\""},
  "45022": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "45023": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "45024": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "45025": {"n":"Miedo al futuro","t":"Dale esta carta al jugador que lleva a Lucas Bishop.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n• Agota a Lucas Bishop → retira Miedo al futuro de la partida.\n• Descarta esta carta y todas las cartas de Recurso desde tu mano. Si no se descarta ninguna carta de Recurso de este modo, esta carta gana Oleada."},
  "45026": {"t":"Ataque veloz.\nRespuesta obligada: después de que Trevor Fitzroy ataque y derrote a un Aliado, Si esta en juego Portal en el tiempo, colócale encima 2 de Amenaza. De no ser posible, localízalo y muéstralo.\n(Esbirro Archienemigo de Bishop.)"},
  "45027": {"n":"Portal en el tiempo","t":"Interrupción obligada: cuando se muestre una carta TEMPORAL, gana Oleada. (Límite de una vez por fase.)","f":"Trevor Fitzroy utiliza portales temporales para cometer delitos y escapar de la justicia."},
  "45028": {"t":"Cuando se muestre esta carta: Si está en juego Portal en el tiempo, colócale 2 de Amenaza. De no ser así, localiza Portal en el tiempo y muéstralo.","f":"\"Es hora de irse, Trevor.\""},
  "45029": {"n":"Artimañas temporales","t":"Cuando se muestre esta carta: descarta una carta de tu mano que tenga el mayor número de iconos de recurso impresos. Coloca 1 de Amenaza sobre cada Plan por cada icono de recurso que hubiera en esta carta.","f":"\"Por eso me encantan los viajes en el tiempo: no importa cuántas veces atraco este banco, siempre se sorprenden.\" —Trevor Fitzroy"},
  "45030a": {"t":"Juega con la primera carta de la parte superior de tu mazo boca arriba.\nUna vez por fase, puedes jugar la primera carta de la parte superior de tu mazo como si estuviese en tu mano, reduciendo en 1 su coste en recursos.","f":"\"No hay copos de nieve en el Limbo.\""},
  "45030b": {"t":"Interrupción: cuando cambies a tu identidad de Héroe, elige un HECHIZO que esté en tu pila de descartes y colócalo en la parte superior de tu mazo. (Límite una vez por fase.)","f":"\"¡Ahora mismo vendería lo que queda de mi alma por un bocata de tortilla!\""},
  "45031": {"n":"Coloso","t":"Dureza.\nInterrupción: cuando un enemigo te ataque, juega a Coloso desde tu mano (pagando su coste en recursos) y decláralo defensor sin agotarlo.","f":"\"Siempre te protegeré, copo de nieve.\""},
  "45032": {"t":"Respuesta: después de que empiece la fase del Villano, agota Limbo → intercambia una carta de tu mano por la primera carta de la parte superior de tu mazo.\nAcción: Agota Limbo → intercambia una carta de tu mano por la primera carta de la parte superior de tu mazo."},
  "45033": {"n":"Corona de Magik","t":"Magik gana Tesón.\nMientras la primera carta de la parte superior de tu mazo tenga un icono de recurso [mental] o [wild], Magik recibe +1 INT.","f":"Magik se ha criado en el Limbo y está destinada a usurpar el trono del hombre que la llevó a esa dimensión."},
  "45034": {"n":"Espada Alma","t":"Restringida.\nLos ataques básicos de Magik ganan Penetrante.\nMientras la primera carta de la parte superior de tu mazo tenga un icono de recurso [physical] o [wild], Magik recibe +1 ATQ."},
  "45035": {"n":"Armadura mística","t":"Magik gana Represalia 1.\nMientras la primera carta de la parte superior de tu mazo tenga un icono de recurso [energy] o [wild], Magik recibe +1 DEF.","f":"Para ir a la moda en el Limbo."},
  "45036": {"n":"Adivinación","t":"Acción: mira las 3 primeras cartas de tu mazo. Roba una, descarta una y devuelve una a la parte superior de tu mazo.","f":"\"Sí, he visto tu futuro. No, no te lo voy a contar.\"—Magik"},
  "45037": {"n":"Disco de salto","t":"Acción de Héroe: prepara tu Héroe. Elige una carta de Magik que éste en tu pila de descartes y no se llame Disco de salto, y colócala en la parte superior de tu mazo.","f":"Magik's teleportation discs can sufre her anywhere by opening a portal through Limbo."},
  "45038": {"n":"Exorcismo","t":"Acción de Héroe (intervención): quita 4 de Amenaza de un Plan. Si la primera carta de la parte superior de tu mazo tiene un icono de recurso [mental] o [wild], confunde al Villano.","f":"\"He purgado el mal en tu interior.\" —Magik"},
  "45039": {"n":"Golpear con el alma","t":"Acción de Héroe (ataque): inflige 4 de Daño a un enemigo. Si la primera carta de la parte superior de tu mazo tiene un icono de recurso [physical] o [wild], aturde a ese enemigo.","f":"\"Very well. Feel the bite of my Espada Alma!\" —Magik"},
  "45040": {"n":"Barrera Mágica","t":"Interrupción de Héroe (defensa): cuando un enemigo inicie un ataque, evita 3 de Daño de este ataque. Si la primera carta de la parte superior de tu mazo tiene un icono de recurso [energy] o [wild], inflige 3 de Dañoal enemigo atacante."},
  "45041": {"n":"Bolas Doradas","t":"[star] Interrupción: cuando Bolas Doradas ataque, descarta un máximo de 3 cartas de la parte superior de tu mazo → Bolas Doradas recibe +X ATQ para este ataque, siendo X el número de cartas descartado de este modo.","f":"\"Yo no escogí el nombre.\""},
  "45042": {"t":"Juega esta carta sólo si tu Héroe tiene el rasgo PATRULLA-X.\nInterrupción: cuando al Villano vaya a ejecutar el Plan, descarta a Tempus → cancela esa activación. Coge 1 carta de Encuentro boca abajo."},
  "45043": {"n":"Furia sanguinaria","t":"Maximo de 1 por jugador.\nRespuesta: después de que derrotes a un enemigo con un ataque básico, agota Furia sanguinaria y sufre 1 de Daño → roba 1 carta."},
  "45044": {"n":"Tantear las defensas","t":"Maximo de 1 por jugador.\nRespuesta: después de que juegues un Evento de ATAQUE, coloca 1 contador de Tanteo sobre esta carta. Si hay al menos 5 contadores de Tanteo sobre ella, descarta esta carta para infligir 5 de Daño a un enemigo."},
  "45045": {"n":"Embestida arrolladora","t":"Acción de Héroe (ataque): inflige 8 de Daño a un enemigo. Si la vida restante de tu Héroe es inferior a la mitad de su Vida inicial, este ataque gana Brutalidad.","f":"\"¡Abre paso, tovarisch!\"—Coloso"},
  "45046": {"n":"Vapuleo","t":"Acción de Héroe (ataque) inflige 3 de Daño a un enemigo. Si ésta es la primera carta que has jugado en la ronda actual, devuévela a tu mano.","f":"\"Como tenga que golpearte otra vez, ya no volverás a levantarte. Nunca.\" —Gamora"},
  "45047": {"n":"El poder de la agresividad","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta de Agresividad (roja)."},
  "45048": {"t":"Respuesta: después de que Triage entre en juego, cura 2 de Daño a un personaje Patrulla-X.","f":"\"Déjame que le eche un vistazo a eso.\""},
  "45049": {"n":"Cucos de Stepford","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo PATRULLA X. Usos (3 contadores Psíquicos).\nInterrupción: cuando un jugador muestre una carta de Perfidia, agota a las Cucos de Stepford y quítales 1 contador Psíquico → anula los efectos de esa carta y descártala. Ese jugador muestra otra carta de Encuentro."},
  "45050": {"n":"Gema de sangre","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo MÍSTICO. Máximo de 1 por mazo.\nRecurso: agota la Gema de sangre y sufre 2 de Daño → genera un recurso [wild]."},
  "45051": {"n":"Hechizo básico","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo MÍSTICO.\nAcción de Héroe: elige una opción:\n• Cura 3 de Daño a un Superhéroe.\n• Quita 3 de Amenaza de un Plan.\n• Inflige 3 de Daño a un enemigo."},
  "45052": {"n":"Meditación espiritual","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Místico.\nAcción: roba 2 cartas. Elige 1 carta de tu mano y descártala.","f":"\"Cada hechizo, cada signo, cada manipulación… debes tenerlo todo vigilado para que no te explote en las narices.\""},
  "45053": {"n":"La Niña Oscura","t":"Dale esta carta al jugador que lleva a Illyana Rasputin.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n• Agota a Illyana Rasputin → retira de la partida La Niña Oscura .\n• Inflige 1 de Daño a cada personaje que controles. Descarta esta Obligación."},
  "45054": {"t":"Infame.\n[star] Respuesta obligada: después de que Belasco se active contra ti, descarta las 3 primeras cartas de la parte superior de tu mazo. Si está en juego Soberano del Limbo, vincúlale esas cartas boca abajo.\n(Esbirro Archienemigo de Magik.)"},
  "45055": {"n":"Soberano del Limbo","t":"No puede quitarse Amenaza de este Plan mientras Belasco esté en juego.\nCuando se muestre esta carta: el jugador que lleva a Illyana Rasputin localiza Limbo y lo vincula Boca abajo sobre esta carta. Cuando se derrote este Plan, pon en juego Limbo controlado por su propietario."},
  "45056": {"t":"Guardia.\nCuando se muestre esta carta: Si está en juego Soberano del Limbo, colócale encima 2 de Amenaza. De no ser así, coloca 2 de Amenaza sobre el Plan principal.","f":"\"El jefe dice que está harto de que interfieras en sus planes.\""},
  "45057": {"n":"Fuego Brujo","t":"Ataque veloz.\nRespuesta obligada: después de que Fuego Brujo ataque y derrote a un Aliado, coloca 1 de Amenaza sobre Soberano del Limbo. De no ser así, coloca 1 de Amenaza sobre el Plan principal.","f":"\"¡El Limbo me pertenece por legítimo derecho!\""},
  "45058": {"n":"Batalla por el Limbo","t":"Cuando se muestre esta carta: cada Esbirro LIMBO que esté en juego se activa contra el jugador al que esté enfrentado. Si no se activa ningún Esbirro LIMBO de este modo, esta carta gana Oleada.\n[star] Aumento: si está en juego Soberano del Limbo, colócale encima 2 de Amenaza."},
  "45059": {"t":"Dureza.\nSi la cantidad de Amenaza que hay sobre Acervo genético es de al menos:\n• 3 — Unus gana Represalia 1.\n• 6 — Unus gana también Firmeza.\n• 9 — Unus gana también un icono [amplify]."},
  "45060": {"t":"Dureza.\nSi la cantidad de Amenaza que hay sobre Acervo genético es de al menos:\n• 3 — Unus gana Represalia 1.\n• 6 — Unus gana también Firmeza.\n• 9 — Unus gana también un icono [amplify]."},
  "45061": {"t":"Dureza.\nSi la cantidad de Amenaza que hay sobre Acervo genético es de al menos:\n• 3 — Unus gana Represalia 1.\n• 6 — Unus gana también Firmeza.\n• 9 — Unus gana también un icono [amplify]."},
  "45062a": {"n":"Cacería de traidores a la raza","t":"Contenido: Unus (I) y Unus (II). (Unus (II) y Unus (III) para jugar en modo Experto.) Unus, Infinitos, y Normal. Un conjunto de Encuentros modular (Pesadilla distópica).\nPreparación: Muestra Acervo genético Plan secundario. En modo Experto, reparte a cada jugador 1 carta de Encuentro boca abajo."},
  "45062b": {"n":"Cacería de traidores a la raza","t":"[star] Respuesta obligada: después de resolver el paso uno de la fase del Villano, coloca 1 de Amenaza sobre Acervo genético.\nSi se completa esta etapa, los jugadores pierden la partida.","f":"Prelado Unus y his squad of Infinitos scour the ruins of the X-Mansion for the enemies of Apocalipsis."},
  "45063": {"n":"Pistola de prelado","t":"Vincula esta carta a Unus.\n[star] Respuesta obligada: después de que Unus ataque y derrote a un Aliado, coloca 1 de Amenaza sobre Acervo genético.\nRespuesta de Héroe: después de que realices un ataque básico contra Unus, gasta recursos [energy] [physical] → descarta esta carta."},
  "45064": {"n":"Armadura de prelado","t":"Vincula esta carta a Unus.\n[star] Respuesta obligada: después de que Unus ejecuta el Plan, dale una carta de Estado \"Duro\".\nRespuesta de Héroe: después de que realices un ataque básico contra Unus, gasta recursos [mental] [physical] → descarta esta carta."},
  "45065": {"n":"Cazador Infinito","t":"Cuando se muestre esta carta: inflige 3 de Daño a un Aliado que controles.\n[star] Aumento: elige entre colocar 2 de Amenaza sobre Acervo genético o que el enemigo activado reciba +2 PLA y +2 ATQ para esta activación."},
  "45066": {"n":"Experimentos genéticos","t":"Vincula esta carta a un Esbirro Infinito. De no ser posible, esta carta gana Oleada.\nEl Esbirro vinculado recibe +2 de Vida.\nInterrupción obligada: cuando el Esbirro vinculado sea derrotado, coloca 2 de Amenaza sobre Acervo genético.\n[star] Aumento: vincula esta carta a un Esbirro Infinito."},
  "45067": {"n":"Prelado Infinito","t":"Cuando se muestre esta carta: Unus se activa contra ti. Si la cantidad de Amenaza que hay sobre Acervo genético es de al menos:\n• 3 — Dale a Unus una carta de Estado \"Duro\".\n• 6 — Cura 3 de Daño a Unus también.\n• 9 — Dale a Unus también una carta de aumento adicional para esta activación."},
  "45068": {"n":"Huestes interminables","t":"Cuando se derrote esta carta: Coloca 3 de Amenaza sobre Acervo genético.","f":"The Infinitos live up to their name: no matter how many you defeat, they keep making more."},
  "45069": {"n":"Soldado Infinito","t":"Guardia.\nSi la cantidad de Amenaza que hay sobre Acervo genético es de al menos:\n• 3 — Este Esbirro gana Ataque veloz.\n• 6 — Este Esbirro gana también Oleada.\n• 9 — Este Esbirro recibe también +3 de Vida."},
  "45070": {"n":"Diezmar a los débiles","t":"Cuando se muestre esta carta: Coloca 4 de Amenaza sobre Acervo genético.\n[star] Aumento: Coloca 2 de Amenaza sobre Acervo genético.","f":"The Infinitos were created to enforce the mandate of Apocalipsis: the weak must perish."},
  "45071": {"n":"Acervo genético","t":"Permanente. Inicio.\nRespuesta obligada: después de que un Aliado sea derrotado por cualquier motivo que no sea Daño derivado, coloca 3 de Amenaza sobre esta carta.","f":"Apocalipsis utiliza el material genético de sus víctimas para crear a los Infinitos."},
  "45072": {"n":"Perseguido","t":"Acción de Alter ego: descarta una carta de tu mano → descarta esta carta."},
  "45073": {"n":"Cansado de luchar","t":"Cuando se muestre esta carta: quedas aturdido. Si ya estabas aturdido, en vez de eso sufres 2 de Daño.\n[star] Aumento: quedas aturdido. Si ya estabas aturdido, en vez de eso sufres 2 de Daño."},
  "45074": {"n":"Exterminio selectivo","t":"Cuando se derrote esta carta: el jugador que haya derrotado este Plan confunde a su Superhéroe.","f":"The Infinitos hunt down those whom their master deems unworthy."},
  "45075a": {"n":"Perseguido por el pasado","t":"Permanente. Inicio.\nRespuesta obligada: después de que coloques un contador de Persecución sobre esta carta, si el número de contadores de Persecución que hay sobre ella es como mínimo 3 más que el número de jugadores, quita todos los contadores → si tu Esbirro Archienemigo está en juego, se activa contra ti. De no ser así, dale la vuelta a esta carta."},
  "45075b": {"n":"Perseguido por el pasado","t":"Permanente.\nRespuesta obligada: después de que pongas boca arriba esta cara, localiza tu Esbirro Archienemigo y muéstralo. Busca el Plan secundario de tu Archienemigo en la zona apartada y muéstralo. Añade el resto del conjunto de tu Archienemigo de la zona apartada al mazo de Encuentros y barájalo. Dale la vuelta a esta carta."},
  "45076": {"n":"Designios siniestros","t":"Cuando se muestre esta carta: Coloca 1 contador de Persecución sobre Perseguido por el pasado. Luego, si tiene algún contador encima, el Villano ejecuta el Plan.\n[star] Aumento: después de que se resuelva esta activación, coloca 1 contador de Persecución sobre Perseguido por el pasado."},
  "45077": {"n":"Descarga siniestra","t":"Cuando se muestre esta carta (Alter ego): Coloca 1 contador de Persecución sobre Perseguido por el pasado. Luego, si tiene algún contador encima, esta carta gana Oleada.\nCuando se muestre esta carta (Héroe): Coloca 1 contador de Persecución sobre Perseguido por el pasado. Luego, si tiene algún contador encima, el Villano te ataca."},
  "45078": {"n":"Alianza maligna","t":"Cuando se muestre esta carta: todos los Esbirros Archienemigos que estén en juego se activan contra ti. Si no no se ha activado ningún Esbirro de este modo, coloca 3 contadores de Persecución sobre Perseguido por el pasado.\n[star] Aumento: después de que se resuelva esta activación, coloca 1 contador de Persecución sobre Perseguido por el pasado."},
  "45079": {"n":"Ningún sitio es seguro","t":"Cuando se muestre esta carta: Coloca 1 contador de Persecución sobre Perseguido por el pasado. Luego, si tiene algún contador encima, descarta una Mejora o Apoyo que controles.\n[star] Aumento: después de que se resuelva esta activación, coloca 1 contador de Persecución sobre Perseguido por el pasado."},
  "45080": {"n":"Cada vez más cerca","t":"Respuesta obligada: después de que empiece tu turno, descarta la primera carta de la parte superior de tu mazo. Coloca 1 contador de Persecución sobre Perseguido por el pasado por cada icono de recurso que haya impreso en esa carta.\nAcción de Alter ego: Descarta una carta específica de tu Superhéroe de tu mano → descarta esta carta."},
  "45081a": {"n":"Guerra","t":"[star] Respuesta obligada: después de que Guerra te ataque, si tiene al menos 1 de Vida, descarta una Mejora o Apoyo que controles.\nGuerra no puede ser derrotado mientras otro Villano tenga al menos 1 de Vida."},
  "45081b": {"n":"Guerra","t":"[star] Respuesta obligada: después de que Guerra te ataque, si tiene al menos 1 de Vida, descarta una Mejora o Apoyo que controles.\nGuerra no puede ser derrotado mientras otro Villano tenga al menos 1 de Vida."},
  "45082a": {"n":"Hambre","t":"[star] Respuesta obligada: después de que Hambre te ataque, si tiene al menos 1 de Vida, descarta las 10 primeras cartas de la parte superior de tu mazo.\nHambre no puede ser derrotado mientras otro Villano tenga al menos 1 de Vida."},
  "45082b": {"n":"Hambre","t":"[star] Respuesta obligada: después de que Hambre te ataque, si tiene al menos 1 de Vida, descarta las 10 primeras cartas de la parte superior de tu mazo.\nHambre no puede ser derrotado mientras otro Villano tenga al menos 1 de Vida."},
  "45083a": {"n":"Peste","t":"[star] Respuesta obligada: después de que Peste te ataque, si tiene al menos 1 de Vida, el texto de reglas de tu Superhéroe se trata como si estuviese en blanco (a excepción de los Rasgos) hasta que empiece la siguiente fase del Villano.\nPeste no puede ser derrotado mientras otro Villano tenga al menos 1 de Vida."},
  "45083b": {"n":"Peste","t":"[star] Respuesta obligada: después de que Peste te ataque, si tiene al menos 1 de Vida, el texto de reglas de tu Superhéroe se trata como si estuviese en blanco (a excepción de los Rasgos) hasta que empiece la siguiente fase del Villano.\nPeste no puede ser derrotado mientras otro Villano tenga al menos 1 de Vida."},
  "45084a": {"n":"Muerte","t":"[star] Respuesta obligada: después de que Muerte te ataque, si tiene al menos 1 de Vida, inflige 1 de Daño a cada personaje que controles.\nMuerte no puede ser derrotado mientras otro Villano tenga al menos 1 de Vida."},
  "45084b": {"n":"Muerte","t":"[star] Respuesta obligada: después de que Muerte te ataque, si tiene al menos 1 de Vida, inflige 1 de Daño a cada personaje que controles.\nMuerte no puede ser derrotado mientras otro Villano tenga al menos 1 de Vida."},
  "45085a": {"n":"Los Jinetes de Apocalipsis","t":"Contenido: Guerra (A), Hambre (A), Peste (A), Muerte (A), los Cuatro jinetes, Normal, y dos conjuntos modulares (Pesadilla distópica y Sabuesos).\nPreparación: Baraja los cuatro Villanos Jinetes, luego muéstralos y colócalos formando una fila de izquierda a derecha. Coloca el contador de Villano activo sobre el Villano del extremo izquierdo (ver cuaderno de reglas). Cada jugador muestra un Plan secundario aleatorio del conjunto de Encuentros de los Cuatro jinetes."},
  "45085b": {"n":"Los Jinetes de Apocalipsis","t":"Respuesta obligada: después de que un Villano se active, traslada el contador del Villano activo al siguiente Villano.\nSi se completa esta etapa, los jugadores pierden la partida.","f":"Los Cuatro jinetes son los siervos más brutrales de Apocalipsis. They strike in turn, using their powers as a team."},
  "45086": {"n":"Los estragos de la guerra","t":"Cuando se derrote esta carta: El jugador que haya derrotado este Plan descarta una Mejora o Apoyo que controle.","f":"Guerra uses the shockwaves created by his arms to keep his opponents off balance."},
  "45087": {"n":"Hambruna","t":"Cuando se derrote esta carta: El jugador que haya derrotado este Plan descarta las 10 primeras cartas de la parte superior de su mazo.","f":"The mere touch of Hambre leaves even the strongest mutant enfeebled."},
  "45088": {"n":"Plaga y pestilencia","t":"Cuando se derrote esta carta: El jugador que haya derrotado este Plan trata el texto de reglas de su Superhéroe como si estuviese en blanco (a excepción de los Rasgos) hasta que empiece la siguiente fase del Villano.","f":"Peste uses her power to make her enemies sick y helpless."},
  "45089": {"n":"El espectro de la muerte","t":"Cuando se derrote esta carta: El jugador que haya derrotado este Plan inflige 1 de Daño a cada personaje que controle.","f":"The shadow of Muerte drives fear into the hearts of those he hunts."},
  "45090": {"n":"Caballo dorado","t":"Vincula esta carta al Villano que tenga menos Vida y que no tenga el rasgo Aéreo.\nEl Villano gana el rasgo Aéreo y se considera que tiene al menos 1 de Vida.\nRespuesta de Héroe: después de que ataques al Villano vinculado, resuelve su \"Respuesta obligada\" como si acabase de atacarte → descarta esta carta."},
  "45091": {"n":"Alas de Metal","t":"Vincula esta carta a Muerte y trasládale el contador de Villano activo.\nMuerte gana Represalia 1 y se considera que tiene al menos 1 de Vida restante.\nRespuesta de Héroe: después de que ataques a Muerte, resuelve su \"Respuesta obligada\" como si acabase de atacarte → descarta esta carta."},
  "45092": {"n":"Jinete de la Guerra","t":"Cuando se muestre esta carta: Cura 2 de Daño a Guerra y dale una carta de Estado \"Duro\". Se activa contra ti.\n[star] Aumento: después de esta activación, Guerra se activa contra ti. No des una carta de aumento a Guerra para esta activación."},
  "45093": {"n":"Jinete del Hambre","t":"Cuando se muestre esta carta: Cura 2 de Daño a Hambre y dale una carta de Estado \"Duro\". Se activa contra ti.\n[star] Aumento: después de esta activación, Hambre se activa contra ti. No des una carta de aumento a Hambre para esta activación."},
  "45094": {"n":"Jinete de la Peste","t":"Cuando se muestre esta carta: Cura 2 de Daño a Peste y dale una carta de Estado \"Duro\". Se activa contra ti.\n[star] Aumento: después de esta activación, Peste se activa contra ti. No des una carta de aumento a Peste para esta activación."},
  "45095": {"n":"Jinete de la Muerte","t":"Cuando se muestre esta carta: Cura 2 de Daño a Muerte y dale una carta de Estado \"Duro\". He se active contra ti.\n[star] Aumento: después de esta activación, Muerte se activa contra ti. No des una carta de aumento a Muerte para esta activación."},
  "45096": {"n":"Caballería apocalíptica","t":"Cuando se muestre esta carta: resuelve la \"Respuesta obligada\" del Villano activo como si tuviese al menos 1 de Vida y te hubiera atacado. Traslada el contador del Villano activo al siguiente Villano y resuelve su \"Respuesta obligada\" del mismo modo."},
  "45097": {"n":"Acab","t":"Dureza.\nCuando se muestre esta carta: si está en juego Soltar los perros, colócale encima 3 de Amenaza. De no ser así, localiza el Plan secundario Soltar los perros y muéstralo.","f":"\"You no puede hide from me, mutant.\""},
  "45098": {"n":"Sabueso","t":"Guardia.\nCuando se muestre esta carta: Si tienes adoptada tu identidad de Héroe, Sabueso te ataca. De no ser así, cambia a tu identidad de Héroe.","f":"Acab's hounds are mutants stripped of free will y forced to hunt their own kind."},
  "45099": {"n":"Lanza de energía de Acab","t":"Vincula esta carta a Acab. De no ser posible, vincula esta carta al Villano.\n[star] Interrupción obligada: cuando el enemigo vinculado te ataque, este ataque gana Brutalidad y Penetrante. Al final de este ataque, descarta la Lanza de energía de Acab."},
  "45100": {"n":"Soltar los perros","t":"La primera carta de un Sabueso que se muestre en cada fase gana Oleada.\nCuando se derrote esta carta: El jugador que haya derrotado este Plan busca una copia de un Sabueso en el mazo de Encuentros y en su pila de descartes,y se la queda como carta de Encuentro boca abajo.","f":"Acab takes pleasure in hunting mutants with the help of his hounds."},
  "45101a": {"n":"Apocalipsis","t":"Dureza.\nInterrupción obligada: cuando se complete el Plan principal, quítale toda la Amenaza (ignorando los iconos de Crisis ([crisis])). Dale la vuelta a esta carta y muestra Apocalipsis (II).","f":"\"Challenge me y be reminded why Apocalipsis reigns supreme.\""},
  "45101b": {"n":"Apocalipsis","t":"Tesón. Dureza.\nInterrupción obligada: cuando se complete el Plan principal, quítale toda la Amenaza (ignorando los iconos de Crisis ([crisis])). Retira esta carta de la partida y muestra Apocalipsis (III)."},
  "45102a": {"n":"Apocalipsis","t":"Tesón. Dureza.\nInterrupción obligada: cuando se complete el Plan principal, quítale toda la Amenaza (ignorando los iconos de Crisis ([crisis])). Dale la vuelta a esta carta y muestra Apocalipsis (IV).","f":"\"This world belongs to me y those I deem worthy.\""},
  "45102b": {"n":"Apocalipsis","t":"Firmeza. Dureza.\n[star] Los ataques de Apocalipsis ganan Brutalidad.\nInterrupción obligada: cuando se complete el Plan principal, los jugadores pierden la partida.","f":"\"I will cleanse este world with fire. Only the strong will survive.\""},
  "45103a": {"n":"La era de Apocalipsis","t":"Contenido: Apocalipsis (II) y Apocalipsis (III). (Apocalipsis (III) para jugar en modo Experto.) Apocalipsis, Prelados, y Normal. Dos conjuntos de Encuentros modulares (Jinetes oscuros e Infinitos).\nPreparación: aparta a un lado todas las cartas de Villano sin usar, todos los Esbirros Prelado, y el Plan secundario El trono del tirano. Muestra el Plan secundario El corazón del imperio. El jugador inicial muestra un Esbirro Prelado aleatorio que esté apartado."},
  "45103b": {"n":"La era de Apocalipsis","t":"X es el valor númerico de Vida impreso en la carta de Apocalipsis.\nInterrupción obligada: cuando Apocalipsis vaya a ser derrotado, en vez de eso descarta todos los Accesorios que tenga vinculados y cúrale tod el Daño. Quita X de Amenaza de este Plan (ignorando los iconos de Crisis ([crisis])).","f":"The time has come for a direct assault sobre Apocalipsis in his towering citadel."},
  "45104a": {"n":"El corazón del imperio","t":"No puede quitarse Amenaza de este Plan mientras haya en juego un Esbirro Prelado.\nCuando se derrote esta carta: El jugador inicial muestra un Esbirro Prelado aleatorio que esté apartado. Reparte una carta de Encuentro a todos los demás jugadores. Dale la vuelta a esta carta.","f":"Before you can challenge Apocalipsis, you must fight your way through his tower."},
  "45105a": {"n":"El trono del tirano","t":"No puede quitarse Amenaza de este Plan mientras haya en juego un Esbirro Prelado.\nCuando se derrote esta carta: El jugador inicial muestra un Esbirro Prelado aleatorio que esté apartado. Reparte una carta de Encuentro a todos los demás jugadores. Dale la vuelta a esta carta y muestra Caido en desgracia."},
  "45105b": {"n":"Caído en desgracia","t":"Vincula esta carta a Apocalipsis y cúrale 5[per_hero] de Vida. No puede sufrir Daño mientras haya en juego un Esbirro Prelado.\nIgnora la \"Interrupción obligada\" del Plan principal.\nInterrupción obligada: cuando Apocalipsis sea derrotado, los jugadores ganan la partida."},
  "45106": {"n":"Ciberpatía","t":"Vincula esta carta a Apocalipsis.\n[star] Respuesta obligada: después de que Apocalipsis ejecuta el Plan, coloca 1 de Amenaza sobre cada Plan secundario.\n[star] Aumento: vincula esta carta a Apocalipsis."},
  "45107": {"n":"Biomorfismo","t":"Vincula esta carta a Apocalipsis.\n[star] Los ataques de Apocalipsis ganan Brutalidad.\n[star] Aumento: vincula esta carta a Apocalipsis."},
  "45108": {"n":"Control Molecular","t":"Vincula esta carta a Apocalipsis.\nApocalipsis gana Represalia 1 y Firmeza.\n[star] Aumento: vincula esta carta a Apocalipsis.","f":"Apocalipsis's power to control every molecule in his body makes him una unpredictable foe."},
  "45109": {"n":"El más apto","t":"Vincula esta carta al Esbirro que tenga el valor impreso de Vida más alto y dale una carta de Estado \"Duro\". De no ser posible, esta carta gana Oleada.\nEl enemigo vinculado recibe +5 de Vida.","f":"Apocalipsis promotes only the strongest y most ruthless mutants to the rank of Prelado."},
  "45110": {"n":"Un lobo entre corderos","t":"Cuando se muestre esta carta: el Esbirro Prelado se activa contra ti. De no ser posible, Apocalipsis se activa contra ti.\n[star] Aumento: dale al Esbirro Prelado una carta de Estado \"Duro\". De no ser posible, dale a Apocalipsis una carta de Estado \"Duro\"."},
  "45111": {"n":"La solución de Apocalipsis","t":"Cuando se derrote esta carta: descarta las X primeras cartas de la parte superior del mazo de Encuentros, siendo X el valor númerico de Vida impreso en la carta de Apocalipsis.","f":"Apocalipsis would rather burn his kingdom to the ground than surrender his rule."},
  "45112": {"n":"Guantelete","t":"Trabajo en equipo (Jinetes oscuros).\n[star] Respuesta obligada: después de que Guantelete te ataque, descarta una Mejora que controles.","f":"\"You want someone gone? You hire the Jinetes oscuros.\""},
  "45113": {"n":"Andanada","t":"Trabajo en equipo (Jinetes oscuros).\n[star] Respuesta obligada: después de que Andanada te ataque, inflige 1 de Daño a cada personaje que controles.","f":"\"Don't expect someone named 'Andanada' to be picky with their targets.\" —Ciclope"},
  "45114": {"n":"Hardrive","t":"Trabajo en equipo (Jinetes oscuros).\n[star] Respuesta obligada: después de que Hardrive te ataque, coloca 1 de Amenaza sobre cada Plan.","f":"\"I've finished my scan. prepara a to jump.\""},
  "45115": {"n":"Colmillo","t":"Trabajo en equipo (Jinetes oscuros).\n[star] Respuesta obligada: después de que Colmillo te ataque, quedas aturdido.\n[star] Aumento: quedas aturdido."},
  "45116": {"n":"Psinapsis","t":"Trabajo en equipo (Jinetes oscuros).\n[star] Respuesta obligada: después de que Psinapsis te ataque, quedas confundido.\n[star] Aumento: quedas confundido."},
  "45117": {"n":"Los Jinetes Oscuros","t":"Complicación 1[per_hero].\nCada Esbirro de los Jinetes oscuros gana Dureza.\nCuando se muestre esta carta: descarta cartas del mazo de Encuentros hasta que se descarte un Esbirro de los Jinetes oscuros y muéstralo.","f":"Jinetes oscuros live by the axiom: The weak must perish."},
  "45118": {"n":"Bestia Oscura","t":"[star] Interrupción obligada: cuando Bestia Oscura te ataque, resuelve la capacidad \"Especial\" del Entorno Ubicación.\nCuando se muestre esta carta: muestra una carta de Entorno aleatoria de las que están apartadas, devuelve el resto de su conjunto de Encuentros al mazo de Encuentros y barájalo.","f":"\"A Villano's work is never done!\""},
  "45119": {"n":"Bestia Oscura","t":"[star] Interrupción obligada: cuando Bestia Oscura te ataque, resuelve la capacidad \"Especial\" del Entorno Ubicación.\nCuando se muestre esta carta: muestra una carta de Entorno aleatoria de las que están apartadas, devuelve el resto de su conjunto de Encuentros al mazo de Encuentros y barájalo. Dale una carta de Encuentro a cada jugador."},
  "45120": {"n":"Bestia Oscura","t":"[star] Interrupción obligada: cuando Bestia Oscura te ataque, resuelve la capacidad \"Especial\" del Entorno Ubicación.\nCuando se muestre esta carta: muestra una carta de Entorno aleatoria de las que están apartadas, devuelve el resto de su conjunto de Encuentros al mazo de Encuentros y barájalo. Dale una carta de Encuentro a cada jugador."},
  "45121a": {"n":"El alucinante viaje de la Bestia Oscura","t":"Contenido: Bestia Oscura (I) y Bestia Oscura (II). (Bestia Oscura (II) y Bestia Oscura (III) para jugar en modo Experto.) Bestia Oscura, Luna azul, Genosha, Tierra Salvaje, y Normal. Un conjunto de Encuentros modular (Pesadilla distópica).\nPreparación: aparta los conjuntos Luna azul, Genosha y Tierra Salvaje (incluyendo todas las cartas de Entorno de esos conjuntos). En modo Experto, muestra la carta de Accesorio Visor de tecnología punta."},
  "45121b": {"n":"El alucinante viaje de la Bestia Oscura","t":"Si se completa esta etapa, los jugadores pierden la partida.","f":"Bestia Oscura activates his time machine to ensure the rise of Apocalipsis, but your quick action ruins his calculations. You wrestle for control of the device as it transports you through time y space!"},
  "45122": {"n":"Visor de tecnología punta","t":"Vincula esta carta a la Bestia Oscura.\nAcción de Héroe: agota tu Héroe y resuelve la capacidad \"Especial\" del Entorno Ubicación → descarta esta carta.\n[star] Aumento: vincula esta carta a la Bestia Oscura."},
  "45123": {"n":"Aumento genético","t":"Vincula esta carta a la Bestia Oscura.\nAcción de Héroe: agota tu Héroe y resuelve la capacidad \"Especial\" del Entorno Ubicación → descarta esta carta.\n[star] Aumento: vincula esta carta a la Bestia Oscura."},
  "45124": {"n":"Experimento cruel","t":"El Esbirro vinculado recibe +2 de Vida y gana Guardia.\nCuando se muestre esta carta: descarta cartas de la parte superior del mazo de Encuentros hasta que descartes un Esbirro. Muestra ese Esbirro y vincúlale Experimento cruel.","f":"\"I could do este with anesthesia, but what fun would that be?\" —Dark Beast"},
  "45125": {"n":"Genio maligno","t":"Cuando se muestre esta carta (Alter ego): la Bestia Oscura ejecuta el Plan. Dale una carta de Estado \"Duro\".\nCuando se muestre esta carta (Héroe): la Bestia Oscura te ataca. Dale una carta de aumento adicional para este ataque."},
  "45126": {"n":"Peripecias temporales","t":"Cuando se derrote esta carta: El jugador que haya derrotado este Plan descarta cartas de la parte superior del mazo de Encuentros hasta que descarte una carta del mismo conjunto de Encuentros que el Entorno Ubicación y muestra la carta que acaba de descartar."},
  "45127": {"n":"La Tierra Salvaje","t":"Inicio.\nEl Villano gana Represalia 1.\nEspecial: descarta las 3 primeras cartas de tu mazo.\nCuando se muestre esta carta: descarta todos los demás Entornos Ubicación que haya en juego."},
  "45128": {"n":"Pterosaurio","t":"Cuando se muestre esta carta: resuelve la capacidad \"Especial\" del Entorno Ubicación.\n[star] Aumento: Si está en juego La Tierra Salvaje, quédate el Pterosaurio como carta de Encuentro boca abajo."},
  "45129": {"n":"Velocirraptor","t":"Ataque veloz.\n[star] Interrupción obligada: cuando Velocirraptor te ataque, descarta la primera carta de tu mazo. El Velocirraptor recibe +1 ATQ para este ataque por cada icono de recurso que se haya descartado de este modo."},
  "45130": {"n":"Simio gigante","t":"Guardia.\nCuando se derrote esta carta: el jugador que haya derrotado al Simio gigante resuelve la capacidad \"Especial\" del Entorno Ubicación."},
  "45131": {"n":"Una tierra de otro tiempo","t":"Cuando se muestre esta carta: si está en juego La Tierra Salvaje, resuelve su capacidad \"Especial\" y sufre 1 de Daño indirecto por cada icono de recurso que se haya en las cartas descartadas. De no ser así, localiza La Tierra Salvaje y muéstrala.","f":"La Tierra Salvaje is exactly what you'd expect from a prehistoric jungle in the middle of Antarctica."},
  "45132": {"n":"Aldea atacada","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: cada jugador resuelve la capacidad \"Especial\" del Entorno Ubicación."},
  "45133": {"t":"Inicio.\nEl Villano gana Tesón.\nEspecial: coloca 1 de Amenaza sobre el Plan principal.\nCuando se muestre esta carta: descarta todos los demás Entornos Ubicación que haya en juego."},
  "45134": {"n":"Magistrado","t":"Patrulla.\nCuando se derrote esta carta: el jugador que la ha derrotado localiza Mutante fugado y lo vincula a su Superhéroe.\n[star] Aumento: Si Mutante fugado está vinculado a tu Superhéroe, esta carta gana [boost][boost][boost]."},
  "45135": {"n":"Uniciclo blindado","t":"Uniciclo blindado se enfrenta al jugador que tenga vinculado Mutante fugado (si es posible).\n[star] Respuesta obligada: después de que Uniciclo blindado ataque, resuelve la capacidad \"Especial\" del Entorno Ubicación."},
  "45136": {"n":"Guardia mecanizado de Genosha","t":"Guardia. Dureza.\n[star] Respuesta obligada: después de que Guardia mecanizado de Genosha ataque y derrote a uno de tus Aliados, resuelve dos veces la capacidad \"Especial\" del Entorno Ubicación.","f":"\"Their suits are built to contador de our powers.\" —Storm"},
  "45137": {"n":"Mutante fugado","t":"Vincula esta carta a tu Superhéroe.\nTodo Esbirro Genosha que se enfrente a ti gana Ataque veloz.\nAcción de Alter ego: resuelve la capacidad \"Especial\" del Entorno Ubicación → descarta esta carta.","f":"Mutants who wish to escape Genosha must localiza a way to evade the magistrate."},
  "45138": {"n":"Estado policial","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: El jugador que haya derrotado este Plan localiza la carta de Accesorio Mutante fugado y la muestra."},
  "45139": {"n":"Zona Azul de la Luna","t":"Inicio.\nTodos los Esbirros gana Guardia.\nEspecial: inflige 1 de Daño a tu Superhéroe.\nCuando se muestre esta carta: descarta todos los demás Entornos Ubicación que haya en juego."},
  "45140": {"n":"Gladiador","t":"Trabajo en equipo (Guardia imperial).\nMientras esté en juego Juicio por combate, Gladiador no puede sufrir Daño.\n[star] Aumento: Si está en juego Juicio por combate, quédate Gladiador como carta de Encuentro boca abajo."},
  "45141": {"n":"Oráculo","t":"Trabajo en equipo (Guardia imperial).\nCuando se muestre esta carta: quedas confundido. Si ya estabas confundido, resuelve la capacidad \"Especial\" del Entorno Ubicación."},
  "45142": {"t":"Trabajo en equipo (Guardia imperial).\nCuando se muestre esta carta: quedas aturdido. Si ya estabas aturdido, resuelve la capacidad \"Especial\" del Entorno Ubicación."},
  "45143": {"n":"Terremoto","t":"Trabajo en equipo (Guardia imperial).\nCuando se muestre esta carta: agota tu carta de Superhéroe. Si ya estaba agotada, resuelve la capacidad \"Especial\" del Entorno Ubicación."},
  "45144": {"n":"Estrella de Guerra","t":"Trabajo en equipo (Guardia imperial).\nCuando se muestre esta carta: descarta la primera carta del mazo de Encuentros. Si esa carta es un Esbirro Guardia imperial, muéstralo. De no ser así, resuelve la capacidad \"Especial\" del Entorno Ubicación."},
  "45145": {"n":"Miembro de la Guardia Imperial","t":"Vincula esta carta a un Esbirro. De no ser posible, esta carta gana Oleada.\nEl Esbirro vinculado recibe +4 de Vida y gana el rasgo Guardia imperial.\nInterrupción obligada: cuando el Esbirro vinculado sea derrotado, resuelve la capacidad \"Especial\" del Entorno Ubicación."},
  "45146": {"n":"Juicio por combate","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: devuelve al mazo de Encuentros todos los Esbirros Guardia imperial que haya en su pila de descartes y baraja el mazo.","f":"Shi'ar law grants the accused una opportunity to defend themselves, but they must battle the Guardia imperial."},
  "45147a": {"n":"La pirámide de En Sabah Nur","t":"Contenido: Apocalipsis (I) y Apocalipsis (II). (Apocalipsis (II) y Apocalipsis (III) para jugar en modo Experto.) Conjuntos de Encuentros de En Sabah Nur y Normal. Dos conjuntos de Encuentros modulares (Tecnología Celestial y Clan Akkaba).\nPreparación: Apocalipsis empieza la partida con su identidad Biomorfo. Reparte a cada jugador 1 carta de Encuentro boca abajo."},
  "45147b": {"n":"La pirámide de En Sabah Nur","t":"[star] Respuesta obligada: después de resolver el paso uno de la fase del Villano, coloca 1 contador de Poder sobre esta carta. Si hay al menos 4 contadores de Poder sobre ella, el jugador inicial quita 4 contadores y descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte una carta Superpoder, y muestra esa carta.","f":"Within his high-tech pyramid, Apocalipsis prepares for his ascension."},
  "45148a": {"n":"La ascensión de Apocalipsis","t":"Cuando se muestre esta carta: El jugador inicial descarta cartas de la parte superior del mazo de Encuentros until a Superpoder card is descartado y la muestra.","f":"You've seen what the future looks like if Apocalipsis's influence is allowed to grow. It's up to you to stop the megalomaniac sobre esta carta y now!"},
  "45148b": {"n":"La ascensión de Apocalipsis","t":"[star] Respuesta obligada: después de resolver el paso uno de la fase del Villano, coloca 1 contador de Poder sobre esta carta. Si hay al menos 4 contadores de Poder sobre ella, el jugador inicial quita 4 contadores y descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte una carta Superpoder, y muestra esa carta.\nSi se completa esta etapa, los jugadores pierden la partida."},
  "45149": {"n":"Fuerza descomunal","t":"Vincula esta carta a Apocalipsis y cambia a su identidad Gigante.\n[star] Interrupción obligada: cuando Apocalipsis te ataque, quedas aturdido. Descarta esta carta después de esta activación.\n[star] Aumento: después de esta activación, muestra esta carta."},
  "45150": {"n":"Rayo biomórfico","t":"Cuando se muestre esta carta: Si Apocalipsis tiene adoptada su identidad Biomorfo, se activa contra ti. De no ser así, Apocalipsis cambia a su identidad Biomorfo y colocas 1 contador de Poder sobre el Plan principal.\n[star] Aumento: después de esta activación, Apocalipsis cambia a su identidad Biomorfo."},
  "45151": {"n":"Interfaz tecnológica","t":"Cuando se muestre esta carta: si Apocalipsis tiene adoptada su identidad Ciberpático, se activa contra ti. De no ser así, Apocalipsis cambia a su identidad Ciberpático y colocas 1 contador de Poder sobre el Plan principal.\n[star] Aumento: después de esta activación, Apocalipsis cambia a su identidad Ciberpático."},
  "45152": {"n":"Déspota colosal","t":"Cuando se muestre esta carta: si Apocalipsis tiene adoptada su identidad Gigante, se activa contra ti. De no ser así, Apocalipsis cambia a su identidad Gigante y colocas 1 contador de Poder sobre el Plan principal.\n[star] Aumento: después de esta activación, Apocalipsis cambia a su identidad Gigante."},
  "45153": {"n":"Fuente de poder","t":"Cuando se derrote esta carta: Si Apocalipsis tiene adoptada su identidad Biomorfo, se activa contra el jugador que haya derrotado este Plan. De no ser así, Apocalipsis cambia a su identidad Biomorfo y le das una carta de Estado \"Duro\"."},
  "45154": {"n":"Conectado","t":"Cuando se derrote esta carta: si Apocalipsis tiene adoptada su identidad Ciberpático, se activa contra el jugador que haya derrotado este Plan. De no ser así, Apocalipsis cambia a su identidad Ciberpático y le das una carta de Estado \"Duro\"."},
  "45155": {"n":"Agigantamiento","t":"Cuando se derrote esta carta: si Apocalipsis tiene adoptada su identidad Gigante, se activa contra el jugador que haya derrotado este Plan. De no ser así, Apocalipsis cambia a su identidad Gigante y le das una carta de Estado \"Duro\"."},
  "45156": {"n":"Armadura Celestial","t":"Vincula esta carta al Villano.\n[star] Interrupción obligada: cuando al Villano ejecute el Plan contra ti, descarta la primera carta de la parte superior de tu mazo. Si el recurso de esa carta tiene:\n[energy] — Cura 2 de Daño al Villano.\n[mental] — Quedas confundido. Descarta esta carta.\n[physical] — Dale al Villano una carta de Estado \"Duro\".\n[wild] — Aplica todo lo anterior."},
  "45157": {"n":"Arma Celestial","t":"Vincula esta carta al Villano.\n[star] Interrupción obligada: cuando el Villano te ataca, descarta la primera carta de la parte superior de tu mazo. Si el recurso de esa carta tiene:\n[energy] — Inflige 2 de Daño a tu Superhéroe.\n[mental] — Descarta una carta de tu mano.\n[physical] — Quedas aturdido. Descarta esta carta.\n[wild] — Aplica todo lo anterior."},
  "45158": {"n":"Tecnología Celestial","t":"Cuando se muestre esta carta: por cada Accesorio Celestial que haya en juego, resuelve su efecto como si el Villano vinculado acabase de ejecutar el Plan contra ti y también acabase de atacarte. Si el Villano no tiene vinculado nigún Accesorio Celestial, busca un Accesorio Celestial en el mazo de Encuentros y en su pila de descartes y muéstralo. (Baraja el mazo.)"},
  "45159": {"t":"Dureza. Infame.\n[star] Cuando Ozymandias ejecuta el Plan, coloca la Amenaza sobre Ritual antiguo.\n[star] Aumento: elige entre colocar 3 de Amenaza sobre Ritual antiguo o que esta carta gane [boost][boost][boost]."},
  "45160": {"n":"Escarabeo","t":"Ataque veloz.\n[star] Respuesta obligada: después de que Escarabeo ataque, coloca 1 de Amenaza sobre Ritual antiguo (3 de Amenaza si el ataque ha derrotado a un Aliado)."},
  "45161": {"n":"Fanático del clan Akkaba","t":"Guardia.\nCuando se derrote esta carta: coloca 2 de Amenaza sobre Ritual antiguo.\n[star] Aumento: coloca 1 de Amenaza sobre Ritual antiguo."},
  "45162": {"n":"Veneración por el tirano","t":"Cuando se muestre esta carta: coloca 5 de Amenaza sobre Ritual antiguo.\n[star] Aumento: elige entre colocar 3 de Amenaza sobre Ritual antiguo o que esta carta gane [boost][boost][boost]."},
  "45163": {"n":"Ritual antiguo","t":"Permanente. Inicio.\nRespuesta obligada: después de que se coloque Amenaza sobre esta carta, si hay al menos 10 de Amenaza sobre ella, quita 5 de Amenaza de este Plan y reparte a cada jugador una carta de Encuentro boca abajo."},
  "45164": {"n":"Agente de Apocalipsis","t":"Guardia.\nCuando se muestre esta carta: elige entre añadir el Agente de Apocalipsis a la zona de misión o que se active contra ti.\n[star] Aumento: inflige 1 de Daño a un Aliado que esté en la misión. Dale al enemigo una carta de aumento adicional."},
  "45165": {"n":"Crisis global","t":"Cuando se muestre esta carta: elige entre colocar 3 de Amenaza sobre el Plan secundario Misión, o bien sufrir 1 de Daño y que esta carta gane Oleada.\n[star] Aumento: coloca 1 de Amenaza sobre el Plan secundario Misión. Dale al enemigo activado una carta de aumento adicional."},
  "45166a": {"n":"Liberar el Núcleo de Seattle","t":"Respuesta obligada: después de que resuelvas un intento por completar la misión, coloca 1 contador de Intento sobre esta carta e inflige 1 de Daño a cada Aliado que haya en la misión. Si hay 4 contadores de Intento sobre esta carta, retira de la partida Equipo para la misión y dale la vuelta a esta carta.\nCuando se derrote esta carta: devuelve todas las cartas de Jugador que haya en la misión a los mazos de sus propietarios y barájalos. Dale la vuelta a Equipo para la misión y a esta carta."},
  "45166b": {"n":"Liberar el Núcleo de Seattle","t":"Respuesta obligada: después de que pongas boca arriba esta cara, retira de la partida todas las cartas que haya en la zona de misión y haz lo siguiente:\n• Si la misión no ha sido derrotada, coloca 2[per_hero] de Amenaza sobre el Plan principal.\n• Si la misión ha sido derrotada, cada jugador añade a su mano 1 copia de la Mejora Medidas desesperadas."},
  "45167a": {"n":"Evacuar a los supervivientes","t":"Respuesta obligada: después de que resuelvas un intento por completar la misión, coloca 1 contador de Intento sobre esta carta e inflige 1 de Daño a cada Aliado que haya en la misión. Si hay 4 contadores de Intento sobre esta carta, retira de la partida Equipo para la misión y dale la vuelta a esta carta.\nCuando se derrote esta carta: devuelve todas las cartas de Jugador que haya en la misión a los mazos de sus propietarios y barájalos. Dale la vuelta a Equipo para la misión y a esta carta."},
  "45167b": {"n":"Evacuar a los supervivientes","t":"Respuesta obligada: después de que pongas boca arriba esta cara, retira de la partida todas las cartas que haya en la zona de misión y haz lo siguiente:\n• Si la misión no ha sido derrotada, inflige cada jugador una carta de Encuentro boca abajo.\n• Si la misión ha sido derrotada, cada jugador busca 1 carta en su mazo y en su pila de descartes, y la añade a su mano."},
  "45168a": {"n":"Sabotear la Muralla Marina","t":"Respuesta obligada: después de que resuelvas un intento por completar la misión, coloca 1 contador de Intento sobre esta carta e inflige 1 de Daño a cada Aliado que haya en la misión. Si hay 4 contadores de Intento sobre esta carta, retira de la partida Equipo para la misión y dale la vuelta a esta carta.\nCuando se derrote esta carta: devuelve todas las cartas de Jugador que haya en la misión a los mazos de sus propietarios y barájalos. Dale la vuelta a Equipo para la misión y a esta carta."},
  "45168b": {"n":"Sabotear la Muralla Marina","t":"Respuesta obligada: después de que pongas boca arriba esta cara, retira de la partida todas las cartas que haya en la zona de misión y haz lo siguiente:\n• Si la misión no ha sido derrotada, localiza La Muralla Marina de Norteamérica y muéstrala. (Baraja el mazo.)\n• Si la misión ha sido derrotada, localiza La Muralla Marina de Norteamérica, retírala de la partida, y cada jugador inflige 3 de Daño a un enemigo."},
  "45169a": {"n":"Encontrar a los mutantes desaparecidos","t":"Respuesta obligada: después de que resuelvas un intento por completar la misión, coloca 1 contador de Intento sobre esta carta e inflige 1 de Daño a cada Aliado que haya en la misión. Si hay 4 contadores de Intento sobre esta carta, retira de la partida Equipo para la misión y dale la vuelta a esta carta.\nCuando se derrote esta carta: devuelve todas las cartas de Jugador que haya en la misión a los mazos de sus propietarios y barájalos. Dale la vuelta a Equipo para la misión y a esta carta."},
  "45169b": {"n":"Encontrar a los mutantes desaparecidos","t":"Respuesta obligada: después de que pongas boca arriba esta cara, retira de la partida todas las cartas que haya en la zona de misión y haz lo siguiente:\n• Si la misión no ha sido derrotada, cada jugador descarta 1 card de su mano.\n• Si la misión ha sido derrotada, cada jugador añade a su mano un Aliado de Campaña que esté apartado."},
  "45170a": {"n":"Proteger al Profesor","t":"Respuesta obligada: después de que resuelvas un intento por completar la misión, coloca 1 contador de Intento sobre esta carta e inflige 1 de Daño a cada Aliado que haya en la misión. Si hay 4 contadores de Intento sobre esta carta, retira de la partida Equipo para la misión y dale la vuelta a esta carta.\nCuando se derrote esta carta: devuelve todas las cartas de Jugador que haya en la misión a los mazos de sus propietarios y barájalos. Dale la vuelta a Equipo para la misión y a esta carta."},
  "45170b": {"n":"Proteger al Profesor","t":"Respuesta obligada: después de que pongas boca arriba esta cara, retira de la partida todas las cartas que haya en la zona de misión y haz lo siguiente:\n• Si la misión no ha sido derrotada, los jugadores pierden la partida.\n• Si la misión ha sido derrotada, cada jugador busca un Aliado en su mazo y en su pila de descartes, y lo añade a su mano."},
  "45171a": {"n":"Equipo para la misión","t":"Esta carta no puede descartarse y está bajo el control del jugador inicial.\nAcción: agota Equipo para la misión → elige una opción:\n• Reduce en 2 el coste del siguiente Aliado que se juegue en la zona de misión.\n• Realiza un intento por completar la misión."},
  "45171b": {"n":"Equipo para la misión","t":"Esta carta no puede descartarse y está bajo el control del jugador inicial.\nAcción: agota Equipo para la misión → elige un jugador para que robe 1 carta.","f":"\"Otra misión completada con éxito.¡Espero que esta vez no nos demanden por daños y perjuicios!\" —Polaris"},
  "45172": {"n":"Destino","t":"Respuesta: después de que Destino entre en tu mano, quita 2 de Amenaza del Plan principal.","f":"\"Aventajar a tu enemigo es un juego de niños cuando conoces el futuro.\""},
  "45173": {"n":"Destello","t":"Respuesta: después de que Destello entre en tu mano, inflige 2 de Daño to al Villano.","f":"\"Me llamo Destello. ¿Cuál de los dos crees que va a ser más rápido?\""},
  "45174": {"n":"Morfo","t":"Respuesta: después de que Morfo entre en tu mano, confunde al Villano.","f":"\"¿A qué viene tanto aspaviento, nene?\""},
  "45175": {"n":"Hombre-X","t":"Respuesta: después de que Hombre-X entre en tu mano, dale a tu Superhéroe una carta de Estado \"Duro\".","f":"\"¡Los inocentes estarán a salvo mientras yo pueda decir algo al respecto!\""},
  "45176": {"n":"Medidas desesperadas","t":"Vincula esta carta a un Aliado. Límite de 1 por Aliado.\nEl Aliado vinculado recibe +1 INT, +1 ATQ, +1 de Vida, y se considera que tiene un icono de recurso Universal ([wild]) además de su icono de recurso impreso."},
  "45177": {"n":"La Muralla Marina de Norteamérica","t":"Complicación 2[per_hero]. Oleada. Victoria 2.\nEl Villano no puede sufrir Daño.\n[star] Aumento: quédate esta carta como carta de Encuentro boca abajo.","f":"Apocalipsis's high-tech sea wall protects the eastern frontier of his realm."},
  "45178": {"n":"Refugiados Asustados","t":"Respuesta obligada: después de que esta carta entre en tu mano, muéstrala. Luego, roba 1 carta.\nAcción de Alter ego: Agota tu carta de Superhéroe → retira esta carta de la partida."},
  "45179a": {"n":"Mister Siniestro","t":"Victoria 5.\nNo puede sufrir Daño mientras haya otro Esbirro en la misión.\nLos jugadores no pueden asignar cartas con el mismo icono de recurso ([energy], [mental], [physical], o [wild]) ta más de un Aliadoen cada intento por completar una misión."},
  "45179b": {"n":"Mister Siniestro","t":"Represalia 1. Dureza. Infame. Victoria 3.\nMister Sinister se enfrenta al jugador inicial."},
  "45180a": {"n":"El Rey Sombra","t":"Victoria 5.\nNo puede sufrir Daño mientras haya otro Esbirro en la misión.\nRespuesta de misión: después de que descartes cartas, coloca 2 de Amenaza sobre el Plan secundario [[Misión] por cada Recurso mental ([mental]) descartado."},
  "45180b": {"n":"El Rey Sombra","t":"Dureza. Victoria 3.\nEl Rey Sombra se enfrenta al jugador inicial.\n[star] Respuesta obligada: después de que El Rey Sombra te ataque, elige un Aliado que controles que tenga la puntación mas alta de INT. Elige entre descartar ese Aliado, o bien colocar tanta Amenaza como su INT sobre el Plan principal."},
  "45181a": {"n":"Abismo","t":"Victoria 5.\nNo puede sufrir Daño mientras haya otro Esbirro en la misión.\nRespuesta de misión: después de que descartes cartas, vincula a Abismo boca abajo cada carta con un recurso Universal [wild] descartado. (No pueden utilizarse par el intento por completar la misión.)"},
  "45181b": {"n":"Abismo","t":"Dureza. Victoria 3.\nAbismo recibe +2 de Vida por cada carta que tenga vinculada boca abajo y se enfrenta al jugador inicial.\n[star] Respuesta obligada: después de que Abismo se active contra ti, vincúlale boca abajo la primera carta de la parte superior de tu mazo."},
  "45182a": {"n":"Hombre de Azúcar","t":"Victoria 5.\nNo puede sufrir Daño mientras haya otro Esbirro en la misión.\nRespuesta de misión: después de que descartes cartas, cura 3 de Daño al Hombre de Azúcar por cada recurso Físico ([physical]) descartado."},
  "45182b": {"n":"Hombre de Azúcar","t":"Dureza. Victoria 3.\nHombre de Azúcar se enfrenta al jugador inicial.\n[star] Interrupción obligada: cuando Hombre de Azúcar ataque, este ataque gana Penetrante. Si este ataque derrota a un personaje, cura 5 de Daño al Hombre de Azúcar."},
  "45183a": {"t":"Victoria 5.\nNo puede sufrir Daño mientras haya otro Esbirro en la misión.\nRespuesta de misión: después de que descartes cartas, inflige 1 de Daño a un Aliado que esté en la misión por cada recurso Energía [energy] descartado."},
  "45183b": {"t":"Dureza. Victoria 3.\nMikhail Rasputin se enfrenta al jugador inicial.\n[star] Interrupción obligada: cuando Mikhail Rasputin te ataque, inflige 1 de Daño a tu Superhéroe."},
  "45184a": {"n":"Apocalipsis","t":"[star] Los ataques de Apocalipsis ganan Brutalidad.\nRespuesta obligada: después de que Apocalipsis cambie a esta identidad, inflige 1 de Daño indirecto a cada jugador."},
  "45184b": {"n":"Apocalipsis","t":"Represalia 1.\nRespuesta obligada: después de que Apocalipsis cambie a esta identidad, coloca 1 de Amenaza sobre cada Plan que haya en juego.","f":"\"I have judged you y found you wanting.\""},
  "45184c": {"n":"Apocalipsis","t":"Firmeza.\nRespuesta obligada: después de que Apocalipsis cambie a esta identidad, se cura 1 de Daño."},
  "45185a": {"n":"Apocalipsis","t":"[star] Los ataques de Apocalipsis ganan Brutalidad.\nRespuesta obligada: después de que Apocalipsis cambie a esta identidad, inflige 2 de Daño indirecto a cada jugador."},
  "45185b": {"n":"Apocalipsis","t":"Represalia 1.\nRespuesta obligada: después de que Apocalipsis cambie a esta identidad, coloca 2 de Amenaza sobre cada Plan que haya en juego.","f":"\"I have judged you y found you wanting.\""},
  "45185c": {"n":"Apocalipsis","t":"Firmeza.\nRespuesta obligada: después de que Apocalipsis cambie a esta identidad, se cura 2 de Daño."},
  "45186a": {"n":"Apocalipsis","t":"[star] Los ataques de Apocalipsis ganan Brutalidad.\nRespuesta obligada: después de que Apocalipsis cambie a esta identidad, inflige 3 de Daño indirecto a cada jugador."},
  "45186b": {"n":"Apocalipsis","t":"Represalia 1.\nRespuesta obligada: después de que Apocalipsis cambie a esta identidad, coloca 3 de Amenaza sobre cada Plan que haya en juego.","f":"\"I have judged you y found you wanting.\""},
  "45186c": {"n":"Apocalipsis","t":"Firmeza.\nRespuesta obligada: después de que Apocalipsis cambie a esta identidad, se cura 3 de Daño."},
  "46001a": {"n":"Hombre de Hielo","t":"\"¡Congélate!\" — Interrupción: cuando el Hombre de Hielo realice un ataque básico o una defensa básica contra un enemigo, vincula una copia apartada de Congelación a ese enemigo.","f":"\"¡Aquí llega el héroe más fresco del equipo!\""},
  "46001b": {"t":"Bobby Drake empieza la partida con 6 cartas de Mejora Congelación apartadas.\nRefrescado — Respuesta: después de que cambies a esta identidad, por cada copia de Congelación que haya en juego, coge 1 carta de Hielo de tu pila de descartes, añádela a tu mazo y barájalo."},
  "46002": {"n":"Congelación","t":"Permanente.\nEl enemigo vinculado recibe -1 PLA y -1 ATQ.\nRespuesta obligada: después de que el enemigo vinculado se active o abandone el juego, aparta esta carta."},
  "46003": {"n":"Duplicado de nieve","t":"No pueden vincularse Mejoras a esta carta.\n[star] Duplicado de nieve sufre -1 de Daño derivado ([cost]) después de atacar a un enemigo que tenga vinculada Congelación.","f":"\"Se podría decir que tiene una actitud muy fría.\" —Hombre de Hielo"},
  "46004": {"n":"Cinturón de poder","t":"Recibes +3 de Vida.\nRecurso de Héroe: agota el Cinturón de poder → genera un recurso [wild] para una carta Hielo.","f":"La Bestia fabricó este cinturón de alta tecnología para ayudar al Hombre de Hielo a controlar mejor sus poderes."},
  "46005": {"n":"Percepción crioquinética","t":"Respuesta de Héroe: después de que resuelvas tu capacidad \"¡Congélate!\", agota esta carta → roba 1 carta. Si esa carta tiene el rasgo Hielo, prepara al Hombre de Hielo.","f":"\"¿Os acordáis de cuando solía arrojar bolas de nieve a Magneto?\" —Hombre de Hielo"},
  "46006": {"n":"Tobogán de Hielo","t":"Hombre de Hielo recibe +1 INT, +1 ATQ y +1 DEF, y gana el rasgo Aéreo.\nRespuesta obligada: después de que cambies a la identidad de Alter ego, devuelve esta carta a tu mazo y barájalo."},
  "46007": {"n":"Encerrado en hielo","t":"Sólo en identidad de Héroe. Vincula esta carta a un enemigo. Máximo de 1 por enemigo.\nInterrupción obligada: cuando el enemigo vinculado vaya a activarse, en vez de eso descarta Encerrado en hielo. Luego vincula a ese enemigo una carta de Congelación que este apartada."},
  "46008": {"n":"Muro de hielo","t":"Interrupción obligada: cuando un Superhéroe vaya a sufrir cualquier cantidad de Daño a consecuencia de un ataque enemigo, en vez de eso coloca ese Daño sobre esta carta. Luego, si hay al menos 8 de Daño sobre esta carta, descártala y vincula una copia apartada de Congelación al enemigo que acaba de atacar."},
  "46009": {"n":"Ataque ártico","t":"Acción de Héroe (ataque): Elige una opción:\n• Inflige 4 de Daño a un enemigo y vincúlale una copia apartada de Congelación.\n• Inflige 6 de Daño a un enemigo que tenga vinculada una copia de Congelación."},
  "46010": {"n":"Estallido de hielo","t":"Acción de Héroe: Elige un jugador. Vincula una copia apartada de Congelación al Villano y a cada Esbirro que esté enfrentado a ese jugador. Inflige 3 de Daño a todo enemigo que tenga vinculada una copia de Congelación.","f":"\"Vamos a enfriar los ánimos de estos tíos.\" —Hombre de Hielo"},
  "46011": {"n":"¡No te calientes!","t":"Acción de Héroe (intervención): quita 3 de Amenaza de un Plan. Vincula una copia apartada de Congelación a un enemigo.","f":"\"Ya en serio, colega. Se me ha acabado el repertorio de chistecitos de frio.\" —Hombre de Hielo"},
  "46012": {"n":"Chica-Tiburón","t":"[star] Mientras Chica-Tiburón esté atacando a un enemigo, recibe +1 ATQ por cada Mejora que tenga vinculada ese enemigo.","f":"Lo único que da más miedo que una adolescente hambrienta es una capaz de convertirse en tiburón."},
  "46013": {"t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Patrulla-X.\nRespuesta: después de que Glob entre en juego, inflige 2 de Daño a un enemigo que tenga una Mejora vinculada."},
  "46014": {"n":"Fuego de supresión","t":"Vincula esta carta a un Esbirro. Máximo de 1 por Esbirro.\nInterrupción de Héroe: cuando ataques y derrotes al Esbirro vinculado, cura 2 de Daño a tu Héroe."},
  "46015": {"n":"Movimiento inesperado","t":"Interrupción de Héroe: cuando realices un ataque básico contra un enemigo que tenga una Mejora vinculada, recibes +2 ATQ para este ataque. Si este ataque derrota a ese enemigo, prepara tu Héroe."},
  "46016": {"n":"¡Chúpate ésa!","t":"Acción de Héroe (ataque): inflige 7 de Daño a un enemigo que tenga una Mejora vinculada.","f":"\"¡Y no vuelvas!\" —Magik"},
  "46017": {"n":"Buscando problemas","t":"Acción de Héroe (intervención): descarta cartas de la parte superior del mazo de Encuentros hasta que descartes un Esbirro. Pon en juego ese Esbirro enfrentado a ti → quita 3 de Amenaza del Plan principal."},
  "46018": {"n":"Ejercer más presión","t":"Victoria 0.\nCuando se derrote esta carta: cada jugador puede buscar un Evento Ataque en su mazo y su pila de descartes y añadirlo a su mano. (Baraja el mazo.) Hasta el final de la fase cada Evento Ataque inflige 1 de Daño adicional."},
  "46019": {"n":"Gatasombra","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Patrulla-X.\nRespuesta: después de que juegues a Gatasombra desde tu mano, elige un Plan secundario que esté en juego → ese Plan pierde todos los iconos [acceleration], [amplify], [crisis], y [hazard] hasta el final de la ronda."},
  "46020": {"n":"Pico","t":"Respuesta: después de que juegues a Pico desde tu mano, quita 1 de Amenaza de un Plan por cada Aliado Patrulla-X que controles.","f":"\"No soy muy fuerte ni lanzo rayos de energía, pero se me da bien hacer amigos.\""},
  "46021": {"n":"Espíritu de equipo","t":"Acción de Héroe: agota Espíritu de equipo → juega una carta de tu mano que tenga un rasgo en común con tu Héroe, reduciendo en 1 su coste en recursos."},
  "46022": {"n":"Restablecimiento","t":"Acción de Alter ego: cura a tu Alter ego tanto Daño como tu REC.","f":"\"Parece que ya empiezas a sentirte mejor.\" —Stephen Extraño"},
  "46023": {"n":"El poder de todos unidos","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta Básica (gris)."},
  "46024": {"n":"Temperamental","t":"Dale esta carta al jugador que lleva a Bobby Drake.\nRespuesta obligada: después de que vincules una copia de Congelación a un enemigo, sufres 1 de Daño.\nRespuesta de Alter ego : después de que realices una recuperación básica, descarta Temperamental."},
  "46025": {"n":"Piros","t":"Ataque veloz.\n[star] Los ataques de Piros infligen Daño indirecto."},
  "46026": {"n":"Jugando con fuego","t":"Cuando se derrote esta carta: el jugador que haya derrotado este Plan descarta las 3 primeras cartas de la parte superior de su mazo y sufre 1 de Daño indirecto por cada icono de recurso que se haya descartado de este modo."},
  "46027": {"n":"Lanzallamas de Piros","t":"Vincula esta carta a Piros. De no ser posible, esta carta gana Oleada.\n[star] Interrupción obligada: cuando Piros te ataque, descarta la primera carta de tu mazo. Piros recibe +1 ATQ para este ataque por cada icono de recurso que haya en esta carta."},
  "46028": {"n":"¡Arde!","t":"Cuando se muestre esta carta: descarta las 2 primeras cartas de tu mazo (las 3 primeras cartas si Piros está en juego). Sufres 1 de Daño indirecto por cada icono de recurso que se haya descartado de este modo.\n[star] Aumento: descarta la primera carta de la parte superior de tu mazo. Esta carta recibe +1 icono de Aumento ([boost]) por cada icono de recurso que haya en esta carta."},
  "46029": {"n":"Saurón","t":"Cuando se muestre esta carta: busca el Accesorio Absorción de vida en el mazo y la pila de descartes de Encuentros y muéstralo.\n[star] Aumento: cura 3 de Daño al enemigo activado y dale una carta de Estado \"Duro\"."},
  "46030": {"n":"¡Saurón vive!","t":"Cuando se derrote esta carta: el jugador que haya derrotado este Plan busca una copia de Saurón en el mazo de Encuentros y en su pila de descartes, y se la queda como carta de Encuentro boca abajo.","f":"cuando Dr. Lykos absorbs mutant energy, he transforms into the terrifying Saurón!"},
  "46031": {"n":"Absorción de vida","t":"Vincula esta carta al Esbirro que tenga el valor impreso más alto de Vida. Se activa contra ti. Si no se activa ningún Esbirro de este modo, esta carta gana Oleada.\n[star] Interrupción obligada: cuando el enemigo vinculado te ataque, sufres 2 de Daño y le das al enemigo atacante una carta de Estado \"Duro\"."},
  "46032": {"n":"La mirada de Saurón","t":"Cuando se muestre esta carta: descarta las 2 primeras cartas de tu mazo (las 3 primeras cartas si Saurón está en juego). Por cada icono de recurso que se haya descartado de este modo, haz lo siguiente:\n[energy] — Coloca 1 de Amenaza sobre el Plan principal.\n[mental] — Descarta 1 carta de tu mano.\n[physical] — Inflige 1 de Daño a tu Superhéroe.\n[wild] — agota un personaje que controles."},
  "47001a": {"n":"Júbilo","t":"\"¡Buah,tronco!\" — Recurso: agota a Júbilo → genera un recurso [wild].","f":"\"¡Tengo que decirte que me pongo de mala uva cuando me ignoran!\""},
  "47001b": {"t":"Asidua del centro comercial — Acción: busca en tu mazo el Plan secundario de jugador De compras y ponlo en juego. (Límite de una vez por fase.)","f":"\"¡Ese sitio molaba más cuando yo vivía aquí!\""},
  "47002": {"n":"Lobezno","t":"[star] Los ataques de Lobezno ganan Penetrante.\nRespuesta: después de que cambies a la identidad de Alter ego, cura 3 de Daño a Lobezno.","f":"\"Baja la voz, niña.¡No estamos aquí de vacaciones!\""},
  "47003": {"n":"De compras","t":"Ni Héroes ni Aliados pueden quitar Amenaza de este Plan.\nAcción de Alter ego: agota tu Superhéroe → quita 1 de Amenaza de esta carta. Cualquier jugador puede aplicar esta capacidad.\nCuando se derrote esta carta: el jugador que haya derrotado este Plan busca una carta Objeto y la pone en juego."},
  "47004": {"n":"Chaqueta de Júbilo","t":"Júbilo recibe +1 INT.\nRespuesta de Héroe (intervención): después de que juegues un Evento Intervención, agota la Chaqueta de Júbilo y elige un Plan → quita 1 de Amenaza de ese Plan por cada tipo de recurso distinto que hayas usado para pagar el coste de ese Evento."},
  "47005": {"n":"Gafas de sol de Júbilo","t":"Júbilo recibe +1 ATQ.\nRespuesta de Héroe (ataque): después de que juegues un Evento Ataque, agota las Gafas de sol de Júbilo y elige un enemigo → inflige 1 de Daño a ese enemigo por cada tipo de recurso distinto que hayas usado para pagar el coste de ese Evento."},
  "47006": {"n":"Destello cegador","t":"Acción de Héroe: elige X enemigos, siendo X la cantidad de tipos de recurso distintos ([energy], [mental], [physical], y [wild]) usados para pagar el coste de este Evento. Aturde y confunde a todos los enemigos elegidos."},
  "47007a": {"n":"Polvorilla","t":"Acción de Héroe (ataque): inflige 4 de Daño a un enemigo. Si has pagado el coste de esta carta usando 2 tipos de recurso distinto, aturde a ese enemigo.","f":"\"¿De dónde sacan tantos matones? Seguro que hacen descuento en alguna parte.\" —Júbilo"},
  "47007b": {"n":"Polvorilla","t":"Acción de Héroe (ataque): inflige 4 de Daño a un enemigo. Si has pagado el coste de esta carta usando 2 tipos de recurso distinto, aturde a ese enemigo.","f":"\"¿De dónde sacan tantos matones? Seguro que hacen descuento en alguna parte.\" —Júbilo"},
  "47007c": {"n":"Polvorilla","t":"Acción de Héroe (ataque): inflige 4 de Daño a un enemigo. Si has pagado el coste de esta carta usando 2 tipos de recurso distinto, aturde a ese enemigo.","f":"\"¿De dónde sacan tantos matones? Seguro que hacen descuento en alguna parte.\" —Júbilo"},
  "47008a": {"n":"Estallido de Luz","t":"Acción de Héroe (intervención): quita 3 de Amenaza de un Plan. Si has pagado el coste de esta carta usando 2 tipos de recurso distinto, confunde a ese enemigo.","f":"\"Tíos, yo ya he tenido bastante ¡Me piro!\" —Júbilo"},
  "47008b": {"n":"Estallido de Luz","t":"Acción de Héroe (intervención): quita 3 de Amenaza de un Plan. Si has pagado el coste de esta carta usando 2 tipos de recurso distinto, confunde a ese enemigo.","f":"\"Tíos, yo ya he tenido bastante ¡Me piro!\" —Júbilo"},
  "47008c": {"n":"Estallido de Luz","t":"Acción de Héroe (intervención): quita 3 de Amenaza de un Plan. Si has pagado el coste de esta carta usando 2 tipos de recurso distinto, confunde a ese enemigo.","f":"\"Tíos, yo ya he tenido bastante ¡Me piro!\" —Júbilo"},
  "47009": {"n":"Gran final","t":"Acción de Héroe (ataque): Inflige 2 de Daño a un enemigo. Por cada tipo de recurso distinto ([energy], [mental], [physical], y [wild]) que hayas usado para pagar el coste de esta carta, elige un enemigo e inflígele 2 de Daño."},
  "47010a": {"n":"Plasmoides de Energía","f":"\"¡Tapaos los ojos, equipo!¡Esto se va a iluminar cosa mala!!\" —Júbilo"},
  "47010b": {"n":"Plasmoides de Energía","f":"\"¡Tapaos los ojos, equipo!¡Esto se va a iluminar cosa mala!!\" —Júbilo"},
  "47010c": {"n":"Plasmoides de Energía","f":"\"¡Tapaos los ojos, equipo!¡Esto se va a iluminar cosa mala!!\" —Júbilo"},
  "47011": {"n":"Cámara","t":"[star] Cámara sufre -1 de Daño derivado ([cost]) después de que ataque a un enemigo confundido.","f":"\"No te preocupes por mí, encanto; lo tengo controlado.\""},
  "47012": {"n":"Vaina","t":"[star] Interrupción: cuando Vaina use un atributo básico, gasta un máximo de 3 recursos → si has gastado al menos 1:\n[energy] — Vaina recibe +1 a ese atributo para este uso.\n[mental] — Cura 1 de Daño a Vaina.\n[physical] — Prepara a Vaina después de este uso."},
  "47013": {"n":"Disfraz","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nAcción (intervención): agota Disfraz y tu carta de Superhéroe → quita 2 de Amenaza de un Plan.","f":"\"Me llamo Parche. A secas.\" —Lobezno"},
  "47014": {"n":"Ataque a traición","t":"Respuesta de Héroe (ataque): después de que tu Héroe intervenga, inflige 4 de Daño a un enemigo (7 de Daño si esa intervención ha quitado la última ficha de Amenaza de un Plan).","f":"\"¡Tú haces daño amigosmi! ¡Ahora tú pagas!\" —Warlock"},
  "47015": {"n":"Tres pasos por delante","t":"Acción de Héroe (intervención): por cada tipo de recurso distinto ([energy], [mental], [physical], y [wild]) que hayas usado para pagar el coste de esta carta, elige un Plan y quítale 2 de Amenaza.","f":"\"Deberías sentirte orgullosa, Pícara; ¡Glob y yo lo hemos planeado de antemano!\" —Camaleón"},
  "47016": {"n":"Generación X","t":"Victoria 0.\nCada personaje Patrulla-X recibe +1 INT mientras esté realizando una intervención básica contra este Plan.\nCuando se derrote esta carta: cada jugador puede buscar un Evento específico de Superhéroe en su mazo y su pila de descartes y añadirlo a su mano. (Baraja el mazo.)"},
  "47017": {"n":"El poder de la justicia","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta de Justicia (amarilla)."},
  "47018": {"n":"Sincro","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Patrulla-X.\nInterrupción: cuando uses un atributo básico, agota a Sincro → recibes +1 a ese atributo para este uso."},
  "47019": {"n":"Teléfono móvil","t":"Usos (3 contadores de Carga).\nAcción: agota el Teléfono móvil, quitale 1 contador de Carga y elige un jugador → ese jugador realiza un ataque básico o una intervención básica con un personaje que controle. Ese personaje recibe +1 INT y +1 ATQ para este uso."},
  "47020": {"n":"Gen X","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo MUTANTE. Máximo de 1 por jugador\nRecurso: agota Gen X → genera un recurso [wild] para un Evento que sea específico de un Superhéroe."},
  "47021": {"n":"Polivalente","t":"Acción de Héroe (ataque/intervención): si has pagado el coste de este Evento usando al menos 1:\n[physical] — Inflige 2 de Daño a un enemigo.\n[mental] — Quita 2 de Amenaza de un Plan.\n[energy] — Cura 2 de Daño a tu Superhéroe."},
  "47022": {"n":"Pareja insólita","t":"Equipo (Júbilo y Lobezno). Máximo de 1 por mazo.\nAcción de Héroe (ataque): confunde a un enemigo. Inflige 4 de Daño a un enemigo que esté confundido."},
  "47023": {"n":"Castigada","t":"Dale esta carta al jugador que lleva a Jubilation Lee.\nComo coste adicional para cambiar a tu identidad de Héroe durante tu turno, debes gastar 2 recursos del mismo tipo.\nCuando se muestre esta carta: cambia a la identidad de tu Alter ego.\nRespuesta: después de que juegues un Evento de Júbilo, retira esta carta de la partida."},
  "47024": {"t":"Dureza.\n[star] Respuesta obligada: después de que Nanny te ataque, si controlas al menos 1 Aliado, busca una copia de Niño \"perdido\" en el mazo de Encuentros, en su pila de descartes y en la zona apartada, y muéstrala."},
  "47025": {"n":"Niños traviesos","t":"Cuando se muestre esta carta: coloca 1 de Amenaza sobre esta carta por cada tipo de recurso distinto ([energy], [mental], [physical], y [wild]) que haya en las cartas que tienes en la mano.","f":"Nanny cruza constantemente la línea que separa el \"rescate\" del \"secuestro\"."},
  "47026": {"n":"Armadura de combate","t":"Vincula esta carta al Esbirro que tenga menos Vida restante. De no ser posible, esta carta gana Oleada.\nEl Esbirro vinculado recibe +3 de Vida y gana el rasgo Aéreo.","f":"El diseño de la armadura de combate de Nanny encubre sus verdaderas capacidades."},
  "47027": {"n":"Niño \"perdido\"","t":"El Aliado vinculado se considera un Esbirro Devuelto con el texto de reglas en blanco. La puntuación de PLA del Esbirro vinculado es igual a su puntuación impresa de INT, y no sufre Daño derivado.\nCuando se muestre esta carta: vincula esta carta al Aliado que tenga el coste más alto y no tenga ya vinculada una copia de Niño \"perdido\". El Aliado vinculado se enfrenta al jugador que lo controla. De no ser posible, esta carta gana Oleada."},
  "47028": {"n":"Caos mutante","t":"Alianza.\nAcción de Héroe: elige un Aliado X-Force y un Aliado Patrulla-X y devuélvelos a las manos de sus respectivos propietarios → esos jugadores juegan esos Aliados, ignorando su coste en recursos."},
  "47029": {"n":"Proteger y servir","t":"Alianza.\nInterrupción de Héroe: cuando vaya a colocarse cualquier cantidad de Amenaza sobre el Plan principal, agota un personaje X-Force y un personaje Patrulla-X → evita esa Amenaza y dale a cada uno de esos personajes una carta de Estado \"Duro\"."},
  "47030": {"t":"Arcade no puede sufrir Daño mientras haya un Plan secundario ¡Trampa! en juego.\nCuando se muestre esta carta: descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Plan secundario ¡Trampa! y muéstralo.","f":"\"¡Cuánto me alegro de que mis mercenarios os hayan convencido de venir!\""},
  "47031": {"n":"Bienvenidos a Mundo Asesino","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: el jugador que haya derrotado este Plan secundario sufre 2 de Daño.","f":"\"¡Estas atracciones son para morirse!\" —Arcade"},
  "47032": {"n":"Salón recreativo de Arcade","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: el jugador que haya derrotado este Plan secundario queda aturdido. Si ya estaba aturdido, descarta un Aliado o Mejora que controle."},
  "47033": {"n":"Laberintos de espejos","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: el jugador que haya derrotado este Plan secundario queda confundido. Si ya estaba confundido, coloca 2 de Amenaza sobre el Plan principal."},
  "47034": {"n":"Trampa elaborada","t":"Cuando se muestre esta carta: resuelve la capacidad \"Cuando se derrote esta carta\" de todos los Planes secundarios ¡Trampa! como si los hubieses derrotado tú. Si no se resuelve ninguna capacidad de este modo, descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Plan secundario ¡Trampa! y muéstralo.","f":"\"Mejor que sobre y no que falte.\" —Arcade"},
  "48001a": {"n":"Rondador Nocturno","t":"Teleportación rápida — Acción: gasta 1 recurso de cualquier tipo → devuelve a tu mano una copia de ¡Bamf! que este en tu pila de descartes. (Límite de una vez por fase.)","f":"\"¡Verzeihung! ¿Os importa que os corte el rollo?\""},
  "48001b": {"t":"Acción: busca en tu mazo una copia de ¡Bamf! y añádela a tu mano. (Límite de una vez por ronda.)","f":"\"Incluso en tiempos oscuros es posible hayar paz y belleza.\""},
  "48002": {"n":"Viajera Diurna","t":"Respuesta: después de que Viajera Diurna entre en juego, busca una copia de ¡Bamf! en tu mazo y en tu pila de descartes y vincúlala a un enemigo. Inflige 1 de Daño a todo enemigo que tenga vinculada una copia de ¡Bamf!"},
  "48003": {"n":"Capilla de Kurt","t":"Kurt Wagner recibe +1 REC.\nRespuesta de Alter ego: después de que realices una recuperación básica, agota la Capilla de Kurt y elige un jugador → ese jugador roba 1 carta."},
  "48004": {"n":"Sables de Kurt","t":"Cuenta como 2 cartas Restringidas.\nRondador Nocturno recibe +1 ATQ, +1 DEF y gana Represalia 1.","f":"\"Tengo dos espadas: ¡una para cada uno de vosotros!\""},
  "48005": {"n":"Cola prensil","t":"Puedes controlar 1 Mejora adicional que tenga la palabra clave Restringida.\nRecurso: agota la Cola prensil → genera un recurso [wild] para un Evento.","f":"La cola de Rondador Nocturno le permite efectuar ataques que nadie más puede."},
  "48006": {"n":"¡Bamf!","t":"Vincula esta carta a un enemigo. Máximo de 1 por enemigo.\nInterrupción de Héroe (defensa): cuando el enemigo vinculado ataque, descarta esta carta → declara a Rondador Nocturno como defensor sin agotarlo."},
  "48007": {"n":"Teleportación con puñetazo","t":"Acción de Héroe (ataque): inflige 3 de Daño a un enemigo. Inflige 3 de Daño a todo enemigo con una copia de ¡Bamf! vinculada.","f":"Rondador Nocturno puede enfrentarse a varios enemigos al mismo tiempo teleportándose tras cada golpe que propina."},
  "48008": {"n":"Teleportar y soltar","t":"Acción de Héroe (ataque): descarta una copia de ¡Bamf! de un enemigo → inflige 8 de Daño a ese enemigo y atúrdelo.","f":"\"Cuando se tiene el aspecto de un demonio, es tentador actuar como tal.\" —Rondador Nocturno"},
  "48009": {"n":"Reconocer el terreno","t":"Acción de Héroe (intervención): quita 3 de Amenaza de un Plan. Puedes descartar una copia de ¡Bamf! de tu mano para quitar 3 de Amenaza de otro Plan.","f":"\"Espera un momento, liebchen — me aseguraré de que no haya peligro.\" —Rondador Nocturno"},
  "48010": {"n":"Teleportarse lejos","t":"Acción: descarta una copia de ¡Bamf! de tu mano → cambia de identidad y prepara tu carta de Superhéroe.","f":"\"¡Volveré!\" —Rondador Nocturno"},
  "48011": {"n":"¡Cuidado, que voy!","t":"Respuesta de Héroe (defensa): después de que ¡Bamf! convierta Rondador Nocturno en el defensor de un ataque, devuelve esa copia de ¡Bamf! a tu mano. Inflige 3 de Daño al enemigo atacante."},
  "48012": {"n":"Pícara","t":"Acción: inflige 1 de Daño a otro personaje amigo → hasta el final de la ronda, Pícara gana todos los Rasgos de ese personaje y añade sus puntuaciones impresas de INT y ATQ a sus correspondientes atributos. (Límite de una vez por ronda.)"},
  "48013": {"n":"Estrella del Norte","t":"Interrupción: cuando se ponga boca arriba una carta de aumento durante un ataque, inflige 1 de Daño a Estrella del Norte → anula todos los iconos de Aumento ([boost]) que haya en esa carta.","f":"\"Los malos no dantanto miedo cuando uno se mueve más deprisa de lo que pueden parpadear.\""},
  "48014": {"n":"Cambio de suerte","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nRespuesta: después de que derrotes a un enemigo durante la fase del Villano, agota esta carta → roba 2 cartas."},
  "48015": {"n":"Bajo control","t":"Vincula esta carta a un Esbirro. Máximo de 1 por Esbirro.\nRespuesta: después de que un Héroe defienda contra un ataque del Esbirro vinculado y no sufra ningún Daño, inflige 4 de Daño al Esbirro vinculado."},
  "48016": {"n":"\"¡Ven a por mí, nene!\"","t":"Acción de Héroe: descarta cartas del mazo de Encuentros hasta que descartes un Esbirro. Pon en juego ese Esbirro enfrentado a ti → cura 3 de Daño a tu Superhéroe y dale a tu Superhéroe una carta de Estado \"Duro\"."},
  "48017": {"n":"Puñetazo potente","t":"Interrupción de Héroe (ataque/defensa): cuando un enemigo inicie un ataque, inflige 4 de Daño a ese enemigo.","f":"\"¿Te apetece un poco de jarabe de palo?\" —Gatasombra"},
  "48018": {"n":"Parada y respuesta","t":"Interrupción de Héroe (defensa): cuando tu Héroe defienda contra un ataque, recibe +2 DEF para ese ataque. Si el ataque no te inflige Daño, inflige 3 de Daño al enemigo atacante."},
  "48019": {"n":"El poder de la protección","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta de Protección (verde)."},
  "48020": {"n":"La increíble Patrulla-X","t":"Victoria 0.\nRespuesta: después de que un personaje Patrulla-X defienda contra un ataque enemigo y no sufra ningún Daño, quita 1 de Amenaza de este Plan.\nCuando se derrote esta carta: Aturde y confunde a cada enemigo que esté en juego."},
  "48021": {"n":"Gambito","t":"X es el número de iconos de Aumento ([boost]) que haya en la carta que hay debajo de Gambito.\nRespuesta: después de que Gambito entre en juego, mira las 3 primeras cartas del mazo de Encuentros y mete una debajo de su carta de modo que sólo asomen los aumentos."},
  "48022": {"t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo MUTANTE.\nRespuesta: después de que un Alter ego MUTANTE cambie a su identidad de Héroe, agota a Moira MacTaggert → el jugador que controla ese Héroe roba 1 carta."},
  "48023": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "48024": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "48025": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "48026": {"n":"Crisis de fe","t":"Dale esta carta al jugador que lleva a Kurt Wagner.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n• agota a Kurt Wagner → retira de la partida Crisis de fe.\n• Descarta todos los eventos Ataque y Defensa de tu mano. Descarta esta Obligación."},
  "48027": {"t":"Ataque veloz.\nNo pueden vincularse Mejoras a Azazel.\n[star] Aumento: dale Azazel al jugador que lleva a Kurt Wagner player como carta de Encuentro boca abajo."},
  "48028": {"n":"Dimensión Azufre","t":"Cuando se derrote esta carta: el jugador que haya derrotado este Plan localiza a Azazel y se lo queda como carta de Encuentro boca abajo.","f":"\"¡Todo esto podría ser tuyo si te unieras a mí!\"—Azazel"},
  "48029": {"n":"Espada de Azazel","t":"Vincula esta carta a Azazel. De no ser posible, Vincula esta carta al Villano.\n[star] Los ataques del enemigo vinculado ganan Penetrante.\nRespuesta de Héroe: después de que el enemigo vinculado te ataque, descarta 1 carta al azar de tu mano → descarta esta carta."},
  "48030": {"n":"Golpe sulfuroso","t":"Cuando se muestre esta carta (Alter ego): localiza a Azazel y muéstralo. Azazel ejecuta el plan.\nCuando se muestre esta carta (Héroe): localiza Azazel y muéstralo.","f":"Azazel se deleita frustando a sus oponentes teleportándose dentro y fuera del combate."},
  "48031": {"n":"Combinar fuerzas","t":"Alianza.\nAcción de Héroe: agota un personaje X-Force y un personaje Patrulla-X → derrota a un Esbirro que no sea Élite.","f":"\"¡Tío, has elegido a los mutantes equivocados en el peor día posible!\"—Cíclope"},
  "48032": {"n":"Diplomacia armada","t":"Alianza.\nAcción de Héroe (ataque/intervención): agota un personaje X-Force y un personaje Patrulla-X → quita X de Amenaza de entre todos los Planes que haya en juego e inflige X de Daño repartido entre todos los enemigos que haya en juego, siendo X la puntuación combinada de INT de los dos personajes agotados."},
  "48033": {"n":"La Banda Loca","t":"Respuesta obligada: después de que un Esbirro que no sea de Elite ejecute el Plan contra un jugador, dale ese Esbirro a ese jugador como carta de Encuentro boca abajo. Luego, si hay más de 1 jugador en la partida, pasa esa carta de Encuentro boca abajo al siguiente jugador."},
  "48034": {"n":"Reina de Corazones","t":"Cuando se muestre esta carta: busca el Plan secundario La Banda Loca en el mazo y la pila de descartes de Encuentros y muéstralo. Si ya está en juego, coge una carta de Encuentro boca abajo. (Baraja el mazo.)","f":"\"¡Que le corten la cabeza!\""},
  "48035": {"n":"Bufón","t":"Cuando se muestre esta carta: quedas confundido. Si ya estabas confundido, descarta un Apoyo que controles.","f":"\"¡Verás qué risa cuando te dé en los morros!\""},
  "48036": {"n":"Ejecutor","t":"Cuando se muestre esta carta: Ejecutorataca al personaje amigo que tenga menos Vida restante. Si este ataque derrota a un Aliado, retira ese Aliado de la partida.","f":"La Reina de Corazones repite una y otra vez su frase característica para mantenerlo ocupado."},
  "48037": {"n":"Simio","t":"Cuando se muestre esta carta: quedas aturdido. Si ya estabas aturdido, descarta una Mejora que controles.","f":"\"¡Jur, jur, jur!\""},
  "48038": {"n":"\"¡Que le corten la cabeza!\"","t":"Cuando se muestre esta carta: Cada Esbirro se activa contra el jugador al que esté enfrentado. Si no se activa ningún Esbirro de este modo, descarta cards de la parte superior del mazo de Encuentros hasta que se descarte un Esbirro y muéstralo.","f":"Prácticamente no dice nada más."},
  "49001a": {"t":"Atracción magnética — Acción: descarta cartas de la parte superior de tu mazo hasta que se descarte una carta Magnético → añade esa carta a tu mano. (Límite de una vez por ronda.)","f":"\"No tengo por qué justificar mis decisiones.\""},
  "49001b": {"t":"Superviviente — Respuesta: después de que cambies a esta identidad, coge las 3 primeras cartas de la parte superior de tu pila de descartes, añádelas a tu mazo y barájalo.","f":"\"Todo lo que he padecido, y todo cuanto he hecho, ha sido para la preservación de la especie mutante.\""},
  "49002": {"n":"Asteroide M","t":"Acción de Alter ego: agota el Asteroide M → coge la primera carta Magnético que haya en la parte superior de tu pila de descartes, añádela a tu mazo, barájalo y cura 1 de Daño a tu Superhéroe.","f":"\"Reconstruir mi hogar me costó un esfuerzo considerable. Procuremos no volver a destruirlo.\" —Magneto"},
  "49003": {"n":"Casco de Magneto","t":"Magneto gana Tesón.\nRecurso: agota el Casco de Magneto → genera un recurso [wild] para una carta Magnético.","f":"El Casco de Magneto le protege contra ataques telepáticos."},
  "49004": {"n":"Armadura de Magneto","t":"Respuesta: después de que resuelvas tu capacidad \"Atracción magnética\", si has descartado al menos 1 de los siguientes iconos de recurso:\n[mental] — Magneto recibe +1 INT esta ronda.\n[physical] — Magneto recibe +1 ATQ esta ronda.\n[energy] — Magneto recibe +1 DEF esta ronda."},
  "49005": {"n":"Capa de Magneto","t":"Magneto gana el rasgo Aéreo.\nRespuesta: después de que resuelvas tu capacidad \"Atracción magnética\", agota la Capa de Magneto → prepara a Magneto."},
  "49006": {"n":"Burbuja Magnética","t":"Magneto gana Represalia 1.\nInterrupción obligada: cuando vayas a sufrir cualquier cantidad de Daño, colócalo sobre esta carta. Luego, si hay al menos 6 de Daño sobre esta carta, descarta la Burbuja Magnética."},
  "49007": {"n":"Envoltura metálica","t":"Sólo identidad de Héroe. Vincula esta carta a un Esbirro que no sea de ÉLITE.\nEl Esbirro vinculado no puede activarse. Trata su texto de reglas impreso como si estuviese en blanco.","f":"\"¡Vuestro poder no puede compararse al del amo del magnetismo!\"—Magneto"},
  "49008": {"n":"Estallido electromagnético","t":"Acción de Héroe (intervención): quita 3 de Amenaza de un Plan. Si esto quita la última ficha de Amenaza de ese Plan, puedes descartar un Accesorio que tenga el encabezado \"Acción de Héroe\" o \"Respuesta de Héroe.\""},
  "49009": {"n":"Fragmentos de metal","t":"Acción de Héroe (ataque): inflige 7 de Daño a un enemigo. Si este ataque derrota a ese enemigo, ganas una carta de Estado \"Duro\".","f":"\"El camino para defender a los mutantes pasa por derrotar a nuestros enemigos.\" —Magneto"},
  "49010": {"n":"Proyectil Magnético","t":"Acción de Héroe: descarta un Esbirro que tenga vinculada Envoltura metálica → inflige 5 de Daño a un enemigo y atúrdelo.","f":"\"He oído vuestras amenazas, y aquí tenéis mi respuesta.\"—Magneto"},
  "49011": {"n":"El amo del magnetismo","f":"Las armas de fuego convencionales son inútiles contra el poder de Magneto."},
  "49012": {"t":"Respuesta: después de que M entre en juego, derrota a un Esbirro que tenga menos Vida restante que M.","f":"\"No me importa entrar como un elefante en una cacharrería.\""},
  "49013": {"n":"Chico Omega","t":"Respuesta: después de que Chico Omega entre en juego, elige una opción:\n• Gasta un recurso [energy] → inflige 1 de Daño a cada enemigo.\n• Gasta un recurso [mental] → quita 1 de Amenaza de cada Plan."},
  "49014": {"n":"Fénix","t":"Respuesta: después de que Fénix entre en juego, elige un Aliado Patrulla-X → prepara ese Aliado y cúrale 1 de Daño.","f":"\"Si te unes a la Patrulla-X, te unes a una familia. Con nosotros nunca estarás realmente solo.\""},
  "49015": {"n":"Cíclope","t":"Respuesta: después de que Cíclope entre en juego, elige un enemigo. Hasta el final de la fase, aumenta en 1 la cantidad de Daño que sufra ese enemigo con cada ataque.","f":"\"A mí, mi Patrulla-X!\""},
  "49016": {"n":"No sabe rendirse","t":"Juega esta carta sólo si tu Superhéroe tiene los rasgos X-Force o Patrulla-X. Máximo de 1 por jugador.\nAcción de Alter ego: descarta esta carta → devuelve a tu mano un Aliado X-Force o Patrulla-X que esté en tu pila de descartes."},
  "49017": {"n":"Confrontación","t":"Acción de Héroe: descarta cartas del mazo de Encuentros hasta que descartes un Esbirro. Pon en juego ese Esbirro enfrentado a ti → juega un Aliado desde tu mano, reduciendo su coste en 3.","f":"\"Vamos allá.\" —M"},
  "49018": {"n":"Sacrificio noble","t":"Acción de Héroe: descarta un Aliado que controles → cura tanto Daño a tu Héroe como la Vida impresa de ese Aliado y dale a tu Héroe una carta de Estado \"Duro\".","f":"\"No me esperéis. ¡Marchaos!\" —X-23"},
  "49019": {"n":"\"¡Tú puedes!\"","t":"Respuesta de Héroe: después de que agotes tu Héroe para realizar una intervención básica o un ataque básico, descarta un Aliado que controles → añade el correspondiente atributo de ese Aliado al atributo de tu Héroe para este uso. Prepara tu Héroe."},
  "49020": {"n":"Nuevos reclutas","t":"Victoria 0.\nJuega esta carta sólo si tu Superhéroe tiene el rasgo Patrulla-X.\nCuando se derrote esta carta: cada jugador elige 1 Aliado Nuevo que esté apartado y lo añade a su mano.","f":"El sueño de todo estudiante en el instituto Xavier es unirse a la Patrulla-X."},
  "49021": {"n":"Reina Blanca","t":"Juega esta carta sólo si tu Superhéroe tiene los rasgos X-Force o Patrulla-X.\nRespuesta: después de que la Reina Blanca entre en juego, descarta una carta de Estado de un personaje.","f":"\"Ay, cielo, para manipularte a ti apenas necesito poderes psiónicos.\""},
  "49022": {"n":"Enfrentarse al pasado","t":"Máximo de 1 por mazo.\nAcción de Héroe: busca tu Esbirro Archienemigo en el mazo de Encuentros, en su pila de descartes y en la zona apartada,y muéstralo → prepara a tu Héroe y roba 3 cartas. No puedes atacar al Villano en esta fase. Retira esta carta de la partida."},
  "49023": {"n":"Concentración eficaz","t":"Máximo de 1 por jugador.\nAcción de Héroe: agota Concentración eficaz → reduce en 1 el coste en recursos de la próxima carta Superpoder que juegues en este turno."},
  "49024": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "49025": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "49026": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "49027": {"n":"Viejas desavenencias","t":"Dale esta carta al jugador que lleva a Erik Lehnsherr.\nRespuesta obligada: después de que uses tu capacidad \"Atracción magnética\", sufre 1 de Daño por cada carta que hayas descartado al usarla.\nAcción de Alter ego: agota a Erik Lehnsherr → descarta Viejas desavenencias."},
  "49028": {"n":"Éxodo","t":"Dureza. Infame. Tesón.\n[star] Respuesta obligada: después de que Éxodo te ataque, descarta tantas cartas de la parte superior de tu mazo como su puntuación total de ATQ.\n(Esbirro Archienemigo de Magneto.)"},
  "49029": {"n":"Mártir mutante","t":"Cuando se derrote esta carta: el jugador que la ha derrotado descarta las 9 primeras cartas de su mazo.","f":"Los antiguos Acólitos de Magneto se sintieron traicionados por su líder cuando cambió de parecer sobre la coexistencia pacífica de mutantes y humanos."},
  "49030": {"t":"Guardia.\nCuando se derrote esta carta: el jugador que la ha derrotado descarta las 4 primeras cartas de su mazo.\n[star] Aumento: descarta las 4 primeras cartas de tu mazo."},
  "49031": {"n":"Frenesí","t":"Ataque veloz.\n[star] Respuesta obligada: después de que Frenesí te ataque, descarta las 2 primeras cartas de tu mazo.\n[star] Aumento: descarta las 4 primeras cartas de tu mazo."},
  "49032": {"n":"Acólito furioso","t":"Cuando se muestre esta carta: cada Esbirro Acólito que esté enfrentado a un jugador se activa contra ese jugador. Si no se activa nigún Esbirro de este modo, descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Esbirro Acólito. Muestra ese Esbirro."},
  "49033": {"n":"Tensión","t":"Enlazada (Nuevo reclutas).\nSi tienes los rasgos Mutante o Patrulla-X, Tensión recibe +1 ATQ y no se cuenta de cara a tu limite de Aliados.","f":"\"¡Toca a mis amigos y te sacudo con diez mil voltios!\""},
  "49034": {"n":"Camaleón","t":"Enlazada (Nuevo reclutas).\nSi tienes los rasgos Mutante o Patrulla-X, Camaleón recibe +1 INT y no se cuenta de cara a tu limite de Aliados.","f":"\"La infancia es muy dura cuando uno parece un monstruo.\""},
  "49035": {"n":"Bling","t":"Enlazada (Nuevo reclutas).\nSi tienes los rasgos Mutante o Patrulla-X, Bling gana Dureza y no se cuenta de cara a tu limite de Aliados.","f":"\"¡Este instituto es penoso!\""},
  "49036": {"t":"Enlazada (Nuevo reclutas).\nSi tienes los rasgos Mutante o Patrulla-X, Indra recibe +2 de Vida y no se cuenta de cara a tu limite de Aliados.","f":"\"He visto las atrocidades que se han cometido con los mutantes.¡Eso se acabó!\""},
  "49037": {"n":"Hijos del átomo","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nCada personaje Factor-X, X-Force y Patrulla-X que controles gana los rasgos Factor-X, X-Force y Patrulla-X."},
  "49038": {"t":"Dureza. Infame.\nRespuesta obligada: después de que se ataque a Sebastian Shaw, dale una carta de aumento boca abajo. No se le puede volver a atacar en esta fase.","f":"\"¡No vuelvas a levantarle la mano a tus superiores, patán!\""},
  "49039": {"t":"Ataque veloz. Infame.\nLos Aliados no pueden atacar a Selene\n[star] Aumento: descarta un Aliado que controles.","f":"\"¡Niña estúpida! Incontables miles han caído al fuego en mi nombre.\""},
  "49040": {"n":"Peón del Fuego infernal","t":"Guardia. Oleada. Patrulla.\n(Mientras un Esbirro con la palabra clave Patrulla esté enfrentado a ti, no podrás intervenir en el Plan principal.)\n[star] Aumento: pon en juego el Peón del Fuego infernal enfrentado a ti."},
  "49041": {"n":"El Círculo Interno","t":"Cuando se muestre esta carta: coloca 2 de Amenaza adicional sobre esta carta por cada carta Fuego infernal que haya en juego.","f":"El círculo interno del Club Fuego infernal utiliza su fortuna y su poder para mover los hilos en la sombra y decidir el destino de los mutantes."},
  "49042": {"n":"Poder y decadencia","t":"Cuando se muestre esta carta: dale al Villano una carta de Estado \"Duro\". Dale esta carta al Villano como una carta de aumento boca abajo.\n[star] Aumento: después de esta activación, el enemigo activado vuelve a activarse contra ti. No le des una carta de aumento para esa activación."},
  "50001a": {"t":"Todos los Aliados que controles ganan el rasgo S.H.I.E.L.D..\nReasignación — Acción: traslada 1 contador genérico desde un Apoyo S.H.I.E.L.D. hasta otro Apoyo S.H.I.E.L.D.. (Límite de una vez por ronda.)"},
  "50001b": {"t":"Puedes incluir en tu mazo la cantidad máxima de copias de 3 Apoyos S.H.I.E.L.D. de otros aspectos que no sean el que has elegido.\nAcción: agota a Maria Hill → busca en tu mazo un Apoyo S.H.I.E.L.D. y añádelo a tu mano."},
  "50002": {"n":"Nick Furia","t":"[star] Respuesta: después de que Nick Furia use un atributo básico, coloca 1 contador genérico sobre un Apoyo S.H.I.E.L.D..","f":"\"He asignado el caso a mi mejor agente.\" —Maria Hill"},
  "50003": {"n":"Orden de búsqueda","t":"Acción de Héroe: por cada Apoyo S.H.I.E.L.D. que controles, elige una opción:\n• Quita 1 de Amenaza de un Plan.\n• Inflige 1 de Daño a un enemigo."},
  "50004": {"n":"Paso ligero","t":"Acción: prepara cualquier cantidad de Apoyos S.H.I.E.L.D. cuyo coste impreso combinado sume 6 o menos.","f":"\"¡Quiero al sospechoso bajo custodia para ayer!\" —Maria Hill"},
  "50005": {"n":"Refuerzos","t":"Acción: elige cualquier cantidad de Apoyos S.H.I.E.L.D. cuyo coste impreso combinado sume 6 o menos. Coloca 1 contador genérico sobre cada uno de esos Apoyos.","f":"\"Tenemos órdenes de la directora. ¡Andando!\" —Dum Dum Dugan"},
  "50006": {"n":"Una difícil decisión","t":"Acción de Héroe: descarta un Apoyo S.H.I.E.L.D. que controles → inflige X de Daño a cada enemigo, donde X el coste impreso del Apoyo descartado.","f":"\"A veces todo se reducea las estadísticas. Si no hago nada, muere más gente que cuando lo hago.\" —Maria Hill"},
  "50007": {"n":"Fondos extraordinarios","t":"Respuesta: después de que gastes esta carta para pagar por un Apoyo S.H.I.E.L.D., coloca 1 contador genérico sobre ese Apoyo después de que entre en juego."},
  "50008": {"n":"Personal de apoyo","t":"Usos (3 contadores de Personal).\nRecurso: agota el Personal de apoyo y quítale 1 contador de Personal → genera un recurso [wild] para un jugador cuyo Superhéroe tenga el rasgo S.H.I.E.L.D.."},
  "50009": {"n":"El Ilíada","t":"Usos (3 contadores de Misión).\nAcción: agota El Ilíada y quítale 1 contador de Misión → elige una opción:\n• Inflige 5 de Daño a un enemigo.\n• Quita 4 de Amenaza de un Plan.\n• Cura 3 de Daño a un Superhéroe."},
  "50010": {"n":"Señuelo dotado de vida","t":"Interrupción: cuando un enemigo te ataque, descarta el Señuelo dotado de vida → evita todo el Daño de ese ataque.","f":"\"Cuando se tiene un oficio tan peligroso como el mío, conviene tomar precauciones.\" —Maria Hill"},
  "50011": {"n":"Directora de S.H.I.E.L.D.","t":"Acción: agota Directora de S.H.I.E.L.D. → coloca 1 contador genérico sobre un Apoyo de S.H.I.E.L.D..","f":"\"No tenéis por qué estar de acuerdo con mis órdenes. Limitaos a cumplirlas.\" —Maria Hill"},
  "50012": {"t":"Respuesta: después de que Victoria Hand entre en juego, prepara un Apoyo S.H.I.E.L.D..","f":"\"¡Más vale que esto tenga una prima de riesgo!\""},
  "50013": {"n":"Tirachinas","t":"Acción: gasta un recurso [energy] → pon en juego a Tirachinas desde tu mano controlada por cualquier jugador. Al final de la fase, si Tirachinas aún sigue en juego, devuélvela a tu mano."},
  "50014": {"n":"Apoyo organizativo","t":"Interrupción: cuando gastes esta carta, agota hasta 3 Aliados o Apoyos que controles y que tengan un rasgo en común con tu Superhéroe → genera los recursos impresos en cada carta que hayas agotado de este modo."},
  "50015": {"n":"Agentes de S.H.I.E.L.D.","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 carta de Grupo por jugador.\nSi todos tus personajes tienen el rasgo S.H.I.E.L.D., esta carta gana: \"Interrupción: cuando muestres una carta de Encuentro, agota esta carta → anula los efectos de esa carta y descártala. Luego muestra otra carta del mazo de Encuentros.\""},
  "50016": {"n":"Grupo de mando","t":"Usos (3 contadores de Mando).\nAcción: agota el Grupo de mando y quítale 1 contador de Mando → prepara un Aliado."},
  "50017": {"n":"El Circe","t":"Usos (2 contadores de Despliegue).\nAcción: agota El Circe, quítale 1 contador de Despliegue y elige un jugador → ese jugador pone en juego un Aliado desde su mano."},
  "50018": {"n":"El Belerofonte","t":"Usos (3 contadores de Misil).\nAcción: agota El Belerofonte, quítale 1 contador de Misil y elige un jugador → inflige 3 de Daño al Villano y a cada Esbirro que esté enfrentado a ese jugador, descartando primero todas las cartas de Estado \"Duro\" que tengan esos enemigos."},
  "50019": {"n":"El Douglass","t":"Usos (3 contadores de Operación).\nAcción: agota El Douglass y quítale 1 contador de Operación → quita 2 de Amenaza de cada Plan, ignorando los iconos de Crisis ([crisis]) que haya en juego."},
  "50020": {"n":"El Pericles","t":"Usos (2 contadores de Suministros).\nAcción: agota El Pericles y quítale 1 contador de Suministros → dale a un Héroe o Villano una carta de Estado de tu elección. Dale a un Aliado o Esbirro una carta de Estado de tu elección."},
  "50021": {"t":"Interrupción: cuando uses uno de los atributos básicos de Dum Dum Dugan, agota hasta 3 cartas S.H.I.E.L.D. que controles. Por cada carta que agotes de este modo, Dum Dum Dugan suma +1 a ese atributo para este uso."},
  "50022": {"t":"Grant Ward no puede defender.\nRespuesta obligada: después de que muestres una carta de Perfidia, puedes gastar un recurso [mental]. Si no lo haces, sufres tanto Daño como el ATQ de Grant Ward y retiras de la partida a Grant Ward."},
  "50023": {"t":"[star] Respuesta: después de que Melinda May use un atributo básico, mira la primera carta de la parte superior del mazo de Encuentros. Puedes descartar esa carta.","f":"\"No vuelvas a llamarme \"La caballeria\".\""},
  "50024": {"n":"Superespías","t":"Equipo (Maria Hill y Nick Furia). Máximo de 1 por mazo.\nAcción de Héroe: coloca un total de 3 contadores genéricos o fichas de Amenaza sobre Apoyos o Mejoras de identidad operativa de S.H.I.E.L.D. en cualquier combinación."},
  "50025": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "50026": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "50027": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "50028": {"n":"Organización de tapadera","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nInterrupción: cuando el efecto de una carta de Encuentro vaya a descartar una carta que controles, descarta la Organización de tapadera en vez de descartar esa carta."},
  "50029": {"n":"Conferencia de prensa","t":"Dale esta carta al jugador que lleva a Maria Hill.\nRespuesta obligada: después de que termine la fase de los Jugadores, quita 1 contador genérico de cada Apoyo que controles.\nAcción de Alter ego: agota tu Superhéroe → descarta esta carta."},
  "50030": {"n":"Controlador","t":"[star] Respuesta obligada: después de que el Controlador se active contra ti, quita 1 contador genérico de un Apoyo. Si está en juego Inocentes controlados, pon en juego la primera carta de tu mazo boca abajo y enfrentada a ti como Esbirro Controlado."},
  "50031": {"n":"Ejército de personas controladas","t":"Cuando se muestre esta carta: localiza el Entorno Inocentes controlados y ponlo en juego.\nCuando se derrote esta carta: descarta cada Esbirro Controlado. Coloca 1 contador genérico sobre un Apoyo por cada Esbirro que se haya descartado de este modo."},
  "50032": {"n":"Inocentes controlados","t":"Cada Esbirro Controlado que esté enfrentado boca abajo a un jugador tiene PLA básico de 1, un ATQ básico de 1 y una Vida básica de 1.\nRespuesta obligada: después de que un Esbirro Controlado sea derrotado, coloca esa carta en la pila de descartes de su propietario y coloca 1 de Amenaza sobre el Plan principal."},
  "50033": {"n":"Discos diabólicos","t":"Oleada.\nCuando se muestre esta carta: quita 1 contador genérico de un Apoyo. Si está en juego Inocentes controlados, pon en juego la primera carta de tu mazo boca abajo y enfrentada a ti como Esbirro Controlado."},
  "50034a": {"n":"Nick Furia","t":"[star] Recabar información — Respuesta: después de que Nick Furia realice una intervención básica, coloca 1 de Amenaza sobre tu Mejora de identidad operativa.\nSalir al descubierto — Interrupción obligada: cuando ataques, cambia a tu identidad operativa de Asalto."},
  "50034b": {"n":"Nick Furia","t":"Ponerse el traje — Preparación: pon en juego tu Mejora de identidad operativa con la cara de Asalto boca arriba.\nInfiltrarse — Acción: cambia a tu identidad operativa de Sigilo."},
  "50035a": {"n":"Asalto","t":"Identidad operativa. Permanente.\nInterrupción: cuando ataques, quita hasta 3 de Amenaza de esta carta → este ataque inflige 1 de Daño adicional por cada ficha de Amenaza retirada de este modo."},
  "50035b": {"n":"Sigilo","t":"Identidad operativa. Permanente.\nInterrupción obligada (Héroe): cuando un enemigo vaya a atacarte, en vez de eso ejecuta el Plan. Coloca 1 de Amenaza de esa activación sobre esta carta en lugar del Plan principal si hay 5 de Amenaza o menos sobre esta carta."},
  "50036": {"t":"[star] Interrupción: cuando Maria Hill intervenga, coloca la Amenaza retirada sobre tu Mejora de identidad operativa.","f":"\"¡Eso sí que es una salida espectacular!\""},
  "50037": {"n":"Fuego concentrado","t":"Acción de Héroe (ataque): inflige 4 de Daño a un enemigo. Este ataque gana A distancia. Si este ataque derrota a un enemigo, elige una opción:\n• Coloca tanta Amenaza sobre tu Mejora de identidad operativa como el valor impreso de PLA de ese enemigo.\n• cambia a tu identidad operativa de Sigilo."},
  "50038": {"n":"Vigilancia encubierta","t":"Acción de Héroe (intervención): quita 2 de Amenaza de un Plan. Si tienes adoptada tu identidad operativa de Sigilo, puedes colocar esa Amenaza sobre tu Mejora de identidad operativa. De no ser así, puedes cambiar a tu identidad operativa de Sigilo."},
  "50039": {"n":"Acribillar","t":"Acción de Héroe (ataque): elige un jugador. Inflige 3 de Daño al Villano y a cada Esbirro que esté enfrentado a ese jugador. Este ataque gana A distancia.","f":"\"¡Comed láser!\" —Nick Furia"},
  "50040": {"n":"Coche volador de Furia","t":"Acción de Héroe: agota el Coche volador de Furia y quita 1 de Amenaza de tu Mejora de identidad operativa → prepara a Nick Furia. Gana el rasgo Aéreo hasta el final de la ronda.","f":"\"Este trabajo tiene sus privilegios.\" —Nick Furia"},
  "50041": {"n":"Piso franco nº221","t":"Acción de Alter ego: agota el Piso franco nº221 → elige una opción:\n• Cura 2 de Daño a Nick Furia.\n• Coloca 1 de Amenaza sobre tu Mejora de identidad operativa."},
  "50042": {"n":"Escudo electromagnético","t":"Interrupción (defensa): cuando vayas a sufrir cualquier cantidad de Daño a consecuencia de un ataque, descarta el Escudo electromagnético → evita todo ese Daño."},
  "50043": {"n":"Parche cámara","t":"Interrupción de Héroe: cuando vaya a colocarse cualquier cantidad de Amenaza sobre el Plan principal, descarta el Parche cámara → en vez de eso coloca hasta 3 de esa Amenaza sobre tu Mejora de identidad operativa."},
  "50044": {"n":"Reloj de Furia","t":"Recurso: agota el Reloj de Furia y quita hasta 2 de Amenaza de tu Mejora de identidad operativa → genera un recurso [mental] por cada ficha de Amenaza que hayas quitado de este modo."},
  "50045": {"n":"Análisis de información","t":"Interrupción: cuando muestres una Perfidia, descarta Análisis de información y quita 1 de Amenaza de tu Mejora de identidad operativa → anula los efectos de esa Perfidia y descártala."},
  "50046": {"n":"Agente secreto","t":"Respuesta de Héroe: después de que resuelvas la capacidad de una carta de Planificación que controles, traslada 1 de Amenaza desde un Plan hasta tu Mejora de identidad operativa.","f":"\"Soy un hombre con una vida llena de peligros.\" —Nick Furia"},
  "50047": {"n":"Agente Coulson","t":"Respuesta: después de que el Agente Coulson entre en juego, busca una carta de PLANIFICACIÓN en tu mazo y en tu pila de descartes y añádela a tu mano. Baraja tu mazo.","f":"\"Soy el tío que tiene un plan.\""},
  "50048": {"n":"Temblor","t":"Respuesta: después de que un Esbirro ejecute el Plan, agota a Temblor → inflige 2 de Daño a ese Esbirro.","f":"\"¡Haré que todo el edificio os caiga encima!\""},
  "50049": {"n":"Logística internacional","t":"Acción: agota 1 carta S.H.I.E.L.D. que controles → mira las 4 primeras cartas de un mazo de Jugador o del mazo de Encuentros. Descarta cualquier cantidad de esas cartas y coloca el resto en la parte superior o inferior de ese mazo en el orden que prefieras."},
  "50050": {"n":"Confidente","t":"Máximo de 1 por jugador.\nInterrupción: cuando un Esbirro ejecute el Plan, descarta al Confidente → esta activación quita Amenaza en vez de colocarla.","f":"\"¿Cuánto vale esa información para ti, Coulson?\" —Supervisor"},
  "50051": {"n":"Datos de inteligencia","t":"Máximo de 1 por jugador.\nRespuesta: después de que un jugador reciba una carta de Encuentro, descarta Datos de inteligencia → mira todas las cartas de Encuentro que se hayan repartido a cada jugador y la primera carta de la parte superior del mazo de Encuentros. Puedes intercambiara cualquier cantidad de esas cartas."},
  "50052": {"n":"Polvo de prisma","t":"Máximo de 1 por jugador.\nRespuesta de Héroe (ataque): después de que entre en juego un Esbirro, descarta el Polvo de prisma → confunde a ese Esbirro e inflígele 2 de Daño."},
  "50053": {"n":"Bajo vigilancia","t":"Vincula esta carta al Plan principal. Máximo de 1 por Plan.\nEl umbral de Amenaza del Plan vinculado se incrementa en 4."},
  "50054": {"n":"Nick Furia (Padre)","t":"Respuesta obligada: después de que Nick Furia (Padre) entre en juego, elige una opción: quita 3 de Amenaza de un Plan, roba 2 cartas o dale una carta de Estado \"Duro\" a un personaje S.H.I.E.L.D.. Al final de la ronda, si Nick Furia (Padre) aún sigue en juego, descártalo."},
  "50055": {"t":"El coste para jugar a Jemma Simmons se reduce en 2 si tu Superhéroe tiene el rasgo S.H.I.E.L.D..\nRecurso: agota a Jemma Simmons → genera un recurso [mental] para una carta Tecnología."},
  "50056": {"t":"El coste para jugar a Leo Fitz se reduce en 2 si tu Superhéroe tiene el rasgo S.H.I.E.L.D..\nAcción de Alter ego: agota a Leo Fitz → busca en tu mazo una carta Tecnología y añádela a tu mano. (Baraja el mazo.)"},
  "50057": {"n":"Destructor aéreo","t":"Respuesta: después de que juegues una carta S.H.I.E.L.D., agota el Destructor aéreo → inflige 2 de Daño a un enemigo.","f":"\"No tenemos por costumbre desplegar destructores aéreos. Pero cuando lo hacemos, ten por seguro que la situación se ha puesto seria.\" —Nick Furia"},
  "50058": {"n":"Plan ensayado","t":"Máximo de 1 por jugador.\nRespuesta: después de que descartes una carta de Planificación que controles, descarta Plan ensayado → devuelve esa carta a tu mano desde tu pila de descartes."},
  "50059": {"n":"Descubierto","t":"Dale esta carta al jugador que lleva a Nick Furia.\nCuando se muestre esta carta: cambia a tu identidad operativa de Asalto. Si no hay Amenaza sobre tu Mejora de identidad operativa, esta carta gana Oleada. De no ser así, elige entre sufrir 1 de Daño por cada ficha de Amenaza que haya sobre tu Mejora de identidad operativa o bien quitar toda la Amenaza que haya sobre tu Mejora de identidad operativa. En cualquier caso, descarta esta carta."},
  "50060": {"n":"Orión","t":"Dureza.\nOrión puede tener cualquier cantidad de cartas de Estado \"Duro\".\nRespuesta obligada: después de que Orión sufra cualquier cantidad de Daño, dale una carta de Estado \"Duro\".\n(Esbirro Archienemigo de Nick Furia.)"},
  "50061": {"n":"Adquirir la fórmula del infinito","t":"Respuesta obligada: después de que Nick Furia sufra cualquier cantidad de Daño, dale a Orión una carta de Estado \"Duro\". Si Orión no está en juego, localízalo y ponlo en juego enfrentado al jugador que lleva a Nick Furia."},
  "50062": {"n":"Soldado de Leviatán","t":"Dureza.\n[star] Respuesta obligada: después de que el Soldado de Leviatán ejecute el Plan, inflige 1 de Daño al Superhéroe del jugador al que está enfrentado.","f":"Leviatán es una antigua rama clandestina del KGB que se ha idependizado y planea dominar el mundo."},
  "50063": {"n":"Cámaras de hibernación","t":"Cuando se muestre esta carta: busca un Esbirro Leviatán en el mazo y la pila de descartes de Encuentros y ponlo en juego enfrentado a ti. (Baraja el mazo.) De no ser así, sufres 2 de Daño.\n[star] Aumento: sufres 1 de Daño."},
  "50064": {"n":"Viuda Negra","t":"Interrupción obligada: cuando un personaje que controles ataque a la Viuda Negra, quita 1 de Amenaza del Plan principal (ignorando los iconos de Crisis que haya en juego) → descarta la primera carta del mazo de Encuentros y resuelve la capacidad de \"Planificación\" que tenga esa carta."},
  "50065": {"n":"Viuda Negra","t":"Cuando se muestre esta carta: coloca 2[per_hero] de Amenaza sobre el Plan principal.\nInterrupción obligada: cuando un personaje que controles ataque a la Viuda Negra, quita 1 de Amenaza del Plan principal → descarta la primera carta del mazo de Encuentros y resuelve la capacidad de \"Planificación\" que tenga esa carta."},
  "50066": {"n":"Viuda Negra","t":"Cuando se muestre esta carta: coloca 3[per_hero] de Amenaza sobre el Plan principal.\nInterrupción obligada: cuando un personaje que controles ataque a la Viuda Negra, quita 1 de Amenaza del Plan principal → descarta la primera carta del mazo de Encuentros y resuelve la capacidad de \"Planificación\" que tenga esa carta."},
  "50067a": {"n":"La red de la Viuda","t":"Contenido: Viuda Negra (I) y Viuda Negra (II). (Viuda Negra (II) y Viuda Negra (III) para jugar en modo Experto.) Conjuntos de Encuentros de la Viuda Negra y Normal. Dos conjuntos de Encuentros modulares (Secuestros de I.M.A. y Ciencia del I.M.A.).\nPreparación: cada jugador busca un Esbirro en el mazo de Encuentros y lo pone en juego enfrentado a él. (Baraja el mazo.)"},
  "50067b": {"n":"La red de la Viuda","t":"X es igual al número de la etapa de la Viuda Negra.\nSi se completa esta etapa, los jugadores pierden la partida.","f":"El rastro de la especialista de S.H.I.E.L.D. desaparecida conduce hasta una estación de metro en desuso donde halláis la base de operaciones de sus secuestradores."},
  "50068": {"n":"Brazaletes de la Viuda Negra","t":"Vincula esta carta a la Viuda Negra.\nLa Viuda Negra gana Represalia 1.\nRespuesta de Héroe: después de que un personaje que controles ataque a la Viuda Negra, si no se ha resuelto ninguna capacidad de \"Planificación\", descarta esta carta (después de resolver la palabra clave Represalia).\nPlanificación: vincula esta carta a la Viuda Negra."},
  "50069": {"n":"Gancho de escalada","t":"Vincula esta carta a la Viuda Negra.\nInterrupción obligada: cuando un jugador juegue una carta de Evento, anula sus efectos y descártala. Luego descarta esta carta.\nPlanificación: descarta 1 carta de Evento de tu mano."},
  "50070": {"n":"Gafas de visión nocturna","t":"Vincula esta carta a la Viuda Negra.\nCada carta de Encuentro que no tenga impresa una capacidad de \"Planificación\" gana \"Planificación: evita todo el Daño de este ataque. Luego descarta las Gafas de visión nocturna.\"\nPlanificación: vincula esta carta a la Viuda Negra."},
  "50071": {"n":"Red paralizante","t":"Vincula esta carta a tu Superhéroe.\nEl personaje vinculado no puede atacar.\nAcción de Héroe: agota un personaje que controles → descarta esta carta. Cualquier jugador puede aplicar esta capacidad.\nPlanificación: después de este ataque, vincula esta carta al personaje atacante."},
  "50072": {"n":"Comando de I.M.A.","t":"Ataque veloz.\nPlanificación: después de este ataque, pon en juego este Esbirro enfrentado a ti."},
  "50073": {"n":"Secuaz de I.M.A.","t":"Guardia.\nPlanificación: pon en juego este Esbirro enfrentado a ti. Luego resuelve este ataque contra el Secuaz de I.M.A. en su lugar."},
  "50074": {"n":"Defensas automatizadas","t":"Complicación 1[per_hero].\nCada carta de Encuentro que no tenga impresa una capacidad de \"Planificación\" gana \"Planificación: inflige 1 de Daño al personaje atacante.\""},
  "50075": {"n":"Destrucción de pruebas","t":"Complicación 2[per_hero].\nTodas las demás cartas de Encuentro ganan Incitar 1. (Cuando se muestre esta carta, coloca 1 de Amenaza sobre el Plan principal.)"},
  "50076": {"n":"Combate acrobático","t":"Cuando se muestre esta carta: si tienes adoptada la identidad de tu Alter ego, cambia a tu identidad de Héroe. La Viuda Negra te ataca. Dale una carta de aumento adicional para este ataque.\nPlanificación: evita todo el Daño de este ataque. En modo Experto, inflige esa misma cantidad de Daño al personaje atacante."},
  "50077": {"n":"Operación encubierta","t":"Cuando se muestre esta carta: quedas confundido. La Viuda Negra ejecuta el Plan.\nPlanificación: coloca 1 de Amenaza sobre cada Plan."},
  "50078": {"n":"Danza mortal","t":"Cuando se muestre esta carta: inflige 1 de Daño a un personaje que controles. Inflige 2 de Daño a otro personaje que controles. Inflige 3 de Daño a un tercer personaje que controles.\nPlanificación: Inflige 1 de Daño a cada personaje que controles."},
  "50079": {"n":"Picadura de la Viuda","t":"Cuando se muestre esta carta: quedas aturdido. Sufres 1 de Daño (2 de Daño si ya estabas aturdido).\nPlanificación: después de este ataque, aturde al personaje atacante."},
  "50080": {"n":"Secuestrador de I.M.A.","t":"Cuando se muestre esta carta: mete debajo de Rapto de superhumanos al Aliado que controles que tenga más Vida restante. De no ser posible, coloca 2 de Amenaza sobre Rapto de superhumanos. Si Rapto de superhumanos no está en juego, localízalo y ponlo en juego."},
  "50081": {"n":"Rapto de superhumanos","t":"Oleada.\nInterrupción obligada: cuando un Aliado abandone el juego, mételo debajo de esta carta y coloca encima de ella tanta Amenaza como el coste del Aliado. Luego coloca 1 ficha de Aceleración sobre esta carta.\nCuando se derrote esta carta: pon en juego controlado por su propietario cada Aliado que esté metido debajo de esta carta."},
  "50082": {"n":"¡Te cacé!","t":"Cuando se muestre esta carta: Si Rapto de superhumanos no está en juego, localízalo y ponlo en juego. Descarta cartas de la parte superior de tu mazo hasta que se descarte un Aliado y mételo debajo de Rapto de superhumanos. Coloca sobre Rapto de superhumanos tanta Amenaza como el coste de ese Aliado y también 1 ficha de Aceleración."},
  "50083": {"n":"Científico de I.M.A.","t":"Oleada. Vulnerable. (Descarta este personaje si queda aturdido o confundido.)\nMientras el jugador enfrentado esté enfrentado a otro Esbirro, no se podrá atacar al Científico de I.M.A."},
  "50084": {"n":"Soldado de I.M.A.","t":"Patrulla.\nCuando se muestre esta carta: localiza al Científico de I.M.A. y ponlo en juego enfrentado a ti. (Si ya está en juego, se enfrenta a ti.) Si el Científico de I.M.A. no ha entrado en juego de este modo, coloca 1 de Amenaza sobre el Plan principal."},
  "50085": {"n":"Ciencia insólita","t":"Complicación 2[per_hero].\nCada Esbirro de I.M.A. gana 1 icono de Aceleración ([acceleration]).","f":"Los brillantes y despiadados miembros de Ideas Mecánicas Avanzadas, llamados despectivamente \"apicultores,\" aspiran a dominar el mundo valiéndose de su poder tecnológico."},
  "50086a": {"t":"[star] Respuesta obligada: después de que Batroc ataque, coloca 1 de Amenaza sobre Nivel de alerta.\nInterrupción obligada: cuando Batroc vaya a ser derrotado, en vez de eso restablece su Vida a 8. Luego quita 6 de Amenaza del Plan principal."},
  "50086b": {"t":"[star] Respuesta obligada: después de que Batroc ataque, coloca 1 de Amenaza sobre Nivel de alerta.\nInterrupción obligada: cuando Batroc vaya a ser derrotado, en vez de eso restablece su Vida a 12. Luego quita 6 de Amenaza del Plan principal."},
  "50087a": {"n":"Infiltrarse en la embajada de I.M.A.","t":"Contenido: Batroc (A). (Batroc (B) para jugar en modo Experto.) Conjuntos de Encuentros de Batroc y Normal. Dos conjuntos de Encuentros modulares (Ciencia del I.M.A. y La brigada de Batroc).\nPreparación: aparta a un lado todas las cartas de Aliado de Prisionero liberado. Pon en juego el Entorno Nivel de alerta, con la cara de Bajo boca arriba. En modo Experto, coloca 2[per_hero] de Amenaza sobre Nivel de alerta."},
  "50087b": {"n":"Infiltrarse en la embajada de I.M.A.","t":"Interrupción obligada: cuando se quite la última ficha de Amenaza de este Plan, avanza a la etapa 2A (los jugadores ganan avanzando el Plan).\nSi se completa esta etapa, los jugadores pierden la partida.","f":"Os coláis discretamente en la embajada de la isla de I.M.A. en busca de Sarah Garza, la especialista de S.H.I.E.L.D. secuestrada. Allí os topáis cara a cara con el mercenario conocido como Batroc el Saltador."},
  "50088a": {"n":"Localizar a la persona desaparecida","f":"Una vez dentro de la embajada, empezáis a buscar a Garza. Encontráis varias celdas de detención en el sótano del edificio. Con suerte, la informática secuestrada estará en una de ellas."},
  "50088b": {"n":"Localizar a la persona desaparecida","t":"Interrupción obligada: cuando se quite la última ficha de Amenaza de este Plan, pon en juego (agotado y controlado por cualquier jugador) 1 Aliado Prisionero liberado que esté apartado. Los jugadores pueden avanzar a la etapa 3A. Si no avanzan, coloca 3[per_hero] de Amenaza sobre esta carta. (Los jugadores ganan la partida avanzando, pero necesitarán al menos 1 Prisionero liberado para sobrevivir.)\nSi se completa esta etapa, los jugadores pierden la partida."},
  "50089a": {"n":"Sacar a los prisioneros","t":"Cuando se muestre esta carta: si Nivel de alerta tiene boca arriba la cara Alto, dale a cada jugador 1 carta de Encuentro boca abajo. De no ser así, quita toda la Amenaza que haya sobre Nivel de alerta y dale la vuelta para poner boca arriba su cara Alto. En cualquier caso, en modo Experto, coloca 2[per_hero] de Amenaza sobre Nivel de alerta..","f":"No habéis encontrado a Garza, pero sí a otros civiles capturados. Tenéis que ponerlos a salvo."},
  "50089b": {"n":"Sacar a los prisioneros","t":"En modo Experto, cada Esbirro gana Ataque veloz.\nInterrupción obligada: cuando un enemigo ataque, en vez de eso ataca a un Prisionero liberado.\nSi no hay Amenaza sobre esta carta, los jugadores ganan la partida.\nSi se completa esta etapa o si no hay ningún Aliado Prisionero liberado en juego, los jugadores pierden la partida."},
  "50090a": {"n":"Nivel de alerta","t":"Si hay al menos 4[per_hero] de Amenaza sobre esta carta, quítale toda la Amenaza y dale la vuelta.\nRespuesta obligada: después de que un personaje sea derrotado por cualquier motivo que no sea Daño derivado, coloca 1 de Amenaza sobre esta carta.\nAcción de Héroe: gasta 1 recurso de cualquier tipo → quita 1 de Amenaza de esta carta."},
  "50090b": {"n":"Nivel de alerta","t":"Batroc recibe +1 PLA y +1 ATQ.\nSi hay al menos 4[per_hero] de Amenaza sobre esta carta, los jugadores pierden la partida.\nRespuesta obligada: después de que un personaje sea derrotado por cualquier motivo que no sea Daño derivado, coloca 1 de Amenaza sobre esta carta.\nAcción de Héroe: gasta 1 recurso de cualquier tipo → quita 1 de Amenaza de esta carta."},
  "50091": {"n":"Prisionero liberado","t":"Victoria -1.\nNo se cuenta de cara a tu límite de Aliados. Las capacidades de cartas no pueden retirar este Aliado del juego.\nAcción de Héroe: agota al Prisionero liberado → quita 1[per_hero] de Amenaza del Plan principal."},
  "50092": {"n":"Reflejos aumentados","t":"Vincula esta carta a Batroc.\nUsos (4 contadores de Salto).\nInterrupción obligada: cuando Batroc vaya a sufrir cualquier cantidad de Daño, evita 2 de ese Daño y quita 1 contador de Salto de esta carta.\n[star] Aumento: vincula esta carta a la Batroc."},
  "50093": {"n":"Guardia de la embajada","t":"Guardia. Vulnerable. (Descarta este personaje si queda aturdido o confundido.)\nSi Nivel de alerta tiene boca arriba la cara de Alto, esta carta gana Oleada.\nCuando se derrote esta carta: coloca 1 de Amenaza sobre Nivel de alerta."},
  "50094": {"n":"Patrulla de la embajada","t":"Patrulla. Vulnerable. (Descarta este personaje si queda aturdido o confundido.)\nSi Nivel de alerta tiene boca arriba la cara de Alto, esta carta gana Incitar 1.\nCuando se derrote esta carta: coloca 1 de Amenaza sobre Nivel de alerta."},
  "50095": {"n":"Tomar la sala de seguridad","t":"Cuando se muestre esta carta: si Nivel de alerta tiene boca arriba la cara de Alto, coloca 1 ficha de Aceleración sobre esta carta.\nCuando se derrote esta carta: quita 1[per_hero] de Amenaza de Nivel de alerta."},
  "50096": {"n":"Patada en salto","t":"Cuando se muestre esta carta (Alter ego): Batroc ejecuta el Plan.\nCuando se muestre esta carta (Héroe): Batroc ataca al Aliado que tenga más Vida restante. Este ataque gana Brutalidad. Si no hay Aliados en juego, Batroc te ataca."},
  "50097": {"n":"Cámaras de seguridad","t":"Cuando se muestre esta carta (Alter ego): quita 1 de Amenaza de Nivel de alerta. Esta carta gana Oleada.\nCuando se muestre esta carta (Héroe): por cada personaje que controles, elige entre agotar a ese personaje o bien colocar 1 de Amenaza sobre Nivel de alerta (2 de Amenaza si Nivel de alerta tiene boca arriba la cara de Alto)."},
  "50098": {"t":"Oleada. Vulnerable.\n[star] Los ataques de Machete ganan Penetrante.\nCuando se derrote esta carta: añade a Machete al mazo de Encuentros y barájalo.","f":"Cada vez que muere un Machete, otro miembro de la familia López hereda el título."},
  "50099": {"n":"Rápido","t":"[star] Los ataques de Rápido ganan A distancia e infligen Daño indirecto.\nCuando se muestre esta carta: inflige 1 de Daño a cada personaje que controles.\n[star] Aumento: inflige 1 de Daño a cada personaje que controles."},
  "50100": {"t":"[star] Zaran recibe +X ATQ, siendo X el coste en recursos impreso de la carta que tenga metida debajo.\nCuando se muestre esta carta: mete una Mejora Arma que controles debajo de Zaran. De no ser posible, mete la primera carta de tu mazo debajo de Zaran."},
  "50101": {"n":"La Brigada de Batroc","t":"Todos los Esbirros ganan Dureza.\nCuando se muestre esta carta: dale a cada enemigo una carta de Estado \"Duro\".\nInterrupción de Héroe: cuando muestres un Esbirro que no sea de Élite, gasta 3 recursos de cualquier tipo → anula los efectos de ese Esbirro y descártalo.","f":"\"El dinero no compra la lealtad, pero ayuda bastante.\" —Batroc"},
  "50102": {"n":"Soldados de fortuna","t":"Cuando se muestre esta carta: elige una opción:\n• Gasta 3 recursos de cualquier tipo.\n• Localiza un Esbirro Mercenario y muéstralo. Si no entra en juego ningún Esbirro de este modo, esta carta gana Oleada.\n[star] Aumento: elige entre gastar 1 recurso de cualquier tipo, o bien que esta carta gane [boost][boost][boost]."},
  "50103a": {"t":"Represalia 1.\nInterrupción obligada: cuando M.O.D.O.K. vaya a ser derrotado, si hay en juego alguna Celda de detención, en vez de eso quita 2 contadores de Cautiverio a la Celda de detención y restablece a 10 la Vida de M.O.D.O.K. De no ser así, los jugadores ganan la partida."},
  "50103b": {"t":"Represalia 2. Tesón.\nInterrupción obligada: cuando M.O.D.O.K. vaya a ser derrotado, si hay en juego alguna Celda de detención, en vez de eso quita 2 contadores de Cautiverio a la Celda de detención y restablece a 14 la Vida de M.O.D.O.K. De no ser así, los jugadores ganan la partida."},
  "50104a": {"n":"Mejoras para los adaptoides","t":"Contenido: M.O.D.O.K. (A). (M.O.D.O.K. (B) para jugar en modo Experto.) Conjuntos de Encuentros de M.O.D.O.K. y Normal. Un conjunto de Encuentros modular (Científico Supremo).\nPreparación: crea el mazo de Celdas de detención (ver página 13 del reglamento). Pon en juego 1 Entorno Adaptoide aleatorio (2 Entornos en modo Experto) y aparta los demás a un lado. Cada jugador busca en el mazo de Encuentros una copia de Adaptoide y la muestra."},
  "50104b": {"n":"Mejoras para los adaptoides","t":"Interrupción obligada: cuando vaya a completarse esta etapa, en vez de eso pon en juego 1 Entorno Adaptoide aleatorio que esté apartado. Luego, si no hay ningún Entorno Adaptoide apartado, los jugadores pierden la partida. De no ser así, quita toda la Amenaza de esta carta, devuelve al mazo de Encuentros todos los Esbirros Adaptoide que haya en su pila de descartes y barájalo."},
  "50105a": {"n":"Celda de detención","t":"Entra en juego con 2[per_hero] contadores de Cautiverio.\nInterrupción obligada: cuando se quite el último contador de Cautiverio de esta carta, dale la vuelta y pon en juego al Inhumano volador controlado por cualquier jugador.\nAcción de Héroe: gasta recursos [energy] [energy] o bien 3 recursos de cualquier tipo → quita 1 contador de Cautiverio de esta carta."},
  "50105b": {"n":"Inhumano volador","t":"No se cuenta de cara a tu límite de Aliados.\n[star] Respuesta: después de que este Aliado intervenga, quita 1 de Amenaza de otro Plan.\nRespuesta obligada: después de que esta carta abandone el juego, dale la vuelta y colócala en la parte inferior del mazo de Celdas de detención."},
  "50106a": {"n":"Celda de detención","t":"Entra en juego con 2[per_hero] contadores de Cautiverio.\nInterrupción obligada: cuando se quite el último contador de Cautiverio de esta carta, dale la vuelta y pon en juego al Inhumano psiónico controlado por cualquier jugador.\nAcción de Héroe: gasta recursos [mental] [mental] o bien 3 recursos de cualquier tipo → quita 1 contador de Cautiverio de esta carta."},
  "50106b": {"n":"Inhumano psiónico","t":"No se cuenta de cara a tu límite de Aliados.\n[star] Respuesta: después de que este Aliado intervenga, quita 1 contador de Cautiverio de una Celda de detención.\nRespuesta obligada: después de que esta carta abandone el juego, dale la vuelta y colócala en la parte inferior del mazo de Celdas de detención."},
  "50107a": {"n":"Celda de detención","t":"Entra en juego con 2[per_hero] contadores de Cautiverio.\nInterrupción obligada: cuando se quite el último contador de Cautiverio de esta carta, dale la vuelta y pon en juego a Sarah Garza controlada por cualquier jugador.\nAcción de Héroe: gasta un recurso [wild] o bien 3 recursos de cualquier tipo → quita 1 contador de Cautiverio de esta carta."},
  "50107b": {"t":"No se cuenta de cara a tu límite de Aliados.\n[star] Los ataques de Sarah Garza ganan A distancia y Brutalidad.\nRespuesta obligada: después de que esta carta abandone el juego, dale la vuelta y colócala en la parte inferior del mazo de Celdas de detención."},
  "50108a": {"n":"Celda de detención","t":"Entra en juego con 2[per_hero] contadores de Cautiverio.\nInterrupción obligada: cuando se quite el último contador de Cautiverio de esta carta, dale la vuelta y pon en juego a la Inhumana fuerte controlada por cualquier jugador.\nAcción de Héroe: gasta recursos [physical] [physical] o bien 3 recursos de cualquier tipo → quita 1 contador de Cautiverio de esta carta."},
  "50108b": {"n":"Inhumana fuerte","t":"Dureza.\nNo se cuenta de cara a tu límite de Aliados.\nInterrupción obligada: después de que esta carta abandone el juego, dale la vuelta y colócala en la parte inferior del mazo de Celdas de detención."},
  "50109": {"n":"Mejora de vuelo","t":"Cada Adaptoide recibe +1 PLA, gana Incitar 1 y gana el rasgo Aéreo.","f":"\"¿Ahora vuelan?\"\n\"Ahora vuelan.\"\n—Maria Hill y Nick Furia"},
  "50110": {"n":"Mejora psiónica","t":"Cada Adaptoide gana Infame y el rasgo Psiónico.","f":"\"¡Recordad vuestro adiestramiento en defensa psiónica!\" —Maria Hill"},
  "50111": {"n":"Mejora de Sarah Garza","t":"Cada Adaptoide gana el rasgo Élite.\nCada Adaptoide recibe +1 ATQ y sus ataques ganan A distancia y Brutalidad.","f":"\"Genial, sencillamente genial. ¡Esas cosas controlan sus poderes mejor que yo los míos!\" —Sarah Garza"},
  "50112": {"n":"Mejora de fuerza","t":"Cada Adaptoide recibe +1 ATQ, gana Dureza y gana el rasgo Bruto.","f":"\"¡Creo que no nos va a gustar verla enfadada!\" —Temblor"},
  "50113": {"n":"Adaptoide","t":"[star] (Busca modificadores a estos valores en las cartas de Entorno Adaptoide.)\nCuando se derrote esta carta: quita 1 contador genérico de un Entorno.\n[star] Aumento: después de esta activación, devuelve el Adaptoide al mazo de Encuentros y barájalo."},
  "50114": {"n":"Unidad móvil automatizada","t":"Vincula esta carta a M.O.D.O.K.\nM.O.D.O.K. recibe +5 de Vida.\nRespuesta obligada: después de que se restablezca la Vida de M.O.D.O.K., descarta esta carta.","f":"\"¡Te aplastaré como a un insecto!\" —M.O.D.O.K."},
  "50115": {"n":"Cristal de enfoque","t":"Vincula esta carta a M.O.D.O.K.\nRespuesta obligada: después de que se restablezca la Vida de M.O.D.O.K., descarta esta carta.","f":"M.O.D.O.K. canaliza sus poderes psiónicos a través del cristal que tiene incrustado en su enorme frente."},
  "50116": {"t":"Vincula esta carta a M.O.D.O.K.\n[star] Respuesta obligada: después de que M.O.D.O.K. se active, cúrale 1 de Daño.\nRespuesta obligada: después de que se restablezca la Vida de M.O.D.O.K., descarta esta carta.","f":"Estas máquinas microscópicas se encargan del mantenimiento de la Silla del Juicio Final."},
  "50117": {"n":"Campo de fuerza psiónico","t":"Vincula esta carta a M.O.D.O.K.\nEl enemigo vinculado gana Firmeza.\nInterrupción obligada: cuando el enemigo vinculado vaya a sufrir cualquier cantidad de Daño, en vez de eso coloca ese Daño sobre esta carta. Luego, si hay al menos 5 de Daño sobre esta carta, descártala.\n[star] Aumento: vincula esta carta al enemigo que se está activando."},
  "50118": {"n":"Machetes psiónico","t":"Vincula esta carta a M.O.D.O.K.\n[star] Los ataques de M.O.D.O.K. ganan Penetrante.\nRespuesta obligada: después de que se restablezca la Vida de M.O.D.O.K., descarta esta carta.\n[star] Aumento: si esta activación es un ataque, gana Penetrante."},
  "50119": {"n":"Ingeniería inversa","t":"Vincula esta carta a M.O.D.O.K.\n[star] X es igual al coste impreso de la carta que esté metida aquí debajo.\nCuando se muestre esta carta: mete debajo de esta carta una mejora que controles. De no ser posible, mete la primera carta de tu mazo debajo de esta carta.\nRespuesta obligada: después de que se restablezca la Vida de M.O.D.O.K., descarta esta carta."},
  "50120": {"n":"Carcelero de I.M.A.","t":"Guardia.\nCuando se muestre esta carta: el Carcelero de I.M.A. ataca al Aliado Rescatado que tenga menos Vida restante. De no ser posible, coloca 1 contador de Cautiverio sobre una Celda de detención."},
  "50121": {"n":"Rehén en peligro","t":"M.O.D.O.K. no puede sufrir Daño.\nCuando se muestre esta carta: vincula a esta carta 1 Aliado Rescatado boca arriba. El Aliado vinculado no ésta controlado por ningún jugador. (El Aliado vinculado sigue en juego.)\nCuando se derrote esta carta: el jugador que la ha derrotado toma el control del Aliado vinculado."},
  "50122": {"n":"Potenciación psiónico","t":"Complicación 1[per_hero].\n[star] Aumento: dale al enemigo activado una carta de aumento adicional."},
  "50123": {"n":"\"¡Está vivo!\"","t":"Cuando se muestre esta carta: Cada jugador busca un Esbirro Adaptoide en el mazo y la pila de descartes de Encuentros y lo muestra. (Baraja el mazo.) Dale una carta de Encuentro boca abajo a cada jugador que no se haya enfrentado a un Esbirro de este modo."},
  "50124": {"n":"Rayo psiónico","t":"Cuando se muestre esta carta (Alter ego): quedas confundido. M.O.D.O.K. ejecuta el Plan.\nCuando se muestre esta carta (Héroe): sufres X de Daño indirecto, siendo X la puntuación de PLA de M.O.D.O.K. Confunde a todos los personajes que hayan sufrido Daño de este modo."},
  "50125": {"n":"Científico Supremo","t":"Victoria -1. Infame. Vulnerable. (Descarta este personaje si queda aturdido o confundido.)\n[star] Los ataques del Científico Supremo ganan A distancia y Penetrante.","f":"Equipado con una armadura de tecnología punta, el Científico Supremo ostenta un enorme poder tanto físico como político."},
  "50126": {"t":"Victoria -1. Infame. Vulnerable. (Descarta este personaje si queda aturdido o confundido.)\nMientras el Científico Supremo esté en la zona de victoria, Monica Rappaccini gana Infame.","f":"Como segunda al mando en I.M.A., Monica tiene el ojo puesto en el título de Científica Suprema."},
  "50127": {"n":"Inmunidad diplomática","t":"Cuando se muestre esta carta: coloca 1 ficha de Aceleración sobre esta carta por cada Esbirro de I.M.A. que haya en la zona de victoria.","f":"Atacar al líder de una nación soberana constituye un suicidio político. Tendréis que ocuparos del Científico Supremo con mucha delicadeza."},
  "50128": {"n":"Sanciones diplomáticas","t":"Oleada.\nCuando se muestre esta carta: descarta 1 carta de tu mano por cada Esbirro de I.M.A. que haya en la zona de victoria.\n[star] Aumento: Esta carta gana [boost] por cada Esbirro de I.M.A. que haya en la zona de victoria."},
  "50129a": {"n":"Ciudadano V","t":"Ciudadano V no puede ser derrotado a menos que haya como mínimo 1[per_hero] Esbirros Thunderbolt en la zona de victoria.\n[star] Interrupción obligada: cuando Ciudadano V vaya a activarse contra ti durante el paso dos de la fase del Villano, si estás enfrentado a un Esbirro Thunderbolt, el Ciudadano V no se activa y en vez de eso se cura 4 de Daño."},
  "50129b": {"n":"Ciudadano V","t":"Ciudadano V no puede ser derrotado a menos que haya como mínimo 1[per_hero] Esbirros Thunderbolt en la zona de victoria.\n[star] Interrupción obligada: cuando Ciudadano V vaya a activarse contra ti durante el paso dos de la fase del Villano, si estás enfrentado a un Esbirro Thunderbolt, el Ciudadano V no se activa y en vez de eso se cura 6 de Daño."},
  "50130a": {"n":"Arresto de agentes renegados","t":"Contenido: Ciudadano V (A). (Ciudadano V (B) para jugar en modo Experto.) Conjuntos de Encuentros de los Thunderbolts y Normal.\nPreparación: elige 1 conjunto modular, más 1[per_hero] conjuntos adicionales, que tengan todos un Esbirro Thunderbolt de Élite. Aparta a un lado todos esos Esbirros, devuelve el resto de sus conjuntos al mazo de Encuentros y barájalo. Muestra la carta de Entorno La justicia, como el rayo."},
  "50130b": {"n":"Arresto de agentes renegados","t":"Cada Esbirro Thunderbolt gana Guardia.\nRespuesta obligada: después de que un jugador ataque a un Esbirro Thunderbolt, ese Esbirro se enfrenta a ese jugador.\nSi se completa esta etapa, los jugadores pierden la partida.","f":"\"Podemos hacerlo por las buenas, o podemos divertirnos.\" —Ciudadano V"},
  "50131a": {"n":"La justicia, como el rayo","t":"Cuando se muestre esta carta: cada jugador muestra un Esbirro Thunderbolt aleatorio que esté apartado. Muestra y vincula a esta carta el Esbirro Thunderbolt apartado que quede. En modo Experto, dale una carta de Estado \"Duro\" a cada uno de estos Esbirros. Dale la vuelta a esta carta.","f":"\"Justicia, como el rayo, cuando haga su aparición, de pocos será desgracia y de todos será terror.\" —Thomas Randolph"},
  "50131b": {"n":"Thunderbolt de refuerzo","t":"(El Esbirro vinculado a esta carta está en juego y puede ser seleccionado como blanco de ataques y capacidades.)\nInterrupción obligada: cuando termine la ronda, vincula a esta carta el Esbirro Thunderbolt que tenga más Daño, intercambiándolo por el Esbirro que ya esté vinculado a esta carta (si lo hay). Cura 1[per_hero] de Daño al Esbirro vinculado. En modo Experto, cura 1[per_hero] de Daño adicional a ese Esbirro y dale una carta de Estado \"Duro\"."},
  "50132": {"n":"Espada de Ciudadano V","t":"Cuando se muestre esta carta: vincula esta carta a Ciudadano V. Se activa contra ti.\nRespuesta de Héroe: después de que ataques y causes Daño al Ciudadano V, gasta recursos [physical] [physical] → descarta esta carta."},
  "50133": {"t":"Infame.\nCuando se derrote esta carta: coloca 3 de Amenaza sobre el Plan principal.\nAcción de Héroe: agota tu Héroe → coloca 1 contador de Tregua sobre Jolt. Si hay al menos 3 contadores de Tregua sobre esta carta, retira Jolt de la partida. (No ha sido derrotada.)"},
  "50134": {"n":"Traseúntes inocentes","t":"Usos (4 contadores de Traseúnte).\nRespuesta obligada: después de que ataques a un enemigo o un enemigo te ataque, elige entre gastar 1 recurso de cualquier tipo o bien colocar 1 de Amenaza sobre el Plan principal (2 de Amenaza en modo Experto). Quita 1 contador de Traseúnte de esta carta."},
  "50135": {"n":"La tormenta inminente","t":"Cuando se muestre esta carta: cada jugador se enfrenta a cada Esbirro que esté enfrentado al jugador de su izquierda.","f":"\"¡Thunderbolts, llevemos a estos justicieros ante las autoridades!\" —Pájaro Cantor"},
  "50136": {"n":"El retumbar del trueno","t":"Cuando se muestre esta carta: cada jugador se enfrenta a cada Esbirro que esté enfrentado al jugador de su izquierda."},
  "50137": {"n":"Tumbado, pero no vencidos","t":"Cuando se muestre esta carta: elige un Esbirro Thunderbolt aleatorio de la zona de victoria y muéstralo. Coloca Daño sobre ese Esbirro hasta dejarlo con 5 de Vida restante. Luego retira esta carta de la partida. Si no entra en juego ningún Esbirro de este modo, esta carta gana Oleada."},
  "50138": {"n":"Tomar el relevo","t":"Cuando se muestre esta carta: enfréntate al Esbirro Thunderbolt que tenga menos Daño y no esté ya enfrentado a ti. Ese Esbirro se active contra ti. Si no se activa ningún Esbirro de este modo, Ciudadano V se activa contra ti.","f":"\"Relájate, Batroc. Yo me encargo.\" —Piedra Lunar"},
  "50139": {"n":"Piedra Lunar","t":"Infame. Victoria 1.\n[star] Respuesta obligada: después de que Piedra Lunar se active, dale una carta de Estado \"Duro\".","f":"\"¡Pilla!\""},
  "50140": {"n":"Dominio del cielo","t":"Todos los personajes Aéreo reciben +1 ATQ.\n[star] Aumento: si el enemigo activado tiene el rasgo Aéreo, dale una carta de aumento adicional."},
  "50141": {"n":"Fuerza gravitatoria","t":"Cuando se muestre esta carta: localiza a Piedra Lunar y muéstrala. (Si ya está en juego, se enfrenta a ti.) Piedra Lunar se activa contra ti. Si no se activa ningún enemigo de este modo, esta carta gana Oleada.\n[star] Aumento: agota un personaje que controles."},
  "50142": {"n":"Manipulación psicológica","t":"Cuando se muestre esta carta (Alter ego): descarta un Aliado o Apoyo que controles. De no ser posible, esta carta gana Oleada.\nCuando se muestre esta carta (Héroe): inflige X de Daño al personaje amigo que tenga menos Vida restante, siendo X igual al ATQ de tu Héroe."},
  "50143": {"n":"Pájaro Cantor","t":"Infame. Victoria 1.\n[star] Interrupción obligada: cuando Pájaro Cantor se active, dale 1 carta de aumento adicional para esta activación.","f":"\"¡Abre bien los oídos!\""},
  "50144": {"n":"Constructos de sonido sólido","t":"Vincula esta carta a Pájaro Cantor. De no ser posible, vincula esta carta al Villano.\nEl enemigo vinculado pierde Firmeza.\nInterrupción obligada: cuando el enemigo vinculado vaya a ganar una carta de Estado \"Aturdido\" o \"Confundido\", en vez de eso descarta esta carta."},
  "50145": {"n":"Ataduras de sonido sólido","t":"Vincula esta carta a tu Superhéroe.\nInterrupción obligada: cuando vayas a atacar, en vez de eso descarta las Ataduras de sonido sólido. Luego quedas aturdido.\n[star] Aumento: quedas aturdido. Si ya estabas aturdido, dale una carta de aumento adicional al enemigo activado."},
  "50146": {"n":"Burbuja sónica","t":"Interrupción obligada: cuando se vaya a infligir cualquier cantidad de Daño a un enemigo, en vez de eso quita esa misma cantidad de Amenaza de esta carta.","f":"\"¡No se toca!\" —Pájaro Cantor"},
  "50147": {"n":"Sonido sólido","t":"Cuando se muestre esta carta: localiza a Pájaro Cantor y muéstrala. (Si ya está en juego, se enfrenta a ti.) Pájaro Cantor se activa contra ti. Si no se activa ningún enemigo de este modo, esta carta gana Oleada.\n[star] Aumento: dale al enemigo activado una carta de aumento adicional."},
  "50148": {"n":"Viuda Negra","t":"Represalia 1. Infame. Victoria 1.\n[star] Respuesta obligada: después de que Viuda Negra ejecuta el Plan contra ti, busca una copia de Voltereta en el mazo y la pila de descartes de Encuentros y vincúlasela. (Baraja el mazo.) De no ser posible, quedas confundido."},
  "50149": {"n":"Voltereta","t":"Vincula esta carta a la Viuda Negra. De no ser posible, vincula esta carta al Villano.\nInterrupción obligada: cuando el enemigo vinculado vaya a sufrir Daño a consecuencia de un ataque, en vez de eso inflige ese Daño al personaje atacante. Descarta esta carta.","f":"\"Ha sido divertido.\" —Viuda Negra"},
  "50150": {"n":"El orgullo de la Sala Roja","t":"Cuando se muestre esta carta: coloca 1 de Amenaza adicional sobre esta carta por cada carta de Planificación que haya en juego.","f":"Tras aventajar a todas sus compañeras en la Sala Roja, Yelena Belova se propuso demostrar que es la mejor Viuda Negra de todas."},
  "50151": {"n":"Pálida arañita","t":"Cuando se muestre esta carta: localiza a la Viuda Negra y muéstrala. (Si ya está en juego, se enfrenta a ti.) La Viuda Negra se activa contra ti. Si no se activa ningún enemigo de este modo, esta carta gana Oleada.\n[star] Aumento: quedas confundido. Si ya estabas confundido, coloca 1 de Amenaza sobre el Plan principal."},
  "50152": {"n":"Hombre Radiactivo","t":"Infame. Victoria 1.\n[star] Respuesta obligada: después de que Hombre Radiactivo se active contra ti, inflige 1 de Daño a cada personaje que controles.","f":"\"¡En pie y a por ellos!\""},
  "50153": {"n":"Irradiado","t":"Vincula esta carta a tu Superhéroe.\n[star] Si el Superhéroe vinculado tiene el rasgo Gamma, este Accesorio le otorga +1 ATQ en vez de -1.\nRespuesta obligada: después de que te recuperes, descarta 1 carta de tu mano → descarta esta carta."},
  "50154": {"n":"Reacción nuclear descontrolada","t":"Respuesta obligada: después de que se inflija cualquier cantidad de Daño al Hombre Radiactivo, coloca esa misma cantidad de Amenaza sobre esta carta. Luego, si hay al menos 10 de Amenaza sobre esta carta, inflige 10 de Daño a cada personaje y descarta la Reacción nuclear descontrolada."},
  "50155": {"n":"El poder del átomo","t":"Cuando se muestre esta carta: localiza al Hombre Radiactivo y muéstralo. (si ya está en juego, se enfrenta a ti.) El Hombre Radiactivo se activa contra ti. Si no se activa ningún enemigo de este modo, esta carta gana Oleada.\n[star] Aumento: sufres 2 de Daño indirecto."},
  "50156": {"t":"Infame. Victoria 1.\n[star] Los personajes que no tengan el rasgo Aéreo no pueden efectuar defensas básicas contra los ataques de MACH-IV.","f":"\"Voy más armado que un caza.\""},
  "50157": {"n":"Lanzarrayos","t":"Vincula esta carta a MACH-IV. De no ser posible, vincula esta carta al enemigo que tenga la puntuación más alta de ATQ.\n[star] Los ataques del enemigo vinculado ganan A distancia y Brutalidad .\nRespuesta de Héroe: después de que ataques e inflijas Daño al enemigo vinculado, gasta recursos [energy] [energy] → descarta esta carta."},
  "50158": {"n":"Misiles buscadores","t":"Vincula esta carta a MACH-IV. De no ser posible, vincula esta carta al Villano.\nUsos (4 contadores de Misil).\n[star] Respuesta obligada: después de que el enemigo vinculado te ataque, quita 1 contador de Misil de esta carta y sufre 2 de Daño indirecto."},
  "50159": {"n":"Duelo aéreo","t":"Complicación 2[per_hero].\nReduce en 2 el Daño que sufra cada personaje Aéreo de cada ataque a menos que el atacante o el ataque tengan el rasgo Aéreo, o que el ataque tenga A distancia."},
  "50160": {"n":"Supersónico","t":"Cuando se muestre esta carta: localiza a MACH-IV y muéstralo. (si ya está en juego, se enfrenta a ti.) MACH-IV se activa contra ti. Si no se activa ningún enemigo de este modo, esta carta gana Oleada.\n[star] Aumento: si esta activación es un ataque, gana A distancia y Brutalidad."},
  "50161": {"t":"Infame. Victoria 1.\nInterrupción obligada: cuando Batroc se enfrente a ti, descarta 1 carta de tu mano.","f":"\"On se revoit. ¡En garde!\""},
  "50162": {"t":"Interrupción obligada: cuando un Esbirro se enfrente a un jugador, ese jugador descarta las X primeras cartas de su mazo, siendo X el número de iconos de Aumento ([boost]) que tenga ese Esbirro. Coloca 1 de Amenaza sobre esta carta por cada recurso [energy] impreso que se haya descartado de este modo."},
  "50163": {"n":"Batroc el Saltador","t":"Cuando se muestre esta carta: localiza a Batroc y muéstralo. (si ya está en juego, se enfrenta a ti.) Batroc se activa contra ti. Si no se activa ningún enemigo de este modo, esta carta gana Oleada.\n[star] Aumento: descarta 1 carta de tu mano."},
  "50164": {"t":"Oleada.\nCuando se muestre esta carta: cada jugador se enfrenta a cada Esbirro que esté enfrentado al jugador de su izquierda.\n[star] Aumento: después de se resuelva este ataque, enfréntate a un Esbirro que esté en juego y no esté ya enfrentado a ti."},
  "50165a": {"n":"Barón Zemo","t":"Interrupción obligada: cuando Barón Zemo vaya a ser derrotado, en vez de eso restablece su Vida a 12. Quita 3 contadores de Secreto de entre todos los Entornos Miembro de la junta.","f":"\"¡Quedan todos arrestados por orden de la junta directiva!\""},
  "50165b": {"n":"Barón Zemo","t":"[star] Interrupción obligada: cuando Barón Zemo se active contra ti, elige entre colocar 1 contador de Secreto sobre una carta Miembro de la junta o bien darle al Barón Zemo una carta de aumento adicional para esta activación."},
  "50166a": {"n":"Barón Zemo","t":"Interrupción obligada: cuando Barón Zemo vaya a ser derrotado, en vez de eso restablece su Vida a 16. Quita 3 contadores de Secreto de entre todos los Entornos Miembro de la junta.","f":"\"¡Quedan todos arrestados por orden de la junta directiva!\""},
  "50166b": {"n":"Barón Zemo","t":"Tesón.\n[star] Interrupción obligada: cuando Barón Zemo se active contra ti, elige coloca 2 contadores de Secreto sobre una carta Miembro de la junta o bien darle al Barón Zemo una carta de aumento adicional para esta activación."},
  "50167a": {"n":"Las manipulaciones de Zemo","t":"Contenido: Barón Zemo (A1). (Barón Zemo (B1) para jugar en modo Experto.) Conjuntos de Encuentros del Barón Zemo, Junta directiva de S.H.I.E.L.D., Pruebas de la junta y Normal. Dos conjuntos de Encuentros modulares (Científico Supremo y S.H.I.E.L.D.).\nPreparación: prepara las Pruebas (ver página 18 del reglamento). Pon en juego todos los Entorno Miembro de la junta. Si no se está jugando al modo Campaña, coloca 2 contadores de Secreto sobre cada Entorno Miembro de la junta."},
  "50167b": {"n":"Las manipulaciones de Zemo","t":"Respuesta: después de que termine la fase de los Jugadores, el jugador inicial puede colocar 2 contadores de Secreto sobre un Entorno Miembro de la junta que no tenga ningún contador de Secreto encima para obtener 2 cartas del sobre de S.H.I.E.L.D. (1 carta en el modo Campaña). Los jugadores pueden avanzar a la etapa 2A para formular su acusación.\nSi se completa esta etapa, los jugadores pierden la partida."},
  "50168a": {"n":"La acusación","t":"Cuando se muestre esta carta: formula una acusación intentando adivinar el medio, el motivo y la oportunidad del topo, así como la identidad del miembro de la junta asociadao a esa combinación en la hoja de campaña. Este miembro de la junta es el acusado. (Ver \"La acusación\" en la página 19 del reglamento.)","f":"Habéis obtenido todas las pruebas que habéis podido. Lo único que queda es formular la acusación."},
  "50168b": {"n":"La acusación","t":"Cuando se muestre esta carta: haz lo siguiente:\n1. Usa las cartas del sobre de I.M.A. para identificar al topo.\n2. Por cada error que hayas cometido, coloca 1 contador de Secreto sobre cada carta Miembro de la junta.\n3. Si has acusado al miembro de la junta equivocado, coloca 3 contadores de Secreto sobre el acusado.\n4. Avanza a la etapa 3A."},
  "50169a": {"n":"Lucha contra Zemo","t":"Cuando se muestre esta carta: dale la vuelta al Barón Zemo para poner boca arriba su cara Desenmascarado y restablece su Vida a su valor impreso. Localiza la Espada del Barón Zemo y vincúlasela.","f":"Habéis descubierto el engaño de Zemo y revelado la identidad de su cómplice."},
  "50169b": {"n":"Lucha contra Zemo","t":"Cuando se muestre esta carta: dale la vuelta al topo para convertirlo en un Accesorio y vincúlalo al Barón Zemo. Coloca 1[per_hero] de Amenaza sobre esta carta por cada contador de Secreto que tenga cada Accesorio Miembro de la junta.\nSi se completa esta etapa, los jugadores pierden la partida.","f":"El Barón Zemo y su cómplice deben responder ante la justicia!"},
  "50170": {"n":"Espada del Barón Zemo","t":"Vincula esta carta a Barón Zemo.\n[star] Respuesta obligada: después de que el Barón Zemo ataque y derrote a un personaje, coloca 1 contador de Secreto sobre el Entorno Miembro de la junta que tenga menos contadores de Secreto.\nAcción de Héroe: gasta recursos [physical] [physical] [physical] o bien [energy] [energy] [energy] → quita 1 contador de Secreto de un Entorno Miembro de la junta y descarta esta carta."},
  "50171": {"n":"Enemigo reacio","t":"Trata al Héroe vinculado como un Esbirro de Élite con una puntuación de PLA igual a su INT impresa. Sustituye su texto de reglas por el siguiente: \"Infame. Cuando se derrote esta carta: retira de la partida a este Héroe y la carta de Enemigo reacio.\"\nCuando se muestre esta carta: busca en tu colección un Héroe cuyo nombre no coincida con el de un personaje que ya esté en juego y ponlo en juego enfrentado a ti. Vincúlale esta carta."},
  "50172": {"n":"Agente de S.H.I.E.L.D.","t":"Ataque veloz. Vulnerable.\n[star] Interrupción obligada: cuando Agente de S.H.I.E.L.D. se active o sea derrotado, añade 1 contador de Secreto al Entorno Miembro de la junta que tenga menos contadores de Secreto."},
  "50173": {"n":"Conflicto de lealtades","t":"Complicación 1[per_hero].\nComo coste adicional para que un jugador ataque, intervenga o defienda con un Aliado, ese jugador debe gastar 1 recurso de cualquier tipo.\nCuando se derrote esta carta: quita 1[per_hero] contadores de Secreto de entre todos los Entornos Miembro de la junta."},
  "50174": {"n":"Privar de apoyo","t":"Complicación 1[per_hero].\nComo coste adicional para que un jugador prepare un Apoyo, ese jugador debe gastar 1 recurso de cualquier tipo.\nCuando se derrote esta carta: quita 1[per_hero] contadores de Secreto de entre todos los Entornos Miembro de la junta.","f":"\"¡Ahora yo doy las órdenes en S.H.I.E.L.D.!\" —Barón Zemo"},
  "50175": {"n":"Batalla de ingenio","t":"Cuando se muestre esta carta: el Barón Zemo ejecuta el Plan. Si esta activation va a colocar cualquier cantidad de Amenaza sobre el Plan principal, puedes gastar X recursos [mental] para evitar X de esa Amenaza y quitar X contadores de Secreto de entre todos los Entornos Miembro de la junta."},
  "50176": {"n":"La ley del más fuerte","t":"Cuando se muestre esta carta (Alter ego): coloca 2 contadores de Secreto sobre el Entorno Miembro de la junta que tenga menos contadores de Secreto.\nCuando se muestre esta carta (Héroe): el Barón Zemo te ataca. Si ningún personaje sufre Daño a consecuencia de este ataque, quita 3 contadores de Secreto de entre todos los Entornos Miembro de la junta."},
  "50177": {"n":"El fin justifica los medios","t":"Cuando se muestre esta carta: elige una opción:\n• El Barón Zemo derrota al Esbirro que tenga menos Vida restante. El Barón Zemo ejecuta el Plan.\n• Descarta un Aliado o Apoyo que controles → quita tantos contadores de Secreto de entre todos los Entornos Miembro de la junta como el coste en recursos impreso de la carta descartada."},
  "50178": {"n":"Infantería de S.H.I.E.L.D.","t":"Patrulla. Vulnerable.\nCuando se derrote esta carta: el jugador enfrentado descarta 1 Aliado o Apoyo S.H.I.E.L.D. que controle. De no ser así, coloca 2 de Amenaza sobre el Plan principal.","f":"\"Vengan con nosotros sin oponer resistencia y nadie saldrá herido.\""},
  "50179": {"n":"Orden de detención","t":"Acción de Alter ego: agota tu Superhéroe o 1 carta de S.H.I.E.L.D. que controles → busca un Esbirro de S.H.I.E.L.D. en el mazo y la pila de descartes de Encuentros y muéstralo. (Baraja el mazo.) Descarta esta carta."},
  "50180": {"n":"Desautorizados","t":"Aumenta en 1 el coste en recursos para jugar cada carta de S.H.I.E.L.D..\nCuando se muestre esta carta: coloca 1 de Amenaza sobre esta carta por cada carta de S.H.I.E.L.D. que haya en juego.","f":"La Junta directiva de S.H.I.E.L.D. se ha desvinculado de vuestras actividades y os ha privado de todos vuestros recursos."},
  "50181a": {"n":"Director médico","t":"Inicio.\nSi hay al menos 4 contadores de Secreto sobre esta carta (al menos 3 en modo Experto), dale la vuelta.\nAcción de Héroe: gasta recursos [energy] [energy] → quita 1 contador de Secreto de esta carta. Luego cura 1 de Daño a un personaje amigo."},
  "50181b": {"n":"Ayuda del director médico","t":"Vincula esta carta al Villano. Permanente.\nRespuesta obligada: después de que se coloque un contador de Secreto sobre esta carta, elige cúrale 2 de Daño al Villano o bien infligir 1 de Daño al personaje amigo que tenga menos Vida restante.\nSi hay en juego 3 Accesorios Miembro de la junta, los jugadores pierden la partida."},
  "50182a": {"n":"Director de vigilancia","t":"Inicio.\nSi hay al menos 4 contadores de Secreto sobre esta carta (al menos 3 en modo Experto), dale la vuelta.\nAcción de Héroe: gasta recursos [mental] [mental] → quita 1 contador de Secreto de esta carta. Luego quita 2 de Amenaza de un Plan."},
  "50182b": {"n":"Ayuda del director de vigilancia","t":"Vincula esta carta al Villano. Permanente.\nRespuesta obligada: después de que se coloque un contador de Secreto sobre esta carta, coloca 2 de Amenaza sobre el Plan principal.\nSi hay en juego 3 Accesorios Miembro de la junta, los jugadores pierden la partida."},
  "50183a": {"n":"Directora de operaciones","t":"Inicio.\nSi hay al menos 4 contadores de Secreto sobre esta carta (al menos 3 en modo Experto), dale la vuelta.\nAcción de Héroe: gasta recursos [physical] [physical] → quita 1 contador de Secreto de esta carta. Luego inflige 2 de Daño a un enemigo."},
  "50183b": {"n":"Ayuda de la directora de operaciones","t":"Vincula esta carta al Villano. Permanente.\nRespuesta obligada: después de que se coloque un contador de Secreto sobre esta carta, inflige 2 de Daño a un personaje amigo.\nSi hay en juego 3 Accesorios Miembro de la junta, los jugadores pierden la partida."},
  "50184a": {"n":"Interferencia de I.M.A. ([energy])","t":"Incitar 1.\nCuando se muestre esta carta: coloca 1 contador de Secreto sobre cada carta Miembro de la junta. Puedes gastar X recursos [energy] para evitar que se coloquen X de esos contadores.\n[star] Aumento: resuelve la capacidad \"Cuando se muestre esta carta\" de esta carta."},
  "50184b": {"n":"Interferencia de I.M.A. ([mental])","t":"Incitar 1.\nCuando se muestre esta carta: coloca 1 contador de Secreto sobre cada carta Miembro de la junta. Puedes gastar X recursos [mental] para evitar que se coloquen X de esos contadores.\n[star] Aumento: resuelve la capacidad \"Cuando se muestre esta carta\" de esta carta."},
  "50184c": {"n":"Interferencia de I.M.A. ([physical])","t":"Incitar 1.\nCuando se muestre esta carta: coloca 1 contador de Secreto sobre cada carta Miembro de la junta. Puedes gastar X recursos [physical] para evitar que se coloquen X de esos contadores.\n[star] Aumento: resuelve la capacidad \"Cuando se muestre esta carta\" de esta carta."},
  "50185": {"n":"Expedientes médicos","t":"Preparación: cada jugador puede añadir 1 contador de Secreto a un Entorno Miembro de la junta para buscar en su colección un Aliado de Protección diferente, añádirlo a su mazo y barajarlo. Cada jugador puede añadir 1 de Amenaza al Plan principal para buscar un Aliado de Protección en su mazo y añádirlo a su mano. (Baraja el mazo.)"},
  "50186": {"n":"Teléfono pinchado","t":"Preparación: cada jugador puede añadir 1 contador de Secreto a un Entorno Miembro de la junta para buscar en su colección un Aliado de Justicia diferente, añádirlo a su mazo y barajarlo. Cada jugador puede añadir 1 de Amenaza al Plan principal para buscar un Aliado de Justicia en su mazo en su mazo y añádirlo a su mano. (Baraja el mazo.)"},
  "50187": {"n":"Escaner de seguridad","t":"Preparación: cada jugador puede añadir 1 contador de Secreto a un Entorno Miembro de la junta para buscar en su colección un Aliado de Agresividad diferente, añádirlo a su mazo y barajarlo. Cada jugador puede añadir 1 de Amenaza al Plan principal para buscar un Aliado de Agresividad en su mazo y añádirlo a su mano. (Baraja el mazo.)"},
  "50188": {"n":"Dinero","t":"Preparación: cada jugador puede añadir 1 contador de Secreto a un Entorno Miembro de la junta para buscar en su colección una Mejora de Protección diferente, añádirla a su mazo y barajarlo. Cada jugador puede añadir 1 de Amenaza al Plan principal para buscar una Mejora de Protección en su mazo y añádirla a su mano. (Baraja el mazo.)"},
  "50189": {"n":"Chantaje","t":"Preparación: cada jugador puede añadir 1 contador de Secreto a un Entorno Miembro de la junta para buscar en su colección una Mejora de Justicia diferente, añádirla a su mazo y barajarlo. Cada jugador puede añadir 1 de Amenaza al Plan principal para buscar una Mejora de Justicia en su mazo y añádirla a su mano. (Baraja el mazo.)"},
  "50190": {"n":"Ideología","t":"Preparación: cada jugador puede añadir 1 contador de Secreto a un Entorno Miembro de la junta para buscar en su colección una Mejora de Agresividad diferente, añádirla a su mazo y barajarlo. Cada jugador puede añadir 1 de Amenaza al Plan principal para buscar una Mejora de Agresividad en su mazo y añádirla a su mano. (Baraja el mazo.)"},
  "50191": {"n":"Acreditación de seguridad","t":"Preparación: cada jugador puede añadir 1 contador de Secreto a un Entorno Miembro de la junta para buscar en su colección un Apoyo de Protección diferente, añádirlo a su mazo y barajarlo. Cada jugador puede añadir 1 de Amenaza al Plan principal para buscar un Apoyo de Protección en su mazo y añádirlo a su mano. (Baraja el mazo.)"},
  "50192": {"n":"Viaje","t":"Preparación: cada jugador puede añadir 1 contador de Secreto a un Entorno Miembro de la junta para buscar en su colección un Apoyo de Justicia diferente, añádirlo a su mazo y barajarlo. Cada jugador puede añadir 1 de Amenaza al Plan principal para buscar un Apoyo de Justicia en su mazo y añádirlo a su mano. (Baraja el mazo.)"},
  "50193": {"n":"Autoridad","t":"Preparación: cada jugador puede añadir 1 contador de Secreto a un Entorno Miembro de la junta para buscar en su colección un Apoyo de Agresividad diferente, añádirlo a su mazo y barajarlo. Cada jugador puede añadir 1 de Amenaza al Plan principal para buscar un Apoyo de Agresividad en su mazo y añádirlo a su mano. (Baraja el mazo.)"},
  "51001a": {"n":"Pantera Negra","t":"[star] Respuesta: después de que Pantera Negra use un atributo básico, resuelve la capacidad \"Especial\" de 1 Mejora Pantera Negra que controles.","f":"\"No descansaré en la defensa de mi patria.\""},
  "51001b": {"t":"Inventora — Acción: agota a Shuri → busca en tu mazo una Mejora Pantera Negra o Tecnología y juégala, reduciendo en 2 su coste en recursos. (Límite de una vez por ronda.)"},
  "51002": {"t":"[star] Respuesta de Héroe: después de que T'Challa use un atributo básico, resuelve la capacidad \"Especial\" de 1 Mejora Pantera Negra que controles."},
  "51003": {"n":"Zarpazo","t":"Acción de Héroe (ataque): inflige 4 de Daño a un enemigo. Resuelve la capacidad \"Especial\" de 1 Mejora Pantera Negra que controles.","f":"\"Te has enfrentado a la fuerza de Wakanda...¡enfréntate ahora a sus garras!\" —Pantera Negra"},
  "51004": {"n":"Acechar","t":"Acción de Héroe (intervención): quita 3 de Amenaza de un Plan. Resuelve la capacidad \"Especial\" de 1 Mejora Pantera Negra que controles.","f":"\"La selva encierra incontables peligros.\" —Pantera Negra"},
  "51005": {"n":"¡Wakanda por siempre!","t":"Acción de Héroe: resuelve la capacidad \"Especial\" de cada Mejora Pantera Negra que controles en el orden que prefieras.","f":"\"Es más que un grito de batalla. Es una promesa.\" —Pantera Negra"},
  "51006": {"f":"\"Desde el reinado de Bashenga, hemos controlado nuestro destino como pocas naciones pueden.\" —T'Challa"},
  "51007": {"n":"La trompa del Elefante","t":"Acción de Alter ego: agota La trompa del Elefante y un máximo de otros 2 Aliados o Apoyos Wakanda que controles → roba 1 carta por cada carta que hayas agotado de este modo (incluida ésta).","f":"Este consejo busca soluciones para los problemas de Wakanda."},
  "51008": {"n":"Reina Ramonda","t":"Acción de Alter ego: agota a la Reina Ramonda → cura tanto Daño a un Alter ego que tenga el rasgo Wakanda como la puntuación de REC de ese Alter ego.","f":"\"Nunca vi que dejases un problema sin resolver, hija mia.\""},
  "51009": {"t":"Acción: agota Aja-Adanna → devuelve a tu mazo 1 carta específica de Superhéroe que esté en tu pila de descartes y barájalo.","f":"Shuri es conocida como la guardiana de la memoria wakandiana."},
  "51010": {"n":"Pulsera kimoyo","t":"Especial (intervención): quita 1 de Amenaza de un Plan. Puedes descartar esta carta para confundir a un enemigo.","f":"\"Te veo.\" —Pantera Negra"},
  "51011": {"n":"Garras de pantera","t":"Especial (ataque): inflige 2 de Daño a un enemigo. Puedes descartar esta carta para infligir 3 de Daño adicional a ese enemigo. Si lo haces, este ataque gana Penetrante."},
  "51012": {"n":"Picaduras arácnidas","t":"Especial: elige un jugador. Inflige 1 de Daño al Villano y a cada Esbirro enfrentado a ese jugador. Puedes descartar esta carta para aturdir a cada uno de esos enemigos."},
  "51013": {"n":"Traje de Vibránium","t":"Especial (ataque): traslada 1 de Daño desde tu Héroe hasta un enemigo. Puedes descartar esta carta para darle a tu Héroe una carta de Estado \"Duro\".","f":"\"Es un símbolo de mi cargo, no un disfraz de gato, muchas gracias.\" —Pantera Negra"},
  "51014": {"n":"Distribuidor","t":"Respuesta: después de que Distribuidor entre en juego, elige un jugador. Ese jugador busca un Plan secundario de jugador en su mazo y en su pila de descartes y lo añade a su mano.","f":"\"Exhorto al universo a plegarse sobre sí mismo para poder desplazarme a cualquier lugar dando un solo paso.\""},
  "51015": {"n":"Infiltración","t":"Acción de Héroe (intervención): elige un número del 1 al 5. Descarta esa misma cantidad de cartas de la parte superior del mazo de Encuentros → quita 1 de Amenaza de un Plan por cada carta que se haya descartado de este modo. Pon en juego enfrentado a ti 1 Esbirro descartado de este modo."},
  "51016": {"n":"Disfrazarse como el enemigo","t":"Victoria 0.\nCuando se derrote esta carta: el jugador que la ha derrotado mira las 5 primeras cartas del mazo de Encuentros. Puede añadir a la zona de victoria 1 carta de entre ellas que no sea específica de un escenario, y luego coloca el resto en la parte superior o inferior del mazo de Encuentros en el orden que prefiera."},
  "51017": {"n":"Muestra de empatía","t":"Victoria 0.\nInterrupción obligada: cuando se quite Amenaza de este Plan, coloca esa Amenaza sobre un Esbirro que no sea de Élite. Si la Amenaza que hay encima de ese Esbirro es igual o superior a su Vida restante, añade Muestra de empatía a la zona de victoria y vincula 1 copia apartada de Redención a ese Esbirro."},
  "51018": {"n":"La Balsa","t":"Respuesta: después de que un Esbirro abandone el juego, mételo debajo de esta carta desde la pila de descartes del mazo de Encuentros → quita tanta Amenaza de un Plan como la puntuación impresa de PLA de ese Esbirro. Si hay al menos 4 Esbirros debajo de esta carta, elige 1 de estos Esbirros al azar y dáselo a cualquier jugador como carta de Encuentro boca abajo."},
  "51019": {"n":"Dispositivo de invisibilidad","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nInterrupción: cuando un enemigo vaya a atacarte, descarta el Dispositivo de invisibilidad → ese enemigo ejecuta el Plan en vez de atacarte.","f":"\"Ahora me veis, ahora no me veis.\" —Phil Coulson"},
  "51020": {"n":"Fusil sónico","t":"Restringida. Usos (2 contadores de Carga).\nAcción de Héroe: agota el Fusil sónico y quítale 1 contador de Carga → confunde a un enemigo (si ya está confundido, en vez de eso inflige 3 de Daño a ese enemigo)."},
  "51021": {"n":"Cebo para criminales","t":"Máximo de 1 por jugador.\nRespuesta: después de que un Esbirro que no sea Élite ejecute el Plan, descarta Cebo para criminales → descarta ese Esbirro.","f":"\"¡Podría haberme salido con la mía!\" —Pavel Rasputin"},
  "51022": {"t":"[star] Respuesta: después de que Aneka use un atributo básico, resuelve la capacidad \"Especial\" de otro Aliado Dora Milaje.\nEspecial: quita 1 de Amenaza de un Plan."},
  "51023": {"t":"[star] Respuesta: después de que Ayo use un atributo básico, resuelve la capacidad \"Especial\" de otro Aliado Dora Milaje.\nEspecial: inflige 1 de Daño a un enemigo."},
  "51024": {"t":"[star] Respuesta: después de que Okoye use un atributo básico, resuelve la capacidad \"Especial\" de otro Aliado Dora Milaje.\nEspecial: elige un Héroe o Aliado Wakanda. Ese Héroe o Aliado recibe +1 INT y +1 ATQ hasta el final de la fase."},
  "51025": {"n":"El corazón de la pantera","t":"Equipo (Pantera Negra/T'Challa y Pantera Negra/Shuri). Máximo de 1 por mazo.\nAcción de Héroe: busca una Mejora Pantera Negra en tu mazo y en tu pila de descartes y ponla en juego. Resuelve la capacidad \"Especial\" de hasta 4 Mejoras Pantera Negra que controles en el orden que prefieras."},
  "51026": {"n":"Conseguir apoyo","t":"Victoria 0.\nCuando se derrote esta carta: cada jugador puede buscar en su mazo y en su pila de descartes un Apoyo con un coste de 3 o menos y ponerlo en juego. (Baraja el mazo.)","f":"\"Tengo lo justo que necesitamos.\" — Forja"},
  "51027": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "51028": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "51029": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "51030": {"n":"Las Dora Milaje","t":"Ignora el coste en recursos de esta carta si tu Superhéroe tiene el rasgo Wakanda.\nAcción: agota Las Dora Milaje → resuelve una capacidad \"Especial\" de 1 Aliado Dora Milaje y cura 1 de Daño a ese Aliado."},
  "51031": {"n":"La sombra de T'Challa","t":"Dale esta carta al jugador que lleva a Shuri.\nUsos (4 contadores de Duda). Victoria 0.\nAumenta en 1 el coste en recursos de cada carta que juegues.\nRespuesta obligada: después de que intervengas, ataques o defiendas, quita 1 contador de Duda de esta carta."},
  "51032": {"t":"[star] Interrupción obligada: cuando Klaw ataque, dale 1 carta de aumento para esta activación.\n(Esbirro Archienemigo de Pantera Negra.)","f":"\"Una vez suene mi dulce música...¡el mundo será mío!\""},
  "51033": {"n":"M.U.S.I.C.A. manipulada","t":"Cuando se muestre esta carta: localiza a M.U.S.I.C.A. y ponla en juego enfrentada a ti.\nCuando se derrote esta carta: descarta a M.U.S.I.C.A. del juego.","f":"Klaw pretende utilizar los poderes de la muchacha a la que llama M.U.S.I.C.A. para controlar las mentes de todos los habitantes del mundo."},
  "51034": {"n":"M.U.S.I.C.A.","t":"Cuando se muestre esta carta: localiza M.U.S.I.C.A. manipulada y ponla en juego.\nCuando se derrote esta carta: traslada toda la Amenaza desde M.U.S.I.C.A. manipulada hasta el Plan principal."},
  "51035": {"n":"El Grito","t":"Cuando se muestre esta carta: aturde a todos los personajes que controles. Inflige 1 de Daño a cada uno de esos personajes que ya estuviera aturdido.\n[star] Aumento: quedas aturdido. Si ya estabas aturdido, sufres 1 de Daño."},
  "51036": {"n":"Redención","t":"Enlazada (Muestra de empatía). Victoria 0.\nToma el control del Esbirro vinculado y trátalo como si fuese un Aliado Redimido con el texto de reglas en blanco. Su valor de INT es igual a su valor impreso de PLA y sufre 1 de Daño derivado después de intervenir o atacar."},
  "51037": {"n":"Lobo Blanco","t":"[star] Respuesta obligada: después de que el Lobo Blanco ataque, coloca 1 de Amenaza sobre el Plan principal.","f":"Como miembro de la Hatut Zeraze (la policía secreta de Wakanda), el Lobo Blanco está dispuesto a emplear métodos extremos para defender su nación adoptiva."},
  "51038": {"n":"Oteador","t":"Usos (2 contadores de Objetivo).\nInterrupción: cuando un Esbirro vaya a enfrentarse a un jugador, quita 1 contador de Objetivo de esta carta → ese Esbirro no podrá activarse hasta el final de la fase. Enfréntate a ese Esbirro."},
  "51039": {"t":"Infame. Victoria 1.\n[star] Interrupción obligada: cuando Joystick se activa contra ti, elige una opción:\n• Dale 1 carta de aumento adicional para esta activación y roba 1 carta.\n• Dale una carta de Estado \"Duro\"."},
  "51040": {"n":"Porra de energía","t":"Vincula esta carta a Joystick. De no ser posible, Vincula esta carta al Villano.\n[star] Los ataques del enemigo vinculado ganan Penetrante.\nAcción de Héroe: el enemigo vinculado te ataca. Después de este ataque, descarta esta carta y roba 1 carta."},
  "51041": {"n":"A por todas","t":"Cada Superhéroe recibe +1 al tamaño de su mano.\nInterrupción obligada: cuando se active un enemigo, dale 1 carta de aumento para esta activación (además de las otras cartas de aumento que reciba).","f":"\"Procura seguirme el ritmo.\" —Joystick"},
  "51042": {"n":"Riesgo extremo","t":"Cuando se muestre esta carta: localiza a Joystick y muéstrala. (Si ya está en juego, se enfrenta a ti.) Joystick se activa contra ti. Si no se activa ningún enemigo de este modo, esta carta gana Oleada.\n[star] Aumento: puedes darle al enemigo activado una carta de aumento adicional. Si lo haces, roba 1 carta."},
  "52001a": {"n":"Seda","t":"Si hay más de 4 cartas metidas debajo de ésta, descártalas todas menos 4.\nSentido sedoso — Respuesta: después de que derrotes a un Esbirro o Plan secundario, o resuelvas una carta de Perfidia, mete esa carta debajo de ésta desde la pila de descartes del mazo de Encuentros."},
  "52001b": {"t":"Si hay más de 4 cartas metidas debajo de ésta, descártalas todas menos 4.\nAcción: descarta una carta que esté metida debajo de ésta → roba 2 cartas. (Límite de una vez por ronda.)","f":"\"Hay cosas que no encajan.\""},
  "52002": {"n":"Suave como la Seda","t":"Acción de Héroe: elige un enemigo o Plan que esté en juego → descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte una carta del mismo conjunto de Encuentros que la carta elegida. Mete esa carta descartada debajo de Seda."},
  "52003": {"n":"Balanceo con patada","t":"Acción de Héroe (ataque): inflige 7 de Daño a un enemigo. Puedes descartar una carta que esté metida debajo de Seda y pertenezca al mismo conjunto de Encuentros que ese enemigo. Si lo haces, este ataque inflige 2 de Daño adicional y gana Brutalidad."},
  "52004": {"n":"Trepar por las paredes","t":"Acción de Héroe (intervención): quita 2 de Amenaza de un Plan. Elije un Plan. Puedes descartar una carta que esté metida debajo de Seda y pertenezca al mismo conjunto de Encuentros que el Plan elegido para quitar 3 de Amenaza del Plan elegido."},
  "52005": {"n":"Conseguir la exclusiva","t":"Acción de Alter ego: agota tu Superhéroe → quita 2 de Amenaza de esta carta. Cualquier jugador puede aplicar esta capacidad.\nCuando se derrote esta carta: el jugador que lleva a Cindy Moon mira las 2 primeras cartas del mazo de Encuentros y mete 1 de esas cartas debajo de su Superhéroe."},
  "52006": {"t":"Acción de Alter ego: agota a Albert Moon → elige una opción:\n• Mete la primera carta del mazo de Encuentros debajo de Cindy Moon.\n• Cura 1 de Daño a Cindy Moon por cada carta metida debajo."},
  "52007": {"t":"Acción de Alter ego: agota esta carta → busca Conseguir la exclusiva en tu mazo y en tu pila de descartes y ponla en juego.\nAcción: agota esta carta → quita 2 de Amenaza de un Plan secundario.","f":"\"Me gustas, Analógica.\""},
  "52008": {"n":"Memoria Eidética","t":"Interrupción: cuando muestres una carta del mismo conjunto de Encuentros que una carta que esté metida debajo de tu Superhéroe, agota Memoria Eidética → intercambia esas cartas. Muestra la carta que estaba metida debajo de Seda en vez de la otra."},
  "52009": {"n":"Lanzaredes orgánicos","t":"Seda recibe +1 INT.\nAcción de Héroe: agota los Lanzaredes orgánicos y descarta una carta que esté metida debajo de Seda → prepara a Seda. Gana el rasgo Aéreo hasta el final de la ronda."},
  "52010": {"n":"Treta astuta","t":"Interrupción de Héroe: cuando Seda realice una intervención básica, agota Treta astuta → para esta intervención recibe +1 INT por cada carta que tenga metida debajo que pertenezca al mismo conjunto de Encuentros que el Plan intervenido."},
  "52011": {"n":"Garras de araña","t":"Interrupción de Héroe: cuando Seda realice un ataque básico, agota Garras de araña → para este ataque recibe +1 ATQ por cada carta que tenga metida debajo que pertenezca al mismo conjunto de Encuentros que el enemigo atacado. Este ataque gana Penetrante."},
  "52012": {"n":"Reflejos arácnidos","t":"Interrupción de Héroe: cuando Seda defienda, agota Reflejos arácnidos → para este ataque recibe +1 DEF por cada carta que tenga metida debajo que pertenezca al mismo conjunto de Encuentros que el enemigo atacante. Después de este ataque, mete debajo de Seda la primera carta de la pila de descartes del mazo de Encuentros."},
  "52013": {"n":"Araña Escarlata","t":"Interrupción: cuando otro personaje Guerrero araña vaya a sufrir cualquier cantidad de Daño, la Araña Escarlata sufre ese Daño en su lugar.","f":"\"Pito pito, arañitas, dónde vais con tantas ganas,\nuna toda escarlata y la otra azulgrana!\""},
  "52014": {"t":"El coste para jugar a Spider-Byte se reduce en 1 por cada carta de Tecnología que controles.","f":"\"¡Soy tu amistosa lanzaredes de la realidad virtual!\""},
  "52015": {"n":"¡No será hoy!","t":"Interrupción de Héroe (defensa): cuando tu Héroe defienda contra un ataque, recibe +2 DEF para ese ataque. Si no sufres Daño a consecuencia de ese ataque, quita 2 de Amenaza de un Plan."},
  "52016": {"n":"\"No te pegues más\"","t":"Respuesta de Héroe (ataque): después de que defiendas contra un ataque enemigo y no sufras ningún Daño, inflige tanto Daño a ese enemigo como la puntuación de DEF que tenías para ese ataque."},
  "52017": {"n":"Doctora Sinclair","t":"Acción de Alter ego: agota a la Doctora Sinclair y gasta un recurso [mental] → cura tanto Daño a tu Alter ego como tu puntuación de REC. Puedes descartar 1 carta de Estado de tu Superhéroe. Cualquier jugador puede aplicar esta capacidad."},
  "52018": {"n":"Escudo de energía","t":"Vincula esta carta a un personaje. Máximo de 1 por personaje.\nInterrupción: cuando el personaje vinculado vaya a sufrir cualquier cantidad de Daño, gasta X recursos [energy] → evita X de ese Daño."},
  "52019": {"n":"Listos para luchar","t":"Requisito ([physical]). Máximo de 1 por jugador.\nInterrupción: cuando un enemigo vaya a ejecutar el Plan, descarta Listos para luchar → cambia a tu identidad de Héroe. Ese enemigo te ataca en vez de ejecutar el Plan."},
  "52020": {"n":"Pistola eléctrica","t":"Restringida. Usos (2 contadores de Carga).\nAcción de Héroe: agota la Pistola eléctrica y quítale 1 ó 2 contadores de Carga → si has quitado:\n• 1 contador de Carga, aturde a un Esbirro.\n• 2 contadores de Carga, aturde al Villano."},
  "52021": {"t":"Respuesta: después de que Madame Web entre en juego, mira las X primeras cartas del mazo de Encuentros, siendo X el número de cartas Guerrero araña que controles. Puedes descartar 1 de las cartas que has mirado de este modo y devolver el resto en cualquier orden."},
  "52022": {"n":"Spiderman","t":"Requisito ([energy] [mental] [physical]).\nRespuesta: después de que Spiderman ataque o intervenga, elige otro personaje Guerrero Araña → prepara ese personaje.","f":"\"¿Te das cuenta, Miles? Así es como se hace.\""},
  "52023": {"n":"Multiverso arácnido","t":"Máximo de 1 por mazo.\nAcción de Héroe: agota una carta Guerrero Araña que controles → busca un Aliado Guerrero Araña en tu pila de descartes y ponlo en juego, luego elige a un jugador. Ese jugador puede gastar 3 recursos de cualquier tipo para volver a usar esta capacidad."},
  "52024": {"n":"Periodismo de investigación","t":"Equipo (Cindy Moon y Peter Parker). Máximo de 1 por mazo.\nInterrupción de Alter ego: cuando un enemigo vaya a ejecutar el Plan, anula esa activación y confunde a ese enemigo."},
  "52025": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "52026": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "52027": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "52028": {"n":"Sobrecarga extrasensorial","t":"Dale esta carta al jugador que lleva a Cindy Moon.\nInterrupción obligada: cuando vaya a meterse una carta debajo de tu Superhéroe por efecto de una carta de Jugador, en vez de eso métela debajo de esta carta. Luego, si hay 2 cartas metidas debajo de ésta, puedes descartar esta carta (si tiene al menos 3 cartas metidas debajo, en vez de eso se retira de la partida)."},
  "52029": {"t":"[star] Morlun recibe +1 PLA y +1 ATQ por cada carta de Encuentro que haya metida debajo de cada Superhéroe.\nCuando se derrote esta carta: descarta todas las copias de La caza de la novia araña que estén metidas debajo de cada Superhéroe."},
  "52030": {"n":"La gran cacería","t":"Cuando se muestre esta carta: coloca 1 de Amenaza adicional sobre esta carta por cada carta que haya metida debajo de cada Superhéroe.","f":"\"Ahí estás. La tejedora en el centro de la red. Empieza la gran cacería.\" —Morlun"},
  "52031": {"n":"La caza de la novia araña","t":"Oleada.\nCuando se muestre esta carta: si tienes 4 cartas metidas debajo de tu Superhéroe, descarta 1 de ellas al azar. mete esta carta debajo de tu Superhéroe.\nRespuesta obligada: después de que el efecto de una carta de Jugador descarte esta carta de debajo de un Superhéroe, ese Superhéroe sufre 2 de Daño."},
  "52032": {"n":"SpiderMan 2099","t":"[star] Respuesta: después de que Spider-Man 2099 use un atributo básico, devuelve un Aliado Guerrero araña que esté en juego a la mano de su propietario.","f":"\"Ése soy yo: el Spider-Man del mañana, que ha venido a salvar el hoy!\""},
  "52033": {"n":"Spiderwoman","t":"Respuesta: después de que entre en juego un Aliado Guerrero araña (incluido éste), inflige 1 de Daño a un enemigo.","f":"\"¡Todo el mundo debería ver lo que está a punto de pasar!\""},
  "52034": {"n":"Burla ocurrente","t":"Requisito ([mental]).\nAcción de Héroe: inflige 1 de Daño a un personaje Guerrero araña que controles → coloca un total de 2 cartas de Estado \"Confundido\" en un máximo de 2 enemigos.","f":"\"¡Tenemos más tentáculos que un restaurante de sushi!\" —Spider-Man"},
  "52035": {"t":"Infame. Victoria 1.\n[star] Atlas recibe +2 de Vida por cada contador de Crecimiento que tenga encima.\nRespuesta obligada: después de que termine la fase del Villano, coloca 1 contador de Crecimiento sobre Atlas."},
  "52036": {"n":"Gigante invulnerable","t":"Cuando se muestre esta carta: coloca 1 de Amenaza adicional sobre esta carta por cada contador de Crecimiento que haya encima de Atlas.\nSi Atlas tiene encima 10 contadores de Crecimiento o más, los jugadores pierden la partida."},
  "52037": {"n":"Crecimiento fuerte","t":"Cuando se muestre esta carta: localiza a Atlas y muéstralo. (Si ya está en juego, se enfrenta a ti.) Atlas se activa contra ti. Si no se activa ningún enemigo de este modo, esta carta gana Oleada.\n[star] Aumento: dale al enemigo activado una carta de Estado \"Duro\"."},
  "52038": {"n":"Proporciones titánicas","t":"Cuando se muestre esta carta: los jugadores sufren colectivamente X de Daño indirecto, siendo X el número de contadores de Crecimiento que haya sobre Atlas. Si X es menor a 3, esta carta gana Oleada.\n[star] Aumento: si Atlas está en juego, coloca 1 contador de Crecimiento sobre su carta."},
  "53001a": {"n":"Halcón","t":"Durante la fase de los Jugadores, juega con la primera carta del mazo de Encuentros boca arriba.\nVista de águila — Respuesta: después de que juegues una carta Aéreo, descarta la primera carta del mazo de Encuentros."},
  "53001b": {"t":"Mismo plumaje — Acción: descarta 1 carta de tu mano → busca una carta Pájaro en tu mazo y en tu pila de descartes, y añádela a tu mano. (Límite de una vez por ronda.)"},
  "53002": {"n":"Ala Roja","t":"Acción de Héroe: agota a Ala Roja, devuélvelo a tu mano y descarta primera carta del mazo de Encuentros → elige entre infligir X de Daño a un enemigo o quitar X de Amenaza de un Plan. X es el número de iconos ([star] y [boost]) que haya en el recuadro de aumentos de la carta descartada."},
  "53003": {"n":"Ave de presa","t":"Acción de Héroe (ataque): inflige 4 de Daño a un enemigo. Puedes descartar la primera carta del mazo de Encuentros para infligir 1 de Daño adicional a ese enemigo por cada icono ([star] y [boost]) que haya en el recuadro de aumentos de la carta descartada."},
  "53004": {"n":"A vista de pájaro","t":"Acción de Héroe (intervención): quita 3 de Amenaza de un Plan. Puedes descartar la primera carta del mazo de Encuentros para quitar 1 de Amenaza adicional de ese Plan por cada icono ([star] y [boost]) que haya en el recuadro de aumentos de la carta descartada."},
  "53005": {"n":"Salir volando","t":"Respuesta de Héroe (defensa): después de que un enemigo atacante reciba una carta de aumento boca abajo, mira esa carta y la primera carta del mazo de Encuentros. Puedes intercambiar esas cartas. Roba 1 carta por cada icono impreso ([star] y [boost]) que haya en el recuadro de aumentos de la (actual) cada de aumento."},
  "53006": {"n":"Bandada del Halcón","t":"Usos (5 contadores de Pájaro).\nRecurso: quita 1 contador de Pájaro de esta carta → genera un recurso [energy] para una carta Aéreo. (Límite de una vez por carta.)","f":"\"En mi caso, más vale ciento volando\" —Halcón"},
  "53007": {"n":"Comedor social","t":"Acción de Alter ego: agota a Sam Wilson y el Comedor social → cura tanto Daño a Sam Wilson como su REC y reduce en 2 el coste del siguiente Aliado o Apoyo que se juegue en esta fase.","f":"Siguiendo el ejemplo de sus padres, Sam procura servir de ejemplo para otros."},
  "53008": {"n":"Evacuación Aérea","t":"Interrupción de Héroe: cuando se vaya a infligir cualquier cantidad de Daño, descarta Evacuación Aérea → evita todo ese Daño y cambia a la identidad de tu Alter ego. Si ese personaje es un Héroe, también cambia a la identidad de su Alter ego."},
  "53009": {"n":"Reconocimiento Aéreo","t":"Acción de Héroe: agota Reconocimiento Aéreo y dale a un jugador 1 carta de Encuentro boca abajo → coloca 1 contador de Reconocimiento sobre esta carta.\nInterrupción: cuabndo un jugador vaya a recibir una carta de Encuentro, en vez de eso quita 1 contador de Reconocimiento de esta carta."},
  "53010": {"n":"Vista panorámica","t":"Interrupción de Héroe: cuando el Halcón use un atributo básico, agota Vista panorámica y descarta la primera carta del mazo de Encuentros → el Halcón recibe +1 en ese atributo para este uso por cada icono ([star] y [boost]) que haya en el recuadro de aumentos de la carta descartada."},
  "53011": {"n":"Atraer los disparos","t":"Respuesta de Héroe: después de que empiece la fase del Villano, descarta Atraer los disparos → el Halcón no se agota para defender hasta el final de la fase.","f":"\"¡Puedo pegarme todo el día así!\" —Halcón"},
  "53012": {"n":"Espolón de caza","t":"Respuesta de Héroe: después de que resuelvas la capacidad \"Vista de águila\" del Halcón, descarta el Espolón de caza → por cada icono que haya en el recuadro de aumentos de la carta descartada, elige una opción:\n• Prepara un personaje que controles.\n• Aturde a un enemigo."},
  "53013": {"n":"Microtejido de vibránium","t":"El Halcón recibe +1 DEF.\nInterrupción de Héroe: cuando el Halcón vaya a sufrir cualquier cantidad de Daño, agota el Microtejido de vibránium → evita 1 de ese Daño e inflige 1 de Daño a un enemigo."},
  "53014": {"t":"Respuesta: después de que Adam Warlock ataque o intervenga, descarta 1 carta de tu mano al azar. Si el recurso impreso de esa carta tiene:\n[physical] - Quita 3 de Amenaza de un plan.\n[energy] - Cura 3 de Daño a un Superhéroe.\n[mental] - Inflige 3 de Daño a un enemigo.\n[wild] - Elige una de las opciones anteriores."},
  "53015": {"t":"Acción de Héroe: agota a Aero → elige un jugador. Hasta el final de la fase, cada personaje Aéreo que controle ese jugador recibe +1 ATQ.","f":"\"Noto una perturbación en el viento.\""},
  "53016": {"n":"Nube 9","t":"Acción de Héroe: agota a Nube 9 → elige un jugador. Hasta el final de la fase, todo personaje Aéreo controlado por ese jugador recibe +1 INT.","f":"\"¡Sólo estoy aquí porque quiero volar!\""},
  "53017": {"n":"Hugin y Munin","t":"Respuesta: después Hugin y Munin entren en juego, busca un Esbirro entre las 10 primeras cartas del mazo de Encuentros y ponlo en juego enfrentado a ti → prepara 1 personaje que controles por cada icono ([star] y [boost]) que haya en el recuadro de aumentos de ese Esbirro."},
  "53018": {"t":"Respuesta: después de que juegues a Spectrum, mete debajo de su carta 1 de las cartas que hayas usado para pagar su coste. Si el recurso impreso de esa carta tiene:\n[mental] – Spectrum recibe +2 INT.\n[physical] – Spectrum recibe +2 ATQ.\n[energy] – Spectrum recibe +2 de Vida.\n[wild] – Todo lo anterior."},
  "53019": {"n":"Diversificación","t":"Alianza.\nAcción de Héroe: por cada Rasgo distinto que tengan los personajes amigos que estén en juego, elige una opción:\n• Quita 1 de Amenaza de un Plan.\n• Inflige 1 de Daño a un enemigo."},
  "53020": {"n":"Escuadrón de voladores","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Aéreo. Máximo de 1 carta de Grupo por jugador.\nSi todos tus Aliados tiene el rasgo Aéreo, tu límite de Aliados se incrementa en 1 y esta carta gana: \"Respuesta: después de que juegues una carta Aéreo, agota esta carta → prepara un Aliado que controles.\""},
  "53021": {"n":"Reserva de recursos","t":"Máximo de 1 por jugador.\nCualquier jugador puede gastar la carta de recurso que esté metida debajo de esta carta como si estuviese en su mano.\nAcción: agota Reserva de recursos → mete debajo de esta carta 1 carta de recurso desde tu mano (Hasta un máximo de 1)."},
  "53022": {"n":"El Triskelion","t":"Tu límite de Aliados se incrementa en 1. (Esto te permite controlar más de 3 Aliados.)","f":"\"¿Crees que lo han construido lo bastante alto?\" —Hulka"},
  "53023": {"n":"Capitán América","t":"Juega esta carta sólo si eres el jugador que lleva a Bucky Barnes o Sam Wilson.\nAcción de Héroe: agota al Capitán América y gasta un recurso [physical] → localiza el Escudo del Capitán América y añádelo a tu mano. Si abandona el juego de este modo, inflige 4 de Daño a un enemigo."},
  "53024": {"n":"Compañero de vuelo","t":"Vincula esta carta a un Aliado Aéreo. Máximo de 1 por Aliado.\nInterrupción: cuando otro Aliado Aéreo vaya a sufrir cualquier cantidad de Daño derivado, agota al Aliado vinculado → evita 1 de ese Daño."},
  "53025": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "53026": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "53027": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "53028": {"n":"El poder del vuelo","t":"El número de recursos generados por esta carta se duplica al pagar el coste de una carta con el rasgo AÉREO."},
  "53029": {"n":"El protector de Harlem","t":"Dale esta carta al jugador que lleva a Sam Wilson.\nUsos (3 contadores de Emergencia). Victoria 0.\nAcción de Alter ego: gasta 1 recurso de cualquier tipo → quitar 1 contador de Emergencia de esta carta."},
  "53030": {"n":"Víbora","t":"Ataque veloz.\n[star] Respuesta obligada: después de que Víbora se active, descarta las 5 primeras cartas del mazo de Encuentros.\n(Esbirro Archienemigo de Halcón.)"},
  "53031": {"n":"Soluciones Serpiente","t":"Respuesta obligada: después de que se descarte un Esbirro Sociedad Serpiente de la parte superior del mazo de Encuentros, dale ese Esbirro al jugador inicial como carta de Encuentro boca abajo.","f":"\"Si tiene problemas, necesita a Soluciones Serpiente.\" —Víbora"},
  "53032": {"n":"Soldado Serpiente","t":"Ataque veloz.\n[star] Aumento: dale al enemigo activado una carta de aumento adicional."},
  "53033": {"n":"Publicidad viperina","t":"Oleada.\nCuando se muestre esta carta: devuelve al mazo de Encuentros todos los Esbirros Sociedad Serpiente que haya en su pila de descartes y barájalo.","f":"Cuando Víbora asumió el mando de la Sociedad Serpiente, utilizó su experiencia como publicista para rebautizar el grupo como \"Soluciones Serpiente.\""},
  "53034": {"n":"Escudo del Capitán América","t":"Enlazada (Mejora del Capitán América). Restringida.\nTu Héroe recibe +1 DEF y gana Represalia 1.","f":"\"Este escudo es un símbolo de libertad.\" —Capitán América"},
  "53035": {"n":"Soldado de Invierno","t":"Respuesta: después de que el Soldado de Invierno ataque y derrote a un enemigo, quita 2 de Amenaza de un Plan.","f":"\"Mientras viva, nunca lucharás solo.\""},
  "53036": {"t":"[star] Interrupción: cuando Misty Knight intervenga, mira las 2 primeras cartas del mazo de Encuentros y descarta 1 de ellas. Misty Knight recibe +1 INT para esta intervención por cada icono ([star] y [boost]) que haya en el recuadro de aumentos de la carta descartada."},
  "53037": {"n":"Sala de operaciones","t":"Usos (3 contadores de Alerta).\nInterrupción: cuando un personaje amigo vaya a sufrir cualquier cantidad de Daño al defender, quita 1 contador de Alerta de esta carta → evita 1 de ese Daño y quita 1 de Amenaza de un Plan."},
  "53038": {"n":"Arreglador","t":"Infame. Victoria 1.\nInterrupción obligada: cuando vaya a vincularse al Villano un Accesorio Tecnología que no sea específico de un escenario, en vez de eso vincúlalo al Arreglador. El texto de esa carta que aluda al \"Villano\" aludirá al Arreglador en su lugar."},
  "53039": {"n":"Mochila propulsora","t":"Vincula esta carta al Arreglador. De no ser posible, vincula esta carta al Villano.\nEl enemigo vinculado gana Aéreo.\nInterrupción obligada: cuando el personaje vinculado vaya a sufrir al menos 3 de Daño, evita todo ese Daño y descarta la Mochila propulsora."},
  "53040": {"n":"Tecnomochila","t":"Vincula esta carta al Arreglador. De no ser posible, vincula esta carta al Villano.\n[star] El enemigo vinculado recibe +1 ATQ por cada Accesorio Tecnología que tenga vinculado además de éste.\nAcción de Héroe: agota cualquier cantidad de personajes que controles y cuya INT combinada sume más que el PLA del enemigo vinculado → descarta esta carta."},
  "53041": {"n":"Innovación tecnológica","t":"Cuando se muestre esta carta: busca un Accesorio Tecnología en el mazo de Encuentros y en su pila de descartes y muéstralo. Coloca 1 de Amenaza adicional sobre esta carta por cada carta Tecnología que haya en juego.","f":"\"¡Volveré toda su tecnología en su contra!\" —Arreglador"},
  "53042": {"n":"Tecno","t":"Cuando se muestre esta carta: localiza al Arreglador y muéstralo. (si ya está en juego, se enfrenta a ti.) Arreglador se activa contra ti. Si no se activa ningún enemigo de este modo, esta carta gana Oleada.\n[star] Aumento: Si esta activación es un ataque, gana Penetrante."},
  "54001a": {"n":"Soldado de Invierno","t":"Protector letal — Respuesta: después de que ataques y derrotes a un enemigo, quita 2 de Amenaza de un Plan.","f":"\"En la Sala Roja me entrenaron para hacer cosas horribles. Ahora utilizo esas habilidades para proteger a los demás.\""},
  "54001b": {"t":"Ciberimplante — Acción: gasta 1 recurso de cualquier tipo → busca el Brazo cibernético en tu mazo y en tu pila de descartes y ponlo en juego. (Baraja el mazo.)","f":"\"No está nada mal para un veterano de noventa y nueve años.\""},
  "54002": {"n":"Brazo cibernético","t":"Recurso: agota el Brazo cibernético → genera un recurso [wild] para un Evento de Ataque. Ese Evento inflige 1 de Daño adicional.","f":"\"Bucky ya era un buen luchador antes de que le implantaran ese brazo. Con él, directamente da miedo.\" —Steve Rogers"},
  "54003": {"n":"Viuda Negra","t":"Respuesta: después de que juegues la Viuda Negra desde tu mano, devuelve a tu mano un Evento de Ataque que esté en tu pila de descartes."},
  "54004": {"n":"Bloquear con el brazo","t":"Interrupción de Héroe (ataque/defensa): cuando un enemigo ataque, inflíngele 3 de Daño. Si has agotado el Brazo cibernético para pagar el coste de este Evento, evitas todo el Daño de ese ataque del enemigo."},
  "54005": {"n":"Puño de metal","t":"Acción de Héroe (ataque): inflige 7 de Daño a un enemigo. Si has agotado el Brazo cibernético para pagar el coste de este Evento, este ataque gana Brutalidad."},
  "54006": {"n":"Descarga eléctrica","t":"Acción de Héroe (ataque): inflige 4 de Daño a un enemigo. Si has pagado el coste de este Evento usando un recurso [energy], aturde a ese enemigo.","f":"\"Los dejarías igual de tiesos si les enseñaras tus fotos del instituto.\" —Viuda Negra"},
  "54007": {"n":"Piso franco nº 30","t":"Acción de Alter ego: agota el Piso franco nº 30 → busca un Esbirro en el mazo de Encuentros y ponlo en juego enfrentado a ti. (Baraja el mazo.) Luego roba 1 carta.","f":"\"A que no adivinas quién se ha mudado a la casa de al lado.\" —Bucky Barnes"},
  "54008": {"n":"Infiltración silenciosa","t":"Respuesta de Héroe: después de que ataques y derrotes a un enemigo, descarta esta carta → prepara tu Héroe y confunde a un enemigo.","f":"\"Ni siquiera lo verán venir.\" —Soldado de Invierno"},
  "54009": {"n":"Armadura de invierno","t":"Recibes +3 de Vida y ganas Tesón.","f":"\"Puede que el brazo sea a prueba de balas, pero todo lo demás sigue siendo de carne y hueso.\" —Soldado de Invierno"},
  "54010": {"n":"Máscara de invierno","t":"Ganas el rasgo Espía.\nRespuesta de Héroe: después de que ataques y derrotes a un enemigo, agota la Máscara de invierno → roba 1 carta."},
  "54011": {"n":"Fusil de invierno","t":"Restringida.\nInterrupción de Héroe: cuando Soldado de Invierno realice un ataque básico, agota el Fusil de invierno → el Soldado de Invierno recibe +2 ATQ para esta ataque. Este ataque gana A distancia y Penetrante."},
  "54012": {"n":"Capitán América","t":"Dureza.\nRespuesta: después de que Capitán América entre en juego, prepara un personaje S.H.I.E.L.D..","f":"\"¡En pie, soldado!\""},
  "54013": {"t":"Respuesta: después de que Deathlok entre en juego, busca una copia de Pistola de S.H.I.E.L.D. en tu mazo y tu pila de descartes y vincúlasela. (Baraja el mazo.)","f":"\"Mi cuerpo tiene implantado armamento de tecnología punta que puedo controlar con la mente.\""},
  "54014": {"n":"Potencia de fuego","t":"Acción de Héroe (ataque): agota hasta 3 Mejoras Arma que controles → por cada Mejora agotada de este modo, elige un enemigo e inflíngele 3 de Daño. Este ataque gana A distancia."},
  "54015": {"n":"Uno por uno","t":"Acción de Héroe (ataque): inflige 2 de Daño a un enemigo. Si este ataque derrota a ese enemigo, inflige 2 de Daño a un enemigo.","f":"\"Tengo muchos más trucos en la manga, damas y caballeros.\" —Moon Girl"},
  "54016": {"n":"Buscando pelea","t":"Acción de Héroe: descarta cartas de la parte superior del mazo de Encuentros hasta que descartes un Esbirro. Pon en juego ese Esbirro enfrentado a ti → prepara tu Héroe."},
  "54017": {"n":"Postura agresiva","t":"Máximo de 1 por jugador.\nRespuesta de Héroe: después de que te enfrentes a un Esbirro, descarta esta carta → busca en tu mazo un Evento de Ataque y añádelo a tu mano. (Baraja el mazo.)"},
  "54018": {"t":"Vincula esta carta a un personaje S.H.I.E.L.D.. Mientras esté vinculada a un Superhéroe, esta carta gana Restringida. Usos (3 contadores de Munición).\nInterrupción: cuando el personaje vinculado realice un ataque básico, quita 1 contador de Munición de esta carta → este ataque inflige 3 de Daño adicional y gana Brutalidad."},
  "54019": {"n":"El hombre en la muralla","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Soldado.\nAcción de Héroe: agota El hombre en la muralla → el coste de la próxima carta que juegues en esta fase se reduce en 1 por cada Esbirro que haya enfrentado a ti."},
  "54020": {"n":"Pistola de S.H.I.E.L.D.","t":"Vincula esta carta a un personaje S.H.I.E.L.D.. Límite de 1 por personaje. Usos (3 contadores de Munición).\nInterrupción: cuando el personaje vinculado realice un ataque básico, agota la Pistola de S.H.I.E.L.D. y quítale 1 contador de Munición → inflige 1 de Daño a un enemigo."},
  "54021": {"n":"Nick Furia (Padre)","t":"Respuesta obligada: después de que Nick Furia (Padre) entre en juego, elige una opción: quita 3 de Amenaza de un Plan, roba 2 cartas o dale una carta de Estado \"Duro\" a un personaje S.H.I.E.L.D.. Al final de la ronda, si Nick Furia (Padre) aún sigue en juego, descártalo."},
  "54022": {"n":"Supersoldados","t":"Equipo (Capitán América y Soldado de Invierno). Máximo de 1 por mazo.\nAcción de Héroe (ataque): inflige 6 de Daño a un enemigo. Dales al Capitán América y al Soldado de Invierno una carta de Estado \"Duro\"."},
  "54023": {"n":"Invierno, Viuda, soldado, espía","t":"Equipo (Viuda Negra y Soldado de Invierno). Máximo de 1 por mazo.\nAcción de Héroe (ataque): pon en juego una Mejora Planificación desde tu pila de descartes. Inflige 4 de Daño a un enemigo."},
  "54024": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "54025": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "54026": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "54027": {"n":"Adoctrinado en la Sala Roja","t":"Dale esta carta al jugador que lleva a Bucky Barnes.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n• Agota a Bucky Barnes → retira esta carta de la partida.\n• Descarta la carta con el coste impreso más alto que tengas en la mano y sufre tanto Daño indirecto como su coste. Descarta esta Obligación."},
  "54028": {"n":"Calavera","t":"Ataque veloz.\n[star] Respuesta obligada: después de que Calavera ataque y derrote a un Aliado, coloca 2 de Amenaza sobre el Plan principal.\n(Esbirro Archienemigo del Soldado de Invierno.)"},
  "54029": {"n":"Escuadrón de la muerte de Hydra","t":"Cada Esbirro Hydra recibe +1 ATQ y +2 de Vida.\nCuando se derrote esta carta: el jugador que haya derrotado este Plan busca un Esbirro Hydra en el mazo de Encuentros y lo muestra. (Baraja el mazo.)","f":"Calavera dirige su propio equipo de sicarios de Hydra escogidos a dedo."},
  "54030": {"n":"Armamento de tecnología punta","t":"Vincula esta carta a Calavera. De no ser posible, vincula esta carta al Villano.\nRespuesta obligada: después de que vincules Armamento de tecnología punta a un enemigo, ese enemigo se activa contra ti.\nAcción de Héroe: agota a un personaje que controles → descarta esta carta."},
  "54031": {"n":"Mercenario de Hydra","t":"Guardia. (While this minion is enfrentado a ti, you cannot ataque Villano.)","f":"\"¿Que hace Hydra aquí?\" —Carol Danvers"},
  "54032": {"n":"Viuda Blanca","t":"Respuesta: después de que resuelvas la capacidad de una carta de Planificación que controles, cura tanto Daño a la Viuda Blanca como el coste en recursos impreso de esa carta.","f":"\"Sorpresa.\""},
  "54033": {"n":"Reclutado por S.H.I.E.L.D.","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo S.H.I.E.L.D..\nVincula esta carta a un personaje amigo.\nEl personaje vinculado recibe +1 de Vida y gana el rasgo S.H.I.E.L.D.."},
  "54034": {"n":"Ventisca","t":"Infame. Victoria 1.\n[star] Respuesta obligada: después de que Ventisca ataque a un personaje, busca Atrapado en hielo en el mazo y la pila de descartes de Encuentros y vincúlala a ese personaje. (Baraja el mazo.) De no ser posible, aturde al personaje atacado."},
  "54035": {"n":"Atrapado en hielo","t":"Vincula esta carta a tu Superhéroe.\nEl personaje vinculado no puede atacar a otro enemigo que no sea esta carta.\nCualquier jugador puede atacar esta carta como si fuese un Esbirro. Si hay al menos 3 de Daño sobre esta carta, traslada al personaje vinculado todo el Daño que haya por encima de 3 y descarta esta carta."},
  "54036": {"n":"Terreno resbaladizo","t":"Respuesta obligada: después de que un Aliado entre en juego, agótalo.","f":"\"¡Mira dónde pisas!\" —Ventisca"},
  "54037": {"n":"Viento blanco","t":"Cuando se muestre esta carta: localiza a Ventisca y muéstralo. (si ya está en juego, se enfrenta a ti.) Ventisca se activa contra ti. Si no se activa ningún enemigo de este modo, esta carta gana Oleada.\n[star] Aumento: quedas aturdido. Si ya estabas aturdido, sufres 1 de Daño."},
  "55001": {"n":"Encantadora","t":"[star] Respuesta obligada: después de que la Encantadora te ataque, coloca 1 contador de Embrujo sobre la carta de Encantamiento que está en tu zona de juego."},
  "55002": {"n":"Encantadora","t":"Tesón. Dureza.\nCuando se muestre esta carta: en modo Normal, pon en juego la carta apartada Futuro de desesperación, luego colócale encima 3[per_hero] de Amenaza adicional.\n[star] Respuesta obligada: después de que Encantadora te ataque, coloca 1 contador de Embrujo sobre la carta de Encantamiento que está en tu zona de juego."},
  "55003": {"n":"Encantadora","t":"Tesón. Dureza.\nCuando se muestre esta carta: pon en juego la carta apartada Futuro de desesperación, luego colócale encima 4[per_hero] de Amenaza adicional.\n[star] Respuesta obligada: después de que Encantadora te ataque, coloca 1 contador de Embrujo sobre la carta de Encantamiento que está en tu zona de juego."},
  "55004a": {"n":"Recalificación territorial","t":"Contenido: Encantadora (I) y Encantadora (II). (Encantadora (II) y Encantadora (III) para jugar en modo Experto.) Conjuntos de Encuentros de la Encantadora y Normal. Un conjunto de Encuentros modular (Magia embaucadora).\nPreparación: aparta a un lado el Plan secundario Futuro de desesperación. Vincula una carta de Mirada hipnótica aleatoria a cada Superhéroe (no se puede mirar el reverso de estas cartas). Aparta a un lado las cartas de Mirada hipnótica que sobren."},
  "55004b": {"n":"Recalificación territorial","t":"Interrupción obligada: cuando vaya a colocarse un contador de Embrujo sobre la carta de Encantamiento que está en tu zona de juego, si tu Superhéroe tiene el rasgo Subyugado, en vez de eso coloca 1 de Amenaza sobre esta carta.","f":"Encantadora prentende conquistar Sudamérica hechizando a todos los que se oponen a ella para convertirlos en esclavos sumisos."},
  "55005a": {"n":"Hechicera soberana","t":"Cuando se muestre esta carta: si está en juego la Diadema de la Encantadora, aturde a todos los Superhéroes. De no ser así, busca la Diadema de la Encantadora en el mazo y la pila de descartes de Encuentros y muéstrala. (Baraja el mazo.)"},
  "55005b": {"n":"Hechicera soberana","t":"Interrupción obligada: cuando vaya a colocarse un contador de Embrujo sobre la carta de Encantamiento que está en tu zona de juego, si tu Superhéroe tiene el rasgo Subyugado, en vez de eso coloca 1 de Amenaza sobre esta carta.\nSi se completa esta etapa, los jugadores pierden la partida."},
  "55006": {"n":"Futuro de desesperación","t":"La Encantadora gana Firmeza y no puede sufrir Daño.\nCuando se muestre esta carta: coloca 1 contador de Embrujo sobre cada carta de Encantamiento que haya en juego."},
  "55007a": {"n":"Mirada hipnótica","t":"Permanente.\nTu Superhéroe gana el rasgo Desafiante.\nSi hay al menos 5 contadores de Embrujo sobre esta carta, quita todos esos contadores de Embrujo y dale la vuelta a esta carta."},
  "55007b": {"n":"Trance de envidia","t":"Permanente.\nTu Superhéroe gana el rasgo Subyugado.\nCuando se muestre esta carta: descarta una carta que controles. De no ser posible, descarta las 8 primeras cartas de tu mazo.\nAcción obligada: agota esta carta → dale a la Encantadora una carta de aumento boca abajo. Prepara tu carta de Superhéroe."},
  "55008a": {"n":"Mirada hipnótica","t":"Permanente.\nTu Superhéroe gana el rasgo Desafiante.\nSi hay al menos 5 contadores de Embrujo sobre esta carta, quita todos esos contadores de Embrujo y dale la vuelta a esta carta."},
  "55008b": {"n":"Trance de avaricia","t":"Permanente.\nTu Superhéroe gana el rasgo Subyugado.\nCuando se muestre esta carta: quedas confundido. De no ser posible, sufres 2 de Daño.\nAcción obligada: agota esta carta → roba 1 carta, luego juega esa carta (pagando su coste). Si no puedes, sufres 1 de Daño."},
  "55009a": {"n":"Mirada hipnótica","t":"Permanente.\nTu Superhéroe gana el rasgo Desafiante.\nSi hay al menos 5 contadores de Embrujo sobre esta carta, quita todos esos contadores de Embrujo y dale la vuelta a esta carta."},
  "55009b": {"n":"Trance de soberbia","t":"Permanente.\nTu Superhéroe gana el rasgo Subyugado.\nCuando se muestre esta carta: agota tu carta de Superhéroe. De no ser posible, descarta 1 carta de tu mano al azar.\nAcción obligada: agota esta carta → coloca 1 de Amenaza sobre el Plan principal. Quita 2 de Amenaza de un Plan secundario."},
  "55010a": {"n":"Mirada hipnótica","t":"Permanente.\nTu Superhéroe gana el rasgo Desafiante.\nSi hay al menos 5 contadores de Embrujo sobre esta carta, quita todos esos contadores de Embrujo y dale la vuelta a esta carta."},
  "55010b": {"n":"Trance de pereza","t":"Permanente.\nTu Superhéroe gana el rasgo Subyugado.\nCuando se muestre esta carta: quedas aturdido. De no ser posible, coloca 2 de Amenaza sobre el Plan principal.\nAcción obligada: agota esta carta → cura 1 de Daño a la Encantadora. Roba 1 carta, luego descarta 1 carta."},
  "55011a": {"n":"Mirada hipnótica","t":"Permanente.\nTu Superhéroe gana el rasgo Desafiante.\nSi hay al menos 5 contadores de Embrujo sobre esta carta, quita todos esos contadores de Embrujo y dale la vuelta a esta carta."},
  "55011b": {"n":"Trance de ira","t":"Permanente.\nTu Superhéroe gana el rasgo Subyugado.\nCuando se muestre esta carta: busca una carta entre las 5 primeras cartas del mazo de Encuentros y muéstrala. (Baraja el mazo.)\nAcción obligada: agota esta carta → sufres 1 de Daño indirecto. Inflige 2 de Daño a un Esbirro."},
  "55012": {"n":"Llamada seductora","t":"Vincula esta carta a tu Superhéroe.\nAcción obligada: agota esta carta → coloca 1 contador de Embrujo sobre la carta de Encantamiento que está en tu zona de juego. Juega una carta de tu mano, reduciendo en 1 su coste en recursos.\nAcción de Alter ego: agota esta carta → descarta esta carta.\n[star] Aumento: muestra esta carta."},
  "55013": {"n":"Beso Tentador","t":"Vincula esta carta a tu Superhéroe.\nAcción obligada: agota esta carta → coloca 1 contador de Embrujo sobre la carta de Encantamiento que está en tu zona de juego. Roba 1 carta, luego descarta 1 carta de tu mano.\nAcción de Alter ego: agota esta carta → descarta esta carta.\n[star] Aumento: muestra esta carta."},
  "55014": {"n":"Filtro de amor","t":"Vincula esta carta a tu Superhéroe.\nAcción obligada: agota esta carta → coloca 1 contador de Embrujo sobre la carta de Encantamiento que está en tu zona de juego. Prepara tu carta de Superhéroe.\nAcción de Alter ego: agota esta carta → descarta esta carta.\n[star] Aumento: muestra esta carta."},
  "55015": {"n":"Seducido","t":"Vincula esta carta a tu Superhéroe.\nNo puedes realizar ataques básicos ni jugar Eventos de Ataque.\nAcción de Alter ego: gasta recursos [energy] [mental] → descarta esta carta.","f":"\"Me amas,¿No es cierto?\" —La Encantadora"},
  "55016": {"n":"Diadema de la Encantadora","t":"Vincula esta carta a la Encantadora.\nEn modo Experto, Encantadora gana Firmeza.\n[star] Respuesta obligada: después de que Encantadora ejecute el Plan contra ti, coloca 1 contador de Embrujo sobre la carta de Encantamiento que está en tu zona de juego.\nAcción de Héroe: cada jugador agota su carta de Superhéroe y sufre 1 de Daño → descarta esta carta."},
  "55017": {"n":"Lacayo subyugado","t":"Ataque veloz.\n[star] Respuesta obligada: después de que este Esbirro te ataque, coloca 1 contador de Embrujo sobre la carta de Encantamiento que está en tu zona de juego.\n[star] Aumento: elige entre colocar 1 contador de Embrujo sobre la carta de Encantamiento que está en tu zona de juego o bien confundir a tu Superhéroe."},
  "55018": {"n":"Bruto Subyugado","t":"Guardia.\n[star] Mientras este Esbirro esté enfrentado a un jugador cuyo Superhéroe tenga el rasgo Subyugado, este Esbirro recibe +3 de Vida.\n[star] Aumento: elige entre coloca 1 contador de Embrujo sobre la carta de Encantamiento que está en tu zona de juego o bien agota a tu Superhéroe."},
  "55019": {"t":"[star] Los ataques de Sindr infligen Daño indirecto.\nCuando se muestre esta carta: si tu Superhéroe tiene el rasgo Desafiante, Sindr se activa contra ti. Si tu Superhéroe tiene el rasgo Subyugado, dale Sindr una carta de Estado \"Duro\"."},
  "55020": {"t":"En modo Experto, Ulik gana Dureza.\nRespuesta obligada: después de que un jugador inflija cualquier cantidad de Daño a la Encantadora, Ulik ataca a ese jugador.\nCuando se derrote esta carta: la Encantadora ataca al jugador que ha derrotado a Ulik y recibe +1 ATQ para ese ataque."},
  "55021": {"n":"Ley de atracción","t":"Cuando se muestre esta carta: descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Esbirro Subyugado. Muestra ese Esbirro.\n[star] Aumento: coloca 1 contador de Embrujo sobre la carta de Encantamiento que está en tu zona de juego."},
  "55022": {"n":"Encandilados","t":"Cuando se muestre esta carta: cada jugador cuyo Superhéroe tenga el rasgo Desafiante coloca 1 contador de Embrujo sobre la carta de Encantamiento que esté en su zona de juego. Cada jugador cuyo Superhéroe tenga el rasgo Subyugado descarta una carta que controle."},
  "55023": {"n":"\"Cumple mi voluntad\"","t":"Cuando se muestre esta carta: si tu Superhéroe tiene el rasgo Desafiante, elige una opción. Si tu Superhéroe tiene el rasgo Subyugado, resuelve las dos opciones en cualquier orden:\n• Busca un Esbirro en el mazo de Encuentros y en su pila de descartes y muéstralo. (Baraja el mazo.)\n• Busca un Plan secundario en el mazo de Encuentros y en su pila de descartes y muéstralo. (Baraja el mazo.)"},
  "55024": {"n":"Ataduras mágicas","t":"Cuando se muestre esta carta: si tu Superhéroe tiene el rasgo Desafiante, elige una opción. Si tu Superhéroe tiene el rasgo Subyugado, resuelve las dos opciones en cualquier orden:\n• quedas aturdido. Coloca 1 contador de Embrujo sobre la carta de Encantamiento que está en tu zona de juego.\n• Quedas confundido. Coloca 1 contador de Embrujo sobre la carta de Encantamiento que está en tu zona de juego."},
  "55025": {"n":"Descarga arcana","t":"Cuando se muestre esta carta: si tu Superhéroe tiene el rasgo Desafiante, elige una opción. Si tu Superhéroe tiene el rasgo Subyugado, resuelve las dos opciones en cualquier orden:\n• La Encantadora ejecuta el Plan (con +1 PLA en modo Experto).\n• La Encantadora te ataca (con +1 ATQ en modo Experto)."},
  "55026": {"n":"Esquirlas arcanas","t":"Cuando se muestre esta carta: sufres 3 de Daño indirecto. Si tu Superhéroe ha sufrido cualquier cantidad de Daño de este modo, coloca 1 contador de Embrujo sobre la carta de Encantamiento que está en tu zona de juego.\n[star] Aumento: coloca 1 contador de Embrujo sobre la carta de Encantamiento que está en tu zona de juego."},
  "55027a": {"n":"Loki, Dios de las Mentiras","t":"Si Loki, Dios de las Mentiras tiene 10[per_hero] o menos de Vida restante, dale la vuelta a esta carta.","f":"\"Arrodillaos.\""},
  "55027b": {"n":"Loki, Dios de las Mentiras","t":"Cuando se muestre esta carta: cada grupo en modo Normal vincula su carta apartada de Concentración intensa al Villano Avatar de Loki que está en su zona de partida. Cada grupo en modo Experto da la vuelta a su carta de Concentración intensa para dejar boca arriba su cara de Concentración total.\nSi Loki, Dios de las Mentiras es derrotado, todos los grupos de jugadores ganan la partida."},
  "55028a": {"n":"Mundos en colisión","t":"Contenido: Loki, Dios de las Mentiras (1). Conjunto de Encuentros del Dios de las Mentiras y Normal. Un conjunto de Encuentros modular (Magia embaucadora).\nPreparación: crea una zona de partida independiente para cada grupo de jugadores (ver página 9 del cuadernillo de reglas). Cada grupo ha de seguir las intrucciones de la carta Maldad y alevosía (1A)."},
  "55028b": {"n":"Mundos en colisión","t":"Cada icono [per_hero] que haya en Loki, Dios de las Mentiras cuenta el número total de jugadores que hay en todas las zonas de la partida.\nCada icono [per_group] que haya en este Plan cuenta el número total de grupos que hay en todos los nodos.\nNinguna carta puede afectar a este Plan ni tampoco a Loki, Dios de las Mentiras a menos que aluda específicamente a estas cartas usando su nombre.\nSi se completa esta etapa, los jugadores pierden la partida."},
  "55029a": {"n":"Loki el granuja","t":"[star] Respuesta obligada: después de que resuelvas una carta de aumento durante la activación de Loki el granuja, si esa carta es de Perfidia, elige entre quedártela como carta de Encuentro boca abajo o bien gastar 1 recurso de cualquier tipo.\nInterrupción obligada: cuando este Villano vaya a ser derrotado, en vez de eso coloca 5[per_hero] contadores de Ruptura sobre esta carta y dale la vuelta."},
  "55029b": {"n":"Ilusión disipada","t":"Cuando se muestre esta carta: rompe la ilusión (ver carta apartada Romper la ilusión). Elige un grupo de tu nodo, luego coloca tantos contadores de Sinergia sobre su Entorno Frente unido como el número de jugadores que haya en ese grupo."},
  "55030a": {"n":"Loki el bribón","t":"Respuesta obligada: después de que resuelvas una carta de Perfidia, coloca 1 de Amenaza sobre el Plan principal y 1 de Amenaza sobre un Plan secundario.\nInterrupción obligada: cuando este Villano vaya a ser derrotado, en vez de eso coloca 5[per_hero] contadores de Ruptura sobre esta carta y dale la vuelta."},
  "55030b": {"n":"Ilusión disipada","t":"Cuando se muestre esta carta: rompe la ilusión (ver carta apartada Romper la ilusión). Elige un grupo de tu nodo, luego coloca tantos contadores de Sinergia sobre su Entorno Resistencia pertinaz como el número de jugadores que haya en ese grupo."},
  "55031a": {"n":"Loki el bellaco","t":"Respuesta obligada: después de que resuelvas una carta de Perfidia, inflige 1 de Daño a tu Superhéroe y 1 de Daño a un Aliado que controles.\nInterrupción obligada: cuando este Villano vaya a ser derrotado, en vez de eso coloca 5[per_hero] contadores de Ruptura sobre esta carta y dale la vuelta."},
  "55031b": {"n":"Ilusión disipada","t":"Cuando se muestre esta carta: rompe la ilusión (ver carta apartada Romper la ilusión). Elige un grupo de tu nodo, luego coloca contadores de Sinergia sobre su Entorno Fuerza dominante como el número de jugadores que haya en ese grupo."},
  "55032a": {"n":"Loki el canalla","t":"[star] Interrupción obligada: cuando Loki el canalla se active contra ti, descarta la primera carta del mazo de Encuentros. Si se ha descartado una carta de Perfidia de este modo, Loki el canalla recibe +1 PLA y +1 ATQ para esta activación.\nInterrupción obligada: cuando este Villano vaya a ser derrotado, en vez de eso coloca 5[per_hero] contadores de Ruptura sobre esta carta y dale la vuelta."},
  "55032b": {"n":"Ilusión disipada","t":"Cuando se muestre esta carta: rompe la ilusión (ver carta apartada Romper la ilusión). Elige un grupo de tu nodo, luego coloca contadores de Sinergia sobre su Entorno Retirada fingida como el número de jugadores que haya en ese grupo."},
  "55033a": {"n":"Maldad y alevosía","t":"Preparación: después de que resolver Mundos en colisión (A), haz lo siguiente:\n1. Pon en juego un Villano Avatar de Loki elegido al azar. Aparta a un lado los demás Villanos Avatar de Loki y la carta Romper la ilusión.\n2. Pon en juego todos los Entornos Sinergia.\n3. En modo Normal, aparta a un lado el Accesorio Concentración intensa. En modo Experto, vincúlalo Villano Avatar de Loki que esté en juego."},
  "55033b": {"n":"Maldad y alevosía","t":"Interrupción obligada: cuando vaya a completarse este Plan, en vez de eso quita toda la Amenaza que haya sobre esta carta y coloca 1 de Amenaza sobre Mundos en colisión.\nInterrupción obligada: cuando un Superhéroe vaya a ser derrotado, en vez de eso cambia a su identidad de Alter ego, se fija su medidor de Vida en 1 y se coloca 1 de Amenaza sobre Mundos en colisión."},
  "55034a": {"n":"Concentración intensa","t":"Permanente.\nEl Villano Avatar de Loki recibe +2[per_hero] de Vida y gana Tesón.\nCuando se muestre esta carta: en modo Normal, descarta las 2[per_hero] primeras cartas del mazo de Encuentros y las 5 primeras cartas del mazo de cada jugador."},
  "55034b": {"n":"Concentración total","t":"Permanente.\nEl Villano Avatar de Loki recibe +3[per_hero] de Vida y gana Tesón.\nCuando se muestre esta carta: descarta las 2[per_hero] cartas del mazo de Encuentros y las 5 primeras cartas del mazo de cada jugador. Localiza el Cetro oscuro y muéstralo. Si el Cetro oscuro no ha entrado en juego de este modo, dale al Villano Avatar de Loki una carta de Estado \"Duro\"."},
  "55035": {"n":"Encadenado","t":"Vincula esta carta a tu Superhéroe.\nEl Superhéroe vinculado no puede prepararse.\nCuando se muestre esta carta: agota tu carta de Superhéroe.\nAcción de Héroe: gasta 2 recursos de un mismo tipo → descarta esta carta. Coloca 1 contador de Ruptura sobre el Villano Avatar de Loki."},
  "55036": {"n":"Cetro oscuro","t":"Vincula esta carta al Villano Avatar de Loki.\nEl Villano Avatar de Loki gana Firmeza.\nNo pueden anularse cartas de Perfidia.\nRespuesta de Héroe: después de que resuelvas una carta de Perfidia, gasta 2 recursos de un mismo tipo → descarta esta carta."},
  "55037": {"n":"Secuaz draugr","t":"Guardia.\nCuando se derrote esta carta: el jugador que la ha derrotado descarta la primera carta del mazo de Encuentros. Si es una carta de Perfidia, ese jugador se queda al Secuaz draugr como carta de Encuentro boca abajo."},
  "55038": {"t":"Guardia.\n[star] Interrupción obligada: cuando Grendell ataque, descarta las 3 primeras cartas del mazo de Encuentros. Por cada carta de Perfidia que se haya descartado de este modo, Grendell recibe +1 ATQ para este ataque.\nCuando se derrote esta carta: coloca 3 contadores de Ruptura sobre el Villano Avatar de Loki."},
  "55039": {"t":"Represalia 1.\n[star] Respuesta obligada: después de que Malekith te ataque, descarta la primera carta del mazo de Encuentros. Si es una carta de Perfidia, quédatela como carta de Encuentro boca abajo.\nCuando se derrote esta carta: coloca 2 contadores de Ruptura sobre el Villano Avatar de Loki."},
  "55040": {"n":"Minotauro","t":"Dureza.\nCuando se muestre esta carta: si hay al menos 5 cartas de Perfidia en la pila de descartes del mazo de Encuentros, el Minotauro se activa contra ti.\nCuando se derrote esta carta: coloca 2 contadores de Ruptura sobre el Villano Avatar de Loki."},
  "55041": {"n":"Mangog","t":"Victoria 1.\nCualquier jugador de tu nodo puede atacar a Mangog como si estuviese en su zona de partida.\nCuando se derrote esta carta: cada grupo de tu nodo coloca 3 contadores de Ruptura sobre su Villano Avatar de Loki y 1 contador de Sinergia sobre uno de sus Entornos Sinergia."},
  "55042": {"n":"El lobo Fenris","t":"Guardia. Patrulla.\nCuando se derrote esta carta: coloca 3 contadores de Ruptura sobre el Villano Avatar de Loki. Elige un grupo de tu nodo, luego coloca 1 contador de Sinergia sobre su Entorno Resistencia pertinaz."},
  "55043": {"t":"Cuando se muestre esta carta: descarta las 3 primeras cartas del mazo de Encuentros. Si se ha descartado alguna carta de Perfidia de este modo, sufres 2 de Daño indirecto.\nCuando se derrote esta carta: coloca 3 contadores de Ruptura sobre el Villano Avatar de Loki. Elige un grupo de tu nodo, luego coloca 1 contador de Sinergia sobre su Entorno Fuerza dominante."},
  "55044": {"t":"Respuesta obligada: después de que un personaje ataque a Laufey, descarta la primera carta del mazo de Encuentros. Si es una carta de Perfidia, aturde al atacante.\nCuando se derrote esta carta: coloca 3 contadores de Ruptura sobre el Villano Avatar de Loki. Elige un grupo de tu nodo, luego coloca 1 contador de Sinergia sobre su Entorno Frente unido."},
  "55045": {"n":"Aura de estasis","t":"Cuando se muestre esta carta: descarta las 2 primeras cartas del mazo de Encuentros (las 3 primeras cartas en modo Experto). Si se ha descartado alguna carta de Perfidia de este modo, agota a tu carta de Superhéroe."},
  "55046": {"n":"Portal entre dos mundos","t":"Victoria 1.\nCualquier jugador de tu nodo puede intervenir contra Portal entre dos mundos como si estuviese en su zona de partida.\nCuando se derrote esta carta: cada grupo de tu nodo coloca 3 contadores de Ruptura sobre su Villano Avatar de Loki y 1 contador de Sinergia sobre uno de sus Entornos Sinergia."},
  "55047": {"n":"Objetivos ambiciosos","t":"Cuando se derrote esta carta: coloca 2 contadores de Ruptura sobre el Villano Avatar de Loki.\n[star] Aumento: sufres 1 de Daño indirecto por cada personaje que controles."},
  "55048": {"n":"Nueva Jotunheim","t":"Cuando se derrote esta carta: coloca 3 contadores de Ruptura sobre el Villano Avatar de Loki. Elige un grupo de tu nodo, luego coloca 1 contador de Sinergia sobre su Entorno Retirada fingida."},
  "55049": {"n":"Artes oscuras","t":"En modo Experto, esta carta gana Incitar 1.\nCuando se muestre esta carta: busca un Esbirro en la pila de descartes del mazo de Encuentros y muéstralo. De no ser posible, coloca 3 de Amenaza sobre el Plan principal.\n[star] Aumento: coloca 1 de Amenaza sobre el Plan principal por cada personaje que controles."},
  "55050": {"n":"Truco rastrero","t":"Cuando se muestre esta carta: quita 1 contador de Ruptura del Villano Avatar de Loki. Sufres 2 de Daño (3 de Daño en modo Experto).\n[star] Aumento: sufres 1 de Daño indirecto por cada personaje que controles."},
  "55051": {"n":"Historias y mentiras","t":"Cuando se muestre esta carta: intercambia el Villano Avatar de Loki que está en juego por un Villano Avatar de Loki aleatorio que esté apartado. Luego:\n• Si está en juego Loki el bellaco o Loki el bribón, ejecuta el Plan (con +1 PLA en modo Experto).\n• Si está en juego Loki el granuja o Loki el canalla, te ataca (con +1 ATQ en modo Experto)."},
  "55052": {"n":"Fuerza dominante","t":"Permanente.\nMáximo de 1[per_hero] contadores de Sinergia sobre esta carta.\nInterrupción: cuando un personaje amigo ataque, quita 1 contador de Sinergia de esta carta → ese ataque inflige 4 de Daño adicional."},
  "55053": {"n":"Retirada fingida","t":"Permanente.\nMáximo de 1[per_hero] contadores de Sinergia sobre esta carta.\nInterrupción: cuando un Superhéroe vaya a sufrir cualquier cantidad de Daño, quita 1 contador de Sinergia de esta carta → evita 4 de ese Daño."},
  "55054": {"n":"Resistencia pertinaz","t":"Permanente.\nMáximo de 1[per_hero] contadores de Sinergia sobre esta carta.\nInterrupción: cuando un personaje amigo intervenga, quita 1 contador de Sinergia de esta carta → esa intervención quita 4 de Amenaza adicional."},
  "55055": {"n":"Frente unido","t":"Permanente.\nMáximo de 1[per_hero] contadores de Sinergia sobre esta carta.\nRecurso: quita 1 contador de Sinergia de esta carta → genera recursos [wild] [wild]."},
  "55056": {"n":"Hombre Absorbente","t":"Guardia. Victoria 1.\n[star] Mientras el Hombre Absorbente esté enfrentado a ti, recibe +X ATQ, siendo X el coste impreso de la carta con el coste más alto que controles.\nCuando se derrote esta carta: el jugador que haya derrotado a este Esbirro pone en juego bajo su control el Aliado Hombre Absorbente que está apartado."},
  "55057": {"t":"Tesón. Victoria 1.\n[star] Los ataques de Titania ganan Brutalidad.\nCuando se derrote esta carta: el jugador que haya derrotado a este Esbirro pone en juego bajo su control el Aliado Titania que está apartado."},
  "55058": {"n":"Torbellino","t":"Ataque veloz. Victoria 1.\n[star] Respuesta obligada: después de que Torbellino te ataque, sufres 1 de Daño indirecto por cada Plan secundario que haya en juego.\nCuando se derrote esta carta: el jugador que haya derrotado a este Esbirro pone en juego bajo su control el Aliado Torbellino que está apartado."},
  "55059": {"t":"Represalia 1. Victoria 1.\nCuando se muestre esta carta: descarta las 4 primeras cartas de tu mazo. Por cada recurso [energy] impreso que hayas descartado de este modo, sufres 1 de Daño indirecto.\nCuando se derrote esta carta: el jugador que haya derrotado a este Esbirro pone en juego bajo su control el Aliado Zzzax que está apartado."},
  "55060": {"n":"El tango de los tramposos","t":"El Villano gana Firmeza. (No puede quedar aturdido ni confundido.)\n[star] Aumento: si esta activación es un ataque, gana Brutalidad."},
  "55061": {"n":"Alguien mueve los hilos","t":"En modo Experto, este Plan gana Complicación 1[per_hero].\nLos Aliados no pueden intervenir este Plan ni defender contra los ataques del Villano."},
  "55062": {"n":"Triangulo amoroso","t":"Vincula esta carta a un Aliado que controles. De no ser posible, esta carta gana Oleada.\nEl Aliado vinculado no puede atacar al Villano ni defender contra los ataques del Villano.\nAcción de Alter ego: agota al Aliado vinculado y gasta un recurso [mental] → descarta esta carta."},
  "55063": {"n":"Hombre Absorbente","t":"Enlazada (Esbirro Hombre Absorbente). Victoria 0. No se cuenta de cara a tu limite de Aliados.\n[star] Interrupción: cuando Hombre Absorbente ataque o intervenga, agota una Mejora o Apoyo que controles. Hombre Absorbente recibe +X en ese atributo para este uso, siendo X el coste impreso de esa carta (hasta un maximo de +3)."},
  "55064": {"t":"Enlazada (Esbirro Titania). Victoria 0. No se cuenta de cara a tu limite de Aliados.\n[star] Los ataques de Titania ganan Brutalidad y Penetrante."},
  "55065": {"n":"Torbellino","t":"Enlazada (Esbirro Torbellino). Victoria 0. No se cuenta de cara a tu limite de Aliados.\n[star] Interrupción: cuando Torbellino ataque, quita 1 de Amenaza de cada Plan que haya en juego. Por cada ficha de Amenaza que se haya quitado de este modo, Torbellino recibe +1 ATQ para ese ataque."},
  "55066": {"t":"Enlazada (Esbirro Zzzax). Victoria 0. No se cuenta de cara a tu limite de Aliados.\nRespuesta: después de que Zzzax entre en juego, busca entre las 5 primeras cartas de tu mazo una carta que tenga impreso un recurso [energy] y añádela a tu mano. (Baraja el mazo.)"},
  "56001a": {"t":"Todo Esbirro que tenga vinculada una copia de Presa pierde Guardia.\nDe cacería — Respuesta: después de que empiece la fase de los Jugadores, roba 1 carta por cada Esbirro que esté enfrentado a ti (hasta un máximo de 3)."},
  "56001b": {"t":"Infiltrada en el cuerpo — Acción: busca una copia de Presa en tu mazo y en tu pila de descartes y añadela a tu mano. (Límite de una vez por ronda.)","f":"\"No hace falta ser un Vengador para proteger a los demás.\""},
  "56002": {"n":"Caballero Luna","t":"Respuesta obligada: después de que el Caballero Luna entre en juego, busca un Esbirro en el mazo y la pila de descartes de Encuentros y ponlo en juego enfrentado a ti. Aturde y confunde a ese Esbirro.","f":"\"¡Eh, Greer, mira lo que me he encontrado!\""},
  "56003": {"n":"Comisaría del distrito","t":"Acción de Alter ego: agota la Comisaría del distrito → quita 1 de Amenaza de un Plan. Quita 1 de Amenaza adicional por cada Esbirro que esté enfrentado a ti.","f":"\"Ahórrate las amenazas, tío. Mis amigos dan mucho más miedo que los tuyos.\" —Greer Nelson"},
  "56004": {"n":"Amuleto de la Cabeza de Gato","t":"Recurso: agota el Amuleto de la Cabeza de Gato → genera un recurso [physical] por cada Esbirro que esté enfrentado a ti (hasta un máximo de [physical] [physical] [physical]).","f":"El amuleto de Tigra le permite cambiar de forma humana a felina."},
  "56005": {"n":"Zarpas afiladas","t":"Interrupción: cuando realices un ataque básico, agota las Zarpas afiladas → Tigra recibe +1 ATQ para este ataque. Elige una opción:\n• Este ataque gana Brutalidad.\n• Este ataque gana Penetrante."},
  "56006": {"n":"Reflejos felinos","t":"Interrupción de Héroe: cuando vayas a sufrir cualquier cantidad de Daño, descarta Reflejos felinos → evita 3 de ese Daño. Puedes confundir a un Esbirro que esté enfrentado a ti."},
  "56007": {"n":"Presa","t":"[star] Como coste adicional para jugar esta Mejora, busca un Esbirro en el mazo y la pila de descartes de Encuentros y ponlo en juego enfrentado a ti. Vincula Presa a ese Esbirro y atúrdelo.\nInterrupción: cuando el Esbirro vinculado sea derrotado, prepara a Tigra."},
  "56008": {"n":"Garras y dientes","t":"El coste para jugar este Evento se reduce en 1 por cada Esbirro que esté enfrentado a ti.\nAcción de Héroe (ataque): inflige 4 de Daño a un enemigo. Inflige 4 de Daño a un enemigo."},
  "56009": {"n":"Sentidos felinos","t":"Acción de Héroe (intervención): quita 3 de Amenaza de un Plan. Si con esto se quita la última ficha de Amenaza de ese Plan, aturde a un Esbirro.","f":"\"Es una cuestión de instinto. Esta gata tiene que cazar.\" —Tigra"},
  "56010": {"n":"Dos Pistolas Kid","t":"[star] Interrupción: cuando Dos Pistolas Kid realice un ataque básico, elige 2 enemigos en vez de 1 y resuelve este ataque contra cada uno de ellos.","f":"\"Adelante, forasteros; cuando vosotros digaís.\""},
  "56011": {"n":"Spidergirl","t":"Respuesta: después de que juegues a Spidergirl desde tu mano, aturde y confunde a un Esbirro.","f":"\"¡Vale, panda de pringaos! ¿Quién quiere un pedazo de mí?\""},
  "56012": {"n":"Cobertura aérea","t":"Usos (2 contadores de Combustible). Máximo de 1 por jugador.\nRespuesta: después de que entre en juego un Esbirro, agota esta carta y quítale 1 contador de Combustible → busca en tu mazo y en tu pila de descartes una Mejora Táctica que pueda vincularse a ese Esbirro y añádela a tu mano."},
  "56013": {"n":"Preparación agresiva","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nRecibes +3 de Vida y tu Héroe recibe +1 ATQ."},
  "56014": {"n":"Fuego de supresión","t":"Vincula esta carta a un Esbirro. Máximo de 1 por Esbirro.\nInterrupción de Héroe: cuando ataques y derrotes al Esbirro vinculado, cura 2 de Daño a tu Héroe."},
  "56015": {"n":"\"¡Os reviento!\"","t":"Máximo de 1 por fase.\nAcción de Héroe: roba 1 carta por cada Esbirro que esté enfrentado a ti.","f":"\"¡Has escogido un mal día para meterte conmigo, colega!\" - Mapache Cohete"},
  "56016": {"n":"Golpe de gracia","t":"Acción de Héroe (ataque): derrota a un Esbirro que no sea Élite y que tenga vinculada una Mejora. Ignora todas las capacidades del tipo \"Cuando se derrote esta carta\" que tenga ese Esbirro.","f":"\"Voy a poner fin a esto – ¡ahora mismo!\" —Caballero Negro"},
  "56017": {"n":"Golpe salvaje","t":"Interrupción de Héroe: cuando realices un ataque básico, recibes +6 ATQ para este ataque. Este ataque gana Penetrante."},
  "56018": {"n":"Audacia","t":"Máximo de 1 por mazo.\nRespuesta de Héroe: después de que gastes esta carta, inflige 1 de Daño al Villano."},
  "56019": {"n":"Chaqueta Amarilla","t":"Juega esta carta sólo si tienes el rasgo Vengador.\nRespuesta: después de que Chaqueta Amarilla entre en juego, busca una Mejora entre las 5 primeras cartas de tu mazo y añádela a tu mano.","f":"\"Sé lo que tengo que hacer.\""},
  "56020": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "56021": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "56022": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "56023": {"n":"Demasiado implicada","t":"Dale esta carta al jugador que lleva a Greer Nelson.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n• agota a Greer Nelson → retira de la partida Demasiado implicada.\n• Cada Esbirro que esté enfrentado a ti se activa contra ti. Si no se activa ningún Esbirro de este modo, Demasiado implicada gana Oleada. Descarta esta carta."},
  "56024": {"n":"El Encapuchado","t":"Tesón. Infame.\n[star] Respuesta obligada: después de que El Encapuchado ataque, coloca 1 de Amenaza sobre el Plan secundario Bajos fondos.\n(Esbirro Archienemigo de Tigra.)"},
  "56025": {"n":"Bajos fondos","t":"Ningún Esbirro Criminal puede sufrir Daño.","f":"El Encapuchado has gathered the disparate elements of the criminal underworld together in one unified gang."},
  "56026": {"n":"Capa del Encapuchado","t":"Vincula esta carta a El Encapuchado. De no ser posible, vincula esta carta al Villano.\nRespuesta de Héroe: después de que realices un ataque básico contra el enemigo vinculado, gasta recursos [energy] [physical] → descarta esta carta.\n[star] Aumento: vincula esta carta a El Encapuchado. De no ser posible, vincula esta carta al Villano."},
  "56027": {"n":"Madame Máscara","t":"Cuando se muestre esta carta: coloca 2 de Amenaza sobre el Plan secundario Bajos fondos. De no ser posible, localiza Bajos fondos y muéstralo.\n[star] Aumento: coloca 2 de Amenaza sobre el Plan secundario Bajos fondos. De no ser posible, esta carta gana [boost][boost]."},
  "56028": {"n":"Puzzle","t":"Ataque veloz.\n[star] Respuesta obligada: después de que Puzzle ataque e inflija Daño a un personaje, coloca 2 de Amenaza sobre el Plan secundario Bajos fondos.","f":"\"¡Gata mala!\""},
  "56029a": {"t":"Forma predilecta — Respuesta obligada: después de que una Mejora Cambio de forma entre en juego controlada por ti, descarta todas las demás Mejoras Cambio de forma que controles y prepara a Hulkling.","f":"\"¡Esto es una pasada!\""},
  "56029b": {"t":"No puedes tener en juego más de 1 Mejora Cambio de forma.\nCambiar de forma — Acción: busca una Mejora Cambio de forma en tu mazo y tu pila de descartes, y añádela a tu mano. (Límite de una vez por ronda.)"},
  "56030": {"t":"Respuesta: después de que juegues a Wiccan desde tu mano, busca una carta de Evento específica de un Superhéroe en tu mazo y en tu pila de descartes y añádela a tu mano. (Baraja el mazo.)","f":"\"¡Aguanta, Teddy!¡Ya estoy aquí!\""},
  "56031": {"n":"Casa de los Altman","t":"Acción de Alter ego: agota la Casa de los Altman → cura 2 de Daño a Teddy Altman y devuelve a tu mazo 1 carta de Hulkling que esté en tu pila de descartes y barájalo.","f":"La señora Altman crió a Teddy desde muy pequeño para ocultar su verdadera naturaleza."},
  "56032": {"n":"Forma alada","t":"Hulkling recibe +1 INT, +1 ATQ, +1 DEF, y gana el rasgo Aéreo.\nRespuesta de Héroe: después de que juegues un Evento, agota Forma alada → quita 2 de Amenaza de un Plan."},
  "56033": {"n":"Forma colosal","t":"Hulkling recibe +2 ATQ y +1 DEF.\nRespuesta de Héroe: después de que juegues un Evento, agota Forma colosal → inflige 2 de Daño a un enemigo."},
  "56034": {"n":"Forma blindada","t":"Hulkling recibe +1 ATQ, +2 DEF, y gana Represalia 1.\nRespuesta de Héroe: después de que juegues un Evento, agota Forma blindada → cura 2 de Daño a Hulkling."},
  "56035": {"n":"Forma imitada","t":"Hulkling recibe +2 INT.\nInterrupción obligada: cuando un enemigo vaya a atacarte, en vez de eso ejecuta el Plan.\nRespuesta de Héroe: después de que juegues un Evento, agota Forma imitada → roba 1 carta."},
  "56036": {"n":"Fisiología alienígena","t":"Recurso: agota Fisiología alienígena → genera un recurso [wild] ([wild] [wild] si estás pagando una carta de Hulkling).","f":"\"Cuando descubrí mis poderes por primera vez, creí que era un mutante. ¡Pero resulta que soy un alienígena!\""},
  "56037": {"n":"Golpe de cambiaformas","t":"Acción de Héroe (ataque): inflige 5 de Daño a un enemigo. Prepara tu Mejora Cambio de forma.","f":"\"¡No toques a mis amigos!\" —Hulkling"},
  "56038": {"n":"Defensa acorazada","t":"Interrupción de Héroe (defensa): cuando un enemigo ataque, inflígele tanto Daño como tu DEF. Despúes de este ataque, dale a Hulkling una carta de Estado \"Duro\"."},
  "56039": {"n":"Suplantación de identidad","t":"Acción de Héroe (intervención): quita 4 de Amenaza de un Plan. Si esto quita la última ficha de Amenaza de ese Plan, puedes cambiar a la identidad de tu Alter ego.","f":"\"Soy el metamorfo residente de los Jóvenes Vengadores.\" —Hulkling"},
  "56040": {"n":"Cambiaformas","t":"Acción de Héroe: busca una Mejora Cambio de forma en tu mazo y tu pila de descartes, y añádela a tu mano. (Baraja el mazo.)","f":"\"No lo has visto venir, ¿verdad?\" —Hulkling"},
  "56041": {"n":"Patriota","t":"Respuesta: después de que te enfrentes a un Esbirro, dale a Patriota una carta de Estado \"Duro\".","f":"\"Estoy listo para lo que sea.\""},
  "56042": {"n":"Hermano Vudú","t":"Respuesta: después de que el Hermano Vudú entre en juego, busca una carta de Evento entre las 5 primeras cartas de tu mazo y añádela a tu mano. Baraja tu mazo.","f":"\"Me llamo Jericho Drumm. Me llaman Hermano Vudú.\""},
  "56043": {"n":"Base secreta","t":"Usos (3 contadores de Fortaleza).\nRespuesta de Alter ego: después de que cambies de identidad, agota la Base secreta y quítale 1 contador de Fortaleza → dale a tu Superhéroe una carta de Estado \"Duro\"."},
  "56044": {"n":"La Enfermera de Noche","t":"Usos (3 contadores de Medicina).\nAcción: agota La Enfermera de Noche y quítale 1 contador de Medicina → cura 1 de Daño a un Héroe y descarta 1 carta de Estado que tenga asignada."},
  "56045": {"t":"Restringida. (Máximo de 2 cartas Restringidas por jugador.)\nRespuesta: después de que tu Héroe defienda contra un ataque enemigo, gasta un recurso [energy] → inflige 2 de Daño a un enemigo."},
  "56046": {"n":"Preparación defensiva","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nRecibes +3 de Vida y tu Héroe recibe +1 DEF."},
  "56047": {"n":"\"Aguantaría todo el día\"","t":"Interrupción de Héroe (defensa): cuando un enemigo ataque, declara a tu Héroe como defensor sin tener que agotarlo."},
  "56048": {"n":"Provocación","t":"Acción de Héroe: el Villano te ataca. Los demás personajes no pueden defender contra este ataque. Roba 3 cartas.","f":"\"¡Eh,Fido! ¿Quién te ha dejado salir de la perrera?\" — Júbilo"},
  "56049": {"n":"Arremetida","t":"Acción de Héroe (ataque): aturde a un enemigo. Si has pagado el coste de esta carta usando un recurso [physical], inflige 3 de Daño a ese enemigo.","f":"Mañana no voy a poder ni moverme."},
  "56050": {"n":"Con la misma moneda","t":"Interrupción de Héroe (defensa): cuando un enemigo ataque, ganas Represalia 1 hasta el final de la fase.","f":"\"¡Yo también conozco ese truco!\" —Wiccan"},
  "56051": {"n":"Preservación","t":"Máximo de 1 por mazo.\nRespuesta de Héroe: después de que gastes esta carta, cura 1 de Daño a tu Héroe."},
  "56052": {"t":"[star] Interrupción: cuando Iron Lad use un atributo básico, agota otro Aliado Vengador que controles → añade el atributo de ese Aliado al atributo de Iron Lad para este uso.","f":"\"Nos hicimos Jóvenes Vengadores por un motivo.\""},
  "56053": {"n":"Evaluar la situación","t":"Acción: recibes +1 al tamaño de tu mano hasta el final de la fase.","f":"\"Bueno, si huyo, no molo. Y si me quedo y me zumban… tampoco. Es un dilema.\" - Tony Stark"},
  "56054": {"n":"Un origen complicado","t":"Dale esta carta al jugador que lleva a Teddy Altman.\nPuedes adoptar la identidad de tu Alter ego. Elige una opción:\n• agota a Teddy Altman → retira de la partida Un origen complicado.\n• Descarta todas las Mejora Cambio de forma que controles. Descarta esta carta."},
  "56055": {"n":"Superskrull","t":"[star] Interrupción obligada: cuando el Superskrull te ataca, descarta la primera carta de tu mazo. Si el recurso impreso de esa carta tiene:\n[energy] – El Superskrull recibe +2 ATQ para este ataque.\n[mental] – Descarta 1 carta de tu mano.\n[physical] – Dale al Superskrull una carta de Estado \"Duro\".\n[wild] – Descarta una Mejora que controles."},
  "56056": {"n":"Asunto de los Skrulls","t":"Respuesta obligada: después de que se descarte cualquier cantidad de cartas de la parte superior del mazo de un jugador, coloca esas cartas boca abajo debajo de este Plan.","f":"Superskrull was sent to abduct Hulkling después his true heritage was mostrado."},
  "56057": {"n":"Poderes fantásticos","t":"El Esbirro vinculado recibe +3 de Vida y gana Represalia 1.\nCuando se muestre esta carta: localiza al Superskrull. Ponlo en juego enfrentado a ti y vincúlale Poderes fantásticos. Si tienes adoptada la identidad de Héroe, Superskrull te ataca."},
  "56058": {"n":"¡Te vienes conmigo!","t":"Cuando se muestre esta carta (Alter ego): descarta las 3 primeras cartas de tu mazo. Coloca 1 de Amenaza sobre el Plan principal por cada icono de recurso distinto que haya en las cartas descartadas.\nCuando se muestre esta carta (Héroe): descarta las 3 primeras cartas de tu mazo. Sufres 1 de Daño por cada icono de recurso distinto que haya en las cartas descartadas ([energy], [mental], [physical], o [wild])."},
  "56059": {"t":"[star] Iron Man recibe +1 PLA por cada Accesorio Tecnología que tenga vinculado (hasta un máximo de +3 PLA).\nPreparación: el equipo enemigo busca un Accesorio de Iron Man en el mazo de Encuentros y tu equipo lo muestra."},
  "56060": {"t":"Tesón.\n[star] Iron Man recibe +1 PLA por cada Accesorio Tecnología que tenga vinculado (hasta un máximo de +3 PLA).\nCuando se muestre esta carta: dale una carta de Encuentro a cada jugador. Iron Man no puede sufrir Daño en esta fase."},
  "56061": {"t":"[star] Iron Man recibe +1 PLA por cada Accesorio Tecnología que tenga vinculado (hasta un máximo de +3 PLA).\nCuando se muestre esta carta: el equipo enemigo busca un Accesorio de Iron Man en el mazo de Encuentros y tu equipo lo muestra."},
  "56062": {"t":"Tesón.\n[star] Iron Man recibe +1 PLA por cada Accesorio Tecnología que tenga vinculado (hasta un máximo de +3 PLA).\nCuando se muestre esta carta: dale una carta de Encuentro a cada jugador. Iron Man no puede sufrir Daño en esta fase."},
  "56063a": {"n":"Ley de Registro de Superhumanos","t":"Contenido: Líder escogido I y II (III y IV para jugar en modo Experto). Conjunto de Encuentros del Líder escogido, Normal, y 3–4 conjuntos modulares.\nPreparación: En el modo Competitivo, el equipo enemigo localiza el Plan secundario Escoger un Bando y tu equipo lo muestra. En el modo Cooperativo, localiza el Plan secundario del Líder escogido y muéstralo."},
  "56063b": {"n":"Retirar el apoyo","t":"Si hay más de 1 jugador en tu equipo, esta etapa gana Complicación 2[per_hero].\nInterrupción obligada: cuando un jugador muestre una carta de Perfidia, coloca 1 de Amenaza sobre esta carta. (Límite de una vez por fase y jugador.)","f":"\"Society will no longer tolerate superheroes who operate outside the law.\" —Hulka"},
  "56064a": {"n":"Medidas para el registro","f":"Iron Man y sus Vengadores tienen orden de capturar a todo individuo con superpoderes que se niege a inscribirse en el registro de S.H.I.E.L.D. Esto incluye a antiguos compañeros de equipo como el Capitán América y Spiderwoman."},
  "56064b": {"n":"Prisión en la Zona Negativa","t":"[star] El umbral de Amenaza de este Plan se reduce en 1 por cada carta boca abajo que tenga debajo.\nRespuesta obligada: después de que un Aliado sea derrotado por un ataque enemigo, coloca ese Aliado boca abajo debajo de este Plan.\nSi se completa esta etapa, los jugadores pierden la partida."},
  "56065": {"n":"Guanteletes potenciados","t":"Vincula esta carta a Iron Man.\n[star] Los ataques de Iron Man ganan A distancia.\nRespuesta de Héroe: después de que realices un ataque básico contra Iron Man, gasta recursos [energy] [physical] → descarta esta carta.\n[star] Aumento: muestra esta carta."},
  "56066": {"n":"Botas propulsoras","t":"Vincula esta carta a Iron Man.\nIron Man gana el rasgo Aéreo.\nRespuesta de Héroe: después de que realices un ataque básico contra Iron Man, gasta recursos [energy] [physical] → descarta esta carta.\n[star] Aumento: muestra esta carta."},
  "56067": {"n":"Casco Mark V","t":"Vincula esta carta a Iron Man y dale una carta de Estado \"Duro\".\nIron Man gana Firmeza.\nRespuesta de Héroe: después de que realices un ataque básico contra Iron Man, gasta recursos [mental] [physical] → descarta esta carta."},
  "56068": {"n":"Reactor ARK","t":"Vincula esta carta a Iron Man y dale una carta de Estado \"Duro\".\nIron Man gana Represalia 1.\nRespuesta de Héroe: después de que realices un ataque básico contra Iron Man, gasta recursos [mental] [physical] → descarta esta carta."},
  "56069": {"n":"Armadura Mark V","t":"Vincula esta carta a Iron Man.\nRespuesta obligada: cuando Iron Man vaya a sufrir cualquier cantidad de Daño, en vez de eso coloca ese Daño sobre esta carta. Luego, si hay al menos 5 de Daño sobre esta carta, descártala.\n[star] Aumento: muestra esta carta."},
  "56070": {"n":"Rayo repulsor","t":"Cuando se muestre esta carta (Alter ego): descarta una Mejora o Apoyo que controles.\nCuando se muestre esta carta (Héroe): descarta las 4 primeras cartas de tu mazo. Por cada recurso [energy] y [wild] impreso que se haya descartado de este modo, inflige 1 de Daño a tu Héroe."},
  "56071": {"n":"Puñetazo supersónico","t":"Cuando se muestre esta carta (Alter ego): Iron Man ejecuta el Plan. Si tiene un Accesorio Tecnología, quedas confundido.\nCuando se muestre esta carta (Héroe): Iron Man te ataca. Si tiene un Accesorio Tecnología, este ataque gana Penetrante.","f":"\"Ese's it. Now I'm mad!\" —Iron Man"},
  "56072": {"n":"Torre Stark","t":"Cuando se derrote esta carta: el equipo enemigo busca un Accesorio de Iron Man en el mazo y la pila de descartes de Encuentros y tu equipo lo muestra.","f":"Iron Man's vast wealth gives sus Vengadores a significant advantage over Capitán América's outlaws."},
  "56073": {"n":"Chaqueta Amarilla","t":"Dureza.\nCuando se muestre esta carta: dale al Líder enemigo una carta de Estado \"Duro\".\n[star] Aumento: dale al Líder enemigo una carta de Estado \"Duro\"."},
  "56074": {"n":"Avispa","t":"Trabajo en equipo (Vengador).\nCuando se muestre esta carta: coloca 1 de Amenaza sobre el Plan principal.\n[star] Aumento: coloca 1 de Amenaza sobre el Plan principal."},
  "56075": {"n":"USAgente","t":"Represalia 1. Dureza.\nCuando se muestre esta carta: inflige 1 de Daño a tu Superhéroe.\n[star] Aumento: inflige 1 de Daño a tu Superhéroe."},
  "56076": {"n":"Poderosos Vengadores","t":"Cuando se muestre esta carta: resuelve las capacidades del tipo \"Cuando se muestre esta carta\" de todos los Esbirros que haya en juego. Si no se resuelve de este modo ninguna capacidad del tipo \"Cuando se muestre esta carta\", esta carta gana Oleada.","f":"\"Do us all a favor y stay down!\" —Doc Samson"},
  "56077": {"n":"Los héroes más poderosos de la Tierra","t":"Complicación 1[per_hero].\nCada Esbirro Vengador gana las palabras clave impresas de todos los demás Esbirro Vengador.","f":"\"We've got you outnumbered y outgunned.\" —Iron Man"},
  "56078": {"t":"Guardia.\nCuando se muestre esta carta: quedas confundido. Si ya estabas confundido, coloca 2 de Amenaza sobre el Plan principal.\n[star] Aumento: quedas confundido."},
  "56079": {"n":"Gata Infernal","t":"Ataque veloz.\nCuando se muestre esta carta: quedas aturdido. Si ya estabas aturdido, sufres 2 de Daño indirecto.\n[star] Aumento: quedas aturdido."},
  "56080": {"n":"Alistado","t":"El Esbirro vinculado recibe +2 de Vida y gana el rasgo Vengador.\nCuando se muestre esta carta: En el modo Competitivo, el equipo enemigo vincula Alistado a un Esbirro que esté enfrentado a ellos y ese Esbirro se enfrenta a ti. De no ser posible, descarta cartas del mazo de Encuentros hasta que se descarte un Esbirro. Muestra ese Esbirro y vincúlale Alistado."},
  "56081": {"n":"Poderosos Vengadores","t":"Cuando se muestre esta carta: resuelve las capacidades del tipo \"Cuando se muestre esta carta\" de todos los Esbirros que haya en juego. Si no se resuelve de este modo ninguna capacidad del tipo \"Cuando se muestre esta carta\", esta carta gana Oleada.","f":"\"Do us all a favor y stay down!\" —Doc Samson"},
  "56082": {"n":"La Iniciativa de los Cincuenta Estados","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: devuelve al mazo de Encuentros todos los Esbirros Vengador que haya en su pila de descartes y baraja el mazo."},
  "56083": {"t":"Represalia 2.\nCuando se muestre esta carta: el equipo enemigo busca una copia de Señuelo dotado de vida en el mazo y la pila de descartes de Encuentros y la vincula a Maria Hill."},
  "56084": {"n":"Señuelo dotado de vida","t":"El equipo enemigo vincula esta carta a un Esbirro o a su Líder. (Límite de 1 por personaje.)\nEl personaje vinculado gana Firmeza.\nInterrupción obligada: cuando el personaje vinculado vaya a sufrir cualquier cantidad de Daño a causa de un ataque, en vez de eso evita ese Daño y descarta esta carta."},
  "56085": {"n":"Orden ejecutiva","t":"Cuando se muestre esta carta: coloca 2 de Amenaza sobre cada Plan. Si Maria Hill está en juego, esta carta gana Oleada.\n[star] Aumento: si Maria Hill está en juego, esta carta gana [boost][boost][boost].","f":"\"Stand down, Captain. You are NOT in command sobre esta carta!\" —Maria Hill"},
  "56086": {"n":"Helitransporte de S.H.I.E.L.D.","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: el jugador que haya derrotado este Plan inflige 1 de Daño a cada personaje que controle y a cada Esbirro que esté enfrentado a él."},
  "56087": {"n":"Veneno","t":"[star] Los ataques de Veneno ganan Penetrante.\nCuando se muestre esta carta: Veneno ataca a tu Líder. De no ser posible, Veneno se activa contra ti."},
  "56088": {"t":"Cuando se muestre esta carta: el equipo enemigo descarta un Accesorio de tu Líder. De no ser posible, descarta una Mejora que controles.","f":"\"This is too rich: I'm working for S.H.I.E.L.D. y Daredevil's the outlaw!\""},
  "56089": {"n":"La justicia, como el rayo","t":"Cuando se muestre esta carta: cada Esbirro se activa contra el jugador al que esté enfrentado. De no ser posible, el Líder enemigo se activa contra ti. No le des una carta de aumento para esta activación."},
  "56090": {"n":"Fuerza excesiva","t":"Cuando se muestre esta carta: coloca 1 de Amenaza sobre el Plan principal por cada Esbirro que haya en juego. De no ser posible, esta carta gana Oleada.\n[star] Aumento: el Líder enemigo ataca a tu Líder (después de esta activación). No le des una carta de aumento para ese ataque."},
  "56091": {"n":"Reclutas peligrosos","t":"Complicación 1[per_hero].\nInterrupción obligada: cuando un Esbirro sea derrotado, dáselo al Líder enemigo como carta de aumento boca abajo."},
  "56092": {"n":"Capitana Marvel","t":"Preparación: el equipo enemigo localiza Canalizar energía y la vincula a la Capitana Marvel.\nRespuesta obligada: después de que la Capitana Marvel ataque y derrote a un personaje, coloca 1 contador de Energía sobre Canalizar energía."},
  "56093": {"n":"Capitana Marvel","t":"Tesón.\nCuando se muestre esta carta: dale una carta de Encuentro a cada jugador. La Capitana Marvel no puede sufrir Daño en esta fase.\nRespuesta obligada: después de que la Capitana Marvel ataque y derrote a un personaje, coloca 1 contador de Energía sobre Canalizar energía."},
  "56094": {"n":"Capitana Marvel","t":"Preparación: el equipo enemigo localiza Canalizar energía y la vincula a la Capitana Marvel.\nRespuesta obligada: después de que la Capitana Marvel ataque y derrote a un personaje, coloca 1 contador de Energía sobre Canalizar energía."},
  "56095": {"n":"Capitana Marvel","t":"Tesón.\nCuando se muestre esta carta: dale una carta de Encuentro a cada jugador. La Capitana Marvel no puede sufrir Daño en esta fase.\nRespuesta obligada: después de que la Capitana Marvel ataque y derrote a un personaje, coloca 1 contador de Energía sobre Canalizar energía."},
  "56096a": {"n":"Ley de Registro de Superhumanos","t":"Contenido: Líder escogido I y II (III y IV para jugar en modo Experto). Conjunto de Encuentros del Líder escogido, Normal, y 3–4 conjuntos modulares.\nPreparación: En el modo Competitivo, el equipo enemigo localiza el Plan secundario Escoger un Bando y tu equipo lo muestra. En el modo Cooperativo, localiza el Plan secundario del Líder escogido y muéstralo."},
  "56096b": {"n":"Reclutas de S.H.I.E.L.D.","t":"Si hay más de 1 jugador en tu equipo, esta etapa gana Complicación 2[per_hero].\nCuando se muestre esta carta: el equipo enemigo busca 1[per_hero] Esbirros en el mazo de Encuentros y reparte uno a cada jugador de tu equipo como carta de Encuentro boca abajo."},
  "56097a": {"n":"Medidas para el registro","f":"Iron Man y sus Vengadores tienen orden de capturar a todo individuo con superpoderes que se niegue a inscribirse en el registro de S.H.I.E.L.D. Esto incluye a antiguos compañeros de equipo como el Capitán América y Spiderwoman."},
  "56097b": {"n":"Caza de héroes rebeldes","t":"Cada Héroe gana el rasgo rasgo No registrado.\nRespuesta obligada: después de que se muestre otra carta que otorgue el rasgo No registrado por lo menos a 1 Héroe, inflige 2 de Daño a cada uno de esos Héroes.\nSi se completa esta etapa, los jugadores pierden la partida."},
  "56098": {"n":"Canalizar energía","t":"Permanente.\nRespuesta obligada: después de que un Líder, Héroe o Aliado ataque a la Capitana Marvel, coloca 1 contador de Energía sobre esta carta. Luego, si hay al menos 4 contadores de Energía sobre esta carta, quítalos todos → la Capitana Marvel ataca a ese personaje. Este ataque gana Brutalidad."},
  "56099": {"n":"Casco de la Capitana Marvel","t":"Vincula esta carta a la Capitana Marvel.\nLa Capitana Marvel gana Firmeza.\nRespuesta de Héroe: después de que realices un ataque básico contra la Capitana Marvel, gasta 3 recursos del mismo tipo → descarta esta carta.\n[star] Aumento: muestra esta carta."},
  "56100": {"n":"Vuelo cósmico","t":"Vincula esta carta a la Capitana Marvel.\nInterrupción obligada: cuando la Capitana Marvel vaya a sufrir más de 3 de Daño a causa de un ataque, reduce esa cantidad a 3. Luego descarta esta carta.\n[star] Aumento: muestra esta carta."},
  "56101": {"n":"Rayo fotónico","t":"Cuando se muestre esta carta (Alter ego): descarta un Aliado o Apoyo que controles.\nCuando se muestre esta carta (Héroe): la Capitana Marvel te ataca. Coloca 1 contador de Energía sobre Canalizar energía."},
  "56102": {"n":"Evitar una crisis","t":"Cuando se muestre esta carta (Alter ego): la Capitana Marvel ejecuta el Plan. Coloca 1 contador de Energía sobre Canalizar energía.\nCuando se muestre esta carta (Héroe): coloca 2 de Amenaza sobre cada Plan."},
  "56103": {"n":"Absorción de Energía","t":"Cuando se muestre esta carta: coloca 1 contador de Energía sobre Canalizar energía. cura 1 de Daño a la Capitana Marvel por cada contador de Energía sobre Canalizar energía.\n[star] Aumento: coloca 1 contador de Energía sobre Canalizar energía."},
  "56104": {"n":"Base orbital de Alpha Flight","t":"Cuando se derrote esta carta: coloca 3 contadores de Energía sobre Canalizar energía.","f":"\"Keep a tu sensors locked sobre North America. I want to know the location of Cap's headquarters.\" —Captain Marvel"},
  "56105": {"n":"Matacapas","t":"Ataque veloz.\n[star] Interrupción obligada: cuando Matacapas ataque a un Superhéroe que tenga el rasgo No registrado, recibe +2 ATQ para este ataque.","f":"S.H.I.E.L.D. formed an elite unit to confront y capture renegade superheroes."},
  "56106": {"n":"Superhumano no registrado","t":"Tu Superhéroe gana el rasgo No registrado.\nAcción de Alter ego: descarta una carta específica de Superhéroe de tu mano → descarta esta carta."},
  "56107": {"n":"Encerradlos","t":"Cuando se muestre esta carta: agota a todos los Superhéroes que tengan el rasgo No registrado. De no ser posible, el equipo enemigo busca una copia de Superhumano no registrado en el mazo de Encuentros y en su pila de descartes,y te la da como carta de Encuentro boca abajo."},
  "56108": {"n":"Orden de arresto","t":"Cuando se derrote esta carta: el jugador que la ha derrotado toma el primer Esbirro S.H.I.E.L.D. que haya en la pila de descartes del mazo de Encuentros y se la queda como carta de Encuentro boca abajo."},
  "56109": {"n":"Soldado de S.H.I.E.L.D.","t":"Cuando se muestre esta carta: coge el primer Esbirro S.H.I.E.L.D. que haya en la pila de descartes del mazo de Encuentros y ponlo en juego enfrentado a ti.\n[star] Aumento: pon en juego este Esbirro enfrentado a ti."},
  "56110": {"n":"Respuesta rápida","t":"Cuando se muestre esta carta: descarta cartas del mazo de Encuentros hasta que se descarte un Esbirro. Si tienes adoptada tu identidad de:\n• Alter ego, coloca tanta Amenaza sobre el Plan principal como el PLA de ese Esbirro.\n• Héroe, inflige tanto Daño a tu Héroe como el ATQ de ese Esbirro."},
  "56111": {"n":"Patrulla de S.H.I.E.L.D.","t":"Complicación 1[per_hero].\nTodos los Esbirros ganan Guardia.","f":"\"Stay alert. Cap's Vengadores were last seen in this area.\" —S.H.I.E.L.D. Officer"},
  "56112": {"t":"Cuando se muestre esta carta: elige un Aliado que controles (si tienes el rasgo No registrado, el equipo enemigo elige por ti). Descarta ese Aliado."},
  "56113": {"t":"Cuando se muestre esta carta: elige una Mejora que controles (si tienes el rasgo No registrado, el equipo enemigo elige por ti). Descarta esa Mejora."},
  "56114": {"n":"Superhumano no registrado","t":"Tu Superhéroe gana el rasgo No registrado.\nAcción de Alter ego: descarta una carta específica de Superhéroe desde tu mano → descarta esta carta."},
  "56115": {"n":"Caza de recompensas","t":"Cuando se muestre esta carta: descarta 1 carta desde tu mano (al azar si tienes el rasgo No registrado). Coloca 1 de Amenaza sobre el Plan principal por cada icono de recurso que hubiera en esa carta."},
  "56116": {"n":"Héroes de alquiler","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: el equipo enemigo busca una copia de Superhumano no registrado en el mazo de Encuentros y en su pila de descartes, y se la da como carta de Encuentro boca abajo al jugador que ha derrotado esta carta."},
  "56117": {"n":"Paladín","t":"Ataque veloz. Dureza.\nCuando se muestre esta carta: descarta 1 carta desde tu mano (al azar si tienes el rasgo No registrado).","f":"\"I'm not in this for a tu political agenda. I'm in it for the money.\""},
  "56118": {"n":"Pistola del Paladín","t":"Vincula esta carta al Paladín. De no ser posible, vincula esta carta al Líder enemigo.\n[star] Interrupción obligada: cuando el personaje vinculado ataque, este ataque gana A distancia y Brutalidad. Descarta esta carta después de este ataque."},
  "56119": {"n":"Caza de recompensas","t":"Cuando se muestre esta carta: descarta 1 carta desde tu mano (al azar si tienes el rasgo No registrado). Coloca 1 de Amenaza sobre el Plan principal por cada icono de recurso que hubiera en esa carta."},
  "56120": {"n":"Contratistas del gobierno","t":"Complicación 1[per_hero].\nTodos los Superhéroes gana el rasgo No registrado.","f":"cuando el Capitán América took his resistance underground, Iron Man contracted Paladín y the Héroes de alquiler to track him down."},
  "56121a": {"n":"Ley de Registro de Superhumanos","t":"Contenido: Líder escogido I y II (III y IV para jugar en modo Experto). Conjunto de Encuentros del Líder escogido, Normal, y 3–4 conjuntos modulares.\nPreparación: En el modo Competitivo, el equipo enemigo localiza el Plan secundario Escoger un Bando y tu equipo lo muestra. En el modo Cooperativo, localiza el Plan secundario del Líder escogido y muéstralo."},
  "56121b": {"n":"Seguridad Nacional","t":"Si hay más de 1 jugador en tu equipo, esta etapa gana Complicación 2[per_hero].\nTodos los Esbirros ganan Guardia."},
  "56122a": {"n":"Ley de Registro de Superhumanos","t":"Contenido: Líder escogido I y II (III y IV para jugar en modo Experto). Conjunto de Encuentros del Líder escogido, Normal, y 3–4 conjuntos modulares.\nPreparación: En el modo Competitivo, el equipo enemigo localiza el Plan secundario Escoger un Bando y tu equipo lo muestra. En el modo Cooperativo, localiza el Plan secundario del Líder escogido y muéstralo."},
  "56122b": {"n":"Indignación pública","t":"Si hay más de 1 jugador en tu equipo, esta etapa gana Complicación 2[per_hero].\n[star] Respuesta obligada: después de resolver el paso 1 de la fase del Villano, cada jugador descarta las 3 primeras cartas de su mazo.","f":"\"I can't believe Capitán América has turned contra his country!\" —J. Jonah Jameson"},
  "56123a": {"n":"Medidas para el registro","f":"Iron Man y sus Vengadores tienen orden de capturar a todo individuo con superpoderes que se niegue a inscribirse en el registro de S.H.I.E.L.D. Esto incluye a antiguos compañeros de equipo como el Capitán América y Spiderwoman."},
  "56123b": {"n":"La Iniciativa","t":"Cuando se muestre esta carta: el equipo enemigo busca 1[per_hero] Planes secundarios en el mazo de Encuentros y en su pila de descartes y reparte uno a cada jugador de tu equipo como carta de Encuentro boca abajo.\nSi se completa esta etapa, los jugadores pierden la partida."},
  "56124a": {"n":"Medidas para el registro","f":"Iron Man y sus Vengadores tienen orden de capturar a todo individuo con superpoderes que se niegue a inscribirse en el registro de S.H.I.E.L.D. Esto incluye a antiguos compañeros de equipo como el Capitán América y Spiderwoman."},
  "56124b": {"n":"No hay vuelta atrás","t":"Los Aliados entran en juego agotados.\nSi se completa esta etapa, los jugadores pierden la partida.","f":"\"There's no more amnesty for Cap y his renegades. It's gone too far!\" —Hulka"},
  "56125": {"n":"Una causa justa","t":"Cuando se muestre esta carta: el Líder enemigo ejecuta el Plan. Si hay más de 1 jugador en tu equipo, dale al Líder enemigo una carta de aumento adicional para esta activación.","f":"\"I was a double agent for years. There's not much I won't do for a just cause.\" —Spiderwoman"},
  "56126": {"n":"Lo que haga falta","t":"Cuando se muestre esta carta (Alter ego): el Líder enemigo ataca a tu Líder.\nCuando se muestre esta carta (Héroe): el Líder enemigo te ataca.","f":"\"I'm sobre target. Commence ataque.\" —Captain Marvel"},
  "56127": {"n":"Ataque dirigido","t":"Cuando se muestre esta carta: el equipo enemigo busca una carta entre las 5 primeras cartas del mazo de Encuentros y te la da como carta de Encuentro boca abajo.\n[star] Aumento: esta carta gana [boost] por cada jugador que haya en tu equipo."},
  "56128a": {"n":"Escoger un bando","t":"Permanente.\nEl Líder enemigo no puede sufrir más de 2 de Daño de cada ataque.\nRespuesta obligada: después de que se quite la última ficha de Amenaza de esta carta, el equipo enemigo busca 1[per_hero] cartas de Encuentro entre las 5 primeras cartas del mazo de Encuentros y reparte una a cada jugador como carta de Encuentro boca abajo. Dale la vuelta a esta carta."},
  "56128b": {"n":"Ahora es personal","t":"Dale esta carta al jugador inicial.\nAcción: retira esta carta de la partida → cada jugador de tu equipo elige 2 cartas de Jugador de tu Líder que estén apartadas y las añade a su mano."},
  "56129": {"n":"Visión de futuro","t":"Acción: tu Líder Iron Man ejecuta el Plan. No le des una carta de aumento para esta activación.","f":"\"Steve está anclado en el pasado. Esto es el futuro, tanto si le gusta como si no.\" —Iron Man"},
  "56130": {"n":"Selección de blanco","t":"Acción: tu Líder Iron Man ataca al Líder enemigo. Si has gastado un recurso [mental] para pagar el coste de este Evento, elige un Accesorio vinculado al Líder enemigo que contenga la expresión \"Respuesta de Héroe\" o \"Interrupción de Héroe\" y descártalo."},
  "56131": {"n":"Armadura de tecnología punta","t":"Vincula esta carta a tu Líder Iron Man. Cuenta como un Accesorio Tecnología.\nAcción de Héroe: gasta recursos [energy] [mental] → descarta esta carta. Cualquier jugador puede aplicar esta capacidad."},
  "56132": {"n":"Ponerse la armadura","t":"Respuesta de Héroe: después de que gastes este recurso, dale una carta de Estado \"Duro\" a tu Líder Iron Man."},
  "56133": {"n":"Respuesta","t":"Interrupción obligada: cuando el Líder enemigo vaya a atacarte,en vez de eso ataca a tu Líder Capitana Marvel. La Capitana Marvel no puede sufrir más de 3 puntos de Daño a consecuencia de este ataque. Descarta esta carta."},
  "56134": {"n":"Tú lo has empezado","t":"Acción: tu Líder Capitana Marvel ataca al Líder enemigo. Si has gastado un recurso [energy] para pagar el coste de este Evento, confunde al Líder enemigo.","f":"\"¡Deberías haberte imaginado lo que iba a pasar!\" —Capitana Marvel"},
  "56135": {"n":"Recluta de Alpha Flight","t":"Vincula esta carta a un Aliado.\nRespuesta: después de que se coloque cualquier cantida de contadores de Energía sobre el Accesorio Canalizar energía de tu Líder Capitana Marvel, cura 1 de Daño al Aliado vinculado."},
  "56136": {"n":"Poder en bruto","t":"Respuesta de Héroe: después de que gastes este recurso, coloca 2 contadores de Energía sobre el Accesorio Canalizar energía de tu Líder Capitana Marvel."},
  "56137": {"n":"Capitán América","t":"Preparación: el equipo enemigo localiza el Escudo del Capi y la vincula al Capitán América.\nRespuesta obligada: después de que Escudo del Capi se vincule al Capitán América, dale una carta de Estado \"Duro\"."},
  "56138": {"n":"Capitán América","t":"Tesón.\nCuando se muestre esta carta: dale una carta de Encuentro a cada jugador. El Capitán América no puede sufrir Daño en esta fase.\nRespuesta obligada: después de que Escudo del Capi se vincule al Capitán América, dale una carta de Estado \"Duro\"."},
  "56139": {"n":"Capitán América","t":"Preparación: el equipo enemigo localiza el Escudo del Capi y la vincula al Capitán América.\nRespuesta obligada: después de que Escudo del Capi se vincule al Capitán América, dale una carta de Estado \"Duro\"."},
  "56140": {"n":"Capitán América","t":"Tesón.\nCuando se muestre esta carta: dale una carta de Encuentro a cada jugador. El Capitán América no puede sufrir Daño en esta fase.\nRespuesta obligada: después de que Escudo del Capi se vincule al Capitán América, dale una carta de Estado \"Duro\"."},
  "56141a": {"n":"Resistencia superheroica","t":"Contenido: Líder escogido I y II (III y IV para jugar en modo Experto). Conjunto de Encuentros del Líder escogido, Normal, y 3–4 conjuntos modulares.\nPreparación: en modo Competitivo, el equipo enemigo localiza el Plan secundario Escoger un Bando y tu equipo lo muestra. En el modo Cooperativo, localiza el Plan secundario del Líder escogido y muéstralo."},
  "56141b": {"n":"Obtener apoyo","t":"Si hay más de 1 jugador en tu equipo, esta etapa gana Complicación 2[per_hero].\nCuando se muestre esta carta: el equipo enemigo busca 1[per_hero] Esbirros en el mazo de Encuentros y reparte uno a cada jugador de tu equipo como carta de Encuentro boca abajo."},
  "56142a": {"n":"Actos de resistencia","f":"El Capitán América y sus Vengadores se ven obligados a pasar a la clandestinidad para no ser arrestados por oponerse a la Ley de Registro. Cuando Iron Man y la Capitana Marvel empiezan a capturar a sus amigos superhumanos, los miembros de este grupo de resistencia deciden contraatacar."},
  "56142b": {"n":"Vengadores Secretos","t":"El Líder enemigo recibe +1 ATQ mientras esté atacando (+2 ATQ si es un ataque no defendido).\nSi se completa esta etapa, los jugadores pierden la partida.","f":"Capitán América's Vengadores continue to fight crime a their secret hideout."},
  "56143": {"n":"Escudo del Capi","t":"Permanente. Vincula esta carta al Capitán América.\nEl personaje vinculado gana Represalia 1 y todos los ataques efectuados contra él pierden Penetrante.\nRespuesta obligada: después de que un Héroe o el Líder Capitán América use su atributo básico de ATQ para atacar e inflija Daño al personaje vinculado, vincula el Escudo del Capi al atacante."},
  "56144": {"n":"Casco del Capi","t":"Vincula esta carta al Capitán América.\nEl Capitán América gana Firmeza.\nRespuesta de Héroe: después de que realices un ataque básico contra el Capitán América, gasta 3 recursos del mismo tipo → descarta esta carta.\n[star] Aumento: muestra esta carta."},
  "56145": {"n":"Suero de supersoldado","t":"Vincula esta carta al Capitán América.\n[star] Interrupción obligada: cuando el Capitán América ataca, este ataque gana Brutalidad. Al final de este ataque, descarta esta carta.\n[star] Aumento: muestra esta carta."},
  "56146": {"n":"Bloqueo de escudo","t":"Cuando se muestre esta carta: si el Escudo del Capi está vinculado al Capitán América, dale una carta de Estado \"Duro\" y una carta de aumento boca abajo. De no ser así, vincúlale el Escudo del Capi y dale una carta de aumento boca abajo.","f":"\"sufres a tu best shot!\" —Capitán América"},
  "56147": {"n":"Lanzamiento de escudo","t":"Cuando se muestre esta carta (Alter ego): el Capitán América ejecuta el Plan.\nCuando se muestre esta carta (Héroe): si el Escudo del Capi está vinculado al Capitán América, inflige 2 de Daño a cada personaje que controles. De no ser así, vincula el Escudo del Capi al Capitán América."},
  "56148": {"n":"Golpe heroico","t":"Cuando se muestre esta carta (Alter ego): descarta un Aliado o Mejora que controles.\nCuando se muestre esta carta (Héroe): el Capitán América te ataca. Si este ataque inflige Daño a un personaje, aturde a ese personaje."},
  "56149": {"n":"Determinación audaz","t":"Cuando se derrote esta carta: vincula el Escudo del Capi al Capitán América. El Capitán América se activa contra el jugador que haya derrotado este Plan.","f":"Capitán América's stand contra the Ley de Registro de Superhumanos gives other Héroes a figure to rally behind."},
  "56150": {"n":"Halcón","t":"Trabajo en equipo (Vengador).\nCuando se derrote esta carta: dale esta carta al Líder enemigo como carta de aumento boca abajo.\n[star] Aumento: quedas confundido. Si ya estabas confundido, esta carta gana [boost][boost]."},
  "56151": {"n":"Hércules","t":"Trabajo en equipo (Vengador).\nCuando se derrote esta carta: dale esta carta al Líder enemigo como carta de aumento boca abajo.\n[star] Aumento: quedas aturdido. Si ya estabas aturdido, esta carta gana [boost][boost]."},
  "56152": {"n":"Goliat","t":"Trabajo en equipo (Vengador).\nCuando se derrote esta carta: dale esta carta al Líder enemigo como carta de aumento boca abajo.\n[star] Aumento: dale al Líder enemigo una carta de Estado \"Duro\". Si ya era Duro, esta carta gana [boost][boost]."},
  "56153": {"n":"Luchadores por la libertad","t":"Cuando se muestre esta carta: resuelve las capacidades de \"Aumento\" de todos los Esbirros que haya en juego. Si no se resuelve ninguna capacidad de \"Aumento\" de este modo, esta carta gana Oleada.\n[star] Aumento: resuelve la capacidad \"Aumento\" de todos los Esbirros que estén enfrentado a ti."},
  "56154": {"n":"Nuevos Vengadores","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: devuelve al mazo de Encuentros todos los Esbirros que haya en su pila de descartes y baraja el mazo.","f":"\"Tony's team is in for a big surprise!\" —Capitán América"},
  "56155": {"n":"Pantera Negra","t":"Trabajo en equipo (Vengador).\nCuando se derrote esta carta: dale esta carta al Líder enemigo como carta de aumento boca abajo.\n[star] Aumento: agota todas las Mejoras que controles."},
  "56156": {"t":"Trabajo en equipo (Vengador).\nCuando se derrote esta carta: dale esta carta al Líder enemigo como carta de aumento boca abajo.\n[star] Aumento: agota un personaje que controles."},
  "56157": {"n":"Luchadores por la libertad","t":"Cuando se muestre esta carta: resuelve las capacidades de \"Aumento\" de todos los Esbirros que haya en juego. Si no se resuelve ninguna capacidad de \"Aumento\" de este modo, esta carta gana Oleada.\n[star] Aumento: resuelve la capacidad \"Aumento\" de todos los Esbirros que estén enfrentado a ti"},
  "56158": {"n":"Cambiar de bando","t":"Cuando se muestre esta carta: descarta un Aliado que controles. En el modo Competitivo, cualquier jugador del equipo enemigo puede gastar tantos recursos como el coste de ese Aliado para ponerlo en juego bajo su control. Si ningún Aliado abandona el juego de este modo, esta carta gana Oleada."},
  "56159": {"n":"Vengadores Secretos","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: el equipo enemigo busca una carta entre las 5 primeras cartas de l mazo de Encuentros. Dale esa carta al Líder enemigo como carta de aumento boca abajo."},
  "56160": {"t":"Firmeza. Dureza. Infame.\nCuando se muestre esta carta: Namor se activa contra ti.","f":"\"Once more, the surface-dwellers' war has injured my Atlantes y the Sub-Mariner must avenge them.\""},
  "56161": {"n":"Tridente de Neptuno","t":"Vincula esta carta a Namor. De no ser posible, vincula esta carta al Líder enemigo.\n[star] Los ataques del personaje vinculado ganan Penetrante.\nAcción de Héroe: gasta recursos [energy] [physical] → descarta esta carta."},
  "56162": {"n":"Cuerno de Proteo","t":"Vincula esta carta a Namor. De no ser posible, vincula esta carta al Líder enemigo.\n[star] Interrupción obligada: cuando el personaje vinculado ejecute el Plan, dale una carta de Estado \"Duro\".\nAcción de Héroe: gasta recursos [mental] [physical] → descarta esta carta."},
  "56163": {"n":"¡Imperius Rex!","t":"Cuando se muestre esta carta: si Namor está en juego, se activa contra ti. De no ser posible, el Líder enemigo se activa contra ti.\n[star] Aumento: dale al enemigo activado una carta de aumento adicional."},
  "56164": {"n":"Monarca de Atlantis","t":"Complicación 1[per_hero].\nNingún Esbirro Atlantis puede sufrir Daño.","f":"\"There is nothing Namor will not dare o do to defend his people.\" —Namor"},
  "56165": {"n":"Guardia Atlante","t":"Guardia.\nCuando se muestre esta carta: descarta las 3 primeras cartas de tu mazo.","f":"\"For Namor y the glory of Atlantis!\""},
  "56166": {"n":"Atlantes","t":"Cuando se muestre esta carta: descarta las 3 primeras cartas de tu mazo. Si tienes adoptada tu identidad de:\n• Alter ego, coloca 1 de Amenaza sobre el Plan principal por cada tipo de carta distinto que se haya descartado de este modo.\n• Héroe, sufres 1 de Daño indirecto por cada tipo de carta distinto que se haya descartado de este modo."},
  "56167": {"n":"Atlantis ataca","t":"Complicación 1[per_hero].\nCuando se muestre esta carta: descarta las 1[per_hero] primeras cartas de tu mazo. Coloca 1 ficha de Aceleración sobre esta carta por cada tipo de carta distinto que se haya descartado de este modo.","f":"The Atlantes as a people share a deep mistrust of surface-dwellers y enmity for the pollution of their waters."},
  "56168": {"n":"Spiderwoman","t":"Preparación: el equipo enemigo localiza Sutileza y la vincula a Spiderwoman.\n[star] Interrupción obligada: cuando Spiderwoman ataca, recibe +1 ATQ para este ataque por cada contador de Habilidad que haya sobre Sutileza. Quita todos los contador de Habilidad que haya sobre Sutileza."},
  "56169": {"n":"Spiderwoman","t":"Tesón.\nCuando se muestre esta carta: dale una carta de Encuentro a cada jugador. Spiderwoman no puede sufrir Daño en esta fase.\n[star] Interrupción obligada: cuando Spiderwoman ataca, recibe +1 ATQ para este ataque por cada contador de Habilidad que haya sobre Sutileza. Quita todos los contador de Habilidad que haya sobre Sutileza."},
  "56170": {"n":"Spiderwoman","t":"Preparación: el equipo enemigo localiza Sutileza y la vincula a Spiderwoman.\n[star] Interrupción obligada: cuando Spiderwoman ataca, recibe +1 ATQ para este ataque por cada contador de Habilidad que haya sobre Sutileza. Quita todos los contador de Habilidad que haya sobre Sutileza."},
  "56171": {"n":"Spiderwoman","t":"Tesón.\nCuando se muestre esta carta: dale una carta de Encuentro a cada jugador. Spiderwoman no puede sufrir Daño en esta fase.\n[star] Interrupción obligada: cuando Spiderwoman ataca, recibe +1 ATQ para este ataque por cada contador de Habilidad que haya sobre Sutileza. Quita todos los contador de Habilidad que haya sobre Sutileza."},
  "56172a": {"n":"Resistencia superheroica","t":"Contenido: Líder escogido I y II (III y IV para jugar en modo Experto). Conjunto de Encuentros del Líder escogido, Normal, y 3–4 conjuntos modulares.\nPreparación: En el modo Competitivo, el equipo enemigo localiza el Plan secundario Escoger un Bando y tu equipo lo muestra. En el modo Cooperativo, localiza el Plan secundario del Líder escogido y muéstralo."},
  "56172b": {"n":"Rebelión abierta","t":"Si hay más de 1 jugador en tu equipo, esta etapa gana Complicación 2[per_hero].\nInterrupción obligada: cuando un jugador muestre una carta de Perfidia, coloca 1 de Amenaza sobre esta carta. (Límite de una vez por fase y jugador.)","f":"\"Why don't you chase después the REAL bad guys?\" —Hulkling"},
  "56173a": {"n":"Actos de resistencia","f":"El Capitán América y sus Vengadores se ven obligados a pasar a la clandestinidad para no ser arrestados por oponerse a la Ley de Registro. Cuando Iron Man y la Capitana Marvel empiezan a capturar a sus amigos superhumanos, los miembros de este grupo de resistencia deciden contraatacar."},
  "56173b": {"n":"Protectores del barrio","t":"Cuando se muestre esta carta: el equipo enemigo busca 1[per_hero] Planes secundarios en el mazo de Encuentros y en su pila de descartes y reparte uno a cada jugador de tu equipo como carta de Encuentro boca abajo.\nSi se completa esta etapa, los jugadores pierden la partida.","f":"\"Does anyone else see the irony in outlaw Héroes fighting crime?\" —Chief of Policía"},
  "56174": {"n":"Sutileza","t":"Permanente.\nMáximo de 3 contadores de Habilidad sobre esta carta.\nInterrupción obligada: cuando se muestre una carta de Perfidia, coloca 1 contador de Habilidad sobre esta carta."},
  "56175": {"n":"Inmunidad a toxinas","t":"Vincula esta carta a Spiderwoman.\nInterrupción obligada: cuando Spiderwoman vaya a quedar aturdida o confundida, en vez de eso descarta esta carta. Dale una carta de Estado \"Duro\".\n[star] Aumento: muestra esta carta."},
  "56176": {"n":"Feromonas","t":"Cuando se muestre esta carta: quedas aturdido y confundido. Coloca 1 contador de Habilidad sobre Sutileza.\n[star] Aumento: quedas aturdido. De no ser posible, quedas confundido."},
  "56177": {"n":"Rayo venenoso","t":"Cuando se muestre esta carta (Alter ego): esta carta gana Oleada.\nCuando se muestre esta carta (Héroe): Spiderwoman te ataca. Si este ataque quita los siguientes contadores de Habilidad de la carta Sutileza:\n• Al menos 1, este ataque gana A distancia.\n• Al menos 2, este ataque gana Penetrante.\n• Al menos 3, este ataque gana Brutalidad."},
  "56178": {"n":"Pasar desapercibida","t":"Cuando se muestre esta carta: elige una opción:\n• descarta la carta con el coste más alto que controles\n• Spiderwoman ejecuta el Plan.\n[star] Aumento: esta carta gana [boost] por cada carta de Estado que tenga tu Superhéroe."},
  "56179": {"n":"Planeo controlado","t":"Interrupción obligada: cuando Spiderwoman vaya a sufrir Daño a causa de un ataque, la cantidad de Daño que sufre se reduce en 1 por cada contador de Habilidad que haya sobre la carta Sutileza.","f":"\"I've made a career out of staying one step ahead of S.H.I.E.L.D.\" —Spiderwoman"},
  "56180": {"n":"Spiderman","t":"Cuando se muestre esta carta: Spiderman ataca a todos los personajes que tengan vinculada una copia de Enredado. Si no se realiza nigún ataque de este modo, el equipo enemigo busca una copia de Enredado en el mazo y la pila de descartes de Encuentros, y te la da como carta de Encuentro boca abajo."},
  "56181": {"n":"Enredado","t":"Vincula esta carta a tu Líder. De no ser posible, vincula esta carta a tu Héroe.\nInterrupción obligada: cuando el personaje vinculado vaya a ejecutar el Plan, intervenir o atacar, en vez de eso descarta esta carta.\n[star] Aumento: si está en juego el Esbirro Spiderman, muestra esta carta."},
  "56182": {"n":"¡Espectacular!","t":"Cuando se muestre esta carta: coloca 2 de Amenaza sobre el Plan principal. En el modo Competitivo, quita 2 de Amenaza del Plan principal de tu Líder.","f":"\"Friendly neighborhood Spiderman swinging through!\" —Spider-Man"},
  "56183": {"n":"Héroe del barrio","t":"Cuando se muestre esta carta: en el modo Competitivo, traslada 2 de Amenaza desde el Plan principal de tu Líder hasta este Plan. De no ser posible, coloca 2[per_hero] de Amenaza sobre esta carta."},
  "56184": {"t":"Cuando se muestre esta carta: aturde a tu Líder. De no ser posible, quedas aturdido.\n[star] Aumento: aturde a tu Líder. De no ser posible, quedas aturdido."},
  "56185": {"t":"Cuando se muestre esta carta: confunde a tu Líder. De no ser posible, quedas confundido.\n[star] Aumento: confunde a tu Líder. De no ser posible, quedas confundido."},
  "56186": {"n":"Proteger a los inocentes","t":"Cuando se muestre esta carta: dale una carta de Estado \"Duro\" al Líder enemigo y a todos los Esbirros. Si el Líder enemigo ya era Duro, esta carta gana Oleada."},
  "56187": {"n":"Defensores callejeros","t":"Cuando se muestre esta carta: cada Esbirro se activa contra el jugador al que esté enfrentado. De no ser posible, el Líder enemigo se activa contra ti. No le des una carta de aumento para esta activación."},
  "56188": {"n":"Los Defensores","t":"Complicación 1[per_hero].\nTodos los Esbirros ganan Guardia.","f":"Los Defensores were formed to protect people often overlooked by the Vengadores."},
  "56189": {"t":"Cuando se muestre esta carta: el equipo enemigo agota un personaje que controles.\n[star] Aumento: agota un personaje que controles.","f":"\"My respect for the law doesn't blind my sense of right y wrong.\""},
  "56190": {"n":"Puño de Hierro","t":"Cuando se muestre esta carta: Puño de Hierro ataca a tu Líder. De no ser posible, Puño de Hierro se activa contra ti.\n[star] Aumento: el Líder enemigo ataca a tu Líder (después de esta activación). No le des una carta de aumento para este ataque."},
  "56191": {"n":"Miembro de la resistencia","t":"Vincula esta carta a un Esbirro elegido por el equipo enemigo. De no ser posible, esta carta gana Oleada.\nEl Esbirro vinculado recibe +4 de Vida y gana Firmeza.\n[star] Aumento: vincula esta carta a un Esbirro que esté enfrentado a ti."},
  "56192": {"n":"Defensores callejeros","t":"Cuando se muestre esta carta: cada Esbirro se activa contra el jugador al que esté enfrentado. De no ser posible, el Líder enemigo se activa contra ti. No le des una carta de aumento para esta activación."},
  "56193": {"n":"Defender la Cocina del Infierno","t":"Complicación 1[per_hero].\nNo puede quitarse Amenaza de este Plan mientras haya en juego un Esbirro Defensor.","f":"\"Tell S.H.I.E.L.D. to pull back. This city is debajo our protection.\" —Daredevil"},
  "56194": {"n":"Capa","t":"Cuando se muestre esta carta: coloca 2 de Amenaza sobre un Plan. En el modo Competitivo, quita 2 de Amenaza del Plan principal de tu Líder.\n[star] Aumento: si Puñal está en juego, muestra a Capa. De no ser así, coloca 1 de Amenaza sobre un Plan."},
  "56195": {"n":"Puñal","t":"Cuando se muestre esta carta: cura 2 de Daño al Líder enemigo. Inflige 2 de Daño a un personaje que controles.\n[star] Aumento: si Capa está en juego, muestra a Puñal. De no ser así, inflige 1 de Daño a un personaje que controles."},
  "56196": {"n":"Fuerza oscura","t":"Vincula esta carta al Líder enemigo y dale una carta de Estado \"Duro\".\n[star] Respuesta obligada: después de que el Líder vinculado ejecute el Plan y coloque Amenaza sobre el Plan principal, quita esa misma cantidad de Amenaza del Plan principal de tu Líder. Descarta esta carta."},
  "56197": {"n":"Fuerza luminosa","t":"Cuando se muestre esta carta: cura 3 de Daño al Líder enemigo. Sufres 3 de Daño indirecto."},
  "56198": {"n":"Capa y Puñal","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: cura 3 de Daño al Líder enemigo y dale una carta de Estado \"Duro\".","f":"Capa y Puñal were among the primer to join Capitán América's superhero resistance."},
  "56199a": {"n":"Resistencia superheroica","t":"Contenido: Líder escogido I y II (III y IV para jugar en modo Experto). Conjunto de Encuentros del Líder escogido, Normal, y 3–4 conjuntos modulares.\nPreparación: En el modo Competitivo, el equipo enemigo localiza el Plan secundario Escoger un Bando y tu equipo lo muestra. En el modo Cooperativo, localiza el Plan secundario del Líder escogido y muéstralo."},
  "56199b": {"n":"Llamamiento","t":"Si hay más de 1 jugador en tu equipo, esta etapa gana Complicación 2[per_hero].\nTodos los Esbirros ganan Guardia.","f":"Capitán América's public denouncement of the Ley de Registro de Superhumanos drew many Aliados to his side."},
  "56200a": {"n":"Resistencia superheroica","t":"Contenido: Líder escogido I y II (III y IV para jugar en modo Experto). Conjunto de Encuentros del Líder escogido, Normal, y 3–4 conjuntos modulares.\nPreparación: En el modo Competitivo, el equipo enemigo localiza el Plan secundario Escoger un Bando y tu equipo lo muestra. En el modo Cooperativo, localiza el Plan secundario del Líder escogido y muéstralo."},
  "56200b": {"n":"Pasar a la clandestinidad","t":"Si hay más de 1 jugador en tu equipo, esta etapa gana Complicación 2[per_hero].\nEl Líder enemigo gana Tesón.","f":"\"I forgot how exhausting it is to be undercover!\" —Spiderwoman"},
  "56201a": {"n":"Actos de resistencia","f":"El Capitán América y sus Vengadores se ven obligados a pasar a la clandestinidad para no ser arrestados por oponerse a la Ley de Registro. Cuando Iron Man y la Capitana Marvel empiezan a capturar a sus amigos superhumanos, los miembros de este grupo de resistencia deciden contraatacar."},
  "56201b": {"n":"Guerra de Guerillas","t":"Respuesta obligada: después de que se coloque una carta de Estado sobre el Líder enemigo, coloca 1 de Amenaza sobre esta carta.\nSi se completa esta etapa, los jugadores pierden la partida."},
  "56202a": {"n":"Actos de resistencia","f":"El Capitán América y sus Vengadores se ven obligados a pasar a la clandestinidad para no ser arrestados por oponerse a la Ley de Registro. Cuando Iron Man y la Capitana Marvel empiezan a capturar a sus amigos superhumanos, los miembros de este grupo de resistencia deciden contraatacar."},
  "56202b": {"n":"Fuga de Superhéroes","t":"[star] Respuesta obligada: después de resolver el paso 1 de la fase del Villano, cada jugador descarta la primera carta del mazo de Encuentros. Cada jugador que haya descartado un Esbirro de este modo lo pone en juego enfrentado a él.\nSi se completa esta etapa, los jugadores pierden la partida."},
  "56203": {"n":"Una causa justa","t":"Cuando se muestre esta carta: el Líder enemigo ejecuta el Plan. Si hay más de 1 jugador en tu equipo, dale al Líder enemigo una carta de aumento adicional para esta activación.","f":"\"I was a double agent for years. There's not much I won't do for a just cause.\" —Spiderwoman"},
  "56204": {"n":"Lo que haga falta","t":"Cuando se muestre esta carta (Alter ego): el Líder enemigo ataca a tu Líder.\nCuando se muestre esta carta (Héroe): el Líder enemigo te ataca.","f":"\"I'm sobre target. Commence ataque.\" —Captain Marvel"},
  "56205": {"n":"Ataque dirigido","t":"Cuando se muestre esta carta: el equipo enemigo busca una carta entre las 5 primeras cartas del mazo de Encuentros y te la da como carta de Encuentro boca abajo.\n[star] Aumento: esta carta gana [boost] por cada jugador que haya en tu equipo."},
  "56206a": {"n":"Escoger un bando","t":"Permanente.\nEl Líder enemigo no puede sufrir más de 2 de Daño de cada ataque.\nRespuesta obligada: después de que se quite la última ficha de Amenaza de esta carta, el equipo enemigo busca 1[per_hero] cartas de Encuentro entre las 5 primeras cartas del mazo de Encuentros y reparte una a cada jugador como carta de Encuentro boca abajo. Dale la vuelta a esta carta."},
  "56206b": {"n":"Ahora es personal","t":"Dale esta carta al jugador inicial.\nAcción: retira esta carta de la partida → cada jugador de tu equipo elige 2 cartas de Jugador de tu Líder que estén apartadas y las añade a su mano."},
  "56207": {"n":"¡No, muévete tú!","t":"Interrupción obligada: cuando el Líder enemigo vaya a atacarte, en vez de eso vincula el Escudo del Capi a tu Líder Capitán América y resuelve este ataque contra él. Descarta esta carta."},
  "56208": {"n":"Pelear sucio","t":"Acción: tu Líder Capitán América ataca al Líder enemigo. Si has gastado un recurso [physical] para pagar el coste de este Evento, aturde al Líder enemigo.","f":"\"Las cosas son un poco distintas esta vez. Ahora peleo sucio.\" —Capitán América"},
  "56209": {"n":"Reclutado por el Capitán","t":"Acción: elige un Esbirro que esté enfrentado a ti y elige a un jugador del equipo enemigo. Ese Esbirro se enfrenta a ese jugador.","f":"\"Nos alegramos de que estés de nuestro lado.\" —Capitán América"},
  "56210": {"n":"El héroe del pueblo","t":"Respuesta de Héroe: después de que gastes este recurso, dale una carta de aumento boca abajo a tu Líder Capitán América."},
  "56211": {"n":"Agente doble","t":"Acción: quita 2 de Amenaza del Plan principal. Coloca 2 de Amenaza sobre el Plan principal de tu Líder.","f":"\"Cuando alguien va a por uno de los nuestros, tiene que responder ante todos nosotros.\" —Spiderwoman"},
  "56212": {"n":"Descarga arácnida","t":"Acción: tu Líder Spiderwoman ataca al Líder enemigo. Si has gastado un recurso [mental] para pagar el coste de este Evento, confunde al Líder enemigo.","f":"\"A partir de ahora, Spiderwoman ya no huirá!\" —Spiderwoman"},
  "56213": {"n":"Blanco difícil","t":"Vincula esta carta a tu Líder Spiderwoman y dale una carta de Estado \"Duro\".\nRespuesta obligada: después de que la Spiderwoman vinculada resuelva un ataque, coloca 2 contadores de Habilidad sobre su Accesorio Sutileza. Descarta esta carta."},
  "56214": {"n":"Contacto secreto","t":"Respuesta de Héroe: después de que gastes este recurso, coloca 2 contadores de Habilidad sobre el Accesorio Sutileza de tu Líder Spiderwoman."},
  "57001": {"n":"Hulka","t":"Preparación: el equipo enemigo localiza una copia de Fuerza sobrehumana y la vincula a Hulka.\nRespuesta obligada: después de que un Alter ego cambie a su identidad de Héroe, inflige 1 de Daño a ese Héroe."},
  "57002": {"n":"Hulka","t":"Tesón.\nCuando se muestre esta carta: dale una carta de Encuentro a cada jugador. Hulka no puede sufrir Daño en esta fase.\nRespuesta obligada: después de que un Alter ego cambie a su identidad de Héroe, inflige 1 de Daño a ese Héroe."},
  "57003": {"n":"Hulka","t":"Preparación: el equipo enemigo localiza una copia de Fuerza sobrehumana y la vincula a Hulka.\nRespuesta obligada: después de que un Alter ego cambie a su identidad de Héroe, inflige 1 de Daño a ese Héroe."},
  "57004": {"n":"Hulka","t":"Tesón.\nCuando se muestre esta carta: dale una carta de Encuentro a cada jugador. Hulka no puede sufrir Daño en esta fase.\nRespuesta obligada: después de que un Alter ego cambie a su identidad de Héroe, inflige 1 de Daño a ese Héroe."},
  "57005a": {"n":"Ley de Registro de Superhumanos","t":"Contenido: Líder escogido I y II (III y IV para jugar en modo Experto). Conjuntos de Encuentros del Líder escogido, Normal, y 3–4 conjuntos modulares.\nPreparación: en el modo Competitivo, el equipo enemigo localiza el Plan secundario Escoger un bando y tu equipo lo muestra. En el modo Cooperativo, localiza el Plan secundario del Líder escogido y muéstralo."},
  "57005b": {"n":"Imponer la ley","t":"Si hay más de 1 jugador en tu equipo, esta etapa gana Complicación 2[per_hero].\nEl Líder enemigo gana Tesón.","f":"\"¡Todo esto podría evitarse si respetaseis la ley!\" —Hulka"},
  "57006a": {"n":"Medidas para el registro","f":"Iron Man y sus Vengadores tienen orden de capturar a todo individuo con superpoderes que se niegue a inscribirse en el registro de S.H.I.E.L.D. Esto incluye a antiguos compañeros de equipo como el Capitán América y Spiderwoman."},
  "57006b": {"n":"Poderosos Vengadores","t":"Mientras el Líder enemigo esté atacando, recibe +1 ATQ (+2 ATQ si es un ataque no defendido).\nSi se completa esta etapa, los jugadores pierden la partida.","f":"Los Vengadores de Iron Man tienen tanta fe en la reforma superheroica que lideran la ofensiva contra sus antiguos compañeros de equipo."},
  "57007": {"n":"Fuerza sobrehumana","t":"Vincula esta carta a Hulka.\n[star] Interrupción obligada: cuando Hulka ataca, este ataque gana Brutalidad. Descarta esta carta después de este ataque.\n[star] Aumento: muestra esta carta."},
  "57008": {"n":"Furia concentrada","t":"Vincula esta carta a Hulka.\nHulka gana Firmeza.\n[star] Respuesta obligada: después de que Hulka ejecute el Plan, descarta esta carta.\n[star] Aumento: muestra esta carta."},
  "57009": {"n":"Sucesión de puñetazos","t":"Cuando se muestre esta carta (Alter ego): Hulka ejecuta el Plan. Dale una carta de Estado \"Duro\".\nCuando se muestre esta carta (Héroe): Hulka te ataca. Dale una carta de Estado \"Duro\".","f":"\"¡No lo pongáis más dificil de lo que ya es!\" —Hulka"},
  "57010": {"n":"Pisotón","t":"Cuando se muestre esta carta: agota todos los personajes que controles. Si no se agota nigún personaje de este modo, esta carta gana Oleada.\n[star] Aumento: agota un personaje que controles."},
  "57011": {"n":"Apisonadora gamma","t":"Cuando se muestre esta carta: descarta el Aliado o Apoyo con el coste más alto que controles. Coloca tanta Amenaza sobre el Plan principal como el coste de esa carta. Si no se coloca Amenaza sobre el Plan principal de este modo, esta carta gana Oleada.","f":"\"¡Te has metido con la mujer equivocada!\" —Hulka"},
  "57012": {"n":"Proceso judicial","t":"Ni Héroes ni Aliados pueden quitar Amenaza de este Plan.\nRespues de Alter ego: después de que cambies de identidad, agota tu Superhéroe → quita 3 de Amenaza de este Plan."},
  "57013": {"n":"Coordinador de S.H.I.E.L.D.","t":"Patrulla.\nCuando se muestre esta carta: coloca 2 de Amenaza sobre el Plan principal.","f":"\"Superhumano no registrado localizado en la 43 con Madison. Unidad doce, acuda para interceptar.\""},
  "57014": {"n":"Vigilancia estratégica","t":"Cuando se muestre esta carta: dale una carta de Estado \"Duro\" al Líder enemigo y a todos los Esbirros.\n[star] Aumento: dale al enemigo activado una carta de Estado \"Duro\".","f":"\"Sabía que no podíamos confiar en ese tío.\" —Maria Hill"},
  "57015": {"n":"Respuesta rápida","t":"Cuando se muestre esta carta: descarta cartas del mazo de Encuentros hasta que se descarte un Esbirro. Si tienes adoptada tu identidad de:\n• Alter ego, coloca tanta Amenaza sobre el Plan principal como el PLA de ese Esbirro.\n• Héroe, inflige tanto Daño a tu Héroe como el ATQ de ese Esbirro."},
  "57016": {"n":"Seguridad Nacional","t":"Complicación 1[per_hero].\nEl primer Esbirro mostrado cada ronda gana Oleada.","f":"\"Se ha detectado actividad superhumana ilegal en esta zona. ¡POr favor, vuelvan a sus casas y no salgan!\" —Agente de S.H.I.E.L.D."},
  "57017": {"t":"Cuando se muestre esta carta: aturde a tu Líder. De no ser posible, quedas aturdido.\n[star] Aumento: aturde a tu Líder. De no ser posible, quedas aturdido.","f":"\"Voy a hacerte sufrir, hombrecillo.\""},
  "57018": {"n":"Pájaro Cantor","t":"Cuando se muestre esta carta: confunde a tu Líder. De no ser posible, quedas confundido.\n[star] Aumento: confunde a tu Líder. De no ser posible, quedas confundido.","f":"\"Eso ha salido mejor de lo que esperaba.\""},
  "57019": {"n":"Penitencia","t":"Cuando se muestre esta carta: inflige 2 de Daño a tu Líder. De no ser posible, inflige 2 de Daño a un personaje que controles.\n[star] Aumento: inflige 2 de Daño a tu Líder. De no ser posible, inflige 1 de Daño a un personaje que controles."},
  "57020": {"n":"La justicia, como el rayo","t":"Cuando se muestre esta carta: cada Esbirro se activa contra el jugador al que esté enfrentado. De no ser posible, el Líder enemigo se activa contra ti. No le des una carta de aumento para esta activación.","f":"\"Todos somos culpables. ¡Esto es justicia!\" —Penitencia"},
  "57021": {"n":"Los Thunderbolts","t":"Complicación 1[per_hero].\nNo puede quitarse Amenaza de este Plan mientras haya en juego un Esbirro Thunderbolt.","f":"El gobierno ofreció dos alternativas a los supercriminales: pudrirse en la cárcel o unirse a los Thunderbolts."},
  "57022": {"n":"Supervisor","t":"Represalia 1. Dureza. Infame.\nCuando se muestre esta carta: Supervisor se activa contra ti.","f":"\"¡Pienso cobrar un plus a S.H.I.E.L.D. por esto!\""},
  "57023": {"n":"Espada del Supervisor","t":"Vincula esta carta a Supervisor. De no ser posible, vincula esta carta al Líder enemigo.\n[star] Los ataques del personaje vinculado ganan Penetrante.\nAcción de Héroe: gasta recursos [mental] [physical] → descarta esta carta."},
  "57024": {"n":"Escudo del Supervisor","t":"Vincula esta carta a Supervisor. De no ser posible, vincula esta carta al Líder enemigo.\nInterrupción obligada: cuando el personaje vinculado vaya a sufrir cualquier cantidad de Daño, reduce esa cantidad en 1.\nAcción de Héroe: gasta recursos [mental] [physical] → descarta esta carta."},
  "57025": {"n":"Movimiento imitado","t":"Cuando se muestre esta carta: si Supervisor está en juego, ataca a tu Líder. De no ser posible, dale al Líder enemigo una carta de Estado \"Duro\" y una carta de aumento boca abajo.\n[star] Aumento: dale al enemigo una carta de aumento adicional."},
  "57026": {"n":"La academia del Supervisor","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: dale al Líder enemigo una carta de Estado \"Duro\" y una carta de aumento boca abajo.","f":"\"¿Creéis que soy demasiado estricto? ¡Ya me lo agradeceréis cuando tengáis que luchar contra Steve Rogers!\" —Supervisor"},
  "57027": {"n":"Bufón","t":"Cuando se muestre esta carta: descarta las 3 primeras cartas de tu mazo. Sufres 1 de Daño indirecto por cada tipo de carta distinto que se haya descartado de este modo.","f":"\"¡Ja, ja! ¡Esto es la monda! ¡Ahora nos ordenan a nosotros que cacemos a los héroes!\""},
  "57028": {"t":"Cuando se muestre esta carta: descarta las 3 primeras cartas de tu mazo. Coloca 1 de Amenaza sobre el Plan principal por cada tipo de carta distinto que se haya descartado de este modo.","f":"\"¡No puedo creer que nos paguen por esto!\""},
  "57029": {"n":"Plataforma de Jack","t":"Vincula esta carta a un Esbirro elegido por el equipo enemigo. De no ser posible, esta carta gana Oleada.\nEl Esbirro vinculado recibe +4 de Vida y gana Firmeza.\n[star] Aumento: vincula esta carta a un Esbirro que esté enfrentado a ti."},
  "57030": {"n":"Yoyó de Bufón","t":"Cuando se muestre esta carta: descarta la carta con el coste más alto que controles. De no ser posible, esta carta gana Oleada.\n[star] Aumento: descarta una Mejora que controles."},
  "57031": {"n":"Dúo mortal","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: cada jugador descarta las 8 primeras cartas de su mazo.","f":"El Bufón y Jack O'Lantern están encantados de cumplir la orden de S.H.I.E.L.D. de cazar héroes renengados."},
  "57032": {"n":"Conducta inadmisible","t":"Interrupción: cuando vaya a colocarse cualquier cantidad de Amenaza sobre el Plan principal, exclama \"¡Protesto!\" y evita 3 de esa Amenaza."},
  "57033": {"n":"Hulka aplasta","t":"Acción: tu Líder Hulka ataca al Líder enemigo. Si has gastado un recurso [physical] para pagar el coste de este Evento, aturde al Líder enemigo.","f":"\"¡Se acabó! ¡Ya me has cabreado!\" —Hulka"},
  "57034": {"n":"Enfádame","t":"Vincula esta carta a tu Líder Hulka.\nRespuesta obligada: después de que un Héroe o Líder ataque a la Hulka vinculada, ésta ataca a ese personaje. Luego descarta esta carta."},
  "57035": {"n":"Asesoramiento legal","t":"Respuesta de Héroe: después de que gastes este recurso, traslada 1 de Amenaza desde el Plan principal hasta el Plan principal de tu Líder."},
  "57036": {"n":"Una causa justa","t":"Cuando se muestre esta carta: el Líder enemigo ejecuta el Plan. Si hay más de 1 jugador en tu equipo, dale al Líder enemigo una carta de aumento adicional para esta activación.","f":"\"I was a double agent for years. There's not much I won't do for a just cause.\" —Spiderwoman"},
  "57037": {"n":"Lo que haga falta","t":"Cuando se muestre esta carta (Alter ego): el Líder enemigo ataca a tu Líder.\nCuando se muestre esta carta (Héroe): el Líder enemigo te ataca.","f":"\"I'm sobre target. Commence ataque.\" —Captain Marvel"},
  "57038": {"n":"Ataque dirigido","t":"Cuando se muestre esta carta: el equipo enemigo busca una carta entre las 5 primeras cartas del mazo de Encuentros y te la da como carta de Encuentro boca abajo.\n[star] Aumento: esta carta gana [boost] por cada jugador que haya en tu equipo."},
  "57039a": {"n":"Escoger un bando","t":"Permanente.\nEl Líder enemigo no puede sufrir más de 2 de Daño de cada ataque.\nRespuesta obligada: después de que se quite la última ficha de Amenaza de esta carta, el equipo enemigo busca 1[per_hero] cartas de Encuentro entre las 5 primeras cartas del mazo de Encuentros y reparte una a cada jugador como carta de Encuentro boca abajo. Dale la vuelta a esta carta."},
  "57039b": {"n":"Ahora es personal","t":"Dale esta carta al jugador inicial.\nAcción: retira esta carta de la partida → cada jugador de tu equipo elige 2 cartas de Jugador de tu Líder que estén apartadas y las añade a su mano."},
  "57040": {"n":"La Visión","t":"Preparación: el equipo enemigo localiza el Accesorio de identidad de masa de La Visión y la vincula a La Visión, con la cara de Denso boca arriba.\nRespuesta obligada: después de resolver el paso 1 de la fase del Villano, dale la vuelta a la identidad de masa de La Visión."},
  "57041": {"n":"La Visión","t":"Tesón.\nCuando se muestre esta carta: dale una carta de Encuentro a cada jugador. La Visión no puede sufrir Daño en esta fase.\nRespuesta obligada: después de resolver el paso 1 de la fase del Villano, dale la vuelta a la identidad de masa de La Visión."},
  "57042": {"n":"La Visión","t":"Preparación: el equipo enemigo localiza el Accesorio de identidad de masa de La Visión y la vincula a La Visión, con la cara de Denso boca arriba.\nRespuesta obligada: después de resolver el paso 1 de la fase del Villano, dale la vuelta a la identidad de masa de La Visión."},
  "57043": {"n":"La Visión","t":"Tesón.\nCuando se muestre esta carta: dale una carta de Encuentro a cada jugador. La Visión no puede sufrir Daño en esta fase.\nRespuesta obligada: después de resolver el paso 1 de la fase del Villano, dale la vuelta a la identidad de masa de La Visión."},
  "57044a": {"n":"Resistencia superheroica","t":"Contenido: Líder escogido I y II (III y IV para jugar en modo Experto). Conjuntos de Encuentros del Líder escogido, Normal, y 3–4 conjuntos modulares.\nPreparación: en el modo Competitivo, el equipo enemigo localiza el Plan secundario Escoger un bando y tu equipo lo muestra. En el modo Cooperativo, localiza el Plan secundario del Líder escogido y muéstralo."},
  "57044b": {"n":"Proteger las identidades secretas","t":"Si hay más de 1 jugador en tu equipo, esta etapa gana Complicación 2[per_hero].\n[star] Respuesta obligada: después de resolver el paso 1 de la fase del Villano, cada jugador descarta las 3 primeras cartas de su mazo.","f":"Si renuncian a sus máscaras, los héroes se ponen en peligro a sí mismos y a sus seres queridos."},
  "57045a": {"n":"Actos de resistencia","f":"El Capitán América y sus Vengadores se ven obligados a pasar a la clandestinidad para no ser arrestados por oponerse a la Ley de Registro. Cuando Iron Man y la Capitana Marvel empiezan a capturar a sus amigos superhumanos, los miembros de este grupo de resistencia deciden contraatacar."},
  "57045b": {"n":"Divulgar los abusos","t":"Los Aliados entran en juego agotados.\nSi se completa esta etapa, los jugadores pierden la partida.","f":"\"Si revelamos la existencia de la prisión clandestina de S.H.I.E.L.D., perderán el apoyo de la opinión pública.\" —La Visión"},
  "57046a": {"n":"Denso","t":"Permanente. Identidad de masa.","f":"La Visión controla las moléculas de su cuerpo para volverse intangible, o tan denso que las armas se hacen añicos al golpearle."},
  "57046b": {"t":"Permanente. Identidad de masa.\nInterrupción obligada: cuando La Visión vaya a sufrir cualquier cantidad de Daño, reduce esa cantidad en 1.","f":"\"La innivación es el arma definitiva.\" —La Visión"},
  "57047": {"n":"Gema solar","t":"Vincula esta carta a La Visión.\nLa Visión gana Firmeza.\nRespuesta de Héroe: después de que realices un ataque básico contra La Visión, gasta recursos [energy] [physical] → descarta esta carta y dale la vuelta a la identidad de masa de La Visión.\n[star] Aumento: muestra esta carta."},
  "57048": {"n":"Capa de la Visión","t":"Vincula esta carta a La Visión.\nLa Visión gana Represalia 1.\nRespuesta de Héroe: después de que realices un ataque básico contra La Visión, gasta recursos [energy] [mental] → descarta esta carta y dale la vuelta a la identidad de masa de La Visión.\n[star] Aumento: muestra esta carta."},
  "57049": {"n":"Aumento de masa","t":"Vincula esta carta a La Visión.\nInterrupción obligada: cuando un personaje ataque a La Visión estando en juego su Accesorio de identidad de masa Denso, evita todo el Daño de ese ataque y aturde al personaje atacante. Descarta esta carta.","f":"\"¡Alto!\" —La Visión"},
  "57050": {"n":"Control de la densidad","t":"Oleada. Vincula esta carta a La Visión.\nInterrupción obligada: cuando La Visión se active, si está activación consiste en:\n• Ejecutar el Plan, dale la vuelta a la identidad de masa de La Visión para volverlo Intangible.\n• Atacar, dale la vuelta a la identidad de masa de La Visión para volverlo Denso.\nLuego, si le has dado la vuelta al Acesorio de identidad de masa de La Visión, descarta esta carta."},
  "57051": {"n":"Rayo solar","t":"Cuando se muestre esta carta (Alter ego): La Visión ejecuta el Plan. Si está en juego su Accesorio de identidad de masa Intangible, La Visión recibe +1 PLA para esta ejecución.\nCuando se muestre esta carta (Héroe): La Visión te ataca. Si está en juego su Accesorio de identidad de masa Denso, La Visión recibe +1 ATQ para este ataque."},
  "57052": {"n":"Golpe superdenso","t":"Cuando se muestre esta carta: agota un personaje que controles. Si está en juego el Accesorio de identidad de masa Denso, inflige 2 de Daño a ese personaje. Si está en juego el Accesorio de identidad de masa Intangible, dale la vuelta a ese Accesorio.","f":"\"POr favor, no os resistáis o me veré obligado a emplear una fuerza aún mayor.\" —La Visión"},
  "57053": {"n":"Disrupción de fase","t":"Cuando se muestre esta carta: el equipo enemigo agota una Mejora que controles. Si está en juego el Accesorio de identidad de masa Intangible, en vez de eso descarta esa Mejora. Si está en juego el Accesorio de identidad de masa Denso, dale la vuelta a ese Accesorio.","f":"\"Objetivo neutralizado.\" —La Visión"},
  "57054": {"n":"Pasar a través","t":"Cuando se derrote esta carta: el jugador que haya derrotado este Plan confunde a su Superhéroe. De no ser posible, aturde a su Superhéroe.","f":"El poder de La Visión para cambiar de fase lo convierte en un adversario difícil e impredecible."},
  "57055": {"n":"Patriota","t":"Dureza.\nCuando se muestre esta carta: dale al Líder enemigo una carta de Estado \"Duro\".","f":"\"¿Estos no saben que nosotros somos los buenos?\""},
  "57056": {"n":"Ojo de Halcón","t":"[star] Los ataques de Ojo de Halcón ganan A distancia y Penetrante.\nCuando se muestre esta carta: descarta una Mejora que controles.","f":"\"¡Muérete de envidia, Clint!\""},
  "57057": {"n":"Estatura","t":"Guardia.\nCuando se muestre esta carta: descarta un Apoyo que controles.","f":"\"¡No deberías ningunear a una chica que puede alcanzar el tamaño de un edificio!\""},
  "57058": {"n":"Superhéroes adolescentes","t":"Cuando se muestre esta carta: resuelve las capacidades del tipo \"Cuando se muestre esta carta\" de todos los Esbirros que haya en juego. Si no se resuelve de este modo ninguna capacidad del tipo \"Cuando se muestre esta carta\", esta carta gana Oleada.","f":"\"Jóvenes Vengadores, reuníos!\" —Kate Bishop"},
  "57059": {"n":"Jóvenes Vengadores","t":"Complicación 1[per_hero].\nEl primer Esbirro mostrado en cada ronda gana Oleada.","f":"La próxima generación de superhéroes espera poder continuar el legado de sus mayores."},
  "57060": {"n":"Veloz","t":"Ataque veloz.\nCuando se muestre esta carta: quedas aturdido. De no ser así, inflige 2 de Daño a tu Superhéroe.","f":"\"Hey! Geriatrics! Let's get a traslada on.\""},
  "57061": {"t":"Incitar 1.\nCuando se muestre esta carta: quedas confundido. De no ser así, coloca 2 de Amenaza sobre el Plan principal.","f":"\"Os habéis metido con los críos equivocados.\""},
  "57062": {"n":"Supervelocidad","t":"Cuando se muestre esta carta: descarta 1 carta de tu mano al azar. Sufres tanto Daño indirecto como su coste.\n[star] Aumento: descarta 1 carta de tu mano.","f":"\"Nolo has visto venir, ¿verdad?\" Veloz"},
  "57063": {"n":"Hechiceria","t":"Interrupción obligada: cuando juegues una carta, anula sus efectos y descártala. Luego descarta esta carta.","f":"\"LUZCEGADORALUZCEGADORA.\" —Wiccan"},
  "57064": {"n":"Hermanos con superpoderes","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: el jugador que haya derrotado este Plan descarta 1 carta de su mano.","f":"Wiccan y Veloz asiguen los pasos de sus superheroicos padres: la Visión y la Bruja Escarlata."},
  "57065": {"n":"Caballero Luna","t":"Represalia 2. Dureza.\nCuando se muestre esta carta: resuelve la capacidad \"Cuando se muestre esta carta\" de la primera carta de Perfidia que haya en la pila de descartes del mazo de Encuentros.","f":"\"Te has metido en un buen lío.\""},
  "57066": {"n":"Cuchilla lunar","t":"Vincula esta carta al Caballero Luna. De no ser posible, vincula esta carta al Líder enemigo.\n[star] Interrupción obligada: cuando el personaje vinculado ataque, este ataque gana A distancia y Penetrante. Descarta esta carta después este ataque."},
  "57067": {"n":"Puño de Khonshu","t":"Cuando se muestre esta carta: agota tu carta de Superhéroe e inflígele 2 de Daño.\n[star] Aumento: agota tu carta de Superhéroe.","f":"\"¡Soy el puño de Khonshu! ¡Soy la venganza!\" —Caballero Luna"},
  "57068": {"n":"Avatar de Khonshu","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte una carta de Perfidia. Resuelve la capacidad \"Cuando se muestre esta carta\" de esa carta."},
  "57069": {"t":"Cuando se muestre esta carta: si tienes el rasgo Perseguido, Janus se activa contra ti. De no ser así, descarta las 2 primeras cartas de tu mazo.","f":"\"¡Nadie escapa a la Guardia Real atlante!\""},
  "57070": {"t":"Cuando se muestre esta carta: si tienes el rasgo Perseguido, Amir se activa contra ti. De no ser así, descarta las 2 primeras cartas de tu mazo.","f":"\"Mi señor Namor ha ordenado que comparezcas ante él.\""},
  "57071": {"n":"Atlantes","t":"Cuando se muestre esta carta: descarta las 3 primeras cartas de tu mazo. Si tienes adoptada tu identidad de:\n• Alter ego, coloca 1 de Amenaza sobre el Plan principal por cada tipo de carta distinto que se haya descartado de este modo.\n• Héroe, sufres 1 de Daño indirecto por cada tipo de carta distinto que se haya descartado de este modo."},
  "57072": {"n":"Deuda de sangre","t":"Ganas el rasgo Perseguido.\nAcción de Alter ego: descarta las 8 primeras cartas de tu mazo → descarta esta carta."},
  "57073": {"n":"La Guardia Real","t":"Complicación 1[per_hero].\nCuando se derrote esta carta: el equipo enemigo busca una copia de Deuda de sangre en el mazo de Encuentros y en su pila de descartes, y se la da como carta de Encuentro boca abajo al jugador que haya derrotado este Plan."},
  "57074": {"n":"Riesgo calculado","t":"Acción: busca una carta de Encuentro entre las 5 primeras cartas del mazo de Encuentros de tu Líder y dásela al jugador inicial del equipo enemigo como carta de Encuentro boca abajo.","f":"\"No existe victoria sin riesgo.\" —La Visión"},
  "57075": {"n":"Golpe de sintezoide","t":"Acción: tu Líder La Visión ataca al Líder enemigo. Si el Accesorio de identidad de masa de La Visión es:\n• Denso, La Visión recibe +1 ATQ para este ataque y además este ataque gana Penetrante.\n• Intangible, dale la vuelta para convertirno en Denso antes antes de resolver este ataque."},
  "57076": {"n":"Interferencia fásica","t":"Acción: elige un Accesorio vinculado al Líder enemigo que contenga las palabras \"Respuesta de Héroe\" o \"Interrupción de Héroe\" y descártalo.","f":"\"Mi capacidad de traspasar dispositivos electrónicos puede neutralizar la tecnología de Stark.\" —La Visión"},
  "57077": {"n":"Ayuda androide","t":"Interrupción de Héroe: cuando gastes este recurso, dale la vuelta al Accesorio de identidad de masa de tu Líder La Visión."},
  "57078": {"n":"Una causa justa","t":"Cuando se muestre esta carta: el Líder enemigo ejecuta el Plan. Si hay más de 1 jugador en tu equipo, dale al Líder enemigo una carta de aumento adicional para esta activación.","f":"\"I was a double agent for years. There's not much I won't do for a just cause.\" —Spiderwoman"},
  "57079": {"n":"Lo que haga falta","t":"Cuando se muestre esta carta (Alter ego): el Líder enemigo ataca a tu Líder.\nCuando se muestre esta carta (Héroe): el Líder enemigo te ataca.","f":"\"I'm sobre target. Commence ataque.\" —Captain Marvel"},
  "57080": {"n":"Ataque dirigido","t":"Cuando se muestre esta carta: el equipo enemigo busca una carta entre las 5 primeras cartas del mazo de Encuentros y te la da como carta de Encuentro boca abajo.\n[star] Aumento: esta carta gana [boost] por cada jugador que haya en tu equipo."},
  "57081a": {"n":"Escoger un bando","t":"Permanente.\nEl Líder enemigo no puede sufrir más de 2 de Daño de cada ataque.\nRespuesta obligada: después de que se quite la última ficha de Amenaza de esta carta, el equipo enemigo busca 1[per_hero] cartas de Encuentro entre las 5 primeras cartas del mazo de Encuentros y reparte una a cada jugador como carta de Encuentro boca abajo. Dale la vuelta a esta carta."},
  "57081b": {"n":"Ahora es personal","t":"Dale esta carta al jugador inicial.\nAcción: retira esta carta de la partida → cada jugador de tu equipo elige 2 cartas de Jugador de tu Líder que estén apartadas y las añade a su mano."},
  "58001a": {"n":"Hombre Maravilla","t":"Reciclaje de poderes — Hombre Maravilla recibe +1 ATQ por cada carta que haya metida debajo de Fisiología iónica.\n[star] Respuesta obligada: después de que el Hombre Maravilla realice un ataque básico, descarta todas las cartas que haya metida debajo de Fisiología iónica."},
  "58001b": {"t":"Ser de energía iónica — Puedes incluir en tu mazo Eventos de cualquier aspecto que tengan impreso un icono de recurso [energy].\nPreparación: pon en juego Fisiología iónica."},
  "58002": {"n":"Fisiología iónica","t":"Permanente. Máximo de 3 cartas metidas debajo de esta carta.\nRespuesta: después de que juegues un Evento que tenga impreso un recurso [energy], mete ese Evento debajo de esta carta desde tu pila de descartes → cura 1 de Daño a tu Superhéroe."},
  "58003": {"n":"Altruismo activo","t":"Acción de Héroe (intervención): quita 1 de Amenaza de un Plan. Quita 2 de Amenaza adicionales de ese Plan por cada recurso [energy] que hayas pagado de más por esta carta (hasta un máximo de [energy] [energy])."},
  "58004": {"n":"Descarga iónica","t":"Acción de Héroe (ataque): inflige 3 de Daño a un enemigo. Inflige 2 de Daño adicionales a ese enemigo por cada recurso [energy] que hayas pagado de más por esta carta (hasta un máximo de [energy] [energy] [energy])."},
  "58005": {"n":"Ver las estrellas","t":"Acción de Héroe (ataque): inflige tanto Daño a un enemigo como tu ATQ. Si has pagado de más un recurso [energy] por esta carta, aturde a ese enemigo."},
  "58006": {"n":"Extracción de energía","t":"Interrupción de Héroe: cuando gastes esta carta, sufres hasta 3 de Daño → esta carta genera 1 recurso [energy] adicional por cada de Daño sufrido de este modo."},
  "58007": {"n":"Admiradores maravillosos","t":"Acción de Alter ego: agota Admiradores maravillosos → elige:\n• Mete debajo de Fisiología iónica 1 Evento desde tu pila de descartes que tenga impreso un recurso [energy].\n• Roba 1 carta."},
  "58008": {"n":"Cinturón cohete","t":"Recurso de Héroe: agota el Cinturón cohete → genera un recurso [energy] para un Evento.\nRecurso de Héroe: agota a Cinturón cohete y descarta una carta que esté metida debajo de Fisiología iónica → genera un recurso [energy]."},
  "58009": {"n":"Estrella de Hollywood","t":"Recurso: genera un recurso [energy] para pagar de más por una carta. (Límite de una vez por carta.)","f":"\"Oye, ¿tú no salías en Colegas de vóley playa II?\" —Kate Bishop"},
  "58010": {"n":"Gafas de sol distintivas","t":"Respuesta: después de que cambies de identidad, elige:\n• Mete debajo de Fisiología iónica 1 Evento o recurso desde tu pila de descartes que tenga impreso un recurso [energy].\n• Añade a tu mano una carta que esté metida debajo de Fisiología iónica."},
  "58011": {"n":"\"¿Qué eres?\"","t":"Interrupción obligada: cuando el Hombre Maravilla vaya a ser derrotado, en vez de eso fija su medidor de Vida en 4 y cambia a la identidad de su Alter ego. Puedes meter debajo de Fisiología iónica Eventos desde tu pila de descartes que tengan impreso un recurso [energy] hasta que haya 3 cartas debajo de ella. Retira esta carta de la partida."},
  "58012": {"n":"Ave de Fuego","t":"Si has pagado de más por Ave de Fuego, coloca 1 contador de Renacimiento sobre su carta.\nInterrupción: cuando Ave de Fuego vaya a ser derrotada por Daño derivado, quítale 1 contador de Renacimiento → curale todo el Daño en vez de derrotarla."},
  "58013": {"n":"Ojo de Halcón","t":"Ojo de Halcón entra en juego con 4 contadores de Flechas.\nRespuesta: después de que un Aliado realice una intervención básica, quita 1 contador de Flechas de Ojo de Halcón → inflige 2 de Daño a un Esbirro."},
  "58014": {"n":"Bruja Escarlata","t":"Respuesta obligada: después de que juegues a la Bruja Escarlata, descarta la primera carta del mazo de Encuentros. Si es una carta de Perfidia, resuelve su capacidad de \"Cuando se muestre esta carta\"."},
  "58015": {"n":"El Vigía","t":"Respuesta obligada: después de que El Vigía entre en juego, busca un Plan secundario en el mazo de Encuentros y muéstralo. (Baraja el mazo.) Si no se muestra ningún Plan secundario de este modo, coloca 6 de Amenaza sobre el Plan principal."},
  "58016": {"n":"Benevolencia en combate","t":"Acción de Héroe: cura 2 de Daño a un enemigo → confunde a ese enemigo.","f":"\"¿Eh? ¿Es un truco?\" —Buitre"},
  "58017": {"n":"Bombas fuera","t":"Acción de Héroe: agota un personaje AÉREO que controles y elije un jugador → inflige 3 de Daño al Villano y a cada Esbirro que esté enfrentado a ese jugador."},
  "58018": {"n":"En todas partes a la vez","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Aéreo.\nAcción de Héroe (intervención): elige X Planes. Quita 2 de Amenaza de cada Plan elegido (3 de Amenaza si has pagado de más por esta carta)."},
  "58019": {"n":"Juntos somos más fuertes","t":"Interrupción de Héroe: cuando un personaje que no sea tu Héroe vaya a sufrir cualquier cantidad de Daño, si ese personaje tiene un Rasgo en común con tu Héroe, reduce ese Daño tantos puntos como tu DEF."},
  "58020": {"n":"Ataque combinado","t":"Interrupción de Héroe: cuando un Aliado use un atributo básico, agota tu Héroe → suma el atributo correspondiente de tu Héroe al de ese Aliado para este uso. Ese Aliado no sufre Daño derivado por este uso."},
  "58021": {"n":"Preparación heroica","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo 1 por jugador.\nRecibes +3 de Vida y tu Héroe recibe +1 INT."},
  "58022": {"n":"Espadachín","t":"[star] Los ataques básicos del Espadachín ganan Penetrante.\nRespuesta de Héroe: después de que se ponga boca arriba una carta de aumento durante un ataque no defendido, declara al Espadachín como defensor sin agotarlo."},
  "58023": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "58024": {"t":"Respuesta: después de que un Héroe Vengador cambie a la identidad de su Alter ego, agota a Jarvis → elige:\n• Ese Superhéroe recibe +2 REC hasta el final de la fase.\n• Descarta una carta de Estado de ese Superhéroe."},
  "58025": {"n":"Pacifismo","t":"Dale esta carta al jugador que lleva a Simon Williams.\nEl Hombre Maravilla no puede atacar.\nAcción de Alter ego: agota a Simon Williams o descarta 3 cartas que estén metidas debajo de Fisiología iónica → descarta esta carta."},
  "58026": {"n":"El Segador","t":"Ataque veloz.\n[star] Respuesta obligada: después de que El Segador ataque y derrote a un Aliado, dale una carta de Encuentro boca abajo al jugador que controla ese Aliado."},
  "58027": {"n":"Hermano contra hermano","t":"Como coste adicional para atacar a El Segador, debes descartar 1 carta de tu mano.","f":"\"Ojalá fueses mi hermano de verdad... y no esa monstruosidad en la que te has convertido.\" —El Segador"},
  "58028": {"n":"Tajo de guadaña","t":"Cuando se muestre esta carta: si El Segador está en juego, se activa contra ti. De no ser así, sufres 2 de Daño indirecto.","f":"\"¡Nada se interpondrá en mi camino!\" —El Segador"},
  "58029": {"n":"La muerte no puede morir","t":"Cuando se muestre esta carta: El Segador se activa contra ti. Si El Segador no está en juego, localízalo y muéstralo.\n[star] Aumento: si El Segador está en juego, se activa contra ti (después de esta activación)."},
  "58030": {"n":"Atrapado en el fuego cruzado","t":"Vincula esta carta a un Esbirro que no sea Élite. Máximo 1 por Esbirro.\nInterrupción: cuando un personaje amigo ataque, inflige 1 de Daño al Esbirro vinculado."},
  "58031": {"t":"Inicio. Máximo de 1 por mazo.\nPreparación: busca en tu colección un Aliado específico de un Superhéroe que no esté presente en la partida. Añade ese Aliado a tu mazo y barájalo. Descarta 2 cartas de tu mano y retira esta carta de la partida."},
  "58032": {"n":"Esfuerzo coordinado","t":"Vincula esta carta a una carta de Encuentro que esté en juego. Máximo 1 por carta de Encuentro.\nAl pagar los costes de la carta vinculada, cualquier jugador puede ayudar a pagarlos."},
  "58033": {"n":"Defensa y desarme","t":"Interrupción de Héroe (defensa): cuando tu Héroe defienda contra un ataque, recibe +2 DEF para ese ataque. Si no sufres Daño a consecuencia de este ataque, descarta descarta un Accesorio vinculado al enemigo atacante que contenga las expresiones \"Acción de Héroe\" o \"Respuesta de Héroe\"."},
  "58034": {"n":"Complejo de los Vengadores","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Vengador. Máximo de 1 por mazo.\nAcción: agota el Complejo de los Vengadores → elige entre meter 1 Aliado debajo de esta carta desde tu mano (si no hay ya un Aliado debajo), o bien jugar el Aliado que esté metido debajo de esta carta como si estuviera en tu mano."},
  "59001a": {"n":"Hércules","t":"Expiación — Respuesta: después de que se añada una carta de Trabajo a la zona de victoria, pon en juego la primera carta del mazo de Dones. Prepara a Hércules. Puedes adoptar la identidad de tu Alter ego. (Límite de una vez por fase.)"},
  "59001b": {"n":"Hércules","t":"Hércules empieza la partida con un mazo de Trabajos y un mazo de Dones. (ver hoja de reglas.)\nLos nuevos trabajos de Hércules — Acción: si no hay en juego ninguna carta de Trabajo, muestra la primera carta del mazo de Trabajos."},
  "59002": {"n":"Derrotar a la Hidra","t":"Victoria 0.\nEl Esbirro vinculado recibe +6 de Vida y gana el rasgo Élite. El Esbirro vinculado sólo puede sufrir Daño por los ataques de Hércules.\nCuando se muestre esta carta: localiza un Esbirro que no sea Élite tenga al menos 6 de Vida impresa. Muéstralo, cúrale todo el Daño y vincúlale esta carta."},
  "59003": {"n":"Servir de ejemplo","t":"Victoria 0.\nEl Plan secundario vinculado gana Asalto. Sólo puede quitarse Amenaza del Plan vinculado mediante intervenciones de Hércules.\nCuando se muestre esta carta: localiza un Plan secundario de Encuentro que no esté en juego y muéstralo, tratando cada [per_hero] que tenga como un 1, y vincúlale esta carta. Coloca 6 de Amenaza adicional sobre este Plan."},
  "59004": {"n":"Proteger a la Humanidad","t":"Usos (3 contadores de Trabajo). Victoria 0.\nCuando se muestre esta carta: localiza a Amadeus Cho y ponlo en juego.\nInterrupción obligada: cuando el Villano vaya a atacar a Hércules, elige 1 de tus Aliados. El Villano ataca a ese Aliado en su lugar. Después de resolver ese ataque, si Hércules ha defendido, quita 1 contador de Trabajo de esta carta."},
  "59005": {"n":"Piel del León de Nemea","t":"Permanente.\nHércules recibe +2 de Vida y gana Tesón.\nRespuesta: después de que esta carta entre en juego, roba 4 cartas."},
  "59006": {"n":"Escudo de Perseo","t":"Permanente.\nHércules recibe +1 de Vida y gana Represalia 1.\nRespuesta: después de que esta carta entre en juego, roba 4 cartas."},
  "59007": {"n":"Espada de Peleo","t":"Permanente. Restringida.\nHércules recibe +1 de Vida y sus ataques básicos ganan Penetrante.\nRespuesta: después de que esta carta entre en juego, roba 4 cartas."},
  "59008": {"t":"Interrupción obligada: cuando un Esbirro vaya a atacarte, en vez de eso ataca a Amadeus Cho.\nAcción: agota a Amadeus Cho → roba 1 carta."},
  "59009": {"n":"El don de la batalla","t":"El coste para jugar esta carta se reduce en 1 por cada carta de Don que controles.\nAcción de Héroe (ataque): inflige 5 de Daño a un enemigo.","f":"\"Como Hércules ha dicho ya en un sinfín de ocasiones: ¡defiéndete!\" —Hércules"},
  "59010": {"n":"Hijo de Zeus","t":"Acción de Héroe: Prepara a Hércules. Si controlas al menos:\n• 1 carta de Don, preprara una Mejora específica de Superhéroe que controles.\n• 2 cartas de Don, ganas una carta de Estado \"Duro\".\n• 3 cartas de Don, roba 1 carta."},
  "59011": {"n":"Sabiduría de Atenea","t":"El coste para jugar esta carta se reduce en 1 por cada carta de Don que controles.\nAcción de Héroe (intervención): quita 4 de Amenaza de un Plan.","f":"\"'¡Diantre! ¿Eres tú, hermana mia?\" —Hércules"},
  "59012": {"n":"Olimpo","t":"Recurso: agota el Olimpo → genera un recurso [wild] por cada carta de Don que controles.","f":"Aunque el influjo del Olimpo haya mermado desde el periodo helenístico, la intensidad de sus bacanales no ha decaído en lo más mínimo."},
  "59013": {"n":"Guanteletes de Hércules","t":"Interrupción de Héroe: cuando Hércules defienda contra un ataque, agota los Guanteletes de Hércules → Hércules gana Represalia 1 para ese ataque por cada carta de Don que controles."},
  "59014": {"n":"Maza dorada","t":"Restringida.\nInterrupción de Héroe: cuando Hércules realice un ataque básico, agota la Maza dorada → Hércules recibe +1 ATQ para este ataque por cada carta de Don que controles. Este ataque gana Brutalidad."},
  "59015": {"n":"Yelmo de Herc","t":"Interrupción de Héroe (defensa): cuando el Villano ataca, agota el Yelmo de Herc → reduce en 1 la cantidad de Daño que inflinja este ataque.","f":"\"Cálmate, mortal, pues el poderoso Hércules no perecerá hoy.\" —Hércules."},
  "59016": {"n":"León del Olimpo","t":"Temporal. (Descarta esta carta al final de la ronda.)\nTu Héroe recibe +1 INT, +1 ATQ, y +1 DEF.","f":"Igual que los poderosos leones nativos de la antigua Grecia, Hércules está dotado de una ferocidad increible."},
  "59017": {"n":"Príncipe del Poder","t":"Respuesta de Héroe: después de que Hércules ataque y derrote a un enemigo, agota Príncipe del Poder → cura 1 de Daño a Hércules por cada punto de Daño sobrante infligido a ese enemigo mediante ese ataque."},
  "59018": {"n":"Grito de Muerte","t":"[star] Interrupción de Héroe: cuando Grito de Muerte realice un ataque básico, inflige 1 de Daño a tu Héroe → Grito de Muerte sufre -1 de Daño derivado ([cost]) en este ataque."},
  "59019": {"t":"[star] Namora recibe +1 de Vida por cada Aliado que controles además de ella.","f":"\"Dicen que puede ganar en un pulso a la Capitana Marvel.\" —Hombre Gorila"},
  "59020": {"t":"[star] Respuesta obligada: después de que Thor realice una intervención básica, descarta cartas de la parte superior del mazo de Encuentros hasta que descartes un Esbirro. Pon en juego ese Esbirro enfrentado a ti."},
  "59021": {"n":"Trabajo en equipo","t":"Interrupción de Héroe: cuando uses tu atributo básico de Intervención (INT) o tu atributo básico de Ataque (ATQ), agota un Aliado que controles → suma el atributo correspondiente de ese Aliado al de tu Héroe para este uso."},
  "59022": {"n":"Pedir refuerzos","t":"Victoria 0.\nCuando se derrote esta carta: cada jugador puede buscar un Aliado en su mazo y su pila de descartes y ponerlo en juego. (Baraja el mazo.)","f":"\"¡Equipo azul, reagruparos en mi posición!\" — Bishop"},
  "59023": {"n":"Campaña de reclutamiento","t":"Solo identidad de Alter ego.\nAcción: descarta Campaña de reclutamiento y elige un jugador → reduce a 0 el coste en recursos del próximo Aliado que juegue ese jugador en esta fase."},
  "59024": {"n":"\"¡Vengadme!\"","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Vengador.\nVincula esta carta a un Aliado. Máximo de 1 por Aliado.\nInterrupción: cuando el Aliado vinculado sea derrotado, roba 2 cartas."},
  "59025": {"t":"Como coste adicional para jugar esta carta, si no tienes el rasgo Eterno, confunde a tu Superhéroe.","f":"Habiendo vivido alrededor de un millón de años, incluso Gilgamesh olvidó una vez quién era."},
  "59026": {"n":"Rivalidad ancestral","t":"Equipo (Hércules y Thor). Máximo de 1 por mazo.\nAcción de Héroe: busca en tu pila de descartes una Mejora específica de un Superhéroe y añádela a tu mano. Prepara a Hércules y a Thor."},
  "59027": {"n":"Aguante ilimitado","t":"Juega esta carta sólo si tu Superhéroe tiene una Vida impresa mínima de 14.\nAcción de Héroe: prepara tu Héroe.","f":"\"¿Qué pasa, te crees que la pelea se ha acabado? Eso sólo ha sido el calentamiento.\" —Thor"},
  "59028": {"n":"Evaluación de amenazas","t":"Victoria 0.\nJuega esta carta sólo si tu Superhéroe tiene el rasgo Vengador o S.H.I.E.L.D..\nCuando se derrote esta carta: cada jugador puede buscar una carta Vengador o S.H.I.E.L.D. en su mazo y su pila de descartes y añadirla a su mano. (Baraja el mazo.) El coste para jugar cada una de esas cartas se reduce en 2 hasta el final de la fase."},
  "59029": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "59030": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "59031": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "59032": {"n":"Complejo de los Vengadores","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo Vengador. Máximo de 1 por mazo.\nAcción: agota el Complejo de los Vengadores → elige entre meter 1 Aliado debajo de esta carta desde tu mano (si no hay ya un Aliado debajo), o bien jugar el Aliado que esté metido debajo de esta carta como si estuviera en tu mano."},
  "59033": {"n":"Helitransporte","t":"Máximo de 1 por jugador.\nAcción: agota el Helitransporte → elige un jugador. Reduce en 1 el coste en recursos de la siguiente carta jugada por ese jugador en esta fase.","f":"\"¿Un portaaviones volador? Estás de guasa, ¿no?\" —Jennifer Walters"},
  "59034": {"n":"Quintransporte","t":"Juega esta carta sólo si tu Superhéroe tiene el rasgo VENGADOR.\nRecurso: agota el Quintransporte → genera un recurso [wild].","f":"\"Lástima que sólo tengamos uno de esos.\" —Ojo de Halcón"},
  "59035": {"n":"Ruego a Atenea","t":"Dale esta carta al jugador que lleva a Hércules.\nCuando tengas que contar las cartas de Don que controlas, se considera que no controlas ninguna.\nAcción de Alter ego: agota a Hércules o gasta [mental] [mental] → retira esta obligación de la partida."},
  "59036": {"t":"Represalia 1.\n[star] Respuesta obligada: después de que Ares ejecute el Plan, coge 1 cart ade Encuentro boca abajo.\n(Esbirro archienemigo de Hércules.)"},
  "59037": {"n":"Hydra de Lerna","t":"Respuesta obligada: después de que un personaje que controles ataque y cause Daño a la Hydra de Lerna, elige una opción:\n• gasta un recurso [physical].\n• La Hydra de Lerna se cura 2 de Daño."},
  "59038": {"n":"Contienda olímpica","t":"Cuando se muestre esta carta: coloca 1 de Amenaza adicional sobre esta carta por cada carta Olimpo que haya en juego.","f":"Hércules ha frustado en dos ocasiones los planes orquestados por su tío Plutón y su hermanastro Ares para derrocar a los dioses del Olimpo."},
  "59039": {"n":"Hacha de Ares","t":"Vincula esta carta a Ares. De no ser posible, vincula esta carta al Villano.\n[star] Respuesta obligada: después de queel enemigo vinculado ataque, si ningún personaje amigo ha sufrido Daño a consecuencia de este ataque, descarta esta carta.","f":"Desde kukris hasta fusiles de precisión Shi'ar, Ares empuña cualquier arma con idéntica malicia."},
  "59040": {"n":"Dios de la Guerra","t":"Cuando se muestre esta carta: cada Esbirro ataca al jugador con el que esté enfrentado (incluso aunque tenga adoptada la identidad de su Alter ego). Si no se activa nigún Esbirro de este modo, descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Esbirro y muéstralo."},
  "59041": {"n":"Todos contra todos","t":"Complicación 2[per_hero].\nRespuesta obligada: después de que un personaje sea derrotado, coloca 2 de Amenaza sobre este Plan.\nCuando se derrote esta carta: aparta a un lado Todos contra todos."},
  "59042": {"n":"Hécate","t":"Cuando se muestre/derrote esta carta: localiza el Plan secundario Todos contra todos y muéstralo.\n[star] Respuesta obligada: después de que Hécate se active, coloca 2 de Amenaza sobre el Plan secundario Todos contra todos.","f":"\"Aquellos que una vez te adoraron se han vuelto contra ti.\""},
  "59043": {"n":"Cicno","t":"Represalia 1. Dureza. Victoria 0.\n[star] Respuesta obligada: después de que Cicno se active, coloca 2 de Amenaza sobre el Plan secundario Todos contra todos. De no ser así, coloca 1 de Amenaza sobre el Plan principal.","f":"\"Cicno, hijo de Ares, los castigará con la pena de muerte.\""},
  "59044": {"n":"Policía embrujado","t":"Represalia 1.\n[star] Los ataques del Policía embrujado ganan A distancia y Penetrante.","f":"\"¡eh, párate a un lado!\""},
  "59045": {"n":"Turba errante","t":"Victoria 0.\nCuando se derrote esta carta: localiza el Plan secundario Todos contra todos y muéstralo.","f":"Nadie está a salvo bajo el dogma bélico del todos contra todos."},
  "60001a": {"t":"Sentidos sobrehumanos — Acción: juega la primera carta de tu mazo de Sentido como si estuviese en tu mano (pagando su coste).\nInterrupción obligada: cuando una Mejora Sentido vaya a abandonar el juego, en vez de eso colócala en la parte inferior del mazo de Sentido."},
  "60001b": {"t":"Matt Murdock empieza la partida con un mazo de cartas de Sentido. (ver página 26 del reglamento.)\nInterrupción obligada: cuando una Mejora Sentido vaya a abandonar el juego, en vez de eso colócala en la parte inferior del mazo de Sentido."},
  "60002": {"n":"Tacto hipersensible","t":"Vincula esta carta a un enemigo o Plan.\nInterrupción: cuando derrotes al enemigo vinculado o quites la última ficha de Amenaza del Plan vinculado, descarta esta carta → prepara tu carta de Superhéroe."},
  "60003": {"n":"Olfato mejorado","t":"Vincula esta carta a un enemigo o Plan.\nInterrupción: cuando derrotes al enemigo vinculado o quites la última ficha de Amenaza del Plan vinculado, descarta esta carta → reduce en 2 el coste de la próxima carta que juegues en esta fase."},
  "60004": {"n":"Oido superdesarrollado","t":"Vincula esta carta a un enemigo.\nInterrupción de Héroe (defensa): cuando el enemigo vinculado ataque, descarta esta carta → ese enemigo recibe -3 ATQ para ese ataque. (Tú te conviertes en el objetivo de ese ataque.)"},
  "60005": {"n":"Sentido radar","t":"Vincula esta carta a un enemigo.\nRespuesta (ataque): después de que ataques al enemigo vinculado, descarta esta carta → inflige 3 de Daño a ese enemigo.","f":"El accidente que privó de la vista a Matt también le otorgó un nuevo sentido similar a la ecolocalización."},
  "60006": {"n":"Gusto superior","t":"Vincula esta carta a un Plan.\nRespuesta (intervención): después de que intervengas en el Plan vinculado, descarta esta carta → quita 2 de Amenaza de ese Plan."},
  "60007": {"t":"[star] Interrupción obligada (Héroe): cuando Elektra vaya a sufrir Daño derivado, en vez de ese Daredevil sufre ese Daño.","f":"\"No necesito que me protejas, Matt.\""},
  "60008": {"n":"Interrogatorio agresivo","t":"Acción de Héroe (ataque): inflige 3 de Daño a un enemigo. Por cada Mejora que tenga vinculada ese enemigo, puedes infligirle 1 de Daño adicional.","f":"\"No hay más preguntas, escoria.\" —Daredevil"},
  "60009": {"n":"Declaración","t":"Acción de Alter ego (intervención): puedes elegir cualquier Mejora del mazo de Sentido y jugarla ignorando su coste en recursos. (no barajes el mazo.) Quita 2 de Amenaza de un Plan.","f":"\"Cuéntanoslo todo.\" —Matt Murdock"},
  "60010": {"n":"Detector de mentiras humano","t":"Acción (intervención): quita 2 de Amenaza de un Plan. Por cada Mejora que tenga vinculada a ese Plan, puedes quitarle 1 de Amenaza adicional.","f":"Bum-Bum Bum-Bum Bum-Bum Bum-Bum Bum-Bum Bum-Bum"},
  "60011": {"n":"Palos de ciego","t":"Acción de Héroe (ataque): inflige 2 de Daño a cada enemigo por cada Mejora que tenga vinculada dicho enemigo (3 de Daño si Daredevil tiene el rasgo Aéreo).","f":"\"No veo la luz. Así que debo de ser la luz. Soy Daredevil, y no tengo miedo.\" —Daredevil"},
  "60012": {"n":"Agudizar los sentidos","t":"Daredevil y Matt Murdock son los únicos que pueden quitar Amenaza de este Plan.\nCuando se derrote esta carta: puedes trasladar cualquier número de Mejoras Sentido que estén en juego a otras cartas a las que puedan vincularse. Elige cualquier cantidad de Mejoras del mazo de Sentido y ponlas en juego. (No barajes el mazo.)"},
  "60013": {"t":"Acción de Alter ego: agota a Foggy Nelson → quita 2 de Amenaza de un Plan.","f":"\"¡Pierde cuidado, Matt! ¡El viejo Fog se encargará del asunto!\""},
  "60014": {"t":"Acción: agota a Karen Page → devuelve a tu mazo 1 carta de Daredevil que esté en tu pila de descartes y barájalo. Si tienes adoptada la identidad de tu Alter ego, roba 1 carta.","f":"\"¿Qué haríais sin mí?\""},
  "60015": {"n":"Nelson y Murdock","t":"Respuesta: después de que un personaje o Apoyo Abogado derrote un Plan secundario, confunde a un enemigo.","f":"\"A ver cómo comenten el robo con el vehículo incautado.\" —Matt Murdock"},
  "60016": {"n":"Hermana Maggie","t":"Matt Murdock recibe +3 REC.\nRespuesta: después de que te recuperes, descarta una carta de Estado de tu Superhéroe.","f":"Sor Maggie, monja católica y madre de Matt, trata con frecuencia las heridas de su hijo."},
  "60017": {"n":"Porra de Daredevil","t":"Restringida. Daredevil recibe +1 ATQ.\nAcción de Héroe: devuelve esta carta a tu mano (estando en juego) → elige una opción:\n• Inflige 1 de Daño a un enemigo.\n• Daredevil gana el rasgo Aéreo hasta el final de la ronda."},
  "60018": {"n":"El hombre sin miedo","t":"Acción de Héroe: agota esta carta e inflige 1 de Daño a Daredevil → elige una opción:\n• Elige cualquier Mejora del mazo de Sentido y juégala ignorando su coste en recursos. (No barajes el mazo.)\n• Prepara a Daredevil."},
  "60019": {"n":"Punto Ciego","t":"[star] Respuesta: después de que Punto Ciego intervenga, confunde a un enemigo que tenga vinculada una Mejora.","f":"\"Soy invisible, pero sigo aquí. Chinatown es donde vivo. Voy a luchar por protegerlo.\""},
  "60020": {"n":"Capa","t":"Acción: agota a Capa y gasta recursos [energy] [energy] → localiza a Puñal y ponla en juego."},
  "60021": {"n":"Puñal","t":"Capa pierde todos sus iconos [acceleration].\n[star] Si Capa está en juego, Puñal sufre -1 de Daño derivado después de usar un atributo básico.","f":"\"Yo seré la luz en tu oscuridad, Ty.\""},
  "60022": {"n":"Motorista Fantasma","t":"[star] Interrupción: cuando el Motorista Fantasma ataque a un enemigo, gasta un recurso [energy] ([energy] [energy] si ese enemigo es el Villano) → confunde a ese enemigo.","f":"\"¡Mi mirada de la penitencia te revelará todos los pecados de tu pasado!\""},
  "60023": {"n":"Conoce a tu enemigo","t":"[star] Descuento 1 (Artista marcial).\nAcción de Héroe (intervención): quita 1 de Amenaza de un Plan. Quita 1 de Amenaza de un Plan.","f":"\"No necesito verte para saber cuál será tu próximo movimiento.\" —Puño de Hierro"},
  "60024": {"n":"Reducir tensiones","t":"Victoria 0.\nCuando se derrote esta carta: retira del juego 1 ficha de Aceleración.","f":"\"¡Desde aquí se ve mi casa!\" —Civil"},
  "60025": {"n":"Encuentro fortuito","t":"Vincula esta carta a un Plan secundario. Máximo de 1 por Plan.\nInterrupción: cuando se derrote el Plan secundario vinculado, busca un Aliado en tu mazo y en tu pila de descartes y añádelo a tu mano. Baraja tu mazo."},
  "60026": {"n":"Problemas con la ley","t":"[star] Descuento 1 (Abogado o Policía).\nVincula esta carta a un Esbirro. Máximo de 1 por Esbirro.\nEl Esbirro vinculado recibe recibe -2 PLA.","f":"\"¿Tiene licencia para eso?\" —Agente de policía"},
  "60027": {"n":"Sombra furtiva","t":"[star] Descuento 1 (Artista marcial o Espía).\nTemporal. Máximo de 1 por jugador.\nRespuesta (intervención): después de que juegues una carta (incluida ésta), quita 1 de Amenaza de un Plan."},
  "60028": {"n":"Entrenamiento en sigilo","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nRespuesta: después de que intervengas y derrotes un Plan secundario sin pasarte, agota Entrenamiento en sigilo → aturde a un enemigo."},
  "60029": {"t":"Interrupción: cuando un personaje Artista marcial amigo use un atributo básico, elige una opción:\n• Agota a Stick → ese personaje recibe +1 en ese atributo básico para este uso.\n• Ese personaje recibe -1 en ese atributo básico para este uso. Prepara a Stick."},
  "60030": {"n":"Plan de respuesta","t":"Máximo de 1 por jugador.\nPuedes jugar la Mejora que esté metida aquí debajo como si estubiera en tu mano.\nAcción: elige 1 Mejora de tu mano que pueda vincularse a un Esbirro o Plan secundario. Mete esa Mejora debajo de esta carta (hasta un máximo de 1)."},
  "60031": {"n":"Bailar con el diablo","t":"Equipo (Daredevil y Elektra). Máximo de 1 por mazo.\nVincula esta carta a un enemigo.\nAcción de Héroe (ataque): descarta esta carta → inflige 3 de Daño al enemigo vinculado."},
  "60032": {"n":"Sobrecarga sensorial","t":"Dale esta carta al jugador que lleva a Matt Murdock.\nRespuesta obligada: después de que entre en juego una Mejora Sentido, sufres 1 de Daño.\nRespuesta de Alter ego: después de que te recuperes, descarta esta carta.","f":"Los sentidos potenciados de Daredevil lo hacen vulnerable a los estímulos intensos."},
  "60033": {"t":"Cuando se muestre esta carta: elige una opción:\n• Descarta un Apoyo Individuo que controles.\n• Bullseye te ataca (aunque tengas adoptada la identidad de tu Alter ego).","f":"\"¡Cualquier cosa es un arma mortal en mis manos!\""},
  "60034": {"n":"El hombre más letal del mundo","t":"Interrupción obligada: cuando Bullseye ataque, dale una carta de aumento boca abajo.","f":"\"¡Venga, cuernecitos, vamos a darle un espectáculo a esta gente!\" —Bullseye"},
  "60035": {"n":"Sai robado","t":"Vincula esta carta al enemigo que tenga la puntuación más alta de ATQ.\n[star] Los ataques del personaje vinculado ganan Penetrante.\nAcción de Héroe: gasta recursos [physical] [physical] → elige entre vincular esta carta a Elektra o bien descartar esta carta.\n[star] Aumento: si esta activación es un ataque, it gana Penetrante."},
  "60036": {"n":"Blanco a la vista","t":"Cuando se muestre esta carta: elige una opción:\n• Retira de la partida un Aliado o Apoyo Individuo que controles.\n• Bullseye te ataca (aunque tengas adoptada la identidad de tu Alter ego). Si no está en juego, localízalo y muéstralo.","f":"\"¡Pilla!\" —Bullseye"},
  "60037a": {"n":"Eco","t":"Mira y aprende — Respuesta: después de que un jugador juegue una carta de Evento Básica o de Aspecto, mete ese Evento debajo de esta carta desde la pila de descartes de ese jugador. Luego, si hay más de tres cartas metidas debajo de ésta, descártalas todas menos 3."},
  "60037b": {"t":"La práctica hace a la maestra — Interrupción: cuando adoptes tu identidad de Héroe, busca en tu mazo una carta de Evento Básica o de Aspecto y añádela a tu mano. (Baraja el mazo.)","f":"Maya puede imitar cualquier movimiento físico que haya visto."},
  "60038": {"n":"Reflejos innatos","t":"Mano inicial. (Puedes añadir esta carta a tu mano antes de robar tu mano inicial.)\nTu Héroe recibe +1 DEF."},
  "60039": {"t":"[star] Respuesta: después de que Daredevil use un atributo básico, reduce en 1 el coste del próximo Evento que juegues esta ronda.","f":"\"Haz lo que yo.\""},
  "60040a": {"n":"Reflejos fotográficos","t":"[star] Si tienes adoptada tu identidad de Héroe, puedes descartar Reflejos fotográficos desde tu mano para jugar un Evento que esté metido debajo de Eco como si estuviera en tu mano. El coste para jugar ese Evento se reduce en 2. No puedes aplicar la capacidad \"Mira y aprende\" de Eco en ese Evento."},
  "60040b": {"n":"Reflejos fotográficos","t":"[star] Si tienes adoptada tu identidad de Héroe, puedes descartar Reflejos fotográficos desde tu mano para jugar un Evento que esté metido debajo de Eco como si estuviera en tu mano. El coste para jugar ese Evento se reduce en 2. No puedes aplicar la capacidad \"Mira y aprende\" de Eco en ese Evento."},
  "60040c": {"n":"Reflejos fotográficos","t":"[star] Si tienes adoptada tu identidad de Héroe, puedes descartar Reflejos fotográficos desde tu mano para jugar un Evento que esté metido debajo de Eco como si estuviera en tu mano. El coste para jugar ese Evento se reduce en 2. No puedes aplicar la capacidad \"Mira y aprende\" de Eco en ese Evento."},
  "60041": {"n":"Estudiar la cinta","t":"Acción: busca 1 carta de Evento de Apecto, 1 carta de Evento Básica o 1 copia de Reflejos fotográficos en la pila de descartes de cualquier jugador y añade esa carta a tu mano.","f":"\"Veo cinta tras cinta antes de entrenarme para la lucha.\" —Eco"},
  "60042": {"n":"La Res","t":"Acción de Alter ego: agota La Res → cura X de Daño a Maya Lopez, siendo X el coste más alto de entre todas las cartas que tiene metidas debajo.","f":"La Res no es una verdadera reserva ni tampoco una nación de nativos americanos, sino un punto de encuentro para todas las tribus."},
  "60043": {"n":"Lengua de signos","t":"Recurso de Héroe: agota esta carta → genera un recurso [wild] para un Evento que esté jugando cualquier jugador.","f":"* —Eco\n*Traducido de la lengua de signos."},
  "60044": {"n":"Coreografía","t":"Acción: agota esta carta → devuelve a tu mazo 1 carta de Evento Básica o de Aspecto que esté en tu pila de descartes y barájalo. Si tienes adoptada la identidad de tu Alter ego, roba 1 carta.","f":"Maya emplea sus aptitudes físicaspara expresarse mediante la danza."},
  "60045": {"n":"Katana de Eco","t":"Restringida.\nRespuesta de Héroe (ataque): después de que juegues un Evento, agota Katana de Eco → inflige tanto Daño a un enemigo como el coste impreso de ese Evento. Este ataque gana Penetrante."},
  "60046": {"n":"Improvisación","t":"Respuesta de Héroe: después de que juegues un Evento, si tiene los siguientes rasgos:\n• Ataque — cura 1 de Daño a Eco.\n• Defensa — quita 1 de Amenaza de un Plan.\n• Intervención — inflige 1 de Daño a un enemigo."},
  "60047": {"n":"Memoria muscular","t":"Acción de Héroe: agota esta carta → añade a tu mano un Evento que esté metido debajo de Eco.","f":"\"I absorb an arsenal of actions, so when I need to, I can perform them with the same precision.\" —Eco"},
  "60048": {"n":"Ejercito de una sola persona","t":"[star] El coste para jugar esta carta aumenta en 1 por cada Aliado que controles.\nAcción de Héroe: prepara a tu Héroe.","f":"\"Dos contra uno no es una pelea justa...para vosotros.\" —Daredevil"},
  "60049": {"n":"Captar su atención","t":"Interrupción de Héroe (defensa/intervención): cuando un enemigo inicie un ataque, quita 3 de Amenaza de un Plan.","f":"\"Me parece que los hemos cabreado.\"\n\"¿Cómo que 'hemos'?\"\n—Mapache Cohete y Gamora"},
  "60050": {"n":"Vidas en peligro","t":"[star] El coste para jugar esta carta aumenta en 1 por cada Aliado que controles.\nAcción de Héroe (ataque/intervención): inflige X de Daño a un enemigo y quita X de Amenaza de un Plan, siendo X igual a tu DEF."},
  "60051": {"n":"Puñetazo potente","t":"Interrupción de Héroe (ataque/defensa): cuando un enemigo inicie un ataque, inflige 4 de Daño a ese enemigo.","f":"\"¿Te apetece un poco de jarabe de palo?\" —Gatasombra"},
  "60052": {"n":"El mejor ataque...","t":"Temporal.\nTu Héroe recibe +1 DEF.\nUsa tu puntuación de DEF en vez de tus puntuaciones de INT y ATQ. (Ignora todos los modificadores a tu INT y ATQ.)"},
  "60053": {"t":"Mientras no controles a ningún Aliado, tu Héroe recibe +1 DEF y gana Represalia 1.","f":"\"Soy Ronin, un samurái sin amo.\" —Ronin"},
  "60054": {"n":"Solo ante el peligro","t":"Máximo de 1 por jugador.\nInterrupción de Héroe: cuando un enemigo te ataque (antes de que se declare ningún defensor), si no controlas ningún Aliado, agota Solo ante el peligro → prepara tu Héroe."},
  "60055": {"n":"En la oscuridad y el silencio","t":"Equipo (Daredevil y Eco). Máximo de 1 por mazo.\nAcción de Héroe (ataque/intervención): elige dos de las siguientes opciones (puedes elegir la misma dos veces):\n• Inflige 3 de Daño a un enemigo.\n• Quita 3 de Amenaza de un Plan."},
  "60056": {"n":"Entrenamiento de superpoderes","t":"Victoria 0.\nCuando se derrote esta carta: cada jugador puede buscar en su mazo y en su pila de descartes una Mejora específica de su Superhéroe y ponerla en juego (Baraja el mazo.)","f":"\"La clase ha empezado.\" — Charles Xavier"},
  "60057": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "60058": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "60059": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "60060": {"n":"Criada por Kingpin","t":"Dale esta carta al jugador que lleva a Maya Lopez.\nNo puedes infligir Daño a Kingpin.\nCuando se muestre esta carta: localiza a Kingpin y ponlo en juego enfrentado a ti.\nRespuesta: después de que intervengas, coloca esa Amenaza sobre esta carta. Si hay al menos 4 de Amenaza aquí, retira esta carta de la partida."},
  "60061": {"t":"[star] Interrupción obligada: cuando Kingpin vaya a atacar al jugador que lleva a Maya Lopez, en vez de eso ejecuta el Plan.\n(Esbirro Archienemigo de Eco.)","f":"\"A mi manera, llegué a apreciarte, Maya. Te quise como a una hija. Aún te quiero.\""},
  "60062": {"n":"Maestro de la manipulación","t":"Kingpin no puede sufrir Daño.\nCuando se muestre esta carta: localiza a Kingpin y ponlo en juego enfrentado a ti.\n[star] Aumento: Si Kingpin está en juego, muestra este Plan.","f":"\"Si me pones un dedo encima, lo lamentarás.\" —Kingpin"},
  "60063": {"n":"Matón de Kingpin","t":"Guardia.\nKingpin no puede sufrir Daño.","f":"\"El señor Fisk quiere hablar con vosotros.\""},
  "60064": {"n":"Peón de Kingpin","t":"Cuando se muestre esta carta (Alter ego): si Kingpin está en juego, ejecuta el Plan. De no ser así, esta carta gana Oleada.\nCuando se muestre esta carta (Héroe): inflige tanto Daño a un Héroe como el ATQ de tu Héroe.","f":"Kingpin convenció a Eco de que fue Daredevil, y no él, quien asesinó a su padre."},
  "60065": {"n":"Bullseye","t":"Cuando se muestre esta carta: aparta a un lado la Columna vertebral de adamántium (68A).\n[star] Interrupción obligada: cuando Bullseye se active, todas sus cartas de aumento ganan [boost]. Si esta activación es un ataque, gana A distancia."},
  "60066": {"n":"Bullseye","t":"Cuando se muestre esta carta: localiza la Columna vertebral de adamántium y vincúlala a Bullseye.\n[star] Interrupción obligada: cuando Bullseye se active, todas sus cartas de aumento ganan [boost]. Si esta activación es un ataque, gana A distancia."},
  "60067": {"n":"Bullseye","t":"Cuando se muestre esta carta: localiza Psicópata sanguinario y muéstralo.\n[star] Interrupción obligada: cuando Bullseye se active, todas sus cartas de aumento ganan [boost]. Si esta activación es un ataque, gana A distancia."},
  "60068a": {"n":"Columna vertebral de adamántium","t":"Permanente.\nInterrupción obligada: cuando Bullseye vaya a sufrir Daño, evita todo ese Daño menos 3. Coloca el Daño evitado sobre esta carta. Luego, si hay al menos 6 de Daño sobre esta carta, dale la vuelta."},
  "60068b": {"n":"Columna vertebral dañada","t":"Permanente.\n[star] Respuesta obligada: después de que Bullseye ejecute el Plan, quita 3 de Daño de esta carta. Luego, si no hay ninguna ficha de Daño sobre esta carta, dale la vuelta."},
  "60069": {"n":"Subir la apuesta","t":"Vincula esta carta a Bullseye.\n[star] Interrupción obligada: cuando Bullseye ataque, dale 1 carta de aumento adicional para este ataque. Si este atque derrota a un personaje amigo, tanto ese personaje como esta carta se retiran de la partida. De no ser posible, devuelve esta carta al mazo de Encuentros y barájalo."},
  "60070": {"n":"Sai mortífero","t":"Vincula esta carta a Bullseye.\n[star] Los ataques de Bullseye pierden A distancia y ganan Penetrante.\nRespuesta de Héroe: después de que tu Héroe defienda contra un ataque de Bullseye, gasta 2 recursos distintos → descarta esta carta."},
  "60071": {"n":"Persecución incesante","t":"Vincula esta carta a un Aliado que no tenga vinculada Persecución incesante. De no ser posible, esta carta gana Oleada.\nInterrupción obligada: cuando el Villano vaya a atacarte, en vez de eso ataca al Aliado vinculado y su ataque gana Brutalidad. Si este ataque derrota al Aliado vinculado, retíralo de la partida."},
  "60072": {"n":"Lady Bullseye","t":"Infame. (Cuando este Esbirro se active, dale una carta de aumento.)\n[star] Interrupción obligada: cuando se estén resolviendo las cartas de aumento durante el ataque de Lady Bullseye, si se trata de un ataque no defendido, dale a Lady Bullseye 1 carta de aumento adicional para este ataque."},
  "60073": {"n":"Psicópata sanguinario","t":"Cuando se muestre esta carta: coloca tanta Amenaza adicional sobre esta carta como el número de la etapa de Bullseye.\n[star] Aumento: después de esta activación, muestra esta carta."},
  "60074": {"n":"Todo es un Arma","t":"Cuando se muestre esta carta (Alter ego): sufres 2 de Daño indirecto.\nCuando se muestre esta carta (Héroe): elige: Bullseye se activa contra ti o bien retiras de la partida un Aliado que controles.\n[star] Aumento: si Bullseye está atacando, dale una carta de aumento adicional y este ataque gana Penetrante."},
  "60075": {"n":"Deseo infalible","t":"Cuando se muestre esta carta: elige entre darle esta carta al Villano como carta de aumento boca abajo, o bien retirar de la partida un Apoyo Individuo que controles.\n[star] Aumento: si esta activación es un ataque, gana Brutalidad."},
  "60076": {"n":"Electro","t":"Cuando se muestre esta carta: localiza Carga eléctrica, vincúlala a Electro y colócale encima 2[per_hero] contadores de Carga.\n[star] Respuesta obligada: después de que Electro ejecute el Plan, coloca 1 contador de Carga sobre Carga eléctrica."},
  "60077": {"n":"Electro","t":"Cuando se muestre esta carta: localiza Carga eléctrica, vincúlala a Electro y colócale encima 2[per_hero] contadores de Carga.\n[star] Respuesta obligada: después de que Electro ejecute el Plan, coloca 1 contador de Carga sobre Carga eléctrica."},
  "60078": {"n":"Electro","t":"Cuando se muestre esta carta: coloca 3[per_hero] contadores de Carga sobre Carga eléctrica.\n[star] Respuesta obligada: después de que Electro ejecute el Plan, coloca 2 contadores de Carga sobre Carga eléctrica."},
  "60079": {"n":"Carga eléctrica","t":"Permanente.\n[star] Interrupción obligada: cuando Electro ataque, quita 1 contador de Carga de esta carta → dale a Electro una carta de aumento adicional para este ataque. Este ataque gana Brutalidad.\nAcción de Héroe: gasta un recurso [energy] o bien 2 recursos de cualquier tipo → quita 1 contador de Carga de esta carta."},
  "60080": {"n":"Energía robada","t":"Usos (3 contadores de Drenaje).\nCuando se muestre esta carta: Vincula esta carta a tu Superhéroe y agota todas las Mejoras que controles.\nInterrupción obligada: cuando vaya a prepararse una Mejora que controles, puedes gastar un recurso [energy] o bien 2 recursos de cualquier tipo. Si lo haces, quita 1 contador de Drenaje de esta carta (y prepara esa Mejora). De no ser así, esa Mejora no se prepara."},
  "60081": {"n":"Latigazo","t":"Interrupción obligada: cuando Latigazo sea atacado, quita 1 contador de Carga de Carga eléctrica → descarta la primera carta del mazo de Encuentros. Inflige 1 de Daño al atacante por cada icono de Aumento ([boost]) que hubiera en la carta descartada.","f":"\"¿Te ha dado un calambre al verme?\""},
  "60082": {"n":"Acumulación de energía","t":"Cuando se derrote esta carta: coloca 3 contadores de Carga sobre Carga eléctrica.","f":"Electro está absorbíendo energía de la red eléctrica.¡Tenéis que cortarle el suministro!"},
  "60083": {"n":"Electrocución en cadena","t":"Cuando se muestre esta carta: por cada personaje que controles, elige una opción:\n• Agota ese personaje.\n• inflige 1 de Daño a ese personaje (3 de Daño si Carga eléctrica tiene contadores de Carga). Quita 1 contador de Carga de Carga eléctrica."},
  "60084": {"n":"Sobrecarga de energía","t":"Cuando se muestre esta carta: si no tienes en la mano ninguna carta con un recurso [energy] impreso, esta carta gana Oleada. De no ser así, por cada carta con un recurso [energy] impreso que tengas en la mano, elige una opción:\n• Descarta esa carta.\n• Aturde un personaje que controles."},
  "60085": {"n":"Revelación electrizante","t":"Cuando se muestre esta carta: descarta la primera carta de tu mazo por cada carta que controles. POr cada carta con un recurso [energy] impreso que se haya descartado de este modo, elige una opción:\n• Sufres 1 de Daño indirecto.\n• Coloca 1 contador de Carga sobre Carga eléctrica."},
  "60086": {"n":"Cabeza de Martillo","t":"[star] Respuesta obligada: después de que Cabeza de Martillo ataque e inflija Daño a un personaje, aturde a ese personaje. Si ese personaje ya estaba aturdido, inflígele 1 de Daño.","f":"\"¡Qué cabeza más dura!\" —Luke Cage"},
  "60087": {"n":"Cabeza de Martillo","t":"Dureza. Represalia 1.\n[star] Respuesta obligada: después de que Cabeza de Martillo ataque e inflija Daño a un personaje, aturde a ese personaje. Si ese personaje ya estaba aturdido, inflígele 1 de Daño.","f":"\"¡Qué cabeza más dura!\" —Luke Cage"},
  "60088": {"n":"Cabeza de Martillo","t":"Dureza. Represalia 2.\n[star] Respuesta obligada: después de que Cabeza de Martillo ataque e inflija Daño a un personaje, aturde a ese personaje. Si ese personaje ya estaba aturdido, inflígele 2 de Daño.","f":"\"¡Qué cabeza más dura!\" —Luke Cage"},
  "60089": {"n":"Metralleta de energía","t":"Vincula esta carta a Cabeza de Martillo.\nRespuesta obligada: después de que Cabeza de Martillo ataque, si el personaje atacado no ha sido derrotado, descarta esta carta → Cabeza de Martillo ataca otra vez a ese personaje.","f":"\"Fijad las armas en aturdir, que quiero interrogarlos luego.\" —Cabeza de Martillo"},
  "60090": {"n":"Duro de mollera","t":"Vincula esta carta a Cabeza de Martillo.\nCabeza de Martillo gana Firmeza.\nAcción de Héroe: gasta recursos [energy] [mental] [physical] → descarta esta carta.\n[star] Aumento: dale al enemigo activado una carta de Estado \"Duro\"."},
  "60091": {"n":"Camaleón","t":"[star] El Camaleón recibe +X PLA, siendo X la puntuación más alta de INT de entre todos los personajes que estén en juego.\nCuando se muestre esta carta: El Camaleón ejecuta el Plan.","f":"\"Soy invisible porque soy lo mismo que miras cada aburrido y horrible día.\""},
  "60092": {"n":"Sicarios de la Maggia","t":"Guardia.\n[star] El valor de PLA de los Sicarios de la Maggia es igual al número de enemigos Maggia que haya en juego (incluido éste).","f":"\"Antes de tener mi propia banda era un matón de la Maggia.\" —Cabeza de Martillo"},
  "60093": {"n":"Lugarteniente de la Maggia","t":"Infame.\n[star] Interrupción obligada: cuando el Lugarteniente de la Maggia se active contra ti, si estás aturdido, dale una carta de aumento adicional para esta activación.","f":"\"Donde otros ven debilidad, yo veo oportunidades.\""},
  "60094": {"n":"Consolidación de poder","t":"Respuesta obligada: después de que un Esbirro sea derrotado, dáselo al Villano como carta de aumento boca abajo.","f":"\"Bienvenidos a la primera división.\" —Cabeza de Martillo"},
  "60095": {"n":"Lucha por el poder","t":"Cuando se muestre esta carta: derrota al Esbirro que tenga menos Vida restante de entre tods los que están en juego. Descarta cartas del mazo de Encuentros hasta que descartes un Esbirro. Muestra ese Esbirro."},
  "60096": {"n":"\"¡Lanzándome de cabeza!\"","t":"Cuando se muestre esta carta (Alter ego): esta carta gana Oleada.\nCuando se muestre esta carta (Héroe): Cabeza de Martillo te ataca. Si estás aturdido, Cabeza de Martillo recibe +2 ATQ para este ataque y además este ataque gana Brutalidad.","f":"\"¿Sabes cómo llegué a la cumbre?\" —Cabeza de Martillo"},
  "60097": {"n":"Hombre Púrpura","t":"Todo Esbirro Sometido gana Guardia.\nTodas las cartas de aumento del conjunto de Encuentros del Hombre Púrpura ganan: \"[star] Aumento: después de esta activación, quédate esta carta como carta de Encuentro boca abajo.\""},
  "60098": {"n":"Hombre Púrpura","t":"Todo Esbirro Sometido gana Guardia e Infame.\nTodas las cartas de aumento del conjunto de Encuentros del Hombre Púrpura ganan: \"[star] Aumento: después de esta activación, quédate esta carta como carta de Encuentro boca abajo.\""},
  "60099": {"n":"Hombre Púrpura","t":"Todo Esbirro Sometido gana Guardia, Patrulla e Infame.\nTodas las cartas de aumento del conjunto de Encuentros del Hombre Púrpura ganan: \"[star] Aumento: después de esta activación, quédate esta carta como carta de Encuentro boca abajo.\""},
  "60100": {"n":"Conversión","t":"El Aliado vinculado se trata como si fuera un Esbirro Sometido con el texto de reglas en blanco. El valor de PLA del Esbirro vinculado es igual a su INT y no sufre Daño derivado.\nCuando se muestre esta carta: vincula esta carta al Aliado de mayor coste que controles y enfréntate a él. De no ser posible, esta carta gana Oleada."},
  "60101": {"n":"Bombero","t":"Vulnerable. (Descarta este personaje si está aturdido o confundido.)\n[star] Los ataques del Bombero ganan Penetrante.\nCuando se derrote esta carta: descarta del juego el Apoyo o Mejora de mayor coste."},
  "60102": {"n":"Juez","t":"Vulnerable. (Descarta este personaje si está aturdido o confundido.)\nCuando se derrote esta carta: coloca 3 de Amenaza sobre el Plan principal.","f":"\"¡Como diga una sola palabra más sobre el señor Killgrave, le acusaré de desacato!\""},
  "60103": {"n":"Guardia de seguridad","t":"Patrulla. Vulnerable. (Descarta este personaje si está aturdido o confundido.)\nCuando se derrote esta carta: Ddescarta el Aliado que este en juego y tenga la puntuación más alta de ATQ (de entre todos los Aliados).","f":"\"Hemos detenido al sospechoso.\""},
  "60104": {"n":"Joven inconformista","t":"Vulnerable. (Descarta este personaje si está aturdido o confundido.)\nCuando se derrote esta carta: inflige 3 de Daño al Superhéroe del jugador que la ha derrotado.","f":"\"A mí lo que me va es el post-punk.\""},
  "60105": {"n":"\"Luchad.\"","t":"Usos (3 contadores de Mando).\nAcción obligada: agota esta carta y quítale 1 contador de Mando → inflige 2 de Daño a un Héroe o Aliado.","f":"\"¿No son el amor y el odio dos caras de la misma moneda?\" —Hombre Púrpura"},
  "60106": {"n":"\"Protégeme.\"","t":"Usos (3 contadores de Mando).\nAcción obligada: agota esta carta y quítale 1 contador de Mando → dale al Villano una carta de Estado \"Duro\".","f":"\"Tienes que acompañarme...a todas partes.\" —Hombre Púrpura"},
  "60107": {"n":"\"Sírveme.\"","t":"Usos (3 contadores de Mando).\nAcción obligada: agota esta carta y quítale 1 contador de Mando → coloca 2 de Amenaza sobre el Plan principal.","f":"\"Despeja tu agenda. Ahora yo soy tu principal prioridad.\" —Hombre Púrpura"},
  "60108": {"n":"El poder de la sugestión","t":"[star] Complicación 3[per_hero].\nTodos los Esbirros ganan el rasgo Sometido.","f":"\"Siente cómo mi voluntad se impone a la tuya.\" —Hombre Púrpura"},
  "60109": {"n":"Instigar a las masas","t":"Cuando se muestre esta carta: elige un Esbirro Sometido de la pila de descartes del mazo de Encuentros y muéstralo. De no ser así, esta carta gana Oleada.","f":"No hay nada más peligroso que un hombre persuasivo con un altavoz."},
  "60110a": {"n":"María Tifoidea","t":"Interrupción obligada: cuando María Tifoidea vaya a ser derrotada, en vez de eso coloca 1 ficha de Daño sobre Mente perturbada y restablece su Vida a 10[per_hero].","f":"\"Es hora de que cuente mi historia. Mi vida. tal y como yo quiera contarla.\""},
  "60110b": {"n":"Bloody Mary","t":"Interrupción obligada: cuando Bloody Mary vaya a ser derrotada, en vez de eso coloca 1 ficha de Daño sobre Mente perturbada y restablece su Vida a 10[per_hero].","f":"\"No permitiré que nadie vuelva a hacernos daño.\""},
  "60111a": {"n":"María Tifoidea","t":"Dureza.\nInterrupción obligada: cuando María Tifoidea vaya a ser derrotada, en vez de eso coloca 1 ficha de Daño sobre Mente perturbada y restablece su Vida a 13[per_hero].","f":"\"Es hora de que cuente mi historia. Mi vida. tal y como yo quiera contarla.\""},
  "60111b": {"n":"Bloody Mary","t":"Cuando se muestre esta carta: inflige 1 de Daño a cada Superhéroe.\nInterrupción obligada: cuando Bloody Mary vaya a ser derrotada, en vez de eso coloca 1 ficha de Daño sobre Mente perturbada y restablece su Vida a 13[per_hero].","f":"\"No permitiré que nadie vuelva a hacernos daño.\""},
  "60112": {"n":"Mente perturbada","t":"Inicio.\nPreparación: pon en juego al Villano con una cara aleatoria boca arriba (y muéstralo).\nInterrupción obligada: cuando termine la fase del Villano, dale la vuelta a su carta.\nSi hay al menos 3 fichas sobre esta carta, los jugadores ganan la partida!"},
  "60113a": {"n":"Ganarse su confianza","t":"Permanente. Inicio.\n[star] En modo Experto, esta carta gana Complicación 3[per_hero].\nCuando se derrote esta carta: coloca 1 ficha de Amenaza sobre Mente perturbada. Dale la vuelta a esta carta.","f":"\"Mary, soy yo. No quiero pelear contigo.\" —Matt Murdock"},
  "60113b": {"n":"Mary Walker","t":"Vincula esta carta al Villano. Permanente.\n[star] El Villano vinculado no puede activarse.\nRespuesta obligada: después de que el Villano sufra Daño o termine la ronda, dale a cada jugador 1 carta de Encuentro boca abajo y dale la vuelta a esta carta.","f":"\"Una de nosotras es tierna, otra no lo es, y la otra busca venganza.\""},
  "60114": {"n":"Telequinesia","t":"Vincula esta carta al Villano.\nAcción de Héroe: gasta recursos [mental] [mental] → descarta esta carta.\n[star] Aumento: si se está activando a María Tifoidea, sufres 3 de Daño indirecto. Agota a todos los personajes que resulten dañados de este modo."},
  "60115": {"n":"Tajo Psiónico","t":"Cuando se muestre esta carta: si Mary Walker está en juego como Accesorio, dale la vuelta y muestra Ganarse su confianza. El Villano ejecuta el Plan.\n[star] Aumento: si se está activando María Tifoidea, inflige 3 de Daño a un Aliado que controles."},
  "60116": {"n":"Nova psiónica","t":"Cuando se muestre esta carta: inflige 1 de Daño a cada personaje que controles. Quedas aturdido.\n[star] Aumento: si se está activando María Tifoidea, quedas aturdido.","f":"\"¡BASTA YA!\" —María Tifoidea"},
  "60117": {"n":"Armadura ensamblada","t":"Vincula esta carta al Villano.\nInterrupción obligada: cuando el Villano vaya a sufrir cualquier cantidad de Daño, en vez de eso coloca ese Daño sobre esta carta. Luego, si hay al menos 5 de Daño sobre ella (al menos 8 en modo Experto), descarta este Accesorio.\n[star] Aumento: si se está activando a Bloody Mary, quedas confundido."},
  "60118": {"n":"Lluvia de cuchillas","t":"Cuando se muestre esta carta: si Mary Walker está en juego como Accesorio, dale la vuelta y muestra Ganarse su confianza. El Villano te ataca (incluso aunque tengas adoptada la identidad de tu Alter ego).\n[star] Aumento: si se está activando a Bloody Mary, sufres 2 de Daño."},
  "60119": {"n":"Parapeto improvisado","t":"Oleada.\nCuando se muestre esta carta: dale al Villano una carta de Estado \"Duro\".\n[star] Aumento: si se está activando a Bloody Mary, dale una carta de Estado \"Duro\".","f":"\"Si nos acorazamos todo lo posible... no podrán tocarnos.\" —Bloody Mary"},
  "60120": {"n":"Vigía de la Mano","t":"Guardia. Dureza.\n[star] Aumento: dale al enemigo activado un carta de aumento adicional.","f":"\"Cuidemos unos de otros. Es el único modo de sobrevivir en esta ciudad.\" —María Tifoidea"},
  "60121a": {"n":"Robo al Museo de Arte","t":"Contenido: el Villano Secuaz elegido (ver página 5 del reglamento). Conjuntos de Encuentros del Villano elegido, Robo al Museo de Arte y Normal. Dos conjuntos de Encuentros modulares (Policías y El Búho).\nPreparación: localiza los 4 Accesorios Arte y vincula 1 al azar al Villano. Devuelve los otros 3 al mazo de Encuentros y barájalo."},
  "60121b": {"n":"Robo al Museo de Arte","t":"[star] X es 1 más que el número de Accesorio Arte vinculados al Villano.\nRespuesta obligada: después de que un enemigo realice un ataque no defendido contra un Superhéroe, vincula al Villano 1 Accesorio Arte que esté vinculado a ese Superhéroe.\nSi se completa esta etapa, los jugadores pierden la partida."},
  "60122": {"n":"Objeto imposible","t":"Oleada.\nVincula esta carta al Villano.\nRespuesta obligada: después de que se vincule esta carta a un personaje, confunde a ese personaje.\nAcción de Héroe: gasta un recurso [mental] o agota tu Héroe → vincula esta carta a tu Héroe."},
  "60123": {"n":"Ánfora admirable","t":"Oleada.\nVincula esta carta al Villano.\nEl personaje vinculado gana Firmeza.\nAcción de Héroe: gasta un recurso [wild] o agota tu Héroe → vincula esta carta a tu Héroe."},
  "60124": {"n":"Réplica del escudo","t":"Oleada.\nVincula esta carta al Villano.\nRespuesta obligada: después de que se vincule esta carta a un personaje, dale a a ese personaje una carta de Estado \"Duro\".\nAcción de Héroe: gasta un recurso [physical] o agota tu Héroe → vincula esta carta a tu Héroe."},
  "60125": {"n":"Paisaje fascinante","t":"Oleada.\nVincula esta carta al Villano.\nRespuesta obligada: después de que se vincule esta carta a un personaje, aturde a ese personaje.\nAcción de Héroe: gasta un recurso recurso [energy] o agota tu Héroe → vincula esta carta a tu Héroe."},
  "60126": {"n":"Ladrón de obras de arte","t":"Cuando se muestre esta carta: busca un Accesorio Arte en el mazo y la pila de descartes de Encuentros y vincúlalo al Villano. Si no es posible, traslada un Accesorio Arte de un Superhéroe al Villano.\n[star] Aumento: traslada un Accesorio Arte de un Superhéroe al Villano."},
  "60127": {"n":"Disputa encarnizada","t":"Cuando se muestre esta carta: puedes gastar recursos [physical] [physical] [physical] para trasladar un Accesorio Arte del Villano a tu Superhéroe. De no ser así, traslada un Accesorio Arte de un Superhéroe al Villano y esta carta gana Oleada."},
  "60128a": {"n":"La huida","t":"Contenido: el Villano Secuaz elegido (ver página 5 del reglamento). Conjuntos de Encuentros del Villano elegido, La huida, y Normal. Dos conjuntos de Encuentros modulares (Policías y Conducción).\nPreparación: coloca 1 contador de Velocidad sobre esta carta (2 contadores en modo Experto). Vincula al Villano el Accesorio Por delante (129A)."},
  "60128b": {"n":"La huida","t":"Interrupción obligada: cuando termine la ronda, si hay Amenaza sobre esta carta, haz lo siguiente:\n1. Coloca 1 contador de Velocidad sobre esta carta.\n2. Si está en juego A un lado, dale la vuelta para convertirla en Por delante. De no ser así, coloca 1 contador de Velocidad adicional sobre esta carta.\nSi se completa esta etapa, los jugadores pierden la partida."},
  "60129a": {"n":"Por delante","t":"Permanente. Vincula esta carta al Villano.\nSi no hay Amenaza sobre el Plan principal, dale la vuelta a esta carta.\n[star] Los ataques del Villano vinculado ganan A distancia.\nInterrupción obligada: cuando se vaya a infligir cualquier cantidad de Daño al Villano, en vez de eso quita esa misma cantidad de Amenaza del Plan principal (ignorando los iconos de Crisis ([crisis]))."},
  "60129b": {"n":"A un lado","t":"Permanente.\nCuando se muestre esta carta: cada jugador sufre 1 de Daño indirecto. El Villano sufre 2[per_hero] de Daño.","f":"El tráfico en la ciudad de New York es brutal."},
  "60130": {"n":"Vehículo de escolta","t":"Guardia. Patrulla.\nSi el número de contadores de Velocidad que hay sobre el Plan principal es de al menos:\n• 3 – Este Esbirro gana Dureza.\n• 6 – Este Esbirro gana también Ataque veloz.\n• 9 – Este Esbirro gana también Oleada."},
  "60131": {"n":"Camión cisterna atravesado","t":"[star] Complicación 1[per_hero].\nNo se puede infligir Daño al Villano.","f":"\"¡Muérete de envidia, Johnny Blaze!\" —Eco"},
  "60132": {"n":"A toda pastilla","t":"Cuando se muestre esta carta: por cada contador de Velocidad que haya sobre el Plan principal, elige una opción:\n• gasta 1 recurso de cualquier tipo.\n• coloca 1 de Amenaza sobre el Plan principal.","f":"¡Ñiiiiiiii!"},
  "60133": {"n":"Peatones","t":"Cuando se muestre esta carta: por cada contador de Velocidad que haya sobre el Plan principal, elige una opción:\n• Agota un personaje que controles.\n• sufres 1 de Daño indirecto.","f":"\"¡Espero que os hayáis abrochado el cinturón!\" —Puño de Hierro"},
  "60134a": {"n":"Red de extorsión","t":"Contenido: el Villano Secuaz elegido (ver página 5 del reglamento). Conjuntos de Encuentros del Villano elegido, Red de extorsión, y Normal. Dos conjuntos de Encuentros modulares (Catástofres y Mafia chandalera).\nPreparación: cada jugador elige un único Plan principal del conjunto Red de extorsión (al azar en modo Experto), lo coloca en su zona de juego y le da la vuelta para poner boca arriba su cara 1B. Aparta todos los Planes principales que no se hayan usado, situándolos fuera del juego."},
  "60134b": {"n":"Pelea en el supermercado","t":"Respuesta obligada: después de que se ataque a un personaje situado en esta zona de juego, inflige 1 de Daño al atacante y coloca 1 de Amenaza sobre esta carta. (Límite de una vez por fase en el modo Normal.)\nSi se completa cualquier Plan principal o se elimina a cualquier jugador, los jugadores pierden la partida."},
  "60135a": {"n":"Red de extorsión","t":"Contenido: el Villano Secuaz elegido (ver página 5 del reglamento). Conjuntos de Encuentros del Villano elegido, Red de extorsión, y Normal. Dos conjuntos de Encuentros modulares (Catástofres y Mafia chandalera).\nPreparación: cada jugador elige un único Plan principal del conjunto Red de extorsión (al azar en modo Experto), lo coloca en su zona de juego y le da la vuelta para poner boca arriba su cara 1B. Aparta todos los Planes principales que no se hayan usado, situándolos fuera del juego."},
  "60135b": {"n":"Antigüedades frágiles","t":"Interrupción obligada: cuando se inflija Daño sobrante a un Aliado (en modo Experto, a un Aliado o Esbirro) en esta zona de juego, coloca esa misma cantidad de Amenaza sobre este Plan.\nSi se completa cualquier Plan principal o se elimina a cualquier jugador, los jugadores pierden la partida."},
  "60136a": {"n":"Red de extorsión","t":"Contenido: el Villano Secuaz elegido (ver página 5 del reglamento). Conjuntos de Encuentros del Villano elegido, Red de extorsión, y Normal. Dos conjuntos de Encuentros modulares (Catástofres y Mafia chandalera).\nPreparación: cada jugador elige un único Plan principal del conjunto Red de extorsión (al azar en modo Experto), lo coloca en su zona de juego y le da la vuelta para poner boca arriba su cara 1B. Aparta todos los Planes principales que no se hayan usado, situándolos fuera del juego."},
  "60136b": {"n":"Limpios como una patena","t":"Respuesta obligada: después de que entre en juego un personaje en esta zona de juego, inflígele 1 de Daño y coloca 1 de Amenaza sobre esta carta.\nSi se completa cualquier Plan principal o se elimina a cualquier jugador, los jugadores pierden la partida.","f":"\"No patalees tanto, que está programada para prendas delicadas.\" —Jessica Jones"},
  "60137a": {"n":"Red de extorsión","t":"Contenido: el Villano Secuaz elegido (ver página 5 del reglamento). Conjuntos de Encuentros del Villano elegido, Red de extorsión, y Normal. Dos conjuntos de Encuentros modulares (Catástofres y Mafia chandalera).\nPreparación: cada jugador elige un único Plan principal del conjunto Red de extorsión (al azar en modo Experto), lo coloca en su zona de juego y le da la vuelta para poner boca arriba su cara 1B. Aparta todos los Planes principales que no se hayan usado, situándolos fuera del juego."},
  "60137b": {"n":"Duelo en la casa de empeños","t":"El coste de la primera Mejora que se juegue en esta zona de juego en cada ronda se reduce en 1.\nRespuesta obligada: después de que entre en juego un Accesorio o Mejora en esta zona de juego, coloca 1 de Amenaza sobre esta carta.\nSi se completa cualquier Plan principal o se elimina a cualquier jugador, los jugadores pierden la partida."},
  "60138a": {"n":"Red de extorsión","t":"Contenido: el Villano Secuaz elegido (ver página 5 del reglamento). Conjuntos de Encuentros del Villano elegido, Red de extorsión, y Normal. Dos conjuntos de Encuentros modulares (Catástofres y Mafia chandalera).\nPreparación: cada jugador elige un único Plan principal del conjunto Red de extorsión (al azar en modo Experto), lo coloca en su zona de juego y le da la vuelta para poner boca arriba su cara 1B. Aparta todos los Planes principales que no se hayan usado, situándolos fuera del juego."},
  "60138b": {"n":"El secreto no está en la masa","t":"Respuesta obligada: después de que un personaje situado en esta zona de juego derrote a otro personaje o un Plan secundario (en cualquier zona de juego), cura 1 de Daño al personaje que lo ha derrotado y coloca 1 de Amenaza sobre esta carta.\nSi se completa cualquier Plan principal o se elimina a cualquier jugador, los jugadores pierden la partida."},
  "60139": {"n":"Propietario del local","t":"Cuando se muestre esta carta: pon en juego Propietario del local controlado por ti. Esta carta gana Oleada.\nInterrupción obligada: cuando este Aliado abandone el juego, coloca 4 de Amenaza sobre el Plan principal que esté en tu zona de juego."},
  "60140": {"n":"Hombre Toro","t":"[star] Respuesta obligada: después de que el Hombre Toro ataque, coloca tanta Amenaza sobre el Plan principal como el Daño sobrante que haya infligido este ataque.\n[star] Aumento: Si esta activación es un ataque, coloca tanta Amenaza sobre el Plan principal como el Daño sobrante que haya infligido este ataque."},
  "60141": {"n":"Cambiar de local","t":"Oleada.\nCuando se muestre esta carta: intercambia tu Plan principal por un Plan principal elegido al azar de entre los que están apartados. La Amenaza que había sobre el Plan anterior se coloca sobre el nuevo.\n[star] Aumento: resuelve la capacidad \"Cuando se muestre esta carta\" de esta carta."},
  "60142a": {"n":"Fuga de La Balsa","t":"Contenido: el Villano Secuaz elegido (ver página 5 del reglamento). Conjuntos de Encuentros del Villano elegido, Fuga de La Balsa, y Normal. Dos conjuntos de Encuentros modulares (El Búho y Lápida).\nPreparación: vincula la Llave maestra al Villano. Cada jugador descarta cartas del mazo de Encuentros uhasta que se descarte un Esbirro Prisionero y muestra ese Esbirro."},
  "60142b": {"n":"Fuga de La Balsa","t":"Todos los Esbirros ganan: \"Cuando se derrote esta carta: quita 1 de Amenaza del Plan principal (2 de Amenaza si este Esbirro tiene el rasgo Élite).\"\nSi se completa esta etapa, los jugadores pierden la partida.","f":"\"¡Sembrad el caos a vuestro paso!\" —Medianoche Próxima"},
  "60143": {"n":"Llave maestra","t":"Vincula esta carta al Villano.\nPermanente.\n[star] Respuesta obligada: después de que el Villano ejecute el Plan contra ti, quédate como cartas de Encuentro boca abajo todas las cartas de aumento de esta activación que sean Esbirros.","f":">Medidas de seguridad anuladas.\n>Puerta abierta."},
  "60144": {"n":"Hombre Absorbente","t":"Infame.\n[star] Interrupción obligada: cuando el Hombre Absorbente te ataca, mete debajo de su carta la primera carta de tu mazo. El Hombre Absorbente recibe +1 ATQ para este ataque por cada cada tipo de recurso distinto ([energy], [mental], [physical], y [wild]) que haya en las cartas que tiene metidas debajo."},
  "60145": {"n":"Barón Zemo","t":"Infame.\nTodo Aliado que tenga Amenaza encima se trata como si fuera un Esbirro Engañado con el texto de reglas en blanco. Su puntuación de PLA es igual a su puntuación básica de INT, y no sufre Daño derivado.\nCuando se muestre esta carta: coloca 1 de Amenaza sobre un Aliado que no tenga Amenaza encima. Ese Aliado se enfrenta al jugador que lo controla."},
  "60146": {"n":"Drang","t":"Infame.\n[star] Respuesta obligada: después de que Drang te ataque, colócale 1 contador de Andanada sobre him. Luego sufres 1 de Daño indirecto por cada contador de Andanada sobre Drang.","f":"\"¡Aritilleros de la nave, apuntad a mis coordenadas!\""},
  "60147": {"n":"Mysterio","t":"Infame.\n[star] Respuesta obligada: después de que Mysterio te ataque, quédate como cartas de Encuentro boca abajo todas las cartas de aumento de esa activación que sean Perfidias."},
  "60148": {"n":"Medianoche Próxima","t":"Infame.\n[star] Interrupción obligada: cuando Medianoche Próxima te ataque, elige entre colocar 1 de Amenaza sobre el Plan principal o bien que Medianoche Próxima reciba +2 ATQ para este ataque."},
  "60149": {"n":"Rino","t":"Dureza. Infame.\n[star] Los ataques del Rino ganan Brutalidad.\n[star] Aumento: dale al enemigo activado una carta de Estado \"Duro\"."},
  "60150": {"n":"Encerrado en una celda","t":"No puedes intervenir, atacar ni adoptar la identidad de tu Alter ego.\nAcción de Héroe: gasta recursos 3 recursos de cualquier tipo o bien agota personajes que controles y que sumen entre todos INT 3 o más → descarta esta carta.\n[star] Aumento: muestra esta carta."},
  "60151a": {"n":"¡Paren las rotativas!","t":"Contenido: el Villano Secuaz elegido (ver página 5 del reglamento). Conjuntos de Encuentros del Villano elegido, ¡Paren las rotativas! y Normal. Dos conjuntos de Encuentros modulares (Lápida y Mafia chandalera).\nPreparación: pon en juego la carta de Entorno del Daily Bugle. Cada jugador pone en juego (bajo su control) un Apoyo Daily Bugle aleatorio de este conjunto de Encuentros. Retira de la partida todos los Apoyos Daily Bugle que sobren."},
  "60151b": {"n":"¡Paren las rotativas!","t":"Respuesta obligada: después de que un enemigo realice un ataque no defendido contra ti, elige una opción:\n• coloca 2 de Amenaza sobre esta carta (3 de Amenaza en modo Experto).\n• Quita 1 contador de Aguante de un Apoyo Daily Bugle que controles.\nsi algún Apoyo Daily Bugle abandona el juego o se completa esta etapa, los jugadores pierden la partida."},
  "60152": {"n":"Daily Bugle","t":"Acción de Alter ego: agota un Apoyo Daily Bugle que controles → coloca 1 contador de Aguante sobre ese Apoyo. (Cualquier jugador puede hacer esto.)","f":"Con J. Jonah Jameson al frente, el Daily Bugle ha llegado a ser uno de los periódicos más leídos de los Estados Unidos."},
  "60153": {"n":"Ben Urich","t":"Usos (3 contadores de Aguante).\nAcción: agota a Ben Urich y quítale 1 contador de Aguante → mira las 2 primeras cartas del mazo de Encuentros. Puedes descartar 1 de esas cartas. (Devuelve el resto en el mismo orden.)"},
  "60154": {"n":"Betty Brant","t":"Usos (3 contadores de Aguante).\nInterrupción: cuando se ponga boca arriba una carta de aumento, agota a Betty Brant y quítale 1 contador de Aguante → anula los iconos de Aumento y la capacidad de \"Aumento\" de esa carta. Dale al enemigo activado otra carta de aumento para esta activación."},
  "60155": {"n":"J. Jonah Jameson","t":"Usos (3 contadores de Aguante).\nAcción: agota a J. Jonah Jameson, quítale 1 contador de Aguante y coge 1 carta de Encuentro boca abajo → roba 2 cartas."},
  "60156": {"n":"Robbie Robertson","t":"Usos (3 contadores de Aguante).\nRespuesta: después de que un jugador reciba una carta de Encuentro boca abajo, agota a Robbie Robertson y quítale 1 contador de Aguante → mira la carta de Encuentro. Puedes descartarla y darle a ese jugador otra carta de Encuentro boca abajo."},
  "60157": {"n":"Entrevista en exclusiva","t":"Los Apoyos Daily Bugle no pueden prepararse.\nCuando se muestre esta carta: agota todos los Apoyos Daily Bugle.","f":"\"Me encantaría que vuestro público oyese mi versión de la historia. A ver, ¿por dónde empiezo?\""},
  "60158": {"n":"Noticia de última hora","t":"Cuando se muestre esta carta: elige una opción:\n• Agota un Apoyo Daily Bugle (controlado por cualquier jugador) y quítale 1 contador de Aguante.\n• Coloca 2 de Amenaza sobre el Plan principal.\n[star] Aumento: agota un Apoyo Daily Bugle (controlado por cualquier jugador)."},
  "60159a": {"n":"Kingpin","t":"Firmeza.\nNo puede infligirse Daño ni vincularse Mejoras a Kingpin. (Los jugadores deben conseguir Apoyo ciudadano para enfrentarse a él directamente.)\n[star] Interrupción obligada: cuando Kingpin vaya a atacarte, en vez de eso ejecuta el Plan."},
  "60159b": {"n":"Kingpin","t":"Tesón.\n[star] Interrupción obligada: cuando Kingpin se active contra ti, si no estás enfrentado a ningún Esbirro, dale a Kingpin 1 carta de aumento adicional para esta activación."},
  "60160a": {"n":"Kingpin","t":"Firmeza.\nNo puede infligirse Daño ni vincularse Mejoras a Kingpin. (Los jugadores deben conseguir Apoyo ciudadano para enfrentarse a él directamente.)\n[star] Interrupción obligada: cuando Kingpin vaya a atacarte, en vez de eso ejecuta el Plan."},
  "60160b": {"n":"Kingpin","t":"Tesón.\n[star] Interrupción obligada: cuando Kingpin se active contra ti, si no estás enfrentado a ningún Esbirro, dale a Kingpin 1 carta de aumento adicional para esta activación y además esta activación gana Brutalidad si es un ataque."},
  "60161a": {"n":"Gambito de rey","t":"Contenido: Kingpin (A1). (Kingpin (B1) para jugar en modo Experto.) Conjunto de Encuentros de Kingpin. Dos conjuntos de Encuentros modulares (Lápida y Mafia chandalera).\nPreparación: cada jugador muestra el Esbirro Archienemigo que tiene apartado. Si el Esbirro Archienemigo de algún jugador se llama igual que un personaje que ya está en juego, en vez de eso retira su Esbirro Archienemigo de la partida, después localiza un Esbirro Secuaz que no esté en juego y lo muestra."},
  "60161b": {"n":"Gambito de rey","t":"Cuando se muestre esta carta: pon en juego Apoyo ciudadano, con la cara Bajo boca arriba.\nAcción de Héroe: quita 5 de Amenaza de esta carta (4 de Amenaza en modo Experto). Baraja el mazo de Encuentros junto con su pila de descartes, luego descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Esbirro, y muestra ese Esbirro.\nSi se completa esta etapa, los jugadores pierden la partida."},
  "60162a": {"n":"La jugada final","t":"Cuando se muestre esta carta: cada jugador localiza su Esbirro Archienemigo y lo muestra. Cada jugador cuyo Esbirro Archienemigo no haya entrado en juego de este modo localiza un Esbirro Secuaz que no esté en juego y lo muestra. En modo Experto, el jugador inicial localiza el Plan secundario Crimen organizado y lo muestra.","f":"\"Basta de juegos. Quiero a esos payasos fuera de circulación. ¡Permanentemente!\" —Kingpin"},
  "60162b": {"n":"La jugada final","t":"Todos los Esbirros ganan Guardia.\nSi se completa esta etapa, los jugadores pierden la partida.","f":"\"YVosotros y vuestras ínfulas heroicas ya habéis entorpecido bastante nuestros planes. ¡Juntos os destruiremos y controlaremos esta ciudad!\" —Kingpin"},
  "60163a": {"n":"Apoyo ciudadano","t":"Respuesta obligada: después de que un Esbirro sea derrotado, coloca 1 contador de Apoyo sobre esta carta.\nInterrupción obligada: cuando empiece la fase del Villano, si hay al menos 2[per_hero]+2 contadores de Apoyo sobre esta carta, dale la vuelta a Kingpin y avanza el Plan principal a la etapa 2A. Luego dale la vuelta a esta carta."},
  "60163b": {"n":"Apoyo ciudadano","t":"Interrupción: cuando un enemigo vaya a recibir una carta de aumento boca abajo, en vez de eso quita 1[per_hero] contadores de Apoyo de esta carta.\nRespuesta obligada: después de que un Esbirro sea derrotado, coloca 1 contador de Apoyo sobre esta carta.","f":"\"¡Qué bien que nos muestren un poco de gratitud para variar!.\" —Jessica Jones"},
  "60164": {"n":"Abrazo de oso","t":"si Kingpin tiene el rasgo Artista marcial, vincula esta carta a tu Héroe. De no ser así, esta carta gana Oleada.\nUsos (3 contadores de Agarre).\nNo puedes adoptar la identidad de tu Alter ego.\nInterrupción obligada: cuando vayas a intervenir o atacar, en vez de eso quita 1 contador de Agarre de esta carta."},
  "60165": {"n":"James Wesley","t":"Cuando se muestre esta carta: vincula esta carta a Kingpin y dale una carta de aumento boca abajo.\nAcción de Héroe: descarta un Evento intervención de tu mano → descarta a James Wesley. Kingpin ejecuta el Plan.\n[star] Aumento: vincula esta carta a Kingpin."},
  "60166": {"n":"Bastón de Kingpin","t":"Cuando se muestre esta carta: vincula esta carta a Kingpin. Quedas aturdido.\nRespuesta obligada: después de que Kingpin ataque e inflija Daño a un Héroe, aturde a ese Héroe. Si algún Héroe es aturdido de este modo, descarta esta carta.\n[star] Aumento: quedas aturdido. Si ya estabas aturdido, sufres 1 de Daño."},
  "60167": {"n":"Montaña de músculos","t":"Si Kingpin tiene el rasgo Artista marcial, vincula esta carta a Kingpin. De no ser así, esta carta gana Oleada.\nKingpin gana Represalia 1.\nInterrupción obligada: cuando Kingpin vaya a sufrir cualquier cantidad de Daño, en vez de eso coloca ese Daño sobre esta carta. Luego, si hay al menos 8 de Daño aquí, descarta esta carta."},
  "60168": {"n":"Vanessa Fisk","t":"Cuando se muestre esta carta: vincula esta carta a Kingpin. Quedas confundido.\nAcción de Héroe: descarta un Evento de Ataque de tu mano → descarta a Vanessa Fisk. Kingpin te ataca.\n[star] Aumento: quedas confundido. Si ya estabas confundido, coloca 1 de Amenaza sobre el Plan principal."},
  "60169": {"n":"Gata Negra","t":"Infame.\nMientras haya 4 de Amenaza sobre esta carta, la Gata Negra se trata como si fuera un Aliado que sufre 2 de Daño derivado después de que ataque o intervenga.\nAcción de Héroe: gasta un recurso [mental] → coloca 1 de Amenaza sobre esta carta. Si hay 4 de Amenaza sobre esta carta, tomas el control de la Gata Negra como Aliado."},
  "60170": {"n":"Iguana","t":"Infame.\n[star] Interrupción obligada: cuando Iguana te ataque, sufres 1 de Daño.\n[star] Aumento: sufres 1 de Daño."},
  "60171": {"n":"Mancha","t":"Entra en juego con 1 contador de Mancha.\nInterrupción obligada: cuando se vaya a infligir Daño a Mancha mediante un ataque, si hay al menos 1 contador de Mancha sobre esta carta, en vez de eso quítale 1 contador de Mancha e inflige ese Daño al atacante. De no ser posible, coloca 1 contador de Mancha sobre esta carta."},
  "60172": {"n":"Zancudo","t":"Entra en juego con 2 contadores de Zancos.\n[star] El Zancudo recibe +1 PLA y +1 ATQ por cada contador de Zancos que tenga.\nInterrupción obligada: cuando el Zancudo vaya a sufrir cualquier cantidad de Daño, en vez de eso quítale 1 contador de Zancos."},
  "60173": {"n":"La influencia de Kingpin","t":"Cuando se derrote esta carta: el jugador que haya derrotado este Plan coloca 3 de Amenaza sobre el Plan secundario de su Archienemigo. Si no está en juego, debe localizarlo y mostrarlo.","f":"Kingpin se sirve de una combinación de mentiras, sobornos y amenazas para hacer que otros cumplan su voluntad."},
  "60174": {"n":"Crimen organizado","t":"Todos los Esbirros recibe +2 de Vida.","f":"\"Somos más fuertes cuando colaboramos.\" —Kingpin"},
  "60175": {"n":"Repertorio de trucos","t":"Cuando se muestre esta carta: muestra una carta aleatoria del conjunto de Archienemigo que tienes apartado. Si no no se muestra ninguna carta de este modo, esta carta gana Oleada.\n[star] Aumento: dale a este personaje una carta aleatoria del conjunto de Archienemigo que tienes apartado como carta de aumento adicional."},
  "60176": {"n":"Odio visceral","t":"Cuando se muestre esta carta: tu Esbirro Archienemigo se activa contra ti. Si tu Esbirro Archienemigo no está en juego, localízalo y muéstralo. Si no puedes localízalo, localiza un Esbirro Secuaz que no esté en juego y muéstralo.\n[star] Aumento: si esta activación es un ataque, gana Brutalidad."},
  "60177": {"n":"Incursión mística","t":"Usos (2 contadores de Civiles).\nAcción de Héroe: gasta recursos [mental] [mental] o bien agota un Héroe o Aliado que controles → quita 1 contador de Civiles de esta carta (2 contadores si has agotado un personaje [[Místico])."},
  "60178": {"n":"Barco naufragado","t":"Usos (2 contadores de Civiles).\nAcción de Héroe: gasta recursos [energy] [energy] o bien agota un Héroe o Aliado que controles → quita 1 contador de Civiles de esta carta (2 contadores si has agotado un personaje [[Aéreo])."},
  "60179": {"n":"Edificio en llamas","t":"Usos (2 contadores de Civiles).\nAcción de Héroe: gasta recursos [physical] [physical] o bien agota un Héroe o Aliado que controles → quita 1 contador de Civiles de esta carta (2 si has agotado un personaje que tiene una carta de Estado \"Duro\")."},
  "60180": {"n":"Puente inestable","t":"[star] Complicación 2[per_hero].\nRespuesta obligada: después de que se quite cualquier cantidad de Amenaza del Puente inestable, coloca 1 de Amenaza sobre esta carta."},
  "60181": {"n":"Traseúntes en peligro","t":"Peligro.\nCuando se muestre esta carta: coloca 1 contador de Civiles sobre un Entorno Catástrofe. Si no se coloca ningún contador de este modo, busca un Entorno Catástrofe en el mazo y la pila de descartes de Encuentros y muéstralo.\n[star] Aumento: coloca 1 contador de Civiles sobre un Entorno Catástrofe."},
  "60182": {"n":"Agente de policía","t":"Ataque veloz. Vulnerable.\n[star] Interrupción obligada: cuando el Agente de policía vaya a ejecutar el Plan, en vez de eso ataca al Villano.\nCuando se derrote esta carta: coloca 2 de Amenaza sobre el Plan principal.","f":"\"¡Alto ahí!\""},
  "60183": {"n":"Policía corrupto","t":"Ataque veloz. Vulnerable.\nCuando se derrote esta carta: el jugador que la ha derrotado coge 1 carta de Encuentros boca abajo.\n[star] Aumento: sufres 2 de Daño indirecto."},
  "60184": {"n":"Buscado por la ley","t":"Acción de Héroe: descarta cartas del mazo de Encuentros hasta que se descarte un Esbirro Policía y ponlo en juego enfrentado a ti. Descarta esta carta."},
  "60185": {"n":"Cordón policial","t":"[star] Complicación 1[per_hero].\nTodos los Esbirro Policía ganan Guardia y Patrulla.\nCuando se muestre esta carta: busca un Esbirro Policía en el mazo y la pila de descartes de Encuentros y muéstralo.","f":"\"No se puede pasar. Esto es el escenario de un crimen.\" —Agente de policía"},
  "60186": {"n":"Deportivo","t":"Vincula esta carta al enemigo que tenga la puntuación más alta de ATQ y que no tenga ya vinculado un Accesorio Vehículo. De no ser posible, esta carta gana Oleada.\nInterrupción obligada: cuando el personaje vinculado vaya a sufrir cualquier cantidad de Daño, en vez de eso coloca ese Daño sobre esta carta. Si hay al menos 4 de Daño aquí, descarta esta carta."},
  "60187": {"n":"Motocicleta","t":"Vincula esta carta al enemigo que tenga la puntuación más alta de PLA y que no tenga ya vinculado un Accesorio Vehículo. De no ser posible, esta carta gana Oleada.\nInterrupción obligada: cuando el personaje vinculado vaya a sufrir cualquier cantidad de Daño, en vez de eso coloca ese Daño sobre esta carta. Si hay al menos 3 de Daño aquí, descarta esta carta."},
  "60188": {"n":"Furgoneta","t":"Vincula esta carta al enemigo que tenga menos Vida restante y que no tenga ya vinculado un Accesorio Vehículo. De no ser posible, esta carta gana Oleada.\nInterrupción obligada: cuando el personaje vinculado vaya a sufrir cualquier cantidad de Daño, en vez de eso coloca ese Daño sobre esta carta. Si hay al menos 6 de Daño aquí, descarta esta carta."},
  "60189": {"n":"Atasco de tráfico","t":"[star] Complicación 2[per_hero].\nInterrupción obligada: cuando un personaje que tenga vinculado un Accesorio Vehículo vaya a:\n• Añadir Amenaza a un Plan, en vez de eso la Amenaza se coloca sobre esta carta.\n• Quitar Amenaza from a scheme, en vez de eso Amenaza se quita de esta carta."},
  "60190": {"n":"Robo de vehículo","t":"Cuando se muestre esta carta: descarta cartas del mazo de Encuentros hasta que se descarte un Accesorio Vehículo y muéstralo. Si tu Superhéroe no tiene vinculado ningún Accesorio Vehículo, en vez de eso puedes gastar 3 recursos del mismo tipo para vincular ese Accesorio a tu Superhéroe."},
  "60191": {"n":"Suero de vuelo","t":"Vincula esta carta a un enemigo que no sea Aéreo. De no ser posible, esta carta gana Oleada.\nEl enemigo vinculado gana el rasgo Aéreo.\nAcción de Héroe: descarta un Evento de Ataque de tu mano → descarta esta carta.","f":"\"Ahora luchamos en mi territorio: ¡el cielo!\" —El Búho"},
  "60192": {"n":"Señor Pez","t":"[star] Los ataques del Señor Pez ganan A distancia y Penetrante.\nCuando se muestre esta carta: el Señor Pez se enfrenta al jugador cuyo Superhéroe menos Vida restante.","f":"\"¡Nadie se ríe del Señor Pez!\""},
  "60193": {"n":"El Búho","t":"Ataque veloz.\n[star] Los ataques de El Búho ganan Penetrante.\n[star] Aumento: si esta activación es un ataque, gana Penetrante."},
  "60194": {"n":"Descenso vertiginoso","t":"Cuando se muestre esta carta (Alter ego): el Villano y todos los Esbirros que estén enfrentados a ti ejecutan el Plan. Cada enemigo Aéreo recibe +2 PLA para su activación.\nCuando se muestre esta carta (Héroe): el Villano y todos los Esbirros que estén enfrentados a ti te atacan. Cada enemigo Aéreo recibe +2 ATQ para su activación."},
  "60195": {"n":"Frío como el hielo","t":"Vincula esta carta al Esbirro que tenga la mayor puntuación básica de Vida y dale una carta de Estado \"Duro\". De no ser posible, esta carta gana Oleada.\n[star] Respuesta obligada: después de que el Esbirro vinculado ejecute el Plan, confunde al Superhéroe del jugador inicial y descarta Frío como el hielo.","f":"\"Yo le haré hablar.\" —Lápida"},
  "60196": {"n":"Duro como el mármol","t":"Vincula esta carta al Esbirro que tenga la mayor puntuación básica de Vida y dale una carta de Estado \"Duro\". De no ser posible, esta carta gana Oleada.\n[star] Respuesta obligada: después de que el Esbirro vinculado ataque, aturde al personaje atacado y descarta Duro como el mármol."},
  "60197": {"n":"Escarabajo","t":"Infame.\nCuando se muestre esta carta: busca en el mazo de Encuentros y en su pila de descartes un Accesorio que pueda vincularse a un Esbirro y vincúlalo al Escarabajo."},
  "60198": {"n":"Lápida","t":"Ataque veloz.\n[star] Aumento: dale al Villano una carta de Estado \"Duro\".","f":"\"Esto es lo que a mí me gusta: ¡una buena pelea!\""},
  "60199": {"n":"Lista negra","t":"Respuesta obligada: después de que empiece la fase del Villano, inflige 3 de Daño indirecto al jugador inicial. Por cada Aliado que sea derrotado de este modo, quita 1[per_hero] de Amenaza de la Lista negra."},
  "60200": {"n":"Ivan Banionis","t":"Trabajo en equipo (Chandalero).\nCuando se muestre esta carta: coloca 1 ficha de Aceleración sobre esta carta.\n[star] Respuesta obligada: después de que Ivan Banionis ejecute el Plan, coloca 1 ficha de Aceleración sobre esta carta."},
  "60201": {"n":"El Payaso","t":"Trabajo en equipo (Chandalero). Infame.\n[star] Respuesta obligada: después de que El Payaso ejecute el Plan, dale 1 carta de aumento boca abajo.","f":"\"...\""},
  "60202": {"n":"Mafioso Chandalero","t":"Represalia 2. Trabajo en equipo (Chandalero). Vulnerable.\nCuando se derrote esta carta: mete esta carta debajo del Plan secundario Mafia chandalera. De no ser posible, aturde y confunde al personaje que haya derrotado al Mafioso Chandalero."},
  "60203": {"n":"Camorrista Chandalero","t":"Trabajo en equipo (Chandalero). Vulnerable.\nCuando se derrote esta carta: mete esta carta debajo del Plan secundario Mafia chandalera. De no ser posible, devuelve esta carta al mazo de Encuentros y barájalo.","f":"\"¡Tío!\""},
  "60204": {"n":"Mafia chandalera","t":"Cuando se muestre esta carta: descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Esbirro Chandalero y mete ese Esbirro debajo de esta carta.\nRespuesta obligada: después de que un jugador muestre un Esbirro Chandalero del mazo de Encuentros, ese jugador muestra 1 Esbirro que esté metido debajo de esta carta."},
  "60205a": {"n":"Robo al Museo de Arte","t":"Preparación: dale a cada Superhéroe una carta de Estado \"Duro\".","f":"Las obras de arte que lograsteis proteger os han inspirado."},
  "60205b": {"n":"Robo al Museo de Arte","t":"Preparación: cada jugador decide entre aturdir o confundir a su Superhéroe (en modo Experto, las dos cosas).","f":"Vuestro fracaso a la hora de impedir el robo al museo os ha desmoralizado."},
  "60206a": {"n":"La huida","t":"Preparación: después de renovar las manos, cada jugador puede buscar una Mejora en su mazo y su pila de descartes y añadirla a su mano. En modo Experto, cada jugador que haga esto descarta 1 carta de su mano.","f":"El banco os ofrece una generosa recompensa como agradecimiento por devolverles el dinero robado."},
  "60206b": {"n":"La huida","t":"En modo Experto, no pueden descartarse Accesorios del juego durante la primera ronda.\nPreparación: cada jugador busca un Accesorio en el mazo de Encuentros y lo muestra. Dale una carta de Encuentro boca abajo a cada jugador que no haya podido hacerlo.","f":"Vuestros enemigos han invertido sus ganancias ilícitas en una mejora de armamento."},
  "60207a": {"n":"Red de extorsión","t":"Preparación: después de renovar las manos, cada jugador puede buscar un Apoyo en su mazo y su pila de descartes y añadirlo a su mano. En modo Experto, cada jugador que haga esto descarta 1 carta de su mano.","f":"Habéis protegido los negocios locales, infundiendo así a los vecinos el valor necesario para colaborar con vosotros."},
  "60207b": {"n":"Red de extorsión","t":"Preparación: cada jugador elige 1 carta de su mano y la descarta (2 cartas en modo Experto).","f":"Los vecinos están demasiado asustados por las amenazas a los negocios para ayudaros."},
  "60208a": {"n":"Fuga de La Balsa","t":"Preparación: después de renovar las manos, cada jugador puede buscar un Aliado en su mazo y su pila de descartes y añadirlo a su mano. En modo Experto, cada jugador que haga esto descarta 1 carta de su mano.","f":"Vuestra labor restaurando el orden en La Balsa ha desocupado a otros héroes que ahora podrán ayudaros a detener al proximo villano."},
  "60208b": {"n":"Fuga de La Balsa","t":"Preparación: baraja todos los Esbirros del conjunto de Encuentros de Fuga de La Balsa junto con el resto del mazo de Encuentros (en modo Experto, dale 1 de esos Esbirros al azar a cada jugador como carta de Encuentro boca abajo antes de barajar las demás).","f":"Muchos fugitivos peligrosos andan sueltos debido a vuestro fracaso en La Balsa."},
  "60209a": {"n":"¡Paren las rotativas!","t":"Preparación: cada jugador pone en juego 1 Apoyo Daily Bugle del conjunto de Encuentros ¡Paren las rotativas! (siempre que no haya sido eliminado de la campaña).","f":"Muy agradecido por haber salvado su periódico, J. Jonah Jameson ha prometido que la plantilla del Daily Bugle os ayudará en lo que pueda. Seguro que dura poco la gratitud."},
  "60209b": {"n":"¡Paren las rotativas!","t":"Preparación: dale a cada jugador 1 carta de Encuentro boca abajo (2 cartas de Encuentro en modo Experto).","f":"A raíz del atentado contra la editorial del Daily Bugle, los medios de comunicación locales están demasiado asustados para ayudaros contra la ola de delincuencia;incluso sospecháis que algunos podrían estar colaborando con los criminales."},
  "60210a": {"n":"María Tifoidea","t":"Inicio. Victoria -1.\n[star] Respuesta obligada: después de que muestres un Esbirro, quita todo el Daño que haya sobre esta carta y dale la vuelta."},
  "60210b": {"n":"Bloody Mary","t":"Victoria -1.\n[star] Respuesta obligada: después de que muestres un Plan secundario, quita todo el Daño que haya sobre esta carta y dale la vuelta."},
  "61001a": {"t":"[star] Reunir pruebas — Respuesta: después de que uses un atributo básico, coloca 1 contador de Pruebas sobre Investigaciones Alias.","f":"\"Estas cosas rara vez terminan bien.\""},
  "61001b": {"t":"De incógnito — Acción: cambia a tu identidad de Héroe. No puedes adoptar la identidad de tu Alter ego en esta fase.\nPreparación: pon en juego el Apoyo Investigaciones Alias."},
  "61002": {"n":"Investigaciones Alias","t":"Permanente.\nRespuesta: después de que se derrote un Plan secundario, agota esta carta → coloca 2 contadores de Prueba sobre esta carta. Luego puedes quitar tantos contadores de Prueba de esta carta como la Vida restante del Villano para derrotar la etapa actual del Villano."},
  "61003": {"t":"Dureza.\nAcción: agota a Luke Cage e inflígele 1 de Daño → dale una carta de Estado \"Duro\".","f":"\"Puede que su piel sea como el acero, pero por dentro tiene un corazón de oro.\" —Jessica Jones"},
  "61004": {"n":"\"La has cagado\"","t":"Acción de Héroe (ataque): inflige 3 de Daño a un enemigo. Puedes quitar 1 contador de Pruebas de Investigaciones Alias para infligir 2 de daño adicional y para que este ataque gane Brutalidad o Penetrante.","f":"\"Te has metido con la tía equivocada.\" —Jessica Jones"},
  "61005": {"n":"Abrirse paso","t":"Respuesta: después de que se coloque un contador de Pruebas sobre Investigaciones Alias, prepara tu Superhéroe. Añade esta carta a tu mazo y barájalo.","f":"\"Cuéntame más.\" —Jessica Jones"},
  "61006": {"n":"Husmear","t":"Acción de Alter ego (intervención): quita 4 de Amenaza de un Plan y coloca 2 contadores de Prueba sobre Investigaciones Alias. Descarta la primera carta del mazo de Encuentros. Si esta carta es un Esbirro o Plan secundario, muéstrala."},
  "61007": {"n":"Unir las piezas","t":"Este Plan no cuenta de cara al límite de Planes secundarios de jugador.\nCuando se derrote esta carta: el jugador que la ha derrotado roba 3 cartas.","f":"A veces sólo hay que retroceder y ponerlo todo en perspectiva para que las piezas encajen."},
  "61008": {"n":"Favores pendientes","t":"Acción de Alter ego: quita 2 contadores de Prueba de Investigaciones Alias y agota Favores pendientes → busca un Aliado en tu mazo y juégalo como si estuviera en tu mano, reduciendo en 2 su coste en recursos. (Baraja el mazo.)"},
  "61009": {"n":"Videocámara digital 4K","t":"Acción de Alter ego: agota esta carta y elige un Esbirro que no sea de Élite. Quita X contadores de Prueba de Investigaciones Alias, siendo X igual a 2 menos que la Vida restante de ese Esbirro → descarta ese Esbirro.","f":"\"Te pillé\" —Jessica Jones"},
  "61010": {"n":"Pruebas circunstanciales","t":"Respuesta: después de que se derrote a un enemigo, agota Pruebas circunstanciales → coloca 1 contador de Pruebas sobre Investigaciones Alias.","f":"\"¡Buen descubrimiento! Eso resultará muy útil.\" —Daredevil"},
  "61011": {"n":"Chaqueta de cuero","t":"Jessica Jones recibe +2 DEF.\nRespuesta: después de que defiendas, coloca 1 contador de Pruebas sobre Investigaciones Alias.","f":"\"Luke, ¿tiene alguna chaqueta que no sea de cuero negro?\" —Puño de Hierro"},
  "61012": {"n":"\"¡Ya me tienes harta!\"","t":"Respuesta obligada (ataque): después de que el Villano se active contra un jugador, si tienes adoptada la identidad de tu Alter ego, cambia a tu identidad de Héroe. Inflige 5 de Daño al Villano y a cada Esbirro que esté enfrentado a ese jugador. Descarta esta carta.","f":"\"¿Qué le acabas de decir?\" —Jessica Jones"},
  "61013": {"n":"Aversión a volar","t":"Interrupción de Héroe (defensa): cuando vayas a sufrir por lo menos 3 de Daño de un ataque, descarta esta carta → evita todo el Daño de ese ataque. Sufres 1 de Daño.","f":"\"Creo que voy a vomitar.\" —Jessica Jones"},
  "61014": {"n":"Vigilar a los sospechosos","t":"Acción: si esta carta está en tu zona de juego, vincúlala a un Plan secundario del mazo de Encuentros que no sea Permanente.\nInterrupción: cuando un personaje intervenga en el Plan vinculado, esa intervención quita 2 de Amenaza adicionales. Si el Plan es derrotado por esa intervención, coloca 2 contadores de Prueba sobre Investigaciones Alias."},
  "61015": {"n":"Capitana Marvel","t":"Respuesta: después de que la Capitana Marvel entre en juego, descarta las 4 primeras cartas de tu mazo. Si descartas un recurso [energy] impreso, quita 2 de Amenaza de un Plan. Si descartas más de un recurso [energy] impreso, también confundes a un enemigo."},
  "61016": {"n":"Spiderwoman","t":"Respuesta: después de que intervenga un personaje que controlas, coloca 1 contador de Extremidad sobre esta carta (hasta un máximo de 8). Puedes descartar a Spiderwoman para infligir 1 de Daño a un enemigo por cada contador de Extremidad que haya sobre esta carta."},
  "61017": {"n":"Chica Ardilla","t":"Respuesta: después de que juegues a la Chica Ardilla desde tu mano, coloca 1 contador de Ardilla sobre esta carta por cada carta que tengas en la mano (hasta un máximo de 4).\nAcción: quita 1 contador de Ardilla de esta carta → quita 1 de Amenaza de un Plan."},
  "61018": {"n":"Imponer la ley","t":"Respuesta de Héroe (intervención): después de que cambies de identidad, quita 3 de Amenaza de un Plan (4 de Amenaza si has pagado el coste de esta carta usando un recurso [mental]).","f":"\"¡Que esto te sirva de lección!\" - Capitán América"},
  "61019": {"n":"Reunión estratégica","t":"Acción de Alter ego: un jugador de tu elección busca un Plan secundario de jugador en su mazo y lo añade a su mano.\nAcción de Héroe (intervención): quita 3 de Amenaza de un Plan secundario de jugador.","f":"\"Tengo un plan, colegas.\" —Nova"},
  "61020": {"n":"Hasta debajo de las piedras","t":"Victoria 0.\nCuando se derrote esta carta: resuelve lo siguiente:\n• La próxima fase de Villano se omite.\n• Reparte a cada jugador 1 carta de Encuentro boca abajo (inmediatamente).\n• El Villano no puede sufrir Daño hasta el comienzo de la próxima fase del Villano (que no se omita)."},
  "61021": {"n":"Tender una trampa","t":"Victoria 0.\nCuando se derrote esta carta: el jugador que haya derrotado este Plan inflige 5[per_hero] de Daño al Villano.","f":"\"Tu le das por abajo y yo por arriba.\"\n\"Siempre me toca a mí por abajo.\"\n\"Vale, pues tú por arriba.\"\n\"Es que me gusta dar por abajo.\"\n— Lobezno y Masacre"},
  "61022": {"n":"Determinación","t":"Máximo de 1 por mazo.\nRespuesta de Héroe: después de que gastes esta carta, quita 1 de Amenaza del Plan principal."},
  "61023": {"n":"Lanzador de Rezón","t":"Restringida.\nAcción de Héroe: descarta esta carta → realiza una intervención básica sin agotarte (incluso aunque ya estés agotado). Para esta intervención, tu Héroe recibe +1 INT e ignora la palabra clave Patrulla y todos los iconos de Crisis ([crisis]) que haya en juego."},
  "61024": {"n":"In fraganti","t":"Máximo de 1 por jugador.\nRespuesta de Alter ego (ataque): después de que el Villano ejecute el Plan, cambia a tu identidad de Héroe y descarta esta carta → inflige tanto Daño al Villano como la cantidad de Amenaza colocada por esta activación."},
  "61025": {"n":"Gata Infernal","t":"Si tu Superhéroe tiene el rasgo Defensor, esta carta gains: \"Acción: pon en juego a Gata Infernal desde tu mano. Al final de la fase, descártala.\"","f":"\"¡Hola a todos! Bueno, ahí os quedáis.\""},
  "61026": {"n":"Lo bueno de la vida","t":"Alianza.\nAcción: elige una opción:\n• Agota un Alter ego Civil → prepara un Héroe o Aliado.\n• Agota a Héroe or Aliado → prepara un Alter ego Civil."},
  "61027": {"n":"Vínculo inquebrantable","t":"Equipo (Jessica Jones y Luke Cage). Máximo de 1 por mazo.\nAcción de Héroe: (intervención): quita 3 de Amenaza de un Plan. Cura 3 de Daño en total a Jessica Jones y Luke Cage."},
  "61028": {"n":"Segunda oportunidad","t":"Victoria 0.\nCuando se derrote esta carta: cada jugador puede devolver a su mazo todas las cartas específicas de Superhéroe que tenga en su pila de descartes.","f":"\"Hagamos lo que mejor se nos da a los héroes:¡evitar una catástrofe!\" —Ms. Marvel"},
  "61029": {"n":"Defender nuestra ciudad","t":"[star] Complicación 1[per_hero].\nRequiere (Defensor). Victoria 0.\nCuando se derrote esta carta: cada jugador puede buscar una carta con Equipo en su mazo y su pila de descartes y añadirla a su mano. Hasta el final de la fase, el coste para jugar todas las cartas que tengan Equipo se reduce en 1."},
  "61030": {"n":"Conciliación familiar","t":"Dale esta carta al jugador que lleva a Jessica Jones.\nComo coste adicional para cambiar de identidad, descarta 1 carta de tu mano.\nAcción de Alter ego: elige una opción:\n• Retira de la partida un Aliado que controles → retira esta carta de la partida.\n• Confunde a tu Superhéroe → descarta esta carta."},
  "61031": {"n":"Hombre Púrpura","t":"[star] La puntuación de PLA del Hombre Púrpura es igual a la puntuación más alta de PLA o INT de entre todos los personajes que están en juego. Su puntuación de ATQ es igual a la puntuación más alta de ATQ de entre todos los personajes que están en juego.","f":"Las feromonas químicamente modificadas de Zebediah Killgrave afectan a todas las personas que están cerca."},
  "61032": {"n":"Voluntad indómita","t":"[star] Complicación 3[per_hero].\nCuando se muestre esta carta: coloca 2 contadores de Feromonas sobre cada carta de Obligación de Sugestión que haya en juego.\nRespuesta obligada: después de que entre una carta de Obligación de Sugestión, coloca 2 contadores de Feromonas (adicionales) sobre ella0."},
  "61033a": {"n":"Sugestión ([energy])","t":"Usos (3 contadores de Feromonas).\nAcción obligada: agota esta carta y quítale 1 contador de Feromonas → elige entre jugar una carta que tenga un icono de recurso [energy] impreso (pagando sus costes) o bien añadir 2 de Amenanza al Plan principal.","f":"\"Hazme un favor...\" —Hombre Púrpura"},
  "61033b": {"n":"Sugestión ([mental])","t":"Usos (3 contadores de Feromonas).\nAcción obligada: agota esta carta y quítale 1 contador de Feromonas → elige entre jugar una carta que tenga un icono de recurso [mental] impreso (pagando sus costes) o bien añadir 2 de Amenanza al Plan principal.","f":"\"Todavía no te he dicho que lo hagas.\" —Hombre Púrpura"},
  "61033c": {"n":"Sugestión ([physical])","t":"Usos (3 contadores de Feromonas).\nAcción obligada: agota esta carta y quítale 1 contador de Feromonas → elige entre jugar una carta que tenga un icono de recurso [physical] impreso (pagando sus costes) o bien añadir 2 de Amenanza al Plan principal.","f":"\"Ah-ah-ah.\" —Hombre Púrpura"},
  "61034": {"n":"Agresividad innata","t":"Mano inicial. (Puedes añadir esta carta a tu mano antes de robar tu mano inicial.)\nTu Héroe recibe +1 ATQ.","f":"¡PAF!"},
  "61035": {"n":"Apretar las tuercas","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nRespuesta: después de que ataques y derrotes a un Esbirro sin pasarte, agota esta carta → quita tanta Amenaza de un Plan como la puntuación básica de PLA de ese Esbirro.","f":"\"No soy tu colega.\" —Jessica Jones"},
  "61036": {"n":"Percepción innata","t":"Mano inicial. (Puedes añadir esta carta a tu mano antes de robar tu mano inicial.)\nTu Héroe recibe +1 INT.","f":"¡FIUUUU!"},
  "61037": {"n":"Inspiración innata","t":"Mano inicial. (Puedes añadir esta carta a tu mano antes de robar tu mano inicial.)\nCada Aliado que controles recibe +1 de Vida."},
  "61038": {"n":"Eco","t":"La cantidad de Daño que sufre Eco de cada ataque enemigo se reduce tantos puntos como la DEF de tu Héroe."},
  "61039": {"n":"Pasar inadvertidos","t":"Victoria 0.\nCuando se derrote esta carta: cada jugador puede adoptar la identidad de su Alter ego. Cada Alter ego se cura tanto Daño como su REC.","f":"\"I'm sure the nice old Estonian couple that owns this place won't mind if we crash sobre esta carta for a bit.\" —Jessica Jones"},
  "61040": {"n":"Amenaza mitigada","t":"Vincula esta carta a una carta. La carta vinculada pierde todos sus iconos [acceleration], [amplify], [crisis] y [hazard].\nRespuesta obligada: al final de la ronda cada jugador puede gastar 1 recurso de cualquier tipo. Si algún jugador no lo hace, descarta esta carta."},
  "62001a": {"t":"Piel impenetrable — Luke Cage puede tener cualquier número de cartas de Estado \"Duro\". Los ataques contra Luke Cage pierden Penetrante.\nRespuesta obligada: después de que se descarte una carta de Estado \"Duro\" de Luke Cage, éste sufre 1 de Daño inevitable (ignorando \"Duro\")."},
  "62001b": {"t":"Piel impenetrable — Luke Cage puede tener cualquier número de cartas de Estado \"Duro\". Los ataques contra Luke Cage pierden Penetrante.\nAcción: busca la Mejora Proceso Burstein y añádela a tu mano. (Límite de una vez por fase.)"},
  "62002": {"t":"[star] Jessica Jones recibe +1 INT por cada carta de Estado \"Duro\" que tenga tu Superhéroe (hasta un máximo de +4 INT).","f":"\"Estoy aquí, y no pienso irme a ninguna parte.\""},
  "62003": {"n":"Héroe de Harlem","t":"Acción de Héroe: dale a Luke Cage una carta de Estado \"Duro\". Por cada carta de Estado \"Duro\" que tenga Luke Cage, elige un personaje que controles y prepáralo.","f":"\"No estoy solo. Tengo una familia que me apoya.\" —Luke Cage"},
  "62004": {"n":"Jarabe de Palo","t":"Acción de Héroe (ataque): inflige 3 de Daño a un enemigo. Puedes descartar una carta de Estado \"Duro\" de Luke Cage para devolver este Evento a tu mano."},
  "62005": {"n":"\"¡Contad conmigo!\"","t":"Acción de Héroe (intervención): dale a Luke Cage una carta de Estado \"Duro\". Quita 1 de Amenaza de un Plan por cada carta de Estado \"Duro\" que tenga Luke Cage (hasta un máximo de 5).","f":"\"Ésta es la mejor ciudad del mundo. No permitiré que caiga en el caos.\" —Luke Cage"},
  "62006": {"n":"\"¡Dulce Navidad!\"","t":"[star] El coste para jugar esta carta se reduce en 1 por cada carta de Estado \"Duro\" que tenga Luke Cage.\nAcción de Héroe (ataque): inflige 5 de Daño al Villano y a cada Esbirro que esté enfrentado a ti."},
  "62007": {"n":"Gimnasio Fogwell","t":"Respuesta: después de que se descarte una carta de Estado \"Duro\" de un personaje Defensor, agota el Gimnasio Fogwell → prepara ese personaje.","f":"\"He reventado un montón de sacos de boxeo en este local y nunca me han echado por eso.\" —Luke Cage"},
  "62008": {"n":"Proceso Burstein","t":"Acción de Alter ego: agota el Proceso Burstein → dale a Luke Cage una carta de Estado \"Duro\" (2 cartas de Estado \"Duro\" si no tiene ninguna).","f":"\"Tengo la piel de acero, y los músculos a juego.\" —Luke Cage"},
  "62009": {"n":"Se rifan tortas","t":"Vincula esta carta a un Esbirro. Máximo de 1 por Esbirro.\nLos ataques contra el Esbirro vinculado infligen 2 de Daño adicional y ganan Brutalidad.\nRespuesta: después de que juegues esta carta, enfréntate al Esbirro vinculado."},
  "62010": {"n":"Muñequera de metal","t":"Luke Cage gana Represalia 1.\nInterrupción de Héroe: cuando se vaya a infligir cualquier cantidad de Daño a Luke Cage, agota la Muñequera de metal → reduce ese Daño en 1."},
  "62011": {"t":"Respuesta de Héroe: después de que se descarte una carta de Estado \"Duro\" de Luke Cage, agota a Power Man → roba una carta.","f":"\"¡Temblad ante el poder de Powe Man! No, eso ha sonado raro. Temblad ante Luke Cage.\" —Luke Cage"},
  "62012": {"n":"Puño de Hierro","t":"Interrupción: cuando Puño de Hierro defienda contra un ataque enemigo, evita tanto Daño de ese ataue como la puntuación de ATQ de Puño de Hierro.","f":"\"He olvidado más técnicas de combate de las que tú llegarás a conocer en tu vida.\" —Puño de Hierro"},
  "62013": {"t":"Dureza.\n[star] Misty Knight recibe +2 ATQ y +2 INT mientras tenga una carta de Estado \"Duro\".","f":"\"Vamos, héroes. Tenemos que ayudar a salvar esta ciudad.\""},
  "62014": {"n":"Valquiria","t":"Dureza.\nInterrupción: cuando otro Aliado vaya a ser derrotado, descarta a Valquiria (del juego) → en vez de derrotar al Aliado, cúrale hasta que tenga 1 de Vida restante."},
  "62015": {"n":"Oponer resistencia","t":"Respuesta de Héroe: después de que tu Héroe defienda, todos los Aliados que controles reciben +1 INT y +1 ATQ hasta el final de la fase de Jugadores.","f":"\"Hace falta mucho más que eso para tumbarme.\" —Luke Cage"},
  "62016": {"n":"Innovación","t":"Máximo de 1 por mazo.\nRespuesta de Héroe: después de que gastes esta carta, cura 1 de Daño a un Aliado que controles."},
  "62017": {"n":"El poder del liderazgo","t":"Máximo de 2 por mazo.\nEl número de recursos generados por esta carta se duplica al pagar el coste de una carta de Liderazgo (azul)."},
  "62018": {"n":"Formación defensiva","t":"Usos (3 contadores de Bloqueo).\nAcción: agota esta carta y quítale 1 contador de Bloqueo → dale una carta de Estado \"Duro\" a un Aliado Defensor."},
  "62019": {"n":"Noble propósito","t":"Juega esta carta poniéndola bajo el control de cualquier jugador. Máximo de 1 por jugador.\nCada personaje que controles que tenga exactamente 1 de Vida restante recibe +2 INT y +2 ATQ.","f":"\"Basta de correr.\" —Daredevil"},
  "62020": {"t":"Hulk recibe +1 ATQ por cada contador de Ira que haya sobre esta carta.\nRespuesta: después de que el Villano te ataque, coloca 1 contador de Ira sobre esta carta."},
  "62021": {"n":"Hulka","t":"Dureza.\nRespuesta: después de que Hulka entre en juego, dale a tu Superhéroe una carta de Estado \"Duro\".","f":"\"Has interrumpido mi entrenamiento.\""},
  "62022": {"n":"Dúo Dinámico","t":"Acción: busca en tu mazo y tu pila de descartes una carta que tenga Equipo y un Aliado cuyo nombre se mencione en la palabra clave Equipo de esa carta. Añade esas cartas a tu mano. (Baraja el mazo.)"},
  "62023": {"n":"Power Man y Puño de Hierro","t":"Equipo (Puño de Hierro y Luke Cage). Máximo de 1 por mazo.\nAcción de Héroe (ataque): inflige 2 de Daño a un enemigo y dale una carta de Estado \"Duro\" a un personaje."},
  "62024": {"n":"Vínculo inquebrantable","t":"Equipo (Jessica Jones y Luke Cage). Máximo de 1 por mazo.\nAcción de Héroe: (intervención): quita 3 de Amenaza de un Plan. Cura 3 de Daño en total a Jessica Jones y Luke Cage."},
  "62025": {"n":"Energía","t":"Máximo de 1 por mazo."},
  "62026": {"n":"Genio","t":"Máximo de 1 por mazo."},
  "62027": {"n":"Fuerza","t":"Máximo de 1 por mazo."},
  "62028": {"n":"Heridas internas","t":"Dale esta carta al jugador que lleva a Luke Cage.\nRespuesta obligada: después de que termine la fase de los Jugadores, sufre 3 de Daño inevitable (ignorando las cartas de Estado \"Duro\").\nRespuesta de Alter ego: después de que te recuperes, retira Heridas internas de la partida."},
  "62029": {"n":"Boa","t":"[star] Respuesta obligada: después de que Boa ataque, atacará al mismo personaje 2 veces. (Límite de una vez por fase.)\n(Esbirro Archienemigo de Luke Cage.)\n[star] Aumento: dale esta carta al jugador que lleva a Luke Cage como carta de Encuentro boca abajo."},
  "62030": {"n":"Susurros ponzoñosos","t":"No se puede atacar a nigún Esbirro Sociedad Serpiente.\nCuando se derrote esta carta: el jugador que la haya derrotado descarta cartas de la parte superior del mazo de Encuentros hasta que se descarte un Esbirro Sociedad Serpiente y muestra ese Esbirro.\n[star] Aumento: quedas confundido."},
  "62031": {"n":"Mandíbula Biónica","t":"Vincula esta carta a Boa. De no ser posible, vincula esta carta al Villano.\n[star] Interrupción obligada: cuando el enemigo vinculado ataque a un personaje, descarta todas las cartas de Estado \"Duro\" que tenga ese personaje.\nAcción de Héroe: gasta recursos [mental] [mental] → descarta esta carta."},
  "62032": {"n":"Áspid","t":"[star] Respuesta obligada: después de que Áspid ejecute el Plan contra ti, quedas aturdido.\n[star] Aumento: quedas aturdido.","f":"\"¡Te mereces una dosis de veneno!\""},
  "62033": {"n":"Crótalo","t":"Ataque veloz.\nInterrupción obligada: cuando se ataque a Crótalo, descarta la primera carta del mazo de Encuentros. Si la carta descartada tiene una capacidad de \"Aumento\", el jugador atacante se queda a Crótalo como carta de Encuentro boca abajo."},
  "62034": {"n":"Ventaja de tamaño","t":"Acción de Héroe (ataque): inflige 3 de Daño a un enemigo (6 de Daño si tienes el rasgo Gigante o más vida restante que ese enemigo).","f":"\"¡Enano canijo!\" —Hulk"},
  "62035": {"n":"Observar","t":"Acción de Héroe: el Villano ejecuta el Plan. Dale a tu Héroe una carta de Estado \"Duro\".","f":"\"Existen otras maneras de ver.\" —Daredevil"},
  "62036": {"n":"Endurecido","t":"Respuesta: después de que te recuperes, si tu Vida restante es igual o mayor que tu Vida básica, agota Endurecido → dale a tu Superhéroe una carta de Estado \"Duro\"."},
  "62037": {"n":"Cinturón negro","t":"Juega esta carta sólo si algún jugador controla una carta Artista marcial.\nVincula esta carta a un personaje amigo. Máximo de 1 por personaje.\nEl personaje vinculado recibe +1 de Vida y gana el rasgo Artista marcial."},
  "90001": {"n":"Ronan el Acusador","t":"Dureza.\nRonan el Acusador no puede quedar aturdido.\nInterrupción obligada: cuanco empiece la fase del Villano, Ronan el Acusador se enfrenta al Héroe que tenga menos Vida restante.\n[star] Aumento: pon en juego a Ronan el Acusador enfrentado a ti."},
  "90002": {"n":"Juez, jurado y verdugo","t":"Respuesta obligada: después de que un personaje amigo sea derrotado a consecuencia de un ataque enemigo, coloca 2 de Amenaza sobre el Plan principal.\n[star] Aumento: pon en juego Juez, jurado y verdugo."},
  "90003": {"n":"El acusado","t":"Vincula esta carta a tu Superhéroe.\nInterrupción obligada: cuando un enemigo inicie un ataque contra el Superhéroe vinculado, ese enemigo recibe +1 ATQ para ese ataque.\nRespuesta obligada: después de que Ronan el Acusar sea derrotado, descarta esta carta.\n[star] Aumento: vincula esta carta a tu Superhéroe."},
  "90004": {"n":"Dictar sentencia","t":"Cuando se muestre esta carta: Ronan el Acusador se activa contra el jugador al que esté enfrentado. Si Ronan el Acusador no está en juego, esta carta gana Oleada.\n[star] Aumento: si algún personaje es derrotado a consecuencia de esta activación, el jugador inicial coge 1 carta de Encuentro boca abajo."},
  "90005": {"n":"¿Te atreves a oponerte a mí?","t":"Cuando se muestre esta carta: descarta las 5 primeras cartas del mazo de Encuentros. Cada vez que se descarte de este modo una carta que pertenezca al conjunto \"Fanático Kree\", quédatela como carta de Encuentro boca abajo.\n[star] Aumento: si esta activación es un ataque, este ataque gana Brutalidad."},
};
